window.QBANK={"19":[{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-1","t":"타인의 사망을 보험사고로 하는 보험계약에는 보험계약 체결 시에 그 타인의 서면에 의한 동의를 얻어야 한다.","ox":"O","m":"①","c":"A","tp":"상법상 생명보험계약"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-2","t":"타인의 생명보험계약 성립 당시 피보험자의 서면동의가 없다면 보험계약은 확정적으로 무효가 되나, 피보험자가 이미 무효로 된 보험계약을 추인하였다면 그 보험계약은 유효하다.","ox":"X","m":"②","c":"A","tp":"상법상 생명보험계약"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-3","t":"15세미만자, 심신상실자 또는 심신박약자의 사망을 보험사고로 한 보험계약은 무효로 한다. 다만 심신박약자가 보험계약을 체결하거나 단체보험의 피보험자가 될 때에 의사능력이 있는 경우에는 그러하지 아니하다.","ox":"O","m":"③","c":"A","tp":"상법상 생명보험계약"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-4","t":"생명보험의 보험계약자가 보험수익자의 지정권을 행사하기 전에 보험사고가 발생하여 상법 제733조에 의하여 피보험자의 상속인이 보험수익자가 되는 경우에, 보험수익자인 상속인의 보험금청구권은 상속재산이 아니라 상속인의 고유재산에 해당한다.","ox":"O","m":"④","c":"A","tp":"상법상 생명보험계약"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-5","t":"단체가 규약에 따라 구성원의 전부 또는 일부를 피보험자로 하는 생명보험계약을 체결하는 경우에는 원칙적으로 피보험자의 서면에 의한 동의를 요하지 아니한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 생명보험계약"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-1","t":"화재보험의 경우 집합된 물건을 일괄하여 보험의 목적으로 한 때에는 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함된 것으로 하고 이 경우 타인을 위한 보험계약의 성질을 가지게 된다.","ox":"O","m":"①","c":"A","tp":"손해보험"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-2","t":"자동차보험계약에서 피보험자가 보험기간 중 자동차를 양도한 때에 양수인이 보험계약으로 인하여 생긴 권리와 의무를 승계하는 것으로 추정한다.","ox":"X","m":"②","c":"A","tp":"손해보험"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-3","t":"책임보험에서 피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판 외의 필요비용은 보험의 목적에 포함된 것으로 한다.","ox":"O","m":"③","c":"A","tp":"손해보험"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-4","t":"운송물의 보험에 있어서는 발송한 때와 곳의 가액과 도착지까지의 운임 기타의 비용을 보험가액으로 한다.","ox":"O","m":"④","c":"A","tp":"손해보험"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-5","t":"해상보험계약의 목적은 해상사업에 관한 사고로 인하여 손해를 입게 될 선박, 적하, 희망이익, 운임 및 선비(船費)이다.","ox":"O","m":"⑤","c":"A","tp":"손해보험"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-1","t":"선장은 선박소유자가 선임 또는 해임한다. 선박소유자가 정당한 사유 없이 선장을 해임한 때에는 선장은 이로 인하여 생긴 손해의 배상을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 선장"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-2","t":"선장은 항해 중에 해임 또는 임기가 만료된 경우에도 다른 선장이 그 업무를 처리할 수 있는 때 또는 그 선박이 선적항에 도착할 때까지 그 직무를 집행할 책임이 있다.","ox":"O","m":"②","c":"A","tp":"상법상 선장"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-3","t":"선장은 불가항력으로 인하여 그 직무를 집행하기가 불능한 때에 법령에 다른 규정이 있는 경우를 제외하고는 자기의 책임으로 타인을 선정하여 선장의 직무를 집행하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 선장"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-4","t":"선적항 외에서는 선장은 항해에 필요한 재판상 또는 재판 외의 모든 행위를 할 권한이 있고, 선적항에서는 선장은 특히 위임을 받은 경우 외에는 해원의 고용과 해고를 할 권한만을 가진다.","ox":"O","m":"④","c":"A","tp":"상법상 선장"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-5","t":"선장의 대리권에 대한 제한은 모든 제3자에게 대항하지 못한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 선장"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-1","t":"선박우선특권은 추급권이 있으므로 그 선박소유권의 이전으로 인하여 영향을 받지 않는다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-2","t":"어선의 책임선장이 선주와의 약정에 따라 지급받기로 한 특별상여금 채권은 선박우선특권이 있는 ‘선원과 그 밖의 선박사용인의 고용계약으로 인한 채권’에 포함되지 아니한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-3","t":"선박우선특권 제도는 형평상 요구에 의하여 생긴 제도임에 비하여 임금우선특권제도는 사회정책적 고려에서 인정된 제도로서 그 공익적인 성격이 매우 강하므로 임금우선특권을 선박우선특권보다 우선시키는 것이 합리적 해석이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-4","t":"선박에 대한 압류의 효력이 발생한 때로부터 경락대금 지급시까지의 기간 동안 선박의 정박을 위하여 발생한 정박료는 집행비용에 해당하여 선박우선특권에 해당한다고 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-5","t":"수회의 항해에 관한 채권의 우선특권이 경합하는 때에는 후의 항해에 관한 채권이 전의 항해에 관한 채권에 우선한다.","ox":"O","m":"⑤","c":"A","tp":"선박우선특권"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-1","t":"선하증권은 운송물인도청구권을 표창하는 유가증권으로서 화물상환증과 같은 물권적 효력은 없다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-2","t":"선하증권이 발행된 경우 운송인과 송하인 사이에 선하증권에 기재된 대로 개품운송계약이 체결되고 운송물을 수령 또는 선적한 것으로 추정한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-3","t":"수통의 선하증권이 발행된 경우 양륙항 외에서 화물의 인도청구가 있을 때에는 운송인은 선하증권의 각통의 반환을 받지 아니하면 운송물을 인도할 의무가 없다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-4","t":"재용선계약 등에 의하여 복수의 해상운송 주체가 있는 경우 운송의 최종 수요자인 운송의뢰인에 대한 관계에서 선하증권의 발행사실만으로 당연히 운송인의 지위가 인정되는 것은 아니다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-5","t":"선장은 양륙항에서 수통의 선하증권 중 1통을 소지한 자가 운송물의 인도를 청구하는 경우 그 인도를 거부하지 못하지만, 다른 소지인이 운송물의 인도를 청구한 경우 지체 없이 운송물을 공탁하고 각 청구자에게 그 통지를 발송해야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-1","t":"제3자에 대한 보험자대위란 피보험자의 손해가 제3자의 행위로 인하여 생긴 경우에 보험금을 지급한 보험자가 그 지급한 금액의 한도에서 그 제3자에 대한 보험계약자 또는 피보험자의 권리를 법률상 당연히 취득하는 것을 말한다.","ox":"O","m":"①","c":"A","tp":"상법상 제3자"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-2","t":"상법 제682조의 보험자대위에 의하여 보험자가 취득하는 권리는 당해 사고의 발생자체로 인하여 피보험자가 제3자에 대하여 가지는 불법행위로 인한 손해배상청구권이나 채무불이행으로 인한 손해배상청구권에 한한다.","ox":"O","m":"②","c":"A","tp":"상법상 제3자"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-3","t":"피보험자 등의 제3자에 대한 손해배상청구권이 시효로 인하여 소멸하였다면 보험자는 이를 대위할 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 제3자"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-4","t":"타인을 위한 손해보험에서 보험계약자는 제3자에 대한 보험자대위에서의 제3자에는 해당하지 아니한다.","ox":"X","m":"④","c":"A","tp":"상법상 제3자"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-5","t":"보험자가 보험약관에 정하여져 있는 중요한 내용에 해당하는 면책약관에 대한 설명의무를 위반함으로 인하여 약관의 규제에 관한 법률 제3조 제4항에 따라 해당 면책약관을 계약의 내용으로 주장하지 못하고 보험금을 지급하게 되었더라도, 이는 보험자가 피보험자에게 보험금을 지급할 책임이 있는 경우에 해당하므로 보험자는 보험자대위를 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 제3자"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-1","t":"공동해손으로 인하여 생긴 채권은 그 계산이 종료된 날로부터 1년 이내에 재판상 청구가 없으면 소멸하고, 이 기간은 당사자의 합의에 의하여도 연장할 수 없다.","ox":"X","m":"①","c":"A","tp":"상법상 공동해손"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-2","t":"공동해손의 분담책임이 있는 자는 선박이 도달하거나 적하를 인도한 때에 현존하는 가액의 한도에서 책임을 진다.","ox":"O","m":"②","c":"A","tp":"상법상 공동해손"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-3","t":"공동해손의 분담에 대한 채권은 선박우선특권이 인정되고, 선박소유자의 유한책임이 배제된다.","ox":"O","m":"③","c":"A","tp":"상법상 공동해손"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-4","t":"해상보험계약의 보험자는 피보험자가 지급할 공동해손의 분담액을 보상할 책임이 있으나, 보험의 목적의 공동해손분담가액이 보험가액을 초과할 때에는 그 초과액에 대한 분담액은 보상하지 아니한다.","ox":"O","m":"④","c":"A","tp":"상법상 공동해손"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-5","t":"공동해손은 그 위험을 면한 선박 또는 적하의 가액과 운임의 반액과 공동해손의 액과의 비율에 따라 각 이해관계인이 이를 분담한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 공동해손"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-1","t":"당사자간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다. 그러나 그 가액이 사고발생시의 가액을 현저하게 초과할 때에는 사고발생시의 가액을 보험가액으로 한다.","ox":"O","m":"①","c":"A","tp":"손해보험"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-2","t":"동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때에는 보험자는 각자의 보험금액의 한도에서 연대책임을 진다. 이 경우에는 각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다.","ox":"O","m":"②","c":"A","tp":"손해보험"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-3","t":"임가공업자가 소유자로부터 공급받은 원ㆍ부자재 및 이를 가공한 완제품에 대하여 동산종합보험을 체결한 경우, 소유자가 동일한 목적물에 대한 소유자의 이익을 부보하기 위하여 체결한 동산종합보험계약과 중복보험에 해당한다.","ox":"X","m":"③","c":"A","tp":"손해보험"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-4","t":"보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때에는 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다. 그러나 보험료의 감액은 장래에 대하여서만 그 효력이 있다.","ox":"O","m":"④","c":"A","tp":"손해보험"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-5","t":"사기로 인하여 체결된 중복보험계약이란 보험계약자가 보험가액을 넘어 위법하게 재산적 이익을 얻을 목적으로 중복보험계약을 체결한 경우를 말하는 것이므로 통지의무를 게을리 하였다는 사유만으로 사기로 인한 중복보험계약이 체결되었다고 추정할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"손해보험"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44-1","t":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간내에 지급되지 아니한 때에는 그 계약을 해지할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44-2","t":"계속보험료의 연체로 보험계약이 해지되고 해지환급금이 지급되지 아니한 경우에 보험계약자는 일정한 기간내에 연체보험료에 약정이자를 붙여 보험자에게 지급하고 그 계약의 부활을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44-3","t":"보험사고의 발생으로 보험자가 보험금액을 지급한 때에도 보험금액이 감액되지 아니하는 보험의 경우에는 보험계약자는 그 사고발생 후에도 보험계약을 해지할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44-4","t":"보험기간 중에 보험계약자 또는 피보험자가 사고발생의 위험이 현저하게 변경 또는 증가된 사실을 안 때에는 지체없이 보험자에게 통지하여야 한다. 이를 해태한 때에는 보험자는 그 사실을 안 날로부터 1월내에 한하여 계약을 해지할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44-5","t":"상법 제655조 본문은 보험사고가 발생한 후에도 보험자가 제650조의 규정에 의하여 계약을 해지한 때에는 이미 지급한 보험금액의 반환을 청구할 수 있다고 규정하고 있으므로, 보험자가 계속보험료 지급의 연체를 이유로 상법 제650조 제2항에 의하여 보험계약을 해지한 경우, 상법 제655조의 규정을 들어 계속보험료 지급의 연체 이전에 발생한 보험사고에 대하여 지급한 보험금의 반환을 구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-1","t":"타인의 사망을 보험사고로 하는 보험계약에는 보험계약 체결시에 그 타인의 서면에 의한 동의를 얻어야 한다는 상법 제731조 제1항의 규정은 강행법규로서 이에 위반하여 체결된 보험계약은 무효이다.","ox":"O","m":"①","c":"A","tp":"‘타인의 사망을 보험사고로 하는 보험계약’"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-2","t":"상법 제731조 제1항을 위반하여 피보험자의 서면 동의 없이 타인의 사망을 보험사고로 하는 보험계약을 체결한 자 스스로가 무효를 주장하는 것은 신의성실 또는 금반언의 원칙에 반하지 않는 것으로서 허용된다.","ox":"O","m":"②","c":"A","tp":"‘타인의 사망을 보험사고로 하는 보험계약’"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-3","t":"피보험자인 타인의 동의는 각 보험계약에 대하여 개별적으로 서면에 의하여 이루어져야 하며, 포괄적인 동의 또는 묵시적이거나 추정적 동의만으로는 부족하다.","ox":"O","m":"③","c":"A","tp":"‘타인의 사망을 보험사고로 하는 보험계약’"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-4","t":"타인으로부터 특정한 보험계약에 관하여 서면동의를 할 권한을 구체적ㆍ개별적으로 수여받았음이 분명한 사람이 권한 범위 내에서 타인을 대리 또는 대행하여 서면동의를 한 경우에도 그 타인의 서면동의는 적법한 대리인에 의하여 유효하게 이루어진 것으로 볼 수 있다.","ox":"O","m":"④","c":"A","tp":"‘타인의 사망을 보험사고로 하는 보험계약’"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-5","t":"타인의 생명보험계약 성립 당시 피보험자의 서면동의가 없었다고 하더라도, 이후 피보험자의 추인이 있으면 하자가 치유될 수 있다.","ox":"X","m":"⑤","c":"A","tp":"‘타인의 사망을 보험사고로 하는 보험계약’"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50","t":"보험약관 명시ㆍ설명의무와 관련하여 판례에서 인정하고 있는 설명의무의 대상만 모두 고른 것은?","c":"A","mc":{"s":"보험약관 명시ㆍ설명의무와 관련하여 판례에서 인정하고 있는 설명의무의 대상만 모두 고른 것은?","d":"ㄱ.오토바이 운전자의 경우 보험금의 지급이 제한된다는 약관의 내용\nㄴ.무보험자동차에 의한 상해보상특약에서 보험금액의 산정기준이나 방법\nㄷ.보험약관상 규정된 보험계약자 또는 피보험자의 보험자에 대한 자동차 구조변경 등과 관련된 통지의무의 규정\nㄹ.‘계약자 또는 피보험자가 손해의 통지 또는 보험금청구에 관한 서류에 고의로 사실과 다른 것을 기재하였거나 그 서류 또는 증거를 위조하거나 변조한 경우’를 보험금청구권의 상실사유로 정한 보험약관\nㅁ.가족운전자 한정운전 특별약관","o":["ㄱ, ㄴ","ㄴ, ㄷ, ㄹ","ㄱ, ㄷ, ㅁ","ㄹ, ㅁ","ㄱ, ㅁ"],"a":5}},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-1","t":"사용자가 피용자의 업무수행과 관련하여 행하여진 불법행위로 인하여 직접 손해를 입었거나 피해자인 제3자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에, 사용자는 손해의 공평한 분담이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 손해배상을 청구하거나 구상권을 행사할 수 있다.","ox":"O","m":"①","c":"A","tp":"사용자 또는 보험자의 피용자"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-2","t":"사용자의 보험자가 피해자인 제3자에게 사용자와 피용자의 공동불법행위로 인한 손해배상금을 보험금으로 모두 지급하여 피용자의 보험자가 면책됨으로써 사용자의 보험자가 피용자의 보험자에게 부담하여야 할 부분에 대하여 직접 구상권을 행사하는 경우에, 피용자의 보험자는 사용자의 보험자에 대하여 구상권 제한의 법리를 주장할 수 있다.","ox":"X","m":"②","c":"A","tp":"사용자 또는 보험자의 피용자"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-3","t":"사용자의 보험자가 피해자인 제3자에게 사용자와 피용자의 공동불법행위로 인한 손해배상금을 보험금으로 모두 지급하여 피용자의 보험자가 면책됨으로써 사용자의 보험자가 피용자의 보험자에게 부담하여야 할 부분에 대하여 직접 구상권을 행사하는 경우에, 그와 같은 구상권의 행사는 상법 제724조 제2항에 의한 피해자의 직접청구권을 대위하는 성격을 가진다.","ox":"O","m":"③","c":"A","tp":"사용자 또는 보험자의 피용자"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-4","t":"사용자의 감독이 소홀한 틈을 이용하여 고의로 불법행위를 저지른 피용자가 바로 그 사용자의 부주의를 이유로 자신의 책임의 감액을 주장하는 것은 신의칙상 허용될 수 없고, 사용자와 피용자가 명의대여자와 명의차용자의 관계에 있다고 하더라도 마찬가지이다.","ox":"O","m":"④","c":"A","tp":"사용자 또는 보험자의 피용자"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-5","t":"피용자가 업무수행과 관련한 불법행위로 사용자가 입은 손해 전부를 변제하기로 하는 각서를 작성하여 사용자에게 제출한 사실이 있다고 하더라도, 그와 같은 각서 때문에 사용자가 공평의 견지에서 신의칙상 상당하다고 인정되는 한도를 넘는 부분에 대한 손해의 배상까지 구할 수 있게 되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"사용자 또는 보험자의 피용자"},{"y":2018,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2018_24-27","t":"보험에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"보험에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["보험계약은 당사자 사이의 의사합치에 의하여 성립되는 낙성계약으로서 별도의 서면을 요하지 아니하므로 보험계약을 체결할 때 작성․교부되는 보험증권이나 보험계약의 내용을 변경하는 경우에 작성․교부되는 배서증권은 하나의 증거증권에 불과하다.","보험자의 책임은 당사자간에 다른 약정이 없으면 최초의 보험료의 지급을 받은 때로부터 개시한다.","보험계약자 또는 피보험자나 보험수익자가 보험사고 발생의 통지의무를 해태함으로 인하여 손해가 증가된 때에는 보험자는 그 증가된 손해를 보상할 책임이 없다.","보험금청구권은 2년간 행사하지 않으면 시효의 완성으로 소멸한다.","보험자는 보험금액의 지급에 관하여 약정기간이 있는 경우에는 그 기간내에, 약정기간이 없는 경우에는 보험사고 발생의 통지를 받은 후 지체없이 지급할 보험금액을 정하고 그 정하여진 날부터 10일내에 피보험자 또는 보험수익자에게 보험금액을 지급하여야 한다. 23-6"],"a":4}},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-1","t":"자기신체사고 자동차보험(자손사고보험)은 피보험자의 생명 또는 신체에 관하여 보험사고가 생길 경우에 보험자가 보험계약이 정하는 보험금을 지급할 책임을 지는 것으로서 그 성질은 인보험이다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-2","t":"사망이나 상해를 보험사고로 하는 인보험에서 피보험자의 고의는 보험사고가 전체적으로 보아 고의로 평가되는 행위로 인한 것이어야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-3","t":"생명보험에서는 보험계약자 또는 피보험자의 과실로 사고가 발생하였다고 하더라도 과실상계가 허용되지 아니한다.","ox":"O","m":"③","c":"A","tp":"인보험"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-4","t":"둘 이상의 보험수익자 중 일부가 고의로 피보험자를 사망하게 한 경우 보험자는 다른 보험수익자에 대한 보험금 지급 책임을 면하지 못한다.","ox":"O","m":"④","c":"A","tp":"인보험"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-5","t":"면책약관에서 피보험자의 정신질환을 피보험자의 고의나 피보험자의 자살과 별도의 독립된 면책사유로 규정하고 있는 경우에, 피보험자가 정신질환에 의하여 자유로운 의사결정을 할 수 없는 상태에 이르렀고 이로 인하여 보험사고가 발생한 경우라면 위 면책사유에 해당하지 아니하므로 보험자는 보험금을 지급할 의무가 있다.","ox":"X","m":"⑤","c":"A","tp":"인보험"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-1","t":"보험계약자는 약관 교부·설명의무 위반을 이유로 보험계약이 성립한 날부터 3개월 이내에 보험계약을 취소할 수 있다는 상법 제638조의3 제2항은 약관의규제에관한법률 제3조의 적용을 배제하는 특별규정이다.","ox":"X","m":"①","c":"A","tp":"보험약관의 명시⋅교부⋅설명의무"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-2","t":"보험자가 보험약관의 명시·설명의무에 위반하여 보험계약을 체결한 때에, 보험계약자나 그 대리인이 그 약관에 규정된 고지의무를 위반하였다 하더라도 보험자는 이를 이유로 보험계약을 해지할 수 없다.","ox":"O","m":"②","c":"A","tp":"보험약관의 명시⋅교부⋅설명의무"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-3","t":"상법 제638조의3 제2항에 의하여 보험자가 약관 교부·설명의무를 위반한 때에 보험계약자가 행사할 수 있는 취소권은 보험계약자에게 주어진 권리일 뿐 의무가 아니다.","ox":"O","m":"③","c":"A","tp":"보험약관의 명시⋅교부⋅설명의무"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-4","t":"보험계약자가 약관 교부·설명의무 위반으로 인하여 보험계약을 취소하지 않았다고 하더라도, 보험자의 설명의무 위반의 하자가 치유되는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"보험약관의 명시⋅교부⋅설명의무"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-5","t":"약관조항에 관한 명시·설명의무가 제대로 이행되었더라도 그러한 사정이 보험계약의 체결 여부에 영향을 미치지 아니하였다면 약관조항은 명시·설명의무의 대상이 되는 보험계약의 중요한 내용이라고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"보험약관의 명시⋅교부⋅설명의무"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42","t":"보험계약의 해지, 취소, 무효에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"보험계약의 해지, 취소, 무효에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["보험계약을 체결하면서 중요한 사항에 관한 보험계약자의 고지의무 위반이 사기에 해당하는 경우에는 보험자는 상법의 규정에 의하여 계약을 해지할 수 있음은 물론 보험계약에서 정한 취소권 규정이나 민법의 일반원칙에 따라 보험계약을 취소할 수 있다.","보험금을 부정취득할 목적으로 다수의 보험계약이 체결된 경우에 개별적인 사안에서 민법 제103조 위반으로 인한 보험계약의 무효와 고지의무 위반을 이유로 한 보험계약의 해지나 취소의 요건을 모두 충족한다면, 보험자는 보험계약의 무효, 해지 또는 취소를 선택적으로 주장할 수 있다.","보험모집인이 통지의무의 대상인 보험사고발생의 위험이 현저하게 변경 또는 증가된 사실을 알았다면, 이로써 곧 보험자가 위와 같은 사실을 알았다고 볼 수 있다.","보험계약당시에 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 인하여 중요한 사항을 고지하지 아니하거나 부실의 고지를 한 때에는 보험자는 그 사실을 안 날로부터 1월 내에, 계약을 체결한 날로부터 3년 내에 한하여 계약을 해지할 수 있다.","보험기간중에 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 인하여 사고발생의 위험이 현저하게 변경 또는 증가된 때에는 보험자는 그 사실을 안 날부터 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다."],"a":3}},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44","t":"선박우선특권에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"선박우선특권에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["선박우선특권에 관하여는 성질에 반하지 않는 한 민법의 저당권에 관한 규정을 준용한다.","선박우선특권은 질권과 저당권에 우선한다.","선박우선특권은 건조 중의 선박에 준용된다.","선박우선특권 있는 채권자는 그 선박에 대하여 채무명의 없이도 경매청구권을 행사할 수 있으나, 그 선박에 대한 가압류도 할 수 있음이 원칙이다.","선박채권자의 우선특권은 그 선박소유권의 이전으로 인하여 영향을 받지 아니한다. 23-9"],"a":4}},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49","t":"선박소유자의 책임제한에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"선박소유자의 책임제한에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["선장 등과 같은 선박소유자의 피용자에게 무모한 행위가 있었다는 이유만으로는 선박소유자의 책임제한이 배제된다고 할 수 없다.","법인의 대표기관뿐만 아니라 적어도 법인의 내부적 업무분장에 따라 당해 법인의 관리 업무 전부 또는 특정 부분에 관하여 대표기관에 갈음하여 사실상 회사의 의사결정 등 권한을 행사하는 사람의 행위는 그가 이사회의 구성원 또는 임원이 아니더라도 선박소유자 등 책임제한 배제 규정을 적용할 때 책임제한 주체 자신의 행위로 보아야 한다.","선박소유자 책임제한절차와 별도로 선박소유자 등에게 손해배상 등을 청구하는 소송이 제기된 경우, 그 선박소유자는 그 소송에서 책임제한 배제사유의 부존재에 대한 증명책임을 부담한다.","선박소유자 책임제한절차에서는 절차개시를 신청하는 신청인이 책임제한 배제사유의 부존재를 소명하여야 한다.","선박소유자 책임제한절차에서 당해 채권에 관하여 책임제한 배제사유가 존재하지 아니함이 소명되어 책임제한절차가 개시되고 나아가 조사절차에서 제한채권으로 확정되더라도, 채권자는 책임제한절차와 상관없이 채무자를 상대로 한도액의 제한 없이 책임을 추급하는 개별소송을 제기할 수 있다. 23-10"],"a":3}},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-1","t":"타인의 사망을 보험사고로 하는 보험계약에는 보험계약 체결시에 그 타인의 서면에 의한 동의를 얻어야 한다.","ox":"O","m":"①","c":"A","tp":"상법상 인보험"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-2","t":"오랜 기간 지속되는 생명보험계약에서는 보험계약자의 사정에 따라 계약 내용을 변경해야 하는 경우가 있다. 생명보험계약에서 보험계약자의 지위를 변경하는 데 보험자의 승낙이 필요하다고 정하고 있더라도 보험계약자는 일방적인 의사표시만으로 보험계약상의 지위를 이전할 수 있다.","ox":"X","m":"②","c":"A","tp":"상법상 인보험"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-3","t":"상해 및 사망을 보험사고로 한 보험계약에서는 사고가 보험계약자 또는 피보험자나 보험수익자의 중대한 과실로 인하여 발생한 경우에도 보험자는 보험금을 지급할 책임을 면하지 못한다.","ox":"O","m":"③","c":"A","tp":"상법상 인보험"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-4","t":"15세 미만자 등의 사망을 보험사고로 한 보험계약은 피보험자의 동의가 있었는지 또는 보험수익자가 누구인지와 관계없이 무효가 된다.","ox":"O","m":"④","c":"A","tp":"상법상 인보험"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-5","t":"자기신체사고 자동차보험의 보험자는 특별한 사정이 없는 한 보험약관이 예정하지 아니하는 피보험자의 손해배상청구권을 대위할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"상법상 인보험"},{"y":2019,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2019_25-30","t":"중복보험과 일부보험에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"중복보험과 일부보험에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["하나의 사고에 관하여 여러 개의 무보험자동차특약보험계약이 체결되고 보험금액의 총액이 피보험자가 입은 손해액을 초과하는 때에는 보험자는 각자의 보험금액의 한도에서 연대책임을 지고, 이 경우 각 보험자 사이에서는 각자의 보험금액의 비율에 따른 보상책임을 진다.","여러 보험자가 각자의 보험금액의 한도에서 연대책임을 지는 경우 특별한 사정이 없는 한 그 보험금 지급책임의 부담에 관하여 각 보험자 사이에 주관적 공동관계가 있다고 보기 어려우므로, 각 보험자는 그 보험금 지급채무에 대하여 부진정연대관계에 있다고 봄이 타당하다.","두 개의 책임보험계약이 보험의 목적, 즉 피보험이익과 보험사고의 내용 및 범위가 전부 공통되지는 않으나 상당 부분 중복되고, 발생한 사고가 그 중복되는 피보험이익에 관련된 보험사고에 해당된다면, 이와 같은 두 개의 책임보험계약에 가입한 것은 피보험자, 피보험이익과 보험사고 및 보험기간이 중복되는 범위 내에서 중복보험에 해당한다.","무보험자동차특약보험의 경우 중복보험에 해당하는지 여부를 판단하기 위한 기준이 되는 ‘손해액’ 은 ‘약관에서 정한 보험금 지급기준에 의해 산출한 금액’이 아니라, ‘피보험자의 실제 손해액’을 의미한다.","보험가액의 일부를 보험에 붙인 경우에는 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상할 책임을 진다. 그러나 당사자간에 다른 약정이 있는 때에는 보험자는 보험금액의 한도내에서 그 손해를 보상할 책임을 진다. 22-7"],"a":4}},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-1","t":"복수의 선원 그 밖의 선박사용인이 선박우선특권에 의하여 그들을 고용한 선박소유자가 소유한 복수의 선박 등에 대한 경매신청을 한 경우, 선박우선특권에 의해 경매신청을 한 압류채권자의 지위에서 당연히 우선 배당을 받을 수 있는 대상은 그 선원이 승선한 당해 선박과 그 속구 등의 매각대금에 한정되는 것이고 당해 선박이 아닌 다른 선박에 대한 매각대금에 대하여서까지 따로 배당요구를 하지 않더라도 당연히 우선 배당을 받을 수 있는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-2","t":"국제사법 규정에 의하여 선박우선특권의 성립 여부를 선적국법에 의하여 판단하여야 하는 경우에도, 선박우선특권이 우리나라에서 실행되는 경우에 실행기간을 포함한 실행방법은 우리나라의 절차법에 의하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-3","t":"어선의 책임선장이 선주와의 약정에 따라 지급받기로 한 특별상여금 채권은 상법 제861조 제1항 제2호가 정한 ‘선원 기타의 선박사용인의 고용계약으로 인한 채권’으로서 선박우선특권 있는 채권에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-4","t":"선박우선특권은 일정한 채권을 담보하기 위하여 법률에 의하여 특별히 인정된 권리로서 일반적으로 그 피담보채권과 분리되어 독립적으로 존재하거나 이전되기는 어려우므로, 선박우선특권이 유효하게 이전되는지 여부는 그 선박우선특권이 담보하는 채권의 이전이 인정되는 경우에 비로소 논할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-5","t":"수회의 항해에 관한 채권의 우선특권이 경합하는 때에는 후의 항해에 관한 채권이 전의 항해에 관한 채권에 우선하는 것이 아니라, 각 채권액의 비율에 따라 변제하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"선박우선특권"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-1","t":"타인을 위한 보험계약에서 피보험자 또는 보험수익자는 보험자에 대하여 별도로 수익의 의사표시를 하지 않더라도 당연히 그 보험계약상의 이익을 받을 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-2","t":"보험기간 중에 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 인하여 사고발생의 위험이 현저하게 변경 또는 증가된 때에는 보험자는 그 사실을 안 날부터 1월내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-3","t":"보험계약자가 계약체결 후 보험료의 전부 또는 제1회 보험료를 지급하지 않는 경우 다른 약정이 없는 한 계약성립 후 2월이 경과하면 그 계약은 해제된 것으로 본다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-4","t":"계속보험료가 약정한 시기에 지급되지 아니한 경우 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간 내에 지급되지 아니한 때에는 그 계약을 해지할 수 있다. 다만 보험계약자는 계약이 해지되고 해지환급금이 지급된 이후라도 일정한 기간 내에 연체보험료에 약정이자를 붙여 보험자에게 지급하고 그 계약의 부활을 청구할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-5","t":"보험계약자가 고지의무를 위반하여 고지하지 않은 사실과 보험사고의 발생 사이의 인과관계가 없더라도 보험자는 고지의무위반을 이유로 계약을 해지할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43-1","t":"피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판외의 필요비용은 보험의 목적에 포함된 것으로 한다. 피보험자는 보험자에 대하여 그 비용의 선급을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 책임보험"},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43-2","t":"수개의 책임보험을 체결한 경우에 보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 아니한다.","ox":"O","m":"②","c":"A","tp":"상법상 책임보험"},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43-3","t":"피보험자가 제3자에 대하여 변제, 승인, 화해 또는 재판으로 인하여 채무가 확정된 때에는 지체없이 보험자에게 그 통지를 발송하여야 하고, 보험자는 특별한 기간의 약정이 없으면 위 통지를 받은 날로부터 10일내에 보험금액을 지급하여야 한다.","ox":"O","m":"③","c":"A","tp":"상법상 책임보험"},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43-4","t":"제3자는 피보험자가 책임을 질 사고로 입은 손해에 대하여 보험금액의 한도내에서 보험자에게 직접 보상을 청구할 수 있고, 위 청구권은 보험금청구권이므로 상법 제662조에 따라 보험사고 발생일로부터 3년간 행사하지 아니하면 시효의 완성으로 소멸한다.","ox":"X","m":"④","c":"A","tp":"상법상 책임보험"},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43-5","t":"보험자는 피보험자가 책임을 질 사고로 인하여 생긴 손해에 대하여 제3자가 그 배상을 받기 전에는 보험금액의 전부 또는 일부를 피보험자에게 지급하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 책임보험"},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47-1","t":"운송인이 수통의 선하증권을 교부한 경우 양륙항이나 양륙항이 아닌 곳에서 수통의 선하증권 중 1통을 소지한 자가 운송물의 인도를 청구하여 운송물의 인도를 받은 때에는 다른 선하증권의 효력이 상실된다.","ox":"X","m":"①","c":"A","tp":"상법상 해상운송"},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47-2","t":"2인 이상의 선하증권소지인이 운송물의 인도를 청구한 때에는 선장은 지체 없이 운송물을 공탁하고 각 청구자에게 그 통지를 발송하여야 한다. 이 때 수인의 선하증권소지인에게 공통되는 전 소지인으로부터 먼저 교부를 받은 증권소지인의 권리가 다른 소지인의 권리에 우선한다.","ox":"O","m":"②","c":"A","tp":"상법상 해상운송"},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47-3","t":"해상물건운송인의 면책사유나 책임제한에 관한 규정은 해상물건운송인의 불법행위로 인한 손해배상책임에는 적용되지 않는다.","ox":"X","m":"③","c":"A","tp":"상법상 해상운송"},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47-4","t":"여객이 출발지나 항해 도중 정박항에서 승선시기까지 승선하지 아니한 때에는 선장은 즉시 발항할 수 있다. 이 경우 정박항에서 발항한 경우에는 여객이 운임 전액을 지급하여야 하나 출발지에서 발항한 경우에는 발항 전 계약 해제에 준하여 운임의 반액을 지급할 의무가 있다.","ox":"X","m":"④","c":"A","tp":"상법상 해상운송"},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47-5","t":"항해용선계약에서 운송물이 전부 또는 일부가 멸실 또는 연착된 경우의 손해배상액은 인도할 날의 도착지의 가격에 따른다.","ox":"X","m":"⑤","c":"A","tp":"상법상 해상운송"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-1","t":"상법 제682조 제1항의 보험자대위권의 규정 취지가 피보험자와 보험자 및 제3자의 이해관계를 조정하고 위험을 분배하고자 하는 데에 있음을 고려할 때, 보험자는 보험계약의 목적이 되는 피보험이익을 기준으로 보험목적물에 발생한 손해에 대하여 자신이 지급한 보험금의 한도 내에서 보험계약자나 피보험자의 제3자에 대한 권리를 취득할 수 있다. 따라서 보험자대위권 행사 범위는 보험목적물을 대상으로 산정하여야 한다.","ox":"O","m":"①","c":"A","tp":"상법상 보험자대위"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-2","t":"일부보험의 피보험자는 보험자로부터 수령한 보험금으로 전보되지 않고 남은 손해에 관하여 제3자를 상대로 그의 배상책임(다만 과실상계 등에 의하여 제한된 범위 내의 책임을 말함)을 이행할 것을 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 보험자대위"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-3","t":"하나의 사고로 보험목적물과 보험목적물이 아닌 재산에 대하여 한꺼번에 손해가 발생한 경우, 보험목적물이 아닌 재산에 발생한 손해에 대해서는 보험계약으로 인한 법률관계를 전제로 하는 상법 제682조의 보험자대위가 적용될 수 없으므로, 보험목적물에 대한 부분으로 한정하여 보험자가 보험자대위에 의하여 제3자에게 청구할 수 있는 권리의 범위를 결정하여야 한다.","ox":"O","m":"③","c":"A","tp":"상법상 보험자대위"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-4","t":"보험금을 지급한 보험자는 상법 제682조 소정의 보험자대위제도에 따라 지급한 보험금의 한도 내에서 피보험자가 제3자에게 갖는 손해배상청구권을 취득하는 결과 피보험자는 보험자로부터 지급 받은 보험금의 한도 내에서 제3자에 대한 손해배상청구권을 잃고 그 제3자에 대하여 청구할 수 있는 손해배상액이 지급된 보험금액만큼 감소되므로, 손해보험의 보험사고에 관하여 동시에 불법행위나 채무불이행에 기한 손해배상책임을 지는 제3자가 있어 피보험자가 그를 상대로 손해배상청구를 하는 경우에, 피보험자가 손해보험계약에 따라 보험자로부터 수령한 보험금은 제3자의 손해배상책임액에서 공제하여야 한다.","ox":"X","m":"④","c":"A","tp":"상법상 보험자대위"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-5","t":"상법 제682조의 제3자에 대한 보험자대위규정은 타인을 위한 손해보험계약에도 적용되고, 타인을 위한 손해보험계약의 보험계약자가 당연히 제3자의 범주에서 제외되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"상법상 보험자대위"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-1","t":"상법 제814조 제1항은 운송인의 송하인 또는 수하인에 대한 채권과 채무는 그 청구원인의 여하에 불구하고 운송인이 수하인에게 운송물을 인도한 날 또는 인도할 날부터 1년 이내에 재판상 청구가 없으면 소멸하되, 당사자의 합의에 의하여 위 기간을 연장할 수 있도록 규정하고 있다. 이러한 해상 운송인의 송하인이나 수하인에 대한 권리·의무에 관한 소멸기간은 제척기간이고, 제척기간의 기산점은 ‘운송물을 인도한 날 또는 인도할 날’이다.","ox":"O","m":"①","c":"A","tp":"상법상 해상운송 등"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-2","t":"해상운송계약에서 운송인이 운송계약상 정해진 양륙항에 도착한 후 운송물을 선창에서 인도 장소까지 반출하여 보세창고업자에게 인도하는 것만으로는 그 운송물이 운송인의 지배를 떠나 정당한 수하인에게 인도된 것으로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"상법상 해상운송 등"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-3","t":"육상운송, 해상운송, 항공운송 중 적어도 두 가지 이상의 서로 다른 운송수단을 결합하여 운송을 수행하는 복합운송 과정에서 운송물의 멸실·훼손 등으로 인하여 손해가 발생한 경우에 손해가 발생한 운송구간이 불분명하거나 그 성질상 특정한 지역으로 한정할 수 없는 때에는 복합운송인은 운임이 가장 비싼 구간에 적용되는 법에 따라 책임을 진다.","ox":"X","m":"③","c":"A","tp":"상법상 해상운송 등"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-4","t":"운송물이 멸실되거나 운송물의 인도가 불가능하게 된 경우에는 ‘운송물을 인도할 날’을 기준으로 상법 제814조 제1항의 제척기간이 도과하였는지를 판단하여야 한다. 여기서 ‘운송물을 인도할 날’이란 통상 운송계약이 그 내용에 좇아 이행되었으면 인도가 행하여져야 했던 날을 의미한다.","ox":"O","m":"④","c":"A","tp":"상법상 해상운송 등"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-5","t":"운송물이 물리적으로 멸실되는 경우뿐만 아니라 운송인이 운송물의 인도를 거절하거나 운송인의 사정으로 운송이 중단되는 등의 사유로 운송물이 인도되지 않은 경우에도 ‘운송물을 인도할 날’을 기준으로 하여 상법 제814조 제1항의 제소기간이 도과하였는지를 판단하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 해상운송 등"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-1","t":"화재보험의 피보험자가 보험금을 지급받은 후 화재에 대한 책임 있는 자로부터 손해배상을 받으면서 나머지 손해배상청구권을 포기하였다 하더라도, 피보험자의 화재에 대한 책임 있는 자에 대한 손해배상청구권은 피보험자가 보험자로부터 보험금을 지급받음과 동시에 그 보험금액의 범위 내에서 보험자에게 당연히 이전되므로, 이미 이전된 보험금 상당 부분에 관한 손해배상청구권을 포기하더라도 이는 효력이 없고, 따라서 보험자는 이로 인하여 손해를 입었다고도 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"손해보험"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-2","t":"손해보험의 보험사고에 관하여 동시에 불법행위나 채무불이행에 기한 손해배상책임을 지는 제3자가 있어 피보험자가 그를 상대로 손해배상청구를 하는 경우, 피보험자가 손해보험계약에 따라 보험자로부터 수령한 보험금은 민법상 손익공제에 관한 법리에 따라 그의 손해배상책임액에서 당연히 공제되어야 한다. 다만 이는 항변사항으로서 위 제3자는 자신의 소송에서 피보험자가 같은 목적의 손해보험에 기초하여 보험금을 지급받은 사실을 주장ㆍ입증하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-3","t":"보험계약자는 계약 체결 후 지체 없이 보험료의 전부 또는 1회 보험료를 지급하여야 하며, 보험계약자가 이를 지급하지 아니하는 경우에는 다른 약정이 없는 한 계약성립 후 2월이 경과하면 그 계약은 해제된 것으로 본다.","ox":"O","m":"③","c":"A","tp":"손해보험"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-4","t":"상법 제682조는 손해가 제3자의 행위로 인하여 생긴 경우 보험금액을 지급한 보험자는 그 지급한 금액의 한도 내에서 그 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다고 규정하고 있는바, 이때 보험자가 취득하는 채권의 소멸시효 기간과 그 기산점 또한 피보험자 등이 제3자에 대하여 가지는 채권 자체를 기준으로 판단하여야 한다.","ox":"O","m":"④","c":"A","tp":"손해보험"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-5","t":"특정한 타인을 위한 보험의 경우에 보험계약자가 보험료의 지급을 지체한 때에는 보험자는 그 타인에게도 상당한 기간을 정하여 보험료의 지급을 최고한 후가 아니면 그 계약을 해제 또는 해지하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"손해보험"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-1","t":"보험계약이 체결되기 전에 보험사고가 이미 발생한 경우, 보험계약의 당사자 쌍방 및 피보험자 전부가 이를 알지 못한 경우를 제외하고는 그 보험계약을 무효로 한다는 상법 제644조의 규정은, 보험사고는 원칙적으로 불확정한 것이어야 한다는 고려에 따라 마련된 임의규정일 뿐이므로, 당사자가 명시적으로 위 규정의 적용을 배제하기로 합의하는 경우 해당 보험계약은 더는 상법 제644조에 저촉되어 무효가 되지 아니한다고 보아야 한다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-2","t":"보험계약의 중요사항은 반드시 보험약관에 규정된 것에 한정된다고 할 수 없으므로, 보험약관만으로 보험계약의 중요사항을 설명하기 어려운 경우 보험회사 또는 보험모집종사자는 상품설명서 등 적절한 추가자료를 활용하는 등의 방법으로 개별 보험상품의 특성과 위험성에 관한 보험계약의 중요사항을 고객이 이해할 수 있도록 설명하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-3","t":"통신판매 방식으로 체결된 상해보험계약에서 보험자가 약관 내용의 개요를 소개한 것이라는 내용과 면책사고에 해당하는 경우를 확인하라는 내용이 기재된 안내문과 청약서를 보험계약자에게 우송한 것만으로는 보험자의 면책약관에 관한 설명의무를 다한 것으로 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-4","t":"보험자는 보험계약자로부터 보험계약의 청약과 함께 보험료 상당액의 전부 또는 일부를 지급받은 경우(인보험계약의 피보험자가 신체검사를 받아야 하는 경우에는 그 검사도 받은 때)에 그 청약을 승낙하기 전에 보험계약에서 정한 보험사고가 생긴 때에는 그 청약을 거절할 사유가 없는 한 보험계약상의 책임을 진다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-5","t":"보험자가 계약 체결에 있어서 서면으로 질문한 사항은 보험계약에 있어서 중요한 사항에 해당하는 것으로 추정되고, 여기의 서면에는 보험청약서도 포함된다. 따라서 보험청약서에 일정한 사항에 관하여 답변을 구하는 취지가 포함되어 있다면 그 사항은 상법 제651조에서 말하는 ‘중요한 사항’으로 추정된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-1","t":"정기용선계약은 선박소유자가 용선자에게 선원이 승무하고 항해 장비를 갖춘 선박을 일정한 기간동안 항해에 사용하게 할 것을 약정하고 용선자가 이에 대하여 기간으로 정한 용선료를 지급하기로 약정함으로써 그 효력이 생기는 계약을 말한다.","ox":"O","m":"①","c":"A","tp":"상법상 정기용선"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-2","t":"정기용선자는 약정한 범위 안의 선박의 사용을 위하여 선장을 지휘할 권리가 있다.","ox":"O","m":"②","c":"A","tp":"상법상 정기용선"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-3","t":"선장ㆍ해원, 그 밖의 선박사용인이 정기용선자의 정당한 지시를 위반하여 정기용선자에게 손해가 발생한 경우에는 선장이 이를 배상할 책임이 있다.","ox":"X","m":"③","c":"A","tp":"상법상 정기용선"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-4","t":"정기용선자가 용선료를 약정기일에 지급하지 아니한 때에는 선박소유자는 계약을 해제 또는 해지할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 정기용선"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-5","t":"정기용선자가 제3자와 운송계약을 체결하여 운송물을 선적한 후 선박의 항해 중에 선박소유자가 용선료의 연체를 이유로 계약을 해제 또는 해지한 때에는 선박소유자는 적하이해관계인에 대하여 정기용선자와 동일한 운송의무가 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 정기용선"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-1","t":"고지의무 위반이 있다고 하더라도 보험계약 체결일로부터 3년을 경과하면 보험계약을 해지할 수 없다.","ox":"O","m":"①","c":"A","tp":"보험계약상 고지의무"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-2","t":"중요한 사항의 고지는 보험계약의 청약시까지 하여야 한다.","ox":"X","m":"②","c":"A","tp":"보험계약상 고지의무"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-3","t":"고지의무자는 보험계약자와 피보험자이다.","ox":"O","m":"③","c":"A","tp":"보험계약상 고지의무"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-4","t":"고지의무 위반사실과 보험사고 발생과의 인과관계의 부존재의 점에 관한 입증책임은 보험계약자에게 있다.","ox":"O","m":"④","c":"A","tp":"보험계약상 고지의무"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-5","t":"보증보험에서 보험계약자의 보증인이 누구인가는 일반적으로는 고지의무의 대상이 되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"보험계약상 고지의무"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48-1","t":"15세미만자, 심신상실자 또는 심신박약자의 상해를 보험사고로 한 상해보험계약도 유효하다.","ox":"O","m":"①","c":"A","tp":"상법상 상해보험"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48-2","t":"태아를 피보험자로 하는 상해보험계약에서 그 보험계약이 정한 바에 따라 보험기간이 개시된 후 태아가 보험계약에서 정한 우연한 사고로 상해를 입었지만, 그 상해를 입은 시기가 출생 전이라면 이는 보험기간 중 보험사고에 해당하지 아니한다.","ox":"X","m":"②","c":"A","tp":"상법상 상해보험"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48-3","t":"태아를 피보험자로 하는 상해보험계약의 보통약관에 면책사유로 규정된 피보험자의 출산은 태아인 피보험자가 출산의 주체가 되는 경우만을 의미하는 것이지 피보험자가 출산의 대상이 되는 경우까지 포함하는 것으로 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 상해보험"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48-4","t":"약관이나 개별약정으로 출생 전 상태인 태아의 신체에 대한 상해를 보험의 담보범위에 포함하는 것이 보험제도의 목적과 취지에 부합하고 보험계약자나 피보험자에게 불리하지 않으므로 상법 제663조에 반하지 아니하고 민법 제103조의 공서양속에도 반하지 않고, 계약자유의 원칙상 태아를 피보험자로 하는 상해보험계약은 유효하다.","ox":"O","m":"④","c":"A","tp":"상법상 상해보험"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48-5","t":"인보험계약의 보험자는 보험사고로 인하여 생긴 보험계약자 또는 보험수익자의 제3자에 대한 권리를 대위하여 행사하지 못한다. 그러나 상해보험계약의 경우에 당사자간에 다른 약정이 있는 때에는 보험자는 피보험자의 권리를 해하지 아니하는 범위안에서 그 권리를 대위하여 행사할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상해보험"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-1","t":"타인의 생명보험계약 성립 당시 피보험자의 서면동의가 없다면 보험계약은 확정적으로 무효가 되고, 피보험자가 이미 무효가 된 보험계약을 추인하였다고 하더라도 그 보험계약이 유효로 될 수는 없다.","ox":"O","m":"①","c":"A","tp":"상법상 생명보험계약"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-2","t":"단체가 규약에 따라 구성원의 전부 또는 일부를 피보험자로 하는 생명보험계약을 체결하는 경우에는 원칙적으로 피보험자의 서면에 의한 동의를 요하지 아니한다.","ox":"O","m":"②","c":"A","tp":"상법상 생명보험계약"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-3","t":"15세미만자, 심신상실자 또는 심신박약자의 사망을 보험사고로 한 보험계약은 무효이다. 심신박약자가 보험계약을 체결하거나 단체보험의 피보험자가 될 때에 의사능력이 있는 경우에도 마찬가지이다.","ox":"X","m":"③","c":"A","tp":"상법상 생명보험계약"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-4","t":"보험계약자가 피보험자의 상속인을 보험수익자로 하여 맺은 생명보험계약에 있어서 피보험자의 상속인은 피보험자의 사망이라는 보험사고가 발생한 때에는 보험수익자의 지위에서 보험자에 대하여 보험금 지급을 청구할 수 있고, 이 권리는 상속재산이 아니라 상속인의 고유재산이다.","ox":"O","m":"④","c":"A","tp":"상법상 생명보험계약"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-5","t":"타인의 사망을 보험사고로 하는 보험계약에서 피보험자인 타인의 동의는 각 보험계약에 대하여 개별적으로 서면에 의하여 이루어져야 하고 포괄적인 동의 또는 묵시적이거나 추정적 동의만으로는 부족하다.","ox":"O","m":"⑤","c":"A","tp":"상법상 생명보험계약"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-1","t":"선하증권이 발행된 경우 운송인과 송하인 사이에 선하증권에 기재된 대로 개품운송계약이 체결되고 운송물을 수령 또는 선적한 것으로 추정한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-2","t":"재용선계약 등에 의하여 복수의 해상운송 주체가 있는 경우 운송의 최종 수요자인 운송의뢰인에 대한 관계에서도 선하증권의 발행사실만으로 당연히 운송인의 지위가 인정된다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-3","t":"운송인은 운송물을 수령한 후 송하인의 청구에 의하여 선하증권을 1통 또는 수통 교부하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-4","t":"양륙항에서 수통의 선하증권 중 1통을 소지한 자가 운송물의 인도를 청구하는 경우에도 선장은 그 인도를 거부하지 못한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-5","t":"선하증권은 운송물인도청구권을 표창하는 유가증권으로서 화물상환증과 같은 물권적 효력이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-1","t":"상법 제680조 제1항의 피보험자의 손해방지의무 내용에는 손해를 직접적으로 방지하는 행위는 물론이고 간접적으로 방지하는 행위도 포함되고, 그 손해는 피보험이익에 대한 구체적인 침해의 결과로서 생기는 손해뿐만 아니라, 보험자의 구상권과 같이 보험자가 손해를 보상한 후에 취득하게 되는 이익을 상실함으로써 결과적으로 보험자에게 부담되는 손해까지 포함된다.","ox":"X","m":"①","c":"A","tp":"손해보험"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-2","t":"손해보험의 보험사고에 관하여 동시에 불법행위나 채무불이행에 기한 손해배상책임을 지는 제3자가 있어 피보험자가 그를 상대로 손해배상청구를 하는 경우에, 피보험자가 손해보험계약에 따라 보험자로부터 수령한 보험금은 제3자의 손해배상책임액에서 공제할 것이 아니고, 피보험자는 보험자로부터 수령한 보험금으로 전보되지 않고 남은 손해에 관하여 제3자를 상대로 그의 배상책임을 이행할 것을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-3","t":"상법 제724조 제2항에 의하여 피해자에게 인정되는 직접청구권의 법적 성질은 보험자가 피보험자의 피해자에 대한 손해배상채무를 병존적으로 인수한 것으로서 피해자가 보험자에 대하여 가지는 손해배상청구권이고, 피보험자의 보험자에 대한 보험금청구권의 변형 내지는 이에 준하는 권리가 아니다.","ox":"O","m":"③","c":"A","tp":"손해보험"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-4","t":"하나의 사고로 보험목적물과 보험목적물이 아닌 재산에 대하여 한꺼번에 손해가 발생한 경우, 보험목적물에 대한 부분으로 한정하여 보험자가 보험자대위에 의하여 제3자에게 청구할 수 있는 권리의 범위를 결정하여야 한다.","ox":"O","m":"④","c":"A","tp":"손해보험"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-5","t":"상법 제724조 제2항에 의하여 피해자에게 인정되는 직접청구권에 대한 지연손해금에 관하여는 연 5%의 민사법정이율이 적용된다.","ox":"O","m":"⑤","c":"A","tp":"손해보험"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-1","t":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간 내에 지급되지 아니한 때에는 그 계약을 해지할 수 있다. 이 경우 연체 이전에 발생한 보험사고에 대해서도 보험금을 지급할 의무가 없다.","ox":"X","m":"①","c":"A","tp":"상법상 보험계약의 해지"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-2","t":"보험기간 중 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 인하여 사고발생의 위험이 현저하게 변경 또는 증가된 때에는 보험자는 그 사실을 안 날부터 1월 내에 보험료의 증액을 청구하거나 해지할 수 있다. 그 경우 보험모집인이 보험사고발생의 위험이 현저하게 변경 또는 증가된 사실을 알았다면 보험자가 이를 알았다고 본다.","ox":"X","m":"②","c":"A","tp":"상법상 보험계약의 해지"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-3","t":"보험자가 보험약관의 교부·설명의무를 위반하여 보험계약을 체결하였다 하더라도 보험계약자가 그 약관에 규정된 고지의무를 위반하였다면 보험자는 이를 이유로 보험계약을 해지할 수 있다.","ox":"X","m":"③","c":"A","tp":"상법상 보험계약의 해지"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-4","t":"보험계약의 존속 중에 당사자 일방의 부당한 행위 등으로 인하여 계약의 기초가 되는 신뢰관계가 파괴되어 계약의 존속을 기대할 수 없는 중대한 사유가 있는 때에는 상대방은 그 계약을 해지할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 보험계약의 해지"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-5","t":"고지의무를 위반한 사실 또는 위험이 현저하게 변경되거나 증가된 사실이 보험사고 발생에 영향을 미치지 아니한 경우라 하더라도 보험계약자가 사전에 올바로 고지하였다면 보험계약을 체결하지 않았거나 최소 동일한 내용으로 보험계약을 체결하지 않았을 것이므로, 보험금을 지급할 책임이 없다.","ox":"X","m":"⑤","c":"A","tp":"상법상 보험계약의 해지"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-1","t":"선박이 출항 준비를 하다가 화재가 발생하였고 수리를 마친 후 항해를 계속한 경우 그 수리비는 선박의 상태 및 가치를 유지·보존하기 위한 비용으로 선박우선특권의 피담보채권에 해당한다.","ox":"X","m":"①","c":"A","tp":"상법상 선박우선특권"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-2","t":"목적하는 항해를 마치지 않고 항해 도중 경매 또는 양도처분으로 항해가 중지된 경우 항해를 폐지한 시기에 선박이 존재하는 항에서 수리한 비용은 피담보채권에 해당하지 않는다.","ox":"X","m":"②","c":"A","tp":"상법상 선박우선특권"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-3","t":"선체용선에 관한 상법 제850조 제2항의 규정이 정기용선에 유추적용되어 정기용선된 선박의 이용에 관하여 생긴 우선특권을 가지는 채권자는 선박소유자의 선박에 대하여 경매청구를 할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 선박우선특권"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-4","t":"선박채권자의 우선특권은 그 선박소유권의 이전으로 인하여 영향을 받지 않으므로, 선박의 양수인에게도 채무의 변제를 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 선박우선특권"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-5","t":"선박우선특권은 건조 중인 선박에는 준용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"상법상 선박우선특권"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-1","t":"상법의 일반조항과 다른 내용으로 보험자의 책임개시시기를 정한 경우, 그 약관 내용은 명시·설명의무의 대상에 해당한다.","ox":"O","m":"①","c":"A","tp":"보험약관의 명시·설명의무"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-2","t":"‘보험약관에 정한 보험금에서 상대방 차량이 가입한 자동차보험 등의 대인배상으로 보상받을 수 있는 금액을 공제한 액수만을 자기신체사고 보험금으로 지급한다.'는 약관 조항은 명시·설명의무의 대상에 해당한다.","ox":"O","m":"②","c":"A","tp":"보험약관의 명시·설명의무"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-3","t":"무보험자동차에 의한 상해보상특약에 있어서 보험금액의 산정기준이나 방법은 명시ㆍ설명의무의 대상에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"보험약관의 명시·설명의무"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-4","t":"보험계약자가 별도의 설명 없이도 충분히 예상할 수 있었던 사항이거나 보험계약자나 그 대리인이 그 내용을 충분히 잘 알고 있는 경우에는 보험자로서는 보험계약자 또는 그 대리인에게 약관의 내용을 따로 설명할 필요가 없다.","ox":"O","m":"④","c":"A","tp":"보험약관의 명시·설명의무"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-5","t":"‘계약자 또는 피보험자가 손해의 통지 또는 보험금청구에 관한 서류에 고의로 사실과 다른 것을 기재하였거나 그 서류 또는 증거를 위조하거나 변조한 경우'를 보험금청구권의 상실사유로 정한 보험약관은 명시·설명의무의 대상에 해당한다.","ox":"X","m":"⑤","c":"A","tp":"보험약관의 명시·설명의무"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-1","t":"보험계약자는 위임을 받거나 위임을 받지 아니하고 특정 또는 불특정의 타인을 위하여 보험계약을 체결할 수 있으나 손해보험계약의 경우에 그 타인의 위임이 없는 때에는 보험계약자는 이를 보험자에게 고지하여야 하고, 그 고지가 없는 때에는 타인이 그 보험계약이 체결된 사실을 알지 못하였다는 사유로 보험자에게 대항하지 못한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-2","t":"보험사고가 발생하기 전에는 보험계약자는 언제든지 계약의 전부 또는 일부를 해지할 수 있다. 그러나 상법 제639조(타인을 위한 보험)의 보험계약의 경우에는 보험계약자는 그 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 그 계약을 해지하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-3","t":"보험계약자 또는 피보험자나 보험수익자는 보험사고의 발생을 안 때에는 지체없이 보험자에게 그 통지를 발송하여야 하고, 보험계약자 또는 피보험자나 보험수익자가 그 통지의무를 해태함으로 인하여 손해가 증가된 때에는 보험자는 그 증가된 손해를 보상할 책임이 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-4","t":"보험계약자가 다수의 계약을 통하여 보험금을 부정 취득할 목적으로 보험계약을 체결하여 그것이 민법 제103조에 따라 선량한 풍속 기타 사회질서에 반하여 무효인 경우 보험자의 보험금에 대한 부당이득반환청구권은 민법상 10년의 소멸시효기간이 적용된다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-5","t":"보험계약의 당사자 사이에 계약상 채무의 존부나 범위에 관하여 다툼이 있는 경우 그로 인한 법적 불안을 제거하기 위하여 보험회사는 먼저 보험수익자를 상대로 소극적 확인의 소를 제기할 확인의 이익이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-1","t":"책임보험계약의 보험자는 피보험자가 보험기간 중의 사고로 인하여 제3자에게 배상할 책임을 진 경우에 이를 보상할 책임이 있고, 이 때 피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판외의 필요비용은 보험의 목적에 포함된 것으로 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-2","t":"피보험자가 제3자로부터 배상청구를 받았을 때에는 지체 없이 보험자에게 그 통지를 발송하여야 하고, 피보험자가 상법 제722조 제1항의 통지를 게을리하여 손해가 증가된 경우 보험자는 그 증가된 손해를 보상할 책임이 없다.","ox":"O","m":"②","c":"A","tp":"책임보험"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-3","t":"피보험자가 동일한 사고로 제3자에게 배상책임을 짐으로써 입은 손해를 보상하는 수개의 책임보험계약이 동시 또는 순차로 체결된 경우에 그 보험금액의 총액이 피보험자의 제3자에 대한 손해배상액을 초과하는 때에는 중복보험의 규정을 준용한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-4","t":"제3자는 피보험자가 책임을 질 사고로 입은 손해에 대하여 보험금액의 한도내에서 보험자에게 직접 보상을 청구할 수 있고, 이러한 직접청구권에 대한 지연손해금에는 연 6%의 상사법정이율이 적용된다.","ox":"X","m":"④","c":"A","tp":"책임보험"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-5","t":"피해자의 직접청구권에 따라 보험자가 부담하는 손해배상채무는 보험계약을 전제로 하는 것으로서 보험계약에 따른 보험자의 책임 한도액의 범위 내에서 인정되어야 한다.","ox":"O","m":"⑤","c":"A","tp":"책임보험"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-1","t":"보험계약자가 피보험자의 상속인을 보험수익자로 하여 맺은 생명보험계약에 있어서 피보험자의 상속인은 피보험자의 사망이라는 보험사고가 발생한 때에는 보험자에 대하여 보험금 지급을 청구할 수 있고, 이 권리는 보험계약의 효력으로 당연히 생기는 것으로서 상속재산이다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-2","t":"생명보험계약의 약관에 보험계약자는 보험계약의 해약환급금의 범위 내에서 보험회사가 정한 방법에 따라 대출을 받을 수 있고, 이에 따라 대출이 된 경우에 보험계약자는 그 대출 원리금을 언제든지 상환할 수 있으며, 만약 상환하지 아니한 동안에 보험금이나 해약환급금의 지급사유가 발생한 때에는 위 대출 원리금을 공제하고 나머지 금액만을 지급한다는 취지로 규정되어 있다면, 보험약관대출금의 경제적 실질은 보험회사가 장차 지급하여야 할 보험금이나 해약환급금을 미리 지급하는 선급금과 같은 성격이고, 일반적인 대출과는 다르다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-3","t":"보험수익자가 보험존속 중에 사망한 때에는 보험계약자는 다시 보험수익자를 지정할 수 있다. 이 경우에 보험계약자가 지정권을 행사하지 아니하고 사망한 때에는 보험수익자의 상속인을 보험수익자로 한다.","ox":"O","m":"③","c":"A","tp":"생명보험"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-4","t":"보험계약자가 계약체결후에 보험수익자를 지정 또는 변경할 때에는 보험자에 대하여 그 통지를 하지 아니하면 이로써 보험자에게 대항하지 못한다.","ox":"O","m":"④","c":"A","tp":"생명보험"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-5","t":"사망을 보험사고로 한 보험계약에서는 사고가 보험계약자 또는 피보험자나 보험수익자의 중대한 과실로 인하여 발생한 경우에도 보험자는 보험금을 지급할 책임을 면하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"생명보험"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-1","t":"약관조항에 관한 명시·설명의무가 제대로 이행되었더라도 그러한 사정이 보험계약의 체결 여부에 영향을 미치지 않은 경우, 약관조항이 명시·설명의무의 대상이 되는 보험계약의 중요한 내용이라고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"보험약관의 설명의무"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-2","t":"보험자 또는 보험계약의 체결 또는 모집에 종사하는 자는 보험계약을 체결할 때에 보험계약자 또는 피보험자에게 보험약관에 기재되어 있는 보험상품의 내용, 보험료율의 체계 및 보험청약서상 기재사항의 변동사항 등 보험계약의 중요한 내용에 대하여 구체적이고 상세하게 설명할 의무를 지고, 보험자가 이러한 보험약관의 설명의무를 위반하여 보험계약을 체결한 때에는 약관의 내용을 보험계약의 내용으로 주장할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-3","t":"보험회사 또는 보험모집종사자가 보험계약을 체결하거나 모집하면서 보험계약의 중요사항에 관한 설명의무를 위반한 경우, 이로 인해 발생한 고객의 손해를 배상할 책임을 부담한다.","ox":"O","m":"③","c":"A","tp":"보험약관의 설명의무"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-4","t":"보험계약 체결에 설명의무 위반이 있는 경우에 이후 보험약관에 따른 해약환급금이 지급되었다면, 보험계약자가 설명의무 위반으로 입은 손해는 납입한 보험료 합계액에서 지급받은 해약환급금액을 공제한 금액 상당이다.","ox":"O","m":"④","c":"A","tp":"보험약관의 설명의무"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-5","t":"약관에 정하여진 사항으로서 이미 법령에 의하여 정하여진 것을 되풀이하거나 부연하는 정도에 불과한 사항에 대해서도 고객이 이를 알고 있다고 단정할 수 없으므로 보험자는 명시·설명의무를 부담한다.","ox":"X","m":"⑤","c":"A","tp":"보험약관의 설명의무"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-1","t":"선박과 적하의 공동위험을 면하기 위한 선장의 선박 또는 적하에 대한 처분으로 인하여 생긴 손해 또는 비용은 공동해손으로 하고, 공동해손은 그 위험을 면한 선박 또는 적하의 가액과 운임의 반액과 공동해손의 액과의 비율에 따라 각 이해관계인이 이를 분담한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-2","t":"공동해손의 분담액을 정함에 있어서는 선박의 가액은 도달의 때와 곳의 가액으로 하고, 적하의 가액은 양륙의 때와 곳의 가액으로 한다. 다만, 적하에 관하여는 그 가액 중에서 멸실로 인하여 지급을 면하게 된 운임과 그 밖의 비용을 공제하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-3","t":"선박에 비치한 무기, 선원의 급료, 선원과 여객의 식량ㆍ의류는 보존된 경우에는 그 가액을 공동해손의 분담에 산입하지 아니하고, 손실된 경우에는 그 가액을 공동해손의 액에 산입한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-4","t":"속구목록에 기재하지 아니한 속구, 선하증권이나 그 밖에 적하의 가격을 정할 수 있는 서류 없이 선적한 하물 또는 종류와 가액을 명시하지 아니한 화폐나 유가증권과 그 밖의 고가물은 보존된 경우에는 그 가액을 공동해손의 분담에 산입하고, 손실된 경우에는 그 가액을 공동해손의 액에 산입하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-5","t":"공동해손으로 인하여 생긴 채권 및 상법 제870조에 따른 구상채권은 그 계산이 종료한 날부터 2년 이내에 재판상 청구가 없으면 소멸한다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-1","t":"상법상 책임이 제한되는 주체는 선박소유자뿐만 아니라 선체용선자도 포함된다.","ox":"O","m":"①","c":"A","tp":"선박소유자의 책임제한"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-2","t":"선박소유자의 책임제한은 계약책임에 대해서만 적용될 뿐이고 불법행위책임에는 적용이 없다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-3","t":"피용자에게 고의 또는 무모한 행위가 있었다고 하더라도 선박소유자 본인에게 그와 같은 고의 또는 무모한 행위가 없는 이상 선박소유자는 상법 제769조 본문에 의하여 책임을 제한할 수 있다.","ox":"O","m":"③","c":"A","tp":"선박소유자의 책임제한"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-4","t":"법인의 대표기관뿐만 아니라 적어도 법인의 내부적 업무분장에 따라 당해 법인의 관리 업무 전부 또는 특정 부분에 관하여 대표기관에 갈음하여 사실상 회사의 의사결정 등 권한을 행사하는 사람의 행위는 그가 이사회의 구성원 또는 임원이 아니더라도 선박소유자 등 책임제한 배제 규정을 적용할 때 책임제한 주체 자신의 행위로 보아야 한다.","ox":"O","m":"④","c":"A","tp":"선박소유자의 책임제한"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-5","t":"선박소유자 등에게 손해배상 등을 청구하는 소송이 제기된 경우 책임제한의 배제를 주장하는 채권자가 책임제한 배제사유의 존재에 대한 증명책임을 부담하지만, 선박소유자 책임제한절차에서는 절차개시를 신청하는 신청인이 책임제한 배제사유의 부존재에 대하여 소명하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"선박소유자의 책임제한"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50-1","t":"상법 제735조의3에 규정된 단체보험에 해당하려면 단체가 규약에 따라 보험계약을 체결하여야 하고, 단순히 다수의 회사 직원을 피보험자로 하여 보험계약이 체결되었다고 하여 위 조항상의 단체보험이 되는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50-2","t":"상법 제735조의3에서 ‘규약’의 의미는 보험가입에 관하여 대표자가 구성원을 위하여 일괄하여 계약을 체결할 수 있다는 취지를 담고 있는 것만으로는 충분하지 않고 반드시 당해 보험가입과 관련한 상세한 사항까지 단체내부의 협정에 규정되어 있어야 한다.","ox":"X","m":"②","c":"A","tp":"단체보험"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50-3","t":"단체보험은 타인의 생명보험임에도 불구하고 계약체결 시 타인의 서면 동의를 받지 않아도 된다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50-4","t":"단체보험에서 보험계약자는 단체의 구성원인 피보험자를 보험수익자로 하여 타인을 위한 보험계약으로 체결할 수도 있고 보험계약자 자신을 보험수익자로 하여 자기를 위한 보험계약으로 체결할 수도 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50-5","t":"보험계약에서 보험계약자가 피보험자 또는 그 상속인이 아닌 자를 보험수익자로 지정할 때에는 단체의 규약에서 명시적으로 정하는 경우 외에는 그 피보험자의 상법 제731조 제1항에 따른 서면 동의를 받아야 한다.","ox":"O","m":"⑤","c":"A","tp":"단체보험"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-1","t":"해상운송인의 송하인 또는 수하인에 대한 채권 및 채무는 그 청구원인의 여하에 불구하고 운송인이 수하인에게 운송물을 인도한 날부터 또는 인도할 날부터 2년 이내에 재판상 청구가 없으면 소멸한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-2","t":"해상운송인의 송하인이나 수하인에 대한 권리·의무에 관한 소멸기간은 소멸시효에 해당하고, 그 기산일인 ‘운송물을 인도할 날’이란 통상 운송계약이 그 내용에 좇아 이행되었으면 인도가 행하여져야 했던 날을 의미한다. 이 경우 운송물이 물리적으로 멸실되는 경우뿐만 아니라 운송인이 운송물의 인도를 거절하거나 운송인의 사정으로 운송이 중단되는 등의 사유로 운송물이 인도되지 않은 경우에도 ‘운송물을 인도할 날’을 기준으로 하여 소멸기간이 도과하였는지를 판단하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-3","t":"상법 제814조 제1항에 따른 해상운송인의 송하인이나 수하인에 대한 권리·의무에 관한 소멸기간은 해상운송인의 송하인 또는 수하인에 대한 채권 및 채무의 청구원인이 계약인 경우에 적용되고, 불법행위인 경우에는 적용되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-4","t":"복합운송주선인인 甲 주식회사가 운송계약에 따라 해상운송인인 乙 외국회사에 운송을 의뢰한 화물은 폐기물처리업자가 수출 화물인 것처럼 가장하여 반출하려 한 폐기물이었는데, 이를 甲 회사 및 甲 회사가 지정한 수하인이 수령하지 않아 컨테이너 초과사용료, 터미널 보관료 등 손해가 계속 발생하자, 乙 회사가 화물 도착 후 2년이 지난 시점에 甲 회사를 상대로 손해배상청구소송을 제기한 경우, 위 소는 상법 제814조 제1항에서 정한 소멸기간이 지난 후에 제기된 것이어서 부적법하다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-5","t":"상법 제814조 제1항에서 정한 소멸기간이 지난 뒤에 그 기간 경과의 이익을 받는 당사자가 기간이 지난 사실을 알면서도 기간 경과로 인한 법적 이익을 받지 않겠다는 의사를 표시한 경우에는, 권리소멸의 이익을 포기하였다고 인정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"해상운송인"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-1","t":"하자보수보증계약의 보증기간을 주계약의 하자담보책임기간과 동일하게 정하였는데, 하자담보책임기간 내에 발생한 하자에 대하여 보증기간이 종료된 후 보증사고가 발생한 경우, 보증금청구권의 소멸시효 기산점은 보증사고가 발생한 때이다.","ox":"O","m":"①","c":"A","tp":"보증보험"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-2","t":"보증보험은 보험계약자의 채무불이행으로 피보험자가 입게 될 손해의 전보를 보험자가 인수하는 손해보험으로서 형식적으로는 채무자의 채무불이행을 보험사고로 하는 보험계약이나 실질적으로는 보증의 성격을 가지고 보증계약과 같은 효과를 목적으로 한다. 따라서 보증보험은 보증의 성격과 보험의 성격을 함께 가지고 그 성질에 반하지 않는 범위에서 보험과 보증의 규정이 모두 적용된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-3","t":"보증보험계약이 체결된 후 보험금이 아직 지급되지 않은 상태에서 주계약의 당사자인 보험계약자와 피보험자 사이에 주계약에 따른 채무의 존부와 범위에 관하여 다툼이 있는 경우, 보험계약자가 피보험자를 상대로 주계약에 따른 채무 부존재 확인을 구하는 소송을 제기하여 승소판결을 받더라도 그 승소판결의 기판력이 보험계약자와 보험자 사이의 법률관계 및 보험자와 피보험자 사이의 법률관계에 미치지 못하므로, 보험계약자는 피보험자를 상대로 주계약에 따른 채무부존재의 확인을 구할 이익이 없다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-4","t":"보증보험계약에서 이행을 담보하는 주계약상의 채무가 확정되기 전에 구상채무의 보증인이 적법하게 보증계약을 해지한 경우, 구체적인 보증채무가 발생하기 전에 보증계약관계가 종료되어 구상채무의 보증인이 보증책임을 면한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-5","t":"보증보험회사는 보증보험계약을 체결함에 있어서 일반적으로 보증대상인 주계약의 부존재나 무효 여부 등에 관하여 조사·확인할 의무가 없으나, 보증보험청약서 등 보험계약자가 제출하는 서류에 보증대상인 주계약의 부존재나 무효 등을 의심할만한 점이 발견되는 등의 특별한 사정이 있는 경우에는 위와 같은 조사·확인 의무가 면제되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-1","t":"보험계약은 당사자 일방이 약정한 보험료를 지급하고, 상대방이 재산 또는 생명이나 신체에 관하여 불확정한 사고가 생길 경우에 일정한 보험금액 기타의 급여를 지급할 것을 약정함으로써 효력이 생기는 계약으로, 계약 내용은 미리 공인·심사된 보험약관의 규정에 국한되어 인정되고, 당사자가 특별히 보험약관과 다른 사항에 관하여 합의한 내용의 효력은 인정되지 아니한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-2","t":"보험계약의 존속 중에 당사자 일방의 부당한 행위 등으로 인하여 계약의 기초가 되는 신뢰관계가 파괴되어 계약의 존속을 기대할 수 없는 중대한 사유가 있는 때에는 상대방은 그 계약을 해지함으로써 장래에 향하여 그 효력을 소멸시킬 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-3","t":"보험계약이 당사자 일방의 부당한 행위로 계약의 기초가 되는 신뢰관계가 파괴되어 상대방이 그 계약을 해지하는 경우, 신뢰관계를 파괴하는 당사자의 부당한 행위가 해당 보험계약의 주계약이 아닌 특약에 관한 것이라 하더라도 그 행위가 중대하여 이로 인해 보험계약 전체가 영향을 받고 계약 자체를 유지할 것을 기대할 수 없다면, 특별한 사정이 없는 한 해지의 효력은 해당 보험계약 전부에 미친다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-4","t":"보험금청구권의 소멸시효는 특별한 다른 사정이 없는 한 보험사고가 발생한 때부터 진행하는 것이 원칙이지만, 객관적으로 보아 보험사고가 발생한 사실을 확인할 수 없는 사정이 있는 경우에는 보험금청구권자가 보험사고의 발생을 알았거나 알 수 있었던 때부터 보험금청구권의 소멸시효가 진행한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-5","t":"보험사고란 보험계약에서 보험자의 보험금 지급책임을 구체화하는 불확정한 사고를 의미하는 것으로서, 계약이행보증보험에 있어서 보험사고가 구체적으로 무엇인지는 당사자 사이의 약정으로 계약내용에 편입된 보험약관과 보험약관이 인용하고 있는 보험증권 및 주계약의 구체적인 내용 등을 종합하여 결정하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36-1","t":"보험계약자는 계약체결 후 지체 없이 보험료의 전부 또는 제1회 보험료를 지급하여야 하며, 보험계약자가 이를 지급하지 아니하는 경우에는 다른 약정이 없는 한 계약성립 후 2월이 경과하면 보험자는 그 계약을 해지할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법상 보험료"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36-2","t":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간 내에 지급되지 아니한 때에는 그 계약을 해지할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 보험료"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36-3","t":"특정한 타인을 위한 보험의 경우에 보험계약자가 보험료의 지급을 지체한 때에는 보험자는 그 타인에게도 상당한 기간을 정하여 보험료의 지급을 최고한 후가 아니면 그 계약을 해제 또는 해지하지 못한다.","ox":"O","m":"③","c":"A","tp":"상법상 보험료"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36-4","t":"보험자는 계속보험료 지급의 연체를 이유로 상법 제650조 제2항에 의하여 보험계약을 해지하였어도 계속보험료의 연체 이전에 발생한 보험사고에 대하여 지급한 보험금의 반환을 구할 수 없다.","ox":"O","m":"④","c":"A","tp":"상법상 보험료"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36-5","t":"계속보험료가 약정한 시기에 지급되지 아니한 때 일정한 유예기간이 경과하면 보험자의 최고나 해지의 의사표시 없이 자동적으로 계약의 효력이 상실된다는 내용의 약관은 무효이다.","ox":"O","m":"⑤","c":"A","tp":"상법상 보험료"},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39-1","t":"손해보험은 피보험자의 ‘물건이나 재산’에 생기는 사고에 대비하는 것이라는 점에서, 피보험자의 ‘생명이나 신체’에 생기는 사고에 대비하는 인보험과 구별된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39-2","t":"손해보험의 보험사고에 관하여 동시에 불법행위나 채무불이행에 기한 손해배상책임을 지는 제3자가 있어 피보험자가 그를 상대로 손해배상청구를 하는 경우에, 피보험자는 보험자로부터 수령한 보험금으로 전보되지 않고 남은 손해에 관하여 제3자를 상대로 그의 배상책임을 이행할 것을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39-3","t":"중복보험의 각 보험자는 각자의 보험금액의 한도에서 각자의 보험금액의 비율에 따라 연대책임을 지는데, 여기서 중복보험이라 함은 동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결되고 그 보험금액의 총액이 보험가액을 초과하는 경우를 말하므로 보험계약의 목적 즉 피보험이익이 다르면 중복보험으로 되지 않는다.","ox":"O","m":"③","c":"A","tp":"손해보험"},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39-4","t":"보험계약자와 피보험자는 손해의 방지와 경감을 위하여 노력하여야 한다(상법 제680조 제1항 전문). 보험계약자와 피보험자가 고의 또는 중대한 과실로 손해방지의무를 위반한 경우에는 보험자는 손해방지의무 위반과 상당인과관계가 있는 손해액에 대하여 배상을 청구하거나 지급할 보험금과 상계하여 이를 공제한 나머지 금액만을 보험금으로 지급할 수 있으나, 경과실로 위반한 경우에는 그러하지 아니하다.","ox":"O","m":"④","c":"A","tp":"손해보험"},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39-5","t":"상법 제682조에 따르면 손해가 제3자의 행위로 인하여 발생한 경우에 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 그 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득하는데, 여기서 ‘제3자의 행위’란 ‘피보험이익에 대하여 손해를 일으키는 행위’를 뜻하는 것으로서 고의 또는 과실에 의한 행위만을 의미한다.","ox":"X","m":"⑤","c":"A","tp":"손해보험"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50-1","t":"학교배상책임공제계약의 피공제자인 중학생 甲이 축구 동아리 활동을 위해 학교 밖 축구장으로 이동하던 중 인도를 지나가던 피해자 乙을 제대로 보지 못하고 부딪히는 사고가 발생하여 乙이 뒤로 넘어지면서 중증 뇌손상 등을 입고 치료 중 사망한 경우, 학교안전공제중앙회가 학교배상책임공제에 따라 피해자 乙에게 공제금을 지급하였다면, 가해자인 피공제자 甲의 책임보험자에게 피해자의 보험금 직접청구권을 대위행사할 수 있다.","ox":"X","m":"①","c":"A","tp":"중복보험"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50-2","t":"건물의 임차인이 임차건물을 보험목적으로 하여 가입한 화재보험과 건물의 소유자가 건물을 보험목적으로 하여 가입한 화재보험이 소유자를 피보험자로 하는 중복보험의 관계에 있는 경우, 임차인의 책임 있는 사유로 임차건물에 화재가 발생하여 소유자에게 보험금을 지급한 소유자 화재보험의 보험자가 임차인 화재보험의 보험자로부터 중복보험 분담금을 지급받았더라도 임차인에 대하여 보험자대위에 의한 청구권을 행사할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50-3","t":"사용자의 보험자가 피해자인 제3자에게 사용자와 피용자의 공동불법행위로 인한 손해배상금을 보험금으로 모두 지급하여 피용자의 보험자가 면책됨으로써 사용자의 보험자가 피용자의 보험자에게 부담하여야 할 부분에 대하여 직접 구상권을 행사하는 경우, 피용자의 보험자는 사용자의 보험자에 대하여 신의칙상 상당하다고 인정되는 한도 내에서만 사용자의 구상권이 인정된다는 등의 구상권 제한의 법리를 주장할 수 없다.","ox":"O","m":"③","c":"A","tp":"중복보험"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50-4","t":"하나의 사고에 관하여 여러 개의 무보험자동차에 의한 상해담보특약이 체결되고 그 보험금액의 총액이 피보험자가 입은 손해액을 초과하는 때에는 손해보험에 관한 상법 제672조 제1항이 준용되어 보험자는 각자의 보험금액의 한도에서 연대책임을 지고, 이 경우 각 보험자 사이에서는 각자의 보험금액의 비율에 따른 보상책임을 진다. 이때 각 보험자는 특별한 사정이 없는 한 보험금 지급채무에 대하여 부진정연대관계에 있다.","ox":"O","m":"④","c":"A","tp":"중복보험"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50-5","t":"제1 책임보험계약과 제2 책임보험계약의 피보험자 甲과 제2 책임보험계약의 피보험자 乙의 공동불법행위로 피해자 丙이 사망하는 보험사고가 발생하여 제2 책임보험계약의 보험자가 丙에 대한 보험금 지급으로 甲, 乙 공동의 면책을 얻게 하였는데 지급한 보험금 전액이 중복보험에 해당하는 경우, 제2 책임보험계약의 보험자가 제1 책임보험계약의 보험자를 상대로 행사할 수 있는 구상권의 범위는 제1 책임보험계약 보험자의 중복보험 부담 부분 중 甲의 과실비율 상당액이다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-1","t":"일반적으로 보험모집인은 독자적으로 보험자를 대리하여 보험계약을 체결할 권한이 없을 뿐만 아니라 고지 내지 통지를 수령할 권한도 없다.","ox":"O","m":"①","c":"A","tp":"보험계약자 또는 피보험자의 고지의무"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-2","t":"보험자가 생명보험계약을 체결함에 있어 다른 보험계약의 존재 여부를 청약서에 기재하여 질문하였다면 이는 그러한 사정을 보험계약을 체결할 것인지의 여부에 관한 판단자료로 삼겠다는 의사를 명백히 한 것으로 볼 수 있고, 그러한 경우에는 다른 보험계약의 존재 여부가 고지의무의 대상이 된다.","ox":"O","m":"②","c":"A","tp":"보험계약자 또는 피보험자의 고지의무"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-3","t":"보험자가 다른 보험계약의 존재 여부에 관한 고지의무 위반을 이유로 보험계약을 해지하려면 보험계약자 또는 피보험자가 다른 보험계약의 존재를 알고 있는 외에 그것이 고지를 요하는 중요한 사항에 해당한다는 사실을 알고도, 또는 중대한 과실로 알지 못하여 고지의무를 다하지 아니한 사실을 입증하여야 한다.","ox":"O","m":"③","c":"A","tp":"보험계약자 또는 피보험자의 고지의무"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-4","t":"상법 제672조 제2항에서 손해보험에 있어서 동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약을 체결하는 경우에는 보험계약자는 각 보험자에 대하여 각 보험계약의 내용을 통지하도록 규정하고 있으므로, 중복보험을 체결한 사실은 상법 제651조의 고지의무의 대상이 되는 중요한 사항에 해당된다.","ox":"X","m":"④","c":"A","tp":"보험계약자 또는 피보험자의 고지의무"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-5","t":"보험자가 보험약관의 명시·설명의무에 위반하여 보험계약을 체결한 때에는 그 약관의 내용을 보험계약의 내용으로 주장할 수 없으므로, 보험계약자나 그 대리인이 그 약관에 규정된 고지의무를 위반하였다 하더라도 이를 이유로 보험계약을 해지할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"보험계약자 또는 피보험자의 고지의무"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41","t":"손해보험 등에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"손해보험 등에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.손해보험에 있어 당사자간에 보험가액을 정하지 아니한 때에는 보험계약 체결 시의 가액을 보험가액으로 한다.\nㄴ.초과보험인지 여부는 원칙적으로 보험계약 당시의 가액을 기준으로 판단한다.\nㄷ.보험계약자의 사기로 인하여 초과보험계약이 체결된 경우에 그 보험계약은 무효가 되나, 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다.\nㄹ.일부보험의 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상할 책임을 지는 것이 원칙이나, 당사자간에 다른 약정이 있는 때에는 보험자는 보험금액의 한도 내에서 그 손해를 보상할 책임을 진다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47-1","t":"보험계약이 체결되기 전에 보험사고가 이미 발생하였을 경우라면, 보험계약의 당사자 쌍방 및 피보험자가 이를 알지 못하였다고 하더라도 그 보험계약은 보험사고가 불확정한 것이어야 한다는 보험의 본질에 비추어 무효이다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47-2","t":"상법 제652조 제2항에 따라 보험자가 피보험자 등으로부터 사고발생의 위험이 변경 또는 증가하였다는 통지를 받고 이를 이유로 보험계약을 해지하는 경우, 보험약관에서 미경과기간에 대한 보험료를 반환하도록 정하고 있다면 그 보험약관은 유효하다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47-3","t":"보험회사 또는 보험모집종사자가 설명의무를 위반하여 고객이 보험계약의 중요사항에 관하여 제대로 이해하지 못한 채 착오에 빠져 보험계약을 체결한 경우, 그러한 착오가 동기의 착오에 불과하다고 하더라도 그러한 착오를 일으키지 않았더라면 보험계약을 체결하지 않았거나 아니면 적어도 동일한 내용으로 보험계약을 체결하지 않았을 것이 명백하다면, 위와 같은 착오는 보험계약의 내용의 중요부분에 관한 것에 해당하므로 이를 이유로 보험계약을 취소할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47-4","t":"약관에 정하여진 사항이라고 하더라도 거래상 일반적이고 공통된 것이어서 보험계약자가 별도의 설명 없이도 충분히 예상할 수 있었던 사항이거나, 이미 법령에 의하여 정하여진 것을 되풀이하거나 부연하는 정도에 불과한 사항이라면, 그러한 사항까지 보험자에게 명시·설명의무가 있다고는 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47-5","t":"통신판매 방식으로 체결된 상해보험계약에서 보험자가 약관 내용의 개요를 소개한 것이라는 내용과 면책사고에 해당하는 경우를 확인하라는 내용이 기재된 안내문과 청약서를 보험계약자에게 우송한 것만으로는 보험자의 면책약관에 관한 설명의무를 다한 것으로 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25","t":"제3자에 대한 보험대위(상법 제682조)에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"제3자에 대한 보험대위(상법 제682조)에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.상법 제682조 제1항 본문은 “손해가 제3자의 행위로 인하여 발생한 경우에 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 그 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다.”고 규정하고 있다. 여기서 말하는 ‘제3자의 행위’란 ‘피보험이익에 대하여 손해를 일으키는 행위’를 뜻하는 것으로서 고의 또는 과실에 의한 행위에 한하고 제3자에게 귀책사유가 없다면 위 조항이 적용되지 않는다.\nㄴ.피보험자동차를 무면허로 운전할 경우 보험자를 면책시키는 약관조항이 부착된(무면허운전 면책약관부) 보험계약에서 무면허 운전자가 피보험자의 동거가족으로서 피보험자동차를 운전한 경우에는 특별한 사정이 없는 한 무면허 운전자는 상법 제682조 소정의 제3자의 범위에 포함되지 않는다. 따라서 피보험자의 아들이 무면허로 피보험자동차를 운전하여 피해자들을 들이받아 상해를 입게 한 후 보험자가 피해자들에게 손해배상하였다고 하더라도 보험자는 피보험자의 아들을 상대로 상법 제682조에 따른 보험자대위를 행사할 수 없다.\nㄷ.타인을 위한 손해보험계약은 타인의 이익을 위한 계약으로서 그 타인(피보험계약자)의 이익이 보험의 목적이 되는 것이므로, 타인을 위하여 자신의 명의로 손해보험계약을 체결하여 보험자에게 보험료를 납입하는 보험계약자는 당연히 제3자의 범주에서 제외되는 것으로 해석하여야 한다.\nㄹ.상법 제682조에서 정한 제3자에 대한 보험자대위가 인정되기 위하여는 보험자가 피보험자에게 보험금을 지급할 책임이 있는 경우이어야 한다. 보험자가 보험약관에 정하여져 있는 중요한 내용에 해당하는 면책약관에 대한 설명의무를 위반하여 약관의 규제에 관한 법률 제3조 제4항에 따라 해당 면책약관을 계약의 내용으로 주장하지 못하고 보험금을 지급하게 되었더라도, 이는 보험자가 피보험자에게 보험금을 지급할 책임이 있는 경우에 해당하므로 보험자는 보험자대위를 할 수 있다.\nㅁ.공동불법행위자 중 1인의 보험자가 피해자에게 손해배상금을 보험금으로 모두 지급함으로써 공동면책되었다면, 피보험자인 공동불법행위자는 다른 공동불법행위자들을 상대로 그들의 부담 부분에 대하여 구상권을 행사할 수 있을 뿐만 아니라, 상법 제724조 제2항에 따라 다른 공동불법행위자들의 부담 부분에 대한 구상권을 그들의 보험자들에게 직접 행사할 수 있고, 손해배상금을 지급한 보험자는 상법 제682조의 보험자대위의 법리에 따라 자신의 피보험자가 다른 공동불법행위자들의 보험자들에 대하여 갖는 직접적인 구상권을 취득하여 그 보험자들에게 행사할 수 있다. 이같이 보험자대위의 법리에 따라 취득한 피보험자의 위 보험자들에 대한 구상권의 소멸시효기간은 상사채권과 같이 5년이고, 그 기산점은 구상권이 발생한 시점, 즉 구상권자가 현실로 피해자에게 손해배상금을 지급한 때이다.","o":["ㄱ, ㄷ, ㅁ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㅁ","ㄴ, ㄹ, ㅁ","ㄱ, ㄷ, ㄹ"],"a":1}},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-1","t":"선박우선특권자는 그 우선특권 있는 채권에 대한 집행력 있는 집행권원을 요함이 없이 선박을 물적 담보로 하여 특별한 사정이 없는 한 언제든지 경매청구를 할 수 있고, 매각대금에 대하여 우선변제권을 행사할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-2","t":"선박에 대한 압류의 효력이 발생한 때부터 매각대금 지급 시까지의 기간 동안에 선박의 정박을 위하여 발생한 정박료는 상법 제777조 제1항 제1호 소정의 선박우선특권에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-3","t":"선박우선특권자는 그 피담보채권이 변제기에 있는 한, 언제든지 우선특권의 목적물에 대하여 우선특권을 행사할 수 있고 반드시 채권의 발생과 동시에 행사하여야 한다거나 항해 종료 직후 곧바로 행사할 필요는 없다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-4","t":"수회의 항해에 관한 채권의 우선특권이 경합하는 때에는 후의 항해에 관한 채권이 전의 항해에 관한 채권에 우선한다.","ox":"O","m":"④","c":"A","tp":"선박우선특권"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-5","t":"선박우선특권은 그 채권이 생긴 날부터 1년 이내에 실행하지 아니하면 소멸한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37-1","t":"상법 제731조 제1항을 위반하여 피보험자의 서면 동의 없이 타인의 사망을 보험사고로 하는 보험계약을 체결한 자가 스스로가 무효를 주장하는 것은 신의성실 또는 금반언의 원칙에 반한다.","ox":"X","m":"①","c":"A","tp":"생명보험"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37-2","t":"타인의 사망을 보험사고로 하는 보험계약에는 피보험자의 동의를 얻어야 한다는 상법 제731조 제1항의 규정은 강행법규로 보아야 하므로 피보험자의 동의는 보험계약의 효력발생 요건이 된다.","ox":"O","m":"②","c":"A","tp":"생명보험"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37-3","t":"상법 제731조 제1항이 타인의 사망을 보험사고로 하는 보험계약의 체결 시 타인의 서면동의를 얻도록 규정한 것은 동의의 시기와 방식을 명확히 함으로써 분쟁의 소지를 없애려는 데 취지가 있으므로, 피보험자인 타인의 동의는 각 보험계약에 대하여 개별적으로 서면에 의하여 이루어져야 하고 포괄적인 동의 또는 묵시적이거나 추정적 동의만으로는 부족하다.","ox":"O","m":"③","c":"A","tp":"생명보험"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37-4","t":"상법 제731조 제1항에 의하면 타인의 생명보험에서 피보험자가 서면으로 동의의 의사표시를 하여야 하는 시점은 보험계약 체결 시까지이고, 이는 강행규정으로서 이에 위반한 보험계약은 무효이므로, 피보험자가 이미 무효로 된 보험계약을 추인하였다고 하더라도 보험계약이 유효로 될 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37-5","t":"보험수익자 변경권은 형성권으로서 보험계약자가 보험자나 보험수익자의 동의를 받지 않고 자유로이 행사할 수 있고, 보험수익자 변경의 의사표시가 보험자에게 도달하지 않더라도 보험수익자 변경의 효과가 발생한다. 다만 보험계약자는 보험수익자를 변경한 후 보험자에 대하여 이를 통지하지 않으면 보험자에게 대항할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"생명보험"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-1","t":"보험금청구권자는 손해보험의 경우 피보험자이고 인보험의 경우 보험수익자인데, 보험사고 발생 전 보험금청구권자가 사망하면 손해보험의 경우 피보험자의 상속인이 보험금청구권을 가지고 인보험의 경우 보험계약자가 보험수익자를 다시 지정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-2","t":"보험금청구권의 소멸시효는 보험사고가 발생한 때로부터 진행하고, 피보험자와 보험자 사이의 보험금 지급기한 유예 합의는 보험금지급청구권에 관한 소멸시효의 이익을 미리 포기하는 것에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-3","t":"보험자는 보험금액의 지급에 관하여 약정기간이 없는 경우에는 보험사고발생통지를 받은 후 지체 없이 지급할 보험금액을 정하고 그 정하여진 날부터 10일 내에 보험금을 지급하여야 한다.","ox":"O","m":"③","c":"A","tp":"보험금 청구"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-4","t":"보험급여는 금전 외에도 채무면제, 현물급부, 용역제공 등으로 제공될 수 있고, 인보험의 경우 약정에 따라 분할지급 할 수도 있다.","ox":"O","m":"④","c":"A","tp":"보험금 청구"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-5","t":"자동차손해배상 보장법 제40조상의 압류·양도금지 규정은 강행규정이지만 피해자를 치료한 의료기관이 피해자에 대한 진료비 청구권에 기하여 피해자의 보험사업자 등에 대한 직접청구권을 압류하는 것까지 금지하는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"보험금 청구"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45-1","t":"손해보험에 있어서 보험사고의 발생에 의하여 피보험자가 불이익을 받게 될 이해관계의 평가액인 보험가액은 보험목적의 객관적인 기준에 따라 평가되어야 하나, 보험사고가 발생한 후 그 평가를 둘러싸고 보험자와 피보험자 사이에 분쟁이 발생하는 것을 미리 예방하고 신속한 보상을 할 수 있도록 하기 위하여 상법 제670조에서 기평가보험에 있어 보험가액에 관한 규정을 두고 있다.","ox":"O","m":"①","c":"A","tp":"보험가액, 초과보험, 중복보험"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45-2","t":"상법 제669조 소정의 초과보험계약이라는 사유를 들어 보험가액의 제한 또는 보험계약의 무효를 주장하는 경우, 그 증명책임은 무효를 주장하는 보험자가 부담한다.","ox":"O","m":"②","c":"A","tp":"보험가액, 초과보험, 중복보험"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45-3","t":"상법 제672조 제2항에서 규정하는 통지의무의 해태로 인한 사기의 중복보험을 인정하기 위하여는 보험자가 통지의무가 있는 보험계약자 등이 통지의무를 이행하였다면 보험자가 그 청약을 거절하였거나 다른 조건으로 승낙할 것이라는 것을 알면서도 정당한 사유 없이 위법하게 재산상의 이익을 얻을 의사로 통지의무를 이행하지 않았음을 증명하여야 할 것이고, 단지 통지의무를 게을리 하였다는 사유만으로 사기로 인한 중복보험계약이 체결되었다고 추정할 수는 없다. 다만 중복보험계약 체결이 인정되기만 한다면 그 고지의무 해태를 이유로 상법 제651조(고지의무위반으로 인한 계약해지)에 따라 보험계약을 해지할 수 있는 것이다.","ox":"X","m":"③","c":"A","tp":"보험가액, 초과보험, 중복보험"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45-4","t":"수 개의 손해보험계약이 동시 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때에는 상법 제672조 제1항의 규정에 따라 보험자는 각자의 보험금액의 한도에서 연대책임을 지고 이 경우 각 보험자의 보상책임은 각자의 보험금액의 비율에 따르는 것이 원칙이라 할 것이나, 이러한 상법의 규정은 강행규정이라고 해석되지 아니하므로, 각 보험계약의 당사자는 각개의 보험계약이나 약관을 통하여 중복보험에 있어서의 피보험자에 대한 보험자의 보상책임 방식이나 보험자들 사이의 책임 분담방식에 대하여 상법의 규정과 다른 내용으로 규정할 수 있다.","ox":"O","m":"④","c":"A","tp":"보험가액, 초과보험, 중복보험"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45-5","t":"중복보험이라 함은 동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결되고 그 보험금액의 총액이 보험가액을 초과하는 경우를 말하므로 보험계약의 목적 즉 피보험이익이 다르면 중복보험으로 되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"보험가액, 초과보험, 중복보험"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-1","t":"보험계약에 관하여 설명의무의 대상이 되는 ‘중요한 내용’이란 사회통념에 비추어 고객이 계약체결 여부나 대가를 결정하는 데 직접적인 영향을 미칠 수 있는 사항을 말하고, 약관조항 중에서 무엇이 중요한 내용에 해당하는지는 일률적으로 말할 수 없으며, 구체적인 사건에서 개별적 사정을 고려하여 판단하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-2","t":"연금보험계약에서 향후 지급받는 연금액은 당해 보험계약 체결 여부에 영향을 미치는 중요한 사항이므로, 연금보험계약을 체결할 때 보험자 등은 보험계약자 등에게 수학식에 의한 복잡한 연금계산방법 자체를 설명하지는 못한다고 하더라도 대략적인 연금액과 함께 그것이 변동될 수 있는 것이면 그 변동 가능성에 대하여 명시⋅설명할 의무가 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-3","t":"해당 연금보험상품의 특성 또는 전체적인 약관 내용에 비추어 보험계약자 등이 향후 지급받는 연금액의 주요 산출기준을 예상할 수 없는 경우 또는 보험계약자 등이 그 내용을 오인할 여지가 있어 계약체결 여부나 대가를 결정하는 데 직접적인 영향을 받을 수 있는 경우에는, 보험자 등은 보험계약자가 예측하지 못한 불이익을 받게 되는 것을 방지하기 위해 그 연금액의 주요 산출기준에 대하여도 명시⋅설명하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-4","t":"보험계약의 기초가 되는 신뢰관계가 파괴되어 보험계약의 존속을 기대할 수 없는 중대한 사유가 있다고 인정된다면 보험자는 보험계약을 해지할 수 있으나, 이러한 해지권은 신의성실의 원칙을 정한 민법 제2조에 근거한 것이므로, 보험자에게 사전에 설명할 의무가 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-5","t":"보증보험계약이 실질적으로는 보증의 성격을 가지고 보증계약과 같은 효과를 목적으로 하는 것이라 할지라도 그 보상은 보험약관이 정하는 바에 따라 그 보험계약금액의 범위 내에서 보상하는 것이므로, 피보험자가 보험약관이 정한 집행권원 없이도 보험자에 대하여 직접청구권을 취득한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-1","t":"보험계약자는 상법 제651조에 따라 중요한 사항을 보험자에게 고지를 해야 하는데, 손해보험의 경우 중복보험을 체결한 사실은 상법 제651조의 고지의무의 대상이 되는 중요한 사항에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-2","t":"보험금청구권의 소멸시효는 특별한 다른 사정이 없는 한 원칙적으로 보험사고가 발생한 때로부터 진행하고, 다만 보험사고가 발생한 것인지의 여부가 객관적으로 분명하지 아니하여 보험금청구권자가 과실 없이 보험사고의 발생을 알 수 없었던 경우에는, 보험금청구권자가 보험사고의 발생을 알았거나 알 수 있었던 때로부터 보험금청구권의 소멸시효가 진행한다.","ox":"O","m":"②","c":"A","tp":"보험계약"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-3","t":"보험계약자가 다수의 보험계약을 통하여 보험금을 부정취득할 목적으로 보험계약을 체결한 경우 보험계약은 민법 제103조에서 정한 선량한 풍속 기타 사회질서에 반하여 무효이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-4","t":"보험자가 보험약관의 명시·설명의무를 위반하여 보험계약을 체결한 때에는 그 약관의 내용을 보험계약의 내용으로 주장할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-5","t":"보험약관에 정하여진 사항이라고 하더라도 거래상 일반적이고 공통된 것이어서 보험계약자가 별도의 설명 없이도 충분히 예상할 수 있었던 사항이거나, 이미 법령에 의하여 정하여진 것을 되풀이하거나 부연하는 정도에 불과한 사항이라면, 그러한 사항에 관하여까지 보험자에게 명시·설명의무가 있다고는 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-1","t":"생명보험의 보험계약자는 보험수익자를 변경할 수 있는데, 이러한 보험수익자 변경권은 형성권으로서 보험계약자가 보험자나 보험수익자의 동의를 받지 않고 자유로이 행사할 수 있고 그 행사에 의해 변경의 효력이 즉시 발생한다. 다만 보험계약자는 보험수익자를 변경한 후 보험자에 대하여 이를 통지하지 않으면 보험자에게 대항할 수 없다.","ox":"O","m":"①","c":"A","tp":"인보험"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-2","t":"보험계약자가 타인의 생활상의 부양이나 경제적 지원을 목적으로 보험자와 사이에 타인을 보험수익자로 하는 생명보험이나 상해보험계약을 체결하여 보험수익자가 보험금을 지급받았는데, 보험계약이 무효인 것으로 판단이 되었다면, 보험자는 보험수익자를 상대로 이미 급부한 것의 반환을 구할 수 있다.","ox":"O","m":"②","c":"A","tp":"인보험"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-3","t":"피보험자의 동의가 없는 타인의 생명보험계약은 무효이나, 보험계약이 피보험자에게 지급할 퇴직금의 적립을 위하여 체결된 것이라면, 보험계약자가 피보험자의 사망을 초래할 우려가 없으므로, 이 경우에는 피보험자의 동의가 없어도 생명보험계약은 유효하다.","ox":"X","m":"③","c":"A","tp":"인보험"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-4","t":"사망을 보험사고로 한 보험계약에서는 사고가 보험계약자 또는 피보험자나 보험수익자의 중대한 과실로 인하여 발생한 경우에도 보험자는 보험금을 지급할 책임을 면하지 못한다.","ox":"O","m":"④","c":"A","tp":"인보험"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-5","t":"상해보험은 일반적으로 외래의 사고 이외에 피보험자의 질병 기타 기왕증이 공동 원인이 되어 상해에 영향을 미친 경우에도, 사고로 인한 상해와 그 결과인 사망이나 후유장해 사이에 인과관계가 인정되면, 특별한 사정이 없는 한 보험계약에서 정한 대로 보험금을 지급할 의무가 발생한다.","ox":"O","m":"⑤","c":"A","tp":"인보험"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-1","t":"보험계약당시에 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 인하여 중요한 사항을 고지하지 아니하거나 부실의 고지를 한 때에는 보험자는 그 사실을 안 날로부터 1월내에, 계약을 체결한 날로부터 3년내에 한하여 계약을 해지할 수 있다.","ox":"O","m":"①","c":"A","tp":"보험계약자 등의 고지의무"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-2","t":"보험자가 계약당시에 중요한 사항의 불고지 또는 부실고지 사실을 알았거나 중대한 과실로 인하여 알지 못한 때에는 고지의무 위반을 이유로 보험계약을 해지할 수 없다.","ox":"O","m":"②","c":"A","tp":"보험계약자 등의 고지의무"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-3","t":"보험계약자나 피보험자가 보험계약 당시에 보험자에게 고지할 의무를 지는 ‘중요한 사항’이란, 보험자가 보험사고의 발생과 그로 인한 책임부담의 개연율을 측정하여 보험계약의 체결 여부 또는 보험료나 특별한 면책조항의 부가와 같은 보험계약의 내용을 결정하기 위한 표준이 되는 사항으로서, 객관적으로 보험자가 그 사실을 안다면 그 계약을 체결하지 않든가 적어도 동일한 조건으로는 계약을 체결하지 않으리라고 생각되는 사항을 말한다.","ox":"O","m":"③","c":"A","tp":"보험계약자 등의 고지의무"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-4","t":"보험자가 고지의무 위반을 이유로 보험계약을 해지한 경우 보험사고가 발생하였더라도 보험자는 보험금을 지급할 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있으며, 이는 보험사고의 발생이 보험계약자가 불고지하였거나 부실고지한 사실에 의한 것이 아니라는 점이 증명된 경우에도 마찬가지이다.","ox":"X","m":"④","c":"A","tp":"보험계약자 등의 고지의무"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-5","t":"보험계약자의 고지의무 위반이 사기에 해당하는 경우에는 보험자는 상법의 규정에 의하여 계약을 해지할 수 있음은 물론, 민법의 일반원칙에 따라 그 보험계약을 취소할 수도 있다.","ox":"O","m":"⑤","c":"A","tp":"보험계약자 등의 고지의무"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36-1","t":"운송인은 여객의 사망 또는 신체의 상해로 인한 손해에 관하여는 그 손해의 원인이 된 사고가 항공기상에서 또는 승강을 위한 작업 중에 발생한 경우에만 책임을 진다.","ox":"O","m":"①","c":"A","tp":"항공운송"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36-2","t":"여객의 사망 또는 신체의 상해가 발생한 항공기사고의 경우에 운송인은 손해배상청구권자가 청구하면 지체 없이 선급금을 지급하여야 한다. 이 경우 선급금의 지급만으로 운송인의 책임이 있는 것으로 보지 아니한다.","ox":"O","m":"②","c":"A","tp":"항공운송"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36-3","t":"운송인은 여객의 연착으로 인한 손해에 대하여 책임을 진다. 다만, 운송인이 자신과 그 사용인 및 대리인이 손해를 방지하기 위하여 합리적으로 요구되는 모든 조치를 하였다는 것 또는 그 조치를 하는 것이 불가능하였다는 것을 증명한 경우에는 그 책임을 면한다.","ox":"O","m":"③","c":"A","tp":"항공운송"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36-4","t":"운송인은 위탁수하물의 멸실 또는 훼손으로 인한 손해에 대하여는 그 손해의 원인이 된 사실이 항공기상에서 또는 위탁수하물이 운송인의 관리하에 있는 기간 중에 발생한 경우에만 책임을 진다. 다만, 그 손해가 위탁수하물의 고유한 결함, 특수한 성질 또는 숨은 하자로 인하여 발생한 경우에는 그 범위에서 책임을 지지 아니한다.","ox":"O","m":"④","c":"A","tp":"항공운송"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36-5","t":"운송인은 수하물의 연착으로 인한 손해에 대하여 책임을 지고, 운송인이 자신과 그 사용인 및 대리인이 손해를 방지하기 위하여 합리적으로 요구되는 모든 조치를 하였다는 것 또는 그 조치를 하는 것이 불가능하였다는 것을 증명한 경우에도 그 책임을 면하지 못한다.","ox":"X","m":"⑤","c":"A","tp":"항공운송"},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42-1","t":"제3자의 직접청구권은 피보험자의 보험금청구권에 우선하는 것으로서, 보험자로서는 제3자가 피보험자로부터 배상을 받기 전에는 피보험자에 대한 보험금 지급으로 직접청구권을 갖는 피해자에게 대항할 수 없다.","ox":"O","m":"①","c":"A","tp":"상법 제724조의 직접청구권"},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42-2","t":"피해자에게 인정되는 직접청구권의 법적 성질은 법률에 의해 보험자가 피보험자의 피해자에 대한 손해배상채무를 병존적으로 인수한 것으로서 피해자가 보험자에 대하여 가지는 손해배상청구권이고 피보험자의 보험자에 대한 보험금청구권의 변형 내지는 이에 준하는 권리가 아니다.","ox":"O","m":"②","c":"A","tp":"상법 제724조의 직접청구권"},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42-3","t":"피해자의 직접청구권에는 상사법정이율이 적용된다.","ox":"X","m":"③","c":"A","tp":"상법 제724조의 직접청구권"},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42-4","t":"직접청구권에 기한 보험자의 피해자에 대한 손해배상채무와 피보험자의 피해자에 대한 손해배상채무는 연대채무관계에 있다.","ox":"O","m":"④","c":"A","tp":"상법 제724조의 직접청구권"},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42-5","t":"보험자가 피보험자에게 보험금을 지불하지 아니하고 직접 피해자에게 그 손해를 보상하였다면 이는 보험자가 병존적으로 인수하여 부담하는 피해자에 대한 자신의 손해배상채무를 변제할 의사로 한 것이라고 보아야 할 것이지, 타인의 채무인 피보험자의 피해자에 대한 손해배상채무를 변제할 의사로 한 것이라고 볼 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"상법 제724조의 직접청구권"}],"14":[{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-1","t":"주식회사의 이사가 다른 업무담당이사의 업무집행이 위법하다고 의심할 만한 사유가 있음에도 불구하고 이를 방치한 때에는 이사에게 요구되는 선관주의의무 내지 감시의무를 해태한 것이므로 이로 말미암아 회사가 입은 손해에 대하여 배상책임을 면할 수 없다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 이사의 책임"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-2","t":"주식회사의 이사가 임무를 수행하면서 법령을 위반한 행위를 한 때에는 그로 인하여 회사에 손해가 발생한 이상 특별한 사정이 없는 한 상법 제399조의 손해배상책임을 면할 수 없고, 법령을 위반한 행위에 대하여는 원칙적으로 경영판단의 원칙이 적용되지 않는다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 이사의 책임"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-3","t":"주식회사의 이사가 회사재산을 횡령하여 회사재산이 감소함으로써 회사가 손해를 입고 결과적으로 주주의 경제적 이익이 침해되는 손해와 같은 간접적인 손해는 상법 제401조 제1항에서 말하는 손해의 개념에 포함되지 아니하므로 이에 대하여는 위 법조항에 의한 손해배상을 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사 이사의 책임"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-4","t":"상법 제399조에 기한 이사의 회사에 대한 임무해태로 인한 손해배상책임은 일반불법행위 책임이 아니라 채무불이행 책임이므로 그 소멸시효 기간은 10년이나, 상법 제401조에 기한 이사의 제3자에 대한 손해배상책임은 일반불법행위 책임이므로 단기소멸시효를 규정한 민법 제766조 제1항이 적용된다.","ox":"X","m":"④","c":"A","tp":"상법상 주식회사 이사의 책임"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-5","t":"상법 제450조에 따른 이사의 책임 해제는 재무제표 등에 그 책임사유가 기재되어 정기총회에서 승인을 얻은 경우에 한정된다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사 이사의 책임"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-1","t":"주식회사의 주주는 대리인으로 하여금 의결권을 행사하게 할 수 있으나, 주주권행사를 포괄적으로 위임할 수 없으며 수임자는 위임자나 그 회사에 불리한 영향을 미칠 사항에 관하여 그 주주권을 행사할 수 없다.","ox":"X","m":"①","c":"A","tp":"주식회사 주주의 의결권행사"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-2","t":"대리인의 자격을 주주로 한정하는 취지의 정관규정은 무효이다.","ox":"X","m":"②","c":"A","tp":"주식회사 주주의 의결권행사"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-3","t":"주주가 2 이상의 의결권을 가지고 있는 때에는 이를 통일하여 행사하여야 한다.","ox":"X","m":"③","c":"A","tp":"주식회사 주주의 의결권행사"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-4","t":"의결권의 대리권을 증명하는 서면을 지참하지 아니한 경우라도 주주 또는 대리인이 다른 방법으로 위임장의 진정성 내지 위임사실을 증명할 수 있으면 대리권이 인정된다.","ox":"O","m":"④","c":"A","tp":"주식회사 주주의 의결권행사"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-5","t":"회사는 주주가 타인을 위하여 주식을 가지고 있는 경우에도 불통일행사를 거부할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"주식회사 주주의 의결권행사"},{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42-1","t":"결의취소의 판결은 제3자에 대하여는 그 효력이 없다.","ox":"X","m":"①","c":"A","tp":"상법상 주주총회결의의 하자를 다투는 소송"},{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42-2","t":"주주가 결의취소의 소를 제기한 때에는 법원은 회사의 청구에 의하여 상당한 담보를 제공할 것을 명할 수 있다. 그러나 그 주주가 이사 또는 감사인 때에는 그러하지 아니하다.","ox":"O","m":"②","c":"A","tp":"상법상 주주총회결의의 하자를 다투는 소송"},{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42-3","t":"결의취소의 소가 제기된 경우에 결의의 내용, 회사의 현황과 제반사정을 참작하여 그 취소가 부적당하다고 인정한 때에는 법원은 그 청구를 기각할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주주총회결의의 하자를 다투는 소송"},{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42-4","t":"주주가 총회의 결의에 관하여 특별한 이해관계가 있어 의결권을 행사할 수 없었던 경우에 결의가 현저하게 부당하고 그 주주가 의결권을 행사하였더라면 이를 저지할 수 있었을 때에는 그 주주는 그 결의의 날로부터 2월 내에 결의의 취소의 소 또는 변경의 소를 제기할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주주총회결의의 하자를 다투는 소송"},{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42-5","t":"결의한 사항이 등기된 경우에 결의취소의 판결이 확정된 때에는 본점과 지점의 소재지에서 등기하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주주총회결의의 하자를 다투는 소송"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-1","t":"회사는 주주총회의 결의로 회사를 대표할 이사를 선정하여야 한다. 그러나 정관으로 이사회에서 이를 선정할 것을 정할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-2","t":"대표이사는 그 업무집행으로 인하여 타인에게 손해를 가한 때에는 그 대표이사만 손해배상책임을 진다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-3","t":"주식회사가 甲, 乙 2명의 대표이사를 두면서 공동대표이사로 정한 경우 甲, 乙은 공동으로만 대표행위를 할 수 있고, 회사의 거래상대방도 甲, 乙 2명에 대하여 모두 의사표시를 하여야 효력이 있다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-4","t":"대표이사가 대표권의 범위 내에서 한 행위가 회사의 영리목적과 관계없이 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 남용한 것이라도, 그 행위의 상대방이 대표이사의 진의를 알았거나 알 수 있었을 경우가 아닌 한 회사의 행위로서 유효하다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-5","t":"甲이 乙 회사 모르게 임의로 乙 회사의 사장으로 행세한 경우에도 이를 신뢰한 제3자인 丙에 대하여는 乙 회사가 책임을 져야 한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-1","t":"상법 시행령으로 정하는 상장회사는 준법지원인을 1명 이상 두어야 한다.","ox":"O","m":"①","c":"A","tp":"상법 제542조의13에서 규정하고 있는 준법지원인"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-2","t":"준법지원인은 준법통제기준의 준수여부를 점검하여 그 결과를 이사회에 보고하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법 제542조의13에서 규정하고 있는 준법지원인"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-3","t":"준법지원인의 임기는 1년으로 하고, 준법지원인은 비상근으로 한다.","ox":"X","m":"③","c":"A","tp":"상법 제542조의13에서 규정하고 있는 준법지원인"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-4","t":"준법지원인은 선량한 관리자의 주의로 그 직무를 수행하여야 한다.","ox":"O","m":"④","c":"A","tp":"상법 제542조의13에서 규정하고 있는 준법지원인"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-5","t":"준법지원인은 재임중 뿐만 아니라 퇴임 후에도 직무상 알게 된 회사의 영업상 비밀을 누설하여서는 아니 된다.","ox":"O","m":"⑤","c":"A","tp":"상법 제542조의13에서 규정하고 있는 준법지원인"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-1","t":"발행주식 총수의 100분의 1 이상에 해당하는 주식을 가진 주주는 회사에 대하여 서면으로 이사의 책임을 추궁하는 소의 제기를 청구하였으나 회사가 그로부터 30일 내에 소를 제기하지 아니한 때에는 즉시 회사를 위하여 주주의 대표소송을 제기할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주주의 대표소송"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-2","t":"회사가 전(前) 이사들을 상대로 하는 주주의 대표소송에 참가하는 경우 회사를 대표하는 자는 대표이사가 아닌 감사이다.","ox":"X","m":"②","c":"A","tp":"상법상 주주의 대표소송"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-3","t":"주주의 대표소송 제기 후 제소한 주주의 보유주식이 발행주식 총수의 100분의 1 미만으로 감소하더라도(발행주식을 보유하지 아니하게 된 경우 제외) 그로 인해 소가 부적법하게 되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"상법상 주주의 대표소송"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-4","t":"주주의 대표소송을 제기한 주주는 주주대표소송에서 확정된 승소판결을 집행권원으로 하여 채무자를 상대로 강제집행신청을 하는 집행채권자가 될 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주주의 대표소송"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-5","t":"주주의 대표소송을 제기한 주주가 패소한 때에는 악의인 경우 외에는 회사에 대하여 손해를 배상할 책임이 없다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주주의 대표소송"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-1","t":"자본금 총액이 10억 원 미만인 회사의 경우에는 감사를 선임하지 아니할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 감사"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-2","t":"감사의 지위는 주주총회의 선임결의와 피선임자의 승낙만 있다고 하여 바로 취득하는 것은 아니고 주주총회의 선임결의에 따라 회사의 대표기관이 임용계약의 청약을 하고 피선임자가 이에 승낙을 함으로써 임용계약이 체결되어야만 비로소 인정된다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사의 감사"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-3","t":"감사가 회의의 목적사항과 소집이유를 서면에 적어 소집권자에게 제출하여 이사회 소집을 청구하였는데도 소집권자가 지체 없이 이사회를 소집하지 아니하면 그 청구한 감사가 이사회를 소집할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 감사"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-4","t":"감사의 임기는 취임 후 3년 내의 최종의 결산기에 관한 정기총회의 종결시까지로 한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 감사"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-5","t":"회사가 이사에 대하여 또는 이사가 회사에 대하여 소를 제기하는 경우에 감사는 그 소에 관하여 회사를 대표한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 감사"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-1","t":"1주 1의결권의 원칙을 규정하고 있는 상법 제369조 제1항은 강행규정이므로 법률에서 위 원칙에 대한 예외를 인정하는 경우를 제외하고, 정관의 규정이나 주주총회의 결의 등으로 위 원칙에 반하여 의결권을 제한하더라도 효력이 없다.","ox":"O","m":"①","c":"A","tp":"주주의 의결권"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-2","t":"의결권의 대리행사로 말미암아 주주총회의 개최가 부당하게 저해되거나 혹은 회사의 이익이 부당하게 침해될 염려가 있는 등의 특별한 사정이 있는 경우에는 회사가 이를 거절할 수 있다.","ox":"O","m":"②","c":"A","tp":"주주의 의결권"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-3","t":"주주가 대리인으로 하여금 그 의결권을 행사하게 하는 경우 대리권을 증명하는 서면은 위조나 변조 여부를 쉽게 식별할 수 있는 원본이어야 하고 특별한 사정이 없는 한 사본은 그 서면에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"주주의 의결권"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-4","t":"대리인의 자격을 주주로 한정하는 취지의 주식회사의 정관 규정은 주주총회가 주주 이외의 제3자에 의하여 교란되는 것을 방지하여 회사 이익을 보호하는 취지에서 마련된 것으로서 합리적인 이유에 의한 상당한 정도의 제한이라고 볼 수 있으므로 이를 무효라고 볼 수는 없다.","ox":"O","m":"④","c":"A","tp":"주주의 의결권"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-5","t":"주주의 대리인의 자격을 주주로 제한하는 정관규정이 있는 경우 주주인 국가, 지방공공단체 또는 주식회사 소속의 공무원, 직원 또는 피용자 등이 그 주주를 위한 대리인으로서 의결권을 대리행사하는 것은 정관 규정에 위반한 무효의 의결권 대리행사이므로 허용될 수 없다.","ox":"X","m":"⑤","c":"A","tp":"주주의 의결권"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-1","t":"이사자격이 없는 자에게 회사가 표현대표이사의 명칭을 사용케 한 경우이거나 이사자격 없이 그 명칭을 사용하는 것을 회사가 알고 용인상태에 둔 경우에는 회사는 상법 제395조에 의한 표현책임을 질 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-2","t":"표현대표이사의 명칭을 사용하는 이사가 자기명의로 행위할 때 뿐 아니라 행위자 자신이 표현대표이사인 이상 다른 대표이사의 명칭을 사용하여 행위한 경우에도 상법 제395조가 적용된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-3","t":"거래의 상대방인 제3자가 대표이사가 아닌 이사에게 그 거래행위를 함에 있어 회사를 대표할 권한이 있다고 믿었다 할지라도 그와 같이 믿은 데에 중대한 과실이 있는 경우에는 회사는 위 규정에 의한 책임을 지지 아니한다.","ox":"O","m":"③","c":"A","tp":"표현대표이사"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-4","t":"회사를 대표할 권한이 없는 표현대표이사가 다른 대표이사의 명칭을 사용하여 어음행위를 한 경우, 회사가 책임을 지는 선의의 제3자의 범위에는 표현대표이사로부터 직접 어음을 취득한 상대방만 포함된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-5","t":"상법 제395조 소정의 ‘선의’란 표현대표이사가 대표권이 없음을 알지 못한 것을 말하는 것이지 반드시 형식상 대표이사가 아니라는 것을 알지 못한 것에 한정할 필요는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-1","t":"집중투표를 하기 위해서는 발행주식총수의 100분의 3 이상에 해당하는 주식(의결권 없는 주식 포함)을 가진 주주가 주주총회일의 7일 전까지 회사에 대하여 집중투표의 방법으로 이사를 선임할 것을 청구해야 한다.","ox":"X","m":"①","c":"A","tp":"상법 제382조의2에서 규정하고 있는 집중투표제"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-2","t":"정관에 집중투표를 배제하는 규정이 없어야 집중투표를 할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법 제382조의2에서 규정하고 있는 집중투표제"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-3","t":"이사의 선임결의에 관하여 집중투표를 하는 경우 각 주주는 1주마다 선임할 이사의 수와 동일한 수의 의결권을 가지며, 그 의결권은 이사 후보자 1인 또는 수인에게 집중하여 투표하는 방법으로 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법 제382조의2에서 규정하고 있는 집중투표제"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-4","t":"집중투표 결과 투표의 최다수를 얻은 사람부터 순차적으로 이사에 선임된다.","ox":"O","m":"④","c":"A","tp":"상법 제382조의2에서 규정하고 있는 집중투표제"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-5","t":"주식회사의 정관에서 이사의 선임을 발행주식총수의 과반수에 해당하는 주식을 가진 주주의 출석과 출석주주의 의결권의 과반수에 의한다고 규정하고 있는 경우 이사의 선임을 집중투표의 방법으로 하더라도 정관에 규정한 의사정족수는 충족되어야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법 제382조의2에서 규정하고 있는 집중투표제"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-1","t":"대표이사는 이사회의 결의로 선정하여야 하나 정관의 규정이 있으면 주주총회에서 선정할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-2","t":"주식회사의 대표이사가 대표권의 범위 내에서 한 행위는 설사 대표이사가 회사의 영리 목적과 관계없이 자기 또는 제3자의 이익을 도모할 목적으로 권한을 남용한 것이라도 일응 회사의 행위로서 유효하나, 회사는 상대방의 악의를 입증하여 행위의 효과를 부인할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-3","t":"주식회사가 수인의 대표이사를 둔 경우 원칙적으로 각 대표이사가 단독으로 회사를 대표하지만 공동으로 회사를 대표할 것을 정할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-4","t":"공동대표이사 중 1인은 다른 공동대표이사에게 그 대표권의 행사를 일반적, 포괄적으로 위임할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-5","t":"대표이사는 회사의 영업에 관한 재판상 또는 재판외의 모든 행위를 할 권한이 있고, 그 권한에 대한 내부적 제한은 선의의 제3자에게 대항할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 대표이사"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22","t":"이사와 회사 사이의 소에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"이사와 회사 사이의 소에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["회사가 이사에 대하여 또는 이사가 회사에 대하여 소를 제기하는 경우에 감사는 그 소에 관하여 회사를 대표한다.","발행주식총수의 100분의 1 이상에 해당하는 주식을 가진 주주가 회사에 대하여 이사의 책임을 추궁할 소를 제기할 경우에도 감사가 회사를 대표한다.","이사와 회사 사이의 소에서 감사로 하여금 회사를 대표하도록 한 취지는, 이사와 회사 양자 간에 이해의 충돌이 있기 쉬우므로 그 충돌을 방지하고 공정한 소송수행을 확보하기 위한 것이다.","피고 회사의 이사인 원고가 피고 회사에 대하여 소를 제기할 때, 대표이사를 피고 회사의 대표자로 표시한 소장을 법원에 제출하고, 법원도 이 점을 간과하여 피고 회사의 대표이사에게 소장의 부본을 송달한 채, 피고 회사의 대표이사로부터 소송대리권을 위임받은 변호사들에 의하여 소송이 수행되었다면, 이 사건 소에 관하여는 피고 회사를 대표할 권한이 대표이사에게 없기 때문에 소장이 피고에게 적법유효하게 송달되었다고 볼 수 없음은 물론 피고 회사의 대표이사가 피고를 대표하여 한 소송행위나 피고 회사의 대표이사에 대하여 원고가 한 소송행위는 모두 무효이다.","소 제기 전 甲 회사의 주주가 甲 회사를 적법하게 대표할 사람이 없다는 이유로 일시대표이사 및 이사의 선임을 구하는 신청을 하여 변호사인 乙이 甲 회사의 일시대표이사 및 이사로 선임된 경우에 일시대표이사인 乙은 감사가 아니므로 甲 회사를 대표하여 甲 회사의 소수주주가 소집한 주주총회에서 이사로 선임된 丙을 상대로 이사선임결의의 부존재를 주장하며 이사 지위의 부존재 확인을 구할 수 없다. 23-5"],"a":5}},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35-1","t":"대표이사가 회사 명의로 한 채무부담행위가 회사에 대하여 무효인 경우에는 회사에 어떠한 손해가 발생하였다고 할 수 없으므로 회사가 사용자 책임을 지는 등의 특별한 사정이 없는 한 이사는 회사에 대하여 책임을 지지 않는다.","ox":"O","m":"①","c":"A","tp":"주식회사의 이사"},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35-2","t":"회사는 정관으로 정하는 바에 따라 상법 제399조에 따른 사외이사의 책임을 그 행위를 한 날이전 최근 1년간의 보수액의 6배를 초과하는 금액에 대하여 면제할 수 있다.","ox":"X","m":"②","c":"A","tp":"주식회사의 이사"},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35-3","t":"상법 제399조에 따른 이사의 책임은 주주 전원의 동의로 면제할 수 있다.","ox":"O","m":"③","c":"A","tp":"주식회사의 이사"},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35-4","t":"이사가 이익상반행위를 통하여 회사에 손해를 입힌 경우 책임이 제한되지 않는다.","ox":"O","m":"④","c":"A","tp":"주식회사의 이사"},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35-5","t":"정기총회에서 재무제표 등을 승인한 후 2년내에 다른 결의가 없으면 부정행위가 없는 한 이사의 책임이 해제된다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 이사"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-1","t":"이사회에 의한 소집 외관과는 달리 이사회의 결정이 없었다는 사정은 주주총회결의의 취소사유이다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-2","t":"소수주주가 주주총회 소집을 청구하였음에도 불구하고 지체 없이 그 소집절차를 밟지 아니한 때에는 청구한 주주는 법원의 허가를 받아 총회를 소집할 수 있는데, 이 경우 주주총회 의장은 법원이 이해관계인의 청구나 직권으로 선임할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-3","t":"이사회에서 주주총회의 소집을 철회하기로 결의하자, 주주총회 개최장소 출입문에 총회소집이 철회되었다는 취지의 공고문을 부착하고 위 이사회에 참석하지 않은 주주들에게는 퀵서비스를 통해 소집철회통지서를 보내는 한편, 전보와 휴대전화로도 같은 취지의 통지를 하였다면, 그 소집은 적법하게 철회되었다고 볼 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-4","t":"상법 제368조의2 제1항에 따라 주주가 2 이상의 의결권을 가지고 있어 이를 통일하지 않고 행사하고자 한다면 주주총회일 3일 전까지 회사에 대하여 서면 또는 전자문서로 그 취지를 통지해야 하는데, 여기서 통지의 의미는 주주가 3일 전까지 통지를 발송하기만 하면 된다는 의미이고, 회사에 3일 전까지 도달해야 한다는 의미는 아니다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-5","t":"자본금 총액이 10억 원 미만인 회사는 주주 전원의 동의가 있을 경우에는 서면에 의한 결의로써 주주총회 결의를 갈음할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-1","t":"이사가 그 지위에 기하여 주주총회결의 취소의 소를 제기하였다가 소송 계속 중에 사망하였거나 사실심 변론종결 후에 사망하였다면, 그 소송은 이사의 사망으로 중단된다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 주주총회 결의의 하자를 다투는 소송"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-2","t":"결의취소의 소가 제기된 경우에 결의의 내용, 회사의 현황과 제반사정을 참작하여 그 취소가 부적당하다고 인정한 때에는 법원은 그 청구를 기각할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 주주총회 결의의 하자를 다투는 소송"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-3","t":"결의취소 및 결의무효·부존재확인의 판결은 제3자에 대하여도 그 효력이 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 주주총회 결의의 하자를 다투는 소송"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-4","t":"주주총회결의 취소소송의 계속 중 원고가 주주로서의 지위를 상실하면 원고는 그 취소를 구할 당사자적격을 상실한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 주주총회 결의의 하자를 다투는 소송"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-5","t":"소제기 이후 주식의 포괄적 교환이 이루어져 원고가 피고회사의 주주의 지위를 상실한 경우에는 주주총회결의의 취소를 구할 원고적격이 인정되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 주주총회 결의의 하자를 다투는 소송"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-1","t":"감사의 임기는 취임후 3년내의 최종의 결산기에 관한 정기총회의 종결시까지로 한다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-2","t":"의결권 없는 주식을 제외한 발행주식의 총수의 100분의 3을 초과하는 수의 주식을 가진 주주는 그 초과하는 주식에 관하여 감사의 선임에 있어서는 의결권을 행사하지 못한다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-3","t":"주주총회에서 감사를 선임하는 경우, 그 선임결의가 있었다고 하여 바로 피선임자가 감사의 지위를 취득하는 것은 아니고 회사의 대표기관과 별도의 임용계약을 체결하여야 감사의 지위를 취득하게 된다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-4","t":"감사는 언제든지 상법 제434조의 규정에 의한 주주총회의 결의로 해임할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-5","t":"감사위원회는 3명 이상의 이사로 구성하고, 사외이사가 위원의 3분의 2 이상이어야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42-1","t":"이사회의 결의에 관하여 특별한 이해관계가 있는 이사는 의결권을 행사하지 못한다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 이사 및 이사회"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42-2","t":"이사회는 이사 및 감사 전원의 동의가 있는 때에는 회일을 정하고 그 전에 통지하는 등의 절차 없이 언제든지 회의할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 이사 및 이사회"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42-3","t":"사외이사는 대표이사가 선임한다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 이사 및 이사회"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42-4","t":"주주는 영업시간내에 이사회의사록의 열람 또는 등사를 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 이사 및 이사회"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42-5","t":"이사회는 정관이 정한 바에 따라 위원회를 설치할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 이사 및 이사회"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-1","t":"대표이사는 이사회에서 선정하나, 정관으로 정한 경우에는 주주총회에서 선정할 수 있다.","ox":"O","m":"①","c":"A","tp":"주식회사 대표이사"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-2","t":"수인의 대표이사가 공동으로 회사를 대표하도록 정한 경우에 제3자의 회사에 대한 의사표시는 대표이사 중 1인에 대하여 함으로써 그 효력이 생긴다.","ox":"O","m":"②","c":"A","tp":"주식회사 대표이사"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-3","t":"주식회사의 대표이사가 그 대표권의 범위 내에서 한 행위는 회사의 영리 목적과 관계없이 자기의 이익을 도모할 목적으로 그 권한을 남용한 것이라 할지라도 회사의 행위로서 유효하다. 다만 그 행위의 상대방이 그와 같은 정을 알았던 경우 회사는 상대방의 악의를 증명하여 그 행위의 효과를 부인할 수 있다.","ox":"O","m":"③","c":"A","tp":"주식회사 대표이사"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-4","t":"대표이사는 이사의 자격을 전제로 하므로 이사의 자격을 상실하면 대표이사의 자격도 잃게 되나, 반대로 대표이사에서 해임되었다고 하여 이사의 자격을 상실하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"주식회사 대표이사"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-5","t":"대표이사가 회사재산을 횡령하여 회사재산이 감소함으로써 회사가 손해를 입고 결과적으로 주주의 경제적 이익이 침해되는 간접적인 손해가 발생한 경우 주주는 이와 같은 손해에 대하여 대표이사를 상대로 상법 제401조 제1항에 따라 손해배상을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"주식회사 대표이사"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-1","t":"정관이나 이사회 결의로 특별히 정하지 않는 한 이사회는 대표이사가 소집한다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 이사회"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-2","t":"이사회의 결의로 소집권자로 지정된 이사가 다른 이사로부터 이사회 소집을 요구받고도 정당한 이유 없이 이사회 소집을 거절하는 경우 그 다른 이사는 이사회를 소집할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 이사회"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-3","t":"이사회의 결의는 이사 과반수의 출석과 출석이사의 과반수로 하여야 하고, 정관으로 그 비율을 높이는 것은 허용되지 않는다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 이사회"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-4","t":"이사회는 이사 및 감사 전원의 동의가 있더라도 소집통지의 발송절차를 생략할 수 없다.","ox":"X","m":"④","c":"A","tp":"상법상 주식회사의 이사회"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-5","t":"이사회의 소집통지는 정관에 달리 규정이 없는 한 서면으로 하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사의 이사회"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-1","t":"주식분할, 정관변경, 재무제표승인에는 상법 제434조에 따른 주주총회의 특별결의가 필요하다.","ox":"X","m":"①","c":"A","tp":"상법상 주주의 의결권, 주주총회의 결의방법 등"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-2","t":"단순한 영업용 재산의 양도는 주주총회의 특별결의가 있어야 하는 상법 제374조 제1항 제1호에서 말하는 ‘영업의 전부 또는 중요한 일부의 양도’에는 해당하지 않는다.","ox":"O","m":"②","c":"A","tp":"상법상 주주의 의결권, 주주총회의 결의방법 등"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-3","t":"주주총회의 결의에 있어서 회사가 가진 자기주식은 의결권이 없고, 그와 같은 자기주식의 수는 발행주식총수에 산입하지 아니한다.","ox":"O","m":"③","c":"A","tp":"상법상 주주의 의결권, 주주총회의 결의방법 등"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-4","t":"이사와 회사 사이의 이익상반거래에 대한 승인은 주주 전원의 동의가 있다거나 그 승인이 정관에 주주총회의 권한사항으로 정해져 있다는 등의 특별한 사정이 없는 한 이사회의 전결사항이므로, 주주총회가 최고기관성을 가지고 있다고 하더라도 이사회의 승인을 받지 못한 이익상반거래에 대하여 승인 권한이 없는 주주총회에서 사후적으로 추인 결의를 하였다고 하여 그 거래가 유효하게 될 수는 없다.","ox":"O","m":"④","c":"A","tp":"상법상 주주의 의결권, 주주총회의 결의방법 등"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-5","t":"상법 제409조 제2항에 따라 의결권 없는 주식을 제외한 발행주식총수의 3%를 초과하는 주식을 가진 주주는 그 초과하는 주식에 관하여 주주총회의 감사 선임에 있어서 의결권을 행사하지 못하는데, 위와 같이 3%를 초과하는 주식은 상법 제368조 제1항의 총회 결의요건 중 ‘발행주식총수의 4분의 1 이상’에서 말하는 ‘발행주식총수’에는 산입되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주주의 의결권, 주주총회의 결의방법 등"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-1","t":"상법은 주주총회결의 하자의 내용에 따라 결의취소의 소, 결의무효확인의 소, 결의부존재확인의 소, 부당결의의 취소·변경의 소를 규정하고 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주주총회 결의의 하자"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-2","t":"모든 결의하자의 소는 대세효, 소급효가 있다는 점에서 차이가 없다.","ox":"O","m":"②","c":"A","tp":"상법상 주주총회 결의의 하자"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-3","t":"모든 결의하자의 소에 있어서 피고는 회사로 한정된다.","ox":"O","m":"③","c":"A","tp":"상법상 주주총회 결의의 하자"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-4","t":"모든 결의하자의 소는 형성의 소이다.","ox":"X","m":"④","c":"A","tp":"상법상 주주총회 결의의 하자"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-5","t":"모든 결의하자의 소 중 이른바 법원의 재량기각이 인정되는 것은 결의취소의 소뿐이다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주주총회 결의의 하자"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-1","t":"상법 제399조는 이사가 법령에 위반한 행위를 한 경우에 회사에 대하여 손해배상책임을 지도록 규정하고 있는데, 이사가 임무를 수행함에 있어서 위와 같이 법령에 위반한 행위를 한 때에는, 그로 인하여 회사에 손해가 발생한 이상 특별한 사정이 없는 한 손해배상책임을 면할 수 없고, 원칙적으로 경영판단의 원칙이 적용되지 않는다.","ox":"O","m":"①","c":"A","tp":"상법상 이사의 책임"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-2","t":"이사가 법령 또는 정관에 위반한 행위를 하거나 그 임무를 게을리함으로써 회사에 대하여 손해를 배상할 책임이 있는 경우에 그 손해배상의 범위를 정함에 있어서는, 여러 제반 사정을 참작하여 손해분담의 공평이라는 손해배상제도의 이념에 비추어 그 손해배상액을 제한할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 이사의 책임"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-3","t":"이사가 회사재산을 횡령하여 회사재산이 감소함으로써 회사가 손해를 입고 결과적으로 주주의 경제적 이익이 침해되는 손해와 같은 간접적인 손해는 상법 제401조 제1항에서 말하는 손해의 개념에 포함되지 아니하므로 이에 대하여는 위 법조항에 의한 손해배상을 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 이사의 책임"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-4","t":"회사 또는 제3자에 대하여 손해를 배상할 책임이 있는 이사는 업무집행지시자와 연대하여 그 책임을 진다.","ox":"O","m":"④","c":"A","tp":"상법상 이사의 책임"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-5","t":"회사의 이사가 될 수 있는 자는 자연인에 한정되므로, 이사와 동일한 책임을 지는 업무집행지시자 역시 자연인에 한정된다.","ox":"X","m":"⑤","c":"A","tp":"상법상 이사의 책임"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-1","t":"이사와 회사 사이의 소송에서는 회사가 원고 또는 피고임을 가리지 않고 감사가 그 소에 관하여 회사를 대표한다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 대표이사의 대표권 제한"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-2","t":"소송의 목적이 되는 권리관계가 이사의 재직중에 일어난 사유로 인한 것이라 할지라도 회사가 그 사람을 이사의 자격으로 제소하는 것이 아니고 이사가 이미 이사의 자리를 떠난 경우에 회사가 그 사람을 상대로 제소하는 경우에는 특별한 사정이 없는 한 상법 제394조 제1항을 적용하여 당해 소송에서 감사가 회사를 대표해야 한다고 볼 것은 아니다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 대표이사의 대표권 제한"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-3","t":"주식회사의 회생절차개시신청은 대표이사의 업무권한인 일상 업무에 속하지 아니한 중요한 업무에 해당하여 이사회 결의가 필요하다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사 대표이사의 대표권 제한"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-4","t":"주식회사가 영업의 전부 또는 중요한 일부를 양도한 후 주주총회의 특별결의가 없었다는 이유를 들어 스스로 그 약정의 무효를 주장하더라도 주주 전원이 그와 같은 약정에 동의한 것으로 볼 수 있는 등 특별한 사정이 인정되지 않는다면 위와 같은 무효 주장이 신의성실 원칙에 반한다고 할 수는 없다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 대표이사의 대표권 제한"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-5","t":"대표이사가 이사회 결의를 거쳐야 할 대외적 거래행위에 관하여 이를 거치지 아니한 경우라도, 이와 같은 이사회결의사항은 회사의 내부적 의사결정에 불과하다 할 것이므로, 그 거래 상대방이 그와 같은 이사회결의가 없었음을 알았거나 알지 못한 데에 중과실이 있는 경우가 아니라면 그 거래행위는 유효하다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사 대표이사의 대표권 제한"},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42","t":"상법상 주주총회결의 부존재확인의 소의 원인이 되는 사항은?","c":"A","mc":{"s":"상법상 주주총회결의 부존재확인의 소의 원인이 되는 사항은?","d":"","o":["소집권한이 없는 자가 이사회의 주주총회 소집결정도 없이 일부 주주에게만 구두로 소집통지하여 소집한 주주총회에서 이루어진 결의","주주총회 결의의 내용이 법령 또는 정관에 위반한 경우","총주식의 과반수를 넘는 주식을 소유한 주주가 참석하여 참석주주 전원의 찬성으로 결의가 있었으나 일부 주주에게 소집통지를 하지 아니한 경우","이사회의 결정 없이 주주총회가 소집되었지만 외관상 이사회의 결정이 있었던 것 같은 형식을 갖추고 소집권한 있는 자가 소집한 경우","소집통지서에 기재된 바 없는 사항에 관한 주주총회 결의"],"a":1}},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-1","t":"주식에 대해 질권이 설정되었다 하더라도 질권설정계약 등에 따라 질권자가 담보제공자인 주주로부터 의결권을 위임받아 직접 의결권을 행사하기로 약정하는 등의 특별한 약정이 있는 경우를 제외하고 질권설정자인 주주는 여전히 주주로서의 지위를 가지고 의결권을 행사할 수 있다.","ox":"O","m":"①","c":"A","tp":"주주의 의결권 행사"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-2","t":"회사는 누구에게든 주주의 권리행사와 관련하여 재산상의 이익을 공여할 수 없다. 회사가 특정의 주주에 대하여 무상으로 재산상의 이익을 공여한 경우에는 주주의 권리행사와 관련하여 이를 공여한 것으로 추정한다. 회사가 특정의 주주에 대하여 유상으로 재산상의 이익을 공여한 경우 회사가 얻은 이익이 공여한 이익에 비하여 현저하게 적은 때에도 또한 같다.","ox":"O","m":"②","c":"A","tp":"주주의 의결권 행사"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-3","t":"주주권행사의 위임은 구체적이고 개별적인 사항에 국한된다고 해석할 근거는 없으므로 주주권행사의 위임은 포괄적으로도 이루어질 수 있다고 보아야 한다. 그리고 포괄적 위임을 받은 자는 위임자나 회사 재산에 불리한 영향을 미칠 사항이라고 하여 그 위임된 주주권행사를 하지 못하는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"주주의 의결권 행사"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-4","t":"자본금 총액이 10억 원 미만인 회사는 주주 전원의 동의가 있을 경우에는 소집절차 없이 주주총회를 개최할 수 있고, 서면에 의한 결의로써 주주총회의 결의를 갈음할 수 있다. 결의의 목적사항에 대하여 주주 전원이 서면으로 동의를 한 때에는 서면에 의한 결의가 있는 것으로 본다.","ox":"O","m":"④","c":"A","tp":"주주의 의결권 행사"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-5","t":"상법 제368조 제2항이 규정하는 대리권을 증명하는 서면이란 위임장을 일컫는 것으로서 회사가 위임장과 함께 인감증명서, 참석장 등을 제출하도록 요구하는 것은 대리인의 자격 유무를 일률적으로 명확히 확인하기 위한 취지로서, 이러한 서류 등을 지참하지 아니한 대리인이 다른 방법으로 위임장의 진정성을 증명하더라도 회사는 그 대리권을 부정할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"주주의 의결권 행사"},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49-1","t":"주식회사 이사의 임기를 정한 경우에 주식회사가 정당한 이유 없이 임기만료 전에 이사를 해임한 때에는 그 이사는 회사에 대하여 해임으로 인한 손해의 배상을 청구할 수 있는데, 이러한 경우 정당한 이유의 존부에 관한 입증책임은 손해배상을 청구하는 이사가 부담한다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 이사"},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49-2","t":"경영권 상실 등으로 퇴직을 앞둔 이사가 회사에서 최대한 많은 보수를 받기 위해 지나치게 과다하여 합리적 수준을 현저히 벗어나는 보수 지급 기준을 마련하고 지위를 이용한 영향력 행사로 소수주주의 반대에도 주주총회결의가 성립되도록 한 경우, 위 행위가 유효하다 할 수 없다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 이사"},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49-3","t":"이사에 대한 퇴직위로금은 상법 제388조에 규정된 보수에 포함되지 않는다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 이사"},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49-4","t":"이사의 선임은 주주총회 보통결의사항, 이사의 해임은 특별결의사항이다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 이사"},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49-5","t":"대표이사를 포함한 이사가 임기의 만료나 사임에 의하여 퇴임함으로 말미암아 법률 또는 정관에 정한 대표이사나 이사의 원수를 채우지 못하게 되는 경우에, 그 퇴임한 이사는 새로 선임된 이사(후임이사)가 취임할 때까지 이사로서의 권리의무가 있고, 이러한 경우에는 이사의 퇴임등기를 하여야 하는 2주 또는 3주의 기간은 일반의 경우처럼 퇴임한 이사의 퇴임일부터 기산하는 것이 아니라 후임이사의 취임일부터 기산한다고 보아야 하며, 후임이사가 취임하기 전에는 퇴임한 이사의 퇴임등기만을 따로 신청할 수 없다고 봄이 상당하다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 이사"},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50-1","t":"주주총회 소집의 통지·공고가 행하여진 후 소집을 철회하거나 연기하기 위해서는 소집의 경우에 준하여 이사회의 결의를 거쳐 대표이사가 그 뜻을 그 소집에서와 같은 방법으로 통지·공고하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50-2","t":"이사와 회사 사이의 이익상반거래에 대한 승인은 원칙적으로 이사회의 전결사항이므로 이사회의 승인을 받지 못한 이익상반거래에 대하여 주주총회에서 사후적으로 추인 결의를 하였다 하더라도 그 거래는 여전히 무효이다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50-3","t":"주식을 질권의 목적으로 한 경우 회사가 질권설정자의 청구에 따라 그 성명과 주소를 주주명부에 덧붙여 쓰고, 그 성명을 주권에 적은 경우에는 질권자는 회사로부터 이익배당, 잔여재산의 분배를 받아 다른 채권자에 우선하여 자기채권의 변제에 충당할 수 있다.","ox":"O","m":"③","c":"A","tp":"주주총회"},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50-4","t":"주주총회결의 취소의 소는 상법 제376조 제1항에 따라 그 결의의 날로부터 2개월 내에 제기하여야 하고, 이 기간이 지난 후에 제기된 소는 부적법하다. 주주총회에서 여러 개의 안건이 상정되어 각 결의가 행하여진 경우 위 제소기간의 준수 여부는 각 안건에 대한 결의마다 별도로 판단되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50-5","t":"주주의 의결권을 적법하게 위임받은 대리인은 특별한 사정이 없는 한 주주총회에 참석하여 의결권을 행사할 수 있다 할 것이나, 그 대리인이 그 의결권의 대리행사를 제3자에게 재위임하는 것은 주주의 당초 수권에 반하는 것으로서 허용되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23","t":"주식회사의 이사 등과 회사 간의 거래에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"주식회사의 이사 등과 회사 간의 거래에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"㉠이사회의 승인을 받지 못한 이사와 회사 사이의 이익상반거래에 대하여는, 사전에 주주 전원의 동의가 있다거나 그 승인이 정관에 주주총회의 권한사항으로 정해져 있다는 등의 특별한 사정이 없는 한, 주주총회에서 사후적으로 추인 결의를 하였다 하여 그 거래가 유효하게 될 수는 없다.\n㉡이사와 회사 사이의 거래가 상법 제398조를 위반하였음을 이유로 무효임을 주장할 수 있는 자는 회사에 한정되고 특별한 사정이 없는 한 거래의 상대방인 당해 이사나 제3자는 그 무효를 주장할 이익이 없다.\n㉢회사에 대하여 개인적인 채권을 가지고 있는 대표이사가 회사를 위하여 보관하고 있는 회사 소유의 금전으로 자신의 채권 변제에 충당하는 행위는 회사와 이사의 이해가 충돌하는 자기거래행위에 해당하므로 이사회의 승인을 필요로 한다.\n㉣甲, 乙 두 회사의 대표이사를 겸하고 있던 자에 의하여 甲 회사와 乙 회사 사이에 토지 및 건물에 대한 매매계약이 체결되고 乙 회사 명의로 소유권이전등기가 경료된 경우, 그 매매계약은 원칙적으로 이사회의 승인을 요하는 이사의 자기거래에 해당한다.\n㉤이사가 자기 또는 제3자의 계산으로 회사와 거래를 하기 위해서는 상법 제398조에 따라 미리 이사회의 승인을 받아야 하고, 이 경우 이사회 승인은 상법 제397조에 따른 경업금지의 해제에 대한 이사회 승인과 동일하게 이사 과반수의 출석과 출석이사의 과반수로 하여야 한다.","o":["㉠, ㉡","㉠, ㉣","㉡, ㉤","㉢, ㉣","㉢, ㉤"],"a":5}},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-1","t":"이사가 고의 또는 과실로 법령 또는 정관에 위반한 행위를 하거나 그 임무를 게을리 한 경우에는 회사에 대하여 손해배상책임을 진다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 이사의 회사"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-2","t":"법령 또는 정관 위반 행위가 이사회의 결의에 의한 경우 결의에 찬성한 이사도 손해배상책임을 지고, 나아가 이사회에 참석하지 아니한 경우에도 이사회 불출석 자체가 임무해태에 해당한다면 손해배상책임을 질 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 이사의 회사"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-3","t":"이사회 결의에 참여한 이사로서 이의를 한 기재가 의사록에 없는 자는 그 결의에 찬성한 것으로 추정되므로, 당해 결의에 기권하였다고 의사록에 기재되었다면 찬성한 것으로 추정되어 그 이사는 손해배상책임을 진다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사 이사의 회사"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-4","t":"업무집행을 담당하지 않는 비상근이사·사외이사도 업무담당이사의 업무집행이 위법하다고 의심할 만한 사유가 있었음에도 불구하고 감시의무를 위반하여 방치한 때에는 손해배상책임을 진다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 이사의 회사"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-5","t":"회사의 이사에 대한 책임은 총주주의 동의로 면제할 수 있는데, 다수의 주주가 면책에 동의한다 하더라도 총주주에 이르지 못하는 이상 면책되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사 이사의 회사"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-1","t":"자본금의 총액이 10억 원 미만인 회사의 경우에는 감사를 선임하지 않을 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-2","t":"감사는 주주총회에서 감사의 해임에 관하여 의견을 진술할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-3","t":"회사는 정관이 정한 바에 따라 감사에 갈음하여 제393조의2의 규정에 의한 위원회로서 감사위원회를 설치할 수 있고, 감사위원회를 설치한 경우에도 감사를 함께 둘 수 있다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-4","t":"감사위원회의 위원의 해임에 관한 이사회의 결의는 이사 총수의 3분의 2 이상의 결의로 하여야 한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-5","t":"감사위원회는 그 결의로 위원회를 대표할 자를 선정하여야 하고, 이 경우 수인의 위원이 공동으로 위원회를 대표할 것을 정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 감사 및 감사위원회"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-1","t":"주식회사의 임시주주총회가 법령 및 정관상 요구되는 이사회의 결의 및 소집절차 없이 이루어졌다 하더라도, 주주명부상의 주주 전원이 참석하여 총회를 개최하는 데 동의하고 아무런 이의 없이 만장일치로 결의가 이루어졌다면 그 결의는 특별한 사정이 없는 한 유효하다.","ox":"O","m":"①","c":"A","tp":"상법상 주주총회"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-2","t":"회사의 총 주식을 한 사람이 소유하게 된 1인 회사의 경우에는 실제 총회를 개최한 사실이 없었다 하더라도 그 1인 주주에 의하여 의결이 있었던 것으로 주주총회의사록이 작성되었다면 특별한 사정이 없는 한 그 내용의 결의가 있었던 것으로 볼 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주주총회"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-3","t":"자본금 총액이 10억 원 미만인 회사가 주주총회를 소집하는 경우에는 주주총회일의 10일 전에 각 주주에게 서면으로 통지를 발송하거나 각 주주의 동의를 받아 전자문서로 통지를 발송할 수 있고, 주주 전원의 동의가 있을 경우에는 소집절차 없이 주주총회를 개최할 수도 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주주총회"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-4","t":"주주총회의 소집을 철회·취소하는 경우에는 반드시 총회의 소집과 동일한 방식으로 그 철회·취소를 총회 구성원들에게 통지하여야 할 필요는 없고, 주주에게 소집의 철회·취소결정이 있었음이 알려질 수 있는 적절한 조치를 취하면 된다.","ox":"X","m":"④","c":"A","tp":"상법상 주주총회"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-5","t":"총회의 소집절차 또는 결의방법이 법령 또는 정관에 위반하거나 현저하게 불공정한 때 또는 그 결의의 내용이 정관에 위반한 때에 주주는 2월내에 결의취소의 소를 제기할 수 있고, 하자가 일부 주주에게만 있는 경우 다른 주주도 그 하자를 주장하여 소를 제기할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주주총회"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-1","t":"회사가 표현대표를 허용하였다고 하기 위하여는 진정한 대표이사가 표현대표를 허용하거나, 이사 전원이 아닐지라도 적어도 이사회결의의 성립을 위하여 회사의 정관에서 정한 이사의 수, 그와 같은 정관의 규정이 없다면 최소한 이사 정원의 과반수 이사가 적극적 또는 묵시적으로 표현대표를 허용한 경우이어야 한다.","ox":"O","m":"①","c":"A","tp":"표현대표이사"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-2","t":"거래의 상대방인 제3자가 회사의 대표이사가 아닌 이사에게 그 거래행위를 함에 있어 회사를 대표할 권한이 있다고 믿었다 할지라도 그와 같이 믿음에 있어서 중대한 과실이 있는 경우에는 회사는 그 제3자에 대하여는 상법 제395조에 의한 책임을 지지 아니한다.","ox":"O","m":"②","c":"A","tp":"표현대표이사"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-3","t":"회사를 대표할 권한이 없는 표현대표이사가 다른 대표이사의 명칭을 사용하여 어음행위를 한 경우, 회사가 책임을 지는 선의의 제3자는 표현대표이사로부터 직접 어음을 취득한 상대방에 한하고, 그로부터 어음을 다시 배서양도받은 제3취득자는 포함되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-4","t":"상법 제395조는 표현대표이사가 자기의 명칭을 사용하여 법률행위를 한 경우뿐만 아니라 자기의 명칭을 사용하지 아니하고 다른 대표이사의 명칭을 사용하여 행위를 한 경우에도 유추적용된다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-5","t":"상법 제395조는 회사가 이사의 자격이 없는 자에게 표현대표이사의 명칭을 사용하게 허용한 경우는 물론, 이사의 자격도 없는 사람이 임의로 표현대표이사의 명칭을 사용하고 있는 것을 회사가 알면서도 아무런 조치를 취하지 아니한 채 그대로 방치하여 소극적으로 묵인한 경우에도 유추적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-1","t":"주주의 대표소송은 주주가 타인인 회사의 이익을 위해서 스스로 원고가 되어 소송을 수행하는 것으로 주주가 승소한 경우 그 손해배상액은 주주에게 귀속된다.","ox":"X","m":"①","c":"A","tp":"상법상 주주의 대표소송"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-2","t":"주주 대표소송을 제기한 주주의 보유주식이 제소 후 발행주식총수의 100분의 1 미만으로 감소하거나 발행주식을 보유하지 않게 된 경우에도 소가 부적법하게 되는 것은 아니다.","ox":"X","m":"②","c":"A","tp":"상법상 주주의 대표소송"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-3","t":"모회사 발행주식총수의 100분의 1 이상에 해당하는 주식을 가진 주주는 자회사에 대하여 자회사 이사의 책임을 추궁할 소의 제기를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주주의 대표소송"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-4","t":"주주가 대표소송을 제기한 경우에는 법원의 허가 없이 소의 취하·청구의 포기·화해를 할 수 없지만 회사가 주주의 청구에 따라 이사의 책임을 추궁하는 소를 제기한 경우에는 법원의 허가 없이 할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 주주의 대표소송"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-5","t":"주주가 대표소송에서 패소한 경우 자신의 청구가 근거 없다는 것을 알면서 또는 과실로 알지 못하고 제소하였다면 손해배상책임을 진다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주주의 대표소송"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25-1","t":"주주총회결의의 효력이 그 회사 아닌 제3자 사이의 소송에 있어 선결문제로 된 경우에는 당사자는 언제든지 당해 소송에서 주주총회결의가 처음부터 무효 또는 부존재하다고 다투어 주장할 수 있는 것이고, 반드시 먼저 회사를 상대로 제소하여야만 하는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25-2","t":"주식회사와 전혀 관계없는 사람이 주주총회의사록을 위조한 경우와 같이 주식회사 내부의 의사결정 자체가 아예 존재하지 않는 경우에 이를 확인하는 판결은 상법 제380조 소정의 주주총회결의부존재확인판결에 해당한다고 보아서는 안된다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25-3","t":"주주총회결의의 부존재·무효를 확인하거나 결의를 취소하는 판결이 확정되면 당사자 이외의 제3자에게도 그 효력이 미쳐 제3자도 이를 다툴 수 없게 되므로, 주주총회결의의 하자를 다투는 소에 있어서 청구의 인낙이나 그 결의의 부존재·무효를 확인하는 내용의 화해·조정은 할 수 없고,가사 이러한 내용의 청구인낙 또는 화해·조정이 이루어졌다 하여도 그 인낙조서나 화해·조정조서는 효력이 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25-4","t":"이사 선임의 주주총회결의에 대한 취소판결이 확정된 경우 그 결의에 의하여 이사로 선임된 이사들에 의하여 구성된 이사회에서 선정된 대표이사는 소급하여 그 자격을 상실하고, 그 대표이사가 이사 선임의 주주총회결의에 대한 취소판결이 확정되기 전에 한 행위는 대표권이 없는 자가 한 행위로서 무효가 된다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25-5","t":"주주총회결의의 부존재 또는 무효 확인을 구하는 소를 여러 사람이 공동으로 제기한 경우 필수적 공동소송이 아니라 통상공동소송에 해당한다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-1","t":"6개월 전부터 계속하여 상장회사인 모회사 발행주식총수의 1만분의 50 이상에 해당하는 주식을 보유한 주주는 자회사에 대하여 자회사 이사의 책임을 추궁할 소의 제기를 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-2","t":"주주의 제소청구서에 책임추궁 대상 이사의 성명이 기재되어 있지 않거나 책임발생 원인사실이 다소 개략적으로 기재되어 있더라도, 회사가 그 서면에 기재된 내용, 이사회의사록 등 회사 보유 자료 등을 종합하여 책임추궁 대상 이사, 책임발생 원인사실을 구체적으로 특정할 수 있다면, 그 서면은 상법 제403조 제2항에서 정한 요건을 충족하였다고 보아야 한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-3","t":"주주가 대표소송에서 주장한 이사의 손해배상책임이 제소청구서에 적시된 것과 차이가 있더라도 제소청구서의 책임발생 원인사실을 기초로 하면서 법적 평가만을 달리한 것에 불과하다면 그 대표소송은 적법하다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-4","t":"모회사 발행주식총수의 100분의 1 이상에 해당하는 주식을 가진 주주는 다중대표소송의 제기를 위해 이유를 붙인 서면으로 자회사에 대해 회계의 장부와 서류의 열람 또는 등사를 청구할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-5","t":"다중대표소송이 제기된 경우에 원고와 피고의 공모로 인하여 소송의 목적인 회사의 권리를 사해할 목적으로써 판결을 하게 한 때에는 회사 또는 주주는 확정한 종국판결에 대하여 재심의 소를 제기할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-1","t":"회사가 ‘영업의 전부 또는 중요한 일부의 양도’, ‘영업 전부의 임대 또는 경영위임, 타인과 영업의 손익 전부를 같이 하는 계약, 그 밖에 이에 준하는 계약의 체결ㆍ변경 또는 해약’, ‘회사의 영업에 중대한 영향을 미치는 다른 회사의 영업 전부 또는 일부의 양수’를 할 때에는 주주총회의 특별결의가 있어야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-2","t":"회사의 영업 그 자체가 아닌 영업용재산의 처분이라고 하더라도 그로 인하여 회사의 영업의 전부 또는 중요한 일부를 양도하거나 폐지하는 것과 같은 결과를 가져오는 경우에는 그 처분행위를 함에 있어서 상법 제374조 제1항 제1호 소정의 주주총회의 특별결의를 요하는 것이고, 다만 회사가 위와 같은 회사존속의 기초가 되는 영업재산을 처분할 당시에 이미 영업을 폐지하거나 중단하고 있었던 경우에는 그 처분으로 인하여 비로소 영업의 전부 또는 일부가 폐지되거나 중단되기에 이른 것이라고 할 수 없으므로 주주총회의 특별결의를 요하지 않는 것이고, 위에서 ‘영업의 중단’이라고 함은 영업의 계속을 포기하고 일체의 영업활동을 중단한 것으로서 영업의 폐지에 준하는 상태를 말하고 단순히 회사의 자금사정 등 경영상태의 악화로 일시 영업활동을 중지한 경우는 여기에 해당하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-3","t":"상법 제374조 제1항 제1호는 주식회사가 영업의 전부 또는 중요한 일부의 양도행위를 할 때에는 제434조에 따라 출석한 주주의 의결권의 3분의 2 이상의 수와 발행주식총수의 3분의 1 이상의 수로써 결의가 있어야 한다고 규정하고 있으나, 거래상대방이 아닌 주식회사가 영업의 전부 또는 중요한 일부를 양도한 후 주주총회의 특별결의가 없었다는 이유를 들어 스스로 그 약정의 무효를 주장하는 것은 특별한 사정이 없는 한 신의성실 원칙에 반한다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-4","t":"영업양도에 반대하는 주주의 주식매수청구권은 이른바 형성권으로서 그 행사로 회사의 승낙 여부와 관계없이 주식에 관한 매매계약이 성립하고, 상법 제374조의2 제2항의 ‘매수 청구 기간이 종료하는 날부터 2개월’은 주식매매대금 지급의무의 이행기를 정한 것이라고 해석된다. 그리고 이러한 법리는 위 2개월 이내에 주식의 매수가액이 확정되지 아니하였다고 하더라도 다르지 아니하다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-5","t":"영업양도에 반대하는 주주의 주식매수청구권 행사에 따른 주식의 매수가액은 주주와 회사간의 협의에 의하여 결정하고, 매수청구기간이 종료하는 날부터 30일 이내에 그 협의가 이루어지지 아니한 경우에는 회사 또는 주식의 매수를 청구한 주주는 법원에 대하여 매수가액의 결정을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-1","t":"이사는 주주총회에서 특별결의로 선임된다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사 이사의 선임"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-2","t":"2인 이상의 이사의 선임을 목적으로 하는 총회의 소집이 있는 때에는 발행주식총수의 100분의 3이상에 해당하는 주식을 가진 주주는 회사에 대하여 집중투표의 방법으로 이사를 선임할 것을 청구할 수 있다. 이때 100분의 3에는 의결권 없는 주식도 포함한다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사 이사의 선임"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-3","t":"2인 이상의 이사 선임에 관한 집중투표를 배제하는 정관 규정은 효력이 없다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사 이사의 선임"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-4","t":"이사선임결의와 피선임자의 승낙만 있으면 대표이사와 별도의 임용계약을 체결하였는지와 관계 없이 이사의 지위를 취득한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 이사의 선임"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-5","t":"이사의 임기는 3년을 초과하지 못하므로, 임기를 정하지 않은 경우에는 그 임기를 3년으로 본다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사 이사의 선임"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39","t":"이사의 경업금지, 이사와 회사간의 거래, 이사의 회사에 대한 책임에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"이사의 경업금지, 이사와 회사간의 거래, 이사의 회사에 대한 책임에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["이사는 경업 대상 회사의 이사, 대표이사가 되는 경우뿐만 아니라 그 회사의 지배주주가 되어 그 회사의 의사결정과 업무집행에 관여할 수 있게 되는 경우에도 자신이 속한 회사 이사회의 승인을 얻어야 한다.","이사의 배우자의 직계존비속이 자기 또는 제3자의 계산으로 회사와 거래를 하기 위하여는 미리 이사회에서 해당 거래에 관한 중요사실을 밝히고 이사회의 승인을 받아야 한다. 이 경우 이사회의 승인은 이사 3분의 2 이상의 수로써 하여야 한다.","이사가 고의 또는 과실로 법령 또는 정관에 위반한 행위를 하거나 그 임무를 게을리한 경우에 그 행위가 이사회의 결의에 의한 것인 때에는 그 결의에 찬성한 이사도 상법 제399조 제1항의 책임이 있다.","위 ③의 이사회 결의에 참가한 이사로서 이의를 한 기재가 의사록에 없는 자는 상법 제399조 제3항에 따라 그 결의에 찬성한 것으로 추정한다.","이사가 위 ③의 이사회에 출석하여 결의에 기권하였다고 의사록에 기재된 경우에는 그 결의에 이의하였다고 볼 수 없으므로 상법 제399조 제3항에 따라 그 결의에 찬성한 것으로 추정한다."],"a":5}},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-1","t":"상법 제388조는 “이사의 보수는 정관에 그 액을 정하지 아니한 때에는 주주총회의 결의로 이를 정한다.”라고 규정하고 있고, 위 규정의 보수에는 연봉, 수당, 상여금 등 명칭을 불문하고 이사의 직무수행에 대한 보상으로 지급되는 모든 대가가 포함된다. 다만 주주총회에서 이사의 보수에 관한 구체적 사항을 이사회에 위임한 경우에는 주주총회에서 이를 직접 정할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-2","t":"주식회사의 총주식을 한 사람이 소유하는 이른바 1인회사의 경우, 주주총회 소집절차에 하자가 있거나 주주총회의사록이 작성되지 않았더라도, 1인주주의 의사가 주주총회의 결의내용과 일치한다면 증거에 의하여 그러한 내용의 결의가 있었던 것으로 볼 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-3","t":"회사는 이사회의 결의로 회사를 대표할 이사를 선정하여야 한다. 그러나 정관으로 주주총회에서 이를 선정할 것을 정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-4","t":"이사회는 각 이사가 소집한다. 그러나 이사회의 결의로 소집할 이사를 정한 때에는 그러하지 아니하다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-5","t":"이사회의 결의는 이사 과반수의 출석과 출석이사의 과반수로 하여야 한다. 그러나 정관으로 그 비율을 높게 정할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-1","t":"주주총회는 상법 또는 정관이 정하는 사항에 한하여 결의할 수 있고, 총회의 소집은 상법에 다른 규정이 있는 경우 외에는 이사회가 결정한다.","ox":"O","m":"①","c":"A","tp":"주식회사의 주주총회"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-2","t":"주주총회 결의사항은 정관이나 주주총회의 결의에 의하더라도 이를 다른 기관이나 제3자에게 위임할 수 있으므로, 정관 또는 주주총회에서 임원의 보수 총액 내지 한도액만을 정하고 개별 이사에 대한 지급액 등 구체적인 사항을 이사회에 위임하는 것은 물론 이사의 보수에 관한 사항을 이사회에 포괄적으로 위임하는 것도 허용된다.","ox":"X","m":"②","c":"A","tp":"주식회사의 주주총회"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-3","t":"주주총회를 소집할 권한이 없는 자가 이사회의 주주총회 소집결정도 없이 소집한 주주총회에서 이루어진 결의는 특별한 사정이 없는 한 총회 및 결의라고 볼 만한 것이 사실상 존재한다고 하더라도 그 성립과정에 중대한 하자가 있어 법률상 존재하지 않는다고 보아야 한다.","ox":"O","m":"③","c":"A","tp":"주식회사의 주주총회"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-4","t":"주식회사가 영업의 전부 또는 중요한 일부를 양도한 후 주주총회의 특별결의가 없었다는 이유를 들어 스스로 그 약정의 무효를 주장하더라도 주주 전원이 그와 같은 약정에 동의한 것으로 볼 수 있는 등 특별한 사정이 인정되지 않는다면 위와 같은 무효 주장이 신의성실 원칙에 반한다고 할 수는 없다.","ox":"O","m":"④","c":"A","tp":"주식회사의 주주총회"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-5","t":"1인회사가 아닌 주식회사에서는 특별한 사정이 없는 한, 주주총회의 의결정족수를 충족하는 주식을 가진 주주들이 동의하거나 승인하였다는 사정만으로 주주총회에서 그러한 내용의 결의가 이루어질 것이 명백하다거나 또는 그러한 내용의 주주총회 결의가 있었던 것과 마찬가지라고 볼 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 주주총회"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-1","t":"상법 제366조 제1항에서 정한 소수주주는 회의의 목적사항과 소집 이유를 적은 서면 또는 전자문서를 이사회에 제출하는 방법으로 임시주주총회의 소집을 청구할 수 있는데, 이때 ‘이사회’는 원칙적으로 대표이사를 의미하고, 예외적으로 대표이사 없이 이사의 수가 1인 또는 2인인 소규모 회사의 경우에는 각 이사를 의미한다.","ox":"O","m":"①","c":"A","tp":"소수주주에 의한 주주총회 소집"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-2","t":"소수주주가 상법 제366조에 따라 임시총회 소집에 관한 법원의 허가를 신청할 때 주주총회의 권한에 속하는 결의사항이 아닌 것을 회의 목적사항으로 할 수는 없다.","ox":"O","m":"②","c":"A","tp":"소수주주에 의한 주주총회 소집"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-3","t":"상법 제366조 제1항에서 정한 ‘전자문서’에는 전자우편은 포함되나 휴대전화 문자메시지·모바일 메시지는 포함되지 않는다.","ox":"X","m":"③","c":"A","tp":"소수주주에 의한 주주총회 소집"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-4","t":"법원은 상법 제366조 제2항에 따라 총회의 소집을 구하는 소수주주에게 회의의 목적사항을 정하여 이를 허가할 수 있는데, 법원이 총회의 소집기간을 구체적으로 정하지 않은 경우에 총회소집허가결정일로부터 상당한 기간이 경과하도록 총회가 소집되지 않았다면, 소집허가결정에 따른 소집권한은 특별한 사정이 없는 한 소멸한다.","ox":"O","m":"④","c":"A","tp":"소수주주에 의한 주주총회 소집"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-5","t":"소수주주가 임시총회 소집에 관한 법원의 허가를 신청한 경우, 법원은 직권으로 주주총회의 의장을 선임할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"소수주주에 의한 주주총회 소집"},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40-1","t":"이사직무집행정지가처분을 신청하기 위해서 이사의 지위를 다투는 본안소송이 반드시 제기되어 있어야 하는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"주식회사 이사"},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40-2","t":"이사직무집행정지가처분에 있어서 피신청인이 될 수 있는 자는 그 성질상 당해 이사이고, 회사에게는 피신청인의 적격이 없다.","ox":"O","m":"②","c":"A","tp":"주식회사 이사"},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40-3","t":"이사직무집행정지가처분이 있는 때에는 본점과 지점의 소재지에서 그 등기를 하여야 한다.","ox":"O","m":"③","c":"A","tp":"주식회사 이사"},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40-4","t":"직무대행자가 이사회 구성을 변경하는 행위를 안건으로 하는 임시주주총회를 소집하기 위해서는 법원의 허가가 필요하지만, 이사회 구성을 변경하는 행위를 안건으로 하는 정기주주총회의 소집은 직무대행자가 법원의 허가 없이 할 수 있다.","ox":"X","m":"④","c":"A","tp":"주식회사 이사"},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40-5","t":"대표이사의 직무집행정지 및 직무대행자선임의 가처분이 이루어졌고, 그 후 대표이사가 해임되고 새로운 대표이사가 선임되었어도 그 가처분결정이 취소되지 아니하는 한 새로이 선임된 대표이사는 대표이사로서의 권한을 가지지 못한다.","ox":"O","m":"⑤","c":"A","tp":"주식회사 이사"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-1","t":"감사는 주주총회에서 선임하는데, 의결권 없는 주식을 제외한 발행주식의 총수의 100분의 3을 초과하는 수의 주식을 가진 주주는 그 초과하는 주식에 관하여 감사 선임에서의 의결권을 행사하지 못하는 것이 원칙이다.","ox":"O","m":"①","c":"A","tp":"주식회사의 감사"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-2","t":"주주총회에서 감사 선임결의가 있고, 선임된 사람의 동의가 있었다고 하여 바로 피선임자가 감사의 지위를 취득하게 되는 것은 아니고, 주주총회의 선임결의에 따라 회사의 대표기관이 임용계약의 청약을 하고 피선임자가 이에 승낙을 함으로써 비로소 피선임자가 감사의 지위에 취임하여 그 직무를 수행할 수 있게 된다.","ox":"X","m":"②","c":"A","tp":"주식회사의 감사"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-3","t":"주식회사의 감사는 회사의 필요적 상설기관으로서 회계감사를 비롯하여 이사의 업무집행 전반을 감시할 권한을 갖는 등 상법 기타 법령이나 정관에서 정한 권한과 의무가 있다. 감사는 이러한 권한과 의무를 선량한 관리자의 주의의무를 다하여 이행하여야 하고, 이에 위반하여 그 임무를 해태한 때에는 그로 인하여 회사가 입은 손해를 배상할 책임이 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-4","t":"감사의 소극적인 직무 수행 사유만을 가지고 감사로서의 자격을 부정하거나 주주총회 결의에서 정한 보수청구권의 효력을 부정하기는 어렵다. 다만 보수가 합리적인 수준을 벗어나서 현저히 균형성을 잃을 정도로 과다하거나, 오로지 보수의 지급이라는 형식으로 회사의 자금을 개인에게 지급하기 위한 방편으로 감사로 선임하였다는 등의 특별한 사정이 있는 경우에는 보수청구권의 일부 또는 전부에 대한 행사가 제한되고 회사는 합리적이라고 인정되는 범위를 초과하여 지급된 보수의 반환을 구할 수 있다.","ox":"O","m":"④","c":"A","tp":"주식회사의 감사"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-5","t":"감사는 필요하면 회의의 목적사항과 소집이유를 서면에 적어 이사 또는 소집권자에게 제출하여 이사회 소집을 청구할 수 있다. 이때 이사가 지체 없이 이사회를 소집하지 아니하면 그 청구한 감사가 이사회를 소집할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 감사"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47-1","t":"상법 제398조는 이사 등이 회사와의 거래에 관하여 이사회 승인을 받기 위하여는 이사회에서 해당 거래에 관한 중요사실을 밝히도록 정하고 있으므로, 만일 이러한 사항들을 밝히지 아니한 채 그 거래가 이익상반거래로서 공정한 것인지에 관한 심의가 이루어진 것이 아니라 통상의 거래로서 이를 허용하는 이사회의 결의가 이루어진 것에 불과한 경우 등에는 상법 제398조가 정하는 이사회 승인이 있다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"상법 제398조(이사 등과 회사 간의 거래)"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47-2","t":"甲이 타인의 명의로 乙 회사가 발행한 주식 총수의 10%(의결권 없는 주식 제외)를 소유한 실질주주인 경우에 甲의 시아버지인 丙이 乙 회사와 거래를 하고자 할 때에는 미리 이사회에서 해당 거래에 관한 중요사실을 밝히고 이사회의 승인을 받을 필요가 없다.","ox":"X","m":"②","c":"A","tp":"상법 제398조(이사 등과 회사 간의 거래)"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47-3","t":"자본금 총액이 10억 원 미만으로 이사가 1명 또는 2명인 회사의 이사가 자기 또는 제3자의 계산으로 회사와 거래를 하기 전에 주주총회에서 해당 거래에 관한 중요사실을 밝히고 주주총회의 승인을 받지 않았다면, 특별한 사정이 없는 한 그 거래는 무효라고 보아야 한다.","ox":"O","m":"③","c":"A","tp":"상법 제398조(이사 등과 회사 간의 거래)"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47-4","t":"이사 등이 자기 또는 제3자의 계산으로 회사와 유효하게 거래를 하기 위하여는 미리 상법 제398조에서 정한 이사회 승인을 받아야 하므로 사전에 상법 제398조에서 정한 이사회 승인을 받지 않았다면 특별한 사정이 없는 한 그 거래는 무효라고 보아야 하고, 사후에 그 거래행위에 대하여 이사회 승인을 받았다고 하더라도 특별한 사정이 없는 한 무효인 거래행위가 유효로 되는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"상법 제398조(이사 등과 회사 간의 거래)"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47-5","t":"이사가 회사에 대하여 담보 약정을 하는 경우에는 이사회의 승인을 거칠 필요가 없다.","ox":"O","m":"⑤","c":"A","tp":"상법 제398조(이사 등과 회사 간의 거래)"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-1","t":"대표이사 아닌 이사가 이사회의 소집 결의에 따라서 주주총회를 소집한 것이라면 위 주주총회에 있어서 소집절차상 하자는 주주총회결의의 취소사유에 불과하고 그것만으로 바로 주주총회결의가 무효이거나 부존재가 된다고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"주주총회 소집절차의 하자"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-2","t":"정당한 소집권자에 의하여 소집된 주주총회에서 정족수가 넘는 주주의 출석으로 출석주주 전원의 찬성에 의하여 이루어진 결의라면, 설사 일부 주주에게 소집통지를 하지 아니하였거나 법정기간을 준수하지 아니한 서면통지에 의하여 주주총회가 소집되었다 하더라도 그와 같은 주주총회 소집절차상의 하자는 주주총회결의의 부존재 또는 무효사유가 아니라 취소사유에 불과하다.","ox":"O","m":"②","c":"A","tp":"주주총회 소집절차의 하자"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-3","t":"주주총회의 개회시각이 부득이한 사정으로 당초 소집통지된 시각보다 지연되는 경우에도 사회통념에 비추어 볼 때 정각에 출석한 주주들의 입장에서 변경된 개회시각까지 기다려 참석하는 것이 곤란하지 않을 정도라면 주주총회결의의 부존재 또는 무효사유가 아니라 단순한 취소사유에 불과하다.","ox":"X","m":"③","c":"A","tp":"주주총회 소집절차의 하자"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-4","t":"주주는 자신이 아닌 다른 주주에 대한 소집절차의 하자를 이유로 주주총회결의 취소의 소를 제기할 수 있다.","ox":"O","m":"④","c":"A","tp":"주주총회 소집절차의 하자"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-5","t":"주주총회에서 총회소집 당시 미리 주주에게 통지하지 아니한 회의의 목적사항 이외의 사항에 관한 결의에 가담한 주주가 주주총회 소집절차 또는 결의방법의 하자를 이유로 그 결의의 취소를 구한다고 하여 곧바로 신의성실의 원칙 및 금반언의 원칙에 반한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"주주총회 소집절차의 하자"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30","t":"주주총회 등에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"주주총회 등에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.이사 선임의 주주총회 결의에 대한 취소판결이 확정된 경우 그 판결은 장래에 대하여 형성적 효력이 있으므로, 그 결의에 의하여 선임된 이사들로 구성된 이사회에서 선정된 대표이사가 취소판결 확정 전에 한 행위는 유효하다.\nㄴ.대표이사의 직무집행정지 및 직무대행자선임 가처분이 이루어진 이후 새로운 대표이사가 선임되었다면 새로이 선임된 대표이사는 그 선임결의의 적법 여부에 관계없이 대표이사로서의 권한을 가진다.\nㄷ.회사 설립무효의 판결 또는 주주총회결의 취소의 판결은 제3자에 대하여도 효력이 미친다.\nㄹ.동일한 결의에 관하여 주주총회결의부존재확인의 소가 결의의 날로부터 2월 내에 제기되어 있다면, 동일한 하자를 원인으로 하여 결의의 날로부터 2월이 경과한 후 주주총회결의취소소송으로 소를 변경하거나 추가한 경우에도 제소기간을 준수한 것이다.","o":["ㄱ","ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ"],"a":2}},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45-1","t":"상법 제399조 제1항에 따라 주식회사의 이사가 회사에 대한 임무를 게을리하여 발생한 손해배상책임은 위임관계로 인한 채무불이행책임이다.","ox":"O","m":"①","c":"A","tp":"주식회사에서 이사의 책임 등"},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45-2","t":"주식회사의 이사가 회사에 대하여 상법 제399조 제1항에 따라 손해배상채무를 부담하는 경우 특별한 사정이 없는 한 임무해태로 인하여 손해가 발생한 시점부터 지체책임을 진다.","ox":"X","m":"②","c":"A","tp":"주식회사에서 이사의 책임 등"},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45-3","t":"이사가 임무를 수행하면서 법령을 위반하는 행위를 한 때는 원칙적으로 경영판단의 원칙이 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"주식회사에서 이사의 책임 등"},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45-4","t":"상법 제401조에 의한 이사의 제3자에 대한 손해배상책임의 소멸시효기간은 10년이다.","ox":"O","m":"④","c":"A","tp":"주식회사에서 이사의 책임 등"},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45-5","t":"이사의 고의 또는 과실에 의한 법령 또는 정관에 위반한 행위 또는 임무 해태가 이사회의 결의에 의한 것인 때에는 그 결의에 찬성한 이사도 연대하여 회사에 대하여 손해를 배상할 책임을 진다.","ox":"O","m":"⑤","c":"A","tp":"주식회사에서 이사의 책임 등"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-1","t":"주주총회에서 선임된 이사가 회사와의 명시적 또는 묵시적 약정에 따라 업무를 다른 이사 등에게 포괄적으로 위임하고 이사로서의 실질적인 업무를 수행하지 않는 경우에는 회사를 상대로 주주총회 결의에서 정한 보수를 청구할 수 없다.","ox":"X","m":"①","c":"A","tp":"주식회사의 이사의 보수"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-2","t":"회사에 대한 경영권 상실 등으로 퇴직을 앞둔 이사가 회사에서 최대한 많은 보수를 받기 위하여 그에 동조하는 다른 이사와 함께 이사의 직무내용, 회사의 재무상황이나 영업실적 등에 비추어 지나치게 과다하여 합리적 수준을 현저히 벗어나는 보수 지급 기준을 마련하고 지위를 이용하여 주주총회에 영향력을 행사함으로써 소수주주의 반대에 불구하고 이에 관한 주주총회 결의가 성립되도록 하였다면, 이는 회사를 위하여 직무를 충실하게 수행하여야 하는 상법 제382조의3에서 정한 의무를 위반하여 회사재산의 부당한 유출을 야기함으로써 회사와 주주의 이익을 침해하는 것으로서 회사에 대한 배임행위에 해당하므로, 주주총회 결의를 거쳤다 하더라도 그러한 위법행위가 유효하다 할 수는 없다.","ox":"O","m":"②","c":"A","tp":"주식회사의 이사의 보수"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-3","t":"정관 등에서 이사의 퇴직금에 관하여 주주총회의 결의로 정한다고 규정하면서 퇴직금의 액수에 관하여만 정하고 있다면, 퇴직금 중간정산에 관한 주주총회의 결의가 있었음을 인정할 증거가 없는 한 이사는 퇴직금 중간정산금 청구권을 행사할 수 없다.","ox":"O","m":"③","c":"A","tp":"주식회사의 이사의 보수"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-4","t":"회사가 정관에서 이사의 퇴직금 지급에 관하여 주주총회의 결의를 거친 임원퇴직금 지급규정에 의한다고 규정하면서 그와 함께 퇴직하는 이사에 대한 퇴직금액의 하한을 구체적으로 정하고 있다면, 주주총회에서 이사의 퇴직금 지급에 관한 규정을 만들지 않거나 퇴직금에 관한 결의를 하지 않았다 하더라도 회사로서는 그와 같은 주주총회 결의 등이 없었음을 이유로 퇴직한 이사에 대하여 정관에 구체적으로 정한 하한의 범위 안에서의 퇴직금의 지급을 거절할 수는 없다.","ox":"O","m":"④","c":"A","tp":"주식회사의 이사의 보수"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-5","t":"주식회사와 이사 사이에 체결된 고용계약에서 이사가 그 의사에 반하여 이사직에서 해임될 경우 퇴직위로금과는 별도로 일정한 금액의 해직보상금을 지급받기로 약정한 경우, 이사의 보수에 관한 상법 제388조를 준용 내지 유추적용하여 이사는 해직보상금에 관하여도 정관에서 그 액을 정하지 않는 한 주주총회 결의가 있어야만 회사에 대하여 이를 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 이사의 보수"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-1","t":"이사는 회사의 위임에 따라 회사에 대하여 수임자로서 선량한 관리자의 주의의무를 지므로 제3자에게 손해배상책임을 지는 경우는 없다.","ox":"X","m":"①","c":"A","tp":"이사의 책임"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-2","t":"이사의 임무는 단지 이사회에 상정된 의안에 대하여 찬부의 의사표시를 하는 데에 그치지 않고 대표이사를 비롯한 업무담당이사의 전반적인 업무집행을 감시할 수 있는 것이다.","ox":"O","m":"②","c":"A","tp":"이사의 책임"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-3","t":"이사가 대표이사나 다른 이사의 업무집행이 위법하거나 선관주의의무나 충실의무를 위반하였다고 의심할 만한 사유가 있음에도 감시의무를 위반하여 이를 방치한 때에는 이로 말미암아 회사가 입은 손해에 대하여 배상책임을 면할 수 없다.","ox":"O","m":"③","c":"A","tp":"이사의 책임"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-4","t":"일정한 업무분장 하에 회사의 일상적인 업무를 집행하는 업무집행이사는 회사의 업무집행을 전혀 담당하지 아니하는 평이사에 비하여 보다 높은 주의의무를 부담한다.","ox":"O","m":"④","c":"A","tp":"이사의 책임"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-5","t":"이사의 감시의무의 구체적인 내용은 회사의 규모나 조직, 업종, 법령의 규제, 영업상황 및 재무상태에 따라 크게 다를 수 있으므로 고도로 분업화되고 전문화된 대규모의 회사라고 하더라도 다른 이사들의 업무집행에 관한 감시의무를 면할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"이사의 책임"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34-1","t":"상법 제401조의2에서 이사가 아니면서 명예회장·회장·사장·부사장·전무·상무·이사 기타 회사의 업무를 집행할 권한이 있는 것으로 인정될 만한 명칭을 사용하여 회사의 업무를 집행한 자 등에 대해서는 회사에 대한 책임이 있는 경우 이사로 보도록 하는 것은, 주식회사의 이사가 아니지만 이사에게 업무집행을 지시하거나 이사처럼 업무를 집행하는 등으로 회사의 업무에 관여한 자에 대하여 그에 상응하는 책임을 묻기 위한 것이다.","ox":"O","m":"①","c":"A","tp":"업무집행지시자 등의 책임(상법 제401조의2)"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34-2","t":"상법 제401조의2 제1항 각호에 해당하는 자는 회사의 이사는 아니지만 상법 제399조에서 정한 손해배상책임을 적용함에 있어 그가 관여한 업무에 관하여 법령준수의무를 비롯하여 이사와 같은 선관주의의무와 충실의무를 부담하고, 이를 게을리하였을 경우 회사에 대하여 그로 인한 손해배상책임을 지게 된다.","ox":"O","m":"②","c":"A","tp":"업무집행지시자 등의 책임(상법 제401조의2)"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34-3","t":"회사의 대주주 겸 회장으로서 회사의 실제 전반적인 운영을 담당한 자가 회사에 대한 업무상횡령범행을 저질러 유죄판결을 받았다면, 회사에 대하여 손해배상책임을 부담할 수 있다.","ox":"O","m":"③","c":"A","tp":"업무집행지시자 등의 책임(상법 제401조의2)"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34-4","t":"상법 제401조의2 제1항이 정한 손해배상책임은 상법에 의하여 이사로 의제되는 데 따른 책임이므로 그에 따른 손해배상채권에도 일반 불법행위책임의 단기소멸시효를 규정한 민법 제766조 제1항이 적용된다.","ox":"X","m":"④","c":"A","tp":"업무집행지시자 등의 책임(상법 제401조의2)"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34-5","t":"상법 제401조의2 제1항 제1호의 ‘회사에 대한 자신의 영향력을 이용하여 이사에게 업무집행을 지시한 자’에는 자연인뿐만 아니라 법인인 지배회사도 포함된다.","ox":"O","m":"⑤","c":"A","tp":"업무집행지시자 등의 책임(상법 제401조의2)"},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43-1","t":"법률 또는 정관에 정한 이사의 원수를 결한 경우에는 임기의 만료 또는 사임으로 인하여 퇴임한 이사는 새로 선임된 이사가 취임할 때까지 이사의 권리의무가 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43-2","t":"임기만료 후 이사로서의 권리의무를 행사하고 있는 퇴임이사는 새로 선임된 이사가 취임하거나 상법 제386조 제2항에 따라 일시 이사의 직무를 행할 자가 선임되면 별도의 주주총회 해임결의를 거치지 않더라도 이사로서의 권리의무를 상실한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43-3","t":"임기의 만료나 사임에 의하여 퇴임한 이사가 그 퇴임으로 법률 또는 정관에 정한 이사의 원수를 채우지 못하게 되어 후임이사의 취임시까지 이사로서의 권리의무를 유지하게 되는 경우에도, 이사의 퇴임으로 인한 변경등기기간의 기산일은 후임이사의 취임일이 아니라 퇴임한 이사의 퇴임일부터 기산하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43-4","t":"임기만료 후 이사로서의 권리의무를 행사하고 있는 퇴임이사는 상법 제385조 제1항의 해임대상이 되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43-5","t":"법인등기부에 이사 또는 감사로 등재되어 있는 경우에는 특단의 사정이 없는 한 정당한 절차에 의하여 선임된 적법한 이사 또는 감사로 추정된다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-1","t":"회사가 대표이사의 딸과 부동산에 관한 매매계약을 체결하기 위해서는 미리 이사회에서 해당 거래에 관한 중요사실을 밝히고 이사회의 승인을 받아야 한다.","ox":"O","m":"①","c":"A","tp":"이사 등의 자기거래 및 그 승인"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-2","t":"이사 등과 회사 사이의 거래에 관하여 상법 제398조에 따라 이사회의 승인을 받아야 하는 경우 이사회의 승인은 이사 3분의 2 이상의 수로써 하여야 하고, 그 거래의 내용과 절차는 공정하여야 한다.","ox":"O","m":"②","c":"A","tp":"이사 등의 자기거래 및 그 승인"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-3","t":"이사 등이 자기 또는 제3자의 계산으로 회사와 거래를 하면서 사전에 상법 제398조에서 정한 이사회 승인을 받지 않은 경우라고 하더라도, 사후에 거래행위에 대하여 이사회 승인을 받은 경우라면 원칙적으로 무효인 거래행위가 유효가 된다.","ox":"X","m":"③","c":"A","tp":"이사 등의 자기거래 및 그 승인"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-4","t":"이사 등과 회사의 거래에 관하여 이사회의 승인이 있었더라도, 해당 거래에 관한 중요사실 등을 밝히지 아니한 채 그 거래가 이익상반거래로서 공정한 것인지에 관한 심의가 이루어진 것이 아니라 통상의 거래로서 이를 허용하는 이사회의 결의가 이루어진 것에 불과한 경우 등에는 상법 제398조가 정하는 이사회 승인이 있다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"이사 등의 자기거래 및 그 승인"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-5","t":"별개인 두 회사의 대표이사를 겸하고 있는 자가 두 회사 사이의 매매계약을 체결한 경우에도 이사의 자기거래에 해당한다.","ox":"O","m":"⑤","c":"A","tp":"이사 등의 자기거래 및 그 승인"},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46-1","t":"이사는 법령 또는 정관에 정해진 목적 범위 내에서 회사의 경영에 관한 판단을 할 재량권을 가지고 있고, 기업의 경영에는 위험이 수반될 수 있으므로, 이사가 법령에 위반됨이 없이 임무를 수행하는 과정에서 합리적으로 이용가능한 범위 내에서 필요한 정보를 충분히 수집·조사하고 검토하는 절차를 거친 다음, 이를 근거로 회사의 최대 이익에 부합한다고 합리적으로 신뢰하고 신의성실에 따라 경영상의 판단을 내렸고, 그 내용이 현저히 불합리하지 않은 것으로서 통상의 이사를 기준으로 할 때 합리적으로 선택할 수 있는 범위 안에 있는 것이라면, 비록 사후에 그 회사가 예상했던 이익을 얻지 못하고 손해를 입게 되는 결과가 발생하였다 하더라도 그 이사의 행위는 허용되는 경영판단의 재량 범위 내에 있는 것이어서 해당 회사에 대하여 손해배상책임을 부담한다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"경영판단의 원칙과 이사의 책임"},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46-2","t":"이사의 경영판단을 정당화할 수 있는 이익은 원칙적으로 회사가 실제로 얻을 가능성이 있는 구체적인 것이어야 하고, 일반적이거나 막연한 기대에 불과하여 회사가 부담하는 비용이나 위험에 상응하지 않는 것이어서는 안 된다.","ox":"O","m":"②","c":"A","tp":"경영판단의 원칙과 이사의 책임"},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46-3","t":"이사가 임무를 수행하면서 검토할 사항은 거래를 하는 목적이나 동기, 거래의 종류와 내용, 상대방과의 관계, 소속 회사의 재무적 상황 등에 따라 달라지므로, 사안마다 개별적으로 판단되어야 한다.","ox":"O","m":"③","c":"A","tp":"경영판단의 원칙과 이사의 책임"},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46-4","t":"이사가 임무를 수행함에 있어서 법령을 위반한 행위를 한 때에는 그 행위 자체가 회사에 대하여 채무불이행에 해당한다고 볼 수 있으나, 이사가 회사의 자금으로 뇌물을 공여함으로써 회사가 결과적으로 상당한 이익을 얻은 경우와 같이 회사가 궁극적으로 이익을 얻었다고 볼 수 있는 경우라면, 경영판단의 원칙이 예외적으로 적용될 수 있다.","ox":"X","m":"④","c":"A","tp":"경영판단의 원칙과 이사의 책임"},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46-5","t":"이사가 합리적으로 이용가능한 범위 내에서 필요한 정보를 충분히 수집·조사하고 검토하는 절차를 거치지 않고 단순히 회사의 경영상의 부담에도 불구하고 관계회사의 부도 등을 방지하는 것이 회사의 신인도를 유지하고 회사의 영업에 이익이 될 것이라는 일반적·추상적인 기대하에 일방적으로 관계회사에 자금을 지원하게 하여 회사에 손해를 입게 한 경우에 불과하다면 이러한 이사의 행위는 허용되는 경영판단의 재량범위 내에 있는 것이라고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"경영판단의 원칙과 이사의 책임"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-1","t":"주식회사의 주주는 상법 제368조 제2항에 따라 타인에게 의결권 행사를 위임하거나 대리행사하도록 할 수 있다. 이 경우 의결권의 행사를 구체적이고 개별적인 사항에 국한하여 위임하여야 하고 포괄적으로 위임하는 것은 허용되지 않는다.","ox":"X","m":"①","c":"A","tp":"의결권의 대리행사 및 불통일행사"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-2","t":"상법 제368조 제2항의 규정은 대리권의 존부에 관한 법률관계를 명확히 하여 주주총회 결의의 성립을 원활하게 하기 위한 데 그 목적이 있다고 할 것이므로 대리권을 증명하는 서면은 위조나 변조 여부를 쉽게 식별할 수 있는 원본이어야 하고, 특별한 사정이 없는 한 사본은 그 서면에 해당하지 아니하고, 팩스를 통하여 출력된 팩스본 위임장 역시 성질상 원본으로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"의결권의 대리행사 및 불통일행사"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-3","t":"상법 제368조 제2항이 규정하는 ‘대리권을 증명하는 서면’이라 함은 위임장을 일컫는 것으로서 회사가 위임장과 함께 인감증명서, 참석장 등을 제출하도록 요구하는 것은 대리인의 자격을 보다 확실하게 확인하기 위하여 요구하는 것일 뿐, 이러한 서류 등을 지참하지 아니하였다 하더라도 주주 또는 대리인이 다른 방법으로 위임장의 진정성 내지 위임의 사실을 증명할 수 있다면 회사는 그 대리권을 부정할 수 없다.","ox":"O","m":"③","c":"A","tp":"의결권의 대리행사 및 불통일행사"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-4","t":"상법 제368조 제2항의 규정은 주주의 대리인의 자격을 제한할 만한 합리적인 이유가 있는 경우 정관의 규정에 의하여 상당하다고 인정되는 정도의 제한을 가하는 것까지 금지하는 취지는 아니라고 해석되는바, 대리인의 자격을 주주로 한정하는 취지의 주식회사의 정관 규정은 주주총회가 주주 이외의 제3자에 의하여 교란되는 것을 방지하여 회사 이익을 보호하는 취지에서 마련된 것으로서 합리적인 이유에 의한 상당한 정도의 제한이라고 볼 수 있으므로 이를 무효라고 볼 수는 없다.","ox":"O","m":"④","c":"A","tp":"의결권의 대리행사 및 불통일행사"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-5","t":"상법 제368조의2 제1항은 “주주가 2 이상의 의결권을 가지고 있는 때에는 이를 통일하지 아니하고 행사할 수 있다. 이 경우 주주총회일의 3일 전에 회사에 대하여 서면 또는 전자문서로 그 뜻과 이유를 통지하여야 한다.”고 규정하고 있는바, 여기서 3일의 기간이라 함은 의결권의 불통일행사가 행하여지는 경우에 회사 측에 그 불통일행사를 거부할 것인가를 판단할 수 있는 시간적 여유를 주고, 회사의 총회 사무운영에 지장을 주지 아니하도록 하기 위하여 부여된 기간으로서, 그 불통일행사의 통지는 원칙적으로 주주총회일의 3일 전에 회사에 도달할 것을 요한다.","ox":"O","m":"⑤","c":"A","tp":"의결권의 대리행사 및 불통일행사"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-1","t":"상법 제395조는 표현대표이사가 자기의 명칭을 사용하여 법률행위를 한 경우는 물론이고, 자기의 명칭을 사용하지 아니하고 다른 대표이사의 명칭을 사용하여 행위를 한 경우에도 유추적용된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-2","t":"회사를 대표할 권한이 없는 표현대표이사가 다른 대표이사의 명칭을 사용하여 어음행위를 한 경우, 회사가 책임을 지는 선의의 제3자의 범위에는 표현대표이사로부터 직접 어음을 취득한 상대방뿐만 아니라, 그로부터 어음을 다시 배서양도 받은 제3취득자도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-3","t":"상법 제395조가 규정하는 표현대표이사의 행위로 인한 주식회사의 책임이 성립하기 위하여는 제3자의 선의 이외에 무과실까지도 필요로 한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-4","t":"상법 제395조에서 말하는 ‘선의’란 표현대표이사가 대표권이 없음을 알지 못한 것을 말하는 것이지 반드시 형식상 대표이사가 아니라는 것을 알지 못한 것에 한정할 필요는 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-5","t":"상법 제395조는 이사의 자격이 없는 사람이 임의로 표현대표이사의 명칭을 사용하고 있는 것을 회사가 알면서도 아무런 조치를 취하지 아니한 채 그대로 방치하여 소극적으로 묵인한 경우에도 유추적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30-1","t":"상법 제369조 제1항에서 주식회사의 주주는 1주마다 1개의 의결권을 가진다고 하는 1주 1의결권의 원칙을 규정하고 있는바, 이는 정관이나 주주총회의 결의로 달리 정할 수 있다.","ox":"X","m":"①","c":"A","tp":"주주의 의결권"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30-2","t":"주주총회가 재무제표를 승인한 후 2년 내에 이사와 감사의 책임을 추궁하는 결의를 하는 경우, 당해 이사와 감사인 주주는 그 결의에 관한 특별이해관계인에 해당하여 의결권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"주주의 의결권"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30-3","t":"의결권 없는 주식을 제외한 발행주식의 총수의 100분의 3(정관에서 더 낮은 주식 보유비율을 정할 수 있으며, 정관에서 더 낮은 주식 보유비율을 정한 경우에는 그 비율)을 초과하는 수의 주식을 가진 주주는 그 초과하는 주식에 관하여 감사의 선임에 있어서는 의결권을 행사하지 못한다.","ox":"O","m":"③","c":"A","tp":"주주의 의결권"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30-4","t":"주주의 자유로운 의결권 행사를 보장하기 위하여 주주가 의결권의 행사를 대리인에게 위임하는 것이 보장되어야 한다고 하더라도, 그 의결권의 대리행사로 말미암아 주주총회의 개최가 부당하게 저해되거나 혹은 회사의 이익이 부당하게 침해될 염려가 있는 등의 특별한 사정이 있는 경우에는 회사는 이를 거절할 수 있다.","ox":"O","m":"④","c":"A","tp":"주주의 의결권"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30-5","t":"상법 제368조의2 제1항은 “주주가 2 이상의 의결권을 가지고 있는 때에는 이를 통일하지 아니하고 행사할 수 있다. 이 경우 주주총회일의 3일 전에 회사에 대하여 서면 또는 전자문서로 그 뜻과 이유를 통지하여야 한다.”라고 정하고 있는데, 불통일행사의 통지가 주주총회일의 3일 전이라는 시한보다 늦게 도착하였다고 하더라도 회사가 스스로 총회운영에 지장이 없다고 판단하여 이를 받아들이기로 하고 이에 따라 의결권의 불통일행사가 이루어진 것이라면, 특별한 사정이 없는 한 그와 같은 의결권의 불통일행사를 위법하다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"주주의 의결권"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-1","t":"이해관계 있는 이사는 이사회에서 의결권을 행사할 수는 없으나, 의사정족수 산정의 기초가 되는 이사의 수에는 포함되고, 다만 결의성립에 필요한 출석이사에는 산입되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-2","t":"이사회는 주주총회의 경우와는 달리 원칙적으로 이사 자신이 직접 출석하여 결의에 참가하여야 하며 대리인에 의한 출석은 인정되지 않고 따라서 이사가 타인에게 출석과 의결권을 위임할 수도 없는 것이니 이에 위배된 이사회의 결의는 무효이다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-3","t":"이사회의 결의에 하자가 있는 경우에 관하여 상법은 아무런 규정을 두고 있지 아니하나, 그 결의에 무효사유가 있는 경우에는 이해관계인은 언제든지 무효확인의 소를 제기하거나 다른 소에서 공격방어방법으로 이사회결의의 무효를 주장할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-4","t":"이사회결의 무효주장의 방법으로서 이사회결의무효확인소송이 제기되어 승소확정판결을 받은 경우, 그 판결의 효력에 관하여는 주주총회결의무효확인소송에 준하여, 대세적 효력이 인정된다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-5","t":"주식회사 정관이나 이사회 규정 등에서 이사회결의를 거치도록 대표이사의 대표권을 제한하였음에도, 대표이사가 이사회결의 없이 제3자와 대외적 거래를 한 경우, 제3자가 이사회결의가 없음을 알았거나 중과실로 알지 못한 경우라면, 그 거래행위는 무효에 해당한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-1","t":"발행주식 총수의 100분의 1 이상에 해당하는 주식을 가진 주주는 그 이유를 기재한 서면으로 회사에 대하여 이사의 책임을 추궁할 소의 제기를 청구할 수 있는데, 서면에 기재되어야 하는 ‘이유’에는 책임추궁 대상 이사, 책임발생 원인사실에 관한 상세하고 구체적인 내용이 포함되어야 하고, 책임추궁 대상 이사의 성명이 기재되어 있지 않거나 책임발생 원인사실이 개략적으로 기재되어 있다면, 이 요건을 충족하였다고 볼 수 없다.","ox":"X","m":"①","c":"A","tp":"대표소송"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-2","t":"주주가 대표소송을 제기하기 위하여는 회사에 대하여 이사의 책임을 추궁할 소의 제기를 청구할 때와 회사를 위하여 그 소를 제기할 때 상법이 정하는 주식보유요건을 갖추면 되고, 소제기 후에는 보유주식의 수가 그 요건에 미달하게 되어도 원칙적으로 무방하다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-3","t":"대표소송을 제기한 주주가 소송의 계속 중에 주식을 전혀 보유하지 아니하게 되어 주주의 지위를 상실하면, 특별한 사정이 없는 한 그 주주는 원고적격을 상실하여 그가 제기한 소는 부적법하게 되고, 이는 그 주주가 자신의 의사에 반하여 주주의 지위를 상실하였다 하여 달리 볼 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-4","t":"주주의 대표소송이 제소요건을 갖추지 못한 채 소가 제기되었다고 하더라도, 주주로부터 소의 제기를 청구받은 회사가 이사의 책임을 추궁할 소를 제기하지 않을 의사를 명시적으로 밝히는 등 주주의 제소청구에 응하지 않으리라는 특별한 사정이 인정된다면, 이러한 경우까지 그 주주대표소송이 부적법하다고 보는 것은 소송경제에 반하므로 그 하자가 치유된다고 봄이 타당하다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-5","t":"주식회사의 주주는 주식의 소유자로서 회사의 경영에 이해관계를 가지고 있기는 하지만, 직접 회사의 경영에 참여하지 못하고 주주총회의 결의를 통해서 이사를 해임하거나 일정한 요건에 따라 이사를 상대로 그 이사의 행위에 대하여 유지청구권을 행사하여 그 행위를 유지시키고 대표소송에 의하여 그 책임을 추궁하는 소를 제기하는 등 회사의 영업에 간접적으로 영향을 미칠 수 있을 뿐이다. 그러므로 주주가 회사의 재산관계에 대하여 법률상 이해관계를 가진다고 평가할 수 없고, 주주는 직접 제3자와의 거래관계에 개입하여 회사가 체결한 계약의 무효 확인을 구할 이익이 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38","t":"주식회사의 이사의 보수에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"주식회사의 이사의 보수에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["이사의 보수는 정관에 그 액을 정하지 아니한 때에는 주주총회의 결의로 이를 정한다.","상법에 따라 주주총회에서 이사의 보수에 관하여 결의할 때 정관에 다른 정함이 있는 경우를 제외하고는 출석한 주주의 의결권의 과반수와 발행주식총수의 4분의 1 이상의 수가 필요하다.","상법 제388조에 따라 주주총회에서 이사의 보수에 관하여 결의할 때, 특별한 사정이 없는 한 주주인 동시에 이사인 자는 특별한 이해관계 있는 자로서 총회에서 의결권을 행사할 수 없다.","위 ③항의 경우 특별이해관계 있는 주주가 가진 주식의 의결권 수는 상법 제371조 제2항에 따라 ‘출석한 주주의 의결권의 수’에 산입되지 아니한다.","반면, 위 ③항의 경우 특별이해관계 있는 주주가 가진 주식의 의결권 수는 상법 제368조 제1항의 정족수 계산의 기초가 되는 ‘발행주식의 총수’에는 산입된다."],"a":5}},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-1","t":"대부분의 주주에게 소집통지를 발송하지 아니하고 개최된 주주총회는 특별한 사정이 없는 한 그 성립과정의 하자가 너무나도 중대하여 사회통념상 총회 자체의 성립이 인정되기 어렵다.","ox":"O","m":"①","c":"A","tp":"주주총회결의"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-2","t":"주주 사이에 체결된 이른바 의결권구속약정, 즉 주주의 주주총회 의결권 행사를 제한하는 내용의 약정은 계약의 일반원칙에 따라 그 내용이나 목적이 강행규정 또는 사회질서 등에 반하지 않는 한 계약의 당사자 사이에서는 원칙적으로 유효하다. 그러나 의결권구속약정의 효력은 주주권의 내용 등 회사의 단체법적 질서에는 영향을 미칠 수 없으므로, 의결권구속약정의 당사자가 약정을 위반하여 주주총회 의결권을 행사함에 따라 주주총회결의가 성립된 경우 약정의 다른 당사자는 회사를 상대로 약정 위반을 주장하며 주주총회결의의 하자를 다툴 수 없고, 다만 약정을 위반한 당사자를 상대로 계약에 근거한 권리를 행사할 수 있을 뿐이다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-3","t":"주식회사가 적법한 절차에 따라 소집, 의결한 주주총회에서 하자 있는 종전의 결의를 그대로 추인하거나 재차 동일한 안건에 대한 결의를 한 경우에는, 그 새로운 주주총회의 결의가 다른 절차상, 내용상의 하자로 인하여 부존재 또는 무효임이 인정되거나 그 결의가 취소되는 등의 특별한 사정이 없는 한, 설령 종전의 결의에 어떠한 하자가 있었다고 할지라도 종전의 하자 있는 결의에 대하여 부존재나 무효확인 또는 그 취소를 구할 소의 이익이 없다.","ox":"O","m":"③","c":"A","tp":"주주총회결의"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-4","t":"주주총회를 소집할 권한이 없는 자가 이사회의 주주총회 소집결정도 없이 소집한 주주총회에서 이루어진 결의는 특별한 사정이 없는 한 취소사유가 있는 것으로 보아야 한다.","ox":"X","m":"④","c":"A","tp":"주주총회결의"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-5","t":"주식회사의 총주식을 한 사람이 소유하는 이른바 1인회사의 경우에는 그 주주가 유일한 주주로서 주주총회에 출석하면 전원 총회로서 성립하고 그 주주의 의사대로 결의가 될 것이 명백하다. 이러한 이유로 주주총회 소집절차에 하자가 있거나 주주총회의사록이 작성되지 않았더라도, 1인주주의 의사가 주주총회의 결의내용과 일치한다면 증거에 의하여 그러한 내용의 결의가 있었던 것으로 볼 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주주총회결의"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-1","t":"이사가 고의 또는 과실로 법령 또는 정관에 위반한 행위를 하거나 그 임무를 게을리한 경우에는 그 이사는 회사에 대하여 연대하여 손해를 배상할 책임이 있다.","ox":"O","m":"①","c":"A","tp":"주식회사의 이사의 의무"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-2","t":"이사의 고의 또는 과실에 의한 법령위반 행위 등이 이사회 결의에 따른 것이라면, 결의에 찬성한 이사도 회사에 대해 책임을 지는데, 이사회의사록에 특정 이사가 해당 결의에 기권한 것으로 기재되어 있는 경우 해당 이사는 그 결의에 찬성한 것으로 추정된다.","ox":"X","m":"②","c":"A","tp":"주식회사의 이사의 의무"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-3","t":"이사는 대표이사나 다른 이사가 선량한 관리자의 주의로써 직무를 수행하는지, 법령과 정관의 규정에 따라 회사를 위하여 직무를 충실하게 수행하는지를 감시·감독하여야 할 의무를 부담한다.","ox":"O","m":"③","c":"A","tp":"주식회사의 이사의 의무"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-4","t":"기업집단을 구성하는 개별 계열회사들은 각자 독립된 법인격을 가진 별개의 회사이므로, 개별 계열회사의 이사는 기업집단이나 다른 계열회사와 관련된 직무를 수행할 때에도 선관주의의무와 충실의무를 부담한다.","ox":"O","m":"④","c":"A","tp":"주식회사의 이사의 의무"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-5","t":"이사의 경영판단을 정당화할 수 있는 이익은 원칙적으로 회사가 실제로 얻을 가능성이 있는 구체적인 것이어야 하고, 일반적이거나 막연한 기대에 불과하여 회사가 부담하는 비용이나 위험에 상응하지 않는 것이어서는 아니 된다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 이사의 의무"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49-1","t":"주주총회결의의 부존재 또는 무효 확인을 구하는 소의 인용판결은 제3자에 대해 효력이 있으므로, 이 소를 여러 사람이 공동으로 제기한 경우 인용판결의 대세효로 인해 공동소송인 사이에 소송법상 합일확정의 필요성이 없다. 따라서 이러한 소송은 통상공동소송에 해당한다.","ox":"X","m":"①","c":"A","tp":"주식회사와 관련된 소송"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49-2","t":"주주가 주주총회의 하자를 다투는 소송을 제기함에 있어 남소를 방지하기 위해 상법은 회사가 법원에 담보제공명령을 청구할 수 있도록 정하고 있다.","ox":"O","m":"②","c":"A","tp":"주식회사와 관련된 소송"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49-3","t":"주주총회결의 부존재 확인의 소는 제소권자의 제한이 없으므로 결의의 부존재의 확인에 관하여 정당한 법률상 이익이 있는 자라면 원칙적으로 누구나 소송으로써 그 확인을 구할 수 있다.","ox":"O","m":"③","c":"A","tp":"주식회사와 관련된 소송"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49-4","t":"이사가 그 지위에 기하여 주주총회결의 취소의 소를 제기하였다가 소송계속 중에 사망하였거나 사실심 변론종결 후에 사망하였다면, 그 소송은 이사의 사망으로 중단되지 않고 그대로 종료된다.","ox":"O","m":"④","c":"A","tp":"주식회사와 관련된 소송"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49-5","t":"이사 선임의 주주총회결의에 대한 취소판결이 확정된 경우 그 결의에 의하여 이사로 선임된 이사들에 의하여 구성된 이사회에서 선정된 대표이사는 소급하여 그 자격을 상실하고, 그 대표이사가 이사 선임의 주주총회결의에 대한 취소판결이 확정되기 전에 한 행위는 대표권이 없는 자가 한 행위로서 무효가 된다.","ox":"O","m":"⑤","c":"A","tp":"주식회사와 관련된 소송"}],"12":[{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-1","t":"한국의 선박회사로서 선박의 실제 소유자인 甲회사가 해운기업상의 편의를 위하여 선적국인 외국에 형식상 乙회사를 설립하였으나, 실제로는 사무실과 경영진 등이 동일한 경우 乙회사가 법률의 적용을 회피하기 위하여 甲회사와는 별개의 법인격을 가지는 회사라는 주장을 내세우는 것은 신의성실의 원칙에 위반하거나 법인격을 남용하는 것으로 허용될 수 없다.","ox":"O","m":"①","c":"A","tp":"회사의 법인격이 남용된 경우"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-2","t":"기존회사가 채무를 면탈할 목적으로 기업의 형태·내용이 실질적으로 동일한 신설회사를 설립하였다면, 신설회사의 설립은 기존회사의 채무면탈이라는 위법한 목적달성을 위하여 회사제도를 남용한 것이므로, 기존회사의 채권자에 대하여 위 두 회사가 별개의 법인격을 갖고 있음을 주장하는 것은 신의성실의 원칙상 허용될 수 없고 기존회사의 채권자는 위 두 회사 어느 쪽에 대하여서도 채무의 이행을 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"회사의 법인격이 남용된 경우"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-3","t":"甲회사가 乙회사와 기업의 형태와 내용이 실질적으로 동일하고 乙회사의 채무를 면탈할 목적으로 설립된 것으로 법인격을 남용하였다 하더라도 소송절차 및 강제집행절차에서는 그 절차의 성격상 판결의 기판력 및 집행력의 범위를 乙회사에까지 확장하는 것은 허용되지 아니한다.","ox":"O","m":"③","c":"A","tp":"회사의 법인격이 남용된 경우"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-4","t":"친자회사 관계에서 母회사가 子회사의 임·직원의 신분을 겸유하고 있거나 子회사의 전 주식을 소유하여 子회사에 대한 강한 지배력을 가지는 경우에는 법인격 남용에 해당한다.","ox":"X","m":"④","c":"A","tp":"회사의 법인격이 남용된 경우"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-5","t":"특수목적회사(SPC)는 일시적인 목적을 달성하기 위하여 최소한의 자본출자요건만을 갖추어 설립되는 것이 일반적인데, 법인격 남용을 인정하려면 적어도 특수목적회사의 법인격이 배후자에 대한 법률적용을 회피하기 위한 수단으로 함부로 이용되거나, 채무면탈, 계약상 채무의 회피, 탈법행위 등 위법한 목적달성을 위하여 회사제도를 남용하는 등의 주관적 의도 또는 목적이 인정되는 경우라야 한다.","ox":"O","m":"⑤","c":"A","tp":"회사의 법인격이 남용된 경우"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-1","t":"주식회사를 설립하려면 5,000만 원 이상의 자본금이 있어야 한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-2","t":"회사는 정관으로 정하는 바에 따라 발행된 액면주식을 무액면주식으로 전환하거나 무액면주식을 액면주식으로 전환할 수 있다.","ox":"O","m":"②","c":"A","tp":"주식회사"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-3","t":"주주의 책임은 그가 가진 주식의 인수가액을 한도로 한다.","ox":"O","m":"③","c":"A","tp":"주식회사"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-4","t":"정관에서 정하는 수권주식의 규모에는 제한이 없다.","ox":"O","m":"④","c":"A","tp":"주식회사"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-5","t":"타인의 승낙을 얻어 그 명의로 주식을 인수한 자는 그 타인과 연대하여 납입할 책임이 있다.","ox":"O","m":"⑤","c":"A","tp":"주식회사"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-1","t":"발기인이 회사의 설립 시에 발행하는 주식의 총수를 인수한 때에는 지체 없이 각 주식에 대하여 그 인수가액의 전액을 납입하여야 한다. 이 경우 발기인은 납입을 맡을 은행 기타 금융기관과 납입장소를 지정하여야 한다.","ox":"O","m":"①","c":"A","tp":"주식회사의 설립"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-2","t":"발기설립의 정관은 반드시 공증인의 인증을 받음으로써 효력이 생긴다.","ox":"X","m":"②","c":"A","tp":"주식회사의 설립"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-3","t":"모집설립의 경우 주식의 인수인이 출자를 이행하지 않으면 실권절차가 있다.","ox":"O","m":"③","c":"A","tp":"주식회사의 설립"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-4","t":"모집설립의 경우 창립총회의 결의는 출석한 주식인수인의 의결권의 3분의 2 이상이며 인수된 주식의 총수의 과반수에 해당하는 다수로 하여야 한다.","ox":"O","m":"④","c":"A","tp":"주식회사의 설립"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-5","t":"발기설립이든 모집설립이든 상법 제317조의 설립등기를 완료함으로써 설립절차가 종료된다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 설립"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31-1","t":"주식회사를 설립하면서 일시적인 차입금으로 주금납입의 외형을 갖추고 회사 설립절차를 마친 다음 바로 그 납입금을 인출하여 차입금을 변제하는 이른바 가장납입의 경우에도 주금납입의 효력을 부인할 수는 없다고 할 것이어서 주식인수인이나 주주의 주금납입의무도 종결되었다고 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31-2","t":"주식회사의 자본충실의 요청상 주금을 납입하기 전에 명의대여자 및 명의차용자 모두에게 주금납입의 연대책임을 부과하는 규정인 상법 제332조 제2항은 이미 주금납입의 효력이 발생한 주금의 가장납입의 경우에는 적용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31-3","t":"회사가 대여금을 실질적으로 회수할 의사 없이 제3자에게 주식인수대금 상당을 대여하고 제3자는 그 대여금으로 주식인수대금을 납입한 경우 그 납입의 효력은 무효이다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31-4","t":"주식회사의 설립업무를 담당한 자가 주금납입취급은행 이외의 제3자로부터 납입금에 해당하는 금액을 차입하여 주금을 납입하고 회사의 설립등기를 마친 직후 이를 인출하여 위 차용채무의 변제에 사용한 경우에, 그 주금납입은 회사에 대하여 유효하고 그 주금의 납입 즉시 그 납입금은 회사의 재산으로 되는 것이므로, 이와 같은 인출행위는 상법상 주금가장납입죄에 해당하는 것과는 별도로 회사재산의 불법영득 행위로서 횡령죄를 구성한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31-5","t":"신주발행의 실체가 존재한다고 할 수 없는 경우, 납입가장죄도 성립하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33","t":"상법상 회사의 종류에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 회사의 종류에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["합명회사란 회사 채권자에 대하여 직접․연대하여 무한책임을 지는 무한책임사원으로만 이루어진 회사를 말한다.","합자회사는 무한책임사원과 유한책임사원으로 구성되고, 유한책임사원은 주식회사․유한회사의 사원과 마찬가지로 회사채무에 대하여 간접책임을 진다.","유한책임회사의 내부관계는 원칙적으로 합명회사에 관한 규정을 준용한다.","유한회사의 사원은 출자전보책임을 진다.","상법상 모회사의 기준은 자회사 발행주식총수의 50%를 초과하여 소유하는 것이다. 23-7"],"a":2}},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40-1","t":"마우스부품 제조업체인 주식회사 X 설립시 발기인 甲이 위 회사 운영에 필수적인 특허권을 출자하고 이를 1억 원으로 평가하여 액면금 10,000원의 주식 10,000주를 부여받기로 한 경우, 이러한 내용은 정관에 기재되지 않으면 효력이 없다.","ox":"O","m":"①","c":"A","tp":"주식회사의 변태설립사항 중 현물출자"},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40-2","t":"현물출자의 목적이 될 수 있는 재산은 금전 이외의 재산으로서 대차대조표의 부에 계상할 수 있는 것이라면 무엇이든지 가능하므로, 노무나 신용도 출자할 수 있다.","ox":"X","m":"②","c":"A","tp":"주식회사의 변태설립사항 중 현물출자"},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40-3","t":"현물출자의 경우 출자된 재산이 금전으로 평가되는 과정에서 과대평가가 이루어질 우려가 있기 때문에 반드시 검사인의 조사를 받아야 한다.","ox":"X","m":"③","c":"A","tp":"주식회사의 변태설립사항 중 현물출자"},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40-4","t":"현물출자를 하더라도 일정한 경우에는 법원에 의해 선임된 검사인의 조사 대신 공인된 감정인의 감정으로 갈음할 수 있고 이 경우 감정인은 그 결과를 법원에 보고하지 않아도 된다.","ox":"X","m":"④","c":"A","tp":"주식회사의 변태설립사항 중 현물출자"},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40-5","t":"현물출자에 따른 번잡함을 피하기 위해 회사 성립 후 회사와 甲 간의 매매계약에 의한 소유권이전등기의 방법에 의하여 위 현물출자를 완성하기로 약정하고 그 후 회사설립을 위한 소정의 절차를 거쳐 위 약정에 따른 현물출자가 이루어진 것이라면, 위 현물출자를 위한 약정은 실질 그대로 상법 제290조 제2호의 현물출자에 해당한다고 할 것이어서 정관에 기재되지 아니하는 한 무효이다.","ox":"X","m":"⑤","c":"A","tp":"주식회사의 변태설립사항 중 현물출자"},{"y":2019,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2019_25-35","t":"상법상 1인회사의 법률관계에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 1인회사의 법률관계에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["총 주식을 한사람이 소유하게 된 1인회사의 경우에는 그 주주가 유일한 주주로서 주주총회에 출석하면 전원 총회로서 성립하고 따로 총회소집절차가 필요 없다.","합명회사와 합자회사는 1인회사가 성립할 수 없다.","1인회사는 주주와 회사의 이익이 일치하므로, 주주가 회사금원을 임의로 처분하더라도 횡령죄를 구성하지 않는다.","실제로 주주총회를 개최한 사실이 없었다 하더라도 1인주주에 의하여 의결이 있었던 것으로 주주총회 의사록이 작성되었다면 주주총회의 결의가 있었던 것으로 볼 수 있다.","회사의 유일한 영업재산을 그 회사의 대표이사이자 1인주주가 처분하였다면 주주총회의 특별결의가 없더라도 동 처분은 유효하다. 22-8"],"a":3}},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-1","t":"회사설립의 하자가 있는 경우 법률관계의 획일적 처리를 위하여 설립의 무효 또는 취소는 반드시 소에 의하여 주장하여야 한다.","ox":"O","m":"①","c":"A","tp":"회사의 설립과 청산"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-2","t":"회사설립무효의 판결 또는 설립취소의 판결은 제3자에 대하여도 그 효력이 있으나, 판결확정 전에 생긴 회사와 사원 및 제3자간의 권리의무에 영향을 미치지 않는다.","ox":"O","m":"②","c":"A","tp":"회사의 설립과 청산"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-3","t":"주식회사 창립총회에서 정관의 변경뿐만 아니라 소집통지서에 그 뜻의 기재가 없는 경우에도 설립의 폐지를 결의할 수 있다.","ox":"O","m":"③","c":"A","tp":"회사의 설립과 청산"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-4","t":"등기의 공신력에 따라 회사에 관한 청산종결의 등기가 마쳐진 경우에는 남아 있는 청산사무가 있더라도 법인격은 소멸하고 남은 청산사무를 종료할 의무만을 부담한다.","ox":"X","m":"④","c":"A","tp":"회사의 설립과 청산"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-5","t":"주식회사의 청산인은 법원이 선임한 경우를 제외하고는 언제라도 주주총회의 결의로 이를 해임할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"회사의 설립과 청산"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41","t":"다음 중 주식회사 정관의 절대적 기재사항이 아닌 것은?","c":"A","mc":{"s":"다음 중 주식회사 정관의 절대적 기재사항이 아닌 것은?","d":"","o":["회사의 설립 시에 발행하는 주식의 총수","액면주식을 발행하는 경우 1주의 금액","현물출자를 하는 자의 성명과 그 목적인 재산의 종류, 수량, 가격과 이에 대하여 부여할 주식의 종류와 수","회사가 공고를 하는 방법","발기인의 성명, 주민등록번호 및 주소 22-9"],"a":3}},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-1","t":"이른바 1인회사의 경우 1인주주에 의하여 의결이 있었던 것으로 주주총회의사록이 작성되었다면 특별한 사정이 없는 한 그 내용의 결의가 있었던 것으로 볼 수 있고, 설령 그 주주총회의사록이 작성되지 아니한 경우라도 증거에 의하여 주주총회 결의가 있었던 것으로 인정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-2","t":"주식회사의 임시주주총회가 법령 및 정관상 요구되는 이사회의 결의 및 소집절차 없이 이루어졌다 하더라도, 주주명부상의 주주 전원이 참석하여 총회를 개최하는 데 동의하고 아무런 이의 없이 만장일치로 결의가 이루어졌다면 그 결의는 특별한 사정이 없는 한 유효하다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-3","t":"회사의 채무부담행위가 상법 제398조 소정의 이사의 자기거래에 해당하여 이사회의 승인을 요한다고 할지라도, 그 채무부담행위에 대하여 사전에 주주 전원의 동의가 있었다면 회사는 이사회의 승인이 없었음을 이유로 그 책임을 회피할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-4","t":"합자회사의 경우 무한책임사원의 지분 양도는 유한책임사원을 포함한 모든 사원의 동의를 요하지만, 유한책임사원의 지분 양도는 유한책임사원 전원의 동의만 있으면 충분하고 다른 무한책임사원의 동의를 요하지 않는다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-5","t":"합명회사의 내부관계에 관한 상법 규정은 원칙적으로 임의규정이고 정관에서 상법 규정과 달리 정하는 것이 허용된다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-1","t":"설립중의 회사로서의 실체가 갖추어지기 이전에 발기인이 취득한 권리의무는 구체적인 사정에 따라 발기인 개인 또는 발기인 조합에 귀속되고, 이후 양수나 계약자 지위인수 등의 특별한 이전행위 없이 설립 후의 회사에게 귀속된다.","ox":"X","m":"①","c":"A","tp":"회사의 설립"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-2","t":"주식회사 설립의 무효는 주주·이사 또는 감사에 한하여 회사성립의 날로부터 2년 내에 소만으로 이를 주장할 수 있다.","ox":"O","m":"②","c":"A","tp":"회사의 설립"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-3","t":"합명회사와 합자회사에서는 설립무효의 판결 또는 설립취소의 판결이 확정된 경우에 그 무효나 취소의 원인이 특정한 사원에 한한 것인 때에는 다른 사원 전원의 동의로써 회사를 계속할 수 있다.","ox":"O","m":"③","c":"A","tp":"회사의 설립"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-4","t":"주식회사의 설립과정에서 설립중의 회사는 정관이 작성되고 발기인이 적어도 1주 이상의 주식을 인수하였을 때 성립한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-5","t":"주식회사 설립무효의 소가 그 심리 중에 원인이 된 하자가 보완되고 회사의 현황과 제반사정을 참작하여 설립을 무효로 하는 것이 부적당하다고 인정한 때에는 법원은 그 청구를 기각할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"회사의 설립"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41","t":"다음 중 상법 제290조의 변태설립사항에 해당하지 않는 것은?","c":"A","mc":{"s":"다음 중 상법 제290조의 변태설립사항에 해당하지 않는 것은?","d":"","o":["발기인이 받을 특별이익과 이를 받을 자의 성명","현물출자를 하는 자의 성명과 그 목적인 재산의 종류, 수량, 가격과 이에 대하여 부여할 주식의 종류와 수","액면주식의 경우에 액면 이상의 주식을 발행할 때에는 그 수와 금액","회사성립 후에 양수할 것을 약정한 재산의 종류, 수량, 가격과 그 양도인의 성명","회사가 부담할 설립비용과 발기인이 받을 보수액"],"a":3}},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-1","t":"회사는 본점소재지에서 설립등기를 함으로써 성립되고, 주식회사의 경우 설립등기가 마쳐지면 주식인수인이 주식청약서 요건의 흠결을 이유로 그 인수의 무효를 주장하거나 사기, 강박 또는 착오를 이유로 그 인수를 취소하지 못한다.","ox":"O","m":"①","c":"A","tp":"상법상 회사"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-2","t":"회사는 합명회사, 합자회사, 유한책임회사, 주식회사, 유한회사의 5종으로 한다.","ox":"O","m":"②","c":"A","tp":"상법상 회사"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-3","t":"개인이 회사를 설립하지 않고 영업을 하다가 그와 영업목적이나 물적 설비, 인적 구성원 등이 동일한 회사를 설립하는 경우에 그 회사가 외형상으로는 법인의 형식을 갖추고 있으나 법인의 형태를 빌리고 있는 것에 지나지 않고, 실질적으로는 완전히 그 법인격의 배후에 있는 개인의 개인기업에 불과하거나, 회사가 개인에 대한 법적 책임을 회피하기 위한 수단으로 함부로 이용되고 있는 예외적인 경우에는 회사의 법인격을 부인하여 그 배후에 있는 개인에게 책임을 물을 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 회사"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-4","t":"개인과 회사의 주주들이 경제적 이해관계를 같이 하는 등 개인이 새로 설립한 회사를 실질적으로 운영하면서 자기 마음대로 이용할 수 있는 지배적 지위에 있다고 인정되는 경우로서, 제반 사정에 비추어 회사와 개인이 별개의 인격 체임을 내세워 회사 설립 전 개인의 채무 부담행위에 대한 회사의 책임을 부인하는 것이 심히 정의와 형평에 반한다고 인정되는 때에는 회사에 대하여 회사 설립 전에 개인이 부담한 채무의 이행을 청구하는 것도 가능하다.","ox":"O","m":"④","c":"A","tp":"상법상 회사"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-5","t":"회사의 법인격이 형해화되었다고 볼 수 있는지 여부는 원칙적으로 회사가 성립되는 설립등기를 한 시점을 기준으로, 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하였는지 여부는 채무면탈 등의 남용행위를 한 시점을 기준으로 각 판단하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 회사"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-1","t":"주식회사에서 총 주식을 한 사람이 소유하고 있는 1인 회사의 경우에는 실제로 주주총회를 개최한 사실이 없다 하더라도 1인 주주에 의하여 의결이 있었던 것으로 주주총회 의사록이 작성되었다면 특별한 사정이 없는 한 그 내용의 결의가 있었던 것으로 볼 수 있어 형식적인 사유에 의하여 결의가 없었던 것으로 다툴 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-2","t":"위 ➀항의 법리는 한 사람이 다른 사람의 명의를 빌려 주주로 등재하였으나 총 주식을 실질적으로 그 한 사람이 모두 소유한 경우에는 적용되지 않는다.","ox":"X","m":"②","c":"A","tp":"1인 회사"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-3","t":"주식의 소유가 실질적으로 분산되어 있는 경우에는 설령 1인이 총 주식의 대다수를 가지고 있고 그 지배주주에 의하여 의결이 있었던 것으로 주주총회 의사록이 작성되어 있다 하더라도 특별한 사정이 없는 한 그 내용의 결의가 있었던 것으로 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"1인 회사"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-4","t":"실질상 1인 회사의 소유 재산을 그 회사의 대표이사이자 1인 주주가 처분하였다면 주주총회의 특별결의가 없고 그 재산이 회사의 유일한 영업재산이라 하더라도 유효하다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-5","t":"임원퇴직금지급규정에 관하여 주주총회 결의가 있거나 주주총회의사록이 작성된 적은 없으나 위 규정에 따른 퇴직금이 사실상 1인 회사의 실질적 1인 주주의 결재·승인을 거쳐 관행적으로 지급되었다면 위 규정에 대하여 주주총회의 결의가 있었던 것으로 볼 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-1","t":"설립중의 회사라 함은 주식회사의 설립과정에서 발기인이 회사의 설립을 위하여 필요한 행위로 인하여 취득하게 된 권리의무가 회사의 설립과 동시에 그 설립된 회사에 귀속되는 관계를 설명하기 위한 강학상의 개념이다.","ox":"O","m":"①","c":"A","tp":"발기인조합과 설립중의 회사"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-2","t":"설립중의 회사로서의 실체가 갖추어지기 이전에 발기인이 취득한 권리의무는 구체적 사정에 따라 발기인 개인 또는 발기인조합에 귀속되는 것으로서 이들에게 귀속된 권리의무는 회사가 설립되면 자동적으로 설립 후의 회사에 귀속된다.","ox":"X","m":"②","c":"A","tp":"발기인조합과 설립중의 회사"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-3","t":"발기인이 개인 명의로 금원을 차용한 경우 이는 그 발기인 개인에게 귀속됨이 원칙이고, 위 채무가 발기인 조합에게 귀속되려면 위 금원의 차용행위가 조합원들의 의사에 기해 발기인 조합을 대리하여 이루어져야 한다.","ox":"O","m":"③","c":"A","tp":"발기인조합과 설립중의 회사"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-4","t":"설립중의 회사는 정관이 작성되고 발기인이 적어도 1주 이상의 주식을 인수하였을 때 비로소 성립한다.","ox":"O","m":"④","c":"A","tp":"발기인조합과 설립중의 회사"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-5","t":"판례는 발기인이 개업준비행위를 한 것에 대하여 성립된 회사의 책임을 인정하였다.","ox":"O","m":"⑤","c":"A","tp":"발기인조합과 설립중의 회사"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-1","t":"회사가 외형상으로는 법인의 형식을 갖추고 있으나 이는 법인의 형태를 빌리고 있는 것에 지나지 아니하고 그 실질에 있어서는 완전히 그 법인격의 배후에 있는 타인의 개인기업에 불과하거나 그것이 배후자에 대한 법률적용을 회피하기 위한 수단으로 함부로 쓰여지는 경우에는, 비록 외견상으로는 회사의 행위라 할지라도 회사와 그 배후자가 별개의 인격체임을 내세워 회사에게만 그로 인한 법적 효과가 귀속됨을 주장하면서 배후자의 책임을 부정하는 것은 신의성실의 원칙에 위반되는 법인격의 남용으로서 심히 정의와 형평에 반하여 허용될 수 없고, 따라서 회사는 물론 그 배후자인 타인에 대하여도 회사의 행위에 관한 책임을 물을 수 있다.","ox":"O","m":"①","c":"A","tp":"법인격 부인"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-2","t":"개인과 회사의 주주들이 경제적 이해관계를 같이 하는 등 개인이 새로 설립한 회사를 실질적으로 운영하면서 자기 마음대로 이용할 수 있는 지배적 지위에 있다고 인정되는 경우로서, 여러 사정을 종합적으로 살펴보아 회사와 개인이 별개의 인격체임을 내세워 회사 설립 전 개인의 채무 부담행위에 대한 회사의 책임을 부인하는 것이 심히 정의와 형평에 반한다고 인정되는 때에는 회사에 대하여 회사 설립 전에 개인이 부담한 채무의 이행을 청구하는 것도 가능하다.","ox":"O","m":"②","c":"A","tp":"법인격 부인"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-3","t":"개인의 채무 부담행위에 대한 회사의 책임을 부인하는 것이 심히 정의와 형평에 반한다고 인정되어 회사에 대하여 개인이 부담한 채무의 이행을 청구하는 법리는 채무면탈을 목적으로 회사가 새로 설립된 경우뿐 아니라 같은 목적으로 기존 회사의 법인격이 이용되는 경우에도 적용되는데, 여기에는 회사가 이름뿐이고 실질적으로는 개인기업에 지나지 않은 상태로 될 정도로 형해화된 경우와 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하는 경우가 있을 수 있다. 이때 회사의 법인격이 형해화되었다고 볼 수 있는지 여부는 원칙적으로 문제가 되고 있는 법률행위나 사실행위를 한 시점을 기준으로, 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하였는지 여부는 채무면탈 등의 남용행위를 한 시점을 기준으로 각 판단하여야 한다.","ox":"O","m":"③","c":"A","tp":"법인격 부인"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-4","t":"기존회사가 채무를 면탈할 목적으로 기업의 형태·내용이 실질적으로 동일한 신설회사를 설립하여 채무면탈이라는 위법한 목적달성을 위하여 회사제도를 남용하였다고 평가되는 경우, 기존회사의 채권자는 신설회사만을 상대로 채무 이행을 구하여야 하고 기존회사를 상대로 채무 이행을 청구할 수는 없다.","ox":"X","m":"④","c":"A","tp":"법인격 부인"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-5","t":"법인의 준거법은 원칙적으로 설립 준거법을 기준으로 결정되므로, 법인과 채권·채무관계가 있는 자가 법인과 사원 등 배후자 사이의 법인격의 분리를 부정하면서 법인의 사원 등 배후자에 대하여 법인의 채무에 대한 책임을 추궁하는 경우, 이는 결국 법인의 구성원이 법인의 채권자에 대하여 책임을 부담할지가 문제 되는 것이므로 특별한 사정이 없는 한 법인과 사원 등 사이의 법인격의 분리 여부와 요건을 규정한 그 법인의 설립 준거법에 따라야 한다.","ox":"O","m":"⑤","c":"A","tp":"법인격 부인"},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50-1","t":"주식회사를 설립하면서 일시적인 차입금으로 주금납입의 외형을 갖추고 회사 설립절차를 마친 다음 바로 그 납입금을 인출하여 차입금을 변제하는 이른바 가장납입의 경우에도 주금납입의 효력을 부인할 수는 없다고 할 것이어서 주식인수인이나 주주의 주금납입의무도 종결되었다고 보아야 할 것이다.","ox":"O","m":"①","c":"A","tp":"주식의 가장납입"},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50-2","t":"주식회사의 자본충실의 요청상 주금을 납입하기 전에 명의대여자 및 명의차용자 모두에게 주금납입의 연대책임을 부과하는 규정인 상법 제332조 제2항은 이미 주금납입의 효력이 발생한 주금의 가장납입의 경우에는 적용되지 않는다.","ox":"O","m":"②","c":"A","tp":"주식의 가장납입"},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50-3","t":"회사 설립 당시 원래 주주들이 주식인수인으로서 주식을 인수하고 가장납입의 형태로 주금을 납입한 경우 그들은 바로 회사의 주주라고 단정하기 어렵고, 그 후 그들이 회사가 청구한 주금 상당액을 실질적으로 납입하여야 주주로서의 지위를 취득한다고 할 것이다.","ox":"X","m":"③","c":"A","tp":"주식의 가장납입"},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50-4","t":"주식회사의 자본충실의 원칙상 주식의 인수대금은 그 전액을 현실적으로 납입하여야 하고 그 납입에 관하여 상계로써 회사에 대항하지 못하는 것이므로 회사가 제3자에게 주식인수대금 상당의 대여를 하고 제3자는 그 대여금으로 주식인수대금을 납입한 경우에, 회사가 처음부터 제3자에 대하여 대여금 채권을 행사하지 아니하기로 약정되어 있는 등으로 대여금을 실질적으로 회수할 의사가 없었고 제3자도 그러한 회사의 의사를 전제로 하여 주식인수청약을 한 때에는, 그 제3자가 인수한 주식의 액면금액에 상당하는 회사의 자본이 증가되었다고 할 수 없으므로 위 주식인수대금의 납입은 단순히 납입을 가장한 것에 지나지 아니한다.","ox":"O","m":"④","c":"A","tp":"주식의 가장납입"},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50-5","t":"상법 제385조 제2항은 “이사가 그 직무에 관하여 부정행위 또는 법령이나 정관에 위반한 중대한 사실이 있음에도 불구하고 주주총회에서 그 해임을 부결한 때에는 발행주식의 총수의 100분의 3 이상에 해당하는 주식을 가진 주주는 총회의 결의가 있은 날부터 1월내에 그 이사의 해임을 법원에 청구할 수 있다.”고 규정한다. 상법 제628조 제1항에 의하여 처벌 대상이 되는 납입 또는 현물출자의 이행을 가장하는 행위는 특별한 다른 사정이 없는 한, 위 상법 제385조 제2항에서 규정하는 ‘그 직무에 관하여 부정행위 또는 법령에 위반한 중대한 사실’이 있는 경우에 해당한다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"주식의 가장납입"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48-1","t":"재산인수는 변태설립사항 중의 하나로서, 회사성립 후에 양수할 것을 약정한 재산의 종류, 수량, 가격과 그 양도인의 성명을 정관에 기재함으로써 그 효력이 있다.","ox":"O","m":"①","c":"A","tp":"재산인수 및 현물출자"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48-2","t":"당사자 사이에 회사를 설립하기로 합의하면서 그 일방은 일정한 재산을 현물로 출자하고, 타방은 현금을 출자하되, 현물출자에 따른 번잡함을 피하기 위하여 회사의 성립 후 회사와 현물출자자 사이의 매매계약에 의한 방법에 의하여 위 현물출자를 완성하기로 약정하고 그 후 회사설립을 위한 소정의 절차를 거쳐 위 약정에 따른 현물출자가 이루어진 것이라면, 위 현물출자를 위한 약정은 실질이 재산인수에 해당한다고 할 것이어서 정관에 기재되지 아니하는 한 무효이다.","ox":"O","m":"②","c":"A","tp":"재산인수 및 현물출자"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48-3","t":"재산인수 약정이 정관에 기재되지 아니하여 무효인 경우, 그 재산인수가 상법 제375조가 규정하는 사후설립에도 해당할 수 있다고 하더라도, 이에 대하여 주주총회의 특별결의에 의한 추인이 있다는 사유만으로, 회사가 재산인수의 대상인 부동산의 소유권을 유효하게 취득할 수는 없다.","ox":"X","m":"③","c":"A","tp":"재산인수 및 현물출자"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48-4","t":"현물출자를 하는 발기인은 납입기일에 지체 없이 출자의 목적인 재산을 인도하고 등기, 등록 기타 권리의 설정 또는 이전을 요할 경우에는 이에 관한 서류를 완비하여 교부하여야 한다.","ox":"O","m":"④","c":"A","tp":"재산인수 및 현물출자"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48-5","t":"정관에 기재가 없어 무효가 되는 재산인수의 양도인이, 재산인수의 무효를 주장하면서 회사를 상대로 양도 목적물의 반환을 구하는 경우, 사정에 따라서는 신의성실의 원칙에 반한다는 이유로 그 반환 청구가 허용되지 아니할 수도 있다.","ox":"O","m":"⑤","c":"A","tp":"재산인수 및 현물출자"}],"11":[{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-1","t":"회사가 아니면 상호에 회사임을 표시하는 문자를 사용하지 못한다. 회사의 영업을 양수한 경우에도 같다.","ox":"O","m":"①","c":"A","tp":"상법상 상호"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-2","t":"회사는 상호나 목적 또는 상호와 목적을 변경하고자 할 때에는 본점의 소재지를 관할하는 등기소에 상호의 가등기를 신청할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 상호"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-3","t":"부정한 목적으로 타인의 영업으로 오인할 수 있는 상호를 사용하는 자가 있는 경우에 이로 인하여 손해를 받을 염려가 있는 자 또는 상호를 등기한 자는 그 폐지를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 상호"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-4","t":"타인에게 자기의 성명 또는 상호를 사용하여 영업을 할 것을 허락한 자는 자기를 영업주로 오인하여 거래한 제3자에 대하여 그 타인과 연대하여 변제할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"상법상 상호"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-5","t":"상호를 등기한 자가 정당한 사유 없이 1년간 상호를 사용하지 아니하는 때에는 이를 폐지한 것으로 본다.","ox":"X","m":"⑤","c":"A","tp":"상법상 상호"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-1","t":"영업의 목적인 상행위를 개시하기 전에 영업을 위한 준비행위를 하는 사람은 그 준비행위를 한 때 상인자격을 취득한다.","ox":"O","m":"①","c":"A","tp":"상법상 상인과 상인자격"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-2","t":"회사는 상행위를 하지 아니하더라도 상인으로 본다.","ox":"O","m":"②","c":"A","tp":"상법상 상인과 상인자격"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-3","t":"행정관청에 대한 인·허가 명의나 국세청에 신고한 사업자등록상의 명의와 실제 영업상의 주체가 다를 경우 후자가 상인이 된다.","ox":"O","m":"③","c":"A","tp":"상법상 상인과 상인자격"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-4","t":"자본금액이 1,000만 원 미만인 상인으로서 회사가 아닌 자인 ‘소상인’에게는 지배인, 상호, 상업장부와 상업등기에 관한 규정은 적용하지 아니한다.","ox":"O","m":"④","c":"A","tp":"상법상 상인과 상인자격"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-5","t":"법무사는 상법 제5조 제1항이 규정하는 점포 기타 유사한 설비에 의하여 상인적 방법으로 영업을 하는 자로서 상인으로 볼 수 있다.","ox":"X","m":"⑤","c":"A","tp":"상법상 상인과 상인자격"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-1","t":"지배인은 자연인이어야 하지만, 반드시 행위능력자임을 요하지 아니하며, 주식회사나 유한회사의 감사도 지배인이 될 수 있다.","ox":"X","m":"①","c":"A","tp":"상업사용인"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-2","t":"상인이 수인의 지배인에게 공동으로 대리권을 행사하게 하는 경우에 지배인 1인에 대한 의사표시는 영업주에 대하여 효력이 있다.","ox":"O","m":"②","c":"A","tp":"상업사용인"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-3","t":"표현지배인이 성립하려면 사용인이 상법상의 영업소로서의 실체를 가지고 어느 정도 독립적인 영업활동을 할 수 있는 곳에서 근무할 것을 요하고, 단순히 본점 또는 지점의 지휘·감독 아래 기계적으로 제한된 보조적 사무만을 처리하는 영업소는 해당되지 아니한다.","ox":"O","m":"③","c":"A","tp":"상업사용인"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-4","t":"부분적 포괄대리권을 가진 사용인에 해당하기 위해서는 그 업무 내용에 영업주를 대리하여 법률행위를 하는 것이 당연히 포함되어 있어야 한다.","ox":"O","m":"④","c":"A","tp":"상업사용인"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-5","t":"영업주가 상업사용인에게 개입권 또는 이득양도청구권을 행사한 이후에도 사용인에 대한 계약의 해지나 손해배상청구를 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32","t":"상법상 영업양도에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 영업양도에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["영업을 양도한 경우에 다른 약정이 없으면 양도인은 5년간 동일한 특별시․광역시․시․군과 인접 특별시․광역시․시․군에서 동종영업을 하지 못한다.","양도인이 동종영업을 하지 아니할 것을 약정한 때에는 동일한 특별시․광역시․시․군과 인접 특별시․광역시․시․군에 한하여 20년을 초과하지 아니한 범위 내에서 그 효력이 있다.","영업양수인이 양도인의 상호를 계속 사용하는 경우에는 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다.","위 ③항의 규정은 양수인이 영업양도를 받은 후 지체 없이 양도인의 채무에 대한 책임이 없음을 등기한 때에는 적용하지 아니한다. 양도인과 양수인이 지체 없이 제3자에 대하여 그 뜻을 통지한 경우에 그 통지를 받은 제3자에 대하여도 같다.","영업양수인이 양도인의 상호를 계속 사용하지 아니하는 경우에 양도인의 영업으로 인한 채무를 인수할 것을 광고한 때에는 양수인도 변제할 책임이 있다."],"a":1}},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-1","t":"상법에 따라 등기할 사항은 당사자의 신청에 의하여 영업소의 소재지를 관할하는 법원의 상업등기부에 등기한다.","ox":"O","m":"①","c":"A","tp":"상법상 상업등기"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-2","t":"등기할 사항은 이를 등기하지 아니하면 선의의 제3자에게 대항하지 못한다.","ox":"O","m":"②","c":"A","tp":"상법상 상업등기"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-3","t":"등기할 사항을 등기한 경우에는 제3자가 정당한 사유로 인하여 이를 알지 못한 경우에도 그에게 대항할 수 있다.","ox":"X","m":"③","c":"A","tp":"상법상 상업등기"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-4","t":"고의 또는 과실로 인하여 사실과 상위(相違)한 사항을 등기한 자는 그 상위를 선의의 제3자에게 대항하지 못한다.","ox":"O","m":"④","c":"A","tp":"상법상 상업등기"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-5","t":"등기한 사항에 변경이 있거나 그 사항이 소멸한 때에는 당사자는 지체 없이 변경 또는 소멸의 등기를 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상업등기"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-1","t":"당사자 일방에 대하여만 상행위에 해당하는 행위로 인한 채권에도 상사소멸시효가 적용된다.","ox":"O","m":"①","c":"A","tp":"상법상 소멸시효가 적용되는 채권"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-2","t":"상인이 영업을 위하여 하는 보조적 상행위로 인한 채권에도 상사소멸시효가 적용된다.","ox":"O","m":"②","c":"A","tp":"상법상 소멸시효가 적용되는 채권"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-3","t":"상인의 불법행위로 인한 손해배상채권에도 상사소멸시효가 적용된다.","ox":"X","m":"③","c":"A","tp":"상법상 소멸시효가 적용되는 채권"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-4","t":"상행위로 인하여 생긴 채무의 불이행에 기하여 성립한 손해배상채권에도 상사소멸시효가 적용된다.","ox":"O","m":"④","c":"A","tp":"상법상 소멸시효가 적용되는 채권"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-5","t":"면책적 채무인수에서 인수채무가 원래 5년의 상사시효의 적용을 받던 채무라면 그 후 면책적 채무인수에 따라 그 채무자의 지위가 인수인으로 교체되었다고 하더라도 그 채무에는 여전히 상사소멸시효가 적용된다.","ox":"O","m":"⑤","c":"A","tp":"상법상 소멸시효가 적용되는 채권"},{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41","t":"상인간의 매매에 있어 매수인의 목적물의 검사와 하자통지의무에 대하여 규정한 상법 제69조에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상인간의 매매에 있어 매수인의 목적물의 검사와 하자통지의무에 대하여 규정한 상법 제69조에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["매수인이 목적물을 수령한 때에는 지체 없이 이를 검사하여야 하며 하자 또는 수량의 부족을 발견한 경우에는 즉시 매도인에게 그 통지를 발송하지 아니하면 이로 인한 계약해제, 대금감액 또는 손해배상을 청구하지 못한다.","매매의 목적물에 즉시 발견할 수 없는 하자가 있는 경우에 매수인이 6월 내에 이를 발견한 때에도 ①과 같다.","매매의 목적물에 상인에게 통상 요구되는 객관적인 주의의무를 다하여도 즉시 발견할 수 없는 하자가 있는 경우에도, 매수인은 6월 내에 그 하자를 발견하여 지체 없이 이를 통지하지 아니하면 매수인은 과실의 유무를 불문하고 매도인에게 하자담보책임을 물을 수 없다.","상법 제69조는 채무불이행에 해당하는 이른바 불완전이행으로 인한 손해배상책임을 묻는 청구에도 적용된다.","상법 제69조는 매도인이 악의인 경우에는 적용하지 아니한다."],"a":4}},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-1","t":"자기명의로써 타인의 계산으로 물건 또는 유가증권의 매매를 영업으로 하는 자를 위탁매매인이라 하는데, 위탁매매인은 위탁자를 위한 매매로 인하여 상대방에 대하여 직접 권리를 취득하고 의무를 부담한다.","ox":"O","m":"①","c":"A","tp":"상법상 위탁매매"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-2","t":"어떠한 계약이 일반의 매매계약인지 위탁매매계약인지는 계약의 명칭 또는 형식적인 문언을 떠나 그 실질을 중시하여 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 위탁매매"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-3","t":"위탁매매인이 위탁자로부터 받은 물건 또는 유가증권이나 위탁매매로 인하여 취득한 물건, 유가증권 또는 채권은 위탁자와 위탁매매인 또는 위탁매매인의 채권자간의 관계에서는 이를 위탁자의 소유 또는 채권으로 본다.","ox":"O","m":"③","c":"A","tp":"상법상 위탁매매"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-4","t":"위탁매매인이 위탁자가 지정한 가액보다 염가로 매도하거나 고가로 매수한 경우에도 위탁매매인이 그 차액을 부담한 때에는 그 매매는 위탁자에 대하여 효력이 있다.","ox":"O","m":"④","c":"A","tp":"상법상 위탁매매"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-5","t":"위탁매매인이 위탁자가 지정한 가액보다 고가로 매도하거나 염가로 매수한 경우에는 그 차액은 다른 약정이 없으면 위탁매매인의 이익으로 한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 위탁매매"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-1","t":"상법 제24조의 명의대여자의 책임 규정은 명의대여자가 상인이 아니거나 명의차용자의 영업이 상행위가 아닌 경우에도 적용된다.","ox":"O","m":"①","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-2","t":"명의대여자의 책임은 명의자를 사업주로 오인하여 거래한 제3자를 보호하기 위한 것이므로 명의의 사용을 허락받은 자의 행위뿐만 아니라 명의차용자의 피용자의 행위에 대해서까지 미친다.","ox":"X","m":"②","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-3","t":"명의대여자는 명의차용자의 거래 상대방이 명의대여사실을 알았거나 모른 데 대하여 중대한 과실이 있는 때에는 책임을 지지 않는다.","ox":"O","m":"③","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-4","t":"명의차용자가 불법행위를 한 경우에는 설령 피해자가 명의대여자를 영업주로 오인하고 있었더라도 신뢰관계를 이유로 명의대여자에게 책임을 지워야 할 이유가 없다.","ox":"O","m":"④","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-5","t":"명의대여자와 명의차용자의 책임은 동일한 경제적 목적을 가진 채무로서 서로 중첩되는 부분에 관하여 일방의 채무가 변제 등으로 소멸하면 타방의 채무도 소멸하는 이른바 부진정연대의 관계에 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21","t":"다음 중 중개인의 의무가 아닌 것은?","c":"A","mc":{"s":"다음 중 중개인의 의무가 아닌 것은?","d":"","o":["견품 보관의무","결약서교부의무","장부작성의무","성명, 상호 묵비의 의무","지정가액준수의무"],"a":5}},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-1","t":"상행위에 해당하는 보증보험계약에 기초한 급부가 이루어짐에 따라 발생한 부당이득반환청구권에 대하여 5년의 상사소멸시효가 적용된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-2","t":"상인이 그의 영업을 위하여 근로자와 체결하는 근로계약은 보조적 상행위에 해당한다고 하더라도, 근로자의 근로계약상의 주의의무 위반으로 인한 손해배상청구권은 특별한 사정이 없는 한 10년의 민사 소멸시효기간이 적용된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-3","t":"주채무자에 대한 확정판결에 의하여 주채무의 소멸시효기간이 10년으로 연장된 상태에서 주채무를 보증한 경우, 특별한 사정이 없는 한 성질에 따라 보증인에 대한 채권이 민사채권인 경우에는 10년, 상사채권인 경우에는 5년의 소멸시효기간이 적용된다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-4","t":"교통사고 피해자가 가해차량이 가입한 책임보험의 보험자로부터 사고로 인한 보험금을 수령하였음에도 자동차손해배상 보장사업을 위탁받은 보험사업자로부터 또다시 피해보상금을 수령한 것을 원인으로 한 위 보험사업자의 피해자에 대한 부당이득반환청구권의 소멸시효기간에 관하여는 상법 제64조가 적용된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-5","t":"주식회사인 부동산 매수인이 의료법인인 매도인과의 부동산매매계약의 이행으로서 그 매매대금을 매도인에게 지급하였으나, 매도인 법인을 대표하여 위 매매계약을 체결한 대표자의 선임에 관한 이사회결의가 부존재하는 것으로 확정됨에 따라 위 매매계약이 무효로 되었음을 이유로 이미 지급하였던 매매대금 상당액의 반환을 구하는 부당이득반환청구의 경우 그 소멸시효기간은 민법 제162조 제1항에 따라 10년이다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-1","t":"회사의 상호에는 그 종류에 따라 합명회사, 합자회사, 유한책임회사, 주식회사 또는 유한회사의 문자를 사용하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-2","t":"회사의 영업을 양수한 경우에도 회사가 아니라면 상호에 회사임을 표시하는 문자를 사용하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-3","t":"동일한 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업으로 타인이 등기한 상호를 사용하는 자는 부정한 목적으로 사용하는 것으로 간주한다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-4","t":"동일한 영업에는 단일상호를 사용하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-5","t":"상호는 영업을 폐지하거나 영업과 함께 하는 경우에 한하여 이를 양도할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-1","t":"상법 제54조의 상사법정이율이 적용되는 ‘상행위로 인한 채무’에는 상행위로 인하여 직접 생긴 채무뿐만 아니라 그와 동일성이 있는 채무 또는 그 변형으로 인정되는 채무도 포함된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-2","t":"상법 제54조의 상사법정이율이 적용되는 ‘상행위로 인한 채무’에는 당사자 쌍방에 대하여 모두 상행위가 되는 행위로 인한 채무뿐만 아니라 당사자 일방에 대하여만 상행위에 해당하는 행위로 인한 채무도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-3","t":"상인 간에서 금전소비대차가 있었음을 주장하면서 약정이자의 지급을 구하는 청구에는 약정 이자율이 인정되지 않더라도 상법 소정의 법정이자의 지급을 구하는 취지가 포함되어 있다고 볼 수 있다.","ox":"O","m":"③","c":"A","tp":"상법 제54조의 상사법정이율"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-4","t":"상법 제54조의 상사법정이율은 상행위가 아닌 불법행위로 인한 손해배상채무에도 적용된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-5","t":"영리법인인 주택건설업자의 아파트 입주 지연에 따른 지체상금은 상행위인 분양계약의 불이행으로 인한 손해배상채권으로서 그 지연손해금에 대하여도 상법 제54조의 상사법정이율을 적용하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-1","t":"회사는 상법에 의하여 상인으로 의제되므로, 대표이사 개인이 회사 자금으로 사용하기 위하여 자금을 차용한 경우 상행위에 해당하여 차용금채무를 상사채무로 볼 수 있다.","ox":"X","m":"①","c":"A","tp":"상인과 상행위"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-2","t":"상법상 지배인, 상호, 상업장부와 상업등기에 관한 규정은 소상인에게 적용하지 아니한다.","ox":"O","m":"②","c":"A","tp":"상인과 상행위"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-3","t":"법무사를 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"상인과 상행위"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-4","t":"영업의 목적인 상행위를 개시하기 전에 영업을 위한 준비행위를 하는 자는 영업으로 상행위를 할 의사를 실현하는 것이므로 준비행위를 한 때 상인자격을 취득함과 아울러 개업준비행위는 영업을 위한 행위로서 최초의 보조적 상행위가 된다.","ox":"O","m":"④","c":"A","tp":"상인과 상행위"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-5","t":"상인은 자기 명의로 상행위를 하는 자를 의미하는데, 여기서 ‘자기 명의’란 상행위로부터 생기는 권리의무의 귀속주체로 된다는 뜻으로서 실질에 따라 판단하여야 하므로, 행정관청에 대한 인ㆍ허가 명의나 국세청에 신고한 사업자등록상의 명의와 실제 영업상의 주체가 다를 경우 후자가 상인이 된다.","ox":"O","m":"⑤","c":"A","tp":"상인과 상행위"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-1","t":"명의대여자는 거래 상대방이 명의대여사실을 알았거나 모른 데 대하여 중대한 과실이 있는 때에는 명의대여자의 책임을 지지 아니한다.","ox":"O","m":"①","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-2","t":"명의대여자와 명의차용자의 책임은 동일한 경제적 목적을 가진 채무로서 서로 중첩되는 부분에 관하여 채무자 1인에 대한 이행청구 또는 채무자 1인이 행한 채무의 승인 등 소멸시효의 중단사유나 시효이익의 포기는 다른 채무자에 대하여 효력이 미친다.","ox":"X","m":"②","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-3","t":"명의대여자 책임은 명의차용인과 그 상대방의 거래행위에 의하여 생긴 채무에 관하여 명의대여자를 진실한 상대방으로 오인하고 그 신용·명의 등을 신뢰한 제3자를 보호하기 위한 것이므로 불법행위의 경우에는 명의대여자 책임이 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-4","t":"제3자가 자기의 상호아래 대리점이란 명칭을 붙여 사용하는 것을 허락하거나 묵인하였다는 것만으로는 곧바로 상법상 명의대여자로서 책임을 물을 수는 없다.","ox":"O","m":"④","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-5","t":"건설업 면허를 대여한 자는 건설업 면허를 대여 받은 자가 그 면허를 사용하여 하도급거래를 한 경우 면허를 대여한 자를 영업의 주체로 오인한 하수급인에 대하여 명의대여자 책임을 질 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-1","t":"본점의 소재지에서 등기할 사항은 다른 규정이 없으면 지점의 소재지에서도 등기하여야 한다.","ox":"O","m":"①","c":"A","tp":"상업등기"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-2","t":"등기신청권자가 스스로 등기를 하지 아니하였다 하더라도 그의 책임 있는 사유로 그 등기가 이루어지는 데에 관여하거나 그 부실등기의 존재를 알고 있음에도 이를 시정하지 않고 방치하는 등 등기신청권자의 고의·과실로 부실등기를 한 것과 동일시할 수 있는 특별한 사정이 있는 경우에는, 그 등기신청권자에 대하여 상법 제39조에 의한 부실등기 책임을 물을 수 있다.","ox":"O","m":"②","c":"A","tp":"상업등기"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-3","t":"등기의무자가 등기할 사항을 등기한 경우에는 정당한 사유로 인하여 이를 알지 못한 경우를 제외하고는 선의의 제3자에게도 대항할 수 있다.","ox":"O","m":"③","c":"A","tp":"상업등기"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-4","t":"법인등기부에 이사 또는 감사로 등재되어 있는 경우에는 특단의 사정이 없는 한 정당한 절차에 의하여 선임된 적법한 이사 또는 감사로 추정된다.","ox":"O","m":"④","c":"A","tp":"상업등기"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-5","t":"등기할 사항을 등기하지 아니하면 선의의 제3자에게 대항하지 못하는데, 여기서 선의의 제3자라 함은 대등한 지위에서 하는 보통의 거래관계의 상대방은 물론 조세권에 기하여 조세의 부과처분을 하는 경우의 국가를 포함한다.","ox":"X","m":"⑤","c":"A","tp":"상업등기"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-1","t":"위탁매매라 함은 자기의 명의로 타인의 계산에 의하여 물품을 구입 또는 판매하고 보수를 받는 것으로서 명의와 계산이 분리되는 것을 본질로 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-2","t":"위탁매매인이 위탁자로부터 받은 물건 또는 유가증권이나 위탁매매로 인하여 취득한 물건, 유가증권 또는 채권은 위탁자와 위탁매매인 또는 위탁매매인의 채권자 간의 관계에서는 이를 위탁자의 소유 또는 채권으로 본다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-3","t":"위탁매매인이 거래소의 시세가 있는 물건 또는 유가증권의 매매를 위탁받은 경우에는 직접 그 매도인이나 매수인이 될 수 있다. 이 경우의 매매대가는 위탁매매인이 매매의 통지를 발송할 때의 거래소의 시세에 따른다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-4","t":"위탁매매인이 위탁자로부터 물건 또는 유가증권을 받은 후 파산한 경우에는 위탁자는 대외적인 소유자가 아니므로 위 물건 또는 유가증권을 환취할 권리가 없다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-5","t":"위탁자의 위탁상품 공급으로 인한 위탁매매인에 대한 이득상환청구권이나 이행담보책임 이행청구권은 민법 제163조 제6호 소정의 '상인이 판매한 상품의 대가'에 해당하지 아니하여 3년의 단기소멸시효의 대상이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-1","t":"금융리스이용자는 금융리스물건을 수령함과 동시에 금융리스료를 지급하여야 한다.","ox":"O","m":"①","c":"A","tp":"상법상 금융리스계약"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-2","t":"금융리스물건수령증을 발급한 경우에는 금융리스이용자와 공급자 사이에 적합한 금융리스물건이 수령된 것으로 추정한다.","ox":"X","m":"②","c":"A","tp":"상법상 금융리스계약"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-3","t":"금융리스물건이 공급계약에서 정한 시기와 내용에 따라 공급되지 아니한 경우 금융리스이용자는 공급자에게 직접 손해배상을 청구하거나 공급계약의 내용에 적합한 금융리스물건의 인도를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 금융리스계약"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-4","t":"금융리스업자는 금융리스이용자가 공급자에게 권리를 행사하는 데 필요한 협력을 하여야 한다.","ox":"O","m":"④","c":"A","tp":"상법상 금융리스계약"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-5","t":"금융리스계약에서 금융리스업자가 금융리스물건의 하자에 대하여 하자담보책임을 배제하는 특약은 합리성이 인정되어 유효하다.","ox":"O","m":"⑤","c":"A","tp":"상법상 금융리스계약"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-1","t":"회사는 상행위를 하지 않더라도 상인으로 본다.","ox":"O","m":"①","c":"A","tp":"상인과 상행위"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-2","t":"변호사는 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고 볼 수 있다.","ox":"X","m":"②","c":"A","tp":"상인과 상행위"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-3","t":"소상인이란 자본금 1,000만 원에 미달하는 회사 아닌 상인으로서 상법상 지배인·상호·상업장부 및 상업등기에 관한 규정이 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"상인과 상행위"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-4","t":"어떠한 자가 자기 명의로 상행위를 함으로써 상인자격을 취득하고자 준비행위를 하는 것이 아니라 다른 상인의 영업을 위한 준비행위를 하는 것에 불과하다면, 그 행위는 행위를 한 자의 보조적 상행위가 될 수 없다.","ox":"O","m":"④","c":"A","tp":"상인과 상행위"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-5","t":"상인은 자기 명의로 상행위를 하는 자를 의미하므로, 행정관청에 대한 인·허가 명의나 국세청에 신고한 사업자등록상의 명의와 실제 영업상의 주체가 다를 경우 후자가 상인이 된다.","ox":"O","m":"⑤","c":"A","tp":"상인과 상행위"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-1","t":"상법상 표현지배인에 관한 규정이 적용되기 위하여는 당해 사용인의 근무장소가 상법상 지점으로서의 실체를 구비하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-2","t":"본부장, 지점장 외에 지점차장도 표현지배인에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-3","t":"거래행위라고 볼 수 없는 재판상 행위에 대하여는 표현지배인이 인정되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-4","t":"단순히 본·지점의 지휘감독 아래 기계적으로 제한된 보조적 사무만을 처리하는 영업소는 상법상의 영업소라 볼 수 없으므로 동 영업소의 소장을 상법 제14조 제1항 소정의 표현지배인으로 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-5","t":"지배인이 영업주 명의로 한 어음행위는 객관적으로 영업에 관한 행위로서 지배인의 대리권의 범위에 속하는 행위라 할 것이므로 지배인이 개인적 목적을 위하여 어음행위를 한 경우에도 그 행위의 효력은 영업주에게 미친다 할 것이고, 이러한 법리는 표현지배인의 경우에도 동일하다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-1","t":"화물상환증의 교부는 운송물 자체의 인도와 동일한 효력이 있다.","ox":"O","m":"①","c":"A","tp":"운송업"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-2","t":"화물상환증은 기명식으로 작성된 경우 배서에 의하여 양도할 수 없다.","ox":"X","m":"②","c":"A","tp":"운송업"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-3","t":"수인이 순차로 운송할 경우에는 각 운송인은 운송물의 멸실, 훼손 또는 연착으로 인한 손해를 연대하여 배상할 책임이 있다.","ox":"O","m":"③","c":"A","tp":"운송업"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-4","t":"화폐, 유가증권 기타의 고가물에 대하여는 송하인이 운송을 위탁할 때에 그 종류와 가액을 명시한 경우에 한하여 운송인이 손해를 배상할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"운송업"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-5","t":"운송계약상의 채무불이행책임과 불법행위로 인한 손해배상책임은 병존하고, 운송계약상의 면책특약은 일반적으로 이를 불법행위책임에도 적용하기로 하는 명시적 또는 묵시적 합의가 없는 한 당연히 불법행위책임에 적용되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"운송업"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-1","t":"영업을 양도한 경우에 다른 약정이 없으면 양도인은 10년간 동일한 특별시·광역시·시·군과 인접 특별시·광역시·시·군에서 동종영업을 하지 못한다.","ox":"O","m":"①","c":"A","tp":"상법상 영업양도"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-2","t":"영업양도에 의하여 승계되는 근로관계는 계약체결일 현재 실제로 그 영업부문에서 근무하고 있는 근로자와의 근로관계뿐만이 아니라, 계약체결일 이전에 해당 영업부문에서 근무하다가 해고된 근로자로서 해고의 효력을 다투는 근로자와의 근로관계도 포함한다.","ox":"X","m":"②","c":"A","tp":"상법상 영업양도"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-3","t":"유한회사가 그 영업의 중요한 일부를 양도하고자 할 경우에는 사원총회의 결의가 필요하고, 그 결의는 총사원의 반수 이상이며 총사원의 의결권의 4분의 3 이상을 가지는 자의 동의로 한다.","ox":"O","m":"③","c":"A","tp":"상법상 영업양도"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-4","t":"영업양수인이 양도인의 상호를 계속사용하지 아니하는 경우라도 양도인의 영업으로 인한 채무를 인수할 것을 광고한 때에는 양수인도 변제할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"상법상 영업양도"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-5","t":"상법 제7장의 영업양도가 있다고 볼 수 있는지 여부는 양수인이 유기적으로 조직화된 수익의 원천으로서의 기능적 재산을 이전받아 양도인이 하던 것과 같은 영업적 활동을 계속하고 있다고 볼 수 있는지에 따라 판단되어야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 영업양도"},{"y":2018,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2018_24-39","t":"유질계약에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"유질계약에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["민법 제339조는 유질계약을 금지하고 있다.","상법 제59조는 상행위로 인하여 생긴 채권을 담보하기 위한 질권설정계약에 대해서는 유질계약을 허용하고 있다.","일방적 상행위로 생긴 채권을 담보하기 위한 질권에 대해서도 유질약정이 허용된다.","질권설정계약에 포함된 유질약정이 상법 제59조에 따라 유효하려면 질권설정자가 상인이어야 한다.","상사질권설정계약에서 유질계약의 성립을 인정하기 위하여서는 그에 관하여 별도의 명시적 또는 묵시적인 약정이 성립되어야 한다. 23-8"],"a":4}},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-1","t":"운송주선인이 위탁자의 청구에 의하여 화물상환증을 작성하거나 운송주선계약에서 운임의 액을 정한 경우에는 운송인으로서의 지위도 취득한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-2","t":"운송주선인이 운송인의 대리인으로서 운송계약을 체결한 경우에 운송의뢰인에 대한 관계에서는 운송주선인의 지위를 상실하고 운송인으로서의 지위를 취득한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-3","t":"운송주선인은 자기나 그 사용인이 운송물의 수령, 인도, 보관, 운송인이나 다른 운송주선인의 선택 기타 운송에 관하여 주의를 게을리 하지 않았음을 증명한 경우에는 운송물의 멸실로 인한 손해를 배상할 책임이 없다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-4","t":"운송주선인은 자기의 이름으로 주선행위를 하는 것이 원칙이지만, 실제로 주선행위를 하였다면 하주나 운송인의 대리인, 위탁자의 이름으로 운송계약을 체결하는 경우에도 운송주선인으로서의 지위를 상실하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-5","t":"해상운송주선인이 위탁자의 청구에 의하여 선하증권을 작성한 때에는 개입권을 행사하였다고 볼 것이나, 해상운송주선인이 타인을 대리하여 위 타인 명의로 작성한 선하증권은 특별한 사정이 없는 개입권 행사의 적법조건이 되는 ‘운송주선인이 작성한 증권’으로 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48-1","t":"부분적 포괄대리권을 가진 상업사용인은 개개의 행위에 대하여 영업주로부터 별도의 수권을 받을 필요가 없다.","ox":"O","m":"①","c":"A","tp":"상법상 상업사용인"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48-2","t":"상업사용인이 영업주가 정한 대리권에 관한 제한 규정에 위반하여 한 행위에 대하여는 제3자가 위 대리권의 제한 사실을 알고 있었던 경우뿐만 아니라 알지 못한 데에 중대한 과실이 있는 경우에도 영업주는 그러한 사유를 들어 상대방에게 대항할 수 있고, 이러한 제3자의 악의 또는 중대한 과실에 대한 주장·증명책임은 영업주가 부담한다.","ox":"O","m":"②","c":"A","tp":"상법상 상업사용인"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48-3","t":"부분적 포괄대리권을 가진 상업사용인이 특정된 영업이나 특정된 사항에 속하지 아니하는 행위를 한 경우 영업주가 책임을 지기 위하여는 민법상의 표현대리의 법리에 의하여 그 상업사용인과 거래한 상대방이 그 상업사용인에게 그 권한이 있다고 믿을 만한 정당한 이유가 있어야 한다.","ox":"O","m":"③","c":"A","tp":"상법상 상업사용인"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48-4","t":"부분적 포괄대리권을 가진 상업사용인이 그 범위 내에서 한 행위는 설사 상업사용인이 영업주 본인의 이익이나 의사에 반하여 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 남용한 것이라 할지라도 일단 영업주 본인의 행위로서 유효하다.","ox":"O","m":"④","c":"A","tp":"상법상 상업사용인"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48-5","t":"부분적 포괄대리권을 가진 사용인의 경우에도 표현지배인에 관한 상법 제14조의 규정이 유추적용된다.","ox":"X","m":"⑤","c":"A","tp":"상법상 상업사용인"},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25","t":"금융리스에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"금융리스에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["금융리스계약은 금융리스업자가 금융리스이용자가 선정한 기계, 시설 등 금융리스물건을 공급자로부터 취득하거나 대여받아 금융리스이용자에게 일정 기간 이용하게 하고 그 기간 종료 후 물건의 처분에 관하여는 당사자 사이의 약정으로 정하는 계약이다.","금융리스업자가 금융리스이용자에게 금융리스물건을 취득 또는 대여하는 데 소요되는 자금에 관한 금융의 편의를 제공하는 것을 본질적 내용으로 한다.","금융리스업자는 특별한 사정이 없는 한, 적합한 금융리스물건을 수령할 수 있도록 협력할 의무와 별도로 독자적인 금융리스물건 인도의무 또는 검사․확인의무를 부담한다.","금융리스업자는 금융리스이용자가 금융리스계약에서 정한 시기에 금융리스계약에 적합한 금융리스물건을 수령할 수 있도록 하여야 하고 금융리스이용자가 금융리스물건수령증을 발급한 경우에는 금융리스업자와 사이에 적합한 금융리스물건이 수령된 것으로 추정한다.","금융리스이용자는 중대한 사정변경으로 인하여 금융리스물건을 계속 사용할 수 없는 경우에는 3개월 전에 예고하고 금융리스계약을 해지할 수 있다. 이 경우 금융리스이용자는 계약의 해지로 인하여 금융리스업자에게 발생한 손해를 배상하여야 한다. 22-6"],"a":3}},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-1","t":"경업금지지역으로서의 동일 지역 또는 인접 지역은 양도된 물적 설비가 있던 지역을 기준으로 정할 것이 아니라 영업양도인의 통상적인 영업활동이 이루어지던 지역을 기준으로 정하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-2","t":"영업재산의 일부를 유보한 채 영업시설을 양도했어도 그 양도한 부분만으로도 종래의 조직이 유지되어 있다고 사회관념상 인정되면 그것을 영업의 양도로 볼 수 있다.","ox":"O","m":"②","c":"A","tp":"영업양도"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-3","t":"양수인에 의하여 속용되는 명칭이 상호 자체가 아닌 옥호 또는 영업표지인 때에는, 양수인은 특별한 사정이 없는 한 양도인의 영업으로 인한 제3자의 채권에 대하여 변제할 책임이 없다.","ox":"X","m":"③","c":"A","tp":"영업양도"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-4","t":"영업임대차의 경우에는 상법 제42조 제1항을 유추적용할 수 없으므로, 임차인은 임대인의 영업으로 인한 제3자의 채권에 대하여 변제할 책임이 없다.","ox":"O","m":"④","c":"A","tp":"영업양도"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-5","t":"양도인의 영업으로 인한 채권에 대하여 채무자가 선의이며 중대한 과실 없이 양도인의 상호를 계속하여 사용하는 양수인에게 변제한 때에는 그 효력이 있다.","ox":"O","m":"⑤","c":"A","tp":"영업양도"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-1","t":"공중접객업자는 고객으로부터 임치받지 아니한 경우에도 그 시설 내에 휴대한 물건이 자기 또는 그 사용인의 과실로 인하여 멸실 또는 훼손되었을 때에는 고객의 휴대물에 대하여 책임이 없음을 알린 경우에도 그 손해를 배상할 책임이 있다.","ox":"O","m":"①","c":"A","tp":"상법상 공중접객업자"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-2","t":"화폐는 고객이 그 종류와 가액을 명시하여 임치하지 아니하면 공중접객업자는 그 물건의 멸실 또는 훼손으로 인한 손해를 배상할 책임이 없다.","ox":"O","m":"②","c":"A","tp":"상법상 공중접객업자"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-3","t":"여관 부설주차장에 시정장치가 된 출입문이 설치되어 있는 등 여관측에서 그 주차장에의 출입과 주차시설을 통제하거나 확인할 수 있는 조치가 되어 있다면, 그러한 주차장에 여관투숙객이 주차한 차량에 관하여는 명시적인 위탁의 의사표시가 없어도 여관업자와 투숙객 사이에 임치의 합의가 있는 것으로 볼 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 공중접객업자"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-4","t":"숙박업자는 고객에게 위험이 없는 안전하고 편안한 객실 등을 제공함으로써 고객의 안전을 배려하여야 할 보호의무를 부담하고, 숙박업자가 이를 위반하여 고객의 생명 등을 침해하여 투숙객에게 손해를 입힌 경우 불완전이행으로 인한 채무불이행책임을 부담한다.","ox":"O","m":"④","c":"A","tp":"상법상 공중접객업자"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-5","t":"고객의 임치물 및 휴대물에 대한 공중접객업자의 악의로 인한 책임은 공중접객업자가 임치물을 반환하거나 고객이 휴대물을 가져간 후 6개월이 지나면 소멸시효가 완성된다.","ox":"X","m":"⑤","c":"A","tp":"상법상 공중접객업자"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39-1","t":"상법 제58조의 일반상사유치권이 성립하기 위하여는 채권자와 채무자가 모두 상인이어야 한다.","ox":"O","m":"①","c":"A","tp":"상법 제58조의 일반상사유치권과 상법상 특별상사유치권"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39-2","t":"상법 제91조 대리상의 유치권은 피담보채권이 ‘목적물에 관하여’ 생긴 것일 필요가 없고, 유치권의 대상이 되는 물건도 ‘채무자 소유’일 것으로 제한되지 않는다. 다만, 당사자간의 약정으로 달리 정할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법 제58조의 일반상사유치권과 상법상 특별상사유치권"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39-3","t":"상법 제58조의 일반상사유치권은 피담보채권이 ‘목적물에 관하여’ 생긴 것일 필요는 없지만 유치권의 대상이 되는 물건은 ‘채무자 소유’일 것으로 제한되어 있다. 다만, 당사자간의 약정으로 달리 정할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법 제58조의 일반상사유치권과 상법상 특별상사유치권"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39-4","t":"채무자 소유의 부동산에 관하여 이미 선행 저당권이 설정되어 있는 상태에서 채권자의 상법 제58조의 일반상사유치권이 성립한 경우, 위 유치권자는 선행저당권에 기한 임의경매절차에서 부동산을 취득한 매수인에게 위 일반상사유치권으로 대항할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법 제58조의 일반상사유치권과 상법상 특별상사유치권"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39-5","t":"상법 제58조의 일반상사유치권 배제의 특약은 당사자 사이의 묵시적 약정에 의해서도 가능하다.","ox":"O","m":"⑤","c":"A","tp":"상법 제58조의 일반상사유치권과 상법상 특별상사유치권"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-1","t":"위탁매매인은 위탁자를 위한 매매에 관하여 상대방이 채무를 이행하지 아니하는 경우에는 다른 약정이나 관습이 없는 이상 위탁자에 대하여 이를 이행할 책임이 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-2","t":"위탁매매인은 위탁자를 위한 매매로 인하여 상대방에 대하여 직접 권리를 취득하고 의무를 부담하므로, 위탁매매인이 위탁매매로 인하여 취득한 물건, 유가증권 또는 채권은 위탁자와 위탁매매인 또는 위탁매매인의 채권자간의 관계에서 이를 위탁매매인의 소유 또는 채권으로 본다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-3","t":"위탁매매인이 위탁자가 지정한 가액보다 염가로 매도하거나 고가로 매수한 경우에도 위탁매매인이 그 차액을 부담한 때에는 그 매매는 위탁자에 대하여 효력이 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-4","t":"위탁매매인이 거래소의 시세가 있는 물건 또는 유가증권의 매매를 위탁받은 경우에는 직접 그 매도인이나 매수인이 될 수 있다. 이 경우의 매매대가는 위탁매매인이 매매의 통지를 발송할 때의 거래소의 시세에 따른다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-5","t":"위탁매매인이 위탁매매의 목적물을 인도받은 후 그 물건의 훼손 또는 하자를 발견하거나 그 물건이 부패할 염려가 있는 때 또는 가격저락의 상황을 안 경우 위탁자의 지시를 받을 수 없거나 그 지시가 지연되는 때에는 위탁자의 이익을 위하여 적당한 처분을 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-1","t":"익명조합원이 자기의 성명을 영업자의 상호 중에 사용하게 하거나 자기의 상호를 영업자의 상호로 사용할 것을 허락한 때에는 그 사용 이후의 채무에 대하여 영업자와 연대하여 변제할 책임이 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-2","t":"상인간의 매매에서 매매의 성질 또는 당사자의 의사표시에 의하여 일정한 일시 또는 일정한 기간내에 이행하지 아니하면 계약의 목적을 달성할 수 없는 경우에 당사자의 일방이 이행시기를 경과한 때에는 상대방은 즉시 그 이행을 청구하지 아니하면 계약을 해제한 것으로 본다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-3","t":"상인간의 매매에서 매수인이 목적물을 수령한 때에는 지체없이 이를 검사하여 하자 또는 수량의 부족을 발견한 경우에는 즉시 매도인에게 그 통지를 발송하여야 하며, 이 경우 매수인이 계약을 해제한 때에도 매도인의 비용으로 매매의 목적물을 보관 또는 공탁하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-4","t":"합자조합에서 유한책임조합원의 지분은 조합계약에서 정하는 바에 따라 양도할 수 있으나, 업무집행조합원은 다른 조합원 전원의 동의가 있어야만 그 지분의 전부나 일부를 타인에게 양도할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-5","t":"중개인은 당사자 간에 계약이 성립된 때에 각 당사자의 성명 또는 상호, 계약년월일과 그 요령을 기재한 서면을 작성하여 기명날인 또는 서명한 후 각 당사자에게 교부하여야 한다. 이 경우 거래의 명확성을 위하여 당사자가 요구하는 경우에도 그 성명 또는 상호의 기재는 생략할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-1","t":"쌍방적 상행위가 되는 가맹계약을 기초로 하여 발생한 부당이득반환채권에는 상법 제64조가 정한 5년의 상사시효가 적용된다.","ox":"O","m":"①","c":"A","tp":"상사소멸시효"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-2","t":"상법 제166조 소정의 창고업자의 책임에 관한 단기소멸시효는 창고업자의 계약상대방인 임치인의 청구뿐만 아니라 임치물이 타인 소유의 물건인 경우에 소유권자인 타인의 청구에도 적용된다.","ox":"X","m":"②","c":"A","tp":"상사소멸시효"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-3","t":"위탁자의 위탁상품 공급으로 인한 위탁매매인에 대한 이득상환청구권이나 이행담보책임 이행청구권은 민법 제163조 제6호 소정의 ‘상인이 판매한 상품의 대가’에 해당하지 아니하여 3년의 단기소멸시효의 대상이 아니다.","ox":"O","m":"③","c":"A","tp":"상사소멸시효"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-4","t":"당사자 쌍방에 대하여 모두 상행위가 되는 행위로 인한 채권뿐만 아니라 당사자 일방에 대하여만 상행위가 되는 행위로 인한 채권도 상법 제64조에 정한 5년의 소멸시효기간이 적용되는 상사채권에 해당하고, 그 상행위에는 상법 제46조 각호에 해당하는 기본적 상행위뿐만 아니라, 상인이 영업을 위하여 하는 보조적 상행위도 포함된다.","ox":"O","m":"④","c":"A","tp":"상사소멸시효"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-5","t":"신용협동조합의 대출을 받은 회원이 상인으로서 그 영업을 위하여 대출을 받았다면 그 대출금채권은 상사채권이므로 위 상사채권에도 상법 제64조에 정한 5년의 소멸시효기간이 적용된다.","ox":"O","m":"⑤","c":"A","tp":"상사소멸시효"},{"y":2019,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2019_25-50","t":"상법상 상호에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 상호에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["상호를 속용하는 영업양수인이 상법 제42조 제1항에 따라 책임지는 제3자의 채권은 영업양도 당시 채무의 변제기가 도래할 필요까지는 없다고 하더라도 그 당시까지 발생한 것이거나 영업양도 당시로 보아 가까운 장래에 발생될 것이 확실한 채권이어야 한다.","회사가 아니면 회사의 영업을 양수한 경우에도 상호에 회사임을 표시하는 문자를 사용하지 못한다.","적법하게 상호를 선정한 경우 상호를 등기하지 않았더라도 부정한 목적으로 타인의 영업으로 오인할 수 있는 상호를 사용하는 자에 대하여 그 폐지를 청구할 수 있다.","타인에게 자기의 성명 또는 상호를 사용하여 영업을 할 것을 허락한 자는 자기를 영업주로 오인하여 거래한 제3자에 대하여 그 타인과 연대하여 변제할 책임이 있고, 이 때 명의대여자와 명의차용자의 책임은 부진정연대책임이다.","명의차용자가 불법행위를 한 경우에는 설령 피해자가 명의대여자를 영업주로 오인하고 있었더라도 그와 같은 오인과 피해의 발생 사이에 인과관계가 없으므로, 이 경우 명의대여자는 신뢰관계를 전제로 하는 명의대여자의 책임을 부담하지 않는다. 22-11"],"a":1}},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23","t":"대리상에 관한 다음 설명 중 옳은 것을 모두 고르면?","c":"A","mc":{"s":"대리상에 관한 다음 설명 중 옳은 것을 모두 고르면?","d":"ㄱ.대리상은 본인의 상업사용인이 아니다.\nㄴ.대리상은 본인 거래의 중개를 영업으로 할 수는 없다.\nㄷ. 대리상은 거래의 대리로 인한 채권이 변제기에 있는 때에는 그 변제를 받을 때까지 본인을 위하여 점유하는 물건을 유치할 수 있으나, 이때 그 물건은 본인의 소유일 것을 요한다.\nㄹ. 대리상의 활동으로 본인이 새로운 고객을 획득하거나 영업상의 거래가 현저하게 증가하고 이로 인하여 계약의 종료후에도 본인이 이익을 얻고 있는 경우에는 대리상은 본인에 대하여 상당한 보상을 청구할 수 있다.\nㅁ. 대리상은 본인에 대해 통지의무, 경업금지의무, 영업비밀준수의무를 부담한다.","o":["ㄱ, ㅁ","ㄴ, ㄷ, ㅁ","ㄱ, ㄷ","ㄴ, ㄹ, ㅁ","ㄱ, ㄹ, ㅁ"],"a":5}},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-1","t":"면책적 채무인수에서 인수채무가 원래 5년의 상사시효의 적용을 받던 채무라면 그 후 면책적 채무인수에 따라 그 채무자의 지위가 인수인으로 교체되었다고 하더라도 그 소멸시효의 기간은 여전히 5년의 상사시효의 적용을 받는다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-2","t":"상사채무의 불이행으로 인한 손해배상채권 및 상인의 불법행위로 인한 손해배상청구권에 대하여 상사시효가 적용된다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-3","t":"상인이 판매한 상품의 대가인 채권(대금채권)의 소멸시효는 상사시효 5년보다 단기인 3년이다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-4","t":"단체협약에 기한 근로자의 유족들의 회사에 대한 위로금채권에는 5년의 상사소멸시효기간이 적용된다.","ox":"O","m":"④","c":"A","tp":"상사시효"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-5","t":"차용금채무의 연대보증인이 그 채권자인 주식회사의 금융기관에 대한 대출금을 변제함으로써 위 차용금채무를 변제한 것으로 하기로 채권자와 약정한 경우, 위 약정에 따른 채권이 상사채권에 해당한다.","ox":"O","m":"⑤","c":"A","tp":"상사시효"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-1","t":"상법 제42조 제1항에는 영업양수인이 양도인의 상호를 계속 사용하는 경우에는 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다고 규정되어 있는바, 이때의 영업으로 인하여 발생한 채무란 영업상의 활동에 관하여 발생하는 채무를 의미하므로, 불법행위로 인한 손해배상채무는 이에 포함되지 않는다고 보아야 한다.","ox":"X","m":"①","c":"A","tp":"영업양도"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-2","t":"영업을 출자하여 주식회사를 설립하고 그 상호를 계속 사용하는 경우 새로 설립된 주식회사는 상법 제42조 제1항의 규정의 유추적용에 의하여 출자자의 채무를 변제할 책임이 있다.","ox":"O","m":"②","c":"A","tp":"영업양도"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-3","t":"영업양도에 의하여 승계되는 근로관계는 계약체결일 현재 실제로 그 영업부문에서 근무하고 있는 근로자와의 근로관계만을 의미하고, 계약체결일 이전에 해당 영업부문에서 근무하다가 해고된 근로자로서 해고의 효력을 다투는 근로자와의 근로관계까지 승계되는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-4","t":"상법상의 영업양도는 종래의 영업조직이 유지되어 그 조직이 전부 또는 중요한 일부로서 기능할 수 있는가에 의하여 결정되어야 한다. 따라서 영업재산의 일부를 유보한 채 영업시설을 양도하였더라도 그 양도한 부분만으로도 종래의 조직이 유지되어 있다고 인정된다면 영업의 양도라고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-5","t":"영업양도는 반드시 영업양도 당사자 사이의 명시적 계약에 의하여야 하는 것은 아니며 묵시적 계약에 의하여도 가능하다. 영업양도의 경우 별도의 등기가 필요하지 않을뿐더러, 그 계약서의 작성이나 기재사항도 법정화되어 있지 않다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43-1","t":"상법 제3조에 따라 당사자 중 1인의 행위가 상행위인 때에는 전원에 대하여 상법이 적용된다. 따라서 당사자의 일방이 수인인 경우에 그 중 1인에게만 상행위가 되더라도 전원에 대하여 상법이 적용된다고 해석된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43-2","t":"조합채무가 특히 조합원 전원을 위하여 상행위가 되는 행위로 인하여 부담하게 된 것이라면 그 채무에 관하여 조합원들에 대하여 상법 제57조 제1항을 적용하여 연대책임을 인정하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43-3","t":"상행위에 해당하는 보증보험계약에 기초한 급부가 이루어짐에 따라 발생한 부당이득반환청구권에 대하여는 5년의 상사소멸시효가 적용된다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43-4","t":"은행이 그 영업행위로서 한 대출금에 대한 변제기 이후의 지연손해금은 민법 제163조 제1호 소정의 단기소멸시효의 대상인 이자채권이 아니고, 상행위로 인한 채권의 소멸시효에 대해 규정한 상법 제64조가 적용되는 것도 아니며, 불법행위로 인한 손해배상채권에 관한 단기소멸시효를 규정한 민법 제766조 제1항이 적용될 따름이다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43-5","t":"질권설정계약에 포함된 유질약정이 상법 제59조에 따라 유효하기 위해서는 질권설정계약의 피담보채권이 상행위로 인하여 생긴 채권이면 충분하고, 질권설정자가 상인이어야 하는 것은 아니다. 또한 일방적 상행위로 생긴 채권을 담보하기 위한 질권에 대해서도 유질약정을 허용한 상법 제59조가 적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-1","t":"상법 제15조의 부분적 포괄대리권을 가진 사용인은 영업의 특정한 종류 또는 특정한 사항에 관한 재판 외의 모든 행위를 할 수 있는 대리권을 가진 상업사용인을 말하므로, 이에 해당하려면 영업주를 대리하여 법률행위를 하는 것이 업무 내용에 포함되어야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-2","t":"주채무자에 대한 확정판결에 의하여 민법 제163조 각 호의 단기소멸시효에 해당하는 주채무의 소멸시효기간이 10년으로 연장된 상태에서 주채무를 보증한 경우, 그 보증채무에 대하여는 민법 제163조 각 호의 단기소멸시효가 적용될 여지가 없고, 성질에 따라 보증인에 대한 채권이 민사채권인 경우에는 10년, 상사채권인 경우에는 5년의 소멸시효기간이 적용된다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-3","t":"상행위의 대리인이 본인을 위한 것임을 표시하지 아니하여도 그 행위는 본인에 대하여 효력이 있다. 그러나 상대방이 본인을 위한 것임을 알지 못한 때에는 대리인에 대하여도 이행의 청구를 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-4","t":"회사는 상법에 의해 상인으로 의제되므로, 회사의 기관인 대표이사 개인이 회사 자금으로 사용하기 위하여 자금을 차용하는 행위 역시 상행위에 해당하여 위 대표이사에 대한 대여금채권은 상사채권으로서 5년의 소멸시효기간이 적용된다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-5","t":"당사자 일방에 대하여만 상행위에 해당하는 행위로 인한 채권도 상법 제64조 소정의 5년의 소멸시효기간이 적용되는 상사채권에 해당한다. 그리고 상행위로부터 생긴 채권뿐만 아니라 이에 준하는 채권에도 상법 제64조가 적용되거나 유추적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-1","t":"매매목적물에 하자가 있어 매수인이 매매계약을 해제한 경우에는, 매도인과 매수인은 원상회복의무만을 부담한다.","ox":"X","m":"①","c":"A","tp":"상사매매 시 매수인의 목적물 검사와 하자 통지의무"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-2","t":"상인간 매매에서 매수인의 목적물 검사와 하자 통지의무에 관하여 정한 상법 제69조는 채무불이행에 해당하는 이른바 불완전이행으로 인한 손해배상책임을 묻는 청구에도 적용된다.","ox":"X","m":"②","c":"A","tp":"상사매매 시 매수인의 목적물 검사와 하자 통지의무"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-3","t":"상법 제69조는 유상계약 일반에 타당한 규정이므로 상인간의 수량을 지정한 건물의 임대차계약에도 준용된다.","ox":"X","m":"③","c":"A","tp":"상사매매 시 매수인의 목적물 검사와 하자 통지의무"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-4","t":"매매의 목적물에 상인에게 통상 요구되는 객관적 주의의무를 다하여도 6월 내에 발견할 수 없는 하자가 있는 경우에는 매수인에게 과실이 없는 경우 매도인에게 하자담보책임을 물을 수 있다.","ox":"X","m":"④","c":"A","tp":"상사매매 시 매수인의 목적물 검사와 하자 통지의무"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-5","t":"매매의 목적물에 즉시 발견할 수 없는 하자가 있는 경우에는 6월 내에 이를 발견하여 즉시 통지한 사실 등에 관한 입증책임은 매수인에게 있다.","ox":"O","m":"⑤","c":"A","tp":"상사매매 시 매수인의 목적물 검사와 하자 통지의무"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-1","t":"제작물공급계약에 의하여 제작공급하여야 할 물건이 대체물인 경우에는 매수인의 목적물 검사와 하자통지의무에 관한 상법 제69조 제1항이 적용된다고 하여도 무방할 것이나, 그 물건이 특정의 주문자의 수요를 만족시키기 위한 부대체물인 경우에는 위 규정이 당연히 적용된다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"상인간 매매"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-2","t":"상인간의 매매에 있어서 매매의 성질 또는 당사자의 의사표시에 의하여 일정한 일시 또는 일정한 기간내에 이행하지 아니하면 계약의 목적을 달성할 수 없는 경우에 당사자의 일방이 이행시기를 경과한 때에는 상대방은 즉시 그 이행을 청구하지 아니하면 계약을 해제한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"상인간 매매"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-3","t":"매수인이 목적물의 수령을 거부하는 경우 매도인은 목적물이 멸실 또는 훼손될 염려가 있는 때에는 법원의 허가를 얻어 경매할 수 있다.","ox":"X","m":"③","c":"A","tp":"상인간 매매"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-4","t":"매수인이 매매 목적물을 수령한 후 하자를 이유로 적법하게 계약을 해제한 경우 매수인은 그 목적물이 멸실 또는 훼손될 염려가 있는 때에는 법원의 허가를 얻어 경매하여 그 대가를 보관 또는 공탁하여야 한다.","ox":"O","m":"④","c":"A","tp":"상인간 매매"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-5","t":"상법 제69조 제1항은 성질상 임의규정이고 당사자간의 약정에 의하여 이와 달리 정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상인간 매매"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-1","t":"운송인은 송하인의 청구에 의하여 화물상환증을 교부하여야 하고, 그 경우 화물상환증의 소지인은 화물상환증과 상환하지 아니하면 운송물의 인도를 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"상법상 육상운송업"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-2","t":"화물상환증이 발행되지 않은 경우 운송인이 수하인과의 계약으로 물건에 대한 권리를 취득한 자에게 인도하였다면 수하인의 의사에 따른 것이므로 물건의 인도에 관한 의무위반으로 볼 수 없다.","ox":"X","m":"②","c":"A","tp":"상법상 육상운송업"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-3","t":"운송인은 자기 또는 운송주선인이나 사용인, 그 밖에 운송을 위하여 사용한 자가 운송물의 수령, 인도, 보관 및 운송에 관하여 주의를 게을리하지 아니하였음을 증명하지 아니하면 운송물의 멸실, 훼손 또는 연착으로 인한 손해를 배상할 책임이 있다.","ox":"O","m":"③","c":"A","tp":"상법상 육상운송업"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-4","t":"해상운송에 있어서 해상강도로 인한 운송물의 멸실이 운송인의 면책사유로 인정되는 것과는 달리 육상에서의 강도로 인한 운송물의 멸실은 반드시 그 자체로서 불가항력으로 인한 면책사유가 된다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"상법상 육상운송업"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-5","t":"상법 제136조 고가물불고지로 인한 면책규정은 일반적으로 운송인의 운송계약상의 채무불이행으로 인한 청구에만 적용되고 불법행위로 인한 손해배상청구에는 그 적용이 없다.","ox":"O","m":"⑤","c":"A","tp":"상법상 육상운송업"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-1","t":"대리상과 중개인은 모두 일정한 상인을 위하여 계속적으로 거래의 중개를 보조하는 자이다.","ox":"X","m":"①","c":"A","tp":"상행위"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-2","t":"대리상, 중개인, 위탁매매인 모두 경업금지의무를 부담한다.","ox":"X","m":"②","c":"A","tp":"상행위"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-3","t":"위탁매매인이 위탁매매로 인하여 취득한 물건 또는 채권은 위탁자와 위탁매매인의 채권자 사이에서는 위탁매매인의 소유 또는 채권으로 본다.","ox":"X","m":"③","c":"A","tp":"상행위"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-4","t":"대리상은 일정한 상인(본인)의 명의로 본인을 대리하여 거래하고, 위탁매매인은 자기의 명의로 타인의 계산으로 거래하며, 가맹상은 자기의 명의와 계산으로 영업을 한다.","ox":"O","m":"④","c":"A","tp":"상행위"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-5","t":"가맹계약상 존속기간에 대한 약정의 유무와 관계없이 부득이한 사정이 있으면 즉시 가맹계약을 해지할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"상행위"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-1","t":"당사자 중 일방이 수인인 경우 그 중 1인에게만 상행위가 되더라도 전원에 대하여 상사 소멸시효가 적용된다.","ox":"O","m":"①","c":"A","tp":"상법상 상행위와 상사 소멸시효"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-2","t":"상인이 영업을 위하여 하는 보조적 상행위에도 상사소멸시효가 적용된다.","ox":"O","m":"②","c":"A","tp":"상법상 상행위와 상사 소멸시효"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-3","t":"상인의 행위는 영업을 위하여 하는 것으로 추정되므로, 영업을 위하여 하는 것인지 아닌지 분명하지 않은 상인의 행위는 영업을 위하여 하는 것으로 추정된다.","ox":"O","m":"③","c":"A","tp":"상법상 상행위와 상사 소멸시효"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-4","t":"회사는 상행위를 하지 않더라도 상인으로 보기 때문에 회사 대표이사 개인이 회사의 운영자금으로 사용하려고 돈을 빌린 때에는 언제나 상행위로 본다.","ox":"X","m":"④","c":"A","tp":"상법상 상행위와 상사 소멸시효"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-5","t":"당사자 일방에 대하여만 상행위에 해당하는 행위로 인한 채권에도 상사소멸시효가 적용된다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상행위와 상사 소멸시효"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-1","t":"어음으로 인한 채권·채무를 상호계산에 계입한 경우에 그 어음채무자가 변제하지 아니한 때에 당사자는 그 채무의 항목을 상호계산에서 제거할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-2","t":"상호계산의 계약체결 당사자는 적어도 일방이 상인이면 된다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-3","t":"각 당사자는 계약의 존속기간을 정한 경우에도 언제든지 상호계산을 해지할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-4","t":"상호계산기간에 대해 당사자간 약정이 있으면 그 기간으로 하고, 약정이 없으면 6개월로 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-5","t":"상호계산제도에서는 상계로 인한 잔액에 대해 이자가 발생할 여지가 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-2","t":"乙과 丙의 출자가 손실로 인하여 감소된 때에는 그 손실을 전보한 후가 아니면 이액배당을 청구하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-4","t":"X약정이 종료한 때에는 甲은 乙과 丙에게 그 출자의 가액을 반환하여야 하고, 출자가 손실로 인하여 감소된 경우에도 마찬가지이다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-5","t":"당사자의 일방이 상대방의 영업을 위하여 출자를 하는 경우라 할지라도 그 영업에서 이익이 난 여부를 따지지 않고 상대방이 정기적으로 일정한 금액을 지급하기로 약정한 경우에는 X약정과 같은 성격의 약정으로 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-1","t":"지배인은 영업주에 갈음하여 그 영업에 관한 재판상 또는 재판 외의 모든 행위를 할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 상업사용인"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-2","t":"지배인이 영업주가 정한 대리권에 관한 제한규정에 위반하여 한 행위에 대하여는 제3자가 위 대리권 제한사실을 알고 있었던 경우뿐만 아니라 알지 못한 데에 중대한 과실이 있는 경우에도 영업주는 그러한 사유를 들어 상대방에게 대항할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 상업사용인"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-3","t":"상인은 수인의 지배인에게 공동으로 대리권을 행사하게 할 수 있는데, 이는 등기사항에는 해당하지 않는다.","ox":"X","m":"③","c":"A","tp":"상법상 상업사용인"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-4","t":"표현지배인은 본점 또는 지점의 본부장, 지점장, 그 밖에 지배인으로 인정될 만한 명칭을 사용하는 자를 말하므로, 지점차장이라는 명칭을 사용하는 자는 표현지배인이라고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"상법상 상업사용인"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-5","t":"부분적 포괄대리권을 가진 상업사용인이 특정된 영업이나 특정된 사항에 속하지 아니하는 행위를 한 경우, 영업주가 책임을 지기 위하여는 민법상의 표현대리의 법리에 의하여 그 상업사용인과 거래한 상대방이 그 상업사용인에게 그 권한이 있다고 믿을 만한 정당한 이유가 있어야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상업사용인"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-1","t":"명의대여자와 명의차용자의 책임은 동일한 경제적 목적을 가진 채무로서 서로 중첩되는 부분에 관하여 일방의 채무가 변제 등으로 소멸하면 타방의 채무도 소멸하는 이른바 부진정연대의 관계에 있다.","ox":"O","m":"①","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-2","t":"불법행위의 경우 피해자가 명의대여자를 영업주로 오인하였다면 명의대여자는 그 신뢰관계를 이유로 명의대여자 책임을 부담한다.","ox":"X","m":"②","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-3","t":"명의대여자는 거래 상대방이 명의대여사실을 알았거나 모른 데 대하여 중대한 과실이 있는 때에는 명의대여자 책임을 지지 아니하고, 이때 거래 상대방의 악의, 중과실에 대하여는 면책을 주장하는 명의대여자가 증명책임을 부담한다.","ox":"O","m":"③","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-4","t":"명의대여자의 책임은 명의사용을 허락받은 자의 행위에 한하고 명의차용자의 피용자의 행위에 대해서까지 미칠 수는 없다.","ox":"O","m":"④","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-5","t":"건설업 면허를 대여한 자는 그 면허를 대여받은 자가 그 면허를 사용하여 면허를 대여한 자의 명의로 하도급거래를 한 경우 면허를 대여한 자를 영업의 주체로 오인한 하수급인에 대하여 명의대여자 책임을 질 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 명의대여자의 책임"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-1","t":"상법 제42조 제1항은 영업양수인이 양도인의 상호를 계속 사용하는 경우 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다고 규정함으로써 양도인이 여전히 주채무자로서 채무를 부담하면서 양수인도 함께 변제책임을 지도록 하고 있는데, 영업양수인이 위 규정에 따라 책임지는 제3자의 채권은 영업양도 당시 발생한 채권과 영업양도 당시로 보아 가까운 장래에 발생될 것이 확실한 채권이다.","ox":"X","m":"①","c":"A","tp":"상호를 속용하는 영업양수인의 책임"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-2","t":"양수인에 의하여 속용되는 명칭이 상호 자체가 아닌 옥호 또는 영업표지인 때에도 그것이 영업주체를 나타내는 것으로 사용되는 경우에는 채권자가 영업주체의 교체나 채무인수 여부 등을 용이하게 알 수 없다는 점에서 일반적인 상호속용의 경우와 다를 바 없으므로, 양수인은 특별한 사정이 없는 한 상호를 속용하는 영업양수인의 책임을 정한 상법 제42조 제1항의 유추적용에 의하여 그 채무를 부담한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-3","t":"채권자가 영업양도 무렵 채무인수 사실이 없음을 알지 못한 경우에는 특별한 사정이 없는 한 상호를 속용하는 영업양수인의 변제책임이 발생하고, 이후 채권자가 채무인수 사실이 없음을 알게 되었다고 하더라도 이미 발생한 영업양수인의 변제책임이 소멸하는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"상호를 속용하는 영업양수인의 책임"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-4","t":"영업임대차의 경우에 상호를 속용하는 영업양수인의 책임을 정한 상법 제42조 제1항을 유추적용할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-5","t":"상법 제42조 제1항에 의하여 상호를 속용하는 영업양수인이 변제책임을 지는 양도인의 제3자에 대한 채무는 양도인의 영업으로 인한 채무로서 영업양도 전에 발생한 것이면 족하고, 반드시 영업양도 당시의 상호를 사용하는 동안 발생한 채무에 한하는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"상호를 속용하는 영업양수인의 책임"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-1","t":"공법인의 상행위에 대하여는 법령에 다른 규정이 없는 경우에 한하여 상법이 적용된다.","ox":"O","m":"①","c":"A","tp":"상법상 상인과 상법의 적용"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-2","t":"행정관청에 대한 인·허가 명의나 국세청에 신고한 사업자등록상의 명의와 실제 영업상의 주체가 다를 경우 실제 영업상의 주체가 자기 명의로 상행위를 하는 자로서 상인이 된다.","ox":"O","m":"②","c":"A","tp":"상법상 상인과 상법의 적용"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-3","t":"변호사와 법무사는 상법 제5조 제1항이 규정하는 ‘상인적 방법으로 영업을 하는 자’라고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 상인과 상법의 적용"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-4","t":"자본금액이 1,000만 원에 미치지 못하는 상인으로서 회사가 아닌 자인 소상인에게는 지배인, 상호, 상업장부, 상업등기, 영업양도에 관한 상법 규정이 적용되지 아니한다.","ox":"X","m":"④","c":"A","tp":"상법상 상인과 상법의 적용"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-5","t":"새마을금고가 금고의 회원에게 자금을 대출하는 행위는 일반적으로 영리를 목적으로 하는 행위라고 보기 어렵지만, 대출을 받은 회원이 상인으로서 그 영업을 위하여 대출을 받았다면 그 대출금채권은 상사채권이라고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상인과 상법의 적용"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-1","t":"익명조합은 당사자의 일방이 상대방의 영업을 위하여 출자하고 상대방은 그 영업으로 인한 이익을 분배할 것을 약정함으로써 그 효력이 생긴다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-2","t":"익명조합원이 출자한 금전 기타의 재산은 영업자의 재산으로 본다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-3","t":"익명조합원이 자기의 성명을 영업자의 상호중에 사용하게 하거나 자기의 상호를 영업자의 상호로 사용할 것을 허락한 때에는 그 사용이후의 채무에 대하여 영업자와 연대하여 변제할 책임이 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-4","t":"당사자간에 다른 약정이 없는 경우에, 익명조합원의 출자가 손실로 인하여 감소된 때에는 그 손실을 전보한 후가 아니면 이익배당을 청구하지 못하고, 손실이 출자액을 초과한 경우에는 증자할 의무가 있다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-5","t":"익명조합계약은 ‘영업의 폐지 또는 양도’, ‘영업자의 사망 또는 성년후견개시’, ‘영업자 또는 익명조합원의 파산’으로 인하여 종료한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-1","t":"상법 제58조의 상사유치권은 피담보채권인 ‘상인간의 상행위로 인한 채권’이 변제기에 있어야 하나, 민사유치권과 달리 피담보채권이 ‘목적물에 관하여’ 생긴 것일 필요는 없다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-2","t":"상법 제58조의 상사유치권은 당사자 사이의 특약에 의하여 배제될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-3","t":"상법 제58조의 상사유치권의 목적물은, 채무자에 대한 상행위로 인하여 자기가 점유하고 있는 물건 또는 유가증권인데, 채무자의 소유일 필요는 없다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-4","t":"채무자 소유의 부동산에 관하여 이미 선행저당권이 설정되어 있는 상태에서 상법 제58조 상사유치권이 성립한 경우, 상사유치권자는 선행저당권자 또는 선행저당권에 기한 임의경매절차에서 부동산을 취득한 매수인에 대한 관계에서는 그 상사유치권으로 대항할 수 없다.","ox":"O","m":"④","c":"A","tp":"상법 제58조의 상사유치권"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-5","t":"상법 제58조의 상사유치권은 계약에 의하여 설정되는 것이 아니라 법이 정하는 일정한 객관적 요건을 갖춤으로써 발생하는 이른바 법정담보물권이나, 신의성실의 원칙에 반한다고 평가되는 유치권제도 남용의 유치권 행사는 허용될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-1","t":"“타인이 등기한 상호는 동일한 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업의 상호로 등기하지 못한다.”고 규정하고 있는 상법 제22조에 기하여 선등기자가 후등기자를 상대로 위 규정에 의하여 금지되는 상호등기의 말소청구의 소를 제기할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 상호"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-2","t":"유한책임회사, 주식회사 또는 유한회사를 설립하고자 할 때 또는 회사의 상호와 목적을 변경하고자 할 때에는 본점의 소재지를 관할하는 등기소에 상호의 가등기를 신청할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 상호"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-3","t":"누구든지 부정한 목적으로 타인의 영업으로 오인할 수 있는 상호를 사용하지 못하므로, 이를 위반하여 상호를 사용하는 자가 있는 경우에 이로 인하여 손해를 받을 염려가 있는 자 또는 상호를 등기한 자는 그 폐지를 청구할 수 있고, 손해를 입은 자는 손해배상청구도 할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 상호"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-4","t":"동일한 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업으로 타인이 등기한 상호를 사용하는 자는 부정한 목적으로 사용하는 것으로 추정한다.","ox":"O","m":"④","c":"A","tp":"상법상 상호"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-5","t":"상호는 영업을 폐지하거나 영업과 함께 하는 경우에 한하여 이를 양도할 수 있는데, 상호의 양도를 등기하지 않더라도 악의의 제3자에게는 대항할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"상법상 상호"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-1","t":"단체협약에 기한 근로자의 유족들의 회사에 대한 위로금채권에는 5년의 상사 소멸시효기간이 적용된다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-2","t":"사용자가 근로계약에 수반되는 신의칙상의 부수적 의무인 보호의무를 위반하여 근로자에게 손해를 입힘으로써 발생한 근로자의 손해배상청구권은 특별한 사정이 없는 한 10년의 민사 소멸시효기간이 적용된다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-3","t":"한국전력공사와 다수의 전기수용가와 사이에 체결된 전기공급계약은 상법상 기본적 상행위에 해당하나 전기공급주체인 공법인은 상법이 적용되지 아니하므로, 전기공급계약에 근거한 위약금 지급채무는 10년의 민사 소멸시효기간이 적용된다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-4","t":"배당가능이익이 없는데도 이익의 배당이나 중간배당이 실시된 경우 회사나 채권자가 주주로부터 배당금을 회수하는 것은 회사의 자본충실을 도모하고 회사 채권자를 보호하는 데 필수적이므로, 위법배당에 따른 부당이득반환청구권은 10년의 민사 소멸시효기간이 적용된다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-5","t":"건설공사에 관한 도급계약이 상행위에 해당하는 경우 그 도급계약에 기한 수급인의 하자담보책임은 5년의 소멸시효기간이 적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-1","t":"대리상은 일정한 상인을 위하여 상업사용인이 아니면서 상시 그 영업부류에 속하는 거래의 대리 또는 중개를 영업으로 하는 자를 말한다.","ox":"O","m":"①","c":"A","tp":"상법상 대리상"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-2","t":"어떤 자가 제조회사와 대리점 총판 계약이라고 하는 명칭의 계약을 체결하였다고 하여 곧바로 상법 제87조의 대리상으로 되는 것은 아니고, 그 계약 내용을 실질적으로 살펴 대리상인지 여부를 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 대리상"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-3","t":"대리상이 본인의 허락 없이 제3자의 계산으로 본인의 영업부류에 속하는 거래를 한 경우에 본인은 대리상과의 계약을 해지할 수 있고, 손해배상을 청구할 수 있으며, 그 거래로 인한 이득의 양도를 청구할 수도 있다.","ox":"O","m":"③","c":"A","tp":"상법상 대리상"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-4","t":"대리상은 거래의 대리 또는 중개로 인한 채권이 변제기에 있는 때에는 그 변제를 받을 때까지 본인을 위하여 점유하는 물건 또는 유가증권을 유치할 수 있는데, 위 물건 또는 유가증권은 본인 소유의 것이어야 한다.","ox":"X","m":"④","c":"A","tp":"상법상 대리상"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-5","t":"대리상의 활동으로 본인이 새로운 고객을 획득하거나 영업상의 거래가 현저하게 증가하고 이로 인하여 계약의 종료 후에도 본인이 이익을 얻고 있는 경우에는 대리상은 계약의 종료가 그의 책임있는 사유로 인한 경우가 아닌 한 본인에 대하여 상당한 보상을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 대리상"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-1","t":"영업양도인이 영업을 양도한 후에도 인근에서 동종영업을 한다면 영업양도는 유명무실해지고 영업양수인은 부당한 손실을 입게 되므로, 상법 제41조 제1항은 영업을 양도한 경우에 다른 약정이 없으면 영업양도인은 10년간 동일한 특별시·광역시·시·군과 인접 특별시·광역시·시·군에서 동종영업을 하지 못한다고 규정하고 있다.","ox":"O","m":"①","c":"A","tp":"상법상 영업양도인의 경업금지"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-2","t":"경업이 금지되는 대상으로서의 동종 영업은 영업의 내용, 규모, 방식, 범위 등 여러 사정을 종합적으로 고려하여 볼 때 양도된 영업과 경쟁관계가 발생할 수 있는 영업을 의미한다고 보아야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 영업양도인의 경업금지"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-3","t":"상인이 아닌 농업협동조합은 영업을 양도하더라도 경업금지의무를 부담하지 않는다.","ox":"O","m":"③","c":"A","tp":"상법상 영업양도인의 경업금지"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-4","t":"영업양도계약에서 경업금지청구권의 양도를 제한하는 등의 특별한 사정이 없다면 양도된 영업이 다시 동일성을 유지한 채 전전양도될 때 영업양수인의 경업금지청구권은 영업재산의 일부로서 영업과 함께 그 뒤의 영업양수인에게 전전양도되고, 그에 수반하여 지명채권인 경업금지청구권의 양도에 관한 통지권한도 전전이전된다.","ox":"O","m":"④","c":"A","tp":"상법상 영업양도인의 경업금지"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-5","t":"경업금지지역으로서의 동일 및 인접 특별시·광역시·시·군 지역은 영업양도인의 통상적인 영업활동이 이루어지던 지역을 기준으로 정할 것이 아니라 양도된 물적 설비가 있던 지역을 기준으로 정하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"상법상 영업양도인의 경업금지"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-1","t":"자기의 명의로 물건운송의 주선을 영업으로 하는 자를 운송주선인이라 하고, 여객운송의 주선은 이에 해당되지 않는다.","ox":"O","m":"①","c":"A","tp":"운송주선업"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-2","t":"운송주선인이 상법 제116조에 따라 위탁자의 청구에 의하여 화물상환증을 작성하거나 상법 제119조 제2항에 따라 운송주선계약에서 운임의 액을 정한 경우에는 운송인으로서의 지위도 취득할 수 있지만, 운송주선인이 위 각 조항에 따라 운송인의 지위를 취득하지 않는 한, 운송인의 대리인으로서 운송계약을 체결하였더라도 운송의뢰인에 대한 관계에서는 여전히 운송주선인의 지위에 있다.","ox":"O","m":"②","c":"A","tp":"운송주선업"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-3","t":"운송주선인의 책임은 수하인이 운송물을 수령한 날 또는 운송물이 전부 멸실한 경우 그 운송물을 인도할 날로부터 1년을 경과하면 소멸시효가 완성되고, 이는 운송주선인이 악의인 경우에도 마찬가지이다.","ox":"X","m":"③","c":"A","tp":"운송주선업"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-4","t":"운송주선인은 위탁자를 위하여 물건운송계약을 체결할 것 등의 위탁을 인수하는 것을 본래적인 영업 목적으로 하나, 이러한 운송주선인이 다른 사람의 운송목적의 실현에 도움을 주는 부수적 업무를 담당할 수도 있는 것이어서 상품의 통관절차, 운송물의 검수, 보관, 부보, 운송물의 수령인도 등의 업무를 담당하고 있는 것이 상례이다.","ox":"O","m":"④","c":"A","tp":"운송주선업"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-5","t":"상법 제115조에 의하면, 운송주선인은 자기나 그 사용인이 운송물의 수령, 인도, 보관, 운송인이나 다른 운송주선인의 선택, 기타 운송에 관하여 주의를 해태하지 아니하였음을 증명하지 아니하면 운송물의 멸실, 훼손 또는 연착으로 인한 손해를 배상할 책임을 면하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"운송주선업"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-1","t":"상인간의 매매에서 매수인이 목적물의 수령을 거부하거나 이를 수령할 수 없는 때에는 매도인은 그 물건을 공탁하거나 상당한 기간을 정하여 최고한 후 경매할 수 있다. 다만, 매수인에 대하여 최고를 할 수 없거나 목적물이 멸실 또는 훼손될 염려가 있는 때에는 최고없이 경매할 수 있다.","ox":"O","m":"①","c":"A","tp":"상인간 매매"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-2","t":"상법 제68조에 정한 상인간의 확정기매매의 경우 당사자의 일방이 이행시기를 경과하면 상대방은 이행의 최고나 해제의 의사표시 없이 바로 해제의 효력을 주장할 수 있는바, 상인간의 확정기매매인지 여부는 매매목적물의 가격 변동성, 매매계약을 체결한 목적 및 그러한 사정을 상대방이 알고 있었는지 여부, 매매대금의 결제 방법 등과 더불어 선적기간의 표기가 불가결하고 중요한 약관이 있는지 여부, 계약 당사자 사이에 종전에 계약이 체결되어 이행된 방식, 당해 매매계약에서의 구체적인 이행 상황 등을 종합하여 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"상인간 매매"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-3","t":"매수인에게 즉시 목적물의 검사와 하자통지를 할 의무를 지우고 있는 상법 제69조의 규정은 상인간의 매매에 적용되는 것이고, 매수인이 상인인 한 매도인이 상인인지 여부를 불문하고 위 규정이 적용되어야 하는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"상인간 매매"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-4","t":"매매의 목적물에 상인에게 통상 요구되는 객관적인 주의의무를 다하여도 즉시 발견할 수 없는 하자가 있는 경우, 상법 제69조에 따라 매수인이 6월 내에 그 하자를 발견하여 지체 없이 이를 통지하지 아니하였더라도 매수인에게 과실이 없다면 매도인에게 여전히 하자담보책임을 물을 수 있다.","ox":"X","m":"④","c":"A","tp":"상인간 매매"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-5","t":"상법 제69조의 경우에 매수인이 계약을 해제한 때에도 매도인의 비용으로 매매의 목적물을 보관 또는 공탁하여야 하나, 목적물의 인도장소가 매도인의 영업소 또는 주소와 동일한 특별시·광역시·시·군인 때에는 위와 같은 보관 또는 공탁 의무가 없다.","ox":"O","m":"⑤","c":"A","tp":"상인간 매매"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-1","t":"등기신청권자가 스스로 등기를 하지 않았더라도 그의 책임 있는 사유로 등기가 이루어지는 데에 관여하거나 불실등기의 존재를 알고 있음에도 이를 시정하지 않고 방치하는 등 등기신청권자의 고의·과실로 불실등기를 한 것과 동일시할 수 있는 특별한 사정이 있는 경우에는, 등기신청권자에 대하여 상법 제39조에 의한 불실등기 책임을 물을 수 있다.","ox":"O","m":"①","c":"A","tp":"상업등기의 효력"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-2","t":"상업등기는 이미 존재하는 사실관계를 공시함으로써 대항력을 갖추게 하는 효력만 가질 뿐이고, 등기된 대로의 효력을 부여하는 공신력이 인정되지는 않는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"상업등기의 효력"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-3","t":"상법에 따라 등기할 사항은 등기하지 아니하면 선의의 제3자에게 대항하지 못하고, 등기한 후라도 제3자가 정당한 사유로 인하여 이를 알지 못한 때에는 대항할 수 없다.","ox":"O","m":"③","c":"A","tp":"상업등기의 효력"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-4","t":"창설적 효력이 인정되는 회사 설립등기 및 해산등기도 선의의 제3자에게 대항하지 못하고, 제3자가 정당한 사유로 등기의 내용을 알지 못한 경우에도 주장할 수 없다.","ox":"X","m":"④","c":"A","tp":"상업등기의 효력"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-5","t":"이사 선임의 주주총회결의에 대한 취소판결이 확정되어 그 결의가 소급하여 무효가 된다고 하더라도 그 선임 결의가 취소되는 대표이사와 거래한 상대방은 상법 제39조의 적용 내지 유추적용에 의하여 보호될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상업등기의 효력"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-1","t":"영업의 목적인 상행위를 개시하기 전에 한 영업을 위한 준비행위에는 상행위에 관한 상법의 규정이 적용될 수 있다.","ox":"O","m":"①","c":"A","tp":"상인과 상행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-2","t":"영업을 위한 개업준비행위에 상행위에 관한 상법의 규정이 적용되기 위해서는 영업의사가 일반적·대외적으로 표시되어야 한다.","ox":"X","m":"②","c":"A","tp":"상인과 상행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-3","t":"회사는 상행위를 하지 아니하더라도 상인으로 본다.","ox":"O","m":"③","c":"A","tp":"상인과 상행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-4","t":"회사의 기관인 대표이사 개인이 회사의 운영 자금으로 사용하려고 돈을 빌리거나 투자를 받더라도 그것만으로 상행위에 해당하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"상인과 상행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-5","t":"상인이 그 영업과 상관없이 개인 자격에서 돈을 투자하는 행위는 상인의 기존 영업을 위한 보조적 상행위가 아니다.","ox":"O","m":"⑤","c":"A","tp":"상인과 상행위"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-1","t":"지배인의 행위가 영업주의 영업에 관한 행위로 판단되는 경우에 지배인이 영업주가 정한 대리권에 관한 제한 규정에 위반하여 한 행위에 대하여는 제3자가 위 대리권의 제한 사실을 알고 있었던 경우뿐만 아니라 알지 못한 데에 중대한 과실이 있는 경우에도 영업주는 그러한 사유를 들어 상대방에게 대항할 수 있고, 이러한 제3자의 악의 또는 중대한 과실에 대한 주장·입증책임은 영업주가 부담한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-2","t":"지배인은 영업주에 갈음하여 그 영업에 관한 재판상 또는 재판 외의 모든 행위를 할 수 있고, 지배인의 대리권에 대한 제한은 선의의 제3자에게 대항하지 못하며, 여기서 지배인의 어떤 행위가 영업주의 영업에 관한 것인가의 여부는 지배인의 행위 당시의 주관적인 의사뿐만 아니라 그 행위의 객관적 성질을 함께 고려하여 판단해야 한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-3","t":"지배인의 행위가 영업에 관한 것으로서 대리권한 범위 내의 행위라 하더라도 영업주 본인의 이익이나 의사에 반하여 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 행사한 경우에 그 상대방이 지배인의 진의를 알았거나 알 수 있었을 때에는 민법 제107조 제1항 단서의 유추해석상 그 지배인의 행위에 대하여 영업주 본인은 아무런 책임을 지지 않는다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-4","t":"지배인이 내부적인 대리권 제한 규정에 위배하여 어음행위를 한 경우, 이러한 대리권의 제한에 대항할 수 있는 제3자의 범위에는 그 지배인으로부터 직접 어음을 취득한 상대방뿐만 아니라 그로부터 어음을 다시 배서양도받은 제3취득자도 포함된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-5","t":"부분적 포괄대리권을 가진 사용인의 경우에는 표현지배인에 관한 상법 제14조의 규정이 유추적용되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-1","t":"금융리스계약은 금융리스업자가 금융리스이용자에게 금융리스물건을 취득 또는 대여하는 데 소요되는 자금에 관한 금융의 편의를 제공하는 것을 본질적 내용으로 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-2","t":"금융리스업자는 금융리스이용자가 공급자로부터 상법 제168조의3 제1항에 따라 적합한 금융리스물건을 수령할 수 있도록 협력할 의무와 함께 독자적인 금융리스물건 인도의무 또는 검사·확인의무도 부담한다.","ox":"X","m":"②","c":"A","tp":"리스계약"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-3","t":"리스계약은 형식에서는 임대차계약과 유사하나 그 실질은 물적 금융이며 임대차계약과는 여러 가지 다른 특질이 있기 때문에 민법의 임대차에 관한 규정이 바로 적용되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-4","t":"리스계약은 물건의 인도를 계약성립의 요건으로 하지 않는 낙성계약으로서 리스이용자가 리스물건수령증서를 리스회사에 발급한 이상 현실적으로 리스물건이 인도되기 전이라고 하여도 이때부터 리스기간이 개시되고 리스이용자의 리스료 지급의무도 발생한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-5","t":"일반적으로 리스계약에 있어서는 리스물건의 소유권이 리스회사에게 유보되는 것 자체가 리스이용자의 리스회사에 대한 계약상의 채무 이행을 담보하는 기능을 가지고 있어 리스물건의 변환물이라고 할 수 있는 리스물건에 관한 리스회사의 보험금청구권 역시 그와 같은 담보적 기능을 가지고 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26","t":"상법상 지배인에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"상법상 지배인에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.지배인은 영업주에 갈음하여 그 영업에 관한 재판상 또는 재판 외의 모든 행위를 할 수 있는 상업사용인이다.\nㄴ.상인은 수인의 지배인에게 공동으로 대리권을 행사하게 할 수 있다. 이 경우 지배인 1인에 대한 의사표시만으로도 영업주에 대하여 효력이 있다.\nㄷ.본점 또는 지점의 본부장, 지점장, 그 밖에 지배인으로 인정될 만한 명칭을 사용하는 자는 본점 또는 지점의 지배인과 동일한 권한이 있는 것으로 본다. 이는 재판상 행위에 관하여도 마찬가지이다.\nㄹ.지배인의 행위가 영업주의 영업에 관한 것인지는 지배인의 행위 당시 주관적 의사와 관계없이 그 행위의 객관적 성질에 따라 추상적으로 판단하여야 한다. 지배인이 영업주 명의로 한 어음행위는 객관적으로 영업에 관한 행위로서 지배인의 대리권의 범위에 속하는 행위이므로 지배인이 개인적 목적을 위하여 어음행위를 한 경우에도 그 행위의 효력은 영업주에게 미친다. 이러한 법리는 표현지배인의 경우에도 동일하게 적용할 수 있다.\nㅁ.상법상 지배인에 관한 규정은 소상인에게 적용되지 않는다.","o":["ㄴ,ㄷ","ㄷ,ㄹ","ㄱ,ㄹ,ㅁ","ㄱ,ㄴ,ㄷ,ㅁ","ㄱ,ㄴ,ㄹ,ㅁ"],"a":5}},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-1","t":"일반적으로 건설회사의 현장소장에게는 회사의 부담으로 될 채무보증 또는 채무인수 등과 같은 행위를 할 권한이나 회사가 공사와 관련하여 거래상대방에 대하여 취득한 채권을 대가 없이 일방적으로 포기할 권한이 회사로부터 위임되어 있다고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"부분적 포괄대리권을 가진 사용인"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-2","t":"부분적 포괄대리권을 가진 상업사용인이 특정된 영업이나 특정된 사항에 속하지 아니하는 행위를 한 경우, 영업주가 책임을 지기 위하여는 민법상의 표현대리의 법리에 의하여 그 상업사용인과 거래한 상대방이 그 상업사용인에게 그 권한이 있다고 믿을 만한 정당한 이유가 있어야 한다.","ox":"O","m":"②","c":"A","tp":"부분적 포괄대리권을 가진 사용인"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-3","t":"상무이사는 주식회사의 기관에 해당하므로 상법 제15조 소정의 부분적 포괄대리권을 가지는 그 회사의 사용인을 겸임할 수 없다.","ox":"X","m":"③","c":"A","tp":"부분적 포괄대리권을 가진 사용인"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-4","t":"일반적으로 주식회사의 경리부장은 경상자금의 수입과 지출, 은행거래, 경리장부의 작성 및 관리 등 경리사무 일체에 관하여 그 권한을 위임받은 것으로 봄이 타당하고, 특별한 사정이 없는 한 독자적인 자금차용은 회사로부터 위임되어 있지 않다고 보아야 할 것이므로 경리부장에게 자금차용에 관한 상법 제15조의 부분적 포괄대리권이 있다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"부분적 포괄대리권을 가진 사용인"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-5","t":"부분적 포괄대리권을 가진 상업사용인이 그 범위 내에서 한 행위는 설사 상업사용인이 영업주 본인의 이익이나 의사에 반하여 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 남용한 것이라 할지라도 일단 영업주 본인의 행위로서 유효하나, 그 행위의 상대방이 상업사용인의 진의를 알았거나 알 수 있었을 때에는 민법 제107조 제1항 단서의 유추해석상 그 행위에 대하여 영업주 본인에 대하여 무효가 된다.","ox":"O","m":"⑤","c":"A","tp":"부분적 포괄대리권을 가진 사용인"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-1","t":"채권매매거래의 위탁계약의 성립 시기는 위탁금이나 위탁채권을 받을 직무상의 권한이 있는 직원이 채권매매거래를 위탁한다는 의사로 이를 위탁하는 고객으로부터 금원이나 채권을 수령하면 곧바로 위탁계약이 성립하고, 그 이후에 그 직원의 금원수납에 관한 처리는 계약의 성립에 영향이 없다.","ox":"O","m":"①","c":"A","tp":"위탁매매업"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-2","t":"위탁매매인이 그가 제3자에 대하여 부담하는 채무를 담보하기 위하여 그 채권자에게 위탁매매로 취득한 채권을 양도한 경우에 위탁매매인은 위탁자에 대한 관계에서는 위탁자에 속하는 채권을 무권리자로서 양도한 것이므로, 그 채권양도는 무권리자의 처분 일반에서와 마찬가지로 양수인이 그 채권을 선의취득하였다는 등의 특별한 사정이 없는 한 위탁자에 대하여 효력이 없다.","ox":"O","m":"②","c":"A","tp":"위탁매매업"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-3","t":"위탁매매란 자기의 명의로 타인의 계산에 의하여 물품을 매수 또는 매도하고 보수를 받는 것으로서 명의와 계산의 분리를 본질로 한다.","ox":"O","m":"③","c":"A","tp":"위탁매매업"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-4","t":"위탁자의 위탁상품 공급으로 인한 위탁매매인에 대한 이득상환청구권이나 이행담보책임 이행청구권은 위탁자의 위탁매매인에 대한 상품 공급과 서로 대가관계에 있으므로 민법 제163조 제6호 소정의 ‘상인이 판매한 상품의 대가’에 해당하여 3년의 단기소멸시효가 적용된다.","ox":"X","m":"④","c":"A","tp":"위탁매매업"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-5","t":"위탁매매인이 위탁자로부터 받은 물건 또는 유가증권이나 위탁매매로 인하여 취득한 물건, 유가증권 또는 채권은 위탁자와 위탁매매인 또는 위탁매매인의 채권자 간의 관계에서는 이를 위탁자의 소유 또는 채권으로 본다.","ox":"O","m":"⑤","c":"A","tp":"위탁매매업"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-1","t":"해상운송사업을 영위하는 자를 위하여 그 사업에 속하는 거래의 대리를 업무로 하는 자로서 운송인과의 계약에 따라 화물의 교부와 관련한 일체의 업무를 수행하는 선박대리점이 운송물에 대한 점유를 이전받기 이전에 실제 운송인 및 터미널 운영업자의 과실로 인하여 화물이 소훼되었다면, 선박대리점에게 운송물의 멸실에 대한 불법행위책임을 물을 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-2","t":"운송인은 그 운송을 위한 화물의 적부(積付)에 있어 선장·선원 내지 하역업자로 하여금 화물이 서로 부딪치거나, 혼합되지 않도록 그리고 선박의 동요 등으로부터 손해를 입지 않도록 하는 적절한 조치와 함께 운송물을 적당하게 선창 내에 배치하여야 하나, 적부가 독립된 하역업자나 송하인의 지시에 의하여 이루어졌다면 운송인은 그러한 적부에 관하여 손해를 방지하기 위한 적절한 예방조치를 강구하여야 할 주의의무가 있다고 할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-3","t":"운송주선인은 하주나 운송인의 대리인이 되기도 하고 위탁자의 이름으로 운송계약을 체결하는 경우에도 운송주선인임에는 변함이 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-4","t":"운송주선인이 운송인의 지위를 취득하지 않는 한, 운송인의 대리인으로서 운송계약을 체결하였더라도 운송의뢰인에 대한 관계에서는 여전히 운송주선인의 지위에 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-5","t":"운송주선업자가 운송의뢰인으로부터 운송관련 업무를 의뢰받은 경우 운송까지 의뢰받은 것인지, 운송주선만을 의뢰받은 것인지 여부가 명확하지 않은 때에는 당사자의 의사를 탐구하여 운송인의 지위도 함께 취득하였는지 여부를 확정하여야 할 것이지만, 그 의사가 명확하지 않으면 선하증권의 발행자 명의, 운임의 지급형태 등 제반 사정을 종합적으로 고려하여 논리와 경험칙에 따라 운송주선업자가 운송의뢰인으로부터 운송을 인수하였다고 볼 수 있는지 여부를 확정하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-1","t":"합자조합에서 업무집행조합원은 다른 조합원 과반수의 동의를 받으면 그 지분의 전부 또는 일부를 타인에게 양도할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법 제78조의 익명조합 또는 상법 제86조의2의 합자조합"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-2","t":"합자조합에서 둘 이상의 업무집행조합원이 있는 경우 조합계약에 다른 정함이 없으면 그 각 업무집행조합원의 업무집행에 관한 행위에 대하여 다른 업무집행조합원의 이의가 있는 경우에는 그 행위를 중지하고 업무집행조합원 과반수의 결의에 따라야 한다.","ox":"O","m":"②","c":"A","tp":"상법 제78조의 익명조합 또는 상법 제86조의2의 합자조합"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-3","t":"익명조합원은 금전 기타 재산으로 출자할 수 있을 뿐만 아니라 신용이나 노무의 출자도 가능하다.","ox":"X","m":"③","c":"A","tp":"상법 제78조의 익명조합 또는 상법 제86조의2의 합자조합"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-4","t":"시설투자자에게 영업에서 이익이 난 여부를 따지지 않고 정기적으로 일정액을 지급할 것을 약정하고, 대외적 거래관계는 타방(경영자)이 그 명의로 단독으로 하며 그에게만 권리의무가 귀속되도록 약정한 동업관계의 경우 상법상 익명조합에 해당한다.","ox":"X","m":"④","c":"A","tp":"상법 제78조의 익명조합 또는 상법 제86조의2의 합자조합"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-5","t":"익명조합원은 조합의 사업에 손실이 발생해 출자금이 감소된 경우라 하더라도 그 손실을 채우지 않고서도 이익배당을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"상법 제78조의 익명조합 또는 상법 제86조의2의 합자조합"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-1","t":"상행위로 인하여 생긴 채권을 담보하기 위한 질권설정계약에 대해서는 유질약정을 허용하고 있다.","ox":"O","m":"①","c":"A","tp":"상법상 상사유치권(제58조) 또는 유질계약(제59조)"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-2","t":"상법은 유질약정이 체결된 경우 질권의 실행 방법이나 절차에 관하여는 아무런 규정을 두고 있지 않으므로, 유질약정이 포함된 질권설정계약이 체결된 경우 질권의 실행 방법이나 절차는 원칙적으로 질권설정계약에서 정한 바에 따라야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 상사유치권(제58조) 또는 유질계약(제59조)"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-3","t":"상사유치권 배제의 특약은 묵시적 약정에 의해서도 가능하다.","ox":"O","m":"③","c":"A","tp":"상법상 상사유치권(제58조) 또는 유질계약(제59조)"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-4","t":"질권설정계약에 포함된 유질약정이 상법 제59조에 따라 유효하기 위해서는 질권설정자와 질권자 쌍방이 모두 상인이어야 한다.","ox":"X","m":"④","c":"A","tp":"상법상 상사유치권(제58조) 또는 유질계약(제59조)"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-5","t":"일방적 상행위로 생긴 채권을 담보하기 위한 질권에 대해서도 유질약정을 허용한 상법 제59조가 적용된다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상사유치권(제58조) 또는 유질계약(제59조)"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-1","t":"영업양도는 일정한 영업목적에 의하여 조직화된 업체, 즉 인적·물적 조직을 그 동일성은 유지하면서 일체로서 이전하는 것으로서 영업의 일부만의 양도도 가능하다.","ox":"O","m":"①","c":"A","tp":"상법상 영업양도"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-2","t":"영업재산의 전부를 양도한 경우에 그 조직을 해체하여 양도했다 하더라도 영업의 양도로 볼 수 있다.","ox":"X","m":"②","c":"A","tp":"상법상 영업양도"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-3","t":"영업양도가 이루어진 경우 별도의 특약이 있어야 해당 근로자들의 근로관계가 양수하는 기업에 포괄적으로 승계된다.","ox":"X","m":"③","c":"A","tp":"상법상 영업양도"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-4","t":"영업을 양도한 경우에 다른 약정이 없으면 양도인은 5년간 동일한 특별시ㆍ광역시ㆍ시ㆍ군과 인접 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업을 하지 못한다.","ox":"X","m":"④","c":"A","tp":"상법상 영업양도"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-5","t":"영업을 양도한 자가 동종영업을 하지 아니할 것을 약정한 때에는 동일한 특별시ㆍ광역시ㆍ시ㆍ군과 인접 특별시ㆍ광역시ㆍ시ㆍ군에 한하여 10년을 초과하지 아니한 범위 내에서 효력이 있다.","ox":"X","m":"⑤","c":"A","tp":"상법상 영업양도"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43-1","t":"어떤 자가 제조자나 공급자와 대리점계약이라는 명칭의 계약을 체결하였다고 하여 곧바로 상법 제87조의 대리상으로 되는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43-2","t":"어떠한 법률관계가 내적 조합에 해당하는지 아니면 익명조합에 해당하는지는 당사자들의 내부관계에 있어서 공동사업이 있는지, 조합원이 업무검사권 등을 가지고 조합의 업무에 관여하였는지, 재산의 처분 또는 변경에 전원의 동의가 필요한지 등을 모두 종합하여 판단하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43-3","t":"해상운송화물이 통관을 위하여 보세창고에 입고된 경우에는 운송인과 보세창고업자 사이에 해상운송화물에 관하여 묵시적 임치계약이 성립한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43-4","t":"보세창고업자는 운송인의 이행보조자로서 해상운송의 정당한 수령인인 수하인 또는 수하인이 지정하는 자에게 화물을 인도할 의무를 부담한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43-5","t":"보세창고업자는 화물 인도 과정에서 운송인이 발행한 화물인도지시서가 화물을 인도할 수 있는 근거서류로 적법하게 발행되었는지 등을 확인할 주의의무를 부담하는데, 선하증권을 취득하지 못한 신용장 개설은행에 대해서도 이러한 주의의무를 부담한다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46-1","t":"상인은 영업상의 재산 및 손익의 상황을 명백히 하기 위하여 회계장부 및 대차대조표를 작성하여야 하고, 그 작성에 관하여 상법에 규정한 것을 제외하고는 일반적으로 공정ㆍ타당한 회계관행에 의한다.","ox":"O","m":"①","c":"A","tp":"상업장부와 상업등기"},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46-2","t":"상인은 상업장부와 영업에 관한 중요서류를 10년간 보존하여야 하지만 전표 또는 이와 유사한 서류는 5년간 이를 보존하면 된다. 상업장부에 관한 보존기간의 기산점은 그 장부를 폐쇄한 날이다.","ox":"O","m":"②","c":"A","tp":"상업장부와 상업등기"},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46-3","t":"상법에 따라 등기할 사항을 등기하지 아니하면 선의의 제3자에게 대항할 수 없다. 그 등기를 한 후라도 제3자가 정당한 사유로 인하여 이를 알지 못한 때에는 마찬가지이다.","ox":"O","m":"③","c":"A","tp":"상업장부와 상업등기"},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46-4","t":"법인등기부에 이사 또는 감사로 등재되어 있더라도 정당한 절차에 의하여 선임된 적법한 이사 또는 감사로 추정되지 않는다.","ox":"X","m":"④","c":"A","tp":"상업장부와 상업등기"},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46-5","t":"회사등기에는 공신력이 인정되지 않는다. 따라서 합자회사의 사원 지분등기가 불실등기인 경우 그 불실등기를 믿고 합자회사 사원의 지분을 양수하였다 하여 그 지분을 양수한 것으로는 될 수 없다.","ox":"O","m":"⑤","c":"A","tp":"상업장부와 상업등기"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48-1","t":"甲이 乙에게 자신의 사업자명의를 사용하여 영업할 것을 허락하였고, 丙이 甲을 영업주로 오인하여 乙과 물품거래를 하였으며, 乙이 丙에게 물품대금 일부를 대물변제하였다면 乙의 시효중단 사유인 채무승인의 효력이 甲에게는 미치지 않는다.","ox":"O","m":"①","c":"A","tp":"소멸시효"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48-2","t":"채권자가 영업양도가 이루어진 뒤 영업양도인을 상대로 소를 제기하여 확정판결을 받았다면 그와 같은 소멸시효 중단이나 소멸시효 연장의 효과는 상호를 속용하는 영업양수인에게 미치지 않는다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48-3","t":"창고업자인 甲이 선하증권이나 화물인도지시서와 상환하지 않고 임치물을 제3자에게 인도하였고, 임치물의 소유자인 乙이 甲에게 불법행위로 인한 손해배상을 청구하는 경우, 甲은 상법 제166조 제1항의 물건을 출고한 날로부터 1년의 소멸시효 항변을 할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48-4","t":"운송주선인이 자기 이름으로 운송계약을 체결한 경우 운송주선인에 대한 운송인의 채권은 1년의 단기소멸시효에 걸린다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48-5","t":"기존회사가 채무를 면탈하기 위하여 기업의 형태·내용이 실질적으로 동일한 신설회사를 설립하여 기존회사의 채무면탈이라는 위법한 목적 달성을 위하여 회사제도를 남용한 것에 해당한다면, 기존회사에 대한 소멸시효가 완성되지 않은 상태에서 신설회사가 기존회사와 별도로 자신에 대하여 소멸시효가 완성되었다고 주장하는 것은 허용될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-1","t":"당사자 쌍방에 대하여 모두 상행위가 되는 행위로 인한 채권뿐만 아니라 당사자 일방에 대하여만 상행위에 해당하는 행위로 인한 채권도 상법 제64조에서 정한 5년의 소멸시효기간이 적용되는 상사채권에 해당하고, 그 상행위에는 상법 제46조 각 호에 해당하는 기본적 상행위뿐만 아니라 상인이 영업을 위하여 하는 보조적 상행위도 포함된다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-2","t":"상법 제5조, 제47조에 의하면 회사는 상행위를 하지 않더라도 상인으로 보고, 상인이 영업을 위하여 하는 행위는 상행위로 보며, 상인의 행위는 영업을 위하여 하는 것으로 추정된다. 그러므로 회사가 한 행위는 그 영업을 위하여 한 것으로 추정되고, 회사가 그 영업을 위하여 하는 행위는 상행위로 보아야 한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-3","t":"상인은 자기 명의로 상행위를 하는 자를 의미하는데, 여기서 ‘자기 명의’란 상행위로부터 생기는 권리의무의 귀속주체로 된다는 뜻으로서 실질에 따라 판단하여야 하므로, 행정관청에 대한 인·허가 명의나 국세청에 신고한 사업자등록상의 명의와 실제 영업상의 주체가 다를 경우 후자가 상인이 된다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-4","t":"한국토지공사가 택지개발사업을 시행하기 위하여 토지 소유자로부터 사업 시행을 위한 토지를 매수하는 행위를 하는 경우에는 한국토지공사를 상인이라고 볼 수 있으므로, 한국토지공사가 택지개발사업 지구 내에 있는 토지에 관하여 토지 소유자와 매매계약을 체결한 행위는 상행위로 볼 수 있다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-5","t":"상법 제3조에 따라 당사자 중 그 1인의 행위가 상행위인 때에는 전원에 대하여 상법이 적용되므로, 당사자의 일방이 수인인 경우에 그중 1인에게만 상행위가 되더라도 전원에 대하여 상법이 적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-1","t":"극장, 여관, 음식점, 그 밖의 공중이 이용하는 시설에 의한 거래를 영업으로 하는 자는 상법상 공중접객업자이다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-2","t":"상법 제152조 제1항의 규정에 의한 임치가 성립하려면 우선 공중접객업자와 객 사이에 공중접객업자가 자기의 지배영역 내에서 목적물 보관의 채무를 부담하기로 하는 명시적 또는 묵시적 합의가 있음을 필요로 한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-3","t":"숙박업을 영위하는 공중접객업자는 투숙객이 소지한 물건 및 부설주차장에 주차한 차량에 한해서는 무조건 상법 제152조 제1항에서 규정하는 임치받은 물건에 관한 손해배상책임을 부담한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-4","t":"숙박업을 영위하는 공중접객업자는 투숙객과 체결한 숙박계약에 따라, 통상의 임대차와 같이 단순히 여관 등의 객실 및 관련 시설을 제공하여 고객으로 하여금 이를 사용·수익하게 할 의무를 부담하는 것에서 한 걸음 더 나아가 고객에게 위험이 없는 안전하고 편안한 객실 및 관련 시설을 제공함으로써 고객의 안전을 배려하여야 할 보호의무를 부담한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-5","t":"공중접객업자가 화폐, 유가증권, 그 밖의 고가물의 물건의 멸실 또는 훼손으로 인한 손해를 배상할 책임을 부담하더라도, 이는 공중접객업자가 임치물을 반환하거나 고객이 휴대물을 가져간 후 6개월이 지나면 소멸시효가 완성된다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-1","t":"상법 제57조 제1항은 상사거래에 있어서의 인적 담보를 강화하여 채무이행을 확실히 하고 거래의 안전을 도모함으로써 상거래의 원활을 기하려는 것으로 민법상 다수당사자간의 채무이행에 있어서의 분할채무 원칙에 대한 특별규정이다. 여기에서 연대채무를 지우게 되는 행위는 수인이 그 1인 또는 전원에게 상행위가 되는 행위로 인하여 채무를 부담하는 경우이어야 한다.","ox":"O","m":"①","c":"A","tp":"상사채무의 연대성(상법 제57조)"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-2","t":"피고들이 양말제조업을 공동으로 경영하며 원고로부터 계속적으로 원사구입을 하여 왔을 경우에 현재까지 지급하지 못한 외상대금이 남아 있다면 이는 피고들의 기본적 상행위로 인하여 부담하게 된 것이므로 피고들은 연대하여 원고에 대하여 채무를 변제할 책임이 있다.","ox":"O","m":"②","c":"A","tp":"상사채무의 연대성(상법 제57조)"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-3","t":"공동수급체의 구성원들이 상인인 경우 탈퇴한 조합원에 대하여 잔존 조합원들이 탈퇴 당시의 조합재산상태에 따라 탈퇴 조합원의 지분을 환급할 의무는 구성원 전원의 상행위에 따라 부담한 채무로서 공동수급체의 구성원들인 잔존 조합원들은 연대하여 탈퇴한 조합원에게 지분환급의무를 이행할 책임이 있다.","ox":"O","m":"③","c":"A","tp":"상사채무의 연대성(상법 제57조)"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-4","t":"피고 甲과 피고 乙이 시멘트 등을 제조판매하는 원고로부터 물품을 구입하여 동업으로 도로포장 공사를 하되 피고 甲은 주로 원고에 대한 교섭과 사업자금을 제공하고 피고 乙은 물품의 구입과 납품 등 업무를 분담 종사한 경우에는 피고 甲과 피고 乙은 동업자로서 원고에 대하여 상법 제57조에 따른 상행위로 인하여 물품대금채무를 부담한 것이므로 연대하여 이를 변제할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"상사채무의 연대성(상법 제57조)"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-5","t":"상가건물의 일부에서 숙박업을 하는 공유자들이 건물의 관리를 담당한 단체와 체결한 숙박사업장의 관리에 관한 계약은 내부적 관리업무의 일환에 따른 것이므로 상법 제57조 제1항에서 규정하는 상행위에 해당하기 어렵고 위 공유자들은 지분비율에 따른 액수만큼 개별적으로 관리비 지급의무를 부담한다.","ox":"X","m":"⑤","c":"A","tp":"상사채무의 연대성(상법 제57조)"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28-1","t":"한국철도공사와 여행업체가 위탁운영 협약을 체결하여 여행업체가 관광열차를 이용한 여행상품을 판매·운영하고 위 여행상품 판매대금에서 판매·운영수수료, 행사비용, 운영비용을 공제한 나머지를 매월 정산하여 한국철도공사에 지급하였는데 양자간 협약상 한국철도공사는 열차 운행의 횟수나 편성 등에 관여할 수 있는 등 관광열차 판매·운영에 광범위한 권한을 가지고 관광열차 관련 지적재산권 등 일체의 권리 또한 한국철도공사에 귀속되었으며, 가격조정에도 한국철도공사의 동의가 필요하였고 여행업체에게 귀속되는 판매·운영수수료는 위 여행상품 총매출액의 일정 비율에 해당하는 금액에 해당하였다면, 여행업체는 자기 명의로 그러나 한국철도공사의 계산으로 위 여행상품 관련 용역의 제공을 영업으로 하는 준위탁매매인에 해당한다고 볼 수 있다.","ox":"O","m":"①","c":"A","tp":"위탁매매업 및 준위탁매매"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28-2","t":"자기명의로써 타인의 계산으로 매매아닌 행위를 영업으로 하는 자에게는 상법상 위탁매매에 관한 규정이 준용되지 않는다.","ox":"X","m":"②","c":"A","tp":"위탁매매업 및 준위탁매매"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28-3","t":"위탁매매인이 그가 제3자에 대하여 부담하는 채무를 담보하기 위하여 그 채권자에게 위탁매매로 취득한 채권을 양도한 경우에 위탁매매인은 위탁자에 대한 관계에서는 위탁자에 속하는 채권을 무권리자로서 양도한 것이고, 따라서 그 채권양도는 무권리자의 처분 일반에서와 마찬가지로 양수인이 그 채권을 선의취득하였다는 등의 특별한 사정이 없는 한 위탁자에 대하여 효력이 없다.","ox":"O","m":"③","c":"A","tp":"위탁매매업 및 준위탁매매"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28-4","t":"위탁매매란 자기명의로써 타인의 계산으로 물품을 매수 또는 매도하고 보수를 받는 것으로서 명의와 계산의 분리를 본질로 하며, 어떠한 계약이 일반의 매매계약인지 위탁매매계약인지는 계약의 명칭 또는 형식적인 문언을 떠나 그 실질을 중시하여 판단하여야 한다.","ox":"O","m":"④","c":"A","tp":"위탁매매업 및 준위탁매매"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28-5","t":"위탁매매인이 거래소의 시세가 있는 물건 또는 유가증권의 매매를 위탁받은 경우에는 직접 그 매도인이나 매수인이 될 수 있다. 이 경우의 매매대가는 위탁매매인이 매매의 통지를 발송할 때의 거래소의 시세에 따른다.","ox":"O","m":"⑤","c":"A","tp":"위탁매매업 및 준위탁매매"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-1","t":"상인간의 매매에 있어서 매수인이 목적물을 수령한 때에는 지체없이 이를 검사하여야 하며 하자 또는 수량의 부족을 발견한 경우에는 즉시, 즉시 발견할 수 없는 하자가 있는 경우에는 6월 내에 매수인이 매도인에게 그 통지를 발송하지 아니하면 이로 인한 계약해제, 대금감액 또는 손해배상을 청구하지 못하도록 규정하고 있는 상법 제69조 제1항은, 민법의 매매에 관한 규정이 민법 제567조에 의하여 매매 이외의 유상계약에 준용되는 것과 마찬가지로 상인간의 수량을 지정한 건물의 임대차계약에 준용될 수 있다.","ox":"X","m":"①","c":"A","tp":"매수인의 목적물의 검사와 하자통지의무를 규정한 상법 제69조"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-2","t":"상법 제69조의 규정은 상인간의 매매에 적용되는 것이며 매수인이 상인인 한 매도인이 상인인지 여부를 불문하고 위 규정이 적용되어야 하는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"매수인의 목적물의 검사와 하자통지의무를 규정한 상법 제69조"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-3","t":"상법 제69조 제1항의 취지는 상인간의 매매에 있어 그 계약의 효력을 민법 규정과 같이 오랫동안 불안정한 상태로 방치하는 것은 매도인에 대하여는 인도 당시의 목적물에 대한 하자의 조사를 어렵게 하고 전매의 기회를 잃게 될 뿐만 아니라, 매수인에 대하여는 그 기간 중 유리한 시기를 선택하여 매도인의 위험으로 투기를 할 수 있는 기회를 주게 되는 폐단 등이 있어 이를 막기 위하여 하자를 용이하게 발견할 수 있는 전문적 지식을 가진 매수인에게 신속한 검사와 통지의 의무를 부과함으로써 상거래를 신속하게 결말짓도록 한 것이다.","ox":"O","m":"③","c":"A","tp":"매수인의 목적물의 검사와 하자통지의무를 규정한 상법 제69조"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-4","t":"상법 제69조 제1항은 민법상의 매도인의 담보책임에 대한 특칙이며, 그 성질상 임의규정으로 보아야 할 것이다. 따라서 당사자간의 약정에 의하여 이와 달리 정할 수 있다고 할 것이다.","ox":"O","m":"④","c":"A","tp":"매수인의 목적물의 검사와 하자통지의무를 규정한 상법 제69조"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-5","t":"상법 제69조에서 규정하는 하자담보책임의 전제요건인 매수인의 목적물 검사와 하자통지사실에 관한 증명책임은 매수인에게 있다.","ox":"O","m":"⑤","c":"A","tp":"매수인의 목적물의 검사와 하자통지의무를 규정한 상법 제69조"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-1","t":"상법 제25조 제1항은 “상호는 영업을 폐지하거나 영업과 함께 하는 경우에 한하여 이를 양도할 수 있다.”고 규정하고 있어 영업과 분리하여 상호만을 양도할 수 있는 것은 영업의 폐지의 경우에 한하여 인정되는데, 이는 양도인의 영업과 양수인의 영업과의 사이에 혼동을 일으키지 않고 또 폐업하는 상인이 상호를 재산적 가치물로서 처분할 수 있도록 하기 위한 것이다.","ox":"O","m":"①","c":"A","tp":"상법상 상호"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-2","t":"상법 제25조 제1항의 ‘영업의 폐지’라 함은 정식으로 영업폐지에 필요한 행정절차를 밟아 폐업하는 경우에 한하고, 사실상 폐업한 경우에는 언제든지 다시 영업을 재개할 수 있으므로 이에 해당하지 않는다.","ox":"X","m":"②","c":"A","tp":"상법상 상호"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-3","t":"상법 제23조 제1항은 “누구든지 부정한 목적으로 타인의 영업으로 오인할 수 있는 상호를 사용하지 못한다.”고 규정하고 있는데, 위 규정의 취지는 일반거래시장에서 상호에 관한 공중의 오인·혼동을 방지하여 이에 대한 신뢰를 보호함과 아울러 상호권자가 타인의 상호와 구별되는 상호를 사용할 수 있는 이익을 보호하는 데 있다.","ox":"O","m":"③","c":"A","tp":"상법상 상호"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-4","t":"상법 제23조 제1항에 규정된 ‘부정한 목적’이란 어느 명칭을 자기의 상호로 사용함으로써 일반인으로 하여금 자기의 영업을 명칭에 의하여 표시된 타인의 영업으로 오인하게 하여 부당한 이익을 얻으려 하거나 타인에게 손해를 가하려고 하는 등의 부정한 의도를 말하고, 부정한 목적이 있는지는 상인의 명성이나 신용, 영업의 종류·규모·방법, 상호 사용의 경위 등 여러 가지 사정을 종합하여 판단하여야 한다.","ox":"O","m":"④","c":"A","tp":"상법상 상호"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-5","t":"상법 제23조 제1항의 입법 취지에 비추어 볼 때 어떤 상호가 ‘타인의 영업으로 오인할 수 있는 상호’에 해당하는지를 판단할 때에는 양 상호 전체를 비교 관찰하여 각 영업의 성질이나 내용, 영업 방법, 수요자층 등에서 서로 밀접한 관련을 가지고 있는 경우로서 일반인이 양 업무의 주체가 서로 관련이 있는 것으로 생각하거나 또는 타인의 상호가 현저하게 널리 알려져 있어 일반인으로부터 기업의 명성으로 견고한 신뢰를 획득한 경우에 해당하는지를 종합적으로 고려하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 상호"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-1","t":"영업양도계약에서 경업금지에 관하여 정함이 없는 경우에도 영업양수인은 영업양도인에게 상법 제41조 제1항에 따라 경업금지청구권을 행사할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-2","t":"영업양도계약에서 경업금지청구권의 양도와 관련하여 특별한 정함이 없는 상태에서 양도된 영업이 다시 동일성을 유지한 채 전전양도되는 경우, 영업양수인의 경업금지청구권과 이에 관한 양도통지의 권한은 원칙적으로 그 뒤의 영업양수인에게 전전양도 및 전전이전되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-3","t":"영업양도는 일정한 영업목적에 의하여 조직화된 업체, 즉 인적·물적 조직을 그 동일성은 유지하면서 일체로서 이전하는 것으로서 영업의 일부양도도 가능하다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-4","t":"회사가 기존 영위하던 사업 부문을 폐지함에 따라 근로자들 전부가 사직서를 제출하고 퇴직금을 정산, 수령하였고 그중 절반 정도의 근로자들은 다른 직장에 취업하였으며 나머지 절반 정도의 근로자들만이 폐지되는 사업 부분과 동일한 사업을 하고 있던 계열회사에 입사시험 없이 종전 수준의 임금을 지급받기로 하고 입사한 경우, 기존 회사는 그 사업 부문을 폐지한 것에 불과할 뿐, 두 회사 사이에 영업양도가 있었다고 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-5","t":"영업재산의 일부를 유보한 채 영업시설을 양도했어도 그 양도한 부분만으로도 종래의 조직이 유지되어 있다고 사회관념상 인정되면 그것을 영업의 양도라 볼 수 있고, 이러한 영업양도는 반드시 영업양도 당사자 사이의 명시적 계약에 의하여야 하는 것은 아니며 묵시적 계약에 의하여도 가능하다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-1","t":"지배인은 영업주의 영업활동을 보조하는 대리인이지만 상법 제11조에 의하여 영업주의 대외적인 영업거래에 대하여 정형적·획일적·포괄적인 대리권을 가지므로, 영업주가 정한 대리권에 관한 제한 규정에 위반한 지배인과 거래한 상대방은 과실이 있더라도 중과실이 아닌 한 보호받는다.","ox":"O","m":"①","c":"A","tp":"지배인의 대리권"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-2","t":"지배인은 영업주에 갈음하여 영업에 관한 재판상·재판 외의 모든 행위를 할 수 있는데, 영업에 관한 행위란 영업의 목적이 되는 행위 뿐 아니라 영업을 위하여 직·간접으로 필요한 행위를 의미한다.","ox":"O","m":"②","c":"A","tp":"지배인의 대리권"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-3","t":"지배인의 어떤 행위가 영업주의 영업에 관한 것인가의 여부는 지배인의 행위 당시의 주관적인 의사와는 관계없이 그 행위의 객관적 성질에 따라 추상적으로 판단되어야 한다.","ox":"O","m":"③","c":"A","tp":"지배인의 대리권"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-4","t":"지배인의 행위가 영업에 관한 것으로서 대리권한 범위 내의 행위라 하더라도 영업주 본인의 이익이나 의사에 반하여 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 행사한 경우에 그 상대방이 지배인의 진의를 알았거나 알 수 있었을 때에는 민법 제107조 제1항 단서의 유추해석상 그 지배인의 행위에 대하여 영업주 본인은 아무런 책임을 지지 않는다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"지배인의 대리권"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-5","t":"지배인이 내부적인 대리권제한규정에 위배하여 어음행위를 한 경우 이러한 대리권의 제한에 대항할 수 있는 제3자의 범위에는 그 지배인으로부터 직접 어음을 취득한 상대방에 한한다.","ox":"X","m":"⑤","c":"A","tp":"지배인의 대리권"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-1","t":"상법 제24조의 명의대여자의 책임규정은 거래상의 외관보호와 금반언의 원칙을 표현한 것으로, 명의대여자가 영업주로서 자기의 성명이나 상호를 사용하는 것을 허락했을 때에는 명의차용자가 그것을 사용하여 법률행위를 함으로써 지게 된 거래상의 채무에 대하여 변제의 책임이 있다는 것을 밝히고 있으므로 여기에 근거한 명의대여자의 책임은 명의의 사용을 허락받은 자가 피용자를 고용하여 영업한 경우 그 피용자의 행위에 대해서까지 미친다.","ox":"X","m":"①","c":"A","tp":"상법상 명의대여"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-2","t":"일반거래에 있어서 실질적인 법률관계는 대리상, 특약점 또는 위탁매매업 등이면서도 두루 대리점이란 명칭으로 통용되고 있는데다가 타인의 상호아래 대리점이란 명칭을 붙인 경우는 그 아래 지점, 영업소, 출장소 등을 붙인 경우와는 달리 타인의 영업을 종속적으로 표시하는 부가부분이라고 보기도 어렵기 때문에 제3자가 자기의 상호아래 대리점이란 명칭을 붙여 사용하는 것을 허락하거나 묵인하였더라도 상법상 명의대여자로서의 책임을 물을 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-3","t":"상법 제24조에 의한 명의대여자와 명의차용자의 책임은 동일한 경제적 목적을 가진 채무로서 서로 중첩되는 부분에 관하여 일방의 채무가 변제 등으로 소멸하면 타방의 채무도 소멸하는 이른바 부진정연대의 관계에 있다. 이와 같은 부진정연대채무에서는 채무자 1인에 대한 이행청구 또는 채무자 1인이 행한 채무의 승인 등 소멸시효의 중단사유나 시효이익의 포기가 다른 채무자에게 효력을 미치지 아니한다.","ox":"O","m":"③","c":"A","tp":"상법상 명의대여"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-4","t":"상법 제24조는 타인에게 명의를 대여하여 영업을 하게 한 경우 그 명의대여자가 영업주인 줄로 알고 거래한 선의의 제3자를 보호하기 위하여 그 거래로 인하여 발생한 명의차용자의 채무에 대하여는 그 외관을 만드는데에 원인을 제공한 명의대여자에게도 명의차용자와 같이 변제책임을 지우자는 것으로서 그 명의대여자가 상인이 아니거나, 명의차용자의 영업이 상행위가 아니라 하더라도 위 법리를 적용하는데에 아무런 영향이 없다.","ox":"O","m":"④","c":"A","tp":"상법상 명의대여"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-5","t":"영업주가 자기의 상점, 전화, 창고 등을 타인에게 사용하게 한 사실은 있으나 그 타인과 원고와의 거래를 위하여 영업주의 상호를 사용한 사실이 없는 경우에는 영업주가 자기의 상호를 타인에게 묵시적으로 대여하여 원고가 그 타인을 영업주로 오인하여 거래하였다고 보기 어렵다.","ox":"O","m":"⑤","c":"A","tp":"상법상 명의대여"},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22-1","t":"대리상은 당사자 간에 다른 약정이 없는 한 거래의 대리 또는 중개로 인한 채권이 변제기에 있는 때에는 그 변제를 받을 때까지 본인을 위하여 점유하는 물건 또는 유가증권을 유치할 수 있다.","ox":"O","m":"①","c":"A","tp":"상인 등"},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22-2","t":"중개인은 중개를 한 당사자 간에 계약이 성립된 때에는 지체 없이 각 당사자의 성명 또는 상호, 계약연월일과 그 요령을 기재한 서면을 작성하여 기명날인 또는 서명한 후 각 당사자에게 교부하여야 한다.","ox":"O","m":"②","c":"A","tp":"상인 등"},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22-3","t":"중개인은 별도의 약정이나 관습이 없더라도, 그 중개한 행위에 관하여 당사자를 위하여 지급 기타의 이행을 받을 수 있다.","ox":"X","m":"③","c":"A","tp":"상인 등"},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22-4","t":"위탁매매인은 위탁자를 위한 매매에 관하여 상대방이 채무를 이행하지 아니 하는 경우에는 특별한 사정이 없는 한 위탁자에 대하여 이를 이행할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"상인 등"},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22-5","t":"운송주선인은 운송물에 관하여 받을 보수, 운임, 기타 위탁자를 위한 체당금이나 선대금에 관하여서만 그 운송물을 유치할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상인 등"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-1","t":"변호사법은 법무법인에 관하여 변호사법에 정한 것 외에는 상법 중 합명회사에 관한 규정을 준용하도록 하고 있어 상법상 회사로 인정하고 있으므로 법무법인은 상법 제5조 제2항에서 정하는 의제상인에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-2","t":"법무사에 대하여는 법령에 의하여 상당한 정도로 그 영리추구 활동이 제한됨과 아울러 직무의 공공성이 요구되고 있는 것으로 보아야 할 것이므로, 법무사를 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고 볼 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-3","t":"변호사는 상법상 당연상인으로 볼 수 없고, 변호사를 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고도 볼 수 없어 위 조항에서 정하는 의제상인에 해당하지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-4","t":"영업을 준비하는 행위가 보조적 상행위로서 상법의 적용을 받기 위해서는 행위를 하는 자 스스로 상인자격을 취득하는 것을 당연한 전제로 하므로, 어떠한 자가 자기 명의로 상행위를 함으로써 상인자격을 취득하고자 준비행위를 하는 것이 아니라 다른 상인의 영업을 위한 준비행위를 하는 것에 불과하다면, 그 행위는 행위를 한 자의 보조적 상행위가 될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-5","t":"회사 설립을 위하여 개인이 한 행위는 그것이 설립 중 회사의 행위로 인정되어 장래 설립될 회사에 효력이 미쳐 회사의 보조적 상행위가 될 수 있는지는 별론으로 하고, 장래 설립될 회사가 상인이라는 이유만으로 당연히 개인의 상행위가 되어 상법 규정이 적용된다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-1","t":"채무자가 영업재산과 영업권이 유기적으로 결합된 일체로서의 영업을 양도함으로써 채무초과상태에 이르거나 이미 채무초과상태에 있는 것을 심화시킨 경우, 영업양도는 채권자취소권 행사의 대상이 된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-2","t":"영업양도가 이루어진 경우에는 원칙적으로 해당 근로자들의 근로관계가 양수하는 기업에 포괄적으로 승계된다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-3","t":"영업재산의 일부를 유보한 채 영업시설을 양도했어도 그 양도한 부분만으로도 종래의 조직이 유지되어 있다고 사회관념상 인정되면 그것을 영업의 양도라 볼 것이지만, 반면에 영업재산의 전부를 양도했어도 그 조직을 해체하여 양도했다면 영업의 양도로 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"영업양도"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-4","t":"영업양도는 일정한 영업목적에 의하여 조직화된 총체 즉, 물적⋅인적 조직을 그 동일성을 유지하면서 일체로서 이전하는 계약으로, 계약의 내용 및 효력을 명확히 하여야 할 필요가 있으므로, 당사자 사이에 명시적 계약이 아닌 묵시적 계약에 의하여 영업양도가 성립한다고 볼 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-5","t":"상법 제42조 제1항에는 영업양수인이 양도인의 상호를 계속 사용하는 경우에는 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다고 규정되어 있는바, 양수인이 변제할 책임이 있는 양도인의 영업으로 인한 제3자의 채권에는 불법행위로 인한 손해배상채권도 포함된다.","ox":"O","m":"⑤","c":"A","tp":"영업양도"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-1","t":"기부자가 상인이라고 하더라도 지방자치단체와 그 기부자 사이에 체결된 기부채납 약정을 보조적 상행위라 볼 수는 없으므로, 그러한 기부채납 약정에 근거한 채권에는 5년의 상사소멸시효가 적용되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-2","t":"면책적 채무인수로 인수한 채무가 원래 5년의 상사소멸시효의 적용을 받던 채무라면, 그 후 면책적 채무인수에 따라 그 채무자의 지위가 인수인으로 교체되었다고 하더라도, 그 소멸시효의 기간은 여전히 5년의 상사소멸시효의 적용을 받는다 할 것이고, 이는 채무인수행위가 상행위나 보조적 상행위에 해당하지 아니한다고 하여 달리 볼 것이 아니다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-3","t":"은행이 영업행위로서 한 대출금에 대한 변제기 이후의 지연손해금은 그 원본채권과 마찬가지로 상행위로 인한 채권으로서 5년의 상사소멸시효가 적용된다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-4","t":"사용자가 근로계약에 수반되는 신의칙상의 부수적 의무인 보호의무를 위반하여 근로자에게 손해를 입힘으로써 발생한 근로자의 손해배상청구권은 특별한 사정이 없는 한 10년의 민사소멸시효가 적용된다고 봄이 타당하다.","ox":"O","m":"④","c":"A","tp":"상사소멸시효"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-5","t":"당사자 일방이 상인인 경우에는 공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 의한 협의취득으로 체결된 부동산 매매계약이라고 하더라도 다른 사정이 없는 한 보조적 상행위에 해당하므로, 매도인의 채무불이행책임이나 하자담보책임에 기한 매수인의 손해배상채권에 대해서는 상사소멸시효가 적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-1","t":"상행위로 인한 채무의 법정이율은 연 6%이다.","ox":"O","m":"①","c":"A","tp":"상행위 특칙"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-2","t":"상사법정이율은 상행위가 아닌 불법행위로 인한 손해배상채무에는 적용되지 않는다.","ox":"O","m":"②","c":"A","tp":"상행위 특칙"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-3","t":"상행위로 인하여 생긴 채권을 담보하기 위하여 설정한 질권의 경우 유질계약이 허용된다.","ox":"O","m":"③","c":"A","tp":"상행위 특칙"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-4","t":"보험계약자가 다수의 계약을 통하여 보험금을 부정취득할 목적으로 보험계약을 체결하여 그것이 민법 제103조에 따라 선량한 풍속 기타 사회질서에 반하여 무효인 경우 보험자의 보험금에 대한 부당이득반환청구권은 10년의 민사소멸시효가 적용되고 상법 제64조를 유추적용할 수는 없다.","ox":"X","m":"④","c":"A","tp":"상행위 특칙"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-5","t":"회사가 배당 가능한 이익이 없음에도 이익의 배당을 한 경우 성립하는 위법배당에 따른 부당이득반환청구권은 10년의 민사소멸시효가 적용된다.","ox":"O","m":"⑤","c":"A","tp":"상행위 특칙"},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50-1","t":"운송주선업자가 운송의뢰인으로부터 운송관련 업무를 의뢰받았다고 하더라도 운송을 의뢰받은 것인지, 운송주선만을 의뢰받은 것인지 여부가 명확하지 않은 경우에는 당사자의 의사를 탐구하여 운송인의 지위를 취득하였는지 여부를 확정하여야 할 것이지만, 당사자의 의사가 명확하지 않은 경우에는 하우스 선하증권의 발행자 명의, 운임의 지급형태 등 제반 사정을 종합적으로 고려하여 논리와 경험칙에 따라 운송주선업자가 운송의뢰인으로부터 운송을 인수하였다고 볼 수 있는지 여부를 확정하여야 한다.","ox":"O","m":"①","c":"A","tp":"운송주선업, 운송업, 해상운송 등"},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50-2","t":"운송인이 운송계약상의 의무에 위배하여 수하인이 아닌 수입상에게 직접 화물을 인도하여 운송의뢰인의 수출대금에 대한 담보권을 침해한 경우 수입상에 대한 수출대금채권이 형식적으로 존재한다고 할지라도 수입상이 화물에 하자 있음을 트집잡아 대금을 지급하지 않고 있다면 담보권상실로 인하여 손해가 발생하였다고 할 것이다.","ox":"O","m":"②","c":"A","tp":"운송주선업, 운송업, 해상운송 등"},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50-3","t":"해상운송인 또는 선박대리점이 선하증권과 상환하지 아니하고 운송물을 선하증권 소지인 아닌 자에게 인도하는 것은 그로 인한 손해의 배상을 전제로 하는 것이어서, 그 결과 선하증권 소지인에게 운송물을 인도하지 못하게 되어 운송물에 대한 그의 권리를 침해하였을 때에는 고의 또는 중대한 과실에 의한 불법행위가 성립된다.","ox":"O","m":"③","c":"A","tp":"운송주선업, 운송업, 해상운송 등"},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50-4","t":"해상운송계약에서 운송인은 운송물의 수령·선적·적부·보관·운송·양륙 및 인도의무를 부담하므로, 운송인은 운송채무의 최종 단계에서 운송물을 정당한 수하인에게 인도함으로써 운송계약의 이행을 완료하게 된다. 따라서 운송인이 운송계약상 정해진 양륙항에 도착한 후 운송물을 선창에서 인도 장소까지 반출하여 보세창고업자에게 인도하였다면 특별한 사정이 없는 한 그 운송물이 운송인의 지배를 떠나 정당한 수하인에게 인도된 것으로 볼 수 있다.","ox":"X","m":"④","c":"A","tp":"운송주선업, 운송업, 해상운송 등"},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50-5","t":"상법 제136조는 화폐, 유가증권 기타의 고가물에 대하여는 송하인이 운송을 위탁할 때에 그 종류와 가액을 명시한 경우에 한하여 운송인이 손해를 배상할 책임이 있다고 정하고 있는바, 이러한 고가물 불고지로 인한 면책규정은 일반적으로 운송인의 운송계약상의 채무불이행으로 인한 청구에만 적용되고 불법행위로 인한 손해배상청구에는 그 적용이 없으므로, 운송인의 운송이행업무를 보조하는 자가 운송과 관련하여 고의 또는 과실로 송하인에게 손해를 가한 경우 불법행위로 인한 손해배상책임을 부담하게 되고, 위 면책규정은 적용될 여지가 없다.","ox":"O","m":"⑤","c":"A","tp":"운송주선업, 운송업, 해상운송 등"}],"18":[{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-1","t":"어음상의 주채무자가 원인관계상의 채무자와 동일하지 아니한 경우에도 특별한 사정이 없는 한 지급에 갈음하여 어음이 교부된 것으로 추정된다.","ox":"X","m":"①","c":"A","tp":"어음ㆍ수표관계와 원인관계"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-2","t":"원인채권의 지급을 확보하기 위한 방법으로 어음이 수수된 경우에 채권자는 그 선택에 따라 권리를 행사할 수 있고, 원인채권에 기하여 청구를 한 것만으로는 어음채권의 소멸시효를 중단시키지 못한다.","ox":"O","m":"②","c":"A","tp":"어음ㆍ수표관계와 원인관계"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-3","t":"기존채무의 지급을 위하여 수표를 교부받은 채권자가 그 수표와 분리하여 기존 원인채권만을 제3자에게 양도한 경우, 채무자는 기존 원인채권의 양수인에 대하여 해당 수표의 반환 없이는 기존 원인채무의 이행을 거절하겠다는 항변권을 행사할 수 없다.","ox":"X","m":"③","c":"A","tp":"어음ㆍ수표관계와 원인관계"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-4","t":"채권자가 원인채무의 변제기가 도래하여 그 이행을 최고한 경우 채무자가 어음의 반환과의 동시이행을 주장하지 않고 단순히 이행을 거절하더라도 이행지체가 되지 않는다.","ox":"X","m":"④","c":"A","tp":"어음ㆍ수표관계와 원인관계"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-5","t":"어음에 의하여 청구를 받은 자는 종전의 소지인에 대한 인적관계로 인한 항변으로써 소지인에게 대항하지 못하므로, 어음의 배서인이 발행인으로부터 지급받은 어음 중 일부를 어음소지인에게 지급한 경우라도 어음의 발행인은 소지인에게 대항하여 그 부분 어음금의 지급을 거절하지 못한다.","ox":"X","m":"⑤","c":"A","tp":"어음ㆍ수표관계와 원인관계"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-1","t":"확정일출급, 발행일자 후 정기출급 또는 일람 후 정기출급의 환어음 소지인은 지급을 할 날 또는 그날 이후의 2거래일 내에 지급을 받기 위한 제시를 하여야 한다.","ox":"O","m":"①","c":"A","tp":"어음, 수표의 지급제시"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-2","t":"약속어음의 소지인이 지급기일에 지급의 제시를 하지 아니하였다고 하여 그 약속어음의 효력이 상실되는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"어음, 수표의 지급제시"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-3","t":"백지미보충어음(단, 발행지백지어음 제외)은 그 지급제시기간 내에 지급을 위한 제시가 있다 하더라도 적법한 지급제시로서의 효력이 없다.","ox":"O","m":"③","c":"A","tp":"어음, 수표의 지급제시"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-4","t":"국내에서 발행하고 지급할 수표는 10일 내에 지급을 받기 위한 제시를 하여야 한다.","ox":"O","m":"④","c":"A","tp":"어음, 수표의 지급제시"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-5","t":"수표에 기재된 발행일이 도래하기 전에 지급제시를 받은 경우에는 기재된 발행일까지 지급을 거절할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"어음, 수표의 지급제시"},{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48-1","t":"배서의 효력에는 권리 이전적 효력, 담보적 효력, 자격 수여적 효력이 있다.","ox":"O","m":"①","c":"A","tp":"어음의 배서"},{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48-2","t":"어음의 점유자가 배서의 연속에 의하여 그 권리를 증명할 때에는 그를 적법한 소지인으로 추정한다.","ox":"O","m":"②","c":"A","tp":"어음의 배서"},{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48-3","t":"배서에 조건을 붙인 경우에는 그 조건이 없는 것으로 본다.","ox":"O","m":"③","c":"A","tp":"어음의 배서"},{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48-4","t":"배서인이 자기의 배서 이후에 새로 하는 배서를 금지한 경우에도 그 배서인은 그 후의 피배서인에 대하여 담보의 책임을 진다.","ox":"X","m":"④","c":"A","tp":"어음의 배서"},{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48-5","t":"지급거절증서가 작성된 후에 한 배서 또는 지급거절증서 작성기간이 지난 후에 한 배서는 지명채권 양도의 효력만 있다.","ox":"O","m":"⑤","c":"A","tp":"어음의 배서"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-1","t":"수표는 발행인 자신을 지급인으로 하여 발행할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-2","t":"수표의 금액을 글자와 숫자로 적은 경우에 그 금액에 차이가 있으면 글자로 적은 금액을 수표금액으로 한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-3","t":"발행일을 백지로 하여 발행된 수표의 백지보충권의 소멸시효기간은 백지보충권을 행사할 수 있는 때로부터 6개월로 봄이 상당하다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-4","t":"수표소지인이 수표의 발행일 도래 전에 지급제시를 하면 그 지급제시는 효력이 없다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-5","t":"지급보증인은 수표소지인이 지급제시기간 내에 수표를 지급제시한 경우에만 수표상의 채무를 부담한다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-1","t":"어음행위에 착오ㆍ사기ㆍ강박 등 의사표시의 하자가 있다는 항변은 어음행위 상대방에 대한 인적항변이다.","ox":"O","m":"①","c":"A","tp":"어음 항변"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-2","t":"융통어음의 발행자는 피융통자로부터 그 어음을 양수한 제3자가 선의라도 그 취득이 기한 후 배서에 의한 것인 경우에는 대가 없이 발행된 융통어음이라는 항변으로 대항할 수 있다.","ox":"X","m":"②","c":"A","tp":"어음 항변"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-3","t":"약속어음 발행인으로부터 인적항변의 대항을 받는 어음소지인은 당해 어음을 제3자에게 배서ㆍ양도한 후 환배서에 의하여 이를 다시 취득하여 소지하게 되었다고 할지라도 발행인으로부터 여전히 위 항변의 대항을 받는다.","ox":"O","m":"③","c":"A","tp":"어음 항변"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-4","t":"어음에 어음채무자로 기재되어 있는 사람이 자신의 기명날인이 위조된 것이라고 주장하는 경우에는 그 사람에 대하여 어음채무의 이행을 청구하는 어음의 소지인이 그 기명날인이 진정한 것임을 증명하여야 한다.","ox":"O","m":"④","c":"A","tp":"어음 항변"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-5","t":"어음의 배서인이 발행인으로부터 지급받은 어음금 중 일부를 어음 소지인에게 지급한 경우 어음의 발행인은 그 범위 내에서 배서인에 대한 인적항변으로써 소지인에게 대항하여 그 부분 어음금 지급을 거절할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"어음 항변"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-1","t":"백지약속어음의 경우 발행인이 수취인 또는 그 소지인으로 하여금 백지부분을 보충케 하려는 보충권을 줄 의사로서 발행하였는지의 여부에 관하여는 발행인에게 보충권을 줄 의사로 발행한 것이 아니라는 점, 즉 백지어음이 아니고 불완전어음으로서 무효라는 점에 관한 입증책임이 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-2","t":"지급을 받을 자 부분이 백지로 된 약속어음의 소지인은 그 백지 부분을 보충하지 않은 상태에서는 어음상의 청구권을 행사할 수 없으므로, 그 백지어음 소지인의 권리행사에 의한 소멸시효 중단의 효과는 생길 여지가 없다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-3","t":"수취인이 백지인 채로 발행된 어음은 인도에 의하여 어음법적으로 유효하게 양도될 수 있다.","ox":"O","m":"③","c":"A","tp":"백지어음"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-4","t":"백지어음의 보충은 보충권이 시효로 소멸하기까지는 지급기일 후에도 이를 행사할 수 있고, 주된 채무자인 발행인에 대하여 어음금청구소송을 제기한 경우에는 변론종결시까지만 보충권을 행사하면 된다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-5","t":"만기를 백지로 한 약속어음을 발행한 경우, 그 보충권의 소멸시효는 다른 특별한 사정이 없는 한 그 어음발행의 원인관계에 비추어 어음상의 권리를 행사하는 것이 법률적으로 가능하게 된 때부터 진행한다.","ox":"O","m":"⑤","c":"A","tp":"백지어음"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-1","t":"어음행위의 대리 또는 대행권한을 수여받은 자가 그 수권의 범위를 넘어 어음행위를 한 경우 본인은 수권의 범위를 불문하고 아무런 어음상의 채무를 부담하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-2","t":"약속어음의 보증 부분이 위조된 경우 해당 약속어음을 배서, 양도받은 제3취득자는 위 보증행위가 민법 제126조가 정한 표현(表見)대리행위로서 보증인에게 그 효력이 미친다고 주장할 수 있는 제3자에 해당한다.","ox":"X","m":"②","c":"A","tp":"어음행위의 대리"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-3","t":"민법상 표현대리에 관한 규정이 어음행위의 위조에 관하여 유추적용되기 위하여서는 상대방이 위조자에게 어음행위를 할 권한이 있다고 믿거나 피위조자가 진정하게 당해 어음행위를 한 것으로 믿은 것만으로 충분하다.","ox":"X","m":"③","c":"A","tp":"어음행위의 대리"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-4","t":"어음이 위조된 경우 피위조자는 민법상 표현(表見)대리에 관한 규정이 유추적용될 수 있다는 등의 특별한 경우를 제외하고는 원칙적으로 어음상의 책임을 지지 않는다.","ox":"O","m":"④","c":"A","tp":"어음행위의 대리"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-5","t":"대리권 없이 타인의 대리인으로 환어음에 기명날인하거나 서명한 자는 그 어음상의 책임을 부담하지 않는다.","ox":"X","m":"⑤","c":"A","tp":"어음행위의 대리"},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23-1","t":"회생절차에 참가하기 위하여 어음채권을 회생채권으로 신고하는 경우에도 어음을 소지하지 않으면 그 어음상의 권리를 행사할 수 없다.","ox":"O","m":"①","c":"A","tp":"어음상 권리의 행사"},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23-2","t":"환어음 인수인, 약속어음 발행인과 같은 주채무자에 대한 지급제시기간은 만기일로부터 3년이다.","ox":"O","m":"②","c":"A","tp":"어음상 권리의 행사"},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23-3","t":"기한은 채무자의 이익을 위한 것으로 추정되므로, 어음채무자는 원칙적으로 만기 전에도 어음금을 지급할 수 있고, 어음소지인은 만기 전이라도 어음금을 지급 받을 의무가 있다.","ox":"X","m":"③","c":"A","tp":"어음상 권리의 행사"},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23-4","t":"만기에 지급이 되지 아니한 경우 환어음소지인은 배서인, 발행인, 그 밖의 어음채무자에 대하여 상환청구권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"어음상 권리의 행사"},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23-5","t":"어음행위는 무인행위로서 어음수수의 원인관계로부터 분리하여 다루어져야 하고 어음은 원인관계와 상관없이 일정한 어음상의 권리를 표창하는 증권이므로 어음이 일정한 조건하에서만 권리를 행사하기로 한 약정 하에 발행되었더라도 이와 같은 사정은 어음의 원인관계에 기한 인적 항변사유에 불과하고 어음상의 권리는 일단 유효하게 성립한다.","ox":"O","m":"⑤","c":"A","tp":"어음상 권리의 행사"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-1","t":"무인 또는 지장을 찍는 것은 유효한 날인이 될 수 없다.","ox":"O","m":"①","c":"A","tp":"어음·수표행위의 성립요건"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-2","t":"어음·수표행위자의 진정한 의사에 기하여 기명날인이 이루어진 이상 기명과 날인이 서로 일치하지 않더라도 유효한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"어음·수표행위의 성립요건"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-3","t":"약속어음의 발행인 명의가 회사 대표이사인 개인으로만 되어 있고 별다른 뜻이 표시되어 있지 아니한 경우 날인된 인영에 법인의 명칭이 나타나 있더라도 이를 가지고 법인의 명칭이 기재되었다고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"어음·수표행위의 성립요건"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-4","t":"‘A 주식회사 甲’이라고 기명하고, 그 옆에 ‘A 주식회사 대표이사’ 라고 날인하여 그 인영에 대표이사라는 사실이 드러나더라도 법인의 어음·수표행위로는 볼 수 없다.","ox":"X","m":"④","c":"A","tp":"어음·수표행위의 성립요건"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-5","t":"대표기관의 기명날인이 없이 법인의 명칭만을 기재하고 대표기관의 날인만 있는 경우에는 무효이다.","ox":"O","m":"⑤","c":"A","tp":"어음·수표행위의 성립요건"},{"y":2018,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2018_24-50","t":"어음에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"어음에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["어음의 요식증권 내지 문언증권으로서의 성질상 어음요건의 성립 여부는 어음상의 기재만에 의하여 판단하여야 하고, 어음요건의 기재가 그 자체로 불가능한 것이거나 각 어음요건이 서로 명백히 모순되어 함께 존립할 수 없게 되는 경우에는 그와 같은 어음은 무효라고 봄이 상당하다.","확정된 날을 만기로 하는 확정일출급 약속어음의 경우에 있어서 만기의 일자가 발행일보다 앞선 일자로 기재되어 있다면 그 약속어음은 어음요건의 기재가 서로 모순되는 것으로서 무효이다.","발행인이 어음에 ‘지시 금지’의 문자를 기재한 경우, 그 어음은 지명채권의 양도방식으로만, 그리고 그 효력으로써만 양도할 수 있다.","어음면의 기재 자체로 보아 국내어음으로 인정되는 경우에 있어서는 그 어음면상 발행지의 기재가 없는 경우라고 할지라도 이를 무효의 어음으로 볼 수는 없다.","일람 후 정기출급 환어음의 발행인은 어음금액에 이자가 붙는다는 약정내용을 기재할 수 있고, 이율을 특정하여 기재한 경우 그에 따른 이자지급을 약정한 것으로, 이율을 특정하여 기재하지 않은 경우 상사이율인 연 6%의 이자를 지급하기로 약정한 것으로 본다. 23-11"],"a":5}},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-1","t":"원고가 배서가 연속된이 사건 약속어음을 지급거절증서 작성기간이 지난 후에 백지식 배서의 방식으로 교부받았더라도 원고는 여전히 이 사건 약속어음의 적법한 소지인으로 추정된다.","ox":"O","m":"①","c":"A","tp":"어음행위 및 어음상 권리의 행사"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-2","t":"어음은 제시증권, 상환증권이므로 어음을 소지하지 않으면 어음상의 권리를 행사할 수 없는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"어음행위 및 어음상 권리의 행사"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-3","t":"어음이 어떤 이유로 이미 채무자의 점유에 귀속하는 경우에도, 어음의 소지는 채무자에 대한 권리행사의 요건이므로, 채무자는 상환이행의 항변을 할 수 있다.","ox":"X","m":"③","c":"A","tp":"어음행위 및 어음상 권리의 행사"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-4","t":"어음행위의 내용은 어디까지나 어음상의 기재에 의하여 객관적으로 해석하여야 하는 것이지, 어음 외의 사정에 의하여 어음상의 기재를 변경하는 방식으로 해석하여서는 아니된다.","ox":"O","m":"④","c":"A","tp":"어음행위 및 어음상 권리의 행사"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-5","t":"어음을 유통시킬 의사로 어음상에 발행인으로 기명날인하여 외관을 갖춘 어음을 작성한 자는 그 어음이 도난·분실 등으로 인하여 그의 의사에 의하지 아니하고 유통되었다고 하더라도, 배서가 연속되어 있는 그 어음의 외관을 신뢰하고 취득한 소지인에 대하여는 그 소지인이 악의 내지 중과실에 의하여 그 어음을 취득하였음을 주장·입증하지 아니하는 한 발행인으로서의 어음상의 채무를 부담한다.","ox":"O","m":"⑤","c":"A","tp":"어음행위 및 어음상 권리의 행사"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-1","t":"환어음 또는 약속어음에서 생긴 권리가 절차의 흠결로 인하여 소멸한 때나 그 소멸시효가 완성한 때라도 소지인은 발행인, 인수인 또는 배서인에 대하여 그가 받은 이익의 한도내에서 상환을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"어음법 및 수표법상 이득상환청구권"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-2","t":"어음법에 의한 이득상환청구권이 발생하기 위하여는 모든 어음상 또는 민법상의 채무자에 대하여 각 권리가 소멸되어야 하는 것인바, 원인관계에 있는 채권의 지급을 확보하기 위하여 발행된 약속어음이 전전양도되어 최후의 소지인이 어음상의 권리를 상실한 경우라도 원인채무는 그대로 존속하는 것이므로 발행인이 바로 어음금액 상당의 이득을 얻고 있다고는 할 수 없다.","ox":"O","m":"②","c":"A","tp":"어음법 및 수표법상 이득상환청구권"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-3","t":"이득상환청구권은 어음의 효력소멸 당시의 소지인에게 부여된 지명채권에 속하므로 지명채권 양도의 방법에 의하여 양도할 수 있다.","ox":"O","m":"③","c":"A","tp":"어음법 및 수표법상 이득상환청구권"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-4","t":"어음법 제79조에서 말하는 ‘받은 이익’이라는 것은 어음채무자가 어음상의 권리의 소멸에 의하여 어음상의 채무를 면하는 것 자체를 말하는 것이 아니라 어음수수의 원인관계 등 실질관계(기본관계)에 있어서 현실로 받은 재산상의 이익을 말하는 것이다.","ox":"O","m":"④","c":"A","tp":"어음법 및 수표법상 이득상환청구권"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-5","t":"자기앞수표의 지급제시기간이 경과된 후에는 수표상의 권리가 아니라 이득상환청구권이 양도되는 것이고, 수표소지인은 이득상환청구권의 선의취득자로 보호받게 된다.","ox":"X","m":"⑤","c":"A","tp":"어음법 및 수표법상 이득상환청구권"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-1","t":"위조된 수표를 할인에 의하여 취득한 사람이 그로 인하여 입게 되는 손해액은 특별한 사정이 없는 한 그 수표가 진정한 것이었다면 그 소지인이 지급받았을 것으로 인정되는 그 수표의 액면에 상당하는 금액이지, 그 위조수표를 취득하기 위하여 현실적으로 출연한 할인금에 상당하는 금액이 아니라고 봄이 상당하다.","ox":"X","m":"①","c":"A","tp":"어음의 위ㆍ변조"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-2","t":"어음발행인이라 하더라도 어음상에 권리의무를 가진 자가 있는 경우에는 이러한 자의 동의를 받지 아니하고 어음의 기재내용에 변경을 가하였다면 이는 변조에 해당한다. 약속어음에 배서인이 있는 경우 배서인은 어음행위를 할 당시의 문언에 따라 어음상의 책임을 지는 것이지 그 변조된 문언에 의한 책임을 지울 수는 없다.","ox":"O","m":"②","c":"A","tp":"어음의 위ㆍ변조"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-3","t":"약속어음의 배서가 위조된 경우에도 배서의 연속이 흠결된 것이라고 할 수 없으므로 피배서인은 배서가 위조되었는지의 여부에 관계없이 배서의 연속이 있는 약속어음의 적법한 소지인으로 추정되며 다만 발행인은 소지인이 악의 또는 중대한 과실로 취득한 사실을 주장 입증하여 발행인으로서의 어음채무를 면할 수 있을 뿐이다.","ox":"O","m":"③","c":"A","tp":"어음의 위ㆍ변조"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-4","t":"어음이 위조된 경우 피위조자는 민법상 표현대리에 관한 규정이 유추적용될 수 있다는 등의 특별한 경우를 제외하고는 원칙적으로 어음상의 책임을 지지 아니한다.","ox":"O","m":"④","c":"A","tp":"어음의 위ㆍ변조"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-5","t":"피위조자의 추인은 묵시적으로도 가능하나 피위조자가 묵시적으로 추인하였다고 인정하려면 추인의 의사가 표시되었다고 볼 만한 사유가 인정되어야 한다.","ox":"O","m":"⑤","c":"A","tp":"어음의 위ㆍ변조"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-1","t":"만기가 기재된 백지어음의 경우 어음의 주채무자에 대한 권리는 만기로부터 3년의 소멸시효에 걸리므로, 백지의 보충도 이 기간 내에 이루어져야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-2","t":"어음법 제75조 소정의 법정기재사항인 약속어음 발행일란의 보충 없이 지급제시한 경우는 적법한 지급제시가 되지 못하여 소구권을 상실한다.","ox":"O","m":"②","c":"A","tp":"백지어음"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-3","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음의 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구하는 경우, 이로써 어음상의 청구권에 관한 소멸시효는 중단된다. 다만 이 경우 백지에 대한 보충권은 어음상의 청구권과는 별개로 독립하여 시효로 소멸하게 된다.","ox":"X","m":"③","c":"A","tp":"백지어음"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-4","t":"수취인이 백지인 채로 발행된 어음은 인도에 의하여 어음법적으로 유효하게 양도될 수 있다.","ox":"O","m":"④","c":"A","tp":"백지어음"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-5","t":"지급기일을 공란으로 하여 약속어음을 발행한 경우에는 특별한 사정이 없는 한 그 어음은 일람출급의 어음으로 볼 것이 아니라 백지어음으로 보아야 한다. 이러한 백지어음을 교부하여 보관시킨 때에는 후일 그 소지인으로 하여금 임의로 그 지급기일의 기재를 보충시킬 의사로 교부, 보관시킨 것이라고 추정된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-1","t":"배서인은 자기의 배서 이후에 새로 하는 배서를 금지할 수 있다. 이 경우 배서인은 어음의 그 후의 피배서인에 대하여 담보의 책임을 지지 아니한다.","ox":"O","m":"①","c":"A","tp":"어음의 배서"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-2","t":"배서는 환어음으로부터 생기는 모든 권리를 이전한다. 일부의 배서는 무효로 한다.","ox":"O","m":"②","c":"A","tp":"어음의 배서"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-3","t":"어음에 있어서 배서의 연속은 형식상 존재함으로써 족하고 또 형식상 존재함을 요한다 할 것이나, 형식상 배서의 연속이 끊어진 경우에 다른 방법으로 그 중단된 부분에 관하여 실질적 관계가 있음을 증명한 소지인이 한 어음상의 권리행사는 적법하다.","ox":"O","m":"③","c":"A","tp":"어음의 배서"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-4","t":"환어음의 점유자가 배서의 연속에 의하여 그 권리를 증명할 때에는 그를 적법한 소지인으로 추정한다. 최후의 배서가 백지식인 경우에도 같다.","ox":"O","m":"④","c":"A","tp":"어음의 배서"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-5","t":"지급거절증서가 작성된 후에 한 배서 또는 지급거절증서 작성기간이 지난 후에 한 배서는 지명채권 양도의 효력만 있다. 따라서 이와 같은 배서가 있는 경우 어음 소지자가 어음상의 권리행사를 하기 위해서는 민법상 지명채권의 양도·양수절차인 채권양도인의 통지 또는 채무자의 승낙을 필요로 한다.","ox":"X","m":"⑤","c":"A","tp":"어음의 배서"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-1","t":"채무자가 기존 채무의 이행에 관하여 채권자에게 어음을 교부하는 경우에 어음상의 주채무자가 원인관계상의 채무자와 동일하지 아니한 때에는 제3자인 어음상의 주채무자에 의한 지급이 예정되어 있으므로 이는 ‘지급을 위하여’ 교부된 것으로 추정되지만, ‘지급에 갈음하여’ 교부된 것으로 볼 만한 특별한 사정이 있는 경우에는 그러한 추정은 깨진다.","ox":"O","m":"①","c":"A","tp":"어음관계와 원인관계"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-2","t":"원인채권의 지급을 확보하기 위한 방법으로 어음이 수수된 경우, 채권자가 어음채권에 기하여 청구를 하더라도 원인채권의 소멸시효를 중단시키는 효력은 없다.","ox":"X","m":"②","c":"A","tp":"어음관계와 원인관계"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-3","t":"다른 사람이 발행 또는 배서양도하는 약속어음에 배서인이 된 사람은 그 배서로 인한 어음상의 채무만을 부담하는 것이 원칙이고, 특별히 채권자에 대하여 자기가 그 발행 또는 배서양도의 원인이 된 채무까지 보증하겠다는 뜻으로 배서한 경우에 한하여 그 원인채무에 대한 보증책임을 부담한다.","ox":"O","m":"③","c":"A","tp":"어음관계와 원인관계"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-4","t":"어음에 의하여 청구를 받은 자는 종전의 소지인에 대한 인적 관계로 인한 항변으로써 소지인에게 대항하지 못하는 것이 원칙이지만, 자기에 대한 배서의 원인관계가 흠결됨으로써 어음소지인이 그 어음을 소지할 정당한 권원이 없어지고 어음금의 지급을 구할 경제적 이익이 없게 된 경우에는 인적항변 절단의 이익을 향유할 지위에 있지 않다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"어음관계와 원인관계"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-5","t":"채무자가 채권자에게 기존 채무의 이행에 관하여 교부한 어음이 '지급을 위하여' 교부된 것으로 추정되는 경우, 채권자가 기존 채무의 변제기보다 후의 일자가 만기로 된 어음을 교부받은 때에는 특별한 사정이 없는 한 기존채무의 지급을 유예하는 의사가 있었다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"어음관계와 원인관계"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-1","t":"어음상에 대리인 자신을 위한 어음행위가 아니고 본인을 위하여 어음행위를 한다는 취지를 인식할 수 있을 정도의 표시가 있으면 대리관계의 표시로 보아야 할 것이어서, “甲주식회사 이사 乙”이라는 표시는 甲주식회사의 대리관계의 표시로써 적법한 표시이다.","ox":"O","m":"①","c":"A","tp":"어음행위의 대리"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-2","t":"조합의 어음행위는 조합의 성질상 조합원 전원이 기명날인 또는 서명을 하여야 하고, 대표조합원이 그 대표자격을 밝히고 조합원 전원을 대리하여 서명한 경우라도 조합원 전원에 대한 유효한 어음행위가 될 수 없다.","ox":"X","m":"②","c":"A","tp":"어음행위의 대리"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-3","t":"약속어음의 보증 부분이 위조된 경우, 해당 약속어음을 배서, 양도받는 제3취득자는 위 보증행위가 민법 제126조 소정의 표현대리행위로서 보증인에게 그 효력이 미친다고 주장할 수 있는 제3자에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"어음행위의 대리"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-4","t":"어음위조의 경우에도 제3자가 어음행위를 실제로 한 자에게 그와 같은 어음행위를 할 수 있는 권한이 있다고 믿을 만한 사유가 있고, 본인에게 책임을 질 만한 사유가 있는 때에는 대리방식에 의한 어음행위의 경우와 마찬가지로 민법상의 표현대리 규정을 유추적용하여 본인에게 그 책임을 물을 수 있다.","ox":"O","m":"④","c":"A","tp":"어음행위의 대리"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-5","t":"어음행위의 대리 또는 대행권한을 수여받은 자가 그 수권의 범위를 넘어 어음행위를 한 경우에 본인은 그 수권의 범위 내에서는 대리 또는 대행자와 함께 어음상의 채무를 부담한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-1","t":"약속어음의 보증을 하면서 누구를 위하여 보증한 것임을 표시하지 아니하였으면 약속어음의 발행인을 위하여 보증한 것으로 본다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-2","t":"보증인이 환어음의 지급을 하면 보증된 자와 그 자의 어음상의 채무자에 대하여 어음으로부터 생기는 권리를 취득한다.","ox":"O","m":"②","c":"A","tp":"어음의 보증"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-3","t":"민법상 보증인에게 인정되는 최고·검색의 항변권은 어음보증인에게도 인정된다.","ox":"X","m":"③","c":"A","tp":"어음의 보증"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-4","t":"어음보증을 조건부로 하더라도 그 효력이 인정된다.","ox":"O","m":"④","c":"A","tp":"어음의 보증"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-5","t":"어음금액의 일부만을 보증하는 일부보증도 가능하다.","ox":"O","m":"⑤","c":"A","tp":"어음의 보증"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-1","t":"소지인이 어음 채무자를 해할 것임을 중대한 과실로 알지 못하였다면 어음 채무자는 종전 소지인에 대한 인적항변으로써 소지인에게 대항할 수 있다.","ox":"X","m":"①","c":"A","tp":"어음의 항변"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-2","t":"융통어음을 발행한 자는 그 어음을 양수한 제3자에 대하여는 특별한 사정이 없는 한 선의, 악의를 묻지 아니하고 대가 없이 발행한 융통어음이었다는 항변으로 대항할 수 없다.","ox":"O","m":"②","c":"A","tp":"어음의 항변"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-3","t":"융통어음을 양수한 제3자가 양수 당시 그 어음이 융통어음으로 발행되었고 이와 교환으로 교부된 담보어음이 지급거절되었다는 사정을 알고 있었다면, 융통어음의 발행자는 그 제3자에 대하여도 융통어음의 항변으로 대항할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-4","t":"현재의 어음소지인에게 어음을 양도한 사람이 어음취득 당시 선의였기 때문에 그에게 대항할 수 없었던 사유에 대하여는 현재의 어음소지인이 비록 어음취득 당시 그 사유를 알고 있었다고 해도 현재의 어음소지인에게 대항할 수 없다.","ox":"O","m":"④","c":"A","tp":"어음의 항변"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-5","t":"약속어음 발행인으로부터 인적항변의 대항을 받는 어음소지인은 당해 어음을 제3자에게 배서·양도한 후 환배서에 의하여 이를 다시 취득하여 소지하게 되었다고 할지라도 발행인으로부터 여전히 위 항변의 대항을 받는다.","ox":"O","m":"⑤","c":"A","tp":"어음의 항변"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38","t":"다음 중 어음 또는 수표가 무효로 되는 경우를 모두 고른 것은?","c":"A","mc":{"s":"다음 중 어음 또는 수표가 무효로 되는 경우를 모두 고른 것은?","d":"가.약속어음의 발행인이 어음면에 지급에 관한 조건을 기재한 경우\n나.수표의 발행인이 수표에 이자의 약정을 기재한 경우\n다.환어음의 발행인이 인수를 담보하지 않는다는 문구를 기재한 경우\n라.약속어음의 발행인이 발행일 이전의 날짜를 만기로 기재한 경우\n마.환어음의 발행인이 지급을 담보하지 않는다는 문구를 기재한 경우","o":["가, 나","가, 라","나, 다","나, 라","다, 마"],"a":2}},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-1","t":"환어음은 조건 없이 일정한 금액을 지급할 것을 위탁하는 뜻을 적고, 약속어음은 조건 없이 일정한 금액을 지급할 것을 약속하는 뜻을 적는다.","ox":"O","m":"①","c":"A","tp":"어음법 및 수표법상 환어음, 약속어음, 수표의 비교"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-2","t":"약속어음은 지급인이 없고 따라서 지급지도 기재하지 않는다.","ox":"X","m":"②","c":"A","tp":"어음법 및 수표법상 환어음, 약속어음, 수표의 비교"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-3","t":"수표에는 만기와 수취인을 기재할 필요가 없다.","ox":"O","m":"③","c":"A","tp":"어음법 및 수표법상 환어음, 약속어음, 수표의 비교"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-4","t":"수표는 발행인이 처분할 수 있는 자금이 있는 은행을 지급인으로 한다. 그러나 이를 위반하는 경우에도 수표로서의 효력에 영향을 미치지 않는다.","ox":"O","m":"④","c":"A","tp":"어음법 및 수표법상 환어음, 약속어음, 수표의 비교"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-5","t":"환어음과 달리 수표는 인수하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"어음법 및 수표법상 환어음, 약속어음, 수표의 비교"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-1","t":"어음채무자는 어음채권을 지명채권양도의 방법으로 양수한 자에게 양도인에 대한 인적 항변으로 대항할 수 있고, 따라서 지명채권양도의 방법으로 양수한 어음채권의 행사는 어음채무자와 양도인 사이의 원인관계의 효력에 따라 제한될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-2","t":"발행인과 수취인이 통모하여 진정한 어음채무 부담이나 어음채권 취득에 관한 의사 없이 단지 발행인의 채권자에게서 채권 추심이나 강제집행을 받는 것을 회피하기 위하여 형식적으로만 약속어음의 발행을 가장한 경우 이러한 어음발행행위는 통정허위표시로서 무효이고, 어음발행행위 등 어떠한 의사표시가 통정허위표시로서 무효라고 주장하는 자에게 그 사유에 해당하는 사실을 증명할 책임이 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-3","t":"특정인의 채무를 담보하기 위하여 약속어음을 발행하거나 그 어음에 배서한 경우에는 어음의 발행이나 배서인과 채권자 사이에 민사상 보증계약이 성립하였다고 추정되므로, 약속어음의 발행인 또는 배서인은 어음금의 지급 또는 상환책임 등 어음상 채무뿐만 아니라 약속어음의 발행 또는 배서의 원인이 되는 채무에 대한 민사상 보증책임도 부담한다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-4","t":"매수인이 매도인으로부터 물품을 공급받은 다음 그들 사이의 물품대금 지급방법에 관한 약정에 따라 대금의 지급을 위하여 물품 매도인에게 지급기일이 물품공급일자 이후로 된 약속어음을 발행·교부한 경우, 물품대금 지급채무의 이행기는 다른 특별한 사정이 없는 한 약속어음의 지급기일이고, 위 약속어음이 발행인에게 발생한 지급정지사유로 지급기일이 도래하기 전에 지급거절 되었더라도 지급거절된 때에 물품대금 지급채무의 이행기가 도래하는 것은 아니다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-5","t":"표지어음은 약속어음임을 표시하는 문구를 비롯하여 만기, 발행일, 발행인의 기명날인 등을 비롯한 어음법 제75조 소정의 주요한 어음요건을 갖추고 있고, 하단에는 표지어음이 어음에 해당함을 다시 확인하여 주는 문구, 즉 “발행지, 발행일, 수취인 등이 누락된 상태에서 지급제시하는 경우 지급거절로 선의의 피해를 입을 수 있으니 누락됨이 없도록 주의하시기 바랍니다.”라고 찍혀 있는 것이 보통이며, 그 기재가 계약서가 아닌 약속어음 표면에 존재하는 이상 이를 예문에 해당하는 것으로 볼 수 없다는 점에서 그 법적 성격은 어음법 소정의 약속어음에 해당한다. 따라서 수취인란이 기재되지 아니한 미완성의 표지어음을 가지고 한 지급제시만으로는 발행인을 이행지체에 빠뜨릴 수 없고 그 지연손해금은 이를 보충한 후 지급제시를 한 다음 날부터 기산한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-1","t":"자기앞수표의 정당한 소지인이 수표법상의 보전절차를 취하지 않고 지급제시기간을 경과하여 수표상의 권리가 소멸됨으로써 수표법 제63조에 따라 취득하게 되는 이득상환청구권은 지명채권에 해당한다.","ox":"O","m":"①","c":"A","tp":"어음 및 수표"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-2","t":"자기앞수표의 이득상환청구권의 경우 양도통지 또는 채무자의 승낙이 확정일자 있는 증서에 의하여 이루어지지 않더라도 채무자인 자기앞수표 발행 은행은 이득상환청구권의 양도, 그에 기한 채무의 변제라는 사정을 들어 양도인의 위 채권에 대한 압류채권자 등 양수인의 지위와 양립할 수 없는 법률상 지위를 취득한 사람에게 대항할 수 있다.","ox":"X","m":"②","c":"A","tp":"어음 및 수표"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-3","t":"지급제시기간이 경과한 자기앞수표는 이득상환청구권이 화체된 유가증권이 아니라 그 소지자가 이득상환청구권을 취득 또는 양수하였다는 점을 유력하게 뒷받침하는 증거증권으로서의 의미를 갖는다. 그러므로 자기앞수표를 소지하지 않은 상태에서 자기앞수표의 이득상환청구권을 행사하고자 하는 사람은 다른 증거에 의하여 자신이 이득상환청구권자임을 증명하여 이득상환청구권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"어음 및 수표"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-4","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구한 경우 어음상의 청구권에 관한 소멸시효가 중단되는 효과가 있다.","ox":"O","m":"④","c":"A","tp":"어음 및 수표"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-5","t":"만기를 백지로 하여 발행된 약속어음의 백지보충권의 소멸시효기간은 백지보충권을 행사할 수 있는 때로부터 3년으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"어음 및 수표"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35-1","t":"약속어음의 소지인이 그 어음이 지급기일에 지급거절되자 자기의 전자에게 피배서인이 백지인 배서가 되어 있는 상태로 교부하여 전자가 그 어음발행인을 상대로 어음금청구의 소를 제기하였으나 인적항변의 대항을 받아 패소하자 다시 그 어음을 교부받아 그 어음발행인을 상대로 어음금청구의 소를 제기한 경우, 그 어음발행인은 전자에 대한 인적항변으로 그 어음소지인에게 대항할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35-2","t":"어음면의 기재 자체로 보아 국내어음으로 인정되는 경우에 있어서는 그 어음면상 발행지의 기재가 없는 경우라고 할지라도 이를 무효의 어음으로 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35-3","t":"어음발행인이 지급기일에 피사취신고 등 사고신고를 하면서 어음액면금 상당의 사고신고담보금을 지급은행에 예치하였다 하더라도, 어음소지인에 대한 변제공탁으로서 효력을 갖는다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35-4","t":"어음발행인에 대한 법인회생절차에서 어음소지인의 어음상의 권리가 회생계획의 규정에 따라 변경되었다고 하더라도 어음소지인이 지급은행에 대하여 갖는 사고신고담보금에 대한 권리에는 아무런 영향이 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35-5","t":"어음발행인과 지급은행 사이에 체결된 사고신고담보금의 처리를 위한 약정서상에 지급은행이 어음발행인에게 담보금을 지급하는 경우의 하나로 ‘당해 어음과 관련하여 이해관계인이 소송계속중임을 입증하는 서면을 지급은행에 제출한 바가 없고 지급제시일로부터 6개월이 경과한 경우’를 정하고 있고, 제3자가 배서인을 채무자, 지급은행을 제3채무자로 하여 사고신고담보금에 대하여 채권압류 및 전부명령을 받은 경우, 제3자가 받은 위 압류 및 전부명령의 송달만으로는 사고신고담보금의 처리를 위한 약정서상의 소송계속중임을 증명하는 서면이 제출된 것으로 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-1","t":"어음법 제10조가 규정하는 ‘악의로 어음을 취득한 때’라 함은 소지인이 백지어음이 부당 보충되었다는 사실과 이를 취득할 경우 어음채무자를 해하게 된다는 것을 알면서도 어음을 양수한 때를 말하고, ‘중대한 과실로 인하여 어음을 취득한 때’라 함은 소지인이 조금만 주의를 기울였더라면 백지어음이 부당 보충되었다는 사실을 알 수 있었음에도 불구하고 그와 같은 주의도 기울이지 아니하고 부당 보충된 어음을 양수한 때를 말한다. 소지인이 악의 또는 중과실로 부당 보충된 어음을 취득한 경우 발행인은 이에 대한 어음상의 책임을 당연히 지지 않게 된다.","ox":"X","m":"①","c":"A","tp":"어음과 수표의 백지보충"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-2","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음의 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구하는 것은 어음상의 청구권에 관하여 잠자는 자가 아님을 객관적으로 표명한 것이고 그 청구로써 어음상의 청구권에 관한 소멸시효는 중단된다.","ox":"O","m":"②","c":"A","tp":"어음과 수표의 백지보충"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-3","t":"백지수표의 보충권 행사에 의하여 생기는 채권은 수표금 채권이고, 수표법 제51조에 의하면 수표의 발행인에 대한 상환청구권은 제시기간 경과 후 6개월간 행사하지 아니하면 소멸시효가 완성되는 점 등을 고려하면 발행일을 백지로 하여 발행된 수표의 백지보충권의 소멸시효기간은 백지보충권을 행사할 수 있는 때로부터 6개월로 봄이 상당하다.","ox":"O","m":"③","c":"A","tp":"어음과 수표의 백지보충"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-4","t":"어음금액이 백지인 어음을 취득하면서 보충권한을 부여받은 자의 지시에 의하여 어음금액란을 보충하는 경우 보충권의 내용에 관하여 어음의 기명날인자(발행인)에게 직접 조회하지 않았다면 특별한 사정이 없는 한 취득자에게 중대한 과실이 있다.","ox":"O","m":"④","c":"A","tp":"어음과 수표의 백지보충"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-5","t":"약속어음의 금액란이 부당보충된 경우에는 어음법상의 어음의 위조에 해당되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"어음과 수표의 백지보충"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-1","t":"어음을 선의취득하기 위해서는 어음의 점유자가 배서의 연속에 의하여 그 권리를 증명하여야 한다.","ox":"O","m":"①","c":"A","tp":"어음의 권리 취득, 행사, 소멸 등"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-2","t":"어음을 선의취득하기 위해서는 취득자에게 악의 또는 중대한 과실이 없어야 하는데, 통상적인 거래기준으로 판단하여 볼 때 양도인이나 그 어음 자체에 의하여 양도인의 실질적 무권리성을 의심하게 할 만한 사정이 있는데도 불구하고 이에 대하여 상당하다고 인정될 만한 조사를 하지 않고 만연히 양수한 경우에는 중대한 과실이 있다고 하여야 한다.","ox":"O","m":"②","c":"A","tp":"어음의 권리 취득, 행사, 소멸 등"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-3","t":"어음채권을 자동채권으로 하여 상계의 의사표시를 하는 경우에 있어 재판 외의 상계와 재판상 상계를 불문하고, 어음채무자의 승낙이 없는 이상 어음의 교부가 필요불가결하고 어음의 교부가 없으면 상계의 효력이 생기지 아니한다.","ox":"X","m":"③","c":"A","tp":"어음의 권리 취득, 행사, 소멸 등"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-4","t":"발행인에 대한 약속어음상의 청구권의 소멸시효는 만기의 날로부터 진행하는 것이 원칙이나, 그 약속어음이 수취인 겸 소지인의 발행인에 대한 장래 발생할 구상채권을 담보하기 위하여 발행된 것이라면, 약속어음상의 청구권의 소멸시효는 위 구상채권이 현실적으로 발생하여 그 약속어음상의 청구권을 행사하는 것이 법률적으로 가능하게 된 때부터 진행된다.","ox":"O","m":"④","c":"A","tp":"어음의 권리 취득, 행사, 소멸 등"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-5","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음의 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구하더라도, 그 청구로써 어음상의 청구권에 관한 소멸시효는 중단된다.","ox":"O","m":"⑤","c":"A","tp":"어음의 권리 취득, 행사, 소멸 등"}],"13":[{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35","t":"상법상 정관에 의하여 주식의 양도가 제한되는 경우에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 정관에 의하여 주식의 양도가 제한되는 경우에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우에는 주식을 양도하고자 하는 주주는 회사에 대하여 양도의 상대방 및 양도하고자 하는 주식의 종류와 수를 기재한 서면으로 양도의 승인을 청구할 수 있고, 이 경우 회사가 주주의 양도승인청구가 있는 날부터 1월 이내에 주주에게 거부의 통지를 하지 아니한 때에는 주식양도를 이사회가 승인한 것으로 본다.","정관에 의하여 양도가 제한된 주식을 보유한 주주는 이사회로부터 양도승인거부의 통지를 받은 경우 통지를 받은 날부터 20일 내에 회사에 대하여 양도상대방의 지정 또는 그 주식의 매수를 청구할 수 있다.","주주가 양도의 상대방을 지정하여 줄 것을 청구한 경우에는 이사회는 이를 지정하고, 그 청구가 있은 날부터 2주간 내에 주주 및 지정된 상대방에게 서면으로 이를 통지하여야 한다. 위 기간 내에 주주에게 상대방지정의 통지를 하지 아니한 때에는 주식의 양도에 관하여 이사회의 승인이 있는 것으로 본다.","위 ③항 전문에 의하여 상대방으로 지정된 자는 지정통지를 받은 날부터 10일 이내에 지정청구를 한 주주에 대하여 서면으로 그 주식을 자기에게 매도할 것을 청구할 수 있다.","주식양도에 관하여 이사회의 승인을 얻어야 하는 경우, 주식양도인이 양도승인을 청구할 수는 있으나, 그로부터 주식을 취득한 자가 회사에 대하여 그 주식취득의 승인을 청구할 수는 없다."],"a":5}},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-1","t":"지배주주는 회사의 경영상 목적을 달성하기 위해 필요한 경우 미리 주주총회의 승인을 받아 소수주주에게 그 보유하는 주식의 매도청구를 할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-2","t":"지배주주가 있는 회사의 소수주주는 언제든지 지배주주에게 그 보유주식의 매수를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-3","t":"지배주주로부터 매도청구를 받은 소수주주는 매도청구를 받은 날부터 1개월 내에 지배주주에게 그 주식을 매도하여야 한다.","ox":"X","m":"③","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-4","t":"지배주주에 의한 소수주식의 전부 취득시 그 매매가액은 매도청구를 받은 소수주주와 매도를 청구한 지배주주 간의 협의로 결정하고, 매도청구를 받은 날부터 30일 내에 매매가액 협의가 이루어지지 아니한 경우 해당 소수주주 또는 지배주주는 법원에 매매가액의 결정을 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-5","t":"지배주주가 소수주주에 대한 매도청구에 따라 소수주식을 취득하는 때에는 매매가액을 소수주주에게 지급한 때에 주식이 이전된 것으로 본다.","ox":"O","m":"⑤","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-1","t":"회사는 회사의 합병 또는 다른 회사의 영업전부의 양수로 인한 경우 자기주식을 취득할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 자기주식의 취득"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-2","t":"회사는 그 권리를 실행하기 위하여 강제집행, 담보권의 실행 등을 함에 있어 채무자에게 회사의 주식 이외에 재산이 없을 때라도 자기주식을 경락 또는 대물변제로 취득할 수는 없다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사의 자기주식의 취득"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-3","t":"회사는 단주의 처리를 위하여 필요한 경우 자기주식을 취득할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 자기주식의 취득"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-4","t":"회사는 주주가 주식매수청구권을 행사한 경우 자기주식을 취득할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 자기주식의 취득"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-5","t":"상법상 자기주식 취득 금지규정에 위반하여 회사가 자기주식을 취득하거나 취득하기로 하는 약정은 무효이다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 자기주식의 취득"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43-1","t":"주권발행 전에 한 주식의 양도라도 회사성립 후 또는 신주의 납입기일 후 6월이 경과한 때에는 회사에 대하여 효력이 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식의 양도"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43-2","t":"주권발행 전 주식의 이중양도가 문제 되는 경우에 그 이중양수인 상호간의 우열은 지명채권 이중양도에 준하여 확정일자 있는 양도통지가 회사에 도달한 일시 또는 확정일자 있는 승낙의 일시의 선후에 의하여 결정하는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"상법상 주식의 양도"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43-3","t":"주권발행 후의 주식의 양도에 있어서는 주권을 교부하여야 효력이 발생하고, 주권의 교부는 현실의 인도 이외에 간이인도, 반환청구권의 양도에 의하여 할 수 있으나 점유개정의 방법에 의해서는 할 수 없다.","ox":"X","m":"③","c":"A","tp":"상법상 주식의 양도"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43-4","t":"주식을 양수하였으나 아직 주주명부에 명의개서를 하지 아니하여 주주명부에는 양도인이 주주로 기재되어 있는 경우 회사에 대한 관계에서는 주주명부상 주주만이 주주로서 의결권 등 주주권을 적법하게 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식의 양도"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43-5","t":"정관이 정하는 바에 따라 주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우 이사회의 승인을 얻지 아니한 주식의 양도는 회사에 대하여 효력이 없다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식의 양도"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-1","t":"회사에 대하여 주주권을 행사할 자가 주주명부의 기재에 의하여 확정되어야 한다는 법리는 주식양도의 경우뿐만 아니라 주식발행의 경우에도 마찬가지로 적용된다.","ox":"O","m":"①","c":"A","tp":"명의개서와 주주"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-2","t":"주주명부상 주주가 주식을 인수하거나 양수한 사람의 의사에 반하여 주주권을 행사하는 경우에 이러한 주주권의 행사는 신의칙에 반하여 무효이다.","ox":"X","m":"②","c":"A","tp":"명의개서와 주주"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-3","t":"상법 제337조 제1항에서 말하는 주식 이전의 대항력은 그 문언에 불구하고 회사도 주주명부 기재에 구속되어 주주명부에 기재된 자의 주주권 행사를 부인하거나 주주명부에 기재되지 아니한 자의 주주권 행사를 인정할 수 없다는 의미를 포함한다.","ox":"O","m":"③","c":"A","tp":"명의개서와 주주"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-4","t":"회사는 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았든 몰랐든 간에 주주명부에 기재를 마치지 아니한 자의 주주권 행사를 인정할 수 없다.","ox":"O","m":"④","c":"A","tp":"명의개서와 주주"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-5","t":"회사는 정관으로 정하는 바에 따라 전자문서로 주주명부를 작성할 수 있는데, 전자주주명부에는 주주명부의 기재사항 외에 전자우편주소를 적어야 한다.","ox":"O","m":"⑤","c":"A","tp":"명의개서와 주주"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43-1","t":"회사성립 후 6월이 경과하기 전에는 주권 발행 전의 주식을 양도하더라도 당사자 사이에서만 채권적 효력이 있을 뿐 회사에 대하여는 효력이 없다.","ox":"O","m":"①","c":"A","tp":"상법상 주권의 발행과 양도"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43-2","t":"상법 제356조에서는 주권에 회사의 상호, 회사가 발행할 주식의 총수, 회사 성립 후 발행된 주식에 관하여는 그 발행 연월일 등을 기재하도록 정하고 있으므로 이러한 기재사항을 모두 기재하지 않으면 그 주권은 무효이다.","ox":"X","m":"②","c":"A","tp":"상법상 주권의 발행과 양도"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43-3","t":"주주는 회사에 대해 주권의 발행 및 교부청구권을 행사할 수 있는데, 이러한 권리는 주주의 채권자가 대위해서 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주권의 발행과 양도"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43-4","t":"액면주식 1주의 금액은 100원 이상으로 하여야 하고 액면주식의 금액은 균일하여야 한다.","ox":"O","m":"④","c":"A","tp":"상법상 주권의 발행과 양도"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43-5","t":"주식의 양도성은 정관에 의해 이사회 승인을 받도록 하는 방법으로 제한될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주권의 발행과 양도"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-1","t":"상법은 주식의 유통성으로 인해 주주가 계속 변동되는 단체적 법률관계의 특성을 고려하여 주주들과 회사 간의 권리관계를 획일적이고 안정적으로 처리할 수 있도록 명의개서제도를 마련해 두고 있다.","ox":"O","m":"①","c":"A","tp":"주주의 지위"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-2","t":"주주명부에 명의개서를 한 주식양수인은 회사에 대하여 자신이 권리자라는 사실을 따로 증명하지 않고도 의결권, 배당금청구권, 신주인수권 등 주주로서의 권리를 적법하게 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"주주의 지위"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-3","t":"회사로서도 주주명부에 기재된 자를 주주로 보고 주주로서의 권리를 인정한 경우 주주명부상 주주가 진정한 주주가 아니더라도 책임을 지지 않는다.","ox":"O","m":"③","c":"A","tp":"주주의 지위"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-4","t":"주권발행 전 주식의 양도담보권자와 동일 주식에 대하여 압류명령을 집행한 자 사이의 우열은 주주명부에 명의개서를 한 선후에 의하여 결정된다.","ox":"X","m":"④","c":"A","tp":"주주의 지위"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-5","t":"회사에 대하여 주주권을 행사할 자가 주주명부의 기재에 의하여 확정되어야 한다는 법리는 주식양도의 경우뿐만 아니라 주식발행의 경우에도 마찬가지로 적용된다.","ox":"O","m":"⑤","c":"A","tp":"주주의 지위"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22-1","t":"질권자는 계속하여 주권을 점유하지 아니하면 그 질권으로써 제3자에게 대항하지 못한다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 주식의 담보설정"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22-2","t":"주식의 소각, 병합, 분할 또는 전환이 있는 때에는 이로 인하여 종전의 주주가 받을 금전이나 주식에 대하여도 종전의 주식을 목적으로 한 질권을 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 주식의 담보설정"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22-3","t":"주식의 질권설정에 필요한 요건인 주권의 점유를 이전하는 방법으로는 현실인도(교부)만이 허용될 뿐, 반환청구권의 양도는 허용되지 않는다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사 주식의 담보설정"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22-4","t":"회사는 회사의 합병 또는 다른 회사의 영업전부의 양수로 인한 경우에는 발행주식총수의 20분의 1을 초과하여 자기의 주식을 질권의 목적으로 받을 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 주식의 담보설정"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22-5","t":"명의개서를 마친 등록양도담보권자는 자익권과 공익권 등 주주권을 행사할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사 주식의 담보설정"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-1","t":"주식회사는 우선주에 한하여 의결권이 없는 주식을 발행할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 종류주식"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-2","t":"회사가 의결권이 없는 종류주식 등을 발행하는 경우에 정관에 의결권의 행사 또는 부활의 조건 등을 정한 경우에는 그 조건 등을 정하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 종류주식"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-3","t":"회사가 분할 또는 분할합병을 하기 위한 주주총회의 승인결의에 관하여는 의결권이 배제되는 주주도 의결권이 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 종류주식"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-4","t":"회사는 정관으로 정하는 바에 따라 주주가 회사에 대하여 상환을 청구할 수 있는 종류주식을 발행할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 종류주식"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-5","t":"회사가 종류주식을 발행하는 경우에는 정관에 일정한 사유가 발생할 때 회사가 주주의 인수 주식을 다른 종류주식으로 전환할 수 있음을 정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 종류주식"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-1","t":"회사는 정관으로 정하는 바에 따라 상법 제434조가 정한 주주총회의 특별결의로 회사의 설립·경영 및 기술혁신 등에 기여하거나 기여할 수 있는 회사의 이사, 집행임원, 감사 또는 피용자에게 미리 정한 가액으로 신주를 인수하거나 자기의 주식을 매수할 수 있는 권리를 부여할 수 있다.","ox":"O","m":"①","c":"A","tp":"주식매수선택권"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-2","t":"회사는 주식매수선택권을 부여받은 자의 권리를 부당하게 제한하지 않고 정관의 기본 취지나 핵심 내용을 해치지 않는 범위에서 주주총회 결의와 개별 계약을 통해서 주식매수선택권을 부여받은 자가 언제까지 선택권을 행사할 수 있는지를 자유롭게 정할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-3","t":"주주총회 결의 이후 회사가 주식매수선택권 부여에 관한 계약을 체결할 때 주식매수선택권의 행사기간 등을 일부 변경하거나 조정한 경우 그것이 주식매수선택권을 부여받은 자, 기존 주주 등 이해관계인들 사이의 균형을 해치지 않고 주주총회 결의에서 정한 본질적인 내용을 훼손하는 것이 아니라면 유효하다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-4","t":"본인의 귀책사유가 아닌 사유로 퇴임 또는 퇴직하게 된 경우에는, 비록 형식적으로는 상법 제340조의4 제1항의 ‘2년 이상 재임 또는 재직’ 요건을 충족하지 못하더라도 주식매수선택권을 행사할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-5","t":"회사가 주식매수선택권을 부여하기 위해서는 정관에 근거가 있어야 하고, 주식매수선택권에 관한 주주총회 결의에서는 주식매수선택권을 부여받을 자의 성명, 부여방법, 행사가액과 조정에 관한 사항, 주식매수선택권의 행사기간, 주식매수선택권의 행사로 발행하거나 양도할 주식의 종류와 수를 정하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-1","t":"상법 제335조 제3항 소정의 주권발행 전에 한 주식의 양도는 회사성립 후 6월이 경과한 때에는 회사에 대하여 효력이 있는 것으로서, 이 경우 주식의 양도는 지명채권의 양도에 관한 일반원칙에 따라 당사자의 의사표시만으로 효력이 발생하는 것이고, 상법 제337조 제1항에 규정된 주주명부상의 명의개서는 주식의 양수인이 회사에 대한 관계에서 주주의 권리를 행사하기 위한 대항요건에 지나지 아니한다.","ox":"O","m":"①","c":"A","tp":"주권발행 전 주식양도"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-2","t":"주권발행 전 주식의 양도가 회사 성립 후 6월이 경과한 후에 이루어진 때에는 당사자의 의사표시만으로 회사에 대하여 효력이 있으므로, 주식양수인은 특별한 사정이 없는 한 양도인의 협력을 받을 필요 없이 단독으로 자신이 주식을 양수한 사실을 증명함으로써 회사에 대하여 명의개서를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"주권발행 전 주식양도"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-3","t":"회사성립 후 또는 신주의 납입기간 후 6월이 지나도록 주권이 발행되지 않아 주권 없이 채권담보를 목적으로 체결된 주식양도계약은 바로 주식양도담보의 효력이 생기고, 양도담보권자가 대외적으로는 주식의 소유자가 된다. 주권발행 전 주식의 양도담보권자와 동일 주식에 대하여 압류명령을 집행한 자 사이의 우열은 주식양도의 경우와 마찬가지로 확정일자 있는 증서에 의한 양도통지 또는 승낙의 일시와 압류명령의 송달일시를 비교하여 그 선후에 따라 결정된다. 이때 그들이 주주명부에 명의개서를 하였는지 여부와는 상관없다.","ox":"O","m":"③","c":"A","tp":"주권발행 전 주식양도"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-4","t":"주권발행 전 주식의 양도에 관한 양도통지가 확정일자 없는 증서에 의하여 이루어짐으로써 제3자에 대한 대항력을 갖추지 못하였더라도 확정일자 없는 증서에 의한 양도통지나 승낙 후에 그 증서에 확정일자를 얻은 경우에는 최초 양도통지일에 소급하여 제3자에 대한 대항력을 취득한다.","ox":"X","m":"④","c":"A","tp":"주권발행 전 주식양도"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-5","t":"주권발행 전 주식의 양도인은 양수인에 대하여 회사에 양도통지를 하거나 회사로부터 승낙을 받음으로써 제3자에 대한 대항요건을 갖추어줄 의무를 부담한다.","ox":"O","m":"⑤","c":"A","tp":"주권발행 전 주식양도"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-1","t":"주식의 이전은 취득자의 성명과 주소를 주주명부에 기재하지 아니하면 회사에 대항하지 못한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-2","t":"타인의 명의를 빌려 주식을 인수하고 타인의 명의로 주주명부 기재를 마친 경우 실질상의 주주인 명의차용인만이 주주권을 행사할 수 있는 주주이다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-3","t":"회사는 특별한 사정이 없는 한 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았든 몰랐든 간에 주주명부상 주주의 주주권 행사를 부인할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-4","t":"타인의 명의로 주식을 인수한 경우에 누가 주주인지는 결국 주식인수를 한 당사자를 누구로 볼 것인지에 따라 결정하여야 한다. 이때 누가 주식인수인이고 주주인지는 결국 신주인수계약의 당사자 확정 문제이므로, 원칙적으로 계약당사자를 확정하는 법리를 따르되, 주식인수계약의 특성을 고려하여야 한다.","ox":"O","m":"④","c":"A","tp":"주주명부"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-5","t":"주주명부에 기재를 마치지 않고도 회사에 대한 관계에서 주주권을 행사할 수 있는 경우는 주주명부에 기재 또는 명의개서청구가 부당하게 지연되거나 거절되었다는 등의 극히 예외적인 사정이 인정되는 경우에 한한다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-1","t":"주권의 점유를 취득하는 방법에는 현실의 인도 외에 간이인도, 반환청구권의 양도가 있다. 양도인이 소유자로부터 보관을 위탁받은 주권을 제3자에게 보관시킨 경우에 반환청구권의 양도에 의하여 주권의 선의취득에 필요한 요건인 주권의 점유를 취득하였다고 하려면, 양도인이 그 제3자에 대한 반환청구권을 양수인에게 양도하고 지명채권 양도의 대항요건을 갖추어야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-2","t":"상법 제355조의 주권발행은 동법 제356조 소정의 형식을 구비한 문서를 작성하여 이를 주주에게 교부하는 것을 말하고, 위 문서가 주주에게 교부된 때에 비로소 주권으로서의 효력을 발생하는 것이므로, 회사가 주주권을 표창하는 문서를 작성하여 이를 주주가 아닌 제3자에게 교부하여 주었다 할지라도 위 문서는 아직 회사의 주권으로서의 효력을 가지지 못한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-3","t":"주식의 양도는 이사회의 승인을 얻도록 회사 정관에 규정되어 있음에도 이사회의 승인을 얻지 아니하고 주식을 양도하였다면 그 주식의 양도는 회사에 대하여뿐만 아니라 주주 사이의 주식양도계약 자체가 무효가 된다.","ox":"X","m":"③","c":"A","tp":"주권"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-4","t":"주권의 선의취득은 주권의 소지라는 권리외관을 신뢰하여 거래한 사람을 보호하는 제도로서, 주권 취득이 악의 또는 중대한 과실로 인한 때에는 선의취득이 인정되지 않는다. 여기서 악의 또는 중대한 과실이 있는지는 그 취득 시기를 기준으로 결정하여야 하며, 악의란 교부계약에 하자가 있다는 것을 알고 있었던 경우를 말하고 중대한 과실이란 주의의무를 현저히 결여한 것을 말한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-5","t":"주권발행전 주식의 양도가 회사 성립 후 6월이 경과한 후에 이루어진 때에는 당사자의 의사표시만으로 회사에 대하여 효력이 있으므로, 그 주식양수인은 특별한 사정이 없는 한 양도인의 협력을 받을 필요 없이 단독으로 자신이 주식을 양수한 사실을 증명하여 회사에 대하여 그 명의개서를 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-1","t":"상법 등에서 명시적으로 자기주식의 취득을 허용하는 경우 외에 회사의 자본적 기초를 위태롭게 하거나 주주 등의 이익을 해한다고 할 수 없는 것이 유형적으로 명백한 경우에도 자기주식의 취득이 예외적으로 허용되지만, 그 밖의 경우에는, 설령 회사 또는 주주나 회사채권자 등에게 생길지도 모르는 중대한 손해를 회피하기 위하여 부득이 한 사정이 있다고 하더라도 자기주식의 취득은 허용되지 않고 위와 같은 금지규정에 위반하여 회사가 자기주식을 취득하는 것은 당연히 무효이다.","ox":"O","m":"①","c":"A","tp":"주식양도의 제한"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-2","t":"정관에 의하여 양도가 제한된 주식을 보유한 주주는 이사회로부터 양도승인거부의 통지를 받은 경우 통지를 받은 날부터 20일 내에 회사에 대하여 양도 상대방의 지정 또는 그 주식의 매수를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"주식양도의 제한"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-3","t":"상법 제335조 제1항 단서는 주식의 양도를 전제로 하고, 다만 이를 제한하는 방법으로서 이사회의 승인을 요하도록 정관에 정할 수 있다는 취지이지 주식의 양도 그 자체를 금지할 수 있음을 정할 수 있다는 뜻은 아니기 때문에, 정관의 규정으로 주식의 양도를 제한하는 경우에도 주식양도를 전면적으로 금지하는 규정을 둘 수는 없다.","ox":"O","m":"③","c":"A","tp":"주식양도의 제한"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-4","t":"甲회사가 乙회사의 발생주식 총수의 10분의 1을 초과하여 취득한 때에는 乙회사에 지체없이 이를 통지하여야 하고, 이 경우 乙회사가 가지고 있는 甲회사의 주식은 의결권이 없다.","ox":"O","m":"④","c":"A","tp":"주식양도의 제한"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-5","t":"주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우에 주식을 취득하였으나 회사로부터 양도승인거부의 통지를 받은 양수인은 상법 제335조의7에 따라 회사에 대하여 주식매수청구권을 행사할 수 있다. 이와 관련하여 주식을 취득하지 못한 양수인이 회사에 대하여 주식매수청구를 하더라도 이는 효력이 없으나, 사후적으로 양수인이 주식 취득의 요건을 갖추게 되면 그 하자가 치유될 수 있다.","ox":"X","m":"⑤","c":"A","tp":"주식양도의 제한"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-1","t":"주권발행 전 주식의 양도가 회사 성립 후 6월이 경과한 후에 이루어진 때에는 당사자의 의사표시만으로 회사에 대하여 효력이 있으므로, 주식양수인은 특별한 사정이 없는 한 양도인의 협력을 받을 필요 없이 단독으로 자신이 주식을 양수한 사실을 증명함으로써 회사에 대하여 명의개서를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식의 양도 및 명의개서"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-2","t":"회사성립 후 또는 신주의 납입기간 후 6월이 지나도록 주권이 발행되지 않아 주권 없이 채권담보를 목적으로 체결된 주식양도계약에 따른 주식의 양도담보권자와 동일 주식에 대하여 압류명령을 집행한 자 사이의 우열은 그들이 주주명부에 명의개서를 하였는지 여부와는 상관없이 확정일자 있는 증서에 의한 양도통지 또는 승낙의 일시와 압류명령의 송달일시를 비교하여 그 선후에 따라 결정된다.","ox":"O","m":"②","c":"A","tp":"상법상 주식의 양도 및 명의개서"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-3","t":"상법은 주주명부의 기재를 회사에 대한 대항요건으로 정하고 있을 뿐 주식 이전의 효력발생요건으로 정하고 있지 않으므로 명의개서가 이루어졌다고 하여 무권리자가 주주가 되는 것은 아니고, 명의개서가 이루어지지 않았다고 해서 주주가 그 권리를 상실하는 것도 아니다.","ox":"O","m":"③","c":"A","tp":"상법상 주식의 양도 및 명의개서"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-4","t":"주식을 인수하거나 양수하려는 자가 타인의 명의를 빌려 회사의 주식을 인수하거나 양수하고 타인의 명의로 주주명부에의 기재까지 마친 경우, 주주명부상의 주주가 아니라 명의를 빌려 실제 주식을 인수하거나 양수한 자가 회사에 대한 관계에서 주주로서 의결권 등 주주권을 적법하게 행사할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 주식의 양도 및 명의개서"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-5","t":"주주가 양도의 상대방을 지정하여 줄 것을 청구한 경우, 이사회가 2주간 내에 주주에게 상대방지정의 통지를 하지 아니한 때에는 주식의 양도에 관하여 이사회의 승인이 있는 것으로 본다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식의 양도 및 명의개서"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50-1","t":"대표이사가 정관에 규정된 병합 주권의 종류와 다른 주권을 발행하였다고 하더라도 회사가 이미 발행한 주식을 표창하는 주권을 발행한 것이라면, 위와 같은 정관 규정에 위배되었다는 사유만으로 이미 발행된 위 주권이 무효라고 할 수는 없다.","ox":"O","m":"①","c":"A","tp":"상법상 주권"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50-2","t":"주식의 양도에 있어서는 주권을 교부하여야 하고, 주권이 발행되어 있는 주식을 양수한 자는 주권을 제시하여 양수사실을 증명함으로써 회사에 대해 단독으로 명의개서를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주권"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50-3","t":"주권이 발행되어 있는 주식을 양수한 자가 단독으로 명의개서를 청구한 경우, 회사는 청구자가 진정한 주주인가에 대한 실질적 자격을 심사하여 명의개서 여부를 결정하여야 한다.","ox":"X","m":"③","c":"A","tp":"상법상 주권"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50-4","t":"주주의 주권불소지신고에 의해 회사가 주주명부에 주권을 발행하지 아니한다는 뜻을 기재하고 그 사실을 주주에게 통지한 경우, 회사는 그 주권을 발행할 수 없다.","ox":"O","m":"④","c":"A","tp":"상법상 주권"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50-5","t":"주권을 상실한 자는 제권판결을 얻지 아니하면 회사에 대하여 주권의 재발행을 청구하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주권"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-1","t":"상법 제335조 제3항 소정의 주권발행 전에 한 주식의 양도는 회사성립 후 6월이 경과한 때에는 회사에 대하여 효력이 있는 것으로서, 이 경우 주식의 양도는 지명채권의 양도에 관한 일반원칙에 따라 당사자의 의사표시만으로 효력이 발생하는 것이고, 상법 제337조 제1항에 규정된 주주명부상의 명의개서는 주식의 양수인이 회사에 대한 관계에서 주주의 권리를 행사하기 위한 대항요건에 지나지 아니한다.","ox":"O","m":"①","c":"A","tp":"주식회사의 주식양도 내지 명의개서"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-2","t":"상법 제335조 제1항의 본문 및 단서에 의하면, 주식은 원칙적으로 타인에게 양도할 수 있고, 예외적으로 회사가 정관으로 정하는 바에 따라 그 발행하는 주식의 양도에 관하여 이사회의 승인을 받도록 할 수 있을 뿐이므로, 주주 사이에서 주식의 양도를 일부 제한하는 약정은 원칙적으로 무효이다.","ox":"X","m":"②","c":"A","tp":"주식회사의 주식양도 내지 명의개서"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-3","t":"주권발행 전 주식의 양도가 회사 성립 후 6월이 경과한 후에 이루어진 때에는 당사자의 의사표시만으로 회사에 대하여 효력이 있으므로, 주식양수인은 특별한 사정이 없는 한 양도인의 협력을 받을 필요 없이 단독으로 자신이 주식을 양수한 사실을 증명함으로써 회사에 대하여 명의개서를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"주식회사의 주식양도 내지 명의개서"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-4","t":"주권발행 전에 한 주식의 양도가 회사성립 후 또는 신주의 납입기일 후 6월이 경과하기 전에 이루어졌다고 하더라도 그 이후 6월이 경과하고 그 때까지 회사가 주권을 발행하지 않았다면, 그 하자는 치유되어 회사에 대하여도 유효한 주식양도가 된다.","ox":"O","m":"④","c":"A","tp":"주식회사의 주식양도 내지 명의개서"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-5","t":"명의개서청구권은 기명주식을 취득한 자가 회사에 대하여 주주권에 기하여 그 기명주식에 관한 자신의 성명, 주소 등을 주주명부에 기재하여 줄 것을 청구하는 권리로서 기명주식을 취득한 자만이 그 기명주식에 관한 명의개서청구권을 행사할 수 있다. 또한 기명주식의 취득자는 원칙적으로 취득한 기명주식에 관하여 명의개서를 할 것인지 아니면 명의개서 없이 이를 타인에게 처분할 것인지 등에 관하여 자유로이 결정할 권리가 있으므로, 주식 양도인은 다른 특별한 사정이 없는 한 회사에 대하여 주식 양수인 명의로 명의개서를 하여 달라고 청구할 권리가 없다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 주식양도 내지 명의개서"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46-1","t":"상법 제341조의2에서 정한 특정목적에 의한 자기주식 취득이 아닌 경우에 회사는 직전 결산기의 배당가능이익을 초과하지 않는 범위에서 자기주식을 취득할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 자기주식"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46-2","t":"배당가능이익으로 하는 자기주식취득에서 매수할 주식의 종류와 수, 취득가액의 총액 한도 등은 주주총회 결의로 정하지만, 정관에서 이사회의 결의로 이익배당을 할 수 있다고 정하는 경우에는 이사회 결의로 정할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 자기주식"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46-3","t":"회사의 합병 또는 다른 회사의 영업전부의 양수로 인한 경우, 회사의 권리를 실행함에 있어 그 목적을 달성하기 위하여 필요한 경우, 단주의 처리를 위하여 필요한 경우, 주주가 주식매수청구권을 행사한 경우에는 배당가능이익과 무관하게 자기주식을 취득할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 자기주식"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46-4","t":"회사가 자기주식을 취득한 경우 상법 제341조의2에서 정한 특정목적에 의한 자기주식 취득이 아닌 이상 지체없이 주식실효의 절차를 밟아야 한다.","ox":"X","m":"④","c":"A","tp":"상법상 자기주식"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46-5","t":"자기주식의 취득이 예외적으로 허용되는 경우를 제외하고, 상법에서 정한 요건과 절차에 따르지 않은 자기주식 취득은 당연히 무효이다.","ox":"O","m":"⑤","c":"A","tp":"상법상 자기주식"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-1","t":"회사의 발행주식총수의 100분의 90 이상을 자기의 계산으로 보유하고 있는 주주는 회사의 경영상 목적을 달성하기 위하여 필요한 경우에는 회사의 다른 주주에게 그 보유하는 주식의 매도를 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-2","t":"지배주주가 소수주주에게 그가 보유하는 주식의 매도청구를 할 때에는 미리 주주총회의 승인을 받아야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-3","t":"지배주주가 있는 회사의 소수주주는 언제든지 지배주주에게 그 보유주식의 매수를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-4","t":"지배주주가 소수주주에 대한 매도청구에 따라 소수주주의 주식을 취득하는 경우, 지배주주가 매매가액을 소수주주에게 지급한 때에 주식이 이전된 것으로 본다.","ox":"O","m":"④","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-5","t":"자회사의 소수주주가 상법 제360조의25 제1항에 따라 모회사에 주식매수청구를 한 경우, 모회사가 지배주주에 해당하는지는 자회사가 보유한 자기주식을 발행주식 총수 및 모회사의 보유주식에 각각 합산하여 판단하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 지배주주에 의한 소수주식의 전부 취득"},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48-1","t":"주주평등의 원칙에 위반하여 회사가 일부 주주에게만 우월한 권리나 이익을 부여하기로 하는 약정은 특별한 사정이 없는 한 무효이다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48-2","t":"회사가 직원들을 유상증자에 참여시키면서 퇴직 시 그 출자 손실금을 전액 보전해 주는 약정은 사용자와 근로자의 관계를 규율하는 단체협약이나 취업규칙의 성격을 함께 가지고 있더라도 무효이다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48-3","t":"잔여재산은 각 주주가 가진 주식 수에 따라 주주에게 분배하여야 한다. 그러나 회사가 잔여 재산의 분배 등에 관하여 내용이 다른 종류의 주식을 발행한 경우에는 그러하지 아니하다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48-4","t":"회사가 주주에게 투하자본의 회수를 절대적으로 보장하는 내용의 약정은 원칙적으로 무효이지만 주주 전원의 동의를 받았다는 특별한 사정이 인정된다면 유효하다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48-5","t":"주주와 다른 주주 사이의 계약은 주주평등의 원칙과 관련이 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-1","t":"주주 또는 회사채권자가 상법 제396조 제2항에 의하여 주주명부 등의 열람·등사청구를 한 경우 회사는 그 청구에 정당한 목적이 없는 등의 특별한 사정이 없는 한 이를 거절할 수 없는데, 이 경우 주주 또는 회사채권자가 정당한 목적이 있다는 점에 관한 증명책임을 부담한다.","ox":"X","m":"①","c":"A","tp":"주주명부와 명의개서"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-2","t":"주주명부에 명의개서를 한 주식양수인은 회사에 대하여 자신이 권리자라는 사실을 따로 증명하지 않고도 의결권, 배당금청구권, 신주인수권 등 주주로서의 권리를 적법하게 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"주주명부와 명의개서"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-3","t":"주식회사는 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았든 몰랐든 간에 주주명부상 주주의 주주권 행사를 부인할 수 없으며, 주주명부에 기재를 마치지 아니한 자의 주주권 행사를 인정할 수도 없다.","ox":"O","m":"③","c":"A","tp":"주주명부와 명의개서"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-4","t":"주식을 취득한 자가 회사에 대하여 의결권을 주장할 수 있기 위하여는 주주명부에 주주로서 명의개서를 하여야 하므로, 명의개서를 하지 아니한 주식양수인에 대하여 주주총회소집통지를 하지 않았다고 하여 주주총회결의에 절차상의 하자가 있다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"주주명부와 명의개서"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-5","t":"주권이 발행되어 있는 주식을 양수한 자는 주권을 제시하여 양수사실을 증명함으로써 회사에 대해 단독으로 명의개서를 청구할 수 있다. 이때 회사는 청구자가 진정한 주권을 점유하고 있는가에 대한 형식적 자격만을 심사하면 족하고, 나아가 청구자가 진정한 주주인가에 대한 실질적 자격까지 심사할 의무는 없다.","ox":"O","m":"⑤","c":"A","tp":"주주명부와 명의개서"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34","t":"주식회사 甲의 다음 행위 중 현행 상법 및 판례에 의할 때 허용되는 것을 모두 고른 것은?","c":"A","mc":{"s":"주식회사 甲의 다음 행위 중 현행 상법 및 판례에 의할 때 허용되는 것을 모두 고른 것은?","d":"ㄱ.주식회사 甲이 발행주식 총수 1,000주 중 500주를 액면가 5,000원에 발행하였는데, 추가로 신주 500주를 액면가 10,000원에 발행하는 행위\nㄴ.임원 A와 퇴직합의를 체결하면서 A가 보유한 주식회사 甲 발행 주식을 주식회사 甲이 매수하게 하는 주식매수청구권을 부여하였는데, 그 후 주식회사 甲이 배당가능이익이 없음에도 위 약정에 기한 A의 주식매수청구권 행사에 따라 주식을 취득한 행위\nㄷ.주식회사 甲이 주주 B로부터 주식회사 甲 발행 주식을 무상으로 양수하는 행위\nㄹ.주식회사 甲의 대표이사가 주주총회에 참석하여 주식회사 甲이 취득한 자기주식으로 의결권을 행사하는 행위\nㅁ.주식회사 甲 발행 주식을 C, D가 공유하는데, 그 주주권을 행사할 자가 지정되지 않는 등으로 권리행사자가 없는 상황에서 주식회사 甲이 주소와 연락처를 알고 있는 C에게만 주주권 행사 관련 통지를 하는 행위","o":["ㄱ, ㄷ","ㄱ, ㅁ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㅁ"],"a":5}},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-1","t":"주식매수선택권 제도는 회사의 설립·경영과 기술혁신 등에 기여하거나 기여할 수 있는 임직원에게 장차 주식매수로 인한 이득을 유인동기로 삼아 직무에 충실하도록 유도하기 위한 일종의 성과보상제도이다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-2","t":"주식매수선택권 부여에 관한 주주총회 결의는 회사의 의사결정절차에 그치는 것이 아니므로, 특정인에 대한 주식매수선택권의 구체적 내용은 주주총회 결의를 통해서 정해진다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-3","t":"본인의 귀책사유가 아닌 사유로 퇴임 또는 퇴직하게 되더라도 퇴임 또는 퇴직일까지 상법 제340조의4 제1항의 ‘2년 이상 재임 또는 재직’ 요건을 충족하지 못한다면 위 조항에 따른 주식매수선택권을 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-4","t":"회사는 주식매수선택권을 부여받은 자의 권리를 부당하게 제한하지 않고 정관의 기본 취지나 핵심 내용을 해치지 않는 범위에서 주주총회 결의와 개별 계약을 통해서 주식매수선택권을 부여받은 자가 언제까지 선택권을 행사할 수 있는지를 자유롭게 정할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-5","t":"회사가 주식매수선택권 부여에 관한 계약을 체결할 때 주식매수선택권의 행사기간 등을 일부 변경하거나 조정한 경우 그것이 주식매수선택권을 부여받은 자, 기존 주주 등 이해관계인들 사이의 균형을 해치지 않고 주주총회 결의에서 정한 본질적인 내용을 훼손하는 것이 아니라면 유효하다고 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39","t":"주주평등의 원칙에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"주주평등의 원칙에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.주주는 원칙적으로 회사와의 법률관계에서 그가 가진 주식의 수에 따라 평등한 취급을 받아야 하지만, 회사가 일부 주주에게 우월한 권리나 이익을 부여하여 다른 주주들과 다르게 대우하는 경우에도 법률이 허용하는 절차와 방식에 따르거나 그 차등적 취급을 정당화할 수 있는 특별한 사정이 있는 경우에는 이를 허용할 수 있다. 회사의 주주에 대한 차등적 취급을 허용할 수 있는지 여부는 제반 사정을 고려하여 일부 주주에게 우월적 권리나 이익을 부여하여 주주를 차등 취급하는 것이 주주와 회사 전체의 이익에 부합하는지를 따져서 정의와 형평의 관념에 비추어 신중하게 판단하여야 한다.\nㄴ.회사와 주주가 회사의 중요 의사결정에 대하여 일부 주주의 사전동의를 받도록 하는 약정을 체결하였고 그 약정에 따른 일부 주주에 대한 차등적 취급이 예외적으로 허용되는 경우에 그 동의권 부여 약정 위반으로 인한 손해배상 명목의 금원을 지급하는 약정을 함께 체결하였다면, 그 금원 지급 약정이 사전동의를 받을 의무 위반으로 주주가 입은 손해를 배상 또는 전보하고 의무의 이행을 확보하기 위한 것이라 하더라도, 이는 투하자본의 회수를 절대적으로 보장함으로써 주주평등의 원칙에 위배되는 것이다.\nㄷ.주주가 회사와 계약을 체결할 때 회사의 다른 주주 내지 이사 개인이 함께 당사자로 참여한 경우에는 주주와 회사의 다른 주주 내지 이사 개인의 법률관계에도 주주평등의 원칙을 직접 적용할 수 있다.\nㄹ.주주가 회사의 다른 주주 내지 이사 개인과 체결한 계약의 내용을 해석할 때에는 계약의 형식과 내용, 계약이 체결된 동기와 경위 및 목적, 당사자의 진정한 의사 등을 종합적으로 고려하여 논리와 경험의 법칙, 사회일반의 상식과 거래의 통념에 따라 합리적으로 해석해야 하는 등 계약 해석에 관한 일반 원칙을 적용할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":3}},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-1","t":"상법 제335조 제1항 단서는 주식의 양도를 제한하는 방법으로서 이사회의 승인을 요하도록 정관에 정할 수 있다는 취지이다. 따라서 정관의 규정으로 주식의 양도를 제한하는 경우 주식양도를 전면적으로 금지하도록 할 수 있다.","ox":"X","m":"①","c":"A","tp":"주식양도의 제한"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-2","t":"주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우에 주식을 취득하였으나 회사로부터 양도승인거부의 통지를 받은 양수인은 회사에 대하여 주식매수청구권을 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"주식양도의 제한"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-3","t":"상법 제335조 제1항 단서의 취지에 비추어 볼 때, 주주들 사이에서 주식의 양도를 일부 제한하는 내용의 약정을 한 경우, 그 약정은 주주의 투하자본회수의 가능성을 전면적으로 부정하는 것이 아니고, 공서양속에 반하지 않는다면 당사자 사이에서는 원칙적으로 유효하다.","ox":"O","m":"③","c":"A","tp":"주식양도의 제한"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-4","t":"주권발행 전에 한 주식의 양도는 회사에 대하여 효력이 없으나 회사성립 후 또는 신주의 납입기일 후 6월이 경과한 때에는 회사에 대하여도 효력이 있다. 이 경우 주식의 양도는 지명채권의 양도에 관한 일반원칙에 따라 당사자의 의사표시만으로 효력이 발생한다.","ox":"O","m":"④","c":"A","tp":"주식양도의 제한"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-5","t":"주권발행 전에 한 주식의 양도가 회사성립 후 또는 신주의 납입기일 후 6월이 경과하기 전에 이루어졌다고 하더라도 그 이후 6월이 경과하고 그때까지 회사가 주권을 발행하지 않았다면, 그 하자는 치유되어 회사에 대하여도 유효한 주식양도가 된다.","ox":"O","m":"⑤","c":"A","tp":"주식양도의 제한"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-1","t":"2011. 4. 14. 법률 제10600호로 개정되어 2012. 4. 15.부터 시행된 개정 상법에 따라 회사의 자기주식취득은 원칙적으로 허용되었고, 상법 규정에서 정한 요건 및 절차를 사후에 갖춘 경우에도 쉽게 그 효력이 부정된다고 볼 수 없다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-2","t":"회사가 주주들에게 보낸 자기주식취득 통지서에 이사회에서 결의한 사항의 일부가 누락되었더라도, 자기주식취득의 정당한 목적이 인정되고 대가가 정당하게 산정되는 등 여러 사정을 종합하여 주주들의 공평한 주식양도의 기회가 침해되었다고 보기 어렵다는 등의 사정이 있다면, 자기주식취득 거래를 당연 무효라고 단정할 수 없다.","ox":"O","m":"②","c":"A","tp":"회사의 자기주식취득"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-3","t":"자기주식취득 가액의 총액을 제한하는 상법 제341조 제1항 단서는 자기주식 취득가액의 총액이 배당가능이익을 초과하여서는 안 된다는 것을 의미할 뿐 차입금으로 자기주식을 취득하는 것이 허용되지 않는다는 것을 의미하지 않는다.","ox":"O","m":"③","c":"A","tp":"회사의 자기주식취득"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-4","t":"회사가 특정 주주와 사이에 특정한 금액으로 주식을 매수하기로 약정함으로써 사실상 매수청구를 할 수 있는 권리를 부여하여 주주가 그 권리를 행사하는 경우, 이는 특정목적, 즉 주주의 주식매수청구의 행사에 의한 자기주식의 취득에 관한 상법 제341조의2 제4호가 적용된다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"회사의 자기주식취득"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-5","t":"회사 아닌 제3자의 명의로 회사의 주식을 취득하더라도 그 주식취득을 위한 자금이 회사의 출연에 의한 것이고 그 주식취득에 따른 손익이 회사에 귀속되는 경우라면, 상법 기타의 법률에서 규정하는 예외사유에 해당하지 않는 한, 그러한 주식의 취득은 상법 제341조의 자기주식의 취득으로 평가될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"회사의 자기주식취득"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-1","t":"다른 회사의 발행주식의 총수의 100분의 50을 초과하는 주식을 가진 회사(모회사)의 주식은 상법 제342조의2 제1항 각호에서 정한 경우를 제외하고는 그 다른 회사(자회사)가 이를 취득할 수 없다.","ox":"O","m":"①","c":"A","tp":"상호주식소유의 제한 및 의결권"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-2","t":"상법 제342조의2 제1항에서 자회사가 모회사의 주식을 취득할 수 있는 경우로 규정하는 사유는 주식의 포괄적 교환, 주식의 포괄적 이전, 회사의 합병 또는 다른 회사의 영업전부의 양수로 인한 때 또는 회사의 권리를 실행함에 있어 그 목적을 달성하기 위하여 필요한 때이다.","ox":"O","m":"②","c":"A","tp":"상호주식소유의 제한 및 의결권"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-3","t":"상법 제342조의2 제1항 각호의 사유가 있어 자회사가 모회사의 주식을 취득하더라도, 자회사는 그 주식을 취득한 날로부터 6월 이내에 모회사의 주식을 처분하여야 한다.","ox":"O","m":"③","c":"A","tp":"상호주식소유의 제한 및 의결권"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-4","t":"2개의 회사가 상대회사의 발행주식 총수의 20% 지분씩을 각각 보유하고 있을 뿐이어서 두 회사가 상법 제342조의2에서 규정하는 모자회사 관계에 이르지 않는다면, 위 각 주식은 모두 의결권이 있다.","ox":"X","m":"④","c":"A","tp":"상호주식소유의 제한 및 의결권"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-5","t":"주주총회에서 권리를 행사할 주주의 확정을 위한 기준일에는 상법 제369조 제3항에 정한 의결권이 제한되는 주식의 상호소유 요건에 해당하지 않았던 주식이라도 실제 의결권이 행사되는 주주총회일에는 그 요건을 충족하는 경우라면, 상법 제369조 제3항이 정하는 상호소유 주식에 해당하여 의결권이 없다.","ox":"O","m":"⑤","c":"A","tp":"상호주식소유의 제한 및 의결권"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48-1","t":"주주평등의 원칙을 위반하여 회사가 일부 주주에게만 우월한 권리나 이익을 부여하기로 하는 약정은 특별한 사정이 없는 한 무효이나, 회사가 일부 주주에게 우월한 권리나 이익을 부여하여 다른 주주들과 다르게 대우하는 경우에도 법률이 허용하는 절차와 방식에 따르거나 그 차등적 취급을 정당화할 수 있는 특별한 사정이 있는 경우에는 이를 허용할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48-2","t":"차등적 취급을 허용할 수 있는지 여부는, 차등적 취급에 따라 다른 주주가 입는 불이익의 내용과 정도, 개별 주주가 처분할 수 있는 사항에 관한 차등적 취급으로 불이익을 입게 되는 주주의 동의 여부와 전반적인 동의율, 회사의 상장 여부, 사업목적, 지배구조, 사업현황, 재무상태 등 제반 사정을 고려하여 일부 주주에게 우월적 권리나 이익을 부여하여 주주를 차등 취급하는 것이 주주와 회사 전체의 이익에 부합하는지를 따져서 정의와 형평의 관념에 비추어 신중하게 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"주주평등의 원칙"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48-3","t":"회사가 자금조달을 위해 신주인수계약을 체결하면서 주주의 지위를 갖게 되는 자에게 회사의 의사결정에 대한 사전 동의를 받기로 약정한 경우, 그 약정은 회사가 일부 주주에게만 우월한 권리를 부여함으로써 주주들을 차등적으로 대우하는 것이다.","ox":"O","m":"③","c":"A","tp":"주주평등의 원칙"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48-4","t":"회사가 주주의 지위를 갖게 되는 자와 사이에 주식인수대금으로 납입한 돈을 전액 보전해 주기로 약정하거나, 상법 제462조 등 법률의 규정에 의한 배당 외에 다른 주주들에게는 지급되지 않는 별도의 수익을 지급하기로 약정한다면, 이는 회사가 해당 주주에 대하여만 투하자본의 회수를 절대적으로 보장함으로써 다른 주주들에게 인정되지 않는 우월한 권리를 부여하는 것으로서 주주평등의 원칙에 위배되어 무효이다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48-5","t":"회사와 주주가 체결한 동의권 부여 약정에 따른 차등적 취급이 예외적으로 허용되는 경우에 동의권 부여 약정 위반으로 인한 손해배상 명목의 금원을 지급하는 약정을 함께 체결하였고 그 약정이 사전 동의를 받을 의무 위반으로 주주가 입은 손해를 배상 또는 전보하고 의무의 이행을 확보하기 위한 것이라고 볼 수 있는 경우, 일부 주주에 대하여 투하자본의 회수를 절대적으로 보장함으로써 주주평등의 원칙에 위배된다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-1","t":"회사성립 후 또는 신주의 납입기간 후 6개월이 지나도록 주권이 발행되지 않아 주권 없이 채권담보를 목적으로 체결된 주식양도계약은 바로 주식양도담보의 효력이 생기고, 양도담보권자가 대외적으로는 주식을 보유하게 된다.","ox":"O","m":"①","c":"A","tp":"주식의 양도성"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-2","t":"회사성립 후 또는 신주의 납입기일 후 6개월이 경과한 경우 주권발행 전의 주식은 당사자의 의사표시만으로 양도할 수 있지만, 그러한 주식양도계약이 해제된 경우 계약의 이행으로 이전된 주식이 당연히 양도인에게 복귀하는 것은 아니다.","ox":"X","m":"②","c":"A","tp":"주식의 양도성"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-3","t":"주주 사이에서 주식의 양도를 일부 제한하는 약정을 한 경우, 그 약정은 주주의 투하자본회수 가능성을 전면적으로 부정하는 것이 아니고, 선량한 풍속 그 밖의 사회질서에 반하지 않는다면 당사자 사이에서는 원칙적으로 유효하다.","ox":"O","m":"③","c":"A","tp":"주식의 양도성"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-4","t":"발행주식 전부 또는 지배주식의 양도와 함께 경영권이 주식 양도인으로부터 주식 양수인에게 이전하는 경우, 경영권의 이전은 발행주식 전부 또는 지배주식의 양도에 따른 부수적인 효과에 지나지 않아 주식 양도의무와 독립적으로 경영권 양도의무를 인정하기 어렵다.","ox":"O","m":"④","c":"A","tp":"주식의 양도성"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-5","t":"주권발행 전이라도 회사성립 후 또는 신주의 납입기일 후 6개월이 지나면 당사자의 의사표시만으로 주식을 양도할 수 있으므로 주권발행 전 주식의 양도를 명하는 판결은 의사의 진술을 명하는 판결에 해당한다.","ox":"O","m":"⑤","c":"A","tp":"주식의 양도성"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-1","t":"회사가 주식매수선택권을 부여하기 위해서는 정관에 근거가 있어야 하고 상법 제434조가 정한 주주총회의 특별결의가 필요하다.","ox":"O","m":"①","c":"A","tp":"상법상 주식매수선택권"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-2","t":"상장회사는 상법 제542조의8 제2항 제5호의 최대주주에게 주식매수선택권을 원칙적으로 부여할 수 없다.","ox":"O","m":"②","c":"A","tp":"상법상 주식매수선택권"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-3","t":"상법은 주식매수선택권을 부여하기로 한 주주총회 결의일로부터 2년 이상 재임 또는 재직해야만 주식매수선택권을 행사할 수 있다고 하여 주식매수선택권을 행사할 수 있는 시기만을 제한하고 있을 뿐 언제까지 행사할 수 있는지에 관해서는 정하지 않고 있으므로, 회사는 주식매수선택권을 부여받은 자의 권리를 부당하게 제한하지 않고 정관의 기본 취지나 핵심 내용을 해치지 않는 범위에서 주주총회 결의와 개별 계약을 통해서 주식매수선택권을 부여받은 자가 언제까지 선택권을 행사할 수 있는지를 자유롭게 정할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 주식매수선택권"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-4","t":"상법 제340조의3에서는 주식매수선택권 부여대상과 부여방법, 행사가액, 주식매수선택권 행사로 발행하거나 양도할 주식의 종류와 수 등을 주주총회 결의로 정하도록 하고 있으므로, 주주총회 결의 시 해당 사항의 세부적인 내용도 정해야 하고, 사후적으로 회사가 주식매수선택권 부여에 관한 계약을 체결하면서 이를 변경하는 것은 허용될 수 없다.","ox":"X","m":"④","c":"A","tp":"상법상 주식매수선택권"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-5","t":"주식매수선택권의 양도는 원칙적으로 금지된다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식매수선택권"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-1","t":"특별한 사정이 없는 한 주주명부에 적법하게 주주로 기재되어 있는 자는 회사에 대한 관계에서 주식에 관한 의결권 등 주주권을 행사할 수 있다.","ox":"O","m":"①","c":"A","tp":"주주명부, 명의개서"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-2","t":"주주명부상 주주가 회사에 대한 관계에서 주주권을 행사하기 위해서는 그 주주명부의 기재가 적법하게 이루어져야 한다.","ox":"O","m":"②","c":"A","tp":"주주명부, 명의개서"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-3","t":"명의개서에 따른 주주명부의 기재가 적법하다고 볼 수 없는 경우 명의개서 직전에 작성된 주주명부가 존재하고, 그 주주명부의 기재가 적법하게 이루어진 것으로 볼 수 있다면 그 주주명부상 주주가 회사에 대한 관계에서 주주권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"주주명부, 명의개서"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-4","t":"주주명부에 기재를 마치지 않고도 회사에 대한 관계에서 주주권을 행사할 수 있는 경우는 주주명부에의 기재 또는 명의개서 청구가 부당하게 지연되거나 거절되었다는 등의 극히 예외적인 사정이 인정되는 경우에 한한다.","ox":"O","m":"④","c":"A","tp":"주주명부, 명의개서"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-5","t":"회사는 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았다면 주주명부상 주주의 주주권 행사를 부인할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"주주명부, 명의개서"}],"15":[{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-1","t":"자본금의 감소는 정관변경사항은 아니지만 채권자와 주주의 권리 보호를 위해 그 요건을 엄격히 하여 어느 경우에나 정관변경에 준하는 특별결의를 필요로 하므로 출석한 주주의 의결권의 3분의 2 이상의 수와 발행주식총수의 3분의 1 이상의 수로써 하여야 한다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 자본금 감소"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-2","t":"주식을 병합할 경우에는 회사는 1월 이상의 기간을 정하여 그 뜻과 그 기간 내에 주권을 회사에 제출할 것을 공고하고 주주명부에 기재된 주주와 질권자에 대하여는 각별로 그 통지를 하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 자본금 감소"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-3","t":"회사가 특정 주식의 소각에 관하여 주주의 동의를 얻고 그 주식을 자기주식으로서 취득하여 소각하는 이른바 주식의 임의소각에 있어서는, 회사가 그 주식을 취득하고 상법 소정의 자본감소의 절차뿐만 아니라 주식실효 절차까지 마친 때에 소각의 효력이 생긴다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 자본금 감소"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-4","t":"1인 회사에 있어서 주식병합에 관한 주주총회의 결의를 거친 경우에는 그 결의에 따라 변경등기가 경료되었다면 공고 등의 절차를 거치지 않았다고 하더라도 그 변경등기 무렵에 주식병합의 효력이 발생한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 자본금 감소"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-5","t":"주주총회의 자본감소 결의에 취소 또는 무효의 하자가 있다고 하더라도 그 하자가 극히 중대하여 자본감소가 존재하지 아니하는 정도에 이르는 등의 특별한 사정이 없는 한 자본감소의 효력이 발생한 후에는 자본감소 무효의 소에 의해서만 다툴 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 자본금 감소"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50-1","t":"전환사채와 신주인수권부사채는 모두 상법상의 특수사채로, 회사로 하여금 보통의 사채보다 유리한 모집조건으로 사채를 모집할 수 있게 하여 회사의 자금조달을 원활하게 하는 기능이 있다.","ox":"O","m":"①","c":"A","tp":"주식회사의 전환사채와 신주인수권부사채"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50-2","t":"사채권자의 전환권과 신주인수권은 형성권이므로, 원칙적으로 신주의 효력발생시기는 전환사채의 경우 사채권자가 회사에 전환을 청구한 때이고, 신주인수권부사채의 경우 사채권자가 회사에 신주인수권을 행사한 때이다.","ox":"X","m":"②","c":"A","tp":"주식회사의 전환사채와 신주인수권부사채"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50-3","t":"신주의 발행가액총액은 전환사채의 경우 전환사채의 발행가액총액과 같아야 하지만, 신주인수권부사채의 경우 신주인수권부사채의 금액을 초과하지 않는 범위 내에서 조정이 가능하다.","ox":"O","m":"③","c":"A","tp":"주식회사의 전환사채와 신주인수권부사채"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50-4","t":"전환사채 발행의 경우에도 신주발행무효의 소에 관한 상법 제429조가 유추적용되므로 전환사채발행무효 확인의 소에 있어서도 상법 제429조 소정의 6월의 제소기간의 제한이 적용된다.","ox":"O","m":"④","c":"A","tp":"주식회사의 전환사채와 신주인수권부사채"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50-5","t":"회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 신주인수권부사채를 발행함으로써 주주가 불이익을 받을 염려가 있는 경우에는 그 주주는 회사에 대하여 그 발행을 유지(留止)할 것을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 전환사채와 신주인수권부사채"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-1","t":"신주발행의 무효는 주주ㆍ이사 또는 감사에 한하여 신주를 발행한 날부터 6월내에 소만으로 주장할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-2","t":"신주발행무효의 소에서 신주를 발행한 날부터 6월의 출소기간이 경과한 후에도 새로운 무효사유를 추가하여 주장할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-3","t":"신주 등의 발행에서 주주배정방식과 제3자배정방식을 구별하는 기준은 회사가 신주 등을 발행하면서 주주들에게 그들의 지분비율에 따라 신주 등을 우선적으로 인수할 기회를 부여하였는지 여부에 따라 객관적으로 결정되어야 한다.","ox":"O","m":"③","c":"A","tp":"신주발행"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-4","t":"회사가 주주배정방식에 의하여 신주를 발행하려는데 주주가 인수를 포기하거나 청약을 하지 아니함으로써 그 인수권을 잃은 때에는 회사는 이사회 결의로 인수가 없는 부분에 대하여 자유로이 이를 제3자에게 처분할 수 있다.","ox":"O","m":"④","c":"A","tp":"신주발행"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-5","t":"신주발행무효의 소 계속 중 그 원고 적격의 근거가 되는 주식이 양도된 경우에 그 양수인은 제소기간 등의 요건이 충족된다면 새로운 주주의 지위에서 신소를 제기할 수 있을 뿐만 아니라, 양도인이 이미 제기한 기존의 위 소송을 적법하게 승계할 수도 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-1","t":"발행주식의 총수의 100분의 3 이상에 해당하는 주식을 가진 주주는 이유를 붙인 서면으로 회계의 장부와 서류의 열람 또는 등사를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 주주의 회계장부열람ㆍ등사청구권"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-2","t":"자회사의 회계장부라도 모자관계에 있는 모회사에 보관되어 있고, 모회사의 회계상황을 파악하기 위한 근거자료로서 실질적으로 필요한 경우에는 모회사의 회계서류로서 모회사 주주의 회계장부열람 또는 등사청구의 대상이 될 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 주주의 회계장부열람ㆍ등사청구권"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-3","t":"주주의 회계장부열람ㆍ등사청구권이 인정되는 경우라도 그 횟수는 1회로 국한되는 등 사전에 제한되어야 한다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사 주주의 회계장부열람ㆍ등사청구권"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-4","t":"회사는 주주의 회계장부열람ㆍ등사청구가 있는 경우 그 청구가 부당함을 증명하여 이를 거부할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 주주의 회계장부열람ㆍ등사청구권"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-5","t":"주주의 회계장부열람ㆍ등사권 행사가 회사업무의 운영 또는 주주 공동의 이익을 해치거나 주주가 회사의 경쟁자로서 취득한 정보를 경업에 이용할 우려가 있거나 또는 회사에 지나치게 불리한 시기를 택하여 행사하는 경우 등에는 정당한 목적을 결하여 부당하다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사 주주의 회계장부열람ㆍ등사청구권"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-1","t":"회사설립과 달리 신주발행에서는 납입이 이루어지지 않는 경우 따로 실권절차를 두지 않고 바로 실권시킨다.","ox":"O","m":"①","c":"A","tp":"상법상 신주발행"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-2","t":"신주발행에서 이사의 담보책임은 인수담보책임에 국한된다.","ox":"O","m":"②","c":"A","tp":"상법상 신주발행"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-3","t":"추상적 신주인수권(신주의 배정을 받을 권리)은 원칙적으로 지분비례에 따라 주주에게 귀속된다.","ox":"O","m":"③","c":"A","tp":"상법상 신주발행"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-4","t":"회사는 정관에 정하는 바에 따라 경영권방어를 위해 주주 외의 자에게 신주를 배정할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 신주발행"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-5","t":"회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 주식을 발행함으로써 주주가 불이익을 받을 염려가 있는 경우에는 그 주주는 회사에 대하여 그 발행을 유지할 것을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 신주발행"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-1","t":"발행주식의 총수의 100분의 3 이상에 해당하는 주식을 가진 주주는 이유를 붙인 서면으로 회계의 장부와 서류의 열람 또는 등사를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"주주의 회계장부열람권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-2","t":"회사는 주주의 회계 장부와 서류 열람 등 청구가 부당함을 증명하여 이를 거부할 수 있고, 주주의 열람·등사권 행사가 부당한 것인지는 행사에 이르게 된 경위, 행사의 목적, 악의성 유무 등 제반 사정을 종합적으로 고려하여 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"주주의 회계장부열람권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-3","t":"주식매수청구권을 행사한 주주도 회사로부터 주식의 매매대금을 지급받지 아니하고 있는 동안에는 주주로서의 지위를 여전히 가지고 있으므로 특별한 사정이 없는 한 주주로서의 권리를 행사하기 위하여 필요한 경우에는 위와 같은 회계장부열람·등사권을 가진다.","ox":"O","m":"③","c":"A","tp":"주주의 회계장부열람권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-4","t":"주주가 주식의 매수가액을 결정하기 위한 경우뿐만 아니라 회사의 이사에 대하여 대표소송을 통한 책임추궁이나 유지청구, 해임청구를 하는 등 주주로서의 권리를 행사하기 위하여 필요하다고 인정되는 경우에는 특별한 사정이 없는 한 그 청구는 회사의 경영을 감독하여 회사와 주주의 이익을 보호하기 위한 것이므로, 주식매수청구권을 행사하였다는 사정만으로 청구가 정당한 목적을 결하여 부당한 것이라고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"주주의 회계장부열람권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-5","t":"발행주식 총수의 100분의 3 이상에 해당하는 주식을 가진 상태에서 회계 장부와 서류 열람 등을 재판상으로 청구하였다면, 이후 소송계속 도중에 보유한 주식의 수가 발행주식 총수의 100분의 3 미만으로 되었다 하더라도 회계장부의 열람·등사를 구할 당사자적격을 상실하지 아니한다.","ox":"X","m":"⑤","c":"A","tp":"주주의 회계장부열람권"},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26-1","t":"회사의 회계는 상법과 상법 시행령으로 규정한 것을 제외하고는 일반적으로 공정하고 타당한 회계관행에 따른다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 회계"},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26-2","t":"배당금의 지급청구권은 5년간 이를 행사하지 아니하면 소멸시효가 완성한다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 회계"},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26-3","t":"주식에 의한 배당은 이익배당총액의 2분의 1에 상당하는 금액을 초과하지 못한다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 회계"},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26-4","t":"발행주식의 총수의 100분의 3 이상에 해당하는 주식을 가진 주주는 이유를 붙인 서면으로 회계의 장부와 서류의 열람 또는 등사를 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 회계"},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26-5","t":"대주주에게는 30%, 소수주주에게는 33%의 이익배당을 하기로 하는 주주총회의 결의는, 이익배당이 각 주주가 가진 주식의 수에 따라야 한다는 상법 제464조에 반하여 위법하다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사의 회계"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-1","t":"상법 제418조 제1항, 제2항의 규정은 회사가 신주를 발행하는 경우 원칙적으로 기존 주주에게 이를 배정하고 정관에 정한 경우에만 제3자에게 신주배정을 할 수 있게 하면서 그 사유도 신기술의 도입이나 재무구조의 개선 등 경영상 목적을 달성하기 위하여 필요한 경우에 한정함으로써 기존 주주의 신주인수권을 보호하고 있다. 따라서 회사가 위와 같은 사유가 없음에도 경영권 분쟁이 현실화된 상황에서 경영진의 경영권이나 지배권 방어라는 목적을 달성하기 위하여 제3자에게 신주를 배정하는 것은 상법 제418조 제2항을 위반하여 주주의 신주인수권을 침해하는 것이다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 신주발행 등"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-2","t":"신주발행무효의 소에서 신주를 발행한 날부터 6월의 출소기간이 경과한 후에는 새로운 무효사유를 추가하여 주장할 수 없다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사의 신주발행 등"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-3","t":"회사가 주주배정방식에 의하여 신주를 발행하려는데 주주가 인수를 포기하거나 청약을 하지 아니함으로써 그 인수권을 잃은 때에는 회사는 이사회 결의로 인수가 없는 부분에 대하여 자유로이 이를 제3자에게 처분할 수 있고, 이 경우 실권된 신주를 제3자에게 발행하는 것에 관하여 정관에 반드시 근거 규정이 있어야 하는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 신주발행 등"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-4","t":"신주발행 무효원인은 가급적 엄격하게 해석하여야 하고, 따라서 법령이나 정관의 중대한 위반 또는 현저한 불공정이 있어 그것이 주식회사의 본질이나 회사법의 기본원칙에 반하거나 기존 주주들의 이익과 회사의 경영권 내지 지배권에 중대한 영향을 미치는 경우로서 신주와 관련된 거래의 안전, 주주 기타 이해관계인의 이익 등을 고려하더라도 도저히 묵과할 수 없는 정도라고 평가되는 경우에 한하여 신주의 발행을 무효로 할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 신주발행 등"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-5","t":"신주인수권부사채 발행의 경우에도 신주발행무효의 소에 관한 상법 제429조가 유추적용되나, 전환사채는 장차 주식으로 전환될 권리가 부여되었을 뿐이므로 전환사채 발행의 경우에는 신주발행무효의 소에 관한 상법 제429조가 유추적용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사의 신주발행 등"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29-1","t":"상법상 전환사채의 발행 무효의 주장 방법으로 전환사채발행 무효의 소가 명문으로 인정되고 그 구체적인 내용에 관하여는 신주발행 무효의 소에 관한 규정을 준용하고 있다.","ox":"X","m":"①","c":"A","tp":"상법상 전환사채발행의 하자"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29-2","t":"전환사채발행무효 확인의 소에 있어서도 신주발행무효의 소와 마찬가지로 6월의 제소기간의 제한이 적용된다.","ox":"O","m":"②","c":"A","tp":"상법상 전환사채발행의 하자"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29-3","t":"전환사채발행무효 확인의 소에 있어서 전환사채를 발행한 날로부터 6월의 출소기간이 경과한 후에는 새로운 무효사유를 추가할 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 전환사채발행의 하자"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29-4","t":"전환사채 인수인이 회사의 지배주주와 특별한 관계에 있는 자라거나 그 전환가액이 발행시점의 주가 등에 비추어 다소 낮은 가격이라는 사유는 일반적으로 이미 발행된 전환사채를 무효화할 만한 원인이 되지 못한다.","ox":"O","m":"④","c":"A","tp":"상법상 전환사채발행의 하자"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29-5","t":"전환사채발행부존재 확인의 소도 인정되고 이 경우 6월의 제소기간 제한은 적용되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"상법상 전환사채발행의 하자"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-1","t":"발행주식 총수의 100분의 3 이상에 해당하는 주식을 가진 상태에서 회계장부와 서류 열람 등을 재판상으로 청구하였더라도 소송계속 중 신주발행 등으로 위 요건에 미달하게 된 경우에는 당사자적격이 상실된다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사 주주의 회계장부 및 주주명부 열람·등사청구"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-2","t":"주식매수청구권을 행사한 주주도 회사로부터 아직 대금을 지급받지 않고 있다면 여전히 주주로서의 지위를 가지므로 주주권 행사에 필요하다면 회계장부의 열람·등사를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"상법상 주식회사 주주의 회계장부 및 주주명부 열람·등사청구"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-3","t":"주주가 열람·등사를 청구하기 위해서는 이유를 붙인 서면을 미리 회사에 제출하여야 하고, 구두에 의한 청구나 이유를 기재하지 않은 청구는 효력이 없다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사 주주의 회계장부 및 주주명부 열람·등사청구"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-4","t":"회사는 주주의 회계장부 열람·등사청구가 부당함을 입증하여 이를 거부할 수 있고, 주주명부에 대한 열람·등사청구에 대하여도 그 청구에 정당한 목적이 없음을 입증하여 거부할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사 주주의 회계장부 및 주주명부 열람·등사청구"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-5","t":"회계장부의 열람·등사청구권을 피보전권리로 한 당해 회계장부의 열람·등사를 명하는 가처분은 사실상 본안소송의 목적을 완전히 달성하게 되는 결과가 되므로 허용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식회사 주주의 회계장부 및 주주명부 열람·등사청구"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-1","t":"이익배당을 할 수 있는 금액을 계산할 때에는 대통령령으로 정하는 미실현이익을 공제하지 않는다.","ox":"X","m":"①","c":"A","tp":"상법상 주식회사의 배당"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-2","t":"이익배당의 의사결정은 주주총회의 결의로만 정할 수 있다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사의 배당"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-3","t":"배당가능이익에 관한 제한을 위반하여 이익을 배당한 경우에도 무효라고 할 수는 없으므로 회사채권자는 배당한 이익을 회사에 반환할 것을 청구할 수는 없다.","ox":"X","m":"③","c":"A","tp":"상법상 주식회사의 배당"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-4","t":"이익의 배당은 새로이 발행하는 주식으로써 할 수도 있고 그 경우 이익배당총액 상당까지 할 수 있다.","ox":"X","m":"④","c":"A","tp":"상법상 주식회사의 배당"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-5","t":"주식배당의 의사결정은 주주총회의 결의로만 정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 배당"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-1","t":"주주외의 자에 대하여 신주인수권부사채를 발행하는 경우에 그 발행할 수 있는 신주인수권부사채의 액, 신주인수권의 내용과 신주인수권을 행사할 수 있는 기간에 관하여 정관에 규정이 없으면 주주총회에서 출석한 주주의 의결권의 3분의 2이상의 수와 발행주식총수의 3분의 1이상의 수로써 이를 정하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-2","t":"상법의 규정에 따르면 주주외의 자에 대하여 신주인수권부사채를 발행하는 경우에 회사는 제516조 제2항에서 정한 신주인수권부사채에 관한 내용을 그 납입기일의 2주 전까지 주주에게 통지하거나 공고하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-3","t":"회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 신주인수권부사채를 발행함으로써 주주가 불이익을 받을 염려가 있는 경우에는 그 주주는 회사에 대하여 그 발행을 유지할 것을 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-4","t":"이사와 통모하여 현저하게 불공정한 발행가액으로 신주인수권부사채를 인수한 자는 회사에 대하여 공정한 발행가액과의 차액에 상당한 금액을 지급할 의무가 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-5","t":"신주인수권부사채 발행의 무효는 주주ㆍ이사 또는 감사에 한하여 신주인수권부사채를 발행한 날로부터 6월내에 소만으로 이를 주장할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-1","t":"전환사채 발행일로부터 6월내에 전환사채발행무효의 소가 제기되지 않거나 6월내에 제기된 전환사채발행무효의 소가 적극적 당사자의 패소로 확정되었다면, 이후에는 더 이상 전환사채 발행의 무효를 주장할 수 없으나, 전환권의 행사로 인한 신주 발행에 대해서는 상법 제429조를 적용하여 신주발행무효의 소로써 다툴 수 있다. 이때 신주발행무효의 소의 제소기간은 신주 발행일로부터 기산하여야 하고, 전환사채 발행일부터 기산되는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-2","t":"전환사채 발행의 실체가 없음에도 전환사채 발행의 등기가 되어 있는 외관이 존재하는 경우 이를 제거하기 위한 전환사채발행부존재 확인의 소에 있어서는 상법 제429조에 따른 6월의 제소기간의 제한이 적용된다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-3","t":"전환사채발행유지 청구는 회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 전환사채를 발행함으로써 주주가 불이익을 받을 염려가 있는 경우에 회사에 대하여 그 발행의 유지를 청구하는 것으로서, 전환사채 발행의 효력이 생기기 전, 즉 전환사채의 납입기일까지 이를 행사하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-4","t":"전환사채권자가 전환 청구를 한 이후에는 주식전환의 금지를 구할 법률상 이익이 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-5","t":"회사가 경영상 목적 없이 대주주 등의 경영권이나 지배권 방어 목적으로 제3자에게 전환사채를 발행하였다면 전환사채의 발행은 무효가 될 수 있고, 전환사채 발행일로부터 6월 내에 위와 같은 사유를 들어 전환사채발행무효의 소로써 다툴 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-1","t":"신주발행무효의 소에서 신주를 발행한 날부터 6월의 출소기간이 경과한 후에는 새로운 무효사유를 추가하여 주장할 수 없다.","ox":"O","m":"①","c":"A","tp":"주식회사의 신주발행"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-2","t":"주식회사가 회사의 경영권 분쟁이 현실화된 상황에서 대주주나 경영진 등의 경영권이나 지배권 방어라는 목적을 달성하기 위하여 제3자에게 신주를 배정하는 것은 상법 제418조 제2항을 위반하여 주주의 신주인수권을 침해하는 것이고, 그로 인하여 회사의 지배구조에 심대한 변화가 초래되고 기존 주주들의 회사에 대한 지배권이 현저하게 약화되는 중대한 결과가 발생하는 경우에는 그러한 신주 발행은 무효이다.","ox":"O","m":"②","c":"A","tp":"주식회사의 신주발행"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-3","t":"신주 등의 발행에서 주주배정방식과 제3자배정방식을 구별하는 기준은 회사가 신주 등을 발행하면서 주주들에게 그들의 지분비율에 따라 신주 등을 우선적으로 인수할 기회를 부여하였는지 여부에 따라 객관적으로 결정되어야 하고, 신주 등의 인수권을 부여받은 주주들이 실제로 인수권을 행사함으로써 신주 등을 배정받았는지 여부에 좌우되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"주식회사의 신주발행"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-4","t":"회사가 주주배정방식에 의하여 신주를 발행하려는데 주주가 인수를 포기하거나 청약을 하지 아니함으로써 그 인수권을 잃은 때에는 회사가 이사회 결의로 인수가 없는 부분을 제3자에게 처분할 수 있으나, 이 경우에도 실권된 신주를 제3자에게 발행하는 것에 관하여 정관에 반드시 근거 규정 자체는 있어야 한다.","ox":"X","m":"④","c":"A","tp":"주식회사의 신주발행"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-5","t":"주식회사가 액면미달의 가액으로 주식을 발행하기 위해서는 설립등기를 마친 날로부터 2년이 경과한 후여야 하고, 반드시 주식의 최저발행가액을 정한 주주총회의 특별결의와 법원의 인가가 있어야 한다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 신주발행"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-1","t":"회사는 상법 제464조에 따른 이익배당을 원칙적으로 이익배당을 결의한 주주총회나 이사회의 결의를 한 날로부터 1개월 내에 하여야 하고, 주주의 배당금지급청구권은 5년간 이를 행사하지 아니하면 소멸시효가 완성된다.","ox":"O","m":"①","c":"A","tp":"주주의 이익배당청구권"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-2","t":"이익잉여금처분계산서가 주주총회에서 승인됨으로써 이익배당이 확정될 때까지는 주주에게 구체적이고 확정적인 배당금지급청구권이 인정되지 아니한다.","ox":"O","m":"②","c":"A","tp":"주주의 이익배당청구권"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-3","t":"정관에서 회사에 배당의무를 부과하면서 배당금의 지급조건이나 배당금액을 산정하는 방식 등을 구체적으로 정하고 있어 그에 따라 개별 주주에게 배당할 금액이 일의적으로 산정되고, 대표이사나 이사회가 경영판단에 따라 배당금 지급 여부나 시기, 배당금액 등을 달리 정할 수 있도록 하는 규정이 없다면, 정관에서 정한 지급조건이 갖추어지는 때에 주주에게 구체적이고 확정적인 배당금지급청구권이 인정될 수 있다. 이러한 경우 회사는 주주총회에서 이익배당에 관한 결의가 이루어지지 않았더라도 주주에게 이익배당금의 지급을 거절할 수 없다.","ox":"O","m":"③","c":"A","tp":"주주의 이익배당청구권"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-4","t":"상법 제467조의2 제1항은 “회사는 누구에게든지 주주의 권리행사와 관련하여 재산상의 이익을 공여할 수 없다.”라고 규정하고 있는데, 위 규정에서 정한 ‘주주의 권리’에 주주총회에서의 의결권, 대표소송 제기권, 주주총회결의에 관한 각종 소권 등과 같은 공익권은 포함되나, 이익배당청구권, 잔여재산분배청구권, 신주인수권 등과 같은 자익권은 포함되지 않는다.","ox":"X","m":"④","c":"A","tp":"주주의 이익배당청구권"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-5","t":"주주총회에서 특정 주주를 제외한 나머지 주주들에 대하여만 배당금을 지급하기로 하는 내용으로 이익배당 결의가 이루어졌을 경우 그와 같은 결의는 주주평등의 원칙에 반하는 것으로서 무효이다. 이 경우 이익배당에서 제외된 주주가 주주평등의 원칙을 내세워 회사를 상대로 다른 주주에게 지급된 이익배당금과 동일한 비율로 계산된 이익배당금의 지급을 구할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"주주의 이익배당청구권"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34-1","t":"회계장부의 열람 또는 등사를 청구할 수 있는 자는 발행주식총수의 100분의 3 이상에 해당하는 주식을 가진 주주이다.","ox":"O","m":"①","c":"A","tp":"주주의 회계장부 등"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34-2","t":"회계장부열람·등사권은 이유를 붙인 서면에 의해 행사되어야 하고, 그 서면에는 특별한 사정이 없는 한 열람·등사청구를 하는 이유를 뒷받침하는 자료가 첨부되어야 한다.","ox":"X","m":"②","c":"A","tp":"주주의 회계장부 등"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34-3","t":"주식매수청구권을 행사한 주주도 회사로부터 주식의 매매대금을 지급받지 아니하고 있는 동안에는 특별한 사정이 없는 한 주주로서의 권리를 행사하기 위하여 필요한 경우에는 회계장부열람·등사권을 가진다.","ox":"O","m":"③","c":"A","tp":"주주의 회계장부 등"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34-4","t":"회계장부 열람·등사청구의 대상이 되는 ‘회계의 장부 및 서류’는 소수주주가 열람·등사를 구하는 이유와 실질적으로 관련이 있는 회계장부와 그 근거자료가 되는 회계서류이다.","ox":"O","m":"④","c":"A","tp":"주주의 회계장부 등"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34-5","t":"열람·등사제공의무를 부담하는 회사의 출자 또는 투자로 성립한 자회사의 회계장부가 모회사에 보관되어 있고, 모회사의 회계상황을 파악하기 위한 근거자료로서 실질적으로 필요한 경우에는 모회사 소수주주의 열람·등사청구의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주주의 회계장부 등"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-1","t":"연 2회 이상의 결산기를 정한 회사는 상법 제462조의3에 따른 중간배당을 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-2","t":"중간배당에 관한 이사회의 결의가 있는 경우, 같은 영업연도 중 다시 중간배당에 관한 이사회 결의를 하는 것은 허용되지 않으나, 같은 영업연도 중이라도 중간배당 지급청구권의 내용을 수정하는 이사회 결의는 허용된다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-3","t":"배당가능이익이 없는데도 중간배당이 실시된 경우, 위법배당에 따른 부당이득반환청구권은 민법 제162조 제1항이 적용되어 10년의 민사소멸시효에 걸린다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-4","t":"상법 제462조의3에 따른 중간배당의 횟수는 영업연도 중 1회로 제한된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-5","t":"당해 결산기 대차대조표상의 순자산액이 상법 제462조 제1항에 규정된 이익배당의 법정한도에 미치지 못함에도 불구하고 중간배당을 한 경우 이사는 회사에 대하여 연대하여 그 차액(배당액이 그 차액보다 적을 경우에는 배당액)을 배상할 책임이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25-1","t":"주식병합을 통한 자본금 감소에 이의가 있는 주주ㆍ이사ㆍ감사ㆍ청산인ㆍ파산관재인 또는 자본금의 감소를 승인하지 않은 채권자는 자본금감소로 인한 변경등기가 된 날부터 6개월 내에 감자무효의 소를 제기할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25-2","t":"주주총회의 자본금 감소 결의에 취소 또는 무효의 하자가 있다고 하더라도 그 하자가 극히 중대하여 자본감소가 존재하지 아니하는 정도에 이르는 등의 특별한 사정이 없는 한 자본감소의 효력이 발생한 후에는 감자무효의 소에 의해서만 다툴 수 있다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25-3","t":"상법은 자본금 감소의 무효와 관련하여 개별적인 무효사유를 열거하고 있지 않으므로, 자본금 감소의 방법 또는 기타 절차가 주주평등의 원칙에 반하는 경우, 기타 법령ㆍ정관에 위반하거나 민법상 일반원칙인 신의성실의 원칙에 반하여 현저히 불공정한 경우에 무효소송을 제기할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25-4","t":"만일 주주의 주식수에 따라 다른 비율로 주식병합을 하여 차등감자가 이루어진다면 이는 주주평등의 원칙에 반하여 자본금 감소 무효의 원인이 될 수 있다. 또한 주식병합을 통한 자본금 감소가 현저하게 불공정하게 이루어져 권리남용금지의 원칙이나 신의성실의 원칙에 반하는 경우에도 자본금 감소 무효의 원인이 될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25-5","t":"자본금 감소를 위한 주식소각 절차에 하자가 있다면, 주주 등은 자본금 감소로 인한 변경등기가 된 날부터 6개월 내에 소로써만 무효를 주장할 수 있으므로, 이사가 주식소각 과정에서 법령을 위반하여 회사에 손해를 끼친 사실이 인정될 때에는 감자무효의 판결이 확정되어야 상법 제399조 제1항에 따라 회사에 대하여 손해배상책임을 부담한다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44-1","t":"발행할 신주의 종류와 수에 관하여 정관에 규정이 없는 경우 이사회에서 이를 결정한다.","ox":"O","m":"①","c":"A","tp":"비상장 주식회사의 신주발행"},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44-2","t":"신주의 인수인이 납입기일에 납입 또는 현물출자를 이행하지 아니한 때에는 그 권리를 잃는다.","ox":"O","m":"②","c":"A","tp":"비상장 주식회사의 신주발행"},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44-3","t":"신주의 인수인이 납입 또는 현물출자의 이행을 한 경우 주권을 교부받은 날부터 주주의 권리의무가 있다.","ox":"X","m":"③","c":"A","tp":"비상장 주식회사의 신주발행"},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44-4","t":"신주인수권증서를 상실한 자는 주식청약서에 의하여 주식의 청약을 할 수 있지만 그 청약은 신주인수권증서에 의한 청약이 있는 때에는 그 효력을 잃는다.","ox":"O","m":"④","c":"A","tp":"비상장 주식회사의 신주발행"},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44-5","t":"신주인수권증서가 발행되지 아니한 경우 신주인수권 양도의 제3자에 대한 대항요건으로는 지명채권의 양도와 마찬가지로 확정일자 있는 증서에 의한 양도통지 또는 회사의 승낙이라고 보는 것이 상당하다.","ox":"O","m":"⑤","c":"A","tp":"비상장 주식회사의 신주발행"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-1","t":"신주의 발행과 관련하여 특별법에서 달리 정한 경우를 제외하고 신주의 발행은 상법이 정하는 방법 및 절차에 의하여만 가능하다는 점에 비추어 볼 때, 상법이 정하고 있지 않은 전환권 부여조항은 효력이 없다.","ox":"O","m":"①","c":"A","tp":"전환사채"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-2","t":"전환사채는 전환권의 행사에 의하여 장차 주식으로 전환될 수 있는 권리가 부여된 사채로서 전환사채의 발행은 주식회사의 물적 기초와 기존 주주들의 이해관계에 영향을 미친다는 점에서 사실상 신주를 발행하는 것과 유사하므로 전환사채 발행의 경우에도 신주발행무효의 소에 관한 상법 제429조가 유추적용된다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-3","t":"전환사채 발행의 실체가 없음에도 전환사채 발행의 등기가 되어 있는 외관이 존재하는 경우 이를 제거하기 위하여 전환사채발행부존재 확인의 소를 제기할 수 있으므로 상법 제429조 소정의 6월의 제소기간의 제한이 적용된다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-4","t":"전환사채발행유지청구는 회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 전환사채를 발행함으로써 주주가 불이익을 받을 염려가 있는 경우에 회사에 대하여 그 발행의 유지를 청구하는 것으로서, 전환사채 발행의 효력이 생기기 전, 즉 전환사채의 납입기일까지 이를 행사하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-5","t":"전환사채권자가 전환청구를 하면 회사는 주식을 발행해 주어야 하는데, 전환권은 형성권이므로 전환을 청구한 때에 당연히 전환의 효력이 발생하여 전환사채권자는 그때부터 주주가 되고 사채권자로서의 지위를 상실하게 되므로 그 이후에는 주식전환의 금지를 구할 법률상 이익이 없게 된다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-1","t":"흡수합병 시 존속회사가 발행하는 합병신주를 소멸회사의 주주에게 배정·교부함에 있어서 적용할 합병비율을 정하는 것은 합병계약의 가장 중요한 내용이므로, 비상장법인 간 흡수합병의 경우 소멸회사의 주주인 회사의 이사로서는 합병비율이 합병할 각 회사의 재산 상태와 그에 따른 주식의 실제적 가치에 비추어 공정하게 정하여졌는지를 판단하여 회사가 합병에 동의할 것인지를 결정하여야 한다.","ox":"O","m":"①","c":"A","tp":"주식회사의 합병과 사채"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-2","t":"비상장법인 간 합병의 경우 법률에서 합병비율의 산정방법에 관하여 구체적으로 정하고 있으므로 이에 따라야 하는 것이지, 자산가치 이외에 시장가치, 수익가치, 상대가치 등의 다양한 요소를 고려하여 결정할 것은 아니다.","ox":"X","m":"②","c":"A","tp":"주식회사의 합병과 사채"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-3","t":"신주인수권부사채는 미리 확정된 가액으로 일정한 수의 신주 인수를 청구할 수 있는 신주인수권이 부여된 사채로서, 신주인수권부사채 발행의 경우에도 주식회사의 물적 기초와 기존 주주들의 이해관계에 영향을 미친다는 점에서 사실상 신주를 발행하는 것과 유사하므로, 신주발행무효의 소에 관한 상법 제429조가 유추적용된다.","ox":"O","m":"③","c":"A","tp":"주식회사의 합병과 사채"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-4","t":"주식회사가 신주를 발행할 때 회사의 경영상 목적을 달성하기 위하여 필요한 범위 안에서 정관이 정한 사유가 없는데도, 회사의 경영권 분쟁이 현실화된 상황에서 대주주나 경영진 등의 경영권이나 지배권 방어라는 목적을 달성하기 위하여 제3자에게 신주를 배정하는 것은 상법 제418조 제2항을 위반하여 주주의 신주인수권을 침해하는 것이고, 그로 인하여 회사의 지배구조에 심대한 변화가 초래되고 기존 주주들의 회사에 대한 지배권이 현저하게 약화되는 중대한 결과가 발생하는 경우에는 그러한 신주 발행은 무효이다. 이러한 법리는 신주인수권부사채를 제3자에게 발행하는 경우에도 마찬가지로 적용된다.","ox":"O","m":"④","c":"A","tp":"주식회사의 합병과 사채"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-5","t":"전환사채의 발행의 경우에도 신주발행무효의 소에 관한 상법 제429조가 유추적용된다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 합병과 사채"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-1","t":"주주 또는 회사채권자가 상법 제396조 제2항에 의하여 주주명부 등의 열람·등사청구를 한 경우 회사는 그 청구에 정당한 목적이 없는 등의 특별한 사정이 없는 한 이를 거절할 수 없고, 이 경우 정당한 목적이 없다는 점에 관한 증명책임은 회사가 부담한다.","ox":"O","m":"①","c":"A","tp":"주주의 열람⋅등사권"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-2","t":"상법 제466조 제1항에 따른 주주의 회계장부와 서류 등에 대한 열람·등사청구가 있는 경우 회사는 청구가 부당함을 증명하여 이를 거부할 수 있는데, 특히 회사업무의 운영 또는 주주 공동의 이익을 해치거나 주주가 회사의 경쟁자로서 취득한 정보를 경업에 이용할 우려가 있거나, 또는 회사에 지나치게 불리한 시기를 택하여 행사하는 경우 등에는 정당한 목적을 결하여 부당한 것이라고 보아야 한다.","ox":"O","m":"②","c":"A","tp":"주주의 열람⋅등사권"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-3","t":"주주는 회사를 상대로 상법 제396조 제2항에 따라 주주명부 열람·등사를 청구할 수 있고, 회사의 이행보조자 또는 수임인인 명의개서대리인에게도 직접 주주명부 열람·등사를 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"주주의 열람⋅등사권"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-4","t":"상법 제466조 제1항에 따른 회계장부 열람·등사를 청구하는 주주가 제출하는 열람·등사청구서에 붙인 ‘이유’는 회사가 열람·등사에 응할 의무의 존부를 판단하거나 열람·등사에 제공할 회계장부와 서류의 범위 등을 확인할 수 있을 정도로 열람·등사청구권 행사에 이르게 된 경위와 행사의 목적 등이 구체적으로 기재되면 충분하고, 더 나아가 그 이유가 사실일지도 모른다는 합리적 의심이 생기게 할 정도로 기재하거나 그 이유를 뒷받침하는 자료를 첨부할 필요는 없다.","ox":"O","m":"④","c":"A","tp":"주주의 열람⋅등사권"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-5","t":"모색적 증거 수집을 위한 열람·등사청구는 허용될 수 없으나, 열람·등사청구권이 기본적으로 회사의 업무 등에 관한 정보가 부족한 주주에게 필요한 정보 획득과 자료 수집을 위한 기회를 부여하는 것이라는 사정을 고려할 때 모색적 증거 수집에 해당하는지는 신중하고 엄격하게 판단해야 한다.","ox":"O","m":"⑤","c":"A","tp":"주주의 열람⋅등사권"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-1","t":"회사는 이사회의 결의에 의하여 사채를 발행할 수 있는데, 정관으로 정하는 바에 따라 이사회는 대표이사에게 사채의 금액 및 종류를 정하여 1년을 초과하지 아니하는 기간 내에 사채를 발행할 것을 위임할 수도 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-2","t":"채권을 기명식 또는 무기명식에 한할 것으로 정한 경우가 아닌 한, 사채권자는 언제든지 기명식의 채권을 무기명식으로, 무기명식의 채권을 기명식으로 할 것을 회사에 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-3","t":"회사는 사채를 발행하는 경우에 사채관리회사를 정하여 변제의 수령, 채권의 보전, 그 밖에 사채의 관리를 위탁할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-4","t":"은행, 신탁회사, 그 밖에 대통령령으로 정하는 자가 아니면 사채관리회사가 될 수 없고, 사채의 인수인도 그 사채의 사채관리회사가 될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-5","t":"사채권자집회의 결의는 그 종류의 사채권자 전원이 동의한 결의에 해당하는지 여부를 불문하고, 법원의 인가를 받아야만 그 효력이 생긴다.","ox":"X","m":"⑤","c":"A"}],"16":[{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-1","t":"주식회사가 유한회사와 합병하는 경우 합병 후 존속하는 회사나 합병으로 설립되는 회사는 주식회사나 유한회사 모두 가능한데, 그 회사가 주식회사인 경우에는 법원의 인가를 얻어야 합병의 효력이 생긴다.","ox":"O","m":"①","c":"A","tp":"상법상 주식회사의 합병"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-2","t":"주식회사가 합병을 함에는 합병계약서를 작성하여 주주총회의 승인을 얻어야 하지만, 합병으로 인하여 소멸하는 회사의 총주주의 동의가 있거나 그 회사의 발행주식총수의 100분의 90 이상을 합병 후 존속하는 회사가 소유하고 있는 때에는 합병 후 존속하는 회사의 주주총회의 승인은 이사회의 승인으로 갈음할 수 있다.","ox":"X","m":"②","c":"A","tp":"상법상 주식회사의 합병"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-3","t":"합병 후 존속하는 회사가 합병으로 인하여 발행하는 신주 및 이전하는 자기주식의 총수가 그 회사의 발행주식총수의 100분의 10을 초과하지 아니하는 경우 존속하는 회사의 주주는 합병에 반대하더라도 주식매수청구권을 행사할 수 없다.","ox":"O","m":"③","c":"A","tp":"상법상 주식회사의 합병"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-4","t":"주식회사의 합병에서 존속하는 회사가 소멸하는 회사의 주주에게 제공하는 재산이 존속하는 회사의 모회사 주식을 포함하는 경우에는 존속하는 회사는 그 지급을 위하여 모회사의 주식을 취득할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 주식회사의 합병"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-5","t":"주식회사가 흡수합병을 한 때에는 합병 보고의 주주총회가 종결한 날 또는 보고에 갈음하는 공고일부터 본점소재지에서는 2주 내, 지점소재지에서는 3주 내에 합병 후 존속하는 회사에 있어서는 변경의 등기, 합병으로 인하여 소멸하는 회사에 있어서는 해산의 등기를 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식회사의 합병"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-1","t":"회사는 해산 이후에도 청산의 목적범위 내에서 법인격이 존속한다.","ox":"O","m":"①","c":"A","tp":"상법상 회사의 해산과 청산"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-2","t":"합명회사는 사원이 1인이 된 때, 합자회사는 무한책임사원 또는 유한책임사원의 전원이 퇴사한 때, 유한책임회사는 사원이 없게 된 때, 주식회사는 주주가 1인이 된 때 각 해산사유가 된다.","ox":"X","m":"②","c":"A","tp":"상법상 회사의 해산과 청산"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-3","t":"합명회사와 합자회사의 각 사원은 부득이한 사유가 있을 때 회사의 해산을 법원에 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"상법상 회사의 해산과 청산"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-4","t":"해산명령의 결정 또는 해산판결의 확정이 있는 때에는 회사는 청산절차를 밟아야 하고, 회사의 계속이 인정되지 아니한다.","ox":"O","m":"④","c":"A","tp":"상법상 회사의 해산과 청산"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-5","t":"주식회사의 청산인은 법원이 선임한 경우가 아니라면 언제든지 주주총회의 결의로 이를 해임할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 회사의 해산과 청산"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-1","t":"회사는 다른 회사의 무한책임사원이 되지 못한다.","ox":"O","m":"①","c":"A","tp":"상법상 회사"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-2","t":"합병을 하는 회사의 일방 또는 쌍방이 주식회사, 유한회사 또는 유한책임회사인 경우에는 합병 후 존속하는 회사나 합병으로 설립되는 회사는 주식회사, 유한회사 또는 유한책임회사이어야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 회사"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-3","t":"주식회사가 해산간주에 의하여 해산한 경우 언제든지 주주총회 특별결의로 회사를 계속할 수 있다.","ox":"X","m":"③","c":"A","tp":"상법상 회사"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-4","t":"합명회사가 총사원의 동의로 해산한 경우 사원의 전부 또는 일부의 동의로 회사를 계속할 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 회사"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-5","t":"이해관계인이 회사의 해산명령을 청구한 때에는 법원은 회사의 청구에 의하여 상당한 담보를 제공할 것을 명할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 회사"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46-1","t":"소규모합병의 경우 존속회사의 주주는 합병에 반대하더라도 주식매수청구권을 행사할 수 없다.","ox":"O","m":"①","c":"A","tp":"상법상 주식매수청구권"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46-2","t":"영업양도에 반대하는 주주가 주식매수청구권을 행사하면 회사의 승낙 여부와 상관없이 주주와 회사 사이에 매매계약이 체결된다.","ox":"O","m":"②","c":"A","tp":"상법상 주식매수청구권"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46-3","t":"의결권이 없는 종류주식을 보유한 주주는 영업양도에 반대하더라도 주식매수청구권을 행사할 수 없다.","ox":"X","m":"③","c":"A","tp":"상법상 주식매수청구권"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46-4","t":"영업양도에 반대하는 주주는 주주총회의 결의일부터 20일 이내에 회사에 대해 주식매수청구를 할 수 있고, 회사는 위 통지를 받으면 위 매수청구기간이 종료하는 날부터 2개월 이내에 그 주식을 매수해야 한다.","ox":"O","m":"④","c":"A","tp":"상법상 주식매수청구권"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46-5","t":"회사가 주식을 분할하기 위해 주주총회를 열어 이를 결의하는 경우, 주주가 주식 분할에 반대하더라도 주식매수청구권이 인정되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"상법상 주식매수청구권"},{"y":2019,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2019_25-46","t":"상법상 주식회사의 합병과 분할에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상법상 주식회사의 합병과 분할에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["합병비율이 현저하게 불공정한 경우 합병할 각 회사의 주주 등은 상법 제529조에 의하여 소로써 합병의 무효를 구할 수 있다.","채권자가 분할이 이루어진 후에 분할회사를 상대로 분할 전의 분할회사 채무에 관한 소를 제기하여 분할회사에 대한 관계에서 시효가 중단되거나 확정판결을 받아 소멸시효 기간이 연장되었다면, 그와 같은 소멸시효 중단이나 연장의 효과는 다른 채무자인 분할로 인하여 설립되는 회사 또는 존속하는 회사에 효력이 미친다.","합병할 회사의 일방이 합병후 존속하는 경우에 합병으로 인하여 소멸하는 회사의 총주주의 동의가 있거나 그 회사의 발행주식총수의 100분의 90이상을 합병후 존속하는 회사가 소유하고 있는 때에는 합병으로 인하여 소멸하는 회사의 주주총회의 승인은 이를 이사회의 승인으로 갈음할 수 있다.","합병을 하는 회사의 일방이 합병후 존속하는 경우에 존속하는 회사의 이사 및 감사로서 합병전에 취임한 자는 합병계약서에 다른 정함이 있는 경우를 제외하고는 합병후 최초로 도래하는 결산기의 정기총회가 종료하는 때에 퇴임한다.","회사의 합병은 합병후 존속하는 회사 또는 합병으로 인하여 설립되는 회사가 그 본점소재지에서 합병의 등기를 함으로써 그 효력이 생긴다. 22-10"],"a":2}},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-1","t":"회사의 채권자는 주식교환의 날로부터 6개월 내에 소만으로 주식교환의 무효를 주장할 수 있다.","ox":"X","m":"①","c":"A","tp":"상법상 주식의 포괄적 교환(이 문제에서‘주식교환’이라고 한다)"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-2","t":"주식교환에 의하여 완전자회사가 되는 회사의 주주는 완전모회사가 되는 회사가 주식교환을 위하여 발행하는 신주의 배정을 받거나 그 회사 자기주식의 이전을 받음으로써 그 회사의 주주가 된다.","ox":"O","m":"②","c":"A","tp":"상법상 주식의 포괄적 교환(이 문제에서‘주식교환’이라고 한다)"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-3","t":"완전모회사가 되는 회사가 완전자회사가 되는 회사의 주주들에게 주식교환의 대가로 이전하기 위하여 취득한 그 모회사의 주식이 주식교환 후에도 남은 경우 완전모회사가 되는 회사는 이를 처분할 의무가 없다.","ox":"X","m":"③","c":"A","tp":"상법상 주식의 포괄적 교환(이 문제에서‘주식교환’이라고 한다)"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-4","t":"주식교환에 의하여 완전모회사가 되는 회사의 이사로서 주식교환 이전에 취임한 자는 주식교환계약서에 다른 정함이 있는 경우를 제외하고는 주식교환이 이루어진 영업연도가 종료된 때 퇴임한다.","ox":"X","m":"④","c":"A","tp":"상법상 주식의 포괄적 교환(이 문제에서‘주식교환’이라고 한다)"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-5","t":"완전자회사가 되는 회사의 총주주의 동의가 있거나 그 회사의 발행주식 총수의 100분의 90 이상을 완전모회사가 되는 회사가 소유하고 있는 때에는 완전자회사가 되는 회사의 주주총회의 승인이나 이사회의 승인은 필요하지 않다.","ox":"X","m":"⑤","c":"A","tp":"상법상 주식의 포괄적 교환(이 문제에서‘주식교환’이라고 한다)"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-1","t":"합병은 주로 흡수합병과 신설합병으로 구별되고, 권리와 의무가 합병 후 존속회사 또는 합병으로 신설되는 회사에 법률상 포괄승계되는 측면에서 영업양도와 유사하다.","ox":"X","m":"①","c":"A","tp":"주식회사의 합병"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-2","t":"회사는 합병계약서를 작성하여 주주총회 승인결의를 얻어야 하고, 그 결의가 있은 날로부터 2주 내에 채권자에 대하여 합병에 관한 이의제출의 기회를 부여해야 한다. 이때 적법한 최고를 받은 채권자가 기한 내에 이의를 제기하지 아니하면 합병을 승인한 것으로 간주되고, 이후 합병무효의 소를 제기할 수 없다.","ox":"O","m":"②","c":"A","tp":"주식회사의 합병"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-3","t":"회사의 합병은 합병 후 존속하는 회사 또는 합병으로 인하여 설립되는 회사가 그 본점 소재지에서 합병의 등기를 마쳐야만 소멸된 회사의 권리의무를 승계하는 효력이 생긴다.","ox":"O","m":"③","c":"A","tp":"주식회사의 합병"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-4","t":"현저하게 불공정한 합병비율을 정한 합병계약은 사법관계를 지배하는 신의성실의 원칙이나 공평의 원칙 등에 비추어 무효이고, 따라서 합병비율이 현저하게 불공정한 경우 합병할 각 회사의 주주 등은 상법 제529조(합병무효의 소)에 의하여 소로써 합병의 무효를 구할 수 있다.","ox":"O","m":"④","c":"A","tp":"주식회사의 합병"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-5","t":"합병무효의 소는 합병의 등기가 있은 날로부터 6월내에 제기하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"주식회사의 합병"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33-1","t":"청산 중인 주식회사의 청산인을 피신청인으로 하여 그 직무집행을 정지하고 직무대행자를 선임하는 가처분결정이 있은 후, 그 선임된 청산인 직무대행자가 주주들의 요구에 따라 소집한 주주총회에서 회사를 계속하기로 하는 결의와 아울러 새로운 이사들과 감사를 선임하는 결의가 있었던 경우 그 주주총회의 결의에 의하여 청산인 직무대행자의 권한이 당연히 소멸하는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"청산 및 해산"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33-2","t":"당사자 쌍방이 현금과 현물(토지)을 출자하여 공동으로 주식회사를 설립하여 운영하고, 그 회사를 공동으로 경영함에 따르는 비용의 부담과 이익의 분배를 지분 비율에 따라 할 것을 내용으로 하는 동업계약에 따라 회사가 설립되어 그 실체가 갖추어진 이상, 주식회사의 청산에 관한 상법의 규정에 따라 청산절차가 이루어지지 않는 한 일방 당사자가 잔여재산을 분배받을 수 없다.","ox":"O","m":"②","c":"A","tp":"청산 및 해산"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33-3","t":"상법 제520조의2의 규정에 의하여 주식회사가 해산되고 그 청산이 종결된 것으로 보게 되는 회사라도 어떤 권리관계가 남아 있어 현실적으로 정리할 필요가 있으면 그 회사의 해산 당시의 이사는 정관에 다른 규정이 있거나 주주총회에서 따로 청산인을 선임하지 아니한 경우에 당연히 청산인이 되고, 그러한 청산인이 없는 때에는 이해관계인의 청구에 의하여 법원이 선임한 자가 청산인이 된다.","ox":"O","m":"③","c":"A","tp":"청산 및 해산"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33-4","t":"청산법인에서는 이사에 갈음하여 청산인만이 회사의 청산사무를 집행하고 회사를 대표하는 기관이 된다.","ox":"O","m":"④","c":"A","tp":"청산 및 해산"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33-5","t":"주식회사에 대하여 법원의 해산판결이 선고, 확정되어 해산등기가 마쳐졌고 아울러 법원이 적법하게 그 청산인을 선임하여 그 취임등기까지 경료되었으나 해산 당시 이사가 해산판결 선고 이전에 부적법하게 해임된 바 있어 주주총회의 이사해임 결의가 무효인 경우, 그 이사는 해산판결 전에 이루어진 회사의 주주총회 결의나 이사회 결의의 무효확인을 구할 법률상 이익이 있다.","ox":"X","m":"⑤","c":"A","tp":"청산 및 해산"},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50-1","t":"주식회사간 흡수합병의 경우 소멸회사 총주주의 동의가 있거나 그 회사 발행주식총수의 90% 이상을 합병후 존속회사가 소유하고 있는 때에는 소멸회사 주주총회 승인을 이사회 승인으로 갈음할 수 있다.","ox":"O","m":"①","c":"A","tp":"상법상 간이합병․소규모합병"},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50-2","t":"소규모합병의 경우 존속하는 회사의 합병계약서에는 주주총회의 승인을 얻지 아니하고 합병을 한다는 뜻을 기재하여야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 간이합병․소규모합병"},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50-3","t":"소규모합병의 경우 존속하는 회사는 합병계약서를 작성한 날부터 2주내에 소멸하는 회사의 상호 및 본점의 소재지, 합병을 할 날, 주주총회의 승인을 얻지 아니하고 합병을 한다는 뜻을 공고하거나 주주에게 통지하여야 한다.","ox":"O","m":"③","c":"A","tp":"상법상 간이합병․소규모합병"},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50-4","t":"소규모합병 및 간이합병의 경우 모두 합병에 반대하는 의사를 통지한 반대주주에게 주식매수청구권이 인정되지 아니한다.","ox":"X","m":"④","c":"A","tp":"상법상 간이합병․소규모합병"},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50-5","t":"소멸회사의 주주에게 지급할 금액이나 그 밖의 재산을 정한 경우 그 금액 및 그 밖의 재산의 가액이 존속회사의 최종 대차대조표상으로 현존하는 순자산액의 100분의 5를 초과하는 때에는 주주총회의 특별결의를 거쳐야 한다.","ox":"O","m":"⑤","c":"A","tp":"상법상 간이합병․소규모합병"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-1","t":"상법상 회사는 합명회사, 합자회사, 유한책임회사, 주식회사와 유한회사의 5종이다.","ox":"O","m":"①","c":"A","tp":"상법상 회사와 합병"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-2","t":"회사합병이 있는 경우에는 피합병회사의 권리·의무는 사법상의 관계 혹은 공법상의 관계를 불문하고 그 성질상 이전이 허용되지 않는 것을 제외하고는 모두 합병으로 인하여 존속한 회사에 승계되는 것으로 보아야 한다.","ox":"O","m":"②","c":"A","tp":"상법상 회사와 합병"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-3","t":"합병을 하는 회사의 일방 또는 쌍방이 주식회사, 유한회사 또는 유한책임회사인 경우에는 합병 후 존속하는 회사나 합병으로 설립되는 회사는 합명회사, 합자회사, 유한책임회사, 주식회사와 유한회사로 자유롭게 정할 수 있다.","ox":"X","m":"③","c":"A","tp":"상법상 회사와 합병"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-4","t":"소멸회사의 주주는 합병에 의하여 1주 미만의 단주만을 취득하게 되는 경우나 혹은 합병에 반대한 주주로서의 주식매수청구권을 행사하는 경우 등과 같은 특별한 경우를 제외하고는 원칙적으로 합병계약상의 합병비율과 배정방식에 따라 존속회사 또는 신설회사의 주주권을 취득하여 존속회사 또는 신설회사의 주주가 된다.","ox":"O","m":"④","c":"A","tp":"상법상 회사와 합병"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-5","t":"법원은 회사의 설립목적이 불법한 것인 때, 회사가 정당한 사유없이 설립 후 1년 내에 영업을 개시하지 아니하거나 1년 이상 영업을 휴지하는 때 등 상법이 규정하는 일정한 사유가 있는 경우에는 이해관계인이나 검사의 청구에 의하여 또는 직권으로 회사의 해산을 명할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상법상 회사와 합병"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-1","t":"상법은 영업양도, 합병, 분할합병, 주식의 포괄적 교환, 주식의 포괄적 이전 등에서 반대주주의 주식매수청구권을 인정하고 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-2","t":"반대주주의 주식매수청구권은 형성권으로서 그 행사로 회사의 승낙여부와 관계 없이 주식에 관한 매매계약이 성립한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-3","t":"반대주주의 주식매수청구권 행사 시 주식의 매수가액은 주주의 청구에 의해 법원이 정하는 것이 원칙이나, 주주와 회사 간의 협의에 의하여 결정할 수도 있다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-4","t":"주식매수청구권을 행사한 주주도 회사로부터 주식의 매매대금을 지급받지 아니하고 있는 동안에는 주주로서의 지위를 여전히 가지고 있으므로 특별한 사정이 없는 한, 주주로서의 권리를 행사하기 위하여 필요한 경우에는 회계장부열람·등사권을 가진다.","ox":"O","m":"④","c":"A","tp":"반대주주의 주식매수청구권"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-5","t":"영업용 재산의 처분이 회사 영업의 전부 또는 일부를 양도하거나 폐지하는 것과 같은 결과를 가져온다면, 이는 상법 제374조 제1항 제1호의 양도로서 주주총회의 특별결의가 필요하고, 위와 같은 영업용 재산의 처분에 관한 결의사항에 반대하는 주주도 상법 제374조의2에 따른 주식매수청구권을 행사할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"반대주주의 주식매수청구권"}],"17":[{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-1","t":"합명회사는 원칙적으로 각 사원이 회사의 채권자에 대하여 직접·연대·무한책임을 부담하고 직접 업무집행을 담당하는 회사로, 실질은 조합적 성질이 있어 내부관계에서는 민법의 조합에 관한 규정이 준용된다.","ox":"O","m":"①","c":"A","tp":"상법상 합명회사"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-2","t":"합명회사의 사원은 다른 사원의 동의를 얻지 아니하면 그 지분을 타인에게 양도하지 못하지만, 사원이 사망한 경우에는 원칙적으로 그 상속인에게 사원의 지분이 상속된다.","ox":"X","m":"②","c":"A","tp":"상법상 합명회사"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-3","t":"합명회사 사원의 출자의 목적은 재산, 노무 또는 신용의 어느 것이라고 무방한데, 그 목적과 가격 또는 평가의 표준은 정관의 절대적 기재사항에 해당한다.","ox":"O","m":"③","c":"A","tp":"상법상 합명회사"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-4","t":"사원은 다른 사원의 동의가 없으면 자기의 계산으로 회사의 영업부류에 속하는 거래를 하지 못하는데, 이를 위반하여 거래를 한 경우에 회사는 이를 회사의 계산으로 한 것으로 볼 수 있다.","ox":"O","m":"④","c":"A","tp":"상법상 합명회사"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-5","t":"합명회사의 성립 후에 가입한 사원은 그 가입 전에 생긴 회사채무에 대하여 다른 사원과 동일한 책임을 진다.","ox":"O","m":"⑤","c":"A","tp":"상법상 합명회사"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-1","t":"유한책임회사의 설립 시 사원은 신용이나 노무를 출자의 목적으로 하지 못한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-2","t":"유한책임회사의 사원은 다른 사원의 동의를 받지 아니하면 그 지분의 전부 또는 일부를 타인에게 양도하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-3","t":"유한책임회사는 법인을 업무집행자로 선임할 수 있고, 이 경우 그 법인은 해당 업무집행자의 직무를 행할 자를 선임하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-4","t":"유한책임회사는 총사원의 동의에 의하여 유한회사로 변경할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-5","t":"유한책임회사의 업무집행자는 결산기마다 대차대조표, 손익계산서, 그 밖에 유한책임회사의 재무상태와 경영성과를 표시하는 것으로서 대통령령으로 정하는 서류를 작성하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-1","t":"회사의 설립의 무효는 그 사원에 한하여, 설립의 취소는 그 취소권 있는 자에 한하여 회사성립의 날로부터 2년내에 소만으로 이를 주장할 수 있는데, 사원은 사원의 주소지 법원에 설립무효의 소를 제기할 수 있다.","ox":"X","m":"①","c":"A","tp":"합명회사의 설립무효, 취소"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-2","t":"설립무효의 판결 또는 설립취소의 판결은 제3자에 대하여도 그 효력이 있으나 판결확정 전에 생긴 회사와 사원 및 제3자간의 권리의무에 영향을 미치지 아니한다.","ox":"O","m":"②","c":"A","tp":"합명회사의 설립무효, 취소"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-3","t":"수개의 설립무효의 소 또는 설립취소의 소가 제기된 때에는 법원은 이를 병합심리하여야 한다.","ox":"O","m":"③","c":"A","tp":"합명회사의 설립무효, 취소"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-4","t":"설립무효의 판결 또는 설립취소의 판결이 확정된 때에는 본점과 지점의 소재지에서 등기하여야 한다.","ox":"O","m":"④","c":"A","tp":"합명회사의 설립무효, 취소"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-5","t":"설립무효의 판결 또는 설립취소의 판결이 확정된 때에는 해산의 경우에 준하여 청산하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"합명회사의 설립무효, 취소"},{"y":2022,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2022_28-44","t":"다음 중 유한책임회사 설립등기사항을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 유한책임회사 설립등기사항을 모두 고른 것은?","d":"㉠목적, 상호, 본점의 소재지, 지점을 둔 경우에는 그 소재지\n㉡존립기간 기타 해산사유를 정한 때에는 그 기간 또는 사유\n㉢자본금의 액\n㉣사원의 성명‧주민등록번호\n㉤유한책임회사를 대표할 자를 정한 경우에는 그 성명 또는 명칭과 주소","o":["㉠, ㉡, ㉤","㉠, ㉣, ㉤","㉠, ㉡, ㉢, ㉣","㉠, ㉡, ㉢, ㉤","㉠, ㉡, ㉢, ㉣, ㉤"],"a":4}},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-1","t":"유한회사의 정관에서 특정 이사의 보수액을 구체적으로 정한 경우, 보수액은 임용계약의 내용이 되어 당사자인 회사와 이사 쌍방을 구속하므로, 특별한 사정이 없는 한 유한회사의 사원총회에서 임용계약의 내용으로 이미 편입된 이사의 보수를 감액하거나 박탈하는 결의를 하더라도, 이러한 사원총회 결의는 결의 자체의 효력과 관계없이 이사의 보수청구권에 아무런 영향을 미치지 못한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-2","t":"유한회사의 사원총회에서 선임된 이사가 회사와의 명시적 또는 묵시적 약정에 따라 그 업무를 다른 이사 등에게 포괄적으로 위임하고 이사로서의 실질적인 업무를 수행하지 않은 경우라 하더라도 특별한 사정이 없는 한 소극적인 직무 수행 사유만을 가지고 그 이사로서의 자격을 부정하거나 사원총회 결의에서 정한 보수청구권의 효력을 부정하기는 어렵다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-3","t":"유한회사 성립 후에 출자금액의 납입 또는 현물출자의 이행이 완료되지 아니하였음이 발견된 때에 회사성립 당시의 사원, 이사와 감사는 회사에 대하여 그 납입되지 아니한 금액 또는 이행되지 아니한 현물의 가액을 연대하여 지급할 책임이 있는데, 이때 사원의 책임은 면제하지 못하나, 이사와 감사의 책임은 총사원의 동의가 있으면 면제할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-4","t":"유한회사 사원의 지분은 사원이 회사에 대하여 가지는 권리의무의 총체 즉 사원권으로서 신분상의 권리와 아울러 재산상의 권리를 포함하고 있는 것이므로 재산상의 가치를 가지고 이를 현금화하는 것이 가능하므로 강제집행의 대상이 되고, 피전부채권으로서의 적격도 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-5","t":"유한회사의 사원권에 관한 명의신탁 해지로 명의신탁자가 사원권을 회복하기 위하여는 사원총회의 특별결의가 있는 때에 한하여 그 효력이 생기고, 해지의 의사표시만에 의하여 수탁된 지분이 바로 명의신탁자에게 복귀하는 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-1","t":"상법상 합명회사의 사원 또는 업무집행사원의 업무집행권한을 상실시키는 것은 상법 제205조 제1항에 따라 다른 사원의 청구에 의하여 법원의 선고로써 권한을 상실시키는 방법에 의해서만 가능하다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-2","t":"합명회사의 사원은 회사채권자에 대하여 직접·연대·무한책임을 부담하지만, 업무집행권한 상실제도를 통하여 업무집행에 현저히 부적합하거나 중대하게 의무를 위반한 사원이나 업무집행사원을 업무집행에서 배제함으로써 자신의 책임이 부당하게 발생·증대되는 것으로부터 자신을 보호할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-3","t":"합명회사 사원의 책임은 ‘회사의 재산으로 회사의 채무를 완제할 수 없는 때’ 또는 ‘회사재산에 대한 강제집행이 주효하지 못한 때’에 비로소 발생한다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-4","t":"합명회사의 청산 중에 사원의 퇴사가 허용된다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-5","t":"상법은 합명회사의 경우 표현책임에 관한 규정을 두고 있지 아니하므로, 합명회사의 사원이 아닌 자가 타인에게 자기를 사원이라고 오인시키는 행위를 하였더라도 오인으로 인하여 회사와 거래한 자에 대하여 사원과 책임을 부담하는 것은 아니다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-1","t":"합자회사에서 업무집행권한 상실선고제도의 목적은 업무를 집행함에 현저하게 부적임하거나 중대한 의무위반행위가 있는 업무집행사원의 권한을 박탈함으로써 그 회사의 운영에 장애사유를 제거하려는 데 있다. 업무집행사원의 권한상실을 선고하는 판결은 형성판결로서 그 판결 확정에 의하여 업무집행권이 상실되면 그 결과 대표권도 함께 상실된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-2","t":"합자회사에서 무한책임사원이 업무집행권한의 상실을 선고하는 판결로 인해 업무집행권 및 대표권을 상실하였더라도, 그 후 어떠한 사유 등으로 그 무한책임사원이 합자회사의 유일한 무한책임사원이 된 경우 해당 무한책임사원의 업무집행권 및 대표권이 부활한다고 볼 수 있다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-3","t":"상법 제270조는 합자회사 정관에는 각 사원이 무한책임사원인지 또는 유한책임사원인지를 기재하도록 규정하고 있으므로, 정관에 기재된 합자회사 사원의 책임 변경은 정관변경의 절차에 의하여야 하고, 이를 위해서는 정관에 그 의결정족수 내지 동의정족수 등에 관하여 별도로 정하고 있다는 등의 특별한 사정이 없는 한 상법 제269조에 의하여 준용되는 상법 제204조에 따라 총 사원의 동의가 필요하다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-4","t":"합자회사의 유한책임사원이 한 지분양도가 합자회사의 정관에서 규정하고 있는 요건을 갖추지 못한 경우에는 그 지분양도는 무효이다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-5","t":"합자회사가 존립기간의 만료로 해산한 후 사원의 일부만 회사계속에 동의하였다면 그 사원들의 동의로 정관의 규정을 변경하거나 폐지할 수 있다. 그리고 회사계속 동의 여부에 대한 사원 전부의 의사가 동시에 분명하게 표시되어야만 회사계속이 가능한 것은 아니므로, 일부 사원이 회사계속에 동의하였다면 나머지 사원들의 동의 여부가 불분명하더라도 회사계속의 효과는 발생한다.","ox":"O","m":"⑤","c":"A"}],"3":[{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-1","t":"수형자의 기본권 제한에 대한 구체적인 한계는 헌법 제37조 제2항에 따라 법률에 의하여 구체적인 자유·권리의 내용과 성질, 그 제한의 태양과 정도 등을 교량하여 설정하게 되며, 수용 시설 내의 안전과 질서를 유지하기 위하여 이들 기본권의 일부 제한이 불가피하다 하더라도 그 본질적인 내용을 침해하거나, 목적의 정당성, 방법의 적정성, 피해의 최소성 및 법익의 균형성 등을 의미하는 과잉금지의 원칙에 위배되어서는 안 된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-2","t":"수형자인 청구인이 헌법소원 사건의 국선대리인인 변호사를 접견함에 있어서 그 접견내용을 녹음, 기록한 피청구인의 행위는 청구인의 재판을 받을 권리를 침해한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-3","t":"수용거실의 지정은 교도소장의 재량적 판단사항이며 수용자에게 수용거실의 변경을 신청할 권리 내지 특정 수용거실에 대한 신청권이 있다고 볼 수 없으므로, 교도소장의 독거수용 거부는 헌법소원심판의 대상이 되는 공권력의 행사에 해당하지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-4","t":"금치 처분을 받은 수형자에 대한 절대적인 운동의 금지는 징벌의 목적을 고려하더라도 그 수단과 방법에 있어서 필요한 최소한도의 범위를 벗어난 것으로서, 수형자의 헌법 제10조의 인간의 존엄과 가치 및 제12조의 신체의 자유를 침해하는 정도에 이르렀다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-5","t":"외부 재판에 출정할 때 운동화를 착용하게 해달라는 청구인의 신청에 대하여 이를 불허하고 고무신의 착용을 강제하는 것은, 효과적인 도주 방지 수단이 될 수도 없고, 오히려 수형자의 신분을 일반인에게 노출시켜 모욕감과 수치심을 갖게 할 뿐으로서 기본권 제한의 한계를 벗어나 청구인의 인격권과 행복추구권을 침해하였다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03","t":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","d":"가.모든 국민은 신체의 자유를 가진다. 누구든지 법률이나 대통령령에 의하지 아니하고는 체포․구속․압수․수색 또는 심문을 받지 아니하며, 법률과 적법한 절차에 의하지 아니하고는 처벌․보안처분 또는 강제노역을 받지 아니한다.\n나.모든 국민은 고문을 받지 아니하며, 형사상 자기에게 불리한 진술을 강요당하지 아니한다.\n다.체포․구속․압수 또는 수색을 할 때에는 적법한 절차에 따라 검사의 신청에 의하여 법관이 발부한 영장을 제시하여야 한다. 다만 현행범인인 경우와 장기 1년 이상의 형에 해당하는 죄를 범하고 도피 또는 증거인멸의 염려가 있을 때에는 사후에 영장을 청구할 수 있다.\n라.누구든지 체포 또는 구속을 당한 때에는 48시간 이내에 변호인의 조력을 받을 권리를 가진다. 다만 형사피고인이 스스로 변호인을 구할 수 없을 때에는 법률이 정하는 바에 의하여 국가가 변호인을 붙인다.\n마.누구든지 체포 또는 구속의 이유와 변호인의 조력을 받을 권리가 있음을 고지받지 아니하고는 체포 또는 구속을 당하지 아니한다. 체포 또는 구속을 당한 자의 가족 등 법률이 정하는 자에게는 그 이유와 일시․장소가 지체 없이 통지되어야 한다.\n바.누구든지 체포 또는 구속을 당한 때에는 적부의 심사를 법원이나 검찰에 청구할 권리를 가진다.","o":["1개","2개","3개","4개","5개"],"a":4}},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-1","t":"청구인의 변호인이 국가보안법위반죄로 구속기소된 청구인의 변론준비를 위하여 피청구인인 검사에게 그가 보관중인 수사기록 일체에 대한 열람·등사신청을 하였으나, 피청구인은 국가기밀의 누설이나 증거인멸, 증인협박, 사생활침해의 우려 등 정당한 사유를 밝히지 아니한 채 이를 전부 거부한 것은 청구인의 신속·공정한 재판을 받을 권리와 변호인의 조력을 받을 권리를 침해하는 것으로 헌법에 위반된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-2","t":"검사가 법원의 증인으로 채택된 수감자를 그 증언에 이르기까지 거의 매일 검사실로 하루 종일 소환하여 피고인측 변호인이 접근하는 것을 차단하고, 검찰에서의 진술을 번복하는 증언을 하지 않도록 회유·압박하는 한편, 때로는 검사실에서 그에게 편의를 제공하기도 한 행위는 피고인의 공정한 재판을 받을 권리를 침해한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-3","t":"형사소송법 제297조 제1항 전문 중 ‘재판장은 증인이 피고인의 면전에서 충분한 진술을 할 수 없다고 인정한 때에는 피고인을 퇴정하게 하고 진술하게 할 수 있다.’는 부분은 피고인의 증인에 대한 반대신문권 등을 완전히 박탈하는 것으로서 과잉금지원칙에 위반되므로, 헌법이 보장하는 공정한 재판을 받을 권리를 침해한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-4","t":"정식재판 청구기간을 ‘약식명령의 고지를 받은 날로부터 7일 이내’로 정하고 있는 형사소송법(1954. 9. 23. 법률 제341호로 제정된 것) 제453조 제1항 중 피고인에 관한 부분이 합리적인 입법재량의 범위를 벗어나 약식명령 피고인의 재판청구권을 침해한다고 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-5","t":"자기 또는 배우자의 직계존속을 고소하지 못하도록 규정한 형사소송법 제224조(1954. 9. 23. 법률 제341호로 제정된 것)는 ‘효’라는 우리 고유의 전통규범을 수호하기 위하여 비속이 존속을 고소하는 행위의 반윤리성을 억제하고자 하는 것이어서, 평등원칙에 위반되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-1","t":"현역병의 군대 입대 전 범죄에 대한 군사법원의 재판권을 규정하고 있는 군사법원법 제2조 제2항 중 제1항 제1호의 ‘군형법 제1조 제2항의 현역에 복무하는 병’ 부분은 재판청구권을 침해한다고 볼 수 없다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-2","t":"영창제도를 규정하고 있는 구 전투경찰대 설치법 제5조는 적법절차원칙에 위배된다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-3","t":"산업기능요원으로 편입되어 1년 이상 종사하다가 편입이 취소되어 입영하는 사람의 경우 복무기간을 단축할 수 있다고 규정한 구 병역법 규정은 1년 미만을 종사하다가 편입취소된 산업기능요원만 차별하여 위헌이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-4","t":"헌법 제39조 제2항이 금지하는 ‘불이익한 처우’라 함은 단순한 사실상, 경제상의 불이익을 모두 포함하는 것이 아니라 법적인 불이익을 의미하는 것으로 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-5","t":"국방의 의무는 외부 적대세력의 직·간접적인 침략행위로부터 국가의 독립을 유지하고 영토를 보전하기 위한 의무로서, 현대전이 고도의 과학기술과 정보를 요구하고 국민전체의 협력을 필요로 하는 이른바 총력전인 점에 비추어 단지 병역법에 의하여 군복무에 임하는 등의 직접적인 병력형성의무만을 가리키는 것이 아니라, 병역법·향토예비군설치법·민방위기본법·비상대비자원관리법 등에 의한 간접적인 병력형성의무 및 병력형성 이후 군작전명령에 복종하고 협력하여야 할 의무도 포함하는 개념이다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-1","t":"일정한 성범죄를 저지른 자로부터 신상정보를 제출받아 보존·관리하는 것은 정당한 목적을 위한 적합한 수단이고, 침해되는 사익은 크지 않은 반면 해당 조항을 통해 달성되는 공익은 매우 중요하므로, 성폭력범죄의 처벌 등에 관한 특례법위반(카메라 등 이용촬영, 카메라 등 이용촬영미수)죄로 유죄판결이 확정된 자는 신상정보 등록대상자가 되도록 규정한 성폭력범죄의 처벌 등에 관한 특례법(2012. 12. 18. 법률 제11556호로 전부개정된 것) 제42조 제1항 중 해당 부분은 개인정보자기결정권을 침해하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-2","t":"법무부장관이 등록대상자의 재범 위험성이 상존하는 20년 동안 그의 신상정보를 보존·관리하는 것은 정당한 목적을 위한 적합한 수단이므로, 모든 등록대상 성범죄자에 대하여 일률적으로 20년의 등록기간을 적용하고 있더라도 개인정보자기결정권을 침해한다고 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-3","t":"주민등록번호 유출 또는 오·남용으로 인하여 발생할 수 있는 피해 등에 대한 아무런 고려 없이 주민등록번호 변경을 일체 허용하지 않는 것은 그 자체로 개인정보자기결정권에 대한 과도한 침해가 될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-4","t":"인터넷게시판을 설치·운영하는 정보통신서비스 제공자에게 본인확인조치의무를 부과하여 게시판 이용자로 하여금 본인확인절차를 거쳐야만 게시판을 이용할 수 있도록 하는 본인확인제를 규정한 정보통신망 이용촉진 및 정보보호 등에 관한 법률(2008. 6. 13. 법률 제9119호로 개정된 것) 제44조의5 제1항 제2호는 과잉금지원칙에 위배하여 인터넷게시판 이용자의 표현의 자유, 개인정보자기결정권을 침해한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-5","t":"인터넷언론사가 선거운동기간 중 당해 홈페이지의 게시판 등에 정당·후보자에 대한 지지·반대의 정보를 게시할 수 있도록 하는 경우 실명을 확인받도록 하는 기술적 조치를 하여야 하고 이를 위반한 때에는 과태료를 부과하는 공직선거법(2010. 1. 25. 법률 제9974호로 개정된 것) 제82조의6 제6항, 제7항은 게시판 이용자의 정치적 익명표현의 자유, 개인정보자기결정권 및 인터넷언론사의 언론의 자유를 침해한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-1","t":"명확성의 원칙은 법률을 적용하는 단계에서 가치판단을 전혀 배제한 무색투명한 서술적 개념으로 규정되어져야 한다는 것을 의미하는 것은 아니고, 입법자의 입법의도가 건전한 일반상식을 가진 자에 의하여 일의적으로 파악될 수 있는 정도의 것을 의미하는 것이다.","ox":"O","m":"①","c":"A","tp":"죄형법정주의"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-2","t":"다소 광범위하고 어느 정도의 범위에서는 법관의 보충적인 해석을 필요로 하는 개념을 사용하여 규정하였다고 하더라도 그 적용단계에서 다의적으로 해석될 우려가 없는 이상 그 점만으로 헌법이 요구하는 명확성의 요구에 위배되는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"죄형법정주의"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-3","t":"군형법 제47조에서 말하는 ‘정당한 명령 또는 규칙’은 군의 특성상 그 내용을 일일이 법률로 정할 수 없어 법률의 위임에 따라 군통수기관이 불특정다수인을 대상으로 발하는 일반적 효력이 있는 명령이나 규칙 중 그 위반에 대하여 형사처벌의 필요가 있는 것, 즉 법령의 범위 내에서 발해지는 군통수작용상 필요한 중요하고도 구체성 있는 특정한 사항에 관한 것을 의미한다고 보아야 할 것이며, 위 법률규정이 불명확하여 죄형법정주의 원칙에 위배된다고 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-4","t":"처벌을 규정하고 있는 법률조항이 구성요건이 되는 행위를 같은 법률조항에서 직접 규정하지 않고 다른 법률조항에서 이미 규정한 내용을 원용하였다거나 그 내용 중 일부를 괄호 안에 규정하였다는 사실만으로 명확성 원칙에 위반된다고 할 수는 없다.","ox":"O","m":"④","c":"A","tp":"죄형법정주의"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-5","t":"헌법 제12조 제1항 후단이 ‘법률과 적법한 절차에 의하지 아니하고는 처벌을 받지 아니한다.’ 라고 규정하여 죄형법정주의를 천명하고 있고, 여기에서 ‘법률’이란 입법부에서 제정한 형식적 의미의 법률을 의미하는 것이긴 하나, 현대국가의 사회적 기능증대와 사회현상의 복잡화에 따라 국민의 권리ㆍ의무에 관한 사항이라 하여 모두 입법부에서 제정한 법률만으로 다정할 수는 없어 예외적으로 하위법령에 위임하는 것을 허용하지 않을 수 없고, 구 노동조합법 제46조의3이 ‘단체협약에 위반한 자’를 1,000만 원 이하의 벌금에 처하도록 규정한 것이 죄형법정주의에 위배된다고 보기 어렵다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-1","t":"모든 인간은 헌법상 생명권의 주체가 되며, 형성 중의 생명인 태아에게도 생명에 대한 권리가 인정되어야 한다. 따라서 태아도 헌법상 생명권의 주체가 되며, 국가는 헌법 제10조에 따라 태아의 생명을 보호할 의무가 있다.","ox":"O","m":"①","c":"A","tp":"태아의 생명권"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-2","t":"민법 제762조는 ‘태아는 손해배상의 청구권에 관하여는 이미 출생한 것으로 본다.’라고 규정함으로써 ‘살아서 출생한 태아’와는 달리 ‘살아서 출생하지 못한 태아’에 대해서는 손해배상청구권을 부정함으로써 후자에게 불리한 결과를 초래하고 있으나 이러한 결과는 사법(私法)관계에서 요구되는 법적 안정성의 요청이라는 법치국가이념에 의한 것으로 헌법적으로 정당화된다 할 것이므로, 그와 같은 차별적 입법조치가 있다는 이유만으로 곧 국가가 기본권 보호를 위해 필요한 최소한의 입법적 조치를 다하지 않아 그로써 위헌적인 입법적 불비나 불완전한 입법상태가 초래된 것이라고 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"태아의 생명권"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-3","t":"초기배아는 수정이 된 배아라는 점에서 형성 중인 생명의 첫걸음을 떼었다고 볼 여지가 있기는 하나 아직 모체에 착상되거나 원시선이 나타나지 않은 이상 기본권 주체성 및 국가의 보호필요성을 인정할 수 없다.","ox":"X","m":"③","c":"A","tp":"태아의 생명권"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-4","t":"법학자, 윤리학자, 철학자, 의사 등의 직업인들이 보존기간이 경과한 잔여배아를 각종 연구에 사용할 수 있도록 허용하고 있는 생명윤리 및 안전에 관한 법률 조항에 의해 불편을 겪는다고 하더라도, 이는 사실적ㆍ간접적 불이익에 불과하여 기본권침해의 가능성 및 자기관련성을 인정할 수 없다.","ox":"O","m":"④","c":"A","tp":"태아의 생명권"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-5","t":"배아생성자는 배아에 대해 자신의 유전자정보가 담긴 신체의 일부를 제공하고, 또 배아가 모체에 성공적으로 착상하여 인간으로 출생할 경우 생물학적 부모로서의 지위를 갖게 되므로 배아의 관리 또는 처분에 대한 결정권을 가진다.","ox":"O","m":"⑤","c":"A","tp":"태아의 생명권"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-1","t":"민사소송법에 의한 방영금지가처분을 허용하는 것은 헌법상 검열금지의 원칙에 위반되지 않는다.","ox":"O","m":"①","c":"A","tp":"언론과 관련된 헌법적 문제"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-2","t":"언론인의 선거운동을 금지하고, 이를 위반한 경우 처벌하도록 규정한 공직선거법 관련 조항 부분은 선거운동의 자유를 침해한다.","ox":"O","m":"②","c":"A","tp":"언론과 관련된 헌법적 문제"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-3","t":"방송통신심의위원회의 시정요구는 헌법소원의 대상이 된다.","ox":"O","m":"③","c":"A","tp":"언론과 관련된 헌법적 문제"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-4","t":"영화도 의사표현의 한 수단이므로 영화의 제작 및 상영 역시 언론·출판의 자유에 의한 보장을 받는다.","ox":"O","m":"④","c":"A","tp":"언론과 관련된 헌법적 문제"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-5","t":"인터넷언론사에 대하여 선거운동기간 중 당해 인터넷홈페이지 게시판·대화방 등에 정당·후보자에 대한 지지·반대의 글을 게시할 수 있도록 하는 경우 실명을 확인받도록 하는 기술적 조치를 할 의무를 부과한 공직선거법은 표현의 자유를 침해한다.","ox":"X","m":"⑤","c":"A","tp":"언론과 관련된 헌법적 문제"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11-1","t":"대학의 자율성은 학문의 자유를 보장하기 위한 수단으로서 대학에 부여된 헌법상 기본권이다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11-2","t":"국립대학은 국가가 설립한 공법상 영조물이지만, 대학의 자율이라는 기본권의 주체이기도 하다.","ox":"O","m":"②","c":"A","tp":"대학의 자율성"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11-3","t":"대학의 자치의 주체를 기본적으로 대학으로 본다고 하더라도 교수나 교수회의 주체성이 부정된다고 볼 수는 없고, 가령 학문의 자유를 침해하는 대학의 장에 대한 관계에서는 교수나 교수회가 주체가 될 수 있고, 또한 국가에 의한 침해에 있어서는 대학 자체 외에도 대학 전구성원이 자율성을 갖는 경우도 있을 것이므로 문제되는 경우에 따라서 대학, 교수, 교수회 모두가 단독, 혹은 중첩적으로 주체가 될 수 있다.","ox":"O","m":"③","c":"A","tp":"대학의 자율성"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11-4","t":"법인으로 설립되지 않은 국립대학은 당사자능력이 인정되지 않으므로, 헌법소원심판을 제기할 수 있는 청구인적격도 인정되지 않는다.","ox":"X","m":"④","c":"A","tp":"대학의 자율성"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11-5","t":"대학의 자율성에 대한 규율의 정도는 그 시대의 사정과 각급 학교에 따라 다를 수 밖에 없는 것이므로 교육의 본질을 침해하지 않는 한 궁극적으로는 입법권자의 형성의 자유에 속한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17","t":"형벌에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"형벌에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["모욕죄를 규정하고 있는 형법은 표현의 자유를 침해하지 아니한다.","헌법 제13조 제1항이 정한 이중처벌금지의 원칙은 동일한 범죄행위에 대하여 국가가 형벌권을 거듭 행사할 수 없도록 함으로써 국민의 기본권을 보장하기 위한 것이므로, 그 ‘처벌’은 국가가 행하는 일체의 제재나 불이익처분을 의미한다.","은닉, 보유․보관된 문화재에 대하여 필요적 몰수를 규정한 문화재보호법 규정은 책임과 형벌 간 비례원칙에 위배된다.","주거침입강제추행죄의 법정형을 주거침입강간죄와 동일하게 규정한 것은 평등원칙에 반하지 아니한다.","형사범죄를 일으킨 공무원에 대하여 공무원연금법상 급여를 제한하더라도 이중적인 처벌에 해당하는 것은 아니다. 23-4"],"a":2}},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-1","t":"집회의 자유는 개인의 인격발현의 요소이자 민주주의를 구성하는 요소라는 이중적 헌법적 기능을 가지고 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-2","t":"집회의 자유는 정치·사회현상에 대한 불만과 비판을 공개적으로 표출케 함으로써 정치적 불만세력을 사회적으로 통합하여 정치적 안정에 기여하는 역할을 하므로, 단지 평화적 또는 비폭력적 집회만 집회의 자유에 의하여 보호된다고 할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-3","t":"집회 또는 시위가 신고된 범위 내에서 행해졌거나 신고된 내용과 다소 다르게 행해졌어도 신고된 범위를 현저히 일탈하지 않은 경우에는, 그로 인하여 도로의 교통이 방해를 받았다고 하더라도 특별한 사정이 없는 한 형법 제185조의 일반교통방해죄가 성립한다고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"집회의 자유"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-4","t":"학문, 예술, 체육, 종교, 의식, 친목, 오락, 관혼상제 및 국경행사에 관한 집회는 법률상 신고대상이 아니다.","ox":"O","m":"④","c":"A","tp":"집회의 자유"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-5","t":"일반적으로 집회는 일정한 장소를 전제로 하여 특정 목적을 가진 다수인이 일시적으로 회합하는 것을 말하는 것으로 일컬어지고 있고, 그 공동의 목적은 내적인 유대 관계로 족하다.","ox":"O","m":"⑤","c":"A","tp":"집회의 자유"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-1","t":"헌법상 사전검열은 표현의 자유 보호대상이면 예외 없이 금지되므로, 건강기능식품의 기능성 광고에 대해서도 사전검열금지원칙이 적용된다. 건강기능식품에 관한 법률상 기능성 광고의 심의는 식약처장으로부터 위탁받은 한국건강기능식품협회에서 수행하고 있는데, 한국건강기능식품협회는 행정권으로부터 독립된 민간 자율기구로서 그 행정주체성을 인정하기 어려우므로 헌법이 금지하는 사전검열에 해당한다고 할 수 없다.","ox":"X","m":"①","c":"A","tp":"언론⋅출판의 자유"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-2","t":"의사표현의 자유는 헌법 제21조 제1항이 규정하는 언론·출판의 자유에 속하고, 여기서 의사표현의 매개체는 어떠한 형태이건 그 제한이 없으므로 의사표현의 한 수단인 TV 방송 역시 다른 의사표현 수단과 마찬가지로 헌법에 의한 보장을 받는다.","ox":"O","m":"②","c":"A","tp":"언론⋅출판의 자유"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-3","t":"국가가 개인의 표현행위를 규제하는 경우, 표현내용에 대한 규제는 원칙적으로 중대한 공익의 실현을 위하여 불가피한 경우에 한하여 엄격한 요건 하에서 허용되는 반면, 표현내용과 무관하게 표현의 방법을 규제하는 것은 합리적인 공익상의 이유로 폭넓은 제한이 가능하다.","ox":"O","m":"③","c":"A","tp":"언론⋅출판의 자유"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-4","t":"방송매체의 특수성을 고려하면 방송의 기능을 보장하기 위한 규율의 필요성은 신문 등 인쇄매체보다 높다.","ox":"O","m":"④","c":"A","tp":"언론⋅출판의 자유"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-5","t":"선거운동의 자유는 널리 선거과정에서 자유로이 의사를 표현할 자유의 일환으로서 표현의 자유를 실현하는 하나의 수단이기도 하다는 점에서 언론·출판의 자유를 보장하고 있는 헌법 제21조에 의해 보호된다.","ox":"O","m":"⑤","c":"A","tp":"언론⋅출판의 자유"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-1","t":"보안처분이라 하더라도 형벌적 성격이 강하여 신체의 자유를 박탈하거나 박탈에 준하는 정도로 신체의 자유를 제한하는 경우에는 소급입법금지원칙을 적용하는 것이 법치주의 및 죄형법정주의에 부합한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-2","t":"카메라등이용촬영죄를 범한 사람에 대하여 유죄판결을 선고하는 경우 성폭력 치료프로그램의 이수명령을 병과하도록 한 성폭력범죄의 처벌 등에 관한 특례법 조항은 보안처분에 해당하므로, 동일한 범죄행위에 대하여 형벌과 병과되더라도 이중처벌금지원칙에 위배된다고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-3","t":"노역장유치란 벌금납입의 대체수단이자 납입강제기능을 갖는 벌금형의 집행방법이며, 벌금형에 대한 환형처분이라는 점에서 형벌과 구별된다. 따라서 노역장유치기간의 하한을 정한 것은 벌금형을 대체하는 집행방법을 강화한 것에 불과하며, 이를 소급적용한다고 하여 형벌불소급의 문제가 발생한다고 보기 어렵다.","ox":"X","m":"③","c":"A","tp":"보안처분"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-4","t":"전자장치 부착명령은 전통적 의미의 형벌이 아닐 뿐 아니라 처벌적인 효과를 나타낸다고 보기도 어려우므로, 전자장치 부착명령은 범죄행위를 한 사람에 대한 응보를 주된 목적으로 그 책임을 추궁하는 사후적 처분인 형벌과 구별되는 비형벌적 보안처분으로서 소급효금지원칙이 적용되지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-5","t":"가정폭력범죄의 처벌 등에 관한 특례법이 정한 보호처분 중의 하나인 사회봉사명령은 보안처분의 성격을 가지는 것이 사실이나, 한편으로 이는 가정폭력범죄행위에 대하여 형사처벌 대신 부과되는 것으로서 가정폭력범죄를 범한 자에게 의무적 노동을 부과하고 여가시간을 박탈하여 실질적으로는 신체적 자유를 제한하게 되므로, 이에 대하여는 원칙적으로 형벌불소급의 원칙에 따라 행위시법을 적용함이 상당하다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-1","t":"형법 제269조 제1항은 부녀가 약물 기타 방법으로 낙태한 때에는 1년 이하의 징역 또는 200만 원 이하의 벌금에 처하도록 규정하고 있다. 이러한 자기낙태죄 조항의 위헌 여부는 임신한 여성의 자기결정권과 태아의 생명권의 직접적인 충돌이 문제되므로 헌법을 규범 조화적으로 해석하여 사안을 해결하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-2","t":"모든 인간은 헌법상 생명권의 주체가 되며, 형성 중의 생명인 태아에게도 생명에 대한 권리가 인정되어야 한다. 따라서 국가는 헌법 제10조 제2문에 따라 태아의 생명을 보호할 의무가 있고, 생명을 보호하는 입법적 조치를 취함에 있어 인간생명의 발달단계에 따라 그 보호정도나 보호수단을 달리하여서는 아니 된다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-3","t":"이른바 임신 제1삼분기(대략 마지막 생리기간의 첫날부터 14주 무렵까지)에는 어떠한 사유를 요구함이 없이 임신한 여성이 자신의 숙고와 판단 아래 낙태할 수 있도록 하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-4","t":"업무상동의낙태죄와 자기낙태죄는 대향범이므로, 임신한 여성의 자기낙태를 처벌하는 것이 위헌이라고 판단되는 경우에는 동일한 목표를 실현하기 위해 부녀의 촉탁 또는 승낙을 받아 낙태하게 한 의사를 형사처벌하는 의사낙태죄 조항도 당연히 위헌이 되는 관계에 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-5","t":"모자보건법상의 정당화 사유에는 사회적·경제적 사유도 포함되는데, 이에 해당하더라도 임신 24주 이내에만 낙태가 가능하므로 임신한 여성의 자기결정권을 보장하기에는 불충분하다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-1","t":"광고물도 사상·지식·정보 등을 불특정다수인에게 전파하는 것으로서 언론·출판의 자유에 의한 보호를 받는 대상이 된다.","ox":"O","m":"①","c":"A","tp":"언론․출판의 자유"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-2","t":"헌법 제21조 제1항에 의해 보장되는 언론·출판의 자유에는 방송의 자유가 포함된다.","ox":"O","m":"②","c":"A","tp":"언론․출판의 자유"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-3","t":"헌법 제21조 제2항의 사전검열금지원칙은 모든 형태의 사전적인 규제를 금지하는 것은 아니고, 의사표현의 발표 여부가 오로지 행정권의 허가에 달려있는 사전심사만을 금지한다. 헌법재판소는 헌법이 금지하는 사전검열의 요건으로 첫째, 일반적으로 허가를 받기 위한 표현물의 제출의무가 존재할 것, 둘째, 행정권이 주체가 된 사전심사절차가 존재할 것, 셋째, 허가를 받지 아니한 의사표현을 금지할 것, 넷째, 심사절차를 관철할 수 있는 강제수단이 존재할 것을 들고 있다.","ox":"O","m":"③","c":"A","tp":"언론․출판의 자유"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-4","t":"음란표현은 헌법 제21조가 규정하는 언론·출판의 보호영역에 아예 포함될 여지가 없다.","ox":"X","m":"④","c":"A","tp":"언론․출판의 자유"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-5","t":"헌법은 언론·출판은 타인의 명예나 권리 또는 공중도덕이나 사회윤리를 침해하여서는 아니되고, 언론·출판이 타인의 명예나 권리를 침해한 때에는 피해자는 이에 대한 피해의 배상을 청구할 수 있다고 규정하고 있다.","ox":"O","m":"⑤","c":"A","tp":"언론․출판의 자유"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-1","t":"법관으로 하여금 미결구금일수를 형기에 산입하되, 그 산입범위는 재량에 의하여 결정하도록 한 형법 조항은 헌법상 무죄추정의 원칙 및 적법절차의 원칙을 위배하여 신체의 자유를 침해한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-2","t":"동일한 범죄사실로 외국에서 형의 전부 또는 일부의 집행을 받은 자에 대하여 우리 형법에 의한 처벌 시 외국에서 받은 형의 집행을 전혀 반영하지 아니할 수도 있도록 한 형법규정은 과잉금지원칙에 위배되어 신체의 자유를 침해한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-3","t":"특정범죄에 대하여 형의 선고를 받아 확정된 사람으로부터 디엔에이감식시료를 채취할 수 있도록 한 디엔에이신원확인정보의 이용 및 보호에 관한 법률 조항은 과잉금지의 원칙을 위반하여 신체의 자유를 침해한다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-4","t":"형사재판에 계속 중인 사람에 대하여 법무부장관이 6개월 이내의 기간을 정하여 출국을 금지할 수 있다고 규정한 출입국관리법 조항은 영장주의에 위배되지 않는다.","ox":"O","m":"④","c":"A","tp":"신체의 자유"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-5","t":"지방의회에서의 사무감사·조사를 위한 증인의 동행명령장제도는 증인의 신체의 자유를 억압하여 일정 장소로 인치하는 것으로서 헌법 제12조 제3항의 체포 또는 구속에 준하는 사태로 보아야 하므로, 이를 실행하기 위하여는 법관이 발부한 영장의 제시가 있어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-1","t":"사생활의 비밀은 국가가 사생활영역을 들여다보는 것에 대한 보호를 제공하는 기본권이다.","ox":"O","m":"①","c":"A","tp":"사생활의 비밀과 자유"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-2","t":"사생활의 자유란 사회공동체의 일반적인 생활규범의 범위 내에서 사생활을 자유롭게 형성해 나가고 그 설계 및 내용에 대해서 외부로부터의 간섭을 받지 아니할 권리를 말한다.","ox":"O","m":"②","c":"A","tp":"사생활의 비밀과 자유"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-3","t":"흡연자들이 자유롭게 흡연할 권리를 흡연권이라고 한다면, 이러한 흡연권은 인간의 존엄과 행복추구권을 규정한 헌법 제10조와 사생활의 자유를 규정한 헌법 제17조에 의하여 뒷받침된다.","ox":"O","m":"③","c":"A","tp":"사생활의 비밀과 자유"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-4","t":"자동차를 도로에서 운전하는 중에 좌석안전띠를 착용할 것인가의 여부의 생활관계가 개인의 전체적 인격과 생존에 관계되는 사생활의 기본조건이라거나 자기결정의 핵심적 영역 또는 인격적 핵심과 관련된다고 보기 어려우므로, 운전할 때 운전자가 좌석안전띠를 착용하는 문제는 사생활영역의 문제가 아니어서 사생활의 비밀과 자유에 의하여 보호되는 범주를 벗어난 행위이다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-5","t":"교도소장이 수용자가 없는 상태에서 실시한 교도소 수용자의 거실 및 작업장 검사행위는 과잉금지원칙에 위배하여 교도소 수용자의 사생활의 비밀과 자유를 침해한다고 할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-1","t":"개인정보자기결정권은 자신에 관한 정보가 언제 누구에게 어느 범위까지 알려지고 또 이용되도록 할 것인지를 그 정보주체가 스스로 결정할 수 있는 권리로서, 헌법 제10조 제1문에서 도출되는 일반적 인격권 및 헌법 제17조의 사생활의 비밀과 자유에 의하여 보장된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-2","t":"개인정보를 대상으로 한 조사ㆍ수집ㆍ보관ㆍ처리ㆍ이용 등의 행위는 모두 원칙적으로 개인정보자기결정권에 대한 제한에 해당한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-3","t":"직계혈족이기만 하면 아무런 제한 없이 자녀의 가족관계증명서 및 기본증명서의 교부를 청구하여 발급받을 수 있도록 규정한 가족관계의 등록 등에 관한 법률 제15조 제1항은 과잉금지원칙을 위반하여 자녀의 개인정보자기결정권을 침해한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-4","t":"정보주체가 직접 또는 제3자를 통하여 이미 공개한 개인정보라고 하더라도 공개 당시 정보주체가 자신의 개인정보에 대한 수집이나 제3자 제공 등의 처리에 대하여 동의를 하였다고 단정할 수 없으므로, 그 정보를 수집·이용·제공 등 처리하고자 하는 자는 정보주체로부터 별도의 동의를 받아야 한다.","ox":"X","m":"④","c":"A","tp":"개인정보자기결정권"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-5","t":"법률정보 제공 사이트를 운영하는 회사가 공립대학교 법학과 교수의 사진, 성명, 성별, 출생연도, 직업, 직장, 학력, 경력 등 개인정보를 위 법학과 홈페이지 등을 통해 수집하여 위 사이트 내 ‘법조인’ 항목에서 유료로 제공한 경우, 위 회사가 영리 목적으로 개인정보를 수집하여 제3자에게 제공하였더라도 그에 의하여 얻을 수 있는 법적 이익이 정보처리를 막음으로써 얻을 수 있는 정보주체의 인격적 법익에 비하여 우월하므로, 개인정보자기결정권을 침해하는 위법한 행위로 평가할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-1","t":"국방의 의무는 법률이 정하는 바에 따라 부담하므로, 그 구체적인 이행방법과 내용은 법률로 정할 사항이다.","ox":"O","m":"①","c":"A","tp":"양심적 병역거부"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-2","t":"양심적 병역거부의 허용 여부는 헌법 제19조 양심의 자유 등 기본권 규범과 헌법 제39조 국방의 의무 규범 사이의 충돌·조정 문제이다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-3","t":"양심적 병역거부는 소극적 부작위에 의한 양심실현에 해당하므로, 이에 대한 제한은 양심의 자유에 대한 과도한 제한이 되거나 본질적 내용에 대한 위협이 될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-4","t":"양심적 병역거부자에게 병역의무의 이행을 일률적으로 강제하고 그 불이행에 대하여 형사처벌 등 제재를 하는 것은 소수자에 대한 관용과 포용이라는 자유민주주의 정신에도 위배된다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-5","t":"신념이 확고하다는 것은 그것이 유동적이거나 가변적이지 않다는 것을 뜻하지만, 반드시 고정불변이어야 하는 것은 아니므로, 상황에 따라 타협적이거나 전략적으로 행동하는 것을 금지하지는 아니한다. 병역거부자가 그 신념과 관련한 문제에서 상황에 따라 다른 행동을 하였다고 하더라도, 그러한 신념이 진실하지 않다고 단정할 수는 없다.","ox":"X","m":"⑤","c":"A","tp":"양심적 병역거부"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15","t":"양심의 자유에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"양심의 자유에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","d":"㉠양심은 어떤 일의 옳고 그름을 판단할 때 그렇게 행동하지 않고서는 자신의 인격적 존재가치가 파멸되고 말 것이라는 강력하고 진지한 마음의 소리로서 절박하고 구체적인 것이어야 한다.\n㉡양심의 자유는 양심을 형성할 자유와 양심에 따라 결정할 자유 등 내심의 자유일 뿐, 양심을 실현할 수 있는 자유는 포함되지 않는다.\n㉢근로관계의 속성상 사용자가 비위행위를 저지른 근로자에게 자신의 잘못을 반성하고 사죄한다는 내용의 시말서 제출을 명령하는 것은 양심의 자유 침해로 볼 수 없다.\n㉣양심은 내면의 영역이므로 양심적 병역거부 행위는 신념이 확고하고 진실한지 여부와 관계없이 병역법에 따라 처벌할 수 없다.\n㉤국가가 수형자의 가석방 여부를 심사하면서 국법질서나 헌법체제를 준수하겠다는 취지의 준법서약서 제출을 요구한 조치는 양심의 자유와 자유로운 정신세계를 형성할 행복추구권을 침해한다.","o":["1개","2개","3개","4개","5개"],"a":1}},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-1","t":"인터넷회선 감청은 타인과의 관계를 전제로 하는 개인의 사적 영역을 보호하려는 헌법 제18조의 통신의 비밀과 자유 외에 헌법 제17조의 사생활의 비밀과 자유도 제한하므로, 인터넷회선 감청을 범죄수사를 위한 통신제한조치 허가 대상으로 정함에 있어서는 과잉금지원칙을 준수하여야 한다.","ox":"O","m":"①","c":"A","tp":"통신의 비밀과 통신의 자유"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-2","t":"교도소장이 법원, 검찰청 등이 수용자에게 보낸 문서를 열람한 행위는 문서 전달 업무에 정확성을 기하고 수용자의 편의를 도모하여 법령상 기간준수 여부 확인을 위한 공적 자료를 마련하기 위한 것이고, 다른 법령에 따라 열람이 금지된 문서는 열람할 수 없으므로 수용자의 통신의 자유를 침해하지 아니한다.","ox":"O","m":"②","c":"A","tp":"통신의 비밀과 통신의 자유"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-3","t":"통신제한조치기간의 연장을 허가함에 있어 총연장기간 또는 총연장횟수의 제한을 두지 아니한 통신비밀보호법 조항은 통신의 비밀을 침해한다.","ox":"O","m":"③","c":"A","tp":"통신의 비밀과 통신의 자유"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-4","t":"수용자가 밖으로 내보내는 모든 서신을 봉함하지 않은 상태로 교정시설에 제출하도록 하는 것은 수용자의 통신비밀의 자유를 침해한다.","ox":"O","m":"④","c":"A","tp":"통신의 비밀과 통신의 자유"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-5","t":"전기통신역무제공에 관한 계약을 체결하는 경우 전기통신사업자로 하여금 가입자의 인적사항을 확인할 수 있는 증서를 제시하도록 요구하고 부정가입방지시스템을 이용해 본인인지 여부를 확인하도록 한 규정은 익명 가입을 원하는 자의 통신의 자유를 침해한다.","ox":"X","m":"⑤","c":"A","tp":"통신의 비밀과 통신의 자유"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-1","t":"공무원이 선거에서 특정정당 또는 특정인을 지지하기 위하여 타인에게 정당에 가입하도록 권유 운동을 한 경우 형사처벌하는 조항은 공무원의 정치적 표현의 자유를 침해한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-2","t":"당원이 아닌 자에게도 투표권을 부여하는 당내경선에서 지방공기업법에 규정된 시설관리공단의 상근직원이 경선운동을 할 수 없도록 금지하는 조항은 정치적 표현의 자유를 침해한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-3","t":"당내경선에서 이루어지는 경선운동은 원칙적으로 공직선거에서의 당선 또는 낙선을 위한 행위인 선거운동에 해당하지 않으므로, 경선운동을 금지하는 조항이 과잉금지원칙에 반하는지 여부를 판단할 때에는 엄격한 심사기준이 적용되어야 한다.","ox":"O","m":"③","c":"A","tp":"정치적 표현의 자유"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-4","t":"오늘날 정치적 표현의 자유는 자유민주적 기본질서의 구성요소로서 다른 기본권에 비하여 우월한 효력을 가지므로, 공무원이라는 지위에 있다는 이유만으로 정치적 표현의 자유를 전면적으로 부정할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-5","t":"군무원이 연설, 문서 등의 방법으로 정치적 의견을 공표하는 경우 2년 이하의 금고에 처하도록 한 조항은 군무원의 정치적 표현의 자유를 침해하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-1","t":"변호사 또는 소비자로부터 금전·기타 경제적 대가를 받고 법률상담 또는 사건 등을 소개·알선·유인하기 위하여 변호사 등을 광고·홍보·소개하는 행위를 금지하는 대한변호사협회의 변호사 광고에 관한 규정은 헌법소원의 대상이 되는 공권력의 행사에 해당한다.","ox":"O","m":"①","c":"A","tp":"변호사 광고 금지"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-2","t":"대한변호사협회의 유권해석에 반하는 내용의 광고를 금지하고, 대한변호사협회의 유권해석에 위반되는 행위를 목적 또는 수단으로 하여 행하는 법률상담과 관련한 광고를 하거나 그러한 사업구조를 갖는 타인에게 하도록 하는 것을 금지하는 변호사 광고에 관한 규정은 법률유보원칙을 위반하여 변호사들의 표현의 자유, 직업의 자유를 침해한다.","ox":"O","m":"②","c":"A","tp":"변호사 광고 금지"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-3","t":"변호사에 대하여 공정한 수임질서를 저해할 우려가 있는 무료 또는 부당한 염가의 수임료를 표방하거나 무료 또는 부당한 염가의 법률상담 방식을 내세운 광고를 금지하는 것은, 무고한 법률 소비자들의 피해를 막고 정당한 수임료나 법률상담료를 제시하는 변호사들을 보호함으로써 공정한 수임질서를 확립하기 위한 것으로 과잉금지원칙에 위배되지 아니한다.","ox":"O","m":"③","c":"A","tp":"변호사 광고 금지"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-4","t":"변호사 등이 아님에도 변호사 등의 직무와 관련한 서비스의 취급·제공 등을 표시하거나 소비자들이 변호사 등으로 오인하게 만들 수 있는 자에게 광고를 의뢰하거나 참여·협조하는 행위를 금지하는 변호사 광고에 관한 규정은 변호사 자격제도를 유지하고 소비자의 피해를 방지하기 위한 적합한 수단이다.","ox":"O","m":"④","c":"A","tp":"변호사 광고 금지"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-5","t":"변호사 또는 소비자로부터 금전·기타 경제적 대가를 받고 법률상담 또는 사건 등을 소개·알선·유인하기 위하여 변호사 등을 광고·홍보·소개하는 행위를 금지하는 변호사 광고에 관한 규정은 변호사법이 금지하는 특정 변호사에 대한 소개·알선·유인행위의 실질을 갖춘 광고행위를 금지하는 것으로 과잉금지원칙에 위배되지 아니한다.","ox":"X","m":"⑤","c":"A","tp":"변호사 광고 금지"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-1","t":"형제자매는 언제나 본인과 이해관계를 같이 하는 것은 아닌데도 형제자매가 본인에 대한 친족·상속 등과 관련된 증명서를 편리하게 발급받을 수 있도록 규정한 법률조항은 개인정보 자기결정권을 제한하고, 그 제한은 입법목적 달성을 위해 필요한 범위를 넘어선 것으로 개인정보자기결정권을 침해한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-2","t":"형법상 강제추행죄로 유죄판결이 확정된 자는 신상정보 등록대상자가 되도록 규정한 법률조항은 등록대상자 선정에 있어 재범의 위험성을 전혀 요구하지 않고 행위 태양의 특성이나 불법성의 경중을 고려하여 등록대상자의 범위를 축소하고 있지도 않으므로, 과잉금지원칙에 반하여 개인정보자기결정권을 침해한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-3","t":"법무부장관은 변호사시험 합격자가 결정되면 즉시 명단을 공고하여야 한다고 규정한 법률조항은 공공성을 지닌 전문직인 변호사에 관한 정보를 널리 공개하여 법률서비스 수요자가 필요한 정보를 얻는 데 도움을 주기 위한 것으로 응시자들의 개인정보자기결정권을 침해한다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-4","t":"인터넷언론사는 선거운동기간 중 당해 홈페이지 게시판 등에 정당ㆍ후보자 등에 대한 지지ㆍ반대 등의 정보를 게시하는 경우 실명을 확인받는 기술적 조치를 하도록 규정한 법률조항은 익명표현이 허용될 경우 발생할 수 있는 부정적 효과를 막기 위한 것이라 하더라도 모든 익명표현을 규제함으로써 대다수 국민의 개인정보자기결정권도 광범위하게 제한하므로 인터넷언론사 홈페이지 게시판 등 이용자의 개인정보자기결정권을 침해한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-5","t":"성적목적공공장소침입죄로 유죄판결이 확정된 자는 신상정보 등록대상자가 되도록 규정한 법률조항은 등록대상자 선정에 있어 재범의 위험성을 전혀 요구하지 않고 있다 하더라도 위 범죄가 공공화장실 등 일정한 장소를 침입하는 경우에 한하여 성립하고 위 조항에 따른 등록대상자의 범위는 이에 따라 제한되므로, 개인정보자기결정권을 침해한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-1","t":"헌법 제12조 제1항 후문과 제3항에 규정된 적법절차의 원칙은 형사절차상의 제한된 범위에만 적용되고, 행정작용 등에는 적용되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-2","t":"개인정보자기결정권은 자신에 관한 정보가 언제 누구에게 어느 범위까지 알려지고 또 이용되도록 할 것인지를 그 정보주체가 스스로 결정할 수 있는 권리로서, 헌법 제10조 제1문에서 도출되는 일반적 인격권 및 헌법 제17조의 사생활의 비밀과 자유에 의하여 보장된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-3","t":"헌법 제12조 제3항은 “체포·구속·압수 또는 수색을 할 때에는 적법한 절차에 따라 검사의 신청에 의하여 법관이 발부한 영장을 제시하여야 한다.”라고 규정하고, 헌법 제16조는 “주거에 대한 압수나 수색을 할 때에는 검사의 신청에 의하여 법관이 발부한 영장을 제시하여야 한다.”라고 규정함으로써 영장주의를 헌법적 차원에서 보장하고 있다. 우리 헌법이 채택하여 온 영장주의는 형사절차와 관련하여 체포·구속·압수·수색의 강제처분을 함에 있어서는 사법권 독립에 의하여 신분이 보장되는 법관이 발부한 영장에 의하지 않으면 아니 된다는 원칙이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-4","t":"헌법재판소는 법무부장관의 일방적 명령에 의하여 변호사 업무를 정지시키는 것은 당해 변호사가 자기에게 유리한 사실을 진술하거나 필요한 증거를 제출할 수 있는 청문의 기회가 보장되지 아니하여 적법절차를 존중하지 아니한 것이 된다고 보았다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-5","t":"피고인 스스로 치료감호를 청구할 수 있는 권리나, 법원으로부터 직권으로 치료감호를 선고받을 수 있는 권리는 헌법상 재판청구권의 보호범위에 포함되지 않는다. 공익의 대표자로서 준사법기관적 성격을 가지고 있는 검사에게만 치료감호 청구권한을 부여한 것은, 본질적으로 자유박탈적이고 침익적 처분인 치료감호와 관련하여 재판의 적정성 및 합리성을 기하기 위한 것이므로 적법절차원칙에 반하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-1","t":"특정한 정당이나 정치인에 대한 정치자금의 기부는 그의 정치활동에 대한 지지·지원인 동시에 정책적 영향력 행사의 의도 또는 가능성을 내포하고 있다는 점에서 일종의 정치활동 내지 정치적인 의사표현이라 할 것인바, 누구든지 단체와 관련된 자금으로 정치자금을 기부할 수 없도록 한 기부금지 조항은 정치활동의 자유 내지 정치적 의사표현의 자유에 대한 제한이 된다고 볼 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-2","t":"우리 헌법은 제21조 제1항에서 “모든 국민은 언론·출판의 자유……를 가진다.”라고 규정하여 현대 자유민주주의의 존립과 발전에 필수불가결한 기본권으로 언론·출판의 자유를 강력하게 보장하고 있으나, 광고물은 상업적 목적으로 제작된 것으로서 언론·출판의 자유에 의한 보호를 받는 대상이 된다고 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-3","t":"‘청소년이용음란물’ 역시 의사형성적 작용을 하는 의사의 표현·전파의 형식 중 하나임이 분명하므로 언론·출판의 자유에 의하여 보호되는 의사표현의 매개체에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-4","t":"헌법 제21조에서 보장하고 있는 언론·출판의 자유 즉 표현의 자유는 전통적으로는 사상 또는 의견의 자유로운 표명(발표의 자유)과 그것을 전파할 자유(전달의 자유)를 의미하고, 개인이 인간으로서의 존엄과 가치를 유지하고 행복을 추구하며 국민주권을 실현하는데 필수불가결한 것으로서, 종교의 자유, 양심의 자유, 학문과 예술의 자유 등의 정신적인 자유를 외부적으로 표현하는 자유라고 할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-5","t":"종교활동은 헌법상 종교의 자유와 정교분리의 원칙에 의하여 국가의 간섭으로부터 그 자유가 보장되어 있는 것이므로 국가기관인 법원으로서도 종교단체 내부관계에 관한 사항에 대해서는 그것이 일반 국민으로서 권리의무나 법률관계를 규율하는 것이 아닌 이상 원칙적으로 그 실체적인 심리판단을 하지 아니함으로써 당해 종교단체의 자율권을 최대한 보장하여야 할 것이고, 한편 종교단체가 그 교리를 확립하고 종교단체 및 신앙의 질서를 유지하기 위하여 교인으로서의 비위가 있는 자를 종교적인 방법으로 제재하는 것은 종교단체 내부의 규제로서 헌법이 보장하는 종교의 자유의 영역에 속하는 것임에 비추어, 교인의 구체적인 권리 또는 법률관계에 관한 분쟁이 있어 그에 관한 청구의 당부를 판단하는 전제로서 종교단체의 교인에 대한 징계의 당부를 판단하는 것은 별론으로 하더라도, 법원이 그 징계의 효력 그 자체를 사법심사의 대상으로 삼아 효력 유무를 판단할 수는 없다고 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-1","t":"집회의 자유는 개인의 인격발현의 요소이자 민주주의를 구성하는 요소라는 이중적 헌법적 기능을 가지고 있다. 뿐만 아니라, 집회를 통하여 국민들이 자신의 의견과 주장을 집단적으로 표명함으로써 여론의 형성에 영향을 미친다는 점에서, 집회의 자유는 표현의 자유와 더불어 민주적 공동체가 기능하기 위하여 불가결한 근본요소에 속한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-2","t":"집회의 자유는 민주국가에서 정신적 대립과 논의의 수단으로서 보호되므로, 집회의 자유에 의하여 보호되는 것은 ‘평화적’ 또는 ‘비폭력적’ 집회 뿐 아니라 폭력을 사용한 의견의 강요에 해당할지라도 헌법적으로 보호받을 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-3","t":"집회의 목적·내용과 집회의 장소는 일반적으로 밀접한 내적인 연관관계에 있기 때문에, 집회의 장소에 대한 선택이 집회의 성과를 결정짓는 경우가 적지 않다. 집회장소가 바로 집회의 목적과 효과에 대하여 중요한 의미를 가지기 때문에, 누구나 ‘어떤 장소에서’ 자신이 계획한 집회를 할 것인가를 원칙적으로 자유롭게 결정할 수 있어야만 집회의 자유가 비로소 효과적으로 보장되는 것이다. 따라서 집회의 자유는 다른 법익의 보호를 위하여 정당화되지 않는 한, 집회장소를 항의의 대상으로부터 분리시키는 것을 금지한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-4","t":"집회의 자유는 집회의 시간, 장소, 방법과 목적을 스스로 결정할 권리를 보장한다. 집회의 자유에 의하여 구체적으로 보호되는 주요행위는 집회의 준비 및 조직, 지휘, 참가, 집회장소·시간의 선택이다. 따라서 집회의 자유는 개인이 집회에 참가하는 것을 방해하거나 또는 집회에 참가할 것을 강요하는 국가행위를 금지할 뿐만 아니라, 예컨대 집회장소로의 여행을 방해하거나, 집회장소로부터 귀가하는 것을 방해하거나, 집회참가자에 대한 검문의 방법으로 시간을 지연시킴으로써 집회장소에 접근하는 것을 방해하는 등 집회의 자유행사에 영향을 미치는 모든 조치를 금지한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-5","t":"헌법 제21조가 규정하는 결사의 자유라 함은 다수의 자연인 또는 법인이 공동의 목적을 위하여 단체를 결성할 수 있는 자유를 말하는 것으로, 결사의 자유에서 말하는 결사란 자유의사에 기하여 결합하고 조직화된 의사형성이 가능한 단체를 말하는 것이므로 공법상의 결사는 이에 포함되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11-1","t":"수형자가 민사재판에 출정하여 법정 대기실 내 쇠창살 격리시설 안에 유치되어 있는 동안 교도소장이 출정계호교도관을 통해 수형자에게 양손수갑 1개를 앞으로 사용한 행위는 수형자의 신체의 자유를 침해하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11-2","t":"과태료 등의 행정질서벌은 죄형법정주의의 규율대상에 해당하지 않는다.","ox":"O","m":"②","c":"A","tp":"신체의 자유"},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11-3","t":"각급선거관리위원회 위원·직원의 선거범죄 조사에 있어서 피조사자에게 자료제출의무를 부과한 공직선거법의 규정에 의한 자료제출요구는 영장주의의 적용대상이 아니다.","ox":"O","m":"③","c":"A","tp":"신체의 자유"},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11-4","t":"선거관리위원회에 허위보고한 정당의 회계책임자를 형사처벌함으로써 ‘보고’의무를 부과하는 것은 진술거부권이 금지하는 진술강요에 해당한다.","ox":"O","m":"④","c":"A","tp":"신체의 자유"},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11-5","t":"헌법상의 변호인과의 접견교통권은 체포 또는 구속당한 피의자·피고인에게 인정되는 신체적 자유에 관한 기본권인데, ‘변호인이 되려는 자’의 접견교통권은 헌법상 기본권에 해당하지 않는다.","ox":"X","m":"⑤","c":"A","tp":"신체의 자유"},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20-1","t":"수사기관 등에 의한 통신자료 제공요청은 임의수사에 해당하는 것으로, 전기통신사업자가 이에 응하지 아니한 경우에도 어떠한 법적 불이익을 받는다고 볼 수 없으므로, 헌법소원의 대상이 되는 공권력의 행사에 해당하지 않는다.","ox":"O","m":"①","c":"A","tp":"수사기관 등의 통신자료 취득행위"},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20-2","t":"전기통신사업자가 수사기관 등의 통신자료 제공요청에 따라 수사기관 등에 제공하는 이용자의 성명, 주민등록번호, 주소, 전화번호, 아이디, 가입일 또는 해지일은 청구인들의 동일성을 식별할 수 있게 해주는 개인정보에 해당한다.","ox":"O","m":"②","c":"A","tp":"수사기관 등의 통신자료 취득행위"},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20-3","t":"헌법상 영장주의는 체포·구속·압수·수색 등 기본권을 제한하는 강제처분에 적용되므로, 강제력이 개입되지 않은 임의수사에 해당하는 수사기관 등의 통신자료 취득에는 영장주의가 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"수사기관 등의 통신자료 취득행위"},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20-4","t":"수사기관 등이 전기통신사업자에게 이용자의 성명 등 통신자료의 열람이나 제출을 요청할 수 있도록 한 전기통신사업법 조항은 통신자료를 요청할 수 있는 사유를 지나치게 광범위하고 포괄적으로 규정하고 있으므로 과잉금지원칙을 위반하여 개인정보자기결정권을 침해한다.","ox":"X","m":"④","c":"A","tp":"수사기관 등의 통신자료 취득행위"},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20-5","t":"수사기관 등이 전기통신사업자에게 이용자의 성명 등 통신자료의 열람이나 제출을 요청할 수 있도록 한 전기통신사업법 조항은 통신자료 취득에 대한 사후통지 절차를 두지않아 적법절차원칙에 위배하여 개인정보자기결정권을 침해한다.","ox":"O","m":"⑤","c":"A","tp":"수사기관 등의 통신자료 취득행위"},{"y":2025,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2025_31-01","t":"이중처벌금지 원칙에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"이중처벌금지 원칙에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"[다툼이 있는 경우 대법원 판례(전원합의체 판결의 경우 다수의견에 의함) 및 헌법재판소 결정에 의함. 이하 문20까지 같음]","o":["헌법 제13조 제1항에서 금지하는 이중처벌은 거듭된 국가의 형벌권 행사를 금지하는 것일 뿐, 형벌권 행사에 덧붙여 일체의 제재나 불이익처분을 부가할 수 없는 것은 아니다.","형벌과 보호감호를 병과한다고 하여 이중처벌금지 원칙에 위반되는 것은 아니다.","행정법상의 질서벌인 과태료와 형사처벌은 그 성질이나 목적을 달리하는 별개의 것이므로 행정법상의 질서벌인 과태료를 납부한 후에 형사처벌을 한다고 하여 이를 일사부재리의 원칙에 반하는 것이라고 할 수는 없다.","어떤 행정처분에 제재와 억지의 성격․기능만 있다면 이는 실질적으로 ‘국가형벌권의 행사’와 다를 바 없으므로, 헌법 제13조 제1항에서 말하는 ‘처벌’에 해당한다고 보아야 한다.","부당 또는 불법의 이득을 환수 내지 박탈한다는 측면과 위반행위자에 대한 제재로서의 측면을 함께 가지고 있는 부동산 실권리자명의 등기에 관한 법률상의 과징금을 형사처벌과 동시에 병과하는 것은 이중처벌금지 원칙의 문제라기보다 과잉금지원칙의 문제로 그 위헌여부를 판단하여야 한다."],"a":4}},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02-1","t":"‘음란’이란 인간존엄 내지 인간성을 왜곡하는 노골적이고 적나라한 성표현으로서 오로지 성적 흥미에만 호소할 뿐 전체적으로 보아 하등의 문학적, 예술적, 과학적 또는 정치적 가치를 지니지 않은 것으로서, 사회의 건전한 성도덕을 크게 해칠 뿐만 아니라 사상의 경쟁메커니즘에 의해서도 그 해악이 해소되기 어렵다고 하지 않을 수 없다. 따라서 이러한 엄격한 의미의 음란표현은 언론·출판의 자유에 의해서 보호되지 않는다.","ox":"X","m":"①","c":"A","tp":"표현의 자유"},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02-2","t":"헌법 제21조 제1항에서 보장하고 있는 표현의 자유는 사상 또는 의견의 자유로운 표명(발표의 자유)과 그것을 전파할 자유(전달의 자유)를 의미하는 것으로서, 그러한 의사의 자유로운 표명과 전파의 자유에는 자신의 신원을 누구에게도 밝히지 아니한 채 익명 또는 가명으로 자신의 사상이나 견해를 표명하고 전파할 익명표현의 자유도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02-3","t":"표현의 자유에 있어 의사표현 또는 전파의 매개체는 어떠한 형태이건 가능하며 그 제한이 없는바, 인터넷게시판은 인터넷에서 의사를 형성·전파하는 매체로서의 역할을 담당하고 있으므로 의사의 표현·전파 형식의 하나로서 인정된다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02-4","t":"헌법 제21조 제2항이 금지하는 검열은 사전검열만을 의미하므로 개인이 정보와 사상을 발표하기 이전에 국가기관이 미리 그 내용을 심사·선별하여 일정한 범위 내에서 발표를 저지하는 것만을 의미하고, 헌법상 보호되지 않는 의사표현에 대하여 공개한 뒤에 국가기관이 간섭하는 것을 금지하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"표현의 자유"},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02-5","t":"심의기관에서 허가절차를 통하여 영화의 상영 여부를 종국적으로 결정할 수 있도록 하는 것은 검열에 해당하나, 영화의 상영으로 인한 실정법위반의 가능성을 사전에 막고 청소년 등에 대한 상영이 부적절할 경우 이를 유통단계에서 효과적으로 관리할 수 있도록 미리 등급을 심사하는 것은 사전검열이 아니다.","ox":"O","m":"⑤","c":"A","tp":"표현의 자유"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-1","t":"헌법 제12조 제4항 및 제12조 제5항 제1문은 형사절차에서 체포·구속된 사람이 가지는 변호인의 조력을 받을 권리를 헌법상 기본권으로 명시하고 있고, 체포·구속된 사람뿐만 아니라 불구속 피의자 및 피고인의 경우에도 헌법상 법치국가원리, 적법절차원칙에 의하여 변호인의 조력을 받을 권리가 당연히 인정된다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-2","t":"피의자 및 피고인이 가지는 변호인의 조력을 받을 권리가 실질적으로 확보되기 위해서는, 피의자 및 피고인에 대한 변호인의 조력할 권리의 핵심적인 부분이 헌법상 기본권으로서 보호되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-3","t":"변호인의 조력을 받을 권리의 출발점은 변호인선임권에 있고, 이는 변호인의 조력을 받을 권리의 가장 기초적인 구성부분으로서 법률로써도 제한할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-4","t":"헌법 제12조 제4항 본문은 “누구든지 체포 또는 구속을 당한 때에는 즉시 변호인의 조력을 받을 권리를 가진다.”라고 규정하고 있는바, 이와 같은 변호인의 조력을 받을 권리는 형사절차에서 피의자 또는 피고인의 방어권 보장을 위한 것으로서 출입국관리법상 보호 또는 강제퇴거의 절차에 적용된다고 보기는 어렵다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-5","t":"변호인과의 자유로운 접견은 신체구속을 당한 사람에게 보장된 변호인의 조력을 받을 권리의 가장 중요한 내용이어서 국가안전보장, 질서유지, 공공복리 등 어떠한 명분으로도 제한될 수 있는 성질의 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01","t":"죄형법정주의에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"죄형법정주의에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"[다툼이 있는 경우 대법원 판례(전원합의체 판결의 경우 다수의견에 의함) 및 헌법재판소 결정에 의함. 이하 문20까지 같음]","o":["헌법은 제12조 제1항 제2문 후단에서 “법률과 적법한 절차에 의하지 아니하고는 처벌ㆍ보안처분 또는 강제노역을 받지 아니한다.”라고 규정하고, 제13조 제1항에서 “모든 국민은 행위시의 법률에 의하여 범죄를 구성하지 아니하는 행위로 소추되지 아니하며, 동일한 범죄에 대하여 거듭 처벌받지 아니한다.”라고 규정하여 죄형법정주의를 천명하고 있다.","형벌불소급원칙에서 의미하는 ‘처벌’은 형법에 규정되어 있는 형식적 의미의 형벌 유형에 국한되지 않으며, 범죄행위에 따른 제재의 내용이나 실제적 효과가 형벌적 성격이 강하여 신체의 자유를 박탈하거나 이에 준하는 정도로 신체의 자유를 제한하는 경우에는 형벌불소급원칙이 적용되어야 한다. 그러나 노역장유치는 벌금형에 대한 집행방법으로서 그 자체가 독립된 형벌이 아니므로, 형벌불소급원칙의 적용대상이 된다고 볼 수 없다.","구 노동조합법(1986. 12. 31. 법률 제3925호로 최종 개정되었다가 1996. 12. 31. 법률 제5244호로 공포된 노동조합 및노동관계조정법의 시행으로 폐지된 것) 제46조의3은 그 구성요건을 “단체협약에…위반한 자”라고만 규정함으로써 범죄구성요건의 외피만 설정하였을 뿐 구성요건의 실질적 내용을 직접 규정하지 아니하고 모두 단체협약에 위임하고 있어 죄형법정주의의 기본적 요청인 “법률”주의에 위배되고, 그 구성요건도 지나치게 애매하고 광범위하여 죄형법정주의의 명확성의 원칙에 위배된다.","형법 제122조 중 ‘직무’ 또는 ‘유기’의 의미가 무엇인지, 그에 해당하는 범위가 어디까지인지는 다소 불분명한 점이 있으나 직무유기죄의 입법취지 및 보호법익, 그 적용대상의 특수성 등을 고려할 때, 위와 같은 약간의 불명확성은 법관의 통상적인 해석작용에 의하여 충분히 보완될 수 있고, 건전한 상식과 통상적인 법감정을 가진 일반인 및 형법 제122조의 피적용자인 공무원이라면 금지되는 행위가 무엇인지 예측할 수 있다고 할 것이므로 형법 제122조는 죄형법정주의에서 요구되는 명확성의 원칙에 위배되지 아니한다.","디엔에이감식시료의 채취 및 디엔에이신원확인정보의 수집, 수록, 검색, 회보를 포함하는 디엔에이신원확인정보의 수집⋅이용은 전통적 의미의 형벌이 아닐 뿐 아니라, 범죄수사 및 범죄예방에 이바지하여 국민을 보호하고자 하는 공익을 목적으로 하며, 디엔에이신원확인정보를 통해서 대상자의 행동 자체를 통제하는 것도 아니라는 점에서 디엔에이신원확인정보의 이용 및 보호에 관한 법률 시행 당시 디엔에이감식시료 채취 대상범죄로 이미 징역이나 금고 이상의 실형을 선고받아 그 형이 확정되어 수용 중인 사람에 대하여도 디엔에이감식시료를 채취하고 디엔에이신원확인정보를 데이터베이스에 수록 및 관리할 수 있도록 하고 있는 이 사건 부칙조항이 처벌적인 효과를 가져오는 것은 아니다. 따라서 디엔에이신원확인정보의 수집⋅이용이 범죄의 예방효과를 가지는 보안처분으로서의 성격을 일부 지닌다고 하더라도 이는 형벌과는 구별되는 비형벌적 보안처분으로서 소급입법금지원칙이 적용되지 않는다."],"a":2}},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-1","t":"종교의 자유라는 기본권의 침해와 관련한 불법행위의 성립여부는 사법상의 일반원칙을 규정한 민법 제2조, 제103조, 제750조, 제751조 등을 통해 사법상으로 보호되는 종교에 관한 인격적 법익침해 등의 형태로 구체화되어 논하여져야 한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-2","t":"풍수원성당은 1907년 고딕양식으로 건립된 성당이고 우리나라에서 현존하는 성당 중 세 번째로 오래된 성당으로서 문화재로 보호할 가치가 충분하므로, 국가 등이 풍수원성당을 문화재로 지정하고 일정한 범위 내에서 보호 내지 지원을 하는 것은 정교분리원칙에 위반되지 않는다.","ox":"O","m":"②","c":"A","tp":"종교의 자유"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-3","t":"종교(선교활동)의 자유는 국민에게 그가 선택한 임의의 장소에서 자유롭게 행사할 수 있는 권리까지 보장한다고 할 수 있다.","ox":"X","m":"③","c":"A","tp":"종교의 자유"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-4","t":"청구인이 자신의 자녀들이 재학 중인 공립 초등학교 교정에 설치된 단군상을 철거해 줄 것을 요청하였으나 이를 거부한 공립 초등학교 교장의 행위는 정교분리원칙을 위반하여 자녀교육권을 침해한다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"종교의 자유"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-5","t":"헌법 제20조 제1항의 종교의 자유에 포함되는 종교적 행위의 자유와 종교적 집회⋅결사의 자유는 신앙의 자유와는 달리 절대적 자유는 아니지만, 이를 제한할 경우 헌법 제37조 제2항의 과잉금지원칙을 준수하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-1","t":"헌법 제19조는 “모든 국민은 양심의 자유를 가진다.”라고 규정하여 양심의 자유를 기본권의 하나로 보장하고 있다. 여기에서의 양심은 옳고 그른 것에 대한 판단을 추구하는 가치적⋅도덕적 마음가짐으로, 개인의 소신에 따른 다양성이 보장되어야 하고 그 형성과 변경에 외부적 개입과 억압에 의한 강요가 있어서는 아니 되는 인간의 윤리적 내심영역이다. 보호되어야 할 양심에는 세계관⋅인생관⋅주의⋅신조 등은 물론, 이에 이르지 아니하여도 보다 널리 개인의 인격형성에 관계되는 내심에 있어서의 가치적⋅윤리적 판단도 포함될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-2","t":"연말정산 간소화를 위하여 의료기관에 환자들의 의료비 내역에 관한 정보를 국세청에 제출하는 의무를 부과하고 있는 구 소득세법 규정에 의하여 의사들이 제출해야 되는 내용은 누가, 언제, 어디에서 진료비로 얼마를 지급하였는지에 관한 것으로 개인의 존엄과 인격의 핵심에 관한 내용이 아니다. 따라서 위 규정에 기한 증빙서류 제출의무는 헌법 제19조가 보장하는 양심의 자유의 보호범위에 포함된다고 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-3","t":"구 독점규제 및 공정거래에 관한 법률 제27조에 따른 법위반사실의 공표명령은 법규정의 문언상으로 보아도 단순히 법위반사실 자체를 공표하라는 것일 뿐, 사죄 내지 사과하라는 의미요소를 가지고 있지는 아니하다. 따라서 위 규정 중 ‘법위반사실의 공표’ 부분의 경우 사죄 내지 사과를 강요함으로 인하여 발생하는 양심의 자유의 침해문제는 발생하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-4","t":"양심의 자유 중 양심형성의 자유는 내심에 머무르는 한 절대적으로 보호되는 기본권인 반면, 양심적 결정을 외부로 표현하고 실현할 수 있는 권리인 양심실현의 자유는 법질서에 위배되거나 타인의 권리를 침해할 수 있기 때문에 법률에 의하여 제한될 수 있는 상대적인 자유이다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-5","t":"가해학생에 대한 조치로 피해학생에 대한 서면사과를 규정한 구 학교폭력예방 및 대책에 관한 법률 제17조 제1항 제1호에 따른 서면사과 조치는 내용에 대한 강제 없이 자신의 행동에 대한 반성과 사과의 기회를 제공하는 교육적 조치로 마련된 것이고, 가해학생에게 의견진술 등 적정한 절차적 기회를 제공한 뒤에 학교폭력 사실이 인정되는 것을 전제로 내려지는 조치이며, 이를 불이행하더라도 추가적인 조치나 불이익이 없다. 또한 이러한 서면사과의 교육적 효과는 가해학생에 대한 주의나 경고 또는 권고적인 조치만으로는 달성하기 어렵다. 따라서 위 규정이 가해학생의 양심의 자유와 인격권을 과도하게 침해한다고 보기 어렵다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-1","t":"옥외집회⋅시위에 대한 경찰의 촬영행위는 증거보전의 필요성 및 긴급성, 방법의 상당성이 인정되는 때에는 헌법에 위반된다고 할 수 없으나, 경찰이 옥외집회 및 시위 현장을 촬영하여 수집한 자료의 보관⋅사용 등은 엄격하게 제한하여, 옥외집회⋅시위 참가자 등의 기본권 제한을 최소화해야 한다.","ox":"O","m":"①","c":"A","tp":"집회의 자유"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-2","t":"누구든지 헌법재판소의 결정에 따라 해산된 정당의 목적을 달성하기 위한 집회 또는 시위, 집단적인 폭행, 협박, 손괴, 방화 등으로 공공의 안녕 질서에 직접적인 위협을 끼칠 것이 명백한 집회나 시위를 주최하거나 그러한 집회 또는 시위를 할 것을 선전⋅선동하여서는 아니 된다.","ox":"O","m":"②","c":"A","tp":"집회의 자유"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-3","t":"옥외집회나 시위를 주최하려는 자는 집회의 목적, 일시, 장소 등을 기재한 신고서를 옥외집회나 시위를 시작하기 720시간 전부터 48시간 전에 관할 경찰서장에게 제출하여야 한다. 관할 경찰서장 또는 시ㆍ도경찰청장(이하 ‘관할경찰관서장’이라 한다)은 위 신고서를 접수하면 신고자에게 접수 일시를 적은 접수증을 즉시 내주어야 한다.","ox":"O","m":"③","c":"A","tp":"집회의 자유"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-4","t":"관할경찰관서장은 집회 또는 시위의 시간과 장소가 중복되는 2개 이상의 신고가 있는 경우 그 목적으로 보아 서로 상반되거나 방해가 된다고 인정되면 각 옥외집회 또는 시위 간에 시간을 나누거나 장소를 분할하여 개최하도록 권유하는 등 각 옥외집회 또는 시위가 서로 방해되지 아니하고 평화적으로 개최ㆍ진행될 수 있도록 노력하여야 한다. 관할경찰관서장은 위와 같은 권유가 받아들여지지 아니하면 뒤에 접수된 옥외집회 또는 시위에 대하여 그 집회 또는 시위의 금지를 통고할 수 있다.","ox":"O","m":"④","c":"A","tp":"집회의 자유"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-5","t":"국회의장 공관의 경계 지점으로부터 100미터 이내의 장소에서의 옥외집회 또는 시위를 일률적으로 금지하고, 이를 위반한 집회⋅시위의 참가자를 처벌하는 구 집회 및 시위에 관한 법률 규정은 과잉금지원칙에 반하여 집회의 자유를 침해한다고 볼 수 없다.","ox":"X","m":"⑤","c":"A"}],"6":[{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-1","t":"제헌 헌법은 근로자의 단결, 단체교섭과 단체행동의 자유는 법률의 범위 내에서 보장된다고 규정하였다.","ox":"O","m":"①","c":"A","tp":"근로3권"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-2","t":"취업활동을 할 수 있는 체류자격이 없는 외국인도 노동조합을 결성하거나 노동조합에 가입할 수 있다.","ox":"O","m":"②","c":"A","tp":"근로3권"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-3","t":"헌법은 사립학교 교원의 단체행동권을 제한하는 명문 규정을 두고 있지 않다.","ox":"O","m":"③","c":"A","tp":"근로3권"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-4","t":"노동조합을 설립할 때 행정관청에 설립신고서를 제출하게 하고 그 요건을 충족하지 못하는 경우 행정관청이 설립신고서를 반려하도록 규정한 구 노동조합 및 노동관계조정법 조항은 단체결성에 대한 허가제를 금지하는 헌법 제21조 제2항에 위배되지는 아니하나, 근로자의 단결권에 대한 과도한 침해로서 헌법 제33조 제1항에 위배된다.","ox":"X","m":"④","c":"A","tp":"근로3권"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-5","t":"근로자 개인뿐 아니라 근로자단체도 헌법상 단결권의 주체가 될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"근로3권"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07","t":"사회보장수급권 등에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"사회보장수급권 등에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","d":"가.교도시설에 수용 중인 경우에는 기결수 뿐 아니라 미결수용자에 대하여도 국민건강보험급여를 정지하고 있는 국민건강보험법 규정이 수용자의 건강권, 인간의 존엄성, 행복추구권, 인간다운 생활을 할 권리를 침해하는 것이라고 할 수 없다.\n나.헌법 제34조 제2항 및 제6항의 국가의 사회보장․사회복지 증진의무나 재해예방노력의무 등의 성질에 비추어 국가가 어떠한 내용의 산재보험을 어떠한 범위와 방법으로 시행할지 여부는 입법자의 재량영역에 속하는 문제이고, 산재피해 근로자에게 인정되는 산재보험수급권도 그와 같은 입법재량권의 행사에 의하여 제정된 산재보험법에 의하여 비로소 구체화되는 ‘법률상의 권리’이며, 개인에게 국가에 대한 사회보장․사회복지 또는 재해예방 등과 관련된 적극적 급부청구권은 인정하고 있지 않다.\n다.국가가 인간다운 생활을 보장하기 위한 헌법적 의무를 다하였는지의 여부가 사법적 심사의 대상이 된 경우에는, 국가가 최저생활보장에 관한 입법을 전혀 하지 아니하였다든가 그 내용이 현저히 불합리하여 헌법상 용인될 수 있는 재량의 범위를 명백히 일탈한 경우에 한하여 헌법에 위반된다고 할 수 있다.\n라.공무원연금법상의 각종 급여는 모두 사회보장 수급권으로서의 성격과 아울러 재산권으로서의 성격도 가지고, 그 중 퇴직일시금 및 퇴직수당 수급권은 후불임금 내지 재산권적 성격을 많이 띠고 있는데 비하여, 퇴직연금 수급권은 상대적으로 사회보장적 급여로서의 성격이 강하다.\n마.일정한 법정요건을 갖춰 발생한 산재보험수급권은 구체적인 법적 권리로 보장되고 그 성질상 경제적․재산적 가치가 있는 공법상의 권리로서 헌법상 재산권의 보호대상에 포함된다.","o":["1개","2개","3개","4개","5개"],"a":5}},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-1","t":"중혼의 취소청구권자를 규정하면서 직계비속을 제외한 민법 제818조(2005. 3. 31. 법률 제7427호로 개정된 것)는 합리적인 이유 없이 직계비속을 차별하고 있어, 평등원칙에 위반된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-2","t":"중혼을 혼인취소의 사유로 정하면서 그 취소청구권의 제척기간 또는 소멸사유를 규정하지 않은 민법(2005. 3. 31. 법률 제7427호로 개정된 것) 제816조 제1호 중 ‘제810조의 규정에 위반한 때’ 부분은 중혼의 당사자를 언제든지 혼인의 취소를 당할 수 있는 불안정한 지위로 만들고, 그로 인해 후혼배우자의 인격권과 행복추구권을 침해하며, 다른 혼인 취소사유와 달리 취급하여 평등원칙에 반한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-3","t":"누진과세제도 하에서 혼인한 부부에게 조세부담의 증가를 초래하는 부부자산소득합산과세를 규정하고 있는 구 소득세법 제80조 제1항 제2호는 혼인한 부부를 비례의 원칙에 반하여 사실혼관계의 부부나 독신자에 비하여 차별하는 것으로서 헌법 제36조 제1항에 위반된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-4","t":"호주제는 당사자의 의사나 복리와 무관하게 남계혈통 중심의 가의 유지와 계승이라는 관념에 뿌리박은 특정한 가족관계의 형태를 일방적으로 규정·강요함으로써 개인을 가족 내에서 존엄한 인격체로 존중하는 것이 아니라 가의 유지와 계승을 위한 도구적 존재로 취급하고 있는데, 이는 혼인·가족생활을 어떻게 꾸려나갈 것인지에 관한 개인과 가족의 자율적 결정권을 존중하라는 헌법 제36조 제1항에 부합하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-5","t":"친생부인의 소의 제척기간을 규정한 민법(2005. 3. 31. 법률 제7427호로 개정된 것) 제847조 제1항 중 ‘부(夫)가 그 사유가 있음을 안 날부터 2년내’ 부분은 친생부인의 소의 제척기간에 관한 입법재량의 한계를 일탈하지 않은 것으로서 헌법에 위반되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-1","t":"근로란 소득을 대가로 이루어지는 정신적ㆍ육체적 활동을 의미한다.","ox":"O","m":"①","c":"A","tp":"헌법 제32조에 따른 근로의 권리"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-2","t":"근로의 권리란 인간이 자신의 의사와 능력에 따라 근로관계를 형성하고, 타인의 방해를 받음이 없이 근로관계를 계속 유지하며, 근로의 기회를 얻지 못한 경우에는 국가에 대하여 근로의 기회를 제공하여 줄 것을 요구할 수 있는 권리를 말한다.","ox":"O","m":"②","c":"A","tp":"헌법 제32조에 따른 근로의 권리"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-3","t":"근로의 권리는 국민의 권리이므로 외국인은 그 주체가 될 수 없는 것이 원칙이나, 근로의 권리 중 일할 환경에 관한 권리에 대해서는 외국인의 기본권 주체성을 인정할 수 있다.","ox":"O","m":"③","c":"A","tp":"헌법 제32조에 따른 근로의 권리"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-4","t":"근로의 권리는 국가에 대하여 직접적인 직장존속보장청구권을 보장하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"헌법 제32조에 따른 근로의 권리"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-5","t":"근로의 권리는 근로자 개인뿐 아니라 노동조합도 그 주체가 될 수 있다.","ox":"X","m":"⑤","c":"A","tp":"헌법 제32조에 따른 근로의 권리"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-1","t":"환경권은 명문의 법률규정이나 관계 법령의 규정 취지 및 조리에 비추어 권리의 주체, 대상, 내용, 행사 방법 등이 구체적으로 정립될 수 있어야만 인정되는 것이므로, 사법상의 권리로서의 환경권을 인정하는 명문의 규정이 없으면 환경권에 기하여 직접 방해배제청구권을 인정할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-2","t":"환경영향평가 대상사업이라도 그 대상 지역 밖의 주민의 경우에는 그들이 누리는 환경상의 이익은 공익으로서의 추상적 이익에 해당하므로 대상사업을 허용하는 허가나 승인처분 등의 취소를 구할 원고적격이 전혀 인정되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-3","t":"환경에는 자연환경 뿐 아니라 생활환경까지도 포함된다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-4","t":"환경권은 건강하고 쾌적한 환경에 대한 침해배제를 청구할 수 있는 자유권적 측면과 쾌적한 환경에서 생활할 수 있도록 배려하는 보호·보장청구권의 측면을 모두 가지고 있다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-5","t":"환경보전은 단순히 국가의 노력만으로 이루어지기는 어려우므로 헌법은 국민의 환경보전 노력 의무도 규정하고 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07-1","t":"‘부모의 자녀에 대한 교육권’은 비록 헌법에 명문으로 규정되어 있지는 아니하지만, 이는 모든 인간이 국적과 관계없이 누리는 양도할 수 없는 불가침의 인권이다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07-2","t":"자녀의 교육은 헌법상 부모와 국가에게 공동으로 부과된 과제이지만, 학교교육의 범주내에서는 국가의 교육권한이 헌법적으로 독자적인 지위를 부여받음으로써 부모의 교육권과 함께 자녀의 교육을 담당하고, 학교 밖의 교육영역에서는 원칙적으로 부모의 교육권이 우위를 차지한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07-3","t":"헌법 제31조의 ‘능력에 따라 균등한 교육을 받을 권리’는 학교교육 밖에서의 사적인 교육영역에까지 균등한 교육이 이루어지도록 개인이 별도로 교육을 시키거나 받는 행위를 국가가 금지하거나 제한할 수 있는 근거를 부여하는 수권규범이 아니다.","ox":"O","m":"③","c":"A","tp":"교육권"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07-4","t":"일부 지나친 고액과외교습을 방지하기 위하여 모든 학생으로 하여금 오로지 학원에서만 사적으로 배울 수 있도록 규율한다는 것은 어디에도 그 예를 찾아볼 수 없는 것일 뿐만 아니라 자기결정과 자기책임을 생활의 기본원칙으로 하는 헌법의 인간상이나 개성과 창의성, 다양성을 지향하는 문화국가원리에도 위반된다.","ox":"O","m":"④","c":"A","tp":"교육권"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07-5","t":"학교교과교습학원의 교습시간만을 05:00부터 22:00까지로 제한하는 조례는 학교교과교습학원 운영자들을 개인과외교습자들에 비해 불합리하게 차별하는 것이어서 평등원칙에 위반된다.","ox":"X","m":"⑤","c":"A","tp":"교육권"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-1","t":"의무교육제도는 교육의 자주성·전문성·정치적 중립성 등을 지도원리로하여 국민의 교육을 받을 권리를 뒷받침하기 위한, 헌법상의 교육기본권에 부수되는 제도보장이다.","ox":"O","m":"①","c":"A","tp":"무상교육"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-2","t":"헌법 제31조 제2항은 초등교육과 법률이 정하는 교육을 의무교육으로서 실시하도록 규정하였으므로 초등교육 이외에 어느범위의 교육을 의무교육으로 할 것인가에 대한 결정은 입법자에게 위임되어 있다. 초등교육 이외의 의무교육은 구체적으로 법률에서 이에 관한 규정이 제정되어야 가능하고 초등교육 이외의 의무교육의 실시 범위를 정하는 것은 입법자의 형성의 자유에 속한다.","ox":"O","m":"②","c":"A","tp":"무상교육"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-3","t":"입법자가 중학교교육에 대한 의무교육을 단계적으로 실시하는 것으로 규정함에 따라 아직 중학교교육의 무상 실시라는 혜택을 받지 못하는 지역이 있더라도 이는 그 지역의 주민들에 대하여는 이러한 혜택이 현재로서는 구체적인 헌법상의 권리로서 보장되지 않고 있는 것이며, 그들의 헌법상 보장된 권리가 국가에 의하여 침해되었다고 볼 수는 없다.","ox":"O","m":"③","c":"A","tp":"무상교육"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-4","t":"헌법 제31조 제1항에서 보장되는 교육의 기회균등권은 정신적·육체적 능력 이외의 성별·종교·경제력·사회적 신분 등에 의하여 교육을 받을 기회를 차별하지 아니함과 동시에, 국가가 모든 국민에게 균등한 교육을 받게 하고 특히 경제적 약자가 실질적인 평등교육을 받을 수 있도록 적극적 정책을 실현해야 한다는 것을 의미한다.","ox":"O","m":"④","c":"A","tp":"무상교육"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-5","t":"급식활동이 의무교육에 있어서 필수불가결한 교육 과정이며 이에 소요되는 경비가 의무교육의 실질적인 균등보장을 위한 본질적이고 핵심적인 항목에 해당하므로, 이에 관한 모든 재원마련도 전적으로 국가와 지방자치단체의 몫이 되어야 하므로 급식에 관한 경비를 전면무상으로 하지 않고 그 일부를 학부모의 부담으로 정하고 있는 법률조항들은 의무교육의 무상원칙에 위배된다.","ox":"X","m":"⑤","c":"A","tp":"무상교육"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18-1","t":"헌법상 개인의 존엄과 양성의 평등에 기초한 혼인 및 가족제도에 관한 규정은 혼인과 가족생활을 스스로 결정하고 형성할 수 있는 자유를 함께 보장하고 있다.","ox":"O","m":"①","c":"A","tp":"헌법상 혼인과 가족제도"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18-2","t":"혼인과 가족생활의 보호에 관한 헌법 제36조 제1항은 인간의 존엄과 양성의 평등이 가족생활에서도 보장되어야 한다는 기본권과 제도보장의 성격을 함께 갖는다.","ox":"O","m":"②","c":"A","tp":"헌법상 혼인과 가족제도"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18-3","t":"인간의 존엄과 양성평등의 가족생활의 보장, 나아가 혼인과 가족생활의 구체적인 제도보장인 일부일처제도의 공익적 이익에서 비롯된 중혼금지에 대하여 현행법상 그 어떤 예외도 인정되지 않는다.","ox":"X","m":"③","c":"A","tp":"헌법상 혼인과 가족제도"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18-4","t":"민법에서 중혼의 취소청구권자를 규정하면서 직계비속을 제외한 것은 합리적 사유 없이 직계비속을 차별하는 것이다.","ox":"O","m":"④","c":"A","tp":"헌법상 혼인과 가족제도"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18-5","t":"가족제도는 자율영역이 보장되지만 부모가 자녀의 건강에 반하는 방향으로 자녀교육권을 행사할 경우에는 헌법 제31조에 따라 국가에게도 자녀의 교육에 대한 과제와 의무가 인정되므로 국가는 부모의 자녀교육권을 제한할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"헌법상 혼인과 가족제도"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17-1","t":"헌법상 근로의 권리는 ‘일할 자리에 관한 권리’만이 아니라 ‘일할 환경에 관한 권리’도 의미하는 것이다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17-2","t":"근로자가 퇴직급여를 청구할 수 있는 권리는 헌법 제32조 제1항의 근로의 권리의 본질적인 내용에 해당하므로, 모든 근로자는 헌법상 권리로서 퇴직급여 청구권을 갖는다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17-3","t":"최저임금제는 법률이 정하는 바에 의하여 보장되는 것이므로, 근로자가 최저임금을 청구할 수 있는 권리가 헌법상 근로의 권리로서 바로 보장되는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17-4","t":"근로의 권리는 개인인 근로자가 그 주체가 되는 것이고, 근로자의 모임인 노동조합은 그 주체가 될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17-5","t":"우리 헌법은 연소자의 근로는 특별한 보호를 받는다고 명문으로 규정하고 있다.","ox":"O","m":"⑤","c":"A","tp":"근로의 권리"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-1","t":"헌법 제36조 제1항은 혼인과 가족생활에서 양성의 평등대우를 명하고 있으므로 남녀의 성을 근거로 하여 차별하는 것은 원칙적으로 금지되고, 성질상 오로지 남성 또는 여성에게만 특유하게 나타나는 문제의 해결을 위하여 필요한 예외적 경우에만 성차별적 규율이 정당화된다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-2","t":"1990년 개정 민법의 시행일인 1991. 1. 1.부터 그 이전에 성립된 계모자 사이의 법정혈족관계를 소멸시키도록 한 민법 부칙 조항은 헌법 제36조 제1항에 위반된다.","ox":"X","m":"②","c":"A","tp":"혼인과 가족생활"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-3","t":"헌법 제36조 제1항은 혼인과 가족에 관련되는 공법 및 사법의 모든 영역에 영향을 미치는 헌법원리 내지 원칙규범으로서의 성격을 가지는데, 이는 적극적으로는 적절한 조치를 통해서 혼인과 가족을 지원하고 제3자에 의한 침해 앞에서 혼인과 가족을 보호해야 할 국가의 과제를 포함하며, 소극적으로는 불이익을 야기하는 제한조치를 통해서 혼인과 가족을 차별하는 것을 금지해야 할 국가의 의무를 포함한다.","ox":"O","m":"③","c":"A","tp":"혼인과 가족생활"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-4","t":"소득세법 제61조 제1항이 자산소득합산과세의 대상이 되는 혼인한 부부를 혼인하지 않은 부부나 독신자에 비하여 차별취급하는 것은 헌법상 정당화되지 아니하기 때문에 헌법 제36조 제1항에 위반된다.","ox":"O","m":"④","c":"A","tp":"혼인과 가족생활"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-5","t":"헌법 제36조 제1항은 혼인과 가족생활을 스스로 결정하고 형성할 수 있는 자유를 기본권으로서 보장하고, 혼인과 가족에 대한 제도를 보장한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-1","t":"헌법 제31조 제1항은 “모든 국민은 능력에 따라 균등하게 교육을 받을 권리를 가진다.”라고 규정하고 있는바, 헌법 제31조 제1항의 교육을 받을 권리에는 국민 누구나가 교육에 대한 접근 기회 즉 취학의 기회가 균등하게 보장되어야 하는 것이 포함된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-2","t":"헌법 제31조 제1항은 취학의 기회에 있어서 고려될 수 있는 차별기준으로 ‘능력’을 제시함으로써, 능력 이외의 다른 요소에 의한 차별을 원칙적으로 제한하고 있다. 여기서 ‘능력’이란 ‘수학능력’을 의미하고 학교 입학에 있어서 고려될 수 있는 합리적인 차별기준을 의미한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-3","t":"헌법 제22조 제1항이 보장하고 있는 학문의 자유와 헌법 제31조 제4항에서 보장하고 있는 대학의 자율성에 따라 대학이 학생의 선발 및 전형 등 대학입시제도를 자율적으로 마련할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-4","t":"대학의 자율적 학생 선발권을 내세워 국민의 ‘균등하게 교육을 받을 권리’를 침해할 수 없으며, 이를 위해 대학의 자율권은 일정부분 제약을 받을 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-5","t":"국립교육대학교 등이 수시모집에서의 검정고시 출신자의 지원을 일률적으로 제한하여 실질적으로 검정고시 출신자의 대학입학 기회를 박탈하는 결과를 초래하더라도 이는 검정고시 출신자들에게 정규 고등학교의 학교생활기록부가 없어 품성과 자질 등을 다방면에서 평가할 자료가 없기 때문이므로, 합리적 차별이라고 볼 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-1","t":"비례의 원칙은 법치국가 원리에서 파생되는 헌법상의 기본원리로서 모든 국가작용에 적용되는 것이므로, 법원이 장애인차별금지 및 권리구제 등에 관한 법률에 따른 적극적 조치 판결을 할 때에도 원고와 피고를 비롯한 모든 이해관계인들의 공익과 사익을 종합적으로 비교ㆍ형량하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-2","t":"장애인 고용부담금은 재정적인 목적보다는 고용에 어려움을 겪는 장애인의 고용촉진을 주된 목적으로 하는 유도적ㆍ조정적 특별부담금의 성격이 강하다고 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-3","t":"보건복지부장관이 장애인차량 엘피지 보조금 지원사업과 관련하여 4~6급 장애인에 대한 지원을 중단하기로 하는 정책결정을 내리고, 이에 따라 일선 공무원들에 대한 지침을 변경한 것은 헌법소원의 대상인 공권력 행사에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-4","t":"특정 직군에 우선 임용될 기회의 보장이나 장애인 구분모집에 응시할 기회의 보장은 공무담임권의 보호영역에 속하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-5","t":"국회의원선거 당일 투표소에 수화통역인을 배치하도록 하는 내용의 법률을 제정할 헌법상 작위의무가 인정된다고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"장애인"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18-1","t":"특정 지역에 혁신도시를 건설해줄 것을 요구하는 권리는 헌법 제35조가 보장하는 환경권에 포함되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18-2","t":"어느 토지나 건물의 소유자가 종전부터 향유하고 있던 경관이나 조망, 조용하고 쾌적한 종교적 환경 등이 그에게 하나의 생활이익으로서의 가치를 가지고 있다고 객관적으로 인정된다면 법적인 보호의 대상이 될 수 있다.","ox":"O","m":"②","c":"A","tp":"환경권"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18-3","t":"헌법 제35조 제1항은 환경정책에 관한 국가적 규제와 조정을 뒷받침하는 헌법적 근거이므로, 이로부터 환경부장관이 자동차 제작자에게 자동차교체명령을 하여야 할 구체적이고 특정한 작위의무가 도출된다고 볼 수 있다.","ox":"X","m":"③","c":"A","tp":"환경권"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18-4","t":"일상생활에서 소음을 제거ㆍ방지하여 ‘정온한 환경에서 생활할 권리’도 환경권의 한 내용을 구성한다고 볼 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18-5","t":"다가구주택의 가구수제한은 헌법 제35조가 요구하는 쾌적한 환경에서 국민이 주거생활을 영위할 수 있도록 노력하여야 할 국가의 의무를 구체화⋅현실화한 것이다.","ox":"O","m":"⑤","c":"A","tp":"환경권"}],"1":[{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-1","t":"출생 당시에 부(父) 또는 모(母)가 대한민국의 국민인 자, 부모가 모두 분명하지 아니한 경우나 국적이 없는 경우에는 대한민국에서 출생한 자는 출생과 동시에 대한민국 국적(國籍)을 취득한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-2","t":"대한민국의 국민이 아닌 자로서 대한민국의 국민인 부 또는 모에 의하여 인지(認知)된 자가 ‘대한민국의 민법상 미성년이고, 출생 당시에 부 또는 모가 대한민국의 국민이었던 경우’에는 법무부장관에게 신고함으로써 대한민국 국적을 취득할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-3","t":"국적법상 일반귀화 요건은 ‘5년 이상 계속하여 대한민국에 주소가 있을 것, 대한민국의 민법상 성년일 것, 품행이 단정할 것, 자신의 자산(資産)이나 기능(技能)에 의하거나 생계를 같이하는 가족에 의존하여 생계를 유지할 능력이 있을 것, 국어능력과 대한민국의 풍습에 대한 이해 등 대한민국 국민으로서의 기본 소양(素養)을 갖추고 있을 것’이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-4","t":"‘대한민국에 특별한 공로가 있는 자’나 ‘과학·경제·문화·체육 등 특정 분야에서 매우 우수한 능력을 보유한 자로서 대한민국의 국익에 기여할 것으로 인정되는 자’는 대한민국에 주소가 없어도 귀화허가를 받을 수 있다.","ox":"X","m":"④","c":"A","tp":"국적"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-5","t":"법무부장관은 귀화신청인이 귀화 요건을 갖추었다 하더라도 귀화를 허가할 것인지 여부에 관하여 재량권을 가진다.","ox":"O","m":"⑤","c":"A","tp":"국적"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-1","t":"지방자치제도의 헌법적 보장은 한마디로 국민주권의 기본원리에서 출발하여 주권의 지역적 주체로서의 주민에 의한 자기통치의 실현으로 요약할 수 있고, 이러한 지방자치의 본질적 내용인 핵심영역은 어떠한 경우라도 입법 기타 중앙정부의 침해로부터 보호되어야 한다는 것을 의미한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-2","t":"제도적 보장으로서 주민의 자치권은 원칙적으로 개별 주민들에게 인정된 권리라 볼 수 없으며, 청구인들의 주장을 주민들의 지역에 관한 의사결정에 참여 내지 주민투표에 관한 권리침해로 이해하더라도 이러한 권리를 헌법이 보장하는 기본권인 참정권이라고 할 수 없고, 헌법상의 주민자치의 범위는 법률에 의하여 형성되고, 핵심영역이 아닌 한 법률에 의하여 제한될 수 있는 것이다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-3","t":"지방자치단체가 조례를 제정할 수 있는 사항은 지방자치단체의 고유사무인 자치사무와 개별 법령에 의하여 지방자치단체에 위임된 단체위임사무에 한하고, 국가사무가 지방자치단체의 장에게 위임되거나 상위 지방자치단체의 사무가 하위 지방자치단체의 장에게 위임된 기관위임사무에 관한 사항은 원칙적으로 조례의 제정범위에 속하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-4","t":"지방자치단체장이 ‘궐위된 경우, 공소 제기된 후 구금상태에 있는 경우, 금고 이상의 형을 선고받고 그 형이 확정되지 아니한 경우’에는 부단체장이 그 권한을 대행한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-5","t":"지방자치단체의 세자녀 이상 세대 양육비 등 지원에 관한 조례안은 지방자치단체 고유의 자치사무 중 주민의 복지증진에 관한 사무에 해당되고, 위 조례안에는 주민의 편의 및 복리증진에 관한 내용을 담고 있어 그 제정에 있어서 반드시 법률의 개별적 위임이 따로 필요한 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-1","t":"정당해산심판제도는 정부의 일방적인 행정처분에 의해 진보적 야당이 등록취소되어 사라지고 말았던 우리 현대사에 대한 반성의 산물로서 도입된 것으로서, 발생사적 측면에서 정당을 보호하기 위한 절차로서의 성격이 부각된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-2","t":"모든 정당의 존립과 활동은 최대한 보장되며, 설령 어떤 정당이 민주적 기본질서를 부정하고 이를 적극적으로 공격하는 것으로 보인다 하더라도 국민의 정치적 의사형성에 참여하는 정당으로서 존재하는 한 헌법에 의해 최대한 두텁게 보호된다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-3","t":"강제적 정당해산은 헌법상 핵심적인 정치적 기본권인 정당활동의 자유에 대한 근본적 제한이므로, 이에 관한 결정을 할 때 헌법 제37조 제2항이 규정하고 있는 비례원칙을 준수해야만 하고, 따라서 헌법 제8조 제4항의 명문규정상 요건이 구비된 경우에도 해당 정당의 위헌적 문제성을 해결할 수 있는 다른 대안적 수단이 없고, 정당해산결정을 통하여 얻을 수 있는 사회적 이익이 정당해산결정으로 인해 초래되는 정당활동 자유 제한으로 인한 불이익과 민주주의 사회에 대한 중대한 제약이라는 사회적 불이익을 초과할 수 있을 정도로 큰 경우에 한하여 정당해산결정이 헌법적으로 정당화될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-4","t":"정당에 보조금을 배분함에 있어 교섭단체의 구성 여부에 따라 차등을 두는 정치자금에 관한 법률(2004. 3. 12. 법률 제7191호로 개정되고, 2005. 8. 4. 법률 제7682호로 전문 개정되기 전의 것) 제18조 제1항 내지 제3항은 정당 간의 경쟁상태를 현저하게 변경시킬 정도로 합리성을 결여한 차별이라고 보기 어렵다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-5","t":"국회의원선거에 참여하여 의석을 얻지 못하고 유효투표총수의 100분의 2 이상을 득표하지 못한 정당에 대해 그 등록을 취소하도록 한 정당법(2005. 8. 4. 법률 제7683호로 개정된 것) 제44조 제1항 제3호는 정당설립의 자유를 침해한다고 볼 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-1","t":"우리 헌법상의 자유민주적 기본질서의 내용은 기본적 인권의 존중, 권력분립, 의회제도, 복수정당제도, 선거제도, 사유재산과 시장경제를 골간으로 한 경제질서 및 사법권의 독립 등을 의미한다.","ox":"O","m":"①","c":"A","tp":"헌법의 기본원리"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-2","t":"우리 헌법상의 경제질서는 사유재산제를 바탕으로 하고 자유경쟁을 존중하는 자유시장경제질서를 기본으로 하면서도 이에 수반되는 갖가지 모순을 제거하고 사회복지ㆍ사회정의를 실현하기 위하여 국가적 규제와 조정을 용인하는 사회적 시장경제질서로서의 성격을 띠고 있다.","ox":"O","m":"②","c":"A","tp":"헌법의 기본원리"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-3","t":"문화의 개방성 내지 다원성과 연결되는 문화국가원리의 특성으로 인하여 국가의 문화육성의 대상에는 엘리트문화뿐만 아니라 서민문화, 대중문화도 포함되어야 한다.","ox":"O","m":"③","c":"A","tp":"헌법의 기본원리"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-4","t":"자기책임의 원리는 인간의 자유와 유책성, 그리고 인간의 존엄성을 진지하게 반영한 원리로서 그것이 비단 민사법이나 형사법에 국한된 원리가 아니라 근대법의 기본이념으로서 법치주의에 당연히 내재하는 원리이며, 이에 반하는 제재는 그 자체로 헌법위반을 구성한다.","ox":"O","m":"④","c":"A","tp":"헌법의 기본원리"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-5","t":"헌법의 기본원리는 헌법의 이념적 기초인 동시에 헌법을 지배하는 지도원리로서, 입법이나 정책결정의 방향을 제시하며 공무원을 비롯한 모든 국민ㆍ국가기관이 헌법을 존중하고 수호하도록 하는 지침이 되며, 구체적 기본권을 도출하는 근거가 될 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-1","t":"저항권은 고대 그리스 도시국가에서 참주에 대한 국외추방제도나 고대 중국의 사상가인 맹자(孟子)의 역성혁명론에서 그 사상적 기원을 찾을 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-2","t":"저항권은 자연권으로 발전되었고, 영국의 대헌장, 미국의 독립선언서, 프랑스의 1789년 인권선언에서 실정화되었으나, 대한민국의 헌법에는 저항권이 명문으로 규정되어 있지는 않다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-3","t":"저항권은 공권력의 행사자가 민주적 기본질서를 침해하거나 파괴하려는 경우 이를 회복하기 위하여 국민이 공권력에 대하여 폭력ㆍ비폭력, 적극적ㆍ소극적으로 저항할 수 있는 국민의 권리이자 헌법수호제도를 의미한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-4","t":"저항권은 공권력의 행사에 대한 실력적 저항이어서 그 본질상 질서교란의 위험이 수반되므로, 저항권의 행사에는 개별 헌법조항에 대한 단순한 위반이 아닌 민주적 기본질서라는 전체적 질서에 대한 중대한 침해가 있거나 이를 파괴하려는 시도가 있어야 하고, 이미 유효한 구제수단이 남아 있지 않아야 한다는 보충성의 요건이 적용된다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-5","t":"저항권은 민주적 기본질서의 유지, 회복을 목적으로 저항할 수 있을 뿐, 기존의 위헌적인 정권을 물러나게 하기 위한 목적으로는 행사할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-1","t":"국적은 성문의 법령을 통해서가 아니라 국가의 생성과 더불어 존재하는 것이므로, 헌법의 위임에 따라 국적법이 제정되나 그 내용은 국가의 구성요소인 국민의 범위를 구체화, 현실화하는 헌법사항을 규율하고 있는 것이다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-2","t":"거주ㆍ이전의 자유는 국가의 간섭 없이 자유롭게 거주와 체류지를 정할 수 있는 자유로서 정치ㆍ경제ㆍ사회ㆍ문화 등 모든 생활영역에서 개성신장을 촉진함으로써 헌법상 보장되고 있는 다른 기본권들의 실효성을 증대시켜 주는 기능을 하며, 국내에서 체류지와 거주지를 자유롭게 정할 수 있는 자유영역뿐 아니라 나아가 국외에서 체류지와 거주지를 자유롭게 정할 수 있는 ‘해외여행 및 해외 이주의 자유’를 포함하고 덧붙여 대한민국의 국적을 이탈할 수 있는 ‘국적변경의 자유’도 포함한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-3","t":"1948년 세계인권선언 제15조 제2항이 ‘누구를 막론하고 불법하게 그 국적을 박탈당하지 아니하여야 하며 그 국적변경의 권리가 거부되어서는 아니 된다.’는 규정을 두고 있으나, ‘이중국적자의 국적선택권’이라는 개념은 별론으로 하더라도, 일반적으로 외국인인 개인이 특정한 국가의 국적을 선택할 권리가 자연권으로서 또는 우리 헌법상 당연히 인정된다고는 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-4","t":"헌법상 영토조항에 따라 북한지역도 대한민국의 영토에 속하는 한반도의 일부를 이루는 것이어서 대한민국의 주권이 미치고, 북한주민도 대한민국 국적을 취득ㆍ유지하는 데 아무런 영향이 없다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-5","t":"우리 헌법이 ‘대한민국의 영토는 한반도와 그 부속도서로 한다’는 영토조항을 두고 있는 이상 북한지역은 당연히 대한민국의 영토가 되며, 개별 법률의 적용에서 북한지역을 외국에 준하는 지역으로, 북한의 주민 또는 법인 등을 외국인에 준하는 지위에 있는 자로 규정하는 것은 헌법상 영토조항에 위반되어 허용될 수 없다.","ox":"X","m":"⑤","c":"A","tp":"국적"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-1","t":"법치국가의 원리는 국가작용이 법에 의해 이루어져야 한다는 것을 의미한다.","ox":"O","m":"①","c":"A","tp":"헌법상 법치국가의 원리"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-2","t":"실정법이 규율하고자 하는 내용이 명확하여 다의적으로 해석ㆍ적용되어서는 안 된다는 명확성의 원칙은 법치국가의 원리에서 파생된 원칙이다.","ox":"O","m":"②","c":"A","tp":"헌법상 법치국가의 원리"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-3","t":"헌법 제75조에서 규정된 포괄위임금지의 원칙은 법률의 명확성의 원칙이 행정입법에 관하여 구체화된 특별규정이다.","ox":"O","m":"③","c":"A","tp":"헌법상 법치국가의 원리"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-4","t":"법령에 따른 개인의 행위가 국가에 의해서 일정방향으로 유인된 신뢰의 행사라고 볼 수 있어 특별히 보호가치가 있는 신뢰이익이 인정된다면, 아무리 법적 상태의 변화에 대한 개인의 예측가능성이 있더라도 그 개인의 신뢰는 언제나 보호되어야 한다.","ox":"X","m":"④","c":"A","tp":"헌법상 법치국가의 원리"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-5","t":"과거에 완성된 사실 또는 법률관계를 규율하는 진정 소급입법은 특단의 사정이 없는 한 구법에서 이미 얻은 자격 또는 권리를 존중해야 하나, 이미 과거에 시작되었으나 아직 완성되지 아니하고 진행과정에 있는 사실관계 또는 법률관계를 규율하는 부진정 소급입법의 경우에는 특단의 사정이 없는 한 구법관계 내지 구법상의 기대이익을 존중하여야 할 입법의무가 없다.","ox":"O","m":"⑤","c":"A","tp":"헌법상 법치국가의 원리"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-1","t":"법치국가원리의 한 표현인 명확성의 원칙은 기본적으로 모든 기본권제한입법에 대하여 요구된다. 규범의 의미내용으로부터 무엇이 금지되는 행위이고 무엇이 허용되는 행위인지를 수범자가 알 수 없다면 법적 안정성과 예측가능성은 확보될 수 없게 될 것이고, 또한 법집행 당국에 의한 자의적 집행을 가능하게 할 것이기 때문이다.","ox":"O","m":"①","c":"A","tp":"법률의 명확성 원칙"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-2","t":"민주사회에서 표현의 자유가 수행하는 역할과 기능에 비추어 볼 때, 불명확한 규범에 의한 표현의 자유의 규제는 헌법상 보호받는 표현에 대한 위축적 효과를 수반하기 때문에, 표현의 자유를 규제하는 입법에 있어서 명확성의 원칙은 특별히 중요한 의미를 지닌다.","ox":"O","m":"②","c":"A","tp":"법률의 명확성 원칙"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-3","t":"처벌법규나 조세법규와 같이 국민의 기본권을 직접적으로 제한하거나 침해할 소지가 있는 법규에 대해서는 명확성의 원칙이 적용되지만, 국민에게 수익적인 급부행정 영역이나 규율대상이 지극히 다양하거나 수시로 변화하는 성질의 것일 때에는 명확성 원칙이 적용되지 않는다.","ox":"X","m":"③","c":"A","tp":"법률의 명확성 원칙"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-4","t":"모든 법규범의 문언을 순수하게 기술적 개념만으로 구성하는 것은 입법기술적으로 불가능하고 또 바람직하지도 않기 때문에 어느 정도 가치개념을 포함한 일반적, 규범적 개념을 사용하지 않을 수 없으므로, 명확성의 원칙이란 기본적으로 최대한이 아닌 최소한의 명확성을 요구하는 것이다.","ox":"O","m":"④","c":"A","tp":"법률의 명확성 원칙"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-5","t":"법문언이 법관의 해석을 통해서 그 의미내용을 확인해낼 수 있고, 그러한 해석이 해석자의 개인적인 취향에 따라 좌우될 가능성이 없다면 명확성의 원칙에 반한다고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"법률의 명확성 원칙"},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15-1","t":"정당은 그 목적·조직과 활동이 민주적이어야 하며, 국민의 정치적 의사형성에 참여하는 데 필요한 조직을 가져야 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15-2","t":"정당의 목적이나 활동이 민주적 기본질서에 위배될 때에는 정부는 헌법재판소에 그 해산을 제소할 수 있고, 정당은 헌법재판소의 심판에 의하여 해산한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15-3","t":"정당설립의 자유는 개인이 정당 일반 또는 특정 정당에 가입하지 아니할 자유, 가입했던 정당으로부터 탈퇴할 자유 등 소극적 자유도 포함한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15-4","t":"정당설립의 자유는 자신들이 원하는 명칭을 사용하여 정당을 설립하거나 정당활동을 할 자유도 포함한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15-5","t":"정당이 비례대표국회의원선거 및 비례대표지방의회의원선거에 후보자를 추천하는 때에는 그 후보자 중 100분의 30 이상을 여성으로 추천하되, 그 후보자명부의 순위의 매 홀수에는 여성을 추천하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-1","t":"대통령의 임기연장 또는 중임변경을 위한 헌법개정은 그 헌법개정 제안 당시의 대통령에 대하여는 효력이 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-2","t":"헌법개정은 국회재적의원 과반수 또는 대통령의 발의로 제안되고, 제안된 헌법개정안은 대통령이 30일 이상의 기간 이를 공고하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-3","t":"국회는 공고된 날로부터 60일 이내에 의결하여야 하며, 국회의 의결은 재적의원 3분의 2 이상의 찬성을 얻어야 한다.","ox":"O","m":"③","c":"A","tp":"헌법개정"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-4","t":"헌법개정안이 국민투표에서 찬성을 얻은 때에는 헌법개정은 확정되며, 대통령은 즉시 이를 공포하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-5","t":"헌법개정안은 국회가 의결한 후 30일 이내에 국민투표에 붙여 국회의원선거권자 과반수의 투표와 투표자 과반수의 찬성을 얻어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2018_24-18","t":"우리나라의 현행 지방자치제도에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"우리나라의 현행 지방자치제도에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","d":"㉠지방자치단체는 주민의 복리에 관한 사무를 처리하고 재산을 관리하며, 법령의 범위 안에서 자치에 관한 규정을 제정할 수 있다.\n㉡행정혁신을 위해 현행 2단계(특별시, 광역시 등과 시, 군, 구)의 지방자치단체를 1단계로 조정하려면 헌법개정이 필수적이다.\n㉢지방의회의 조직·권한·의원선거와 지방자치단체의 장의 선임방법 기타 지방자치단체의 조직과 운영에 관한 사항은 조례로 정한다.\n㉣지방자치단체의 관할 구역 경계변경은 법률로 정한다.\n㉤지방자치단체에게는 자신의 관할구역 내의 사람과 물건을 배타적으로 지배할 수 있는 권리가 부여되어 있다.","o":["없음","1개","2개","3개","4개"],"a":5}},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-1","t":"중앙선거관리위원회는 국무총리의 제청에 따라 대통령이 임명하는 3인, 국회에서 선출하는 3인, 대법원장이 지명하는 3인의 위원으로 구성한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-2","t":"중앙선거관리위원회의 위원장은 중앙선거관리위원 중에서 대법원장이 지명한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-3","t":"헌법상 중앙선거관리위원회 위원은 정당에 가입하거나 정치에 관여할 수 없고, 다른 공직을 겸직할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-4","t":"행정기관이 선거·국민투표 및 정당관계법령을 제정·개정 또는 폐지하고자 할 때에는 미리 당해 법령안을 중앙선거관리위원회에 송부하여 그 의견을 구하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-5","t":"중앙선거관리위원회 위원은 현행범인이 아니면 체포·구속·소추되지 아니한다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-1","t":"주민소환제란 지방자치단체의 특정한 공직에 있는 자가 주민의 신뢰에 반하는 행위를 하고 있다고 생각될 때 임기 종료 전에 주민이 직접 그 해직을 청구하는 제도로서, 주민에 의한 지방행정 통제의 가장 강력한 수단이며, 주민의 참정기회를 확대하고 주민대표의 정책이나 행정처리가 주민의사에 반하지 않도록 주민대표나 행정기관에 대한 통제와 주민에 대한 책임성을 확보하는 데 그 제도적 의의가 있다.","ox":"O","m":"①","c":"A","tp":"조례"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-2","t":"주민소환제는 주민의 참정기회를 확대하고 주민대표의 정책이나 행정처리가 주민의사에 반하지 않도록 통제하고 책임성을 확보하며 선거제도의 실패를 보완하는 긍정적 기능도 하지만, 선거패배자나 이익단체 등에 의하여 정치적으로 악용·남용되거나, 민주적 정당성에 기반한 선출직 공직자의 활동이 위축되는 등 지방행정의 효율성이 저해되는 결과가 발생될 소지도 없지 않다.","ox":"O","m":"②","c":"A","tp":"조례"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-3","t":"주민소환제의 제도 형성에 관해서는 입법자에게 광범위한 입법재량이 인정되지만, 주민소환제는 주민의 참여를 적극 보장하고 이로써 주민자치를 실현하여 지방자치에도 부합하므로, 주민소환제 자체는 지방자치의 본질적인 내용에 해당한다.","ox":"X","m":"③","c":"A","tp":"조례"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-4","t":"주민소환권은 주민소환제에 부수하여 법률상 창설된 권리일 뿐, 헌법에서 열거되지 아니한 기본권으로 볼 수는 없다.","ox":"O","m":"④","c":"A","tp":"조례"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-5","t":"지방자치법에서 규정한 주민투표권이나 주민소환청구권은 그 성질상 선거권, 공무담임권, 국민투표권과는 다른 것이어서 이를 법률이 보장하는 참정권이라고 할 수 있을지언정 헌법이 보장하는 참정권이라 할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"조례"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17","t":"다음 중 규칙제정권의 규범적 근거가 다른 것은?","c":"A","mc":{"s":"다음 중 규칙제정권의 규범적 근거가 다른 것은?","d":"","o":["국회의 규칙제정권","감사원의 규칙제정권","대법원의 규칙제정권","헌법재판소의 규칙제정권","중앙선거관리위원회의 규칙제정권"],"a":2}},{"y":2019,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2019_25-20","t":"현행 헌법인 1987년 제9차 개정헌법에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"현행 헌법인 1987년 제9차 개정헌법에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["범죄피해자구조청구권제도가 처음 규정되었다.","대한민국 임시정부의 법통 계승이 처음 규정되었다.","현대적 인권인 환경권이 처음 규정되었다.","언론․출판에 대한 허가나 검열과 집회․결사에 대한 허가는 인정되지 않는다는 조항이 부활되었다.","헌법재판제도는 현행 헌법에 최초로 규정된 것이 아니다. 22-5"],"a":3}},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-1","t":"구 지방자치법 제9조 제1항과 제15조 등의 관련 규정에 의하면 지방자치단체는 원칙적으로 그 고유사무인 자치사무와 법령에 의하여 위임된 단체위임사무에 관하여 이른바 자치조례를 제정할 수 있는 외에, 개별 법령에서 특별히 위임하고 있을 경우에는 그러한 사무에 속하지 아니하는 기관위임사무에 관하여도 그 위임의 범위 내에서 이른바 위임조례를 제정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-2","t":"조례가 규정하고 있는 사항이 자치사무나 단체위임사무에 관한 것이라면 이는 자치조례로서 구 지방자치법 제15조가 규정하고 있는 ‘법령의 범위 안'이라는 사항적 한계가 적용될 뿐, 위임조례와 같이 국가법에 적용되는 일반적인 위임입법의 한계가 적용될 여지는 없다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-3","t":"구 지방자치법 제15조에서 말하는 ‘법령의 범위 안’이라는 의미는 ‘법령에 위반되지 아니하는 범위 안’이라는 의미로 풀이되는 것으로서, 특정 사항에 관하여 국가 법령이 이미 존재할 경우에도 그 규정의 취지가 반드시 전국에 걸쳐 일률적인 규율을 하려는 것이 아니라 각 지방자치단체가 그 지방의 실정에 맞게 별도로 규율하는 것을 용인하고 있다고 해석될 때에는 조례가 국가 법령에서 정하지 아니하는 사항을 규정하고 있다고 하더라도 이를 들어 법령에 위반되는 것이라고 할 수가 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-4","t":"지방의회가 조례로 정한 특정한 사항에 관하여는 일정한 기간 내에 반드시 주민투표를 실시하도록 규정한 조례안은 지방자치단체의 장의 고유권한을 침해하는 규정이다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-5","t":"조례가 집행행위의 개입 없이도 그 자체로서 직접 국민의 구체적인 권리의무나 법적 이익에 영향을 미치는 등의 법률상 효과를 발생하는 경우 그 조례는 항고소송의 대상이 되는 행정처분에 해당하고, 이러한 조례에 대한 무효확인소송을 제기함에 있어서 피고적격이 있는 처분 등을 행한 행정청은 행정주체인 지방자치단체이다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-1","t":"법치국가원리의 한 표현인 명확성의 원칙은 기본적으로 모든 기본권 제한입법에 대하여 요구된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-2","t":"규범의 의미내용으로부터 무엇이 금지되는 행위이고 무엇이 허용되는 행위인지를 수범자가 알 수 없다면 법적 안정성과 예측가능성은 확보될 수 없게 될 것이고, 법집행 당국에 의한 자의적 집행을 가능하게 만들 수 있다.","ox":"O","m":"②","c":"A","tp":"명확성의 원칙"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-3","t":"명확성의 원칙은 모든 법률에 있어서 동일한 정도로 요구되는 것은 아니고 개개의 법률이나 법조항의 성격에 따라 요구되는 정도에 차이가 있을 수 있으며 각각의 구성요건의 특수성과 그러한 법률이 제정되게 된 배경이나 상황에 따라 달라질 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-4","t":"일반론으로는 어떠한 규정이 부담적 성격을 가지는 경우에는 수익적 성격을 가지는 경우에 비하여 명확성의 원칙이 더욱 엄격하게 요구되고, 죄형법정주의가 지배하는 형사 관련 법률에서는 명확성의 정도가 강화되어 더 엄격한 기준이 적용되지만, 일반적인 법률에서는 명확성의 정도가 그리 강하게 요구되지 않기 때문에 상대적으로 완화된 기준이 적용된다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-5","t":"명확성의 원칙은 입법자가 법률을 제정함에 있어서 개괄조항이나 불확정 법개념의 사용을 금지한다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-1","t":"정당의 목적이나 활동이 민주적 기본질서에 위배될 때에는 정부는 국무회의의 심의를 거쳐 헌법재판소에 정당해산심판을 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-2","t":"헌법재판소는 정당해산심판의 청구를 받은 때에는 직권 또는 청구인의 신청에 의하여 종국결정의 선고 시까지 피청구인의 활동을 정지하는 결정을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-3","t":"정당은 법률이 정하는 바에 의하여 국가의 보호를 받으며, 국가는 법률이 정하는 바에 의하여 정당운영에 필요한 자금을 보조할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-4","t":"정당의 해산을 명하는 헌법재판소의 결정은 중앙선거관리위원회가 정당법에 따라 집행한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-5","t":"헌법 제8조 제1항은 정당설립의 자유만을 명시적으로 규정하고 있으므로, 정당활동의 자유는 헌법상 기본권으로 보호되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-1","t":"중앙선거관리위원회 위원의 임기는 5년으로 한다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-2","t":"중앙선거관리위원회는 법령의 범위 안에서 선거관리·국민투표관리 또는 정당사무에 관한 규칙을 제정할 수 있고, 법률에 저촉되지 아니하는 범위안에서 내부규율에 관한 규칙을 제정할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-3","t":"중앙선거관리위원회의 위원은 탄핵 또는 금고 이상의 형의 선고에 의하지 아니하고는 파면되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-4","t":"각급 선거관리위원회는 선거인명부의 작성 등 선거사무와 국민투표사무에 관하여 관계 행정기관에 필요한 지시를 할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-5","t":"선거에 관한 경비는 법률이 정하는 경우를 제외하고는 정당 또는 후보자에게 부담시킬 수 없다.","ox":"O","m":"⑤","c":"A","tp":"선거관리"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-1","t":"우리 헌법은 정당을 일반적인 결사의 자유로부터 분리하여 제8조에 독자적으로 규율함으로써, 정당의 특별한 지위를 강조하고 있다.","ox":"O","m":"①","c":"A","tp":"정당제도"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-2","t":"헌법 제8조 제1항 전단의 정당설립의 자유는 정당설립의 자유만이 아니라 누구나 국가의 간섭을 받지 아니하고 자유롭게 정당에 가입하고 정당으로부터 탈퇴할 수 있는 자유를 함께 보장한다.","ox":"O","m":"②","c":"A","tp":"정당제도"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-3","t":"정당의 설립과 활동의 자유를 보장하는 것은 선거제도의 민주화와 국민주권을 실질적으로 현실화하고 정치적으로 자유민주주의 구현에 기여하는 데 그 목적이 있는 것이지 정치의 독점이나 무소속후보자의 진출을 봉쇄하는 정당의 특권을 설정할 수 있는 것을 의미하는 것이 아니다.","ox":"O","m":"③","c":"A","tp":"정당제도"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-4","t":"정당은 단순히 행정부의 통상적인 처분에 의해서는 해산될 수 없고, 오직 헌법재판소가 그 정당의 위헌성을 확인하고 해산의 필요성을 인정한 경우에만 정당정치의 영역에서 배제된다.","ox":"O","m":"④","c":"A","tp":"정당제도"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-5","t":"정당해산심판절차에 민사소송에 관한 법령을 준용하도록 한 헌법재판소법 제40조 제1항은 헌법상 재판을 받을 권리를 침해한다.","ox":"X","m":"⑤","c":"A","tp":"정당제도"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-1","t":"자유민주적 기본질서란 모든 폭력적 지배와 자의적 지배, 즉 반국가단체의 일인독재 내지 일당독재를 배제하고 다수의 의사에 의한 국민의 자치, 자유·평등의 기본원칙에 의한 법치주의적 통치질서를 말한다. 구체적으로는 기본적 인권의 존중, 권력분립, 의회제도, 복수정당제도, 선거제도, 사유재산과 시장경제를 골간으로 한 경제질서 및 사법권의 독립 등을 의미한다.","ox":"O","m":"①","c":"A","tp":"헌법의 기본원리"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-2","t":"우리 헌법상의 경제질서는 사유재산제를 바탕으로 하고 자유경쟁을 존중하는 자유시장경제질서를 기본으로 하면서도 이에 수반되는 갖가지 모순을 제거하고 사회복지·사회정의를 실현하기 위하여 국가적 규제와 조정을 용인하는 사회적 시장경제질서로서의 성격을 띠고 있다.","ox":"O","m":"②","c":"A","tp":"헌법의 기본원리"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-3","t":"우리 헌법은 사회국가원리를 명문으로 규정하고 있지는 않지만, 구체화된 여러 표현을 통하여 사회국가원리를 수용한 것으로 평가할 수 있다.","ox":"O","m":"③","c":"A","tp":"헌법의 기본원리"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-4","t":"사회국가란 사회정의의 이념을 헌법에 수용한 국가, 사회현상에 대하여 방관적인 국가가 아니라 경제·사회·문화의 모든 영역에서 정의로운 사회질서의 형성을 위하여 사회현상에 관여하고 간섭하고 분배하고 조정하는 국가이며, 궁극적으로는 국민 각자가 실제로 자유를 행사할 수 있는 그 실질적 조건을 마련해 줄 의무가 있는 국가이다.","ox":"O","m":"④","c":"A","tp":"헌법의 기본원리"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-5","t":"복수정당제가 우리 헌법상 반드시 보장되는 것은 아니다.","ox":"X","m":"⑤","c":"A","tp":"헌법의 기본원리"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-1","t":"헌법은 방어적 민주주의 관점에 기초하여 정당해산심판제도를 규정하고 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-2","t":"정당의 목적이나 활동이 민주적 기본절서에 위배될 때에는 정부는 헌법재판소에 그 해산을 제소할 수 있다.","ox":"O","m":"②","c":"A","tp":"정당해산심판제도"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-3","t":"정당의 목적이나 활동이 헌법에 위반된 경우, 그 위반이 사소한 위반인 경우에도 그 정당을 해산하는 것이 헌법 정신에 부합한다.","ox":"X","m":"③","c":"A","tp":"정당해산심판제도"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-4","t":"정당 소속원이 민주적 기본질서에 위반된 행위를 하였다고 하더라도, 개인적 차원의 행위에 불과한 것이라면, 이러한 행위에 대해서까지 정당해산심판의 심판대상이 되는 활동으로 보기는 어렵다.","ox":"O","m":"④","c":"A","tp":"정당해산심판제도"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-5","t":"정당해산심판제도는 정치적 비판자들을 탄압하기 위한 용도로 남용되는 일이 생기지 않도록 엄격하고 제한적으로 운용되어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-1","t":"선거운동의 자유는 우리 헌법에 명시되어 있지 않다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-2","t":"예비후보자로 등록한 사람은 선거운동기간 이전이라도 선거운동을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-3","t":"예비후보자로서 선거운동을 할 수 있는 기간을 제한하는 것 자체가 선거운동의 자유를 과도하게 제한하는 것이라고 할 수는 없고, 제한되는 기간을 어느 정도로 할 것인지 여부는 입법정책에 맡겨져 있다고 볼 수 있으며, 그 구체적인 기간이 선거운동의 자유를 형해화할 정도에 이르지 않았다면 이 역시 기본권을 침해하였다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-4","t":"선거운동기간 전에는 문자메시지를 전송하는 방법이나 인터넷 홈페이지 또는 그 게시판ㆍ대화방 등에 글이나 동영상 등을 게시하거나 전자우편을 전송하는 방법으로 선거운동을 하는 것이 허용되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-5","t":"공직선거법이 자치구ㆍ시의 장의 선거에서 예비후보자의 선거운동기간보다 군의 장의 선거에서 예비후보자의 선거운동기간을 단기간으로 정한 것은 합리적 이유 있는 차별로서 평등원칙에 위배되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-1","t":"선거와 국민투표의 공정한 관리 및 정당에 관한 사무를 처리하기 위하여 선거관리위원회를 둔다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-2","t":"중앙선거관리위원회는 대통령이 임명하는 9인의 위원으로 구성하고, 위원장은 위원 중에서 호선한다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-3","t":"중앙선거관리위원회 위원의 임기는 6년으로 한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-4","t":"각급 선거관리위원회는 선거인명부의 작성 등 선거사무와 국민투표사무에 관하여 관계 행정기관에 필요한 지시를 할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-5","t":"선거에 관한 경비는 법률이 정하는 경우를 제외하고는 정당 또는 후보자에게 부담시킬 수 없다.","ox":"O","m":"⑤","c":"A","tp":"선거관리"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-1","t":"대통령령은 법률의 위임이 없어도 법률에 위반되지 않는 범위 내에서 국민의 권리·의무에 관한 사항을 규율할 수 있다.","ox":"X","m":"①","c":"A","tp":"법률유보원칙"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-2","t":"법률이 국민의 기본권 실현과 관련된 영역에 있어서 본질적인 사항에 대하여 스스로 결정하지 않고 행정입법에 위임하였다고 하더라도, 법률유보원칙에 위반되는 것은 아니다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-3","t":"법률유보원칙과 의회유보원칙은 서로 다른 별개의 원리로서 법률유보원칙이 의회유보원칙을 포함하는 것은 아니다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-4","t":"조례에 대한 법률의 위임은 법규명령에 대한 법률의 위임과 같이 반드시 구체적으로 범위를 정하여 할 필요가 없으며 포괄적인 것으로 족하다.","ox":"O","m":"④","c":"A","tp":"법률유보원칙"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-5","t":"입법자가 형식적 법률로 스스로 규율하여야 하는 사항이 어떤 것인지는 일률적으로 획정되어야 한다.","ox":"X","m":"⑤","c":"A","tp":"법률유보원칙"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19-1","t":"헌법상 특정 지방자치단체의 존속이 보장되어야 하므로 법률로 지방자치단체를 폐치·분합하는 것은 허용되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19-2","t":"지방자치단체 상호간에 권한의 유무 또는 범위에 관하여 다툼이 있을 때에는 해당 지방자치단체는 헌법재판소에 권한쟁의심판을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19-3","t":"지방자치단체에는 반드시 지방의회를 두어야 한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19-4","t":"지방자치단체는 주민의 복리에 관한 사무를 처리하고 재산을 관리하며, 법령의 범위 안에서 자치에 관한 규정을 제정할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19-5","t":"지방자치단체가 제정한 조례가 법령에 위반되는 경우에는 효력이 없다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-1","t":"‘소급입법’은 신법이 이미 종료된 사실관계나 법률관계에 적용되는지, 아니면 현재 진행 중인 사실관계나 법률관계에 적용되는지에 따라 ‘진정소급입법’과 ‘부진정소급입법’으로 구분되고, 전자는 헌법상 원칙적으로 허용되지 않고 특단의 사정이 있는 경우에만 예외적으로 허용되는 반면, 후자는 원칙적으로 허용되지만 소급효를 요구하는 공익상의 사유와 신뢰보호 요청 사이의 비교형량 과정에서 신뢰보호의 관점이 입법자의 입법형성권에 일정한 제한을 가하게 된다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-2","t":"신법이 피적용자에게 유리한 경우에는 이른바 시혜적인 소급입법이 가능하지만, 그러한 소급입법을 할 것인지 여부는 그 일차적인 판단이 입법기관에 맡겨져 있으므로 입법자는 입법목적, 사회실정, 법률의 개정 이유나 경위 등을 참작하여 결정할 수 있고, 그 판단이 합리적 재량의 범위를 벗어나 현저하게 불합리하고 불공정한 것이 아닌 한 헌법에 위반된다고 할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-3","t":"공소시효제도는 행위의 가벌성이 아닌 소추가능성에만 연관된 것이기는 하나, 소추가능성은 행위의 가벌성을 전제로 하므로, 원칙적으로 형벌불소급의 원칙이 적용된다.","ox":"X","m":"③","c":"A","tp":"소급입법"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-4","t":"형벌불소급원칙에서 의미하는 ‘처벌’은 형법에 규정되어 있는 형식적 의미의 형벌 유형에 국한되지 않으며, 범죄행위에 따른 제재의 내용이나 실제적 효과가 형벌적 성격이 강하여 신체의 자유를 박탈하거나 이에 준하는 정도로 신체의 자유를 제한하는 경우에는 형벌불소급원칙이 적용되어야 한다.","ox":"O","m":"④","c":"A","tp":"소급입법"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-5","t":"특정 범죄자에 대한 위치추적 전자장치 부착 등에 관한 법률에 의한 전자장치 부착명령은 형벌과 구별되는 비형벌적 보안처분으로서 소급효금지원칙이 적용되지 아니한다.","ox":"O","m":"⑤","c":"A","tp":"소급입법"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-1","t":"현행 헌법은 입법자에게 대한민국의 국민이 되는 요건을 법률로 정할 것을 위임하고 있다.","ox":"O","m":"①","c":"A","tp":"대한민국 국민"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-2","t":"북한주민 역시 일반적으로 대한민국 국민에 포함된다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-3","t":"우리나라의 국적법은 종래 부계혈통주의를 채택한 적이 있다.","ox":"O","m":"③","c":"A","tp":"대한민국 국민"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-4","t":"외국인이 대한민국 국민과 혼인하면 자동으로 대한민국 국적을 취득한다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-5","t":"대한민국 국민이었던 외국인은 법무부장관의 국적회복허가를 받아 대한민국 국적을 취득할 수 있는데, 병역을 기피할 목적으로 대한민국 국적을 상실하였거나 이탈하였던 사람은 제외된다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-1","t":"헌법개정은 국회재적의원 과반수 또는 대통령의 발의로 제안된다.","ox":"O","m":"①","c":"A","tp":"헌법개정 절차"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-2","t":"제안된 헌법개정안은 대통령이 20일 이상의 기간 이를 공고하여야 하고, 국회는 헌법개정안이 공고된 날로부터 60일 이내에 의결하여야 한다.","ox":"O","m":"②","c":"A","tp":"헌법개정 절차"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-3","t":"헌법개정안에 대한 국회의 의결은 재적의원 3분의 2 이상의 찬성을 얻어 확정되고, 대통령은 국회의 의결을 거친 즉시 이를 공포하여야 한다.","ox":"X","m":"③","c":"A","tp":"헌법개정 절차"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-4","t":"대통령의 임기를 연장하거나 중임변경을 위한 헌법개정은 그 헌법개정 제안 당시의 대통령에 대하여는 효력이 없다.","ox":"O","m":"④","c":"A","tp":"헌법개정 절차"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-5","t":"대통령이 발의하는 헌법개정안에 대하여는 국무회의의 심의를 거쳐야 한다.","ox":"O","m":"⑤","c":"A","tp":"헌법개정 절차"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-1","t":"국회의 의결을 거쳐 국민투표에 의하여 개정함을 명백히 밝히고 있다.","ox":"O","m":"①","c":"A","tp":"현행 대한민국헌법의 전문(前文)"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-2","t":"헌법 전문에서 말하는 전통이란 역사성과 시대성을 띤 개념이므로 오늘날의 의미로 포착하여야 한다.","ox":"O","m":"②","c":"A","tp":"현행 대한민국헌법의 전문(前文)"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-3","t":"3·1정신은 우리나라 헌법의 연혁적·이념적 기초로서 헌법이나 법률해석에서의 해석기준으로 작용할 수 있지만, 그에 기초하여 곧바로 국민의 개별적 기본권성을 도출해낼 수는 없다.","ox":"O","m":"③","c":"A","tp":"현행 대한민국헌법의 전문(前文)"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-4","t":"3ㆍ1운동으로 건립된 대한민국임시정부의 법통을 계승한다고 선언한 헌법 전문으로부터 국가의 독립유공자와 그 유족에 대한 예우를 하여야 할 헌법적 의무가 도출될 수 있다.","ox":"O","m":"④","c":"A","tp":"현행 대한민국헌법의 전문(前文)"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-5","t":"3ㆍ1운동의 정신과 4ㆍ19민주이념이 헌법 전문에 함께 규정되어 있는 점을 감안하여 보면, 4ㆍ19혁명공로자에 대한 보훈 수준은 애국지사와 동일하게 설정되어야 한다.","ox":"X","m":"⑤","c":"A","tp":"현행 대한민국헌법의 전문(前文)"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19","t":"정당에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개 인가?","c":"A","mc":{"s":"정당에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개 인가?","d":"㉠정당의 목적이나 활동 중 어느 하나라도 민주적 기본질서에 위배된다면 정당해산의 사유가 될 수 있다.\n㉡정당해산심판제도는 1960. 6. 15. 제3차 헌법 개정을 통해 우리 헌법에 도입되었다.\n㉢정당해산 사유를 규정한 헌법 제8조 제4항의 “민주적 기본질서”는 최대한 엄격하고 협소한 의미로 이해하여야 한다.\n㉣정당이 당원 내지 후원자들로부터 정당의 목적에 따른 활동에 필요한 정치자금을 모금하는 것은 정당활동의 자유의 내용에 당연히 포함된다.\n㉤헌법 제8조 제1항 전단에 규정된 정당설립의 자유에는 정당존속의 자유와 정당활동의 자유가 당연히 포함된다.","o":["없음","1개","2개","3개","4개"],"a":1}},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-1","t":"지방자치법상 공법인인 지방자치단체의 기관으로는 대의기관인 지방의회, 집행기관인 지방자치단체장이 있다.","ox":"O","m":"①","c":"A","tp":"지방자치제도"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-2","t":"지방의회는 조례·규칙의 제정·개정 및 폐지, 예산의 심의·확정, 결산의 승인, 행정사무감사 및 조사권을 가진다.","ox":"X","m":"②","c":"A","tp":"지방자치제도"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-3","t":"지방자치단체는 사무처리를 위한 행정기구를 설치할 수 있고, 소속 공무원에 관한 임용, 징계 등 인사를 스스로 할 수 있다.","ox":"O","m":"③","c":"A","tp":"지방자치제도"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-4","t":"지방자치단체가 기관위임사무에 관한 권한쟁의심판을 청구하는 것은 허용되지 아니한다.","ox":"O","m":"④","c":"A","tp":"지방자치제도"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-5","t":"감사원은 지방자치단체에 대하여 합목적성 감사도 실시할 수 있으나, 중앙행정기관은 지방자치단체에 대하여 합법성 감사만을 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"지방자치제도"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-1","t":"정당은 국민의 이익을 위하여 책임 있는 정치적 주장이나 정책을 추진하고 공직선거의 후보자를 추천 또는 지지함으로써 국민의 정치적 의사형성에 참여함을 목적으로 하는 헌법상 기관이므로, 공권력행사의 주체가 된다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-2","t":"정당은 수도에 소재하는 중앙당과 특별시·광역시·도에 각각 소재하는 시·도당으로 구성하는데, 정당은 5 이상의 시·도당을 가져야 하고, 시·도당은 500명 이상의 당원을 가져야 한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-3","t":"정당이 그 소속 국회의원을 제명하기 위해서는 당헌이 정하는 절차를 거치는 외에 그 소속 국회의원 전원의 2분의 1 이상의 찬성이 있어야 한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-4","t":"헌법재판소의 해산결정에 의하여 해산된 정당의 잔여재산은 당헌이 정하는 바에 따라 처분하고, 처분되지 아니한 정당의 잔여재산은 국고에 귀속한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-5","t":"정당은 등록이 취소된 이후에는 헌법소원의 청구인능력이 없다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-1","t":"선거운동기간 전에 개별적으로 대면하여 말로 하는 선거운동을 금지한 공직선거법 조항은 과잉금지원칙에 반하여 선거운동 등 정치적 표현의 자유를 침해한다.","ox":"O","m":"①","c":"A","tp":"공직선거법상 선거운동"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-2","t":"공개장소에서의 연설·대담장소 또는 대담·토론회장에서 연설·대담·토론용으로 사용하는 경우를 제외하고는 선거운동을 위하여 확성장치를 사용할 수 없도록 한 공직선거법 조항은 과잉금지원칙에 반하여 정치적 표현의 자유를 침해한다.","ox":"X","m":"②","c":"A","tp":"공직선거법상 선거운동"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-3","t":"선거일 전 180일부터 선거일까지 선거에 영향을 미치게 하기 위한 벽보의 게시, 인쇄물의 배부·게시행위를 금지한 공직선거법 조항은 과잉금지원칙에 반하여 정치적 표현의 자유를 침해한다.","ox":"O","m":"③","c":"A","tp":"공직선거법상 선거운동"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-4","t":"누구든지 선거기간 중 선거에 영향을 미치게 하기 위한 그 밖의 집회나 모임의 개최를 금지한 공직선거법 조항은 과잉금지원칙에 반하여 집회의 자유, 정치적 표현의 자유를 침해한다.","ox":"O","m":"④","c":"A","tp":"공직선거법상 선거운동"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-5","t":"선거일 전 180일부터 선거일까지 선거에 영향을 미치게 하기 위한 광고물의 설치·진열·게시나 표시물의 착용을 금지하는 공직선거법 조항은 과잉금지원칙에 반하여 정치적 표현의 자유를 침해한다.","ox":"O","m":"⑤","c":"A","tp":"공직선거법상 선거운동"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-1","t":"법령에서 조례로 정하도록 위임한 사항은 그 법령의 하위법령에서 그 위임의 내용과 범위를 제한하거나 직접 규정할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-2","t":"조례는 고유사무와 단체위임사무에 대하여만 제정할 수 있으며, 기관위임사무와 같은 국가적 사무에 대하여는 조례를 제정할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-3","t":"지방자치법이 지방자치단체의 장의 재량으로 투표실시 여부를 결정할 수 있도록 규정하고 있음에도 일정한 기간 내에 반드시 투표를 실시하도록 규정한 조례안은 지방자치단체의 장의 고유권한을 침해한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-4","t":"주민은 지방세·사용료·수수료·부담금을 부과·징수 또는 감면하는 사항에 대하여 조례의 제정을 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-5","t":"헌법 제117조 및 제118조의 ‘지방자치’에 관한 규정으로부터 지방자치단체와 지역주민들의 자치권이 제도적으로 보장된다.","ox":"X","m":"⑤","c":"A","tp":"조례"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-1","t":"보통선거의 원칙은 선거권자의 능력, 재산, 사회적 지위 등의 실질적인 요소를 배제하고, 성년자이면 누구라도 당연히 선거권을 갖는 것을 요구한다. 따라서 보통선거의 원칙에 반하는 선거권 제한의 입법을 하기 위해서는 헌법 제37조 제2항의 규정에 따른 한계가 한층 엄격히 지켜져야 한다.","ox":"O","m":"①","c":"A","tp":"선거원칙"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-2","t":"평등선거의 원칙은 1인 1표의 원칙과 1표의 투표가치가 대표자 선정이라는 선거의 결과에 대하여 기여한 정도에 있어서도 평등하여야 한다는 원칙(one vote, one value)을 그 내용으로 한다. 또한, 일정한 집단의 의사가 정치과정에서 반영될 수 없도록 차별적으로 선거구를 획정하는, 이른바 ‘게리맨더링’에 대한 부정을 의미하기도 한다.","ox":"O","m":"②","c":"A","tp":"선거원칙"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-3","t":"신체의 장애로 인하여 자신이 기표할 수 없는 선거인에 대해 투표보조인이 가족이 아닌 경우 반드시 2인을 동반하여서만 투표를 보조하게 할 수 있도록 정하고 있는 공직선거법 규정은, 선거인이 자신에게 필요한 투표보조인의 수를 스스로 결정할 수 없게 하고, 2인의 투표보조인에게 투표의 내용을 공개하도록 하여 선거권 행사를 위축시킨다. 따라서 위 규정은 선거의 공정성을 확보하는 데 치우친 나머지 비밀선거의 중요성을 간과하고 있으므로 선거권 제한을 최소화하고 있다고 보기 어려운 점 등에 비추어 과잉금지원칙에 위반된다.","ox":"X","m":"③","c":"A","tp":"선거원칙"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-4","t":"자유선거의 원칙은 헌법에 명문으로 규정되어 있지는 아니하나, 민주국가의 선거제도에 내재하는 법 원리로서, 국민주권의 원리, 의회민주주의의 원리 및 참정권에 관한 규정에서 그 근거를 찾을 수 있다.","ox":"O","m":"④","c":"A","tp":"선거원칙"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-5","t":"일부 선거구의 획정에 위헌성이 있다고 하더라도 선거구구역표는 전체가 불가분적 일체를 이루는 것이므로 선거구구역표의 전부에 관하여 위헌선언을 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"선거원칙"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-1","t":"정당은 헌법 제111조 제1항 제4호 및 헌법재판소법 제62조 제1항 제1호의 ‘국가기관’에 해당한다고 볼 수는 없으나, 사적 결사와 국회 교섭단체로서의 이중적 지위를 가진다는 점에서 권한쟁의심판의 당사자능력이 인정된다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-2","t":"정당의 목적이나 활동이 민주적 기본질서에 위배될 때에는 정부는 국무회의의 심의를 거쳐 헌법재판소에 정당해산심판을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-3","t":"복수 당적 보유가 허용될 경우 정당 간의 위법·부당한 간섭이 발생하거나 정당의 정체성이 약화될 수 있고, 그 결과 정당이 국민의 정치적 의사형성에 참여하고 이러한 목표 달성에 필요한 조직을 갖추어야 한다는 헌법적 과제를 효과적으로 수행하지 못하게 될 우려가 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-4","t":"정당 설립을 위하여 등록을 요구하는 정당등록제도는 어떤 정치적 결사가 정당법상 정당임을 법적으로 확인하여 주는 것에 그치므로 이를 정당의 자유에 대한 과도한 제한이라고 보기 어렵다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-5","t":"헌법재판소는 정당해산심판의 청구를 받은 때에는 직권 또는 청구인의 신청에 의하여 종국결정의 선고시까지 피청구인의 활동을 정지하는 결정을 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-1","t":"주민조례발안에 관한 법률에 따르면 주민은 공공시설 설치의 반대, 행정기구의 설치·변경에 대해서는 조례의 제정이나 개정 또는 폐지를 청구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-2","t":"조례안재의결 무효확인소송에서의 심리대상은 지방의회에 재의를 요구할 당시 이의사항으로 지적되어 재의결에서 심의의 대상이 된 것에 국한되지 아니한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-3","t":"지방자치단체는 조례를 위반한 행위에 대하여 조례로써 1천만 원 이하의 과태료를 정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-4","t":"지방자치단체의 장은 지방의회에서 의결되어 지방자치단체의 장에게 이송된 조례안에 대하여 이의가 있으면 재의 요구를 할 수 있으나, 조례안의 일부에 대한 재의 요구는 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-5","t":"교육감은 교육·학예에 관한 의안 중 주민의 재정적 부담이나 의무 부과에 관한 조례안을 시·도의회에 제출하고자 할 때에는 미리 시·도지사와 협의하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-1","t":"우리 헌법은 국가권력의 남용으로부터 국민의 기본권을 보호하려는 법치국가의 실현을 기본이념으로 하고 있고, 법치국가의 개념은 범죄에 대한 법정형을 정함에 있어 죄질과 그에 따른 행위자의 책임 사이에 적절한 비례관계가 지켜질 것을 요구하는 실질적 법치국가의 이념을 포함하고 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-2","t":"입법자가 형벌이라는 수단을 선택함에 있어서는 그 형벌이 불법과 책임의 경중에 일치하도록 하여야 하고, 만약 선택한 형벌이 구성요건에 기술된 불법의 내용과 행위자의 책임에 일치되지 않는 과도한 것이라면 이는 비례의 원칙을 일탈한 것으로 헌법상 용인될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-3","t":"어떤 범죄를 어떻게 처벌할 것인가 하는 문제, 즉 법정형의 종류와 범위의 선택은 그 범죄의 죄질과 보호법익에 대한 고려뿐만 아니라 우리의 역사와 문화, 입법 당시의 시대적 상황, 국민 일반의 가치관 내지 법감정, 그리고 범죄예방을 위한 형사정책의 측면 등 여러 요소를 종합적으로 고려하여 입법자가 결정할 사항으로서 광범위한 입법재량 내지 형성의 자유가 인정되어야 할 분야이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-4","t":"예비군훈련의 원활한 이행을 위해서는 정당한 사유 없이 훈련에 불응하는 예비군대원을 처벌할 필요가 있고, 이를 위해서는 그 전제로 소집통지서가 예비군대원 본인에게 적법하게 전달이 되어 그 효력이 발생하여야 하기 때문에, 예비군대원 본인의 부재중 소집통지서를 대신 수령한 가족 중 성년자에게 이를 본인에게 전달하도록 의무를 지우는 것이 필요하다고 볼 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-5","t":"예비군대원 본인에 대한 소집통지서의 전달을 확보하기 위하여 예비군대원 본인과 세대를 같이 하면서 본인 대신 소집통지서를 받은 가족 중 성년자에게 전달할 의무를 부여하고, 정당한 사유 없이 이를 전달하지 아니한 경우 6개월 이하의 징역 또는 500만 원 이하의 벌금에 처하는 것이 책임과 형벌 간의 비례원칙에 위반된다고 보기 어렵다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05-1","t":"헌법의 개정이란, 헌법이 정하는 절차에 따라 헌법전의 문구를 명시적으로 바꾸는 것을 말한다. 헌법 개정은 헌법의 현실적합성을 제고하여 헌법의 규범력을 유지하기 위하여 필요하다. 반면 헌법변천이란, 헌법문구의 변경 없이 시대의 변천에 따라 다른 내용의 헌법규범으로 기능하는 것을 말한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05-2","t":"헌법개정은 국회재적의원 과반수 또는 대통령의 발의로 제안된다. 제안된 헌법개정안은 대통령이 20일 이상의 기간 이를 공고하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05-3","t":"헌법은 전문과 단순한 개별조항의 상호관련성이 없는 집합에 지나지 않는 것이 아니고 하나의 통일된 가치체계를 이루고 있는 것이므로, 헌법의 전문과 각 개별규정은 서로 밀접한 관련을 맺고 있고, 이념적⋅논리적으로도 규범 상호 간의 우열을 인정할 수 없다.","ox":"X","m":"③","c":"A","tp":"헌법 개정"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05-4","t":"우리 헌법의 각 개별규정 가운데 무엇이 헌법제정규정이고 무엇이 헌법개정규정인지를 구분하는 것이 가능하지 아니할 뿐 아니라, 각 개별규정에 그 효력상의 차이를 인정하여야 할 형식적인 이유를 찾을 수 없다. 이러한 점과 현행 헌법 및 헌법재판소법의 명문의 규정취지에 비추어, 헌법제정권과 헌법개정권의 구별론이나 헌법개정한계론은 그 자체로서의 이론적 타당성 여부와 상관없이 헌법재판소가 헌법의 개별규정에 대하여 위헌심사를 할 수 있다는 논거로 원용될 수 있는 것이 아니다. 또한 국민투표에 의하여 확정된 현행 헌법의 성립과정과 헌법 제130조 제2항이 헌법의 개정을 국민투표에 의하여 확정하도록 하고 있음에 비추어, 헌법은 그 전체로서 주권자인 국민의 결단 내지 국민적 합의의 결과라고 보아야 할 것으로, 헌법의 규정을 헌법재판소법 제68조 제1항 소정의 공권력 행사의 결과라고 볼 수도 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05-5","t":"헌법개정안은 국회가 의결한 후 30일 이내에 국민투표에 붙여 국회의원선거권자 과반수의 투표와 투표자 과반수의 찬성을 얻어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10","t":"법치주의원리에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"법치주의원리에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["헌법 제12조 제1항은 누구든지 법률과 적법한 절차에 의하지 아니하고는 처벌⋅보안처분 또는 강제노역을 받지 아니한다고 규정하고 있다. 이러한 죄형법정주의의 원칙은 법률이 처벌하고자 하는 행위가 무엇이며 그에 대한 형벌이 어떠한 것인지를 누구나 예견할 수 있고, 그에 따라 자신의 행위를 결정할 수 있게끔 구성요건을 명확하게 규정할 것을 요구한다. 처벌법규의 모든 구성요건은 단순한 의미의 서술적인 개념에 의하여 규정되어야 하고, 법관의 보충적인 해석을 필요로 하는 개념을 사용한 경우에는 처벌법규의 명확성에 배치된다고 보아야 한다.","오늘날의 법률유보원칙은 단순히 행정작용이 법률에 근거를 두기만 하면 충분한 것이 아니라, 국가공동체와 그 구성원에게 기본적이고도 중요한 의미를 갖는 영역, 특히 국민의 기본권 실현에 관련된 영역에 있어서는 행정에 맡길 것이 아니고 국민의 대표자인 입법자 스스로 그 본질적 사항에 대하여 결정하여야 한다는 요구, 즉 의회유보원칙까지 내포하는 것으로 이해되고 있다.","어떠한 사안이 국회가 형식적 법률로 스스로 규정하여야 하는 본질적 사항에 해당되는지는, 구체적 사례에서 관련된 이익 내지 가치의 중요성, 규제 또는 침해의 정도와 방법 등을 고려하여 개별적으로 결정하여야 하지만, 규율대상이 국민의 기본권과 관련한 중요성을 가질수록 그리고 그에 관한 공개적 토론의 필요성 또는 상충하는 이익 사이의 조정 필요성이 클수록, 그것이 국회의 법률에 의하여 직접 규율될 필요성은 더 증대된다.","법치국가원리의 한 표현인 명확성의 원칙은 기본적으로 모든 기본권 제한 입법에 대하여 요구되지만, 모든 법률에 있어서 동일한 정도로 요구되는 것은 아니고 개개의 법률이나 법조항의 성격에 따라 요구되는 정도에 차이가 있을 수 있으며 각각의 구성요건의 특수성과 그러한 법률이 제정되게 된 배경이나 상황에 따라 달라질 수 있다. 특히 민사법규는 행위규범의 측면이 강조되는 형벌법규와는 달리 기본적으로는 재판법규의 측면이 훨씬 강조되므로, 사회현실에 나타나는 여러 가지 현상에 관하여 일반적으로 흠결 없이 적용될 수 있도록 보다 추상적인 표현을 사용하는 것이 상대적으로 더 가능하다고 본다.","포괄위임금지의 원칙은 행정부에 입법을 위임하는 수권법률의 명확성원칙에 관한 것으로서 법률의 명확성 원칙이 위임입법에 관하여 구체화된 특별규정이라고 할 수 있다. 따라서 수권법률조항의 명확성원칙 위배 여부는 헌법 제75조의 포괄위임금지의 원칙의 위반 여부에 대한 심사로써 충족된다."],"a":1}},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-1","t":"1945. 8. 9. 이후 성립된 거래를 전부 무효로 한 재조선미국육군사령부군정청 법령 조항은 진정소급입법에 해당하지만, 이는 소급입법금지원칙에 대한 예외로서 헌법 제13조 제2항에 위반되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-2","t":"현재 공무원으로 재직 중인 자가 퇴직하는 경우 장차 받게 될 퇴직연금의 지급시기를 변경한 것은 아직 완성되지 아니한 사실 또는 법률관계를 규율대상으로 하는 부진정소급입법에 해당하여 원칙적으로 허용될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-3","t":"국민이 가지는 모든 기대 내지 신뢰가 헌법상 권리로서 보호될 것은 아니고, 신뢰의 근거 및 종류, 상실된 이익의 중요성, 침해의 방법 등에 의하여 개정된 법규⋅제도의 존속에 대한 개인의 신뢰가 합리적이어서 권리로서 보호할 필요성이 인정되어야 하고, 특히 조세법의 영역에 있어서는 국가가 조세⋅재정정책을 탄력적⋅합리적으로 운용할 필요성이 매우 큰 만큼, 조세에 관한 법률⋅제도는 신축적으로 변할 수밖에 없으므로, 납세의무자로서는 특별한 사정이 없는 한 원칙적으로 현재의 세법이 변함없이 유지되리라고 기대하거나 신뢰할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-4","t":"실종선고가 1990년 개정민법 시행일 이후에 내려지더라도 실종기간이 구법 시행 중에 만료된 경우에 상속에 관하여 개정민법의 규정이 적용된다면 재산권 제한에 관하여 진정소급입법의 성격을 가진다고 할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-5","t":"부당환급받은 세액을 징수하는 근거규정인 개정조항을 개정된 법 시행 후 최초로 환급세액을 징수하는 분부터 적용하도록 규정한 법인세법 부칙조항은 진정소급입법에 해당하며 재산권을 침해한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-1","t":"헌법은 선거 및 투표관리 등에 관한 사무를 일반행정업무와 기능적으로 분리해 이를 독립된 헌법기관인 선거관리위원회에 맡김으로써 행정부의 부당한 선거 간섭을 제도적으로 배제 내지 견제할 수 있도록 하고 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-2","t":"우리 헌법이 선거관리사무를 행정부로부터 독립된 헌법기관인 선거관리위원회에 부여한 것은, 독립적ㆍ중립적 선거관리라는 헌법적 과제를 제대로 수행하기 위해서는 외부 권력기관, 특히 대통령을 수반으로 하는 정부의 영향력을 제도적으로 차단할 필요가 있다는 헌법적 결단이 반영된 결과라고 볼 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-3","t":"선거관리위원회의 헌법상 지위와 헌법 및 선거관리위원회법의 관련 규정들을 종합하여 보면, 선거관리위원회에는 헌법과 선거관리위원회법에 의하여 행정부 등 외부기관의 부당한 간섭 없이 선거관리사무는 물론 인사ㆍ조직운영ㆍ내부규율 등에 관한 사무를 독립적으로 수행할 권한이 부여되어 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-4","t":"헌법 제97조는 “국가의 세입ㆍ세출의 결산, 국가 및 법률이 정한 단체의 회계검사와 행정기관 및 공무원의 직무에 관한 감찰을 하기 위하여 대통령 소속하에 감사원을 둔다.”라고 정하여, 감사원에게 ‘국가’를 대상으로 한 회계검사권과 ‘행정기관’을 대상으로 한 직무감찰권을 부여하고 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-5","t":"선거관리위원회가 담당하는 선거관리사무는 그 성격상 행정작용에 해당한다고 볼 수 있으므로, 헌법 제97조가 감사원의 직무감찰 대상으로 정한 행정기관에 포함된다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-1","t":"헌법 제8조 제4항은 “정당의 목적이나 활동이 민주적 기본질서에 위배될 때에는 정부는 헌법재판소에 그 해산을 제소할 수 있고, 정당은 헌법재판소의 심판에 의하여 해산된다.”라고 규정하고 있다. 정당해산심판은 헌법과 민주주의를 부정하고 파괴하려는 정당으로부터 헌법을 수호하기 위해 마련된 제도로서 ‘방어적 민주주의’의 표현이다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-2","t":"정당해산심판절차에는 형사소송에 관한 법령 및 행정소송법이 함께 준용되는데, 헌법재판소는 이것이 정당의 공정한 재판을 받을 권리를 침해하는 것은 아니라고 하였다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-3","t":"헌법재판소는 정당해산심판의 청구를 받은 때에는 직권 또는 청구인의 신청에 의하여 종국결정의 선고 시까지 피청구인의 활동을 정지하는 결정을 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-4","t":"헌법 제8조 제4항은 정당해산심판의 사유를 “정당의 목적이나 활동이 민주적 기본질서에 위배될 때”로 규정하고 있는데, 여기서 말하는 민주적 기본질서의 ‘위배’란, 민주적 기본질서에 대한 단순한 위반이나 저촉을 의미하는 것이 아니라, 민주사회의 불가결한 요소인 정당의 존립을 제약해야 할 만큼 그 정당의 목적이나 활동이 우리 사회의 민주적 기본질서에 대하여 실질적인 해악을 끼칠 수 있는 구체적 위험성을 초래하는 경우를 가리킨다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-5","t":"강제적 정당해산은 헌법상 핵심적인 정치적 기본권인 정당활동의 자유에 대한 근본적 제한이므로, 헌법재판소는 이에 관한 결정을 할 때 헌법 제37조 제2항이 규정하고 있는 비례원칙을 준수해야만 한다.","ox":"O","m":"⑤","c":"A","tp":"정당해산심판"}],"7":[{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06","t":"의결정족수에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"의결정족수에 관한 다음 설명 중 옳은 것은 모두 몇 개인가?","d":"가.국무총리에 대한 해임건의 발의 정족수와 탄핵소추 발의 정족수는 같다.\n나.국회의원의 자격심사의 청구 정족수와 예산안에 대한 수정동의 정족수는 같다.\n다.국회 위원회의 의사정족수와 본회의의 의사정족수는 같다.\n라.국회의원 제명 정족수와 헌법개정안 의결 정족수는 같다.\n마.국회의장 선출 정족수와 계엄해제 요구 정족수는 같다.","o":["1개","2개","3개","4개","5개"],"a":4}},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12","t":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","d":"가.국회는 국민의 보통․평등․직접․공개선거에 의하여 선출된 국회의원으로 구성한다.\n나.국회의원의 수는 법률로 정하되, 300인 이하로 한다.\n다.국회의원은 현행범인인 경우에도 회기 중 국회의 동의없이 체포 또는 구금되지 아니한다.\n라.국회의원은 국회에서 직무상 행한 발언과 표결에 관하여 국회 외에서 책임을 지지 아니한다.\n마.국회의 정기회는 법률이 정하는 바에 의하여 매년 1회 집회되며, 국회의 임시회는 대통령 또는 국회재적의원 4분의 1 이상의 요구에 의하여 집회된다.\n바.정기회의 회기는 100일을, 임시회의 회기는 30일을 초과할 수 없다.","o":["1개","2개","3개","4개","5개"],"a":3}},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-1","t":"국회의원은 국회에서 직무상 행한 발언과 표결에 관하여 국회 외에서 책임을 지지 아니하는데, 그 취지는 국회의원이 국민의 대표자로서 국회 내에서 자유롭게 발언하고 표결할 수 있도록 보장함으로써 국회가 입법 및 국정통제 등 헌법에 의하여 부여된 권한을 적정하게 행사하고 그 기능을 원활하게 수행할 수 있도록 보장하는 데에 있다.","ox":"O","m":"①","c":"A","tp":"국회의원의 특권"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-2","t":"면책특권의 대상이 되는 행위는 국회의 직무수행에 필수적인 국회의원의 국회 내에서의 직무상 발언과 표결이라는 의사표현행위 자체에만 국한되지 않고 이에 통상적으로 부수하여 행하여지는 행위까지 포함된다.","ox":"O","m":"②","c":"A","tp":"국회의원의 특권"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-3","t":"국회의원은 현행범인 경우를 제외하고는 회기 중 국회의 동의 없이 체포 또는 구금되지 아니하며, 회기 전에 체포 또는 구금된 때에는 현행범이 아닌 한 국회의 요구가 있으면 회기 중 석방된다.","ox":"O","m":"③","c":"A","tp":"국회의원의 특권"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-4","t":"회기 중 국회의원 체포안에 대한 동의에는 국회의원 재적의원 과반수의 찬성이 필요하다.","ox":"X","m":"④","c":"A","tp":"국회의원의 특권"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-5","t":"헌법상 국회의원의 불체포특권은 불수사특권이나 불기소특권을 의미하는 것은 아니므로, 회기 중에 유죄 판결이 확정되면 그 형을 집행할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"국회의원의 특권"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-1","t":"국회의장과 부의장은 국회에서 기명투표로 선거하되, 재적의원 과반수의 득표로 당선된다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-2","t":"국회의장은 위원회에 출석하여 발언·표결할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-3","t":"국회의원은 둘 이상의 상임위원회의 위원이 될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-4","t":"국회 본회의는 재적의원 4분의 1 이상의 출석으로 개의한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-5","t":"국회의원은 위원회에서 동일의제에 대하여 횟수 및 시간 등에 제한 없이 발언할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2018_24-19","t":"국회의 위원회에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"국회의 위원회에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"㉠예산결산특별위원회는 국가의 예산·결산심사를 더욱 충실하게 하고 정부예산에 대한 연중 통제를 위한 상설위원회이다.\n㉡국회의원은 2 이상의 상임위원회의 위원이 될 수 있으며, 각 상임위원회의 위원장은 교섭단체 대표의원의 요청으로 국회본회의 의결을 거쳐 국회의장이 임명한다.\n㉢두 개 이상의 위원회는 연석회의를 열어 공통의 사안을 표결할 수 있다.\n㉣국무총리, 국무위원, 국무총리실장, 처의 장, 행정각부의 차관, 그 밖의 국가공무원의 직을 겸한 의원은 상임위원을 사임해야 한다.\n㉤⌜국회법⌟ 기타 국회규칙에 관한 사항은 국회운영위원회의 소관사항이다.","o":["㉠, ㉢, ㉣","㉡, ㉢, ㉣","㉢, ㉣, ㉤","㉡, ㉣, ㉤","㉠, ㉣, ㉤"],"a":2}},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-1","t":"정부는 회계연도마다 예산안을 편성하여 회계연도 개시 60일 전까지 국회에 제출하고, 국회는 회계연도 개시 30일 전까지 이를 의결하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-2","t":"국회는 정부의 동의 없이 정부가 제출한 지출예산 각항의 금액을 증가하거나 새 비목을 설치할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-3","t":"한 회계연도를 넘어 계속하여 지출할 필요가 있을 때에는 정부는 연한을 정하여 계속비로서 국회의 의결을 얻어야 한다.","ox":"O","m":"③","c":"A","tp":"예산"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-4","t":"정부는 예산에 변경을 가할 필요가 있을 때에는 수정예산안을 편성하여 국회에 제출할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-5","t":"국회의 예산안 의결은 정부의 재정행위를 통하여 일반 국민을 구속하므로 헌법소원심판의 대상이 된다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12-1","t":"상임위원회는 국회의 내부기관인 동시에 본회의의 심의 전에 회부된 안건을 심사하거나 그 소관에 속하는 의안을 입안하는 국회의 합의제기관으로, 회부된 안건을 심사하고 그 결과를 본회의에 보고하여 본회의의 판단자료를 제공한다. 이처럼 우리나라 국회의 법률안 심의는 본회의 중심주의를 채택하고 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12-2","t":"안건신속처리제도는 여야 간 쟁점안건이 심의대상도 되지 못하고 위원회에 장기간 계류되는 상황을 최소화하기 위한 제도적 장치로서, 신속처리대상으로 지정된 안건에 대해서는 일정기간이 경과하면 자동으로 다음 단계로 진행하도록 하여 입법의 효율성을 제고하고자 도입된 것이다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12-3","t":"국회법상 직권상정권한은 국회의 수장이 국회의 비상적인 헌법적 장애상태를 회복하기 위하여 가지는 권한으로 국회의장의 의사정리권에 속하고, 비상적·예외적 의사절차에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12-4","t":"무제한 토론을 실시하는 중에 해당 회기가 종료되는 때에는 무제한 토론은 종결 선포된 것으로 본다. 이 경우 해당 안건은 바로 다음 회기에서 지체 없이 표결하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12-5","t":"본회의 개의에 필요한 출석자의 수는 재적의원 5분의 1 이상이다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-1","t":"국무총리에 대한 해임건의발의 정족수와 탄핵소추발의 정족수는 같다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-2","t":"국회의원의 자격심사의 청구 정족수와 예산안에 대한 수정동의 정족수는 같다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-3","t":"국회 위원회의 의사정족수와 본회의의 의사정족수는 같다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-4","t":"국회의원 제명 정족수와 헌법개정안 의결 정족수는 같다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-5","t":"국회의장 선출 정족수와 계엄해제 요구 정족수는 같다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-1","t":"대통령이 일반사면을 명하려면 국회의 동의를 얻어야 한다.","ox":"O","m":"①","c":"A","tp":"국회의 동의권한"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-2","t":"대통령이 감사원장을 임명하는 경우 국회의 동의가 필요 없다.","ox":"X","m":"②","c":"A","tp":"국회의 동의권한"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-3","t":"국회는 상호원조 또는 안전보장에 관한 조약, 중요한 국제조직에 관한 조약, 우호통상항해조약, 주권의 제약에 관한 조약, 강화조약, 국가나 국민에게 중대한 재정적 부담을 지우는 조약 또는 입법사항에 관한 조약의 체결·비준에 대한 동의권을 가진다.","ox":"O","m":"③","c":"A","tp":"국회의 동의권한"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-4","t":"대법관은 대법원장의 제청으로 국회의 동의를 얻어 대통령이 임명한다.","ox":"O","m":"④","c":"A","tp":"국회의 동의권한"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-5","t":"국회는 선전포고, 국군의 외국에의 파견 또는 외국 군대의 대한민국 영역 안에서의 주류에 대한 동의권을 가진다.","ox":"O","m":"⑤","c":"A","tp":"국회의 동의권한"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18","t":"다음 중 국회의 법제사법위원회 소관 사항이 아닌 것은?","c":"A","mc":{"s":"다음 중 국회의 법제사법위원회 소관 사항이 아닌 것은?","d":"","o":["법제처 소관에 속하는 사항","감사원 소관에 속하는 사항","헌법재판소 사무에 관한 사항","국가인권위원회 소관에 속하는 사항","탄핵소추에 관한 사항"],"a":4}},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-1","t":"국회의 정기회는 법률이 정하는 바에 의하여 매년 1회 집회되며, 임시회는 대통령 또는 국회재적의원 4분의 1 이상의 요구에 의하여 집회된다. 대통령이 임시회의 집회를 요구할 때에는 기간과 집회요구의 이유를 명시하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-2","t":"국회의 회의는 공개한다. 다만, 출석의원 과반수의 찬성이 있거나 의장이 국가의 안전보장을 위하여 필요하다고 인정할 때에는 공개하지 아니할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-3","t":"우리 헌법은 국회에 제출된 의안이 회기중에 의결되지 못한 경우에는 폐기된다는 회기불계속의 원칙을 취하고 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-4","t":"대통령은 국회에서 의결된 법률안에 이의가 있을 때에는 정부에 이송된 후 15일 이내에 이의서를 붙여 국회로 환부하여 그 재의를 요구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-5","t":"법률안에 대한 재의의 요구가 있을 때에는 국회는 재의에 붙이고, 재적의원 과반수의 출석과 출석의원 3분의 2 이상의 찬성으로 전과 같은 의결을 하면 그 법률안은 법률로서 확정된다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-1","t":"우리 헌법은 대법원장, 대법관, 헌법재판소장, 국무총리, 감사원장에 대하여는 그 임명시 인사청문회를 실시하도록 규정하고 있으나, 국세청장, 검찰총장, 경찰청장 등에 대하여는 헌법이 아닌 국회법에 인사청문회의 실시근거를 두고 있다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-2","t":"대법원장, 대법관, 헌법재판소장에 대한 인사청문회는 국회 법제사법위원회에서 실시하고, 국무총리, 감사원장에 대한 인사청문회는 국회 정무위원회에서 실시한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-3","t":"국회에 선출권이나 동의권이 없는 공직후보자에 관한 국회 인사청문경과보고서는 임명권자의 판단을 구속하지 아니하므로, 임명권자는 국회의 의견과 다르게 후보자를 임명하거나 임명하지 않을 수 있다.","ox":"O","m":"③","c":"A","tp":"인사청문회"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-4","t":"국회는 임명동의안 등이 제출된 날부터 20일 이내에 그 심사 또는 인사청문을 마쳐야 하고, 부득이한 사유로 그 기간 이내에 국회가 인사청문경과보고서를 송부하지 못한 경우 임명권자는 15일 이내의 범위에서 기간을 정하여 인사청문경과보고서 송부를 요청할 수 있다.","ox":"X","m":"④","c":"A","tp":"인사청문회"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-5","t":"인사청문 요청은 임명권자 내지 지명권자가 하는 것이 원칙이므로, 대통령과 대법원장은 후보자에 대한 인사청문을 요청할 수 있으나, 임기가 개시되지 아니하여 법률적 지위가 부여되기 이전인 대통령당선인은 인사청문 요청을 할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"인사청문회"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11","t":"헌법에 명시된 탄핵소추의 대상이 아닌 자는?","c":"A","mc":{"s":"헌법에 명시된 탄핵소추의 대상이 아닌 자는?","d":"","o":["대통령","법관","국무위원","헌법재판소 재판관","검사"],"a":5}},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-1","t":"국회의원만이 법률안을 제출할 수 있다.","ox":"X","m":"①","c":"A","tp":"국회의 입법권"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-2","t":"법률안 심의·표결권은 국회의원으로 구성된 국회에 부여된 것이지 국회의원 각자에게 보장된 것은 아니다.","ox":"X","m":"②","c":"A","tp":"국회의 입법권"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-3","t":"대통령이 법률안에 대하여 재의를 요구한 경우 국회는 재의에 붙이고, 재적의원 3분의 2 이상의 출석과 출석의원 3분의 2 이상의 찬성으로 전과 같은 의결을 하면 그 법률안은 법률로서 확정된다.","ox":"X","m":"③","c":"A","tp":"국회의 입법권"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-4","t":"국회에 제출된 법률안은 회기 중에 의결되지 못하면 폐기되는 것이 원칙이다.","ox":"X","m":"④","c":"A","tp":"국회의 입법권"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-5","t":"국회의원은 국회의 조약에 대한 체결·비준 동의권 침해를 주장하면서 대통령을 상대로 권한쟁의심판을 청구할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"국회의 입법권"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-1","t":"국회의 정기회는 법률이 정하는 바에 의하여 매년 1회 집회되며, 국회의 임시회는 대통령 또는 국회재적의원 4분의 1 이상의 요구에 의하여 집회된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-2","t":"국회에서 의결된 법률안은 정부에 이송되어 15일 이내에 대통령이 공포하나, 법률안에 이의가 있을 때에는 대통령은 제1항의 기간 내에 그 전부 또는 일부에 관한 이의서를 붙여 국회로 환부하고, 그 재의를 요구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-3","t":"국회나 그 위원회의 요구가 있는 경우 국무총리ㆍ국무위원 또는 정부위원은 출석ㆍ답변하여야 하며, 국무총리 또는 국무위원이 출석요구를 받은 때에는 국무위원 또는 정부위원으로 하여금 출석ㆍ답변하게 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-4","t":"국회는 직무집행에 있어서 헌법이나 법률을 위배한 검사뿐만 아니라 고위공직자범죄수사처의 검사에 대하여도 탄핵소추를 의결할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-5","t":"국회는 정부의 동의 없이 정부가 제출한 지출예산 각항의 금액을 증가하거나 새 비목을 설치할 수 없으며, 예산에 변경을 가할 필요가 있다 하더라도 직접 추가경정예산안을 제출, 의결할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13-1","t":"헌법개정안은 기명투표로 표결한다.","ox":"O","m":"①","c":"A","tp":"국회"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13-2","t":"국무총리 또는 국무위원의 해임건의안이 발의되었을 때에는 의장은 그 해임건의안이 발의된 후 처음 개의하는 본회의에 그 사실을 보고하고, 본회의에 보고된 때부터 24시간 이후 72시간 이내에 무기명투표로 표결한다.","ox":"O","m":"②","c":"A","tp":"국회"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13-3","t":"본회의의 표결방법은 전자투표에 의한 기록표결이 원칙이나, 중요한 안건으로서 의장의 제의 또는 의원의 동의로 본회의 의결이 있거나 재적의원 5분의 1 이상의 요구가 있을 때에는 기명투표·호명투표 또는 무기명투표로 표결한다.","ox":"O","m":"③","c":"A","tp":"국회"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13-4","t":"국회는 휴회 중이라도 대통령의 요구가 있을 때, 의장이 긴급한 필요가 있다고 인정할 때 또는 재적의원 3분의 1 이상의 요구가 있을 때에는 본회의를 재개한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13-5","t":"국회의원이 징계대상자에 대한 징계를 요구하려는 경우에는 의원 20명 이상의 찬성으로 그 사유를 적은 요구서를 의장에게 제출하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-1","t":"국회의원이 체포 또는 구금된 국회의원의 석방 요구를 발의할 때에는 재적의원 과반수의 연서로 그 이유를 첨부한 요구서를 국회의장에게 제출하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-2","t":"국회의장은 국회를 대표하는 자로서 헌법상의 국가기관이며, 국회를 대표하고 의사를 정리하며 질서를 유지하고 사무를 감독할 지위에 있다.","ox":"O","m":"②","c":"A","tp":"국회의원"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-3","t":"발의된 의안의 철회 동의 여부에 관한 국회의원의 심의·표결권한은 그 성질상 일신전속적인 것이므로 국회의원직을 상실한 경우 승계되거나 상속될 수 없고, 그 권한의 침해 여부가 문제된 권한쟁의심판절차 또한 수계될 수 있는 성질의 것이 아니다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-4","t":"국회법상 국회의장은 위원회에 출석하여 발언할 수 있으나, 표결에는 참가할 수 없다.","ox":"O","m":"④","c":"A","tp":"국회의원"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-5","t":"무소속 국회의원으로서 교섭단체 소속 국회의원과 동등하게 대우받을 권리라는 것은 헌법이 일반 국민에게 보장하고 있는 기본권이라고 할 수 없으므로, 국회의원이 위와 같은 권리 침해를 이유로 헌법재판소법 제68조 제1항에 따른 헌법소원심판을 청구할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-1","t":"국회의 임시회는 대통령 또는 국회재적의원 5분의 1 이상의 요구에 의하여 집회된다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-2","t":"정기회의 회기는 100일을, 임시회의 회기는 50일을 초과할 수 없다.","ox":"X","m":"②","c":"A","tp":"국회"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-3","t":"헌법 제50조 제1항 단서가 정하고 있는 출석의원 과반수의 찬성보다 더 엄격한 본회의 의결을 통해 민주적 정당성을 갖춘 법률의 형식으로 위원회 회의의 비공개를 결정할 수 있다.","ox":"X","m":"③","c":"A","tp":"국회"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-4","t":"법률안에 대한 대통령의 재의의 요구가 있을 때에는 국회는 재의에 붙이고, 재적의원 3분의 2 이상의 찬성으로 전과 같은 의결을 하면 그 법률안은 법률로서 확정된다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-5","t":"국회에서 선출하는 헌법재판소 재판관·중앙선거관리위원회 위원 후보자는 인사청문특별위원회에서 인사청문회를 실시하고, 대통령이 임명하거나 대법원장이 지명하는 헌법재판소 재판관·중앙선거관리위원회 위원 후보자는 소관 상임위원회에서 인사청문회를 실시한다.","ox":"O","m":"⑤","c":"A"}],"8":[{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-1","t":"헌법은 군인은 현역을 면한 후가 아니면 국무총리 또는 국무위원으로 임명될 수 없다고 명문으로 규정하고 있다.","ox":"O","m":"①","c":"A","tp":"행정부"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-2","t":"국무총리는 국무위원의 해임을 대통령에게 건의할 수 있다.","ox":"O","m":"②","c":"A","tp":"행정부"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-3","t":"국무총리 또는 행정각부의 장은 소관 사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 총리령 또는 부령을 발할 수 있다.","ox":"O","m":"③","c":"A","tp":"행정부"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-4","t":"국무회의는 대통령, 국무총리와 15인 이상 30인 이하의 국무위원으로 구성된다.","ox":"O","m":"④","c":"A","tp":"행정부"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-5","t":"행정각부의 장과는 달리 국무위원으로 임명되기 위해서는 국무총리의 제청이 필수적인 것은 아니다.","ox":"X","m":"⑤","c":"A","tp":"행정부"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14","t":"헌법에 따라 대통령이 임명권을 가지는 사람을 모두 열거한 것은?","c":"A","mc":{"s":"헌법에 따라 대통령이 임명권을 가지는 사람을 모두 열거한 것은?","d":"가.법관(대법원장이나 대법관이 아닌 법관을 말함)\n나.감사원 감사위원\n다.헌법재판관 중 국회에서 선출하는 3인의 재판관\n라.중앙선거관리위원 중 대법원장이 지명하는 3인의 위원","o":["가, 나, 다, 라","나, 다, 라","나, 다","나, 라","다, 라"],"a":3}},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05","t":"헌법상 국무회의의 심의를 거쳐야 하는 사항이 아닌 것은 몇 개인가?","c":"A","mc":{"s":"헌법상 국무회의의 심의를 거쳐야 하는 사항이 아닌 것은 몇 개인가?","d":"ㄱ.정부에 제출 또는 회부된 정부의 정책에 관계되는 청원의 심사\nㄴ.각군참모총장, 국립대학교총장의 임명\nㄷ.조약의 체결ㆍ비준 및 외교사절의 신임ㆍ접수\nㄹ.사면ㆍ감형과 복권\nㅁ.군사에 관한 중요사항\nㅂ.국회의 임시회 집회의 요구\nㅅ.행정각부간의 권한의 획정\nㅇ.정당해산의 제소","o":["0개","1개","2개","3개","4개"],"a":2}},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-1","t":"국회에서 의결된 법률안은 정부에 이송되어 15일 이내에 대통령이 공포한다.","ox":"O","m":"①","c":"A","tp":"대통령의 법률안 거부권"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-2","t":"대통령은 법률안의 일부에 대하여 또는 법률안을 수정하여 재의를 요구할 수 없다.","ox":"O","m":"②","c":"A","tp":"대통령의 법률안 거부권"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-3","t":"법률안이 정부에 이송된 지 15일 이내에 대통령이 공포나 재의를 요구하지 아니한 때에는 그 법률안은 법률로서 확정된다.","ox":"O","m":"③","c":"A","tp":"대통령의 법률안 거부권"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-4","t":"국회의 재의결에 의한 확정법률이 정부에 이송된 후 15일 이내에 대통령이 공포하지 아니할 때에는 국회의장이 이를 공포한다.","ox":"X","m":"④","c":"A","tp":"대통령의 법률안 거부권"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-5","t":"법률은 특별한 규정이 없는 한 공포한 날로부터 20일을 경과함으로써 효력이 발생한다.","ox":"O","m":"⑤","c":"A","tp":"대통령의 법률안 거부권"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-1","t":"조약의 체결 권한은 대통령에게 있고, 비준권은 국회에 속한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-2","t":"중요한 국제조직에 관한 조약, 우호통상항해조약의 체결 및 비준에 대해서는 국회가 동의권을 가진다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-3","t":"‘대한민국과 일본국간의 어업에 관한 협정’은 한일간 행정협정에 불과하여 국내법과 같은 효력을 가지는 조약에 해당되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-4","t":"국내법의 개정 없이 마라케쉬협정에 의하여 관세법위반자의 처벌이 가중되는 것은 죄형법정주의 원칙에 위배된다.","ox":"X","m":"④","c":"A","tp":"조약"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-5","t":"대통령이 국회의 동의를 요하는 조약을 그 동의 없이 체결한 경우 국회의원은 대통령을 상대로 조약에 대한 심의ㆍ의결권 침해를 이유로 권한쟁의심판을 제기할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-1","t":"감사원은 대통령에 소속된 기관으로 국무총리의 통할을 받지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-2","t":"감사원은 원장을 포함한 5인 이상 11인 이하의 감사위원으로 구성한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-3","t":"감사원장과 감사위원은 국회의 동의를 얻어 대통령이 임명한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-4","t":"감사원은 스스로 규칙을 제정할 수 있는 권한이 있다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-5","t":"법률이 정하는 경우 국가기관이 아닌 경우에도 감사원의 회계검사를 받아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-1","t":"국무총리는 국무회의의 부의장이 된다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-2","t":"제2차 개정헌법에서는 국무총리제가 폐지되었다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-3","t":"헌법 제86조 제2항의 국무총리의 통할을 받는 행정각부에 모든 행정기관이 포함된다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-4","t":"우리 헌법이 대통령중심제의 정부형태를 취하면서도 국무총리제도를 두게 된 주된 이유는 대통령의 강력한 권력을 견제하기 위함이다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-5","t":"국무총리는 국무위원의 해임을 대통령에게 건의할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-1","t":"대통령 선거에 있어서 최고득표자가 2인 이상인 때에는 국회의 재적의원 3분의 2가 출석한 공개회의에서 다수표를 얻은 자를 당선자로 한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-2","t":"대통령은 국민의 보통·평등·자유·비밀선거에 의하여 선출한다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-3","t":"대통령후보자가 1인일 때에는 그 득표수가 선거권자 총수의 과반수 이상이 아니면 대통령으로 당선될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-4","t":"대통령이 궐위된 때 또는 대통령 당선자가 사망하거나 판결 기타의 사유로 그 자격을 상실한 때에는 60일 이내에 후임자를 선거한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-5","t":"대통령의 임기가 만료되는 때에는 임기만료 60일 내지 40일 전에 후임자를 선거한다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-1","t":"군인은 현역을 면한 후가 아니면 국무총리 또는 국무위원으로 임명될 수 없다.","ox":"O","m":"①","c":"A","tp":"행정부"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-2","t":"행정각부의 장과는 달리 국무위원으로 임명되기 위해서는 국무총리의 제청이 필수적인 것은 아니다.","ox":"X","m":"②","c":"A","tp":"행정부"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-3","t":"국무회의는 대통령, 국무총리와 15인 이상 30인 이하의 국무위원으로 구성한다.","ox":"O","m":"③","c":"A","tp":"행정부"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-4","t":"대통령은 국무회의 의장으로서 회의를 소집하고 이를 주재한다.","ox":"O","m":"④","c":"A","tp":"행정부"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-5","t":"국무총리 또는 행정각부의 장은 소관사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 총리령 또는 부령을 발할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"행정부"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-1","t":"대통령은 법률이 정하는 바에 의하여 사면·감형 또는 복권을 명할 수 있다.","ox":"O","m":"①","c":"A","tp":"대통령의 권한"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-2","t":"대통령은 헌법과 법률이 정하는 바에 의하여 국군을 통수한다.","ox":"O","m":"②","c":"A","tp":"대통령의 권한"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-3","t":"대통령은 전시·사변 또는 이에 준하는 국가비상사태에 있어서 병력으로써 군사상의 필요에 응하거나 공공의 안녕질서를 유지할 필요가 있을 때에는 법률이 정하는 바에 의하여 계엄을 선포할 수 있고 이때 대통령은 지체 없이 국회에 보고하여 그 승인을 얻어야 한다.","ox":"X","m":"③","c":"A","tp":"대통령의 권한"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-4","t":"대통령은 국회에 출석하여 발언하거나 서한으로 의견을 표시할 수 있다.","ox":"O","m":"④","c":"A","tp":"대통령의 권한"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-5","t":"대통령은 법률이 정하는 바에 의하여 훈장 기타의 영전을 수여한다.","ox":"O","m":"⑤","c":"A","tp":"대통령의 권한"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-1","t":"구체적으로 어떤 정책을 필수적으로 국무회의 심의를 거쳐야 하는 중요한 정책으로 보아야 하는지는 국무회의에 의안을 상정할 수 있는 권한자인 대통령이나 국무위원에게 일정 정도의 판단재량이 인정되는 것으로 보아야 하고, 그에 관한 대통령이나 국무위원의 일차적 판단이 명백히 비합리적이거나 자의적인 것이 아닌 한 존중되어야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-2","t":"국무회의는 행정부 내 최고의 정책 심의기관이지만 의결기관은 아니다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-3","t":"국회는 국회재적의원 과반수의 발의와 국회재적의원 3분의 2 이상의 찬성으로 국무위원의 해임을 대통령에게 건의할 수 있다.","ox":"X","m":"③","c":"A","tp":"국무회의"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-4","t":"대통령의 직무상 해외 순방 중 국무총리가 주재한 국무회의에서 이루어진 정당해산심판청구서 제출안에 대한 의결은 위법하지 아니하다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-5","t":"국무회의는 대통령·국무총리와 15인 이상 30인 이하의 국무위원으로 구성한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-1","t":"감사원은 조직상 대통령에 소속하되, 직무에 관하여는 독립의 지위를 가진다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-2","t":"감사위원은 원장의 제청으로 국회의 동의를 얻어 대통령이 임명한다.","ox":"X","m":"②","c":"A","tp":"감사원"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-3","t":"국회·법원 및 헌법재판소에 소속된 공무원에 대하여는 직무감찰을 할 수 없다.","ox":"O","m":"③","c":"A","tp":"감사원"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-4","t":"감사원은 직무감찰결과 비위사실이 밝혀지더라도 해당 공무원에 대하여 직접 징계를 할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-5","t":"지방자치단체의 자치사무에 관하여도 합법성 감사뿐만 아니라 합목적성 감사가 허용된다.","ox":"O","m":"⑤","c":"A","tp":"감사원"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-1","t":"우리 헌법 제79조 제1항은 “대통령은 법률이 정하는 바에 의하여 사면·감형 또는 복권을 명할 수 있다.”고 대통령의 사면권을 규정하고 있고, 제3항은 “사면·감형 또는 복권에 관한 사항은 법률로 정한다.”고 규정하여 사면의 구체적 내용과 방법 등을 법률에 위임하고 있다. 그러므로 사면의 종류, 대상, 범위, 절차, 효과 등은 범죄의 죄질과 보호법익, 일반국민의 가치관 내지 법감정, 국가이익과 국민화합의 필요성, 권력분립의 원칙과의 관계 등 제반사항을 종합하여 입법자가 결정할 사항으로서 광범위한 입법재량 내지 형성의 자유가 부여되어 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-2","t":"사면은 형의 선고의 효력 또는 공소권을 상실시키거나, 형의 집행을 면제시키는 국가원수의 고유한 권한을 의미하며, 사법부의 판단을 변경하는 제도로서 권력분립의 원리에 대한 예외가 된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-3","t":"사면에는 일반사면과 특별사면이 있으며, 특별사면은 이미 형의 선고를 받은 특정인에 대하여 형의 집행을 면제하거나, 선고의 효력을 상실케 하는 사면이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-4","t":"대통령의 사면권행사는 권력분립의 원리에 대한 예외로서 이를 존중하기 위해 국회의 동의를 받을 필요가 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-5","t":"복권이란 형의 선고로 인하여 법령에 따른 자격이 상실되거나 정지된 자격을 회복시키는 것을 말하고, 형의 집행이 끝나지 아니한 자 또는 집행이 면제되지 아니한 자에 대하여는 하지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-1","t":"대통령은 국무총리·국무위원·행정각부의 장 기타 법률이 정하는 공사의 직을 겸할 수 없고, 이는 비상계엄하에서도 마찬가지이다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-2","t":"국가원로자문회의의 의장은 전직대통령이 된다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-3","t":"대통령후보자가 1인일 때에는 그 득표수가 선거권자 총수의 3분의 1 이상이 아니면 대통령으로 당선될 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-4","t":"대통령이 발한 긴급명령이 국회의 승인을 얻지 못한 때에는 그 명령은 그때부터 효력을 상실한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-5","t":"국회가 재적의원 과반수의 찬성으로 계엄의 해제를 요구한 때에는 대통령은 이를 해제하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-1","t":"국가긴급권은 법치주의의 예외로서, 위기 극복이라는 소극적 목적을 위해 발동되어야 하며, 기간, 범위에 있어 목적 달성에 불가결한 최소한도 내로 한정되어야 한다.","ox":"O","m":"①","c":"A","tp":"대통령의 국가긴급권"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-2","t":"헌법재판소나 법원은 국가긴급권 발동의 위헌·위법 여부를 사후적으로 심사할 수는 있으나, 국가긴급권이 가지는 고도의 정치적 성격이 그 심사의 한계로서 작용할 수 있다.","ox":"O","m":"②","c":"A","tp":"대통령의 국가긴급권"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-3","t":"대법원은 소위 유신헌법 제53조에 근거한 대통령 긴급조치 제1호에 대하여 비록 그 발동 당시 시행 중이던 유신헌법에 위배되지는 아니하나, 현행헌법에 비추어 그 발동요건을 갖추지 못하여 위헌, 위법이라고 판시한 바 있다.","ox":"X","m":"③","c":"A","tp":"대통령의 국가긴급권"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-4","t":"대통령의 긴급재정·경제명령은 법률과 마찬가지로 위헌법률심판이나 헌법소원심판의 대상이 된다.","ox":"O","m":"④","c":"A","tp":"대통령의 국가긴급권"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-5","t":"계엄 상황이 해소된 때에는 대통령은 국무회의의 심의를 거쳐 계엄을 해제할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"대통령의 국가긴급권"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-1","t":"국가인권위원회는 위원장 1명과 상임위원 4명을 포함한 11명의 인권위원으로 구성한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-2","t":"국가인권위원회는 법률에 설치근거를 둔 국가기관이고 헌법에 의하여 설치된 국가기관이 아니므로, 권한쟁의심판을 청구할 당사자능력이 인정되지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-3","t":"국가인권위원회는 재적위원 과반수의 찬성으로 의결하고, 의사는 공개한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-4","t":"사인(私人)으로부터 차별행위를 당한 경우에도 국가인권위원회에 그 내용을 진정할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-5","t":"국가인권위원회는 진정에 관한 위원회의 조사, 증거의 확보 또는 피해자의 권리 구제를 위하여 필요하다고 인정하면 피해자를 위하여 대한법률구조공단 등에게 법률구조를 요청할 수 있으나, 피해자의 명시한 의사에 반하여 법률구조를 요청할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-1","t":"국무위원이 국무회의에 출석하지 못할 때에는 각 부의 차관이 대리하여 출석하며, 대리 출석한 차관은 관계 의안에 관하여 발언하고 표결에 참가할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-2","t":"상훈법상 서훈의 추천이 있는 경우 행정안전부장관은 서훈에 관한 의안을 국무회의에 제출하여야 하고, 대통령은 이에 대하여 국무회의의 심의를 거쳐 서훈 대상자를 결정한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-3","t":"국무회의는 구성원 과반수의 출석으로 개의하고, 출석구성원 3분의 2 이상의 찬성으로 의결한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-4","t":"국가안전보장에 관련되는 대외정책·군사정책과 국내정책의 수립에 관하여 국무회의의 심의에 앞서 대통령의 자문에 응하기 위하여 국가안전보장회의를 둔다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-5","t":"국무회의에 제출된 의안은 긴급한 의안이 아닌 한 차관회의의 심의를 먼저 거쳐야 하나, 의안의 긴급성에 관한 판단에는 원칙적으로 정부의 재량이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-1","t":"대통령후보자가 1인일 때에는 그 득표수가 선거권자 총수의 3분의 1 이상이 아니면 대통령으로 당선될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-2","t":"대통령으로부터 환부된 법률안과 그 밖에 인사에 관한 안건은 무기명투표로 표결한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-3","t":"대통령선거의 후보자는 후보자의 등록이 끝난 때부터 개표종료시까지 사형ㆍ무기 또는 장기 7년 이상의 징역이나 금고에 해당하는 죄를 범한 경우를 제외하고는 현행범인이 아니면 체포 또는 구속되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-4","t":"대통령의 임기연장 또는 중임변경을 위한 헌법개정은 그 헌법개정 제안 당시의 대통령에 대하여는 효력이 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-5","t":"궐위로 인한 선거에 의한 대통령의 임기는 당선이 결정된 날의 다음날 0시부터 개시된다.","ox":"X","m":"⑤","c":"A"}],"10":[{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-1","t":"기소유예처분을 받은 피의자는 수사기관에 진정을 제기할 수 있으므로, 그러한 절차 없이 그 처분의 취소를 구하는 헌법소원심판을 청구하는 것은 헌법재판소법 제68조 제1항 단서에 규정된 ‘다른 법률에서 정한 구제절차’를 거치지 아니한 것이므로, 보충성 요건을 갖추지 못하여 부적법하다.","ox":"X","m":"①","c":"A","tp":"헌법소원의 보충성"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-2","t":"고용노동부장관의 청구인 전국교직원노동조합에 대한 2013. 9. 23. 자 시정요구(이하 ‘이 사건 시정 요구’라 한다)는 청구인 전국교직원노동조합(이하 ‘전교조’라 한다)의 권리·의무에 변동을 일으키는 행정행위에 해당하나, 청구인 전교조는 이 사건 시정요구에 대하여 다른 불복절차를 거치지 아니하고 곧바로 헌법소원심판을 청구하였으므로, 이에 대한 헌법소원은 보충성 요건을 결하였다.","ox":"O","m":"②","c":"A","tp":"헌법소원의 보충성"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-3","t":"사법경찰관인 피청구인이 청구인에 관한 보도자료를 기자들에게 배포한 행위는 수사기관이 공소제기 이전에 피의사실을 대외적으로 알리는 것으로서, 이것이 형법 제126조의 피의사실공표죄에 해당하는 범죄행위라면 청구인은 이를 수사기관에 고소하고 그 처리결과에 따라 검찰청법에 따른 항고를 거쳐 재정신청을 할 수 있으므로, 위와 같은 권리구제절차를 거치지 아니한 채 제기한 보도자료 배포행위에 대한 심판청구는 보충성 요건을 갖추지 못하여 부적법하다.","ox":"O","m":"③","c":"A","tp":"헌법소원의 보충성"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-4","t":"행정심판이나 행정소송 등의 사전구제절차를 거치지 아니하고 청구한 국가인권위원회의 진정에 대한 각하 또는 기각결정의 취소를 구하는 헌법소원심판은 보충성 요건을 충족하지 못한 것이다.","ox":"O","m":"④","c":"A","tp":"헌법소원의 보충성"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-5","t":"공공기관의 정보공개에 관한 법률에 별도의 불복절차가 마련되어 있으므로, 피청구인의 정보비공개결정에 대하여 청구인이 위 불복절차를 거치지 아니하고 곧바로 이 사건 헌법소원심판을 청구한 것은 보충성 요건을 결여한 것이다.","ox":"O","m":"⑤","c":"A","tp":"헌법소원의 보충성"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-1","t":"헌법재판소법 제47조 제1항 및 제75조 제1항에 규정된 법률의 위헌결정 및 헌법소원 인용결정의 기속력과 관련하여, 입법자인 국회에게 기속력이 미치는지 여부, 나아가 결정주문뿐 아니라 결정이유에까지 기속력을 인정할지 여부는 헌법재판소의 헌법재판권 내지 사법권의 범위와 한계, 국회의 입법권의 범위와 한계 등을 고려하여 신중하게 접근할 필요가 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-2","t":"헌법재판소법 제68조 제2항 후문은 당사자가 당해 사건의 소송절차에서 동일한 사유를 이유로 다시 위헌법률심판을 제청신청할 수 없다고 규정하고 있는데, 여기서 당해 사건의 소송절차란 당해 사건의 상소심 소송절차는 물론 대법원에 의해 파기환송되기 전후의 소송절차를 모두 포함한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-3","t":"일반적으로 법률이 헌법에 위반된다는 사정은 헌법재판소의 위헌결정이 있기 전에는 객관적으로 명백한 것이라고 할 수 없어, 법률이 헌법에 위반되는지 여부를 심사할 권한이 없는 공무원으로서는 행위 당시의 법률에 따를 수 밖에 없으므로, 행위의 근거가 된 법률조항에 대하여 위헌결정이 선고되더라도 위 법률조항에 따라 행위한 당해 공무원에게는 고의 또는 과실이 있다 할 수 없어 국가배상책임은 성립되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-4","t":"강북구청장이 한 ‘4·19혁명 국민문화제 2015 전국 대학생 토론대회’ 공모는 민법상 우수현상광고 또는 이와 유사한 성격의 법률행위라고 봄이 상당하고, 이 사건 공고가 법률상 근거에 따른 법집행작용의 일환이라고 보기도 어려우며, 국민에게 어떠한 권리나 의무를 부여하는 것으로 볼 수 없는 점 등을 종합하면, 이 사건 공고는 사법상 법률행위에 불과하고 공권력 행사의 주체라는 우월적 지위에서 한 것으로서 헌법재판소법 제68조 제1항에 따른 헌법소원심판의 대상인 ‘공권력의 행사’라고 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-5","t":"관습법은 사회의 거듭된 관행으로 생성한 사회생활규범이 사회의 법적 확신과 인식에 의하여 법적 규범으로 승인되고 강행되기에 이른 것을 말하는데, 그러한 관습법은 법원(法源)으로서 법령에 저촉되지 아니하는 한 법칙으로서의 효력이 있는 것이다. 따라서 관습법은 형식적 의미의 법률과 동일한 효력이 없으므로 헌법재판소의 위헌법률심판이나 헌법재판소법 제68조 제2항에 따른 헌법소원심판의 대상이 될 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-1","t":"재판의 전제성이라 함은 구체적인 사건이 법원에 계속 중이어야 하고, 위헌 여부가 문제되는 법률이 당해 소송사건의 재판에 적용되는 것이어야 하며, 그 법률이 헌법에 위반되는지 여부에 따라 당해 소송사건을 담당하는 법원이 다른 내용의 재판을 하게 되는 경우를 말한다.","ox":"O","m":"①","c":"A","tp":"위헌법률심판의 적법요건인 재판의 전제성"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-2","t":"재판의 전제성과 관련하여 법원이 다른 내용의 재판을 하게 되는 경우라 함은 문제된 법률의 위헌 여부가 당해 사건의 재판의 결론이나 주문에 영향을 주는 것 뿐만 아니라, 재판의 주문에 영향을 미치지 않아도 재판의 내용과 효력에 관한 법률적 의미가 달라지는 경우도 포함한다.","ox":"O","m":"②","c":"A","tp":"위헌법률심판의 적법요건인 재판의 전제성"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-3","t":"당해 사건에는 구법조항이 적용되었는데 법원이 동일한 내용의 신법조항을 제청한 경우에 신법조항의 위헌 여부는 당해사건에 적용되지 않으므로 재판의 전제성이 없다.","ox":"O","m":"③","c":"A","tp":"위헌법률심판의 적법요건인 재판의 전제성"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-4","t":"공소가 제기되지 아니한 사실에 적용되는 법률조항의 위헌 여부는 다른 특별한 사정이 없는 한 당해 형사사건에서 재판의 전제가 될 수 있다.","ox":"X","m":"④","c":"A","tp":"위헌법률심판의 적법요건인 재판의 전제성"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-5","t":"법원이 위헌법률심판제청을 한 경우 재판의 전제성 요건을 갖추었는지 여부에 대하여 되도록 제청법원의 법률적 견해를 존중해야 하지만, 재판의 전제성에 관한 제청법원의 법률적 견해가 명백하게 유지될 수 없을 때에는 헌법재판소가 그 제청을 부적법하다고 하여 각하할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"위헌법률심판의 적법요건인 재판의 전제성"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-1","t":"경찰의 차벽 설치로 인하여 청구인 A의 기본권 침해 가능성이 인정된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-2","t":"경찰의 차벽 설치 행위는 이른바 ‘권력적 사실행위’에 해당하여 행정소송의 대상이 되나 이미 경찰의 차벽설치행위가 종료되고 서울광장 통행이 재개되어 행정소송을 제기해도 소의 이익이 부정될 가능성이 높아서 예외적으로 보충성의 원칙이 인정된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-3","t":"헌법소원은 주관적 권리구제 뿐만 아니라 객관적 헌법질서의 보장 기능도 겸하고 있으므로 비록 경찰의 차벽 설치행위가 종료되었다고 하여도 이와 같은 행위가 다시 반복될 것이 예상되므로 권리보호의 이익이 인정된다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-4","t":"경찰의 차벽 설치 행위로 침해되는 A의 기본권은 헌법 제14조의 거주ㆍ이전의 자유이다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-5","t":"경찰이 차벽을 설치하여 청구인 A의 서울광장 통행을 제지한 것은 과잉금지원칙에 위반되어 A의 기본권을 침해한 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06","t":"헌법재판에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"헌법재판에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["헌법소원심판절차에서 당사자인 사인(私人)은 자신이 변호사 자격이 있는 경우가 아닌 한, 변호사를 대리인으로 선임하여야 한다.","탄핵심판절차에서 재판관 3인으로 구성되는 지정재판부를 두어 사전심사를 담당하게 하는 것은 허용되지 않는다.","권한쟁의심판에서는 관여 재판관 과반수의 찬성으로 결정할 수 있다.","정당해산심판에서는 재판관 6명 이상의 찬성으로 인용결정을 할 수 있다.","이미 헌법재판소가 합헌결정을 한 법률조항에 대해 다시 헌법소원심판을 청구하는 것은 헌법재판소 결정의 기속력에 반하므로 각하한다. 23-2"],"a":5}},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10","t":"탄핵심판에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"탄핵심판에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["국회가 탄핵소추사유에 대하여 별도의 조사를 하지 않았다거나 국정조사결과나 특별검사의 수사결과를 기다리지 않고 탄핵소추안을 의결하였다고 하여 그 의결이 헌법이나 법률을 위반한 것이라고 볼 수 없다.","탄핵소추의 발의가 있고 법제사법위원회에 회부하기로 의결하지 아니한 때에는 본회의에 보고된 때로부터 24시간 이후 72시간 이내에 탄핵소추의 여부를 무기명투표로 표결한다. 이 기간 내에 표결하지 아니한 때에는 그 탄핵소추안은 폐기된 것으로 본다.","탄핵소추절차는 국회와 대통령이라는 헌법기관 사이의 문제이고, 국회의 탄핵소추의결에 따라 사인으로서 대통령 개인의 기본권이 침해되는 것이 아니며 국가기관으로서 대통령의 권한행사가 정지될 뿐이어서, 국가기관이 국민에 대하여 공권력을 행사할 때 준수하여야 하는 법원칙으로 형성된 적법절차 원칙을 탄핵소추절차에 직접 적용할 수 없다.","헌법 제65조는 대통령이 ‘그 직무집행에 있어서 헌법이나 법률을 위배한 때’를 탄핵사유로 규정하고 있는데, 그 중 ‘헌법’은 명문의 헌법규정을, ‘법률’은 형식적 의미의 법률을 지칭한다고 해석하는 것이 명확성 원칙에 부합한다.","탄핵소추안을 각 소추사유별로 나누어 발의할 것인지, 아니면 여러 소추사유를 포함하여 하나의 안으로 발의할 것인지는 소추안을 발의하는 의원들의 자유로운 의사에 달린 것이다. 23-3"],"a":4}},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-1","t":"어떤 법률의 개념이 다의적이고 그 어의의 테두리안에서 여러 가지 해석이 가능할 때 헌법을 그 최고 법규로 하는 통일적인 법질서의 형성을 위하여 헌법에 합치되는 해석 즉 합헌적인 해석을 택하여야 하며, 이에 의하여 위헌적인 결과가 될 해석을 배제하면서 합헌적이고 긍정적인 면은 살려야 한다는 것이 헌법의 일반 법리이다.","ox":"O","m":"①","c":"A","tp":"합헌적 법률해석"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-2","t":"법률의 합헌적 해석은 헌법의 최고규범성에서 나오는 법질서의 통일성에 바탕을 두고, 법률이 헌법에 조화하여 해석될 수 있는 경우에는 위헌으로 판단하여서는 아니된다는 것을 뜻하는 것으로서 권력분립과 입법권을 존중하는 정신에 그 뿌리를 두고 있다.","ox":"O","m":"②","c":"A","tp":"합헌적 법률해석"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-3","t":"법률의 조항은 원칙적으로 가능한 범위안에서 합헌적으로 해석함이 마땅하나, 법률의 조항의 문구가 간직하고 있는 말의 뜻을 넘어서 말의 뜻이 완전히 다른 의미로 변질되지 아니하는 범위내이어야 한다는 문의적 한계와 입법권자가 그 법률의 제정으로써 추구하고자 하는 입법자의 명백한 의지와 입법의 목적을 헛되게 하는 내용으로 해석할 수 없다는 법목적에 따른 한계가 있다.","ox":"O","m":"③","c":"A","tp":"합헌적 법률해석"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-4","t":"구체적 사건에서의 법률의 해석·적용권한은 사법권의 본질적 내용을 이루는 것으로서, 합헌적 법률해석은 대법원을 정점으로 하는 일반법원이 하여야 하는 임무이고, 법률의 위헌심사를 맡는 헌법재판소의 임무는 아니다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-5","t":"합헌적인 한정축소해석은 위헌적인 해석 가능성과 그에 따른 법적용을 소극적으로 배제한 것이고, 적용범위의 축소에 의한 한정위헌결정은 위헌적인 법적용 영역과 그에 상응하는 해석 가능성을 적극적으로 배제한다는 뜻에서 차이가 있을 뿐, 본질적으로는 같은 방법이다.","ox":"O","m":"⑤","c":"A","tp":"합헌적 법률해석"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10","t":"다음 중 위헌법률심판 및 헌법재판소법 제68조 제2항에 따른 헌법소원심판의 대상이 될 수 없는 것은?","c":"A","mc":{"s":"다음 중 위헌법률심판 및 헌법재판소법 제68조 제2항에 따른 헌법소원심판의 대상이 될 수 없는 것은?","d":"","o":["대한민국과 아메리카합중국 간의 상호방위조약 제4조에 의한 시설과 구역 및 대한민국에서의 합중국군대의 지위에 관한 협정 제2조 제1의 (나)항","국제통화기금 임직원의 공적 행위에 대한 재판권 면제 등을 규정한 국제통화기금협정 제9조 제3항","군인 등의 국가배상청구를 제한하고 있는 헌법 제29조 제2항","일반적으로 승인된 국제법규","‘여호주가 사망하거나 출가하여 호주상속 없이 절가된 경우 유산은 그 절가된 가(家)의 가족이 승계하고 가족이 없을 때에는 출가녀(出家女)가 승계한다’는 구 관습법"],"a":3}},{"y":2019,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2019_25-14","t":"헌법소원의 보충성 요건에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"헌법소원의 보충성 요건에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["다른 법률이 정한 절차에 따라 침해된 기본권의 구제를 받기 위한 모든 수단을 다하지 아니한 채 헌법소원을 제기하였더라도 종국결정 전에 권리구제절차를 거쳤다면 사전에 구제절차를 거치지 않은 하자가 치유될 수 있다.","손해배상청구나 손실보상청구, 진정, 형의 집행 및 수용자의 처우에 관한 법률상 청원제도는 헌법재판소법 제68조 제1항 단서의 ‘다른 법률에서 정한 구제절차’에 해당하지 아니한다.","금치처분을 받은 자에 대하여 금치기간 중에는 집필을 금지하고 있는 형의 집행 및 수용자의 처우에 관한 법률 시행령 조항에 대해서는 다른 구제절차 없이 바로 헌법소원심판을 청구할 수 있다.","행정관청의 고시는 일반적․추상적 성격을 가지므로 다른 구제절차를 거칠 것 없이 바로 헌법소원심판을 청구할 수 있다.","구속된 피의자가 검사조사실에서 수갑 및 포승을 시용(施用)한 상태로 피의자신문을 받도록 한 행위는 이미 종료된 권력적 사실행위로서 행정심판이나 행정소송의 대상으로 인정되기 어려워 헌법소원심판을 청구하는 외에 달리 효과적인 구제방법이 없으므로 보충성 원칙에 대한 예외에 해당한다. 22-4"],"a":4}},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-1","t":"헌법재판소법 제41조 제1항의 재판이라 함은 판결·결정·명령 등 그 형식 여하와 본안에 관한 재판이거나 소송절차에 관한 재판이거나를 불문하며 심급을 종국적으로 종결시키는 종국재판뿐만 아니라 중간재판도 이에 포함된다.","ox":"O","m":"①","c":"A","tp":"위헌법률심판"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-2","t":"대법원 외의 법원은 대법원을 거칠 필요 없이 직접 헌법재판소에 헌법재판소법 제41조 제1항의 위헌심판 제청을 할 수 있다.","ox":"X","m":"②","c":"A","tp":"위헌법률심판"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-3","t":"헌법재판소법 제41조 제1항에 따른 법률의 위헌 여부 심판의 제청신청이 기각된 때에 그 신청을 한 당사자는 헌법재판소에 헌법재판소법 제68조 제2항의 헌법소원심판을 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"위헌법률심판"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-4","t":"법원이 헌법재판소에 법률의 위헌 여부의 심판을 제청한 때에는 당해 소송사건의 재판은 헌법재판소의 위헌 여부의 결정이 있을 때까지 정지되나, 다만 법원이 긴급하다고 인정하는 경우에는 종국재판 외의 소송절차를 진행할 수 있다.","ox":"O","m":"④","c":"A","tp":"위헌법률심판"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-5","t":"군사법원도 위헌법률심판을 제청할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-1","t":"헌법재판소는 법관의 자격을 가진 9인의 재판관으로 구성하고, 재판관은 대통령이 임명한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-2","t":"헌법재판소 재판관의 임기는 6년으로 하며, 법률이 정하는 바에 의하여 연임할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-3","t":"헌법재판소 재판관은 정당에 가입하거나 정치에 관여할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-4","t":"헌법재판소 재판관은 탄핵 또는 금고 이상의 형의 선고에 의하지 아니하고는 파면되지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-5","t":"헌법재판소에서 법률의 위헌결정, 탄핵의 결정, 정당해산의 결정 또는 헌법소원에 관한 인용결정을 할 때에는 재판관 5인 이상의 찬성이 있어야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-1","t":"행정청이 우월적 지위에서 일방적으로 강제하는 ‘권력적 사실행위’는 헌법소원의 대상이 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-2","t":"대통령의 법률안 제출행위는 국가기관 사이의 내부적 행위에 불과하므로 헌법소원심판의 대상이 되는 공권력의 행사가 아니다.","ox":"O","m":"②","c":"A","tp":"헌법소원의 대상"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-3","t":"명령·규칙 그 자체에 의하여 직접 기본권이 침해된 경우, 대법원이 이를 최종적으로 심사할 권한을 가지므로 명령·규칙은 헌법소원의 대상이 될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-4","t":"예산은 일반국민을 구속하지 않으므로 국회의 예산안 의결행위는 헌법소원의 대상이 되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-5","t":"헌법 해석상 특정인의 기본권을 보호하기 위한 국가의 입법의무가 발생하였음에도 불구하고 입법자가 아무런 입법조치를 취하지 않고 있는 경우 그 입법부작위는 헌법소원의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-1","t":"헌법재판소는 법관의 자격을 가진 9인의 재판관으로 구성하며, 재판관은 대통령이 임명한다.","ox":"O","m":"①","c":"A","tp":"헌법재판소 및 위헌법률심사"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-2","t":"위헌법률심판의 대상이 되는 ‘법률’에는 국회의 의결을 거친 형식적 의미의 법률뿐만 아니라 조약 등 형식적 의미의 법률과 동일한 효력을 가지는 법규범들도 포함된다.","ox":"O","m":"②","c":"A","tp":"헌법재판소 및 위헌법률심사"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-3","t":"법률의 위헌 여부가 재판의 전제가 된 경우 법원은 헌법재판소에 제청하여 그 심판에 의하여 재판을 하는데, 여기서 말하는 재판에는 본안에 관한 재판 외에 소송절차에 관한 재판도 포함된다.","ox":"O","m":"③","c":"A","tp":"헌법재판소 및 위헌법률심사"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-4","t":"헌법재판소법 제68조 제2항의 헌법소원은 법률의 위헌여부 심판의 제청신청을 하여 그 신청이 기각된 때에 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"헌법재판소 및 위헌법률심사"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-5","t":"개별적, 구체적 사건에서 법률조항의 단순한 포섭, 적용에 관한 문제를 다투는 것도 적법한 헌법소원 심판청구에 해당한다.","ox":"X","m":"⑤","c":"A","tp":"헌법재판소 및 위헌법률심사"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-1","t":"행정규칙은 원칙적으로 헌법소원의 대상이 될 수 없으나, 예외적으로 법령의 규정에 의하여 행정관청에 법령의 구체적 내용을 보충할 권한을 부여한 경우나, 재량권행사의 준칙으로서 그 정한 바에 따라 되풀이 시행되어 행정관행이 형성됨으로써 평등의 원칙이나 신뢰보호의 원칙에 따라 행정기관이 그 상대방에 대한 관계에서 그 규칙에 따라야 할 자기구속을 당하게 되는 경우에는 헌법소원의 대상이 될 수도 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-2","t":"중앙선거관리위원회가 ‘비례○○당’의 명칭이 정당법에서 금지하는 유사명칭에 해당하여 정당의 명칭으로 사용할 수 없다고 결정·공표한 행위는 정당의 법적 지위에 영향을 미치므로 헌법소원의 대상이 되는 공권력의 행사에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-3","t":"대통령기록물 소관 기록관이 대통령기록물을 중앙기록물관리기관으로 이관하는 행위는 국가기관 사이의 내부적·절차적 행위에 불과하므로 헌법소원의 대상이 되는 공권력의 행사에 해당하지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-4","t":"경찰서장이 시장에게 활동보조인과 수급자의 인적사항, 휴대전화번호 등을 확인할 수 있는 자료를 요청한 것에 대하여 시장은 협조할 의무를 부담하지 않으므로 경찰서장의 위와 같은 요청행위는 공권력 행사성이 인정되지 않는다.","ox":"O","m":"④","c":"A","tp":"헌법소원의 대상"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-5","t":"행정권력의 부작위에 대한 헌법소원은 공권력의 주체에게 헌법에서 유래하는 작위의무가 특별히 구체적으로 규정되어 이에 의거하여 기본권의 주체가 행정행위 내지 공권력의 행사를 청구할 수 있음에도 공권력의 주체가 그 의무를 해태하는 경우에 한하여 허용된다.","ox":"O","m":"⑤","c":"A","tp":"헌법소원의 대상"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-1","t":"국가기관의 법률상 권한은 국회의 입법행위에 의하여 형성·부여된 권한일 뿐, 역으로 국회의 입법행위를 구속하는 기준이 될 수 없으므로, 침해의 원인이 ‘국회의 입법행위’인 경우에 ‘법률상 권한’을 침해의 대상으로 삼는 심판청구는 그 권한침해가능성을 인정할 수 없다.","ox":"O","m":"①","c":"A","tp":"권한쟁의심판"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-2","t":"국가기관과 지방자치단체 간 권한쟁의심판의 당사자에 관한 헌법재판소법 제62조 제1항 제2호의 ‘정부’는 예시규정이므로, 정부 뿐 아니라 정부의 부분기관, 국회, 법원도 당사자가 될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-3","t":"국가기관과 지방자치단체 간, 지방자치단체 상호 간 권한쟁의심판의 당사자에 관한 헌법재판소법 제62조 제1항 제3호의 ‘지방자치단체’는 예시규정이라 할 수 없으므로, 지방의회나 교육감은 당사자가 될 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-4","t":"중앙행정기관이나 광역지방자치단체가 지방자치단체의 자치사무에 대한 감사에 착수하기 위해서는 감사대상이 사전에 특정되어야 하고, 연간감사계획에 포함되지 아니한 감사라 하더라도 감사대상 지방자치단체에게 특정된 감사대상을 사전에 통보하는 것이 감사의 개시요건이라 할 것이므로, 그러한 절차를 거치지 않았다면 해당 감사착수는 적법하다고 볼 수 없다.","ox":"X","m":"④","c":"A","tp":"권한쟁의심판"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-5","t":"권한쟁의심판을 청구하기 위해서는 피청구인의 처분 또는 부작위가 요구되므로, 정부의 법률안 제출행위, 행정안전부장관의 단순한 견해표명 또는 업무연락은 처분성이 인정되지 아니하여 권한쟁의심판의 대상이 되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-1","t":"형사재판 유죄확정판결이 있은 후 당해 처벌 근거조항에 대해 위헌결정이 내려진 경우 유죄판결을 받은 자는 재심청구를 통하여 유죄의 확정판결을 다툴 수 있다.","ox":"O","m":"①","c":"A","tp":"헌법재판소 위헌결정의 효력 등"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-2","t":"헌법재판소법은 법률의 위헌결정, 권한쟁의심판의 결정, 헌법소원의 인용결정에 대한 기속력을 명문으로 규정하고 있다.","ox":"O","m":"②","c":"A","tp":"헌법재판소 위헌결정의 효력 등"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-3","t":"형벌에 관한 법률 또는 법률의 조항이 위헌으로 결정된 경우 소급하여 그 효력을 상실하지만, 종전에 합헌으로 결정한 사건이 있는 경우에는 그 결정이 있는 날로 소급하여 효력을 상실한다.","ox":"X","m":"③","c":"A","tp":"헌법재판소 위헌결정의 효력 등"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-4","t":"헌법재판소의 헌법불합치결정은 법률조항에 대한 위헌결정에 해당하므로, 형벌에 관한 법률조항을 이루게 되는 집회 및 시위에 관한 법률 조항에 대하여 헌법불합치결정이 선고된 경우 헌법재판소가 위 조항에 대하여 잠정적용을 명한 경우라 하더라도 형벌에 관한 법률조항에 대하여 위헌결정이 선고된 경우 그 조항이 소급하여 효력을 상실한다고 규정한 헌법재판소법 조항에 따라 위 조항은 소급하여 효력을 상실한다.","ox":"O","m":"④","c":"A","tp":"헌법재판소 위헌결정의 효력 등"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-5","t":"법률조항의 위헌결정으로 인하여 당해 법률 전부를 시행할 수 없다고 인정될 때에는 그 전부에 대하여도 위헌결정을 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"헌법재판소 위헌결정의 효력 등"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-1","t":"헌법 제65조는 행정부와 사법부의 고위공직자에 의한 헌법위반이나 법률위반에 대하여 탄핵소추의 가능성을 규정함으로써, 그들에 의한 헌법위반을 경고하고 사전에 방지하는 기능을 하며, 국민에 의하여 국가권력을 위임받은 국가기관이 그 권한을 남용하여 헌법이나 법률에 위반하는 경우에는 다시 그 권한을 박탈하는 기능을 한다. 즉, 공직자가 직무수행에 있어서 헌법에 위반한 경우 그에 대한 법적 책임을 추궁함으로써, 헌법의 규범력을 확보하고자 하는 것이 바로 탄핵심판절차의 목적과 기능인 것이다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-2","t":"국회의 의사절차에 헌법이나 법률을 명백히 위반한 흠이 있는 경우가 아니면 국회 의사절차의 자율권은 권력분립의 원칙상 존중되어야 하고, 국회법 제130조 제1항은 탄핵소추의 발의가 있을 때 그 사유 등에 대한 조사 여부를 국회의 재량으로 규정하고 있으므로, 국회가 탄핵소추사유에 대하여 별도의 조사를 하지 않았다거나 국정조사결과나 특별검사의 수사결과를 기다리지 않고 탄핵소추안을 의결하였다고 하여 그 의결이 헌법이나 법률을 위반한 것이라고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-3","t":"대통령ㆍ국무총리ㆍ국무위원ㆍ행정각부의장ㆍ헌법재판소 재판관ㆍ법관ㆍ중앙선거관리위원회위원ㆍ감사원장ㆍ감사위원 기타 법률이 정한 공무원이 그 직무집행에 있어서 헌법이나 법률을 위배한 때에는 국회는 탄핵의 소추를 의결할 수 있다. 탄핵소추는 국회재적의원 3분의 1 이상의 발의가 있어야 하며, 그 의결은 국회재적의원 과반수의 찬성이 있어야 한다. 다만, 대통령에 대한 탄핵소추는 국회재적의원 과반수의 발의와 국회재적의원 3분의 2 이상의 찬성이 있어야 한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-4","t":"국가기관이 국민에 대하여 공권력을 행사할 때 준수하여야 하는 법원칙으로 형성된 적법절차의 원칙을 국가기관에 대하여 헌법을 수호하고자 하는 탄핵소추절차에 직접 적용할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-5","t":"피청구인에 대한 탄핵심판 청구와 동일한 사유로 형사소송이 진행되고 있는 경우에는 재판부는 심판절차를 정지하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-1","t":"양육비 대지급제 등 양육비 이행의 실효성을 더 높이는 내용의 법률을 제정할 헌법의 명시적인 입법위임이 존재한다고 볼 수 없고, 헌법해석상 기존의 양육비 이행을 확보하기 위하여 마련된 여러 입법 이외에 양육비 대지급제 등과 같은 구체적ㆍ개별적 사항에 대한 입법의무가 새롭게 발생된다고도 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"입법부작위"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-2","t":"진정입법부작위에 대한 헌법소원심판청구는 헌법에서 기본권 보장을 위하여 법률에 명시적으로 입법위임을 하였음에도 입법자가 이를 이행하지 아니한 경우이거나, 헌법 해석상 특정인에게 구체적인 기본권이 생겨 이를 보장하기 위한 국가의 행위의무 내지 보호의무가 발생하였음이 명백함에도 불구하고 입법자가 아무런 입법조치를 취하지 아니한 경우에 한하여 허용된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-3","t":"의료인이 아닌 사람도 문신시술을 업으로 행할 수 있도록 그 자격 및 요건을 법률로 제정하도록 하는 내용의 명시적인 입법위임은 헌법에 존재하지 않으며, 문신시술을 위한 별도의 자격제도를 마련할지 여부는 여러 가지 사회적ㆍ경제적 사정을 참작하여 입법부가 결정할 사항으로, 그에 관한 입법의무가 헌법해석상 도출된다고 보기는 어렵다.","ox":"O","m":"③","c":"A","tp":"입법부작위"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-4","t":"가정폭력 가해자인 전 남편이 이혼 후 추가 가해 목적으로 자녀의 가족관계증명서 및 기본증명서의 교부를 청구하는 것이 분명한 경우에도 이를 제한하는 규정을 제정하지 아니한 ‘가족관계의 등록 등에 관한 법률’의 입법부작위는 청구인의 개인정보자기결정권을 침해하는 진정입법부작위에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-5","t":"가족이 북한 내 정치범수용소에 억류되어 있는 북한이탈주민 등이 이른바 ‘북한인권법’을 제정하지 아니한 입법부작위가 청구인들의 기본권을 침해한다고 주장하며 제기한 헌법소원심판 계속 중에 국회가 북한인권법을 제정하였다면, 더 이상 권리보호이익이 존재한다고 보기 어렵고, 달리 헌법적 해명의 필요성도 찾아보기 어려우므로 헌법소원심판청구는 부적법하다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-1","t":"헌법재판소가 권한쟁의심판의 청구를 받았을 때에는 직권 또는 청구인의 신청에 의하여 종국결정의 선고 시까지 심판대상이 된 피청구인의 처분의 효력을 정지하는 결정을 할 수 있고, 이 가처분결정을 함에 있어서는 행정소송법과 민사소송법 소정의 가처분 관련 규정이 준용된다.","ox":"O","m":"①","c":"A","tp":"헌법재판절차에서 행해지는 가처분"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-2","t":"본안심판이 부적법하거나 이유 없음이 명백하지 않고, 권한쟁의심판에서 문제된 피청구인의 처분 등이나 그 집행 또는 절차의 속행으로 인하여 생길 회복하기 어려운 손해를 예방할 필요와 그 효력을 정지시켜야 할 긴급한 필요가 있으며, 가처분을 인용한 뒤 종국결정에서 청구가 기각되었을 때 발생하게 될 불이익과 가처분을 기각한 뒤 청구가 인용되었을 때 발생하게 될 불이익을 비교형량하여 후자의 불이익이 전자의 불이익보다 클 경우 가처분을 인용할 수 있다.","ox":"O","m":"②","c":"A","tp":"헌법재판절차에서 행해지는 가처분"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-3","t":"헌법소원심판절차에 있어 헌법재판소법상 명문의 규정을 두고 있지 않으나 가처분이 허용된다 할 것이고, 이러한 가처분결정은 헌법소원심판에서 다투어지는 ‘공권력 행사 또는 불행사’의 현상을 그대로 유지시킴으로 인하여 생길 회복하기 어려운 손해를 예방할 필요가 있어야 하고 그 효력을 정지시켜야 할 긴급한 필요가 있는 경우 인용할 수 있다.","ox":"O","m":"③","c":"A","tp":"헌법재판절차에서 행해지는 가처분"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-4","t":"법령의 위헌확인을 청구하는 헌법소원심판에서의 가처분이 사인간의 법률관계나 행정청의 구체적 처분의 효력을 정지시키는 것이 아니라 현재 시행되고 있는 법령의 효력을 정지시키는 것일 때에는 그 효력의 정지로 인하여 파급적으로 발생되는 효과가 클 수도 있기 때문에 이러한 점까지 고려하여 신중하게 판단하여야 한다.","ox":"O","m":"④","c":"A","tp":"헌법재판절차에서 행해지는 가처분"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-5","t":"입국불허결정을 받은 외국인이, “출입국관리사무소장”을 상대로 제기한 인신보호법상 수용임시해제청구의 소가 인용되었고, 인신보호청구의 소 역시 항고심에서 인용된 후 재항고심에 계속 중이며, 난민인정심사불회부결정취소의 소 역시 청구를 인용하는 제1심 판결이 선고되었다면, 비록 위 소송 제기 후 5개월 이상 변호인을 접견하지 못한 상태라 하더라도 변호인 접견 허가에 관한 임시지위를 정하기 위한 가처분과 관련하여 손해를 방지할 긴급한 필요가 인정된다고 보기 어렵다.","ox":"X","m":"⑤","c":"A","tp":"헌법재판절차에서 행해지는 가처분"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-1","t":"헌법 제65조는 행정각부의 장이 ‘그 직무집행에 있어서 헌법이나 법률을 위배한 때’를 탄핵소추사유로 규정하고 있는데, 여기에서 ‘직무’란 법제상 소관 직무에 속하는 고유 업무와 사회통념상 이와 관련된 업무를 말하고, 법령에 근거한 행위뿐만 아니라 행정각부의 장의 지위에서 국정수행과 관련하여 행하는 모든 행위를 포괄하는 개념이다.","ox":"O","m":"①","c":"A","tp":"탄핵소추심판"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-2","t":"탄핵소추사유인 헌법과 법률 위반과 관련하여, 헌법 제65조에서 말하는 ‘헌법’에는 명문의 헌법규정뿐만 아니라 헌법재판소의 결정에 따라 형성되어 확립된 불문헌법도 포함되고, ‘법률’에는 형식적 의미의 법률과 이와 동등한 효력을 가지는 국제조약 및 일반적으로 승인된 국제법규 등이 포함된다.","ox":"O","m":"②","c":"A","tp":"탄핵소추심판"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-3","t":"행정각부의 장은 정부 권한에 속하는 중요정책을 심의하는 국무회의의 구성원이자 행정부의 소관 사무를 통할하고 소속공무원을 지휘ㆍ감독하는 기관으로서 행정부 내에서 통치기구와 집행기구를 연결하는 가교 역할을 하므로, 그에 대한 파면 결정이 가져올 수 있는 국정공백과 정치적 혼란 등 국가적 손실이 경미하다고 평가하기 어렵다.","ox":"O","m":"③","c":"A","tp":"탄핵소추심판"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-4","t":"‘탄핵심판 청구가 이유 있는 경우’란 피청구인의 파면을 정당화할 수 있을 정도로 중대한 헌법이나 법률 위반이 있는 경우를 말하는데, 국가 원수이자 행정부의 수반으로서 국민의 선거에 의하여 선출되어 직접적인 민주적 정당성을 부여받은 대통령과 행정각부의 장은 정치적 기능이나 비중에서 본질적 차이가 있고, 양자 사이의 직무계속성의 공익이 다름에 따라 파면의 효과 역시 근본적인 차이가 있으므로, ‘법 위반행위의 중대성’과 ‘파면 결정으로 인한 효과’ 사이의 법익형량을 함에 있어 이와 같은 점이 고려되어야 한다.","ox":"O","m":"④","c":"A","tp":"탄핵소추심판"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-5","t":"헌법 제65조의 탄핵제도는 고위공직자가 그 지위에서 국민의 대의기관인 국회로부터 헌법이나 법률 위반의 법적 책임을 추궁받는 제도이므로, 탄핵소추를 받은 자가 임기만료로 퇴직하여 더 이상 공직을 보유하지 않게 되었다면 탄핵심판에서의 피청구인자격을 상실하여 심판절차가 종료된 것으로 보아야 한다.","ox":"X","m":"⑤","c":"A","tp":"탄핵소추심판"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-1","t":"헌법재판소법 제68조 제2항에 의한 헌법소원은 법률의 위헌성을 적극적으로 다투는 제도이므로, 법률의 부존재, 즉 진정입법부작위를 다투는 것은 허용되지 아니하고, 다만 법률이 불완전·불충분하게 규정되었음을 주장하며 법률 자체의 위헌성을 다투는 취지라면 이는 그 법률이 당해 사건의 재판의 전제가 된다는 것을 요건으로 허용될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-2","t":"행정절차에서의 위법하거나 부당한 구금의 피해자에 대하여 형사보상 및 명예회복에 관한 법률에 보상 규정을 두지 않은 입법부작위는 진정입법부작위에 해당한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-3","t":"국가로 하여금 무죄판결이 확정된 피고인에 대하여 그 재판에 소요된 비용을 보상하도록 규정한 형사소송법 제194조의2 제1항에서 기소유예처분을 받았다가 헌법재판소의 취소결정을 받고 혐의없음의 불기소처분을 받은 피의자에 대한 경우를 비용보상의 대상으로 규정하지 아니한 것은 비용보상의 요건을 불완전·불충분하게 규정한 것에 해당한다.","ox":"X","m":"③","c":"A","tp":"입법부작위"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-4","t":"70세 이상인 불구속 피의자에 대하여 국선변호인을 선정하는 제도를 두지 않은 입법부작위는 헌법소원의 대상이 될 수 없는 입법부작위에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-5","t":"6·25전쟁 중(1950. 6. 25.부터 1953. 7. 27. 군사정전에 관한 협정 체결 전까지를 말한다) 본인의 의사에 반하여 북한에 의하여 강제로 납북된 자 및 그 가족에 대한 보상입법을 마련하지 아니한 입법부작위는 헌법소원의 대상이 될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05-1","t":"헌법소원심판청구 당시 권리보호이익이 인정되더라도 심판 계속 중에 사실관계 또는 법률관계의 변동으로 말미암아 청구인이 주장하는 기본권의 침해가 종료된 경우에는 원칙적으로 권리보호이익이 없다.","ox":"O","m":"①","c":"A","tp":"헌법소원에서의 권리보호이익"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05-2","t":"대법원호적예규 중 한자 성의 한글표기에 관하여 두음법칙을 예외 없이 일률적·획일적으로 적용하도록 규정하던 부분이 헌법소원 심판청구 후 합리적 사유가 있는 경우에는 두음법칙에 따르지 않을 수 있도록 개정되었다면 위 부분의 위헌 확인을 구할 권리보호이익이 상실된다.","ox":"O","m":"②","c":"A","tp":"헌법소원에서의 권리보호이익"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05-3","t":"헌법소원심판청구가 청구인의 주관적 권리구제에는 도움이 되지 않는다 하더라도 그러한 침해행위가 앞으로도 반복될 위험이 있고, 당해 분쟁의 해결이 헌법질서의 수호·유지를 위하여 긴요한 사항이어서 헌법적으로 그 해명이 중대한 의미를 지니고 있는 경우에는 예외적으로 심판의 이익을 인정할 수 있다.","ox":"O","m":"③","c":"A","tp":"헌법소원에서의 권리보호이익"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05-4","t":"행정5급 일반임기제공무원을 채용하는 경력경쟁채용시험공고를 하면서, 그 응시자격요건으로 변호사 자격 등록을 요구한 방위사업청 공고의 위헌확인을 구하는 헌법소원에 대해서는 예외적으로 심판의 이익을 인정하기 어렵다.","ox":"X","m":"④","c":"A","tp":"헌법소원에서의 권리보호이익"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05-5","t":"구치소장이 변호인접견실에 CCTV를 설치하여 접견 장면을 관찰하는 행위는 반복될 우려가 있고, 이는 미결수용자에 대한 기본적 처우와 관련된 중요한 문제로서 그에 대한 헌법적 해명은 헌법질서의 수호⋅유지를 위해 중요한 의미를 가지므로 이에 대해서는 심판의 이익을 인정할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"헌법소원에서의 권리보호이익"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-1","t":"헌법재판소법 제68조 제1항에서의 ‘공권력’은 입법권·행정권·사법권을 행사하는 모든 국가기관·공공단체 등의 고권적 작용을 말하고, 그 행사 또는 불행사로 국민의 권리와 의무에 대하여 직접적인 법률효과를 발생시켜 청구인의 법률관계 내지 법적 지위를 불리하게 변화시키는 것이어야 한다.","ox":"O","m":"①","c":"A","tp":"헌법재판소법 제68조 제1항의 ‘공권력의 행사 또는 불행사’"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-2","t":"일반적으로 어떤 행위가 헌법소원의 대상이 되는 권력적 사실행위에 해당하는지 여부는 당해 행정주체와 상대방의 관계, 그 사실행위에 대한 상대방의 의사·관여정도와 태도, 사실행위의 목적·경위, 법령에 의한 명령·강제수단 발동 가부 등 그 행위가 행하여질 당시의 구체적 사정을 종합적으로 고려하여 개별적으로 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"헌법재판소법 제68조 제1항의 ‘공권력의 행사 또는 불행사’"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-3","t":"행정권력의 부작위가 헌법소원의 대상이 되는 공권력의 불행사에 해당하려면, 공권력의 주체에게 헌법에서 유래하는 작위의무가 특별히 구체적으로 규정되어 이에 의거하여 기본권의 주체가 행정행위나 공권력의 행사를 청구할 수 있음에도 공권력의 주체가 그 의무를 해태하는 경우이어야 한다.","ox":"O","m":"③","c":"A","tp":"헌법재판소법 제68조 제1항의 ‘공권력의 행사 또는 불행사’"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-4","t":"대통령과 통일부장관에 의한 개성공단 전면중단 조치는 개성공단 투자기업들에 대해 일방적으로 행해진 권력적 사실행위로서 공권력의 행사에 해당한다.","ox":"O","m":"④","c":"A","tp":"헌법재판소법 제68조 제1항의 ‘공권력의 행사 또는 불행사’"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-5","t":"검찰수사관이 피의자신문에 참여한 변호인에게 변호인 참여신청서의 작성을 요구한 행위는 검찰수사관이 자신의 우월한 지위를 이용하여 변호인에게 일방적으로 강제한 것으로서 권력적 사실행위에 해당하여 헌법소원의 대상이 될 수 있다.","ox":"X","m":"⑤","c":"A","tp":"헌법재판소법 제68조 제1항의 ‘공권력의 행사 또는 불행사’"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-1","t":"헌법재판소는 법관의 자격을 가진 9인의 재판관으로 구성하며, 재판관은 대통령이 임명한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-2","t":"헌법재판소 재판관 중 3인은 국회에서 선출하는 자를, 3인은 대법원장이 지명하는 자를 임명한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-3","t":"헌법이 재판관 임명과 관련하여 국회에 부여한 선출권은 임명권자인 대통령의 재판관 임명권을 견제하기 위한 것일 뿐, 국회에 헌법재판소를 구성할 독자적이고 실질적인 권한을 부여한 것은 아니다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-4","t":"헌법재판소 재판관의 임기는 6년으로 하며 연임할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-5","t":"헌법재판소 재판관은 정당에 가입할 수 없다.","ox":"O","m":"⑤","c":"A"}],"2":[{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-1","t":"태아도 헌법상 생명권의 주체가 되며, 국가는 헌법 제10조에 따라 태아의 생명을 보호할 의무가 있으나, 초기배아는 자연과학적 인식 수준에서 독립된 인간과 배아 간의 개체적 연속성을 확정하기 어려우므로 기본권 주체성을 인정하기 어렵다.","ox":"O","m":"①","c":"A","tp":"기본권의 주체"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-2","t":"헌법은 국가의 교육권한과 부모의 교육권의 범주 내에서 학생에게도 자신의 교육에 관하여 스스로 결정할 권리, 즉 자유롭게 교육을 받을 권리를 부여하고, 학생은 국가의 간섭을 받지 아니하고 자신의 능력과 개성, 적성에 맞는 학교를 자유롭게 선택할 권리를 가진다.","ox":"O","m":"②","c":"A","tp":"기본권의 주체"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-3","t":"의료인의 면허된 의료행위 이외의 의료행위를 금지하고 처벌하는 의료법(2007. 4. 11. 법률 제8366호로 개정된 것) 제27조 제1항 본문 전단 부분이 제한하고 있는 직업선택의 자유는 인간의 존엄과 가치 및 행복추구권과 밀접한 관련을 가지는 권리이므로, 근로가 허용된 외국인의 경우 그 허용된 범위 안에서 위 규정이 제한하고 있던 근로의 권리와 직업선택의 자유가 회복된다.","ox":"X","m":"③","c":"A","tp":"기본권의 주체"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-4","t":"법인도 법인의 목적과 사회적 기능에 비추어 볼 때 그 성질에 반하지 않는 범위 내에서 인격권의 한 내용인 사회적 신용이나 명예 등의 주체가 될 수 있고 법인이 이러한 사회적 신용이나 명예 유지 내지 법인격의 자유로운 발현을 위하여 의사결정이나 행동을 어떻게 할 것인지를 자율적으로 결정하는 것도 법인의 인격권의 한 내용을 이룬다.","ox":"O","m":"④","c":"A","tp":"기본권의 주체"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-5","t":"대통령은 소속 정당을 위하여 정당활동을 할 수 있는 사인으로서의 지위와 국민 모두에 대한 봉사자로서 공익실현의 의무가 있는 헌법기관으로서의 지위를 동시에 갖는데 최소한 전자의 지위와 관련하여는 기본권 주체성을 갖는다.","ox":"O","m":"⑤","c":"A","tp":"기본권의 주체"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-1","t":"헌법재판소가 사업장에 종사하는 근로자의 3분의 2 이상을 대표하는 노동조합의 경우 단체협약을 매개로 조직강제를 용인하는 법률조항을 합헌으로 본 것은 노동조합의 적극적 단결권을 근로자 개인의 단결하지 않을 자유보다 중시한 것이다.","ox":"O","m":"①","c":"A","tp":"기본권의 경합과 충돌"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-2","t":"학생의 학습권은 교원의 수업권에 대하여 우월한 지위에 있으므로 교원이 고의로 수업을 거부할 자유는 인정되지 아니한다.","ox":"O","m":"②","c":"A","tp":"기본권의 경합과 충돌"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-3","t":"종교단체가 설립한 사립학교에서 특정종교의 교리를 전파하는 종교행사와 종교과목 수업을 실시하면서 참가 거부가 사실상 불가능한 분위기를 조성하고 대체과목을 개설하지 않는 등 다른 신앙을 가진 학생의 기본권을 고려하지 않는 것은 학생의 종교에 관한 인격적 법익을 침해하는 위법행위이다.","ox":"O","m":"③","c":"A","tp":"기본권의 경합과 충돌"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-4","t":"흡연권은 사생활의 자유를 실질적 핵으로 하는 것이고 혐연권은 사생활의 자유뿐만 아니라 생명권에까지 연결되는 것이므로 혐연권이 흡연권보다 상위의 기본권이다.","ox":"O","m":"④","c":"A","tp":"기본권의 경합과 충돌"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-5","t":"헌법재판소가 채권자취소권을 합헌으로 본 것은 채권자의 재산권과 채무자의 일반적 행동의 자유권 중에서 채권자의 재산권이 상위의 기본권이라고 보았기 때문이다.","ox":"X","m":"⑤","c":"A","tp":"기본권의 경합과 충돌"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-1","t":"개인이 자유의지에 의하여 자유롭게 자기의 삶과 운명을 결정할 수 있는 권리를 말하고, 헌법 명문의 규정은 없지만 기본권으로 인정된다.","ox":"O","m":"①","c":"A","tp":"헌법상 자기결정권"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-2","t":"간통을 형사 처벌하는 법률조항 및 혼인빙자간음을 형사 처벌하는 법률조항은 개인의 성적 자기결정권을 침해하여 헌법에 위반되지만, 성매매를 한 자를 형사 처벌하는 법률조항은 개인의 성적 자기결정권을 침해하지 않으므로 헌법에 위반되지 않는다.","ox":"O","m":"②","c":"A","tp":"헌법상 자기결정권"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-3","t":"시체의 처분에 관한 자기결정권이 인정되므로 인수자가 없는 시체를 생전의 본인의 의사와는 무관하게 해부용 시체로 제공하도록 하는 것은 개인의 시체처분에 관한 자기결정권을 침해하여 헌법에 위반된다.","ox":"O","m":"③","c":"A","tp":"헌법상 자기결정권"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-4","t":"임부가 약물 기타 방법으로 낙태하는 것을 처벌하는 법률 조항은 임부 개인의 자기 결정권을 침해하지 아니하므로 헌법에 위반되지 않는다.","ox":"O","m":"④","c":"A","tp":"헌법상 자기결정권"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-5","t":"법률로 안전띠 착용을 강제하는 것은 개인의 일반적 행동자유권을 침해하여 헌법에 위반된다.","ox":"X","m":"⑤","c":"A","tp":"헌법상 자기결정권"},{"y":2019,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2019_25-04","t":"행복추구권에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"행복추구권에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["행복추구권은 국민이 행복을 추구하기 위한 활동을 국가권력의 간섭없이 자유롭게 할 수 있는 자유권으로서, 국민이 행복을 추구하기 위하여 필요한 급부를 국가에게 적극적으로 요구할 수 있는 것을 내용으로 하는 권리이다.","기부행위자는 자신의 재산을 사회적 약자나 소외 계층을 위하여 출연함으로써 자기가 속한 사회에 공헌하였다는 행복감과 만족감을 실현할 수 있으므로, 기부행위는 행복추구권과 그로부터 파생되는 일반적 행동자유권에 의해 보호된다.","일반적 행동자유권의 보호영역에는 개인의 생활방식과 취미에 관한 사항도 포함되며, 위험한 스포츠를 즐길 권리와 같은 위험한 생활방식으로 살아갈 권리도 포함된다.","게임물 사업자에게 게임물 이용자의 본인인증 수단을 마련하도록 강제하는 법률조항은 게임을 이용하려는 사람들의 일반적 행동자유권을 제한하나 이를 통해 달성하려는 게임 과몰입 및 중독 방지라는 공익이 매우 중대하므로 일반적 행동자유권을 침해하지는 아니한다.","가족에 대한 수형자의 접견교통권은 비록 헌법에 열거되지는 아니하였지만 행복추구권에 포함되는 기본권의 하나인 일반적 행동자유권으로부터 나온다. 22-2"],"a":1}},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-1","t":"주민등록번호가 부여된 이후 주민등록번호 변경을 허용하게 되면 범죄은폐, 탈세, 채무면탈 또는 신분세탁 등 불순한 용도로 이를 악용하는 경우가 발생할 수 있으므로 주민등록번호 변경을 허용하지 않은 주민등록법이 개인정보자기결정권을 침해한 것으로 볼 수 없다.","ox":"X","m":"①","c":"A","tp":"기본권"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-2","t":"인터넷언론사의 공개된 게시판·대화방에서 스스로의 의사에 의하여 정당·후보자에 대한 지지·반대의 글을 게시하는 행위는 양심의 자유나 사생활 비밀의 자유에 의하여 보호되는 영역이라고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"기본권"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-3","t":"방송의 자유는 주관적 권리로서의 성격과 함께 자유로운 의견형성이나 여론형성을 위해 필수적인 기능을 행하는 객관적 규범질서로서 제도적 보장의 성격을 함께 가진다.","ox":"O","m":"③","c":"A","tp":"기본권"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-4","t":"군대 내에서 군종장교가 성직자의 신분에서 종교활동을 수행함에 있어 소속종단의 종교를 선전하거나 다른 종교를 비판하였다고 할지라도 그것만으로 종교적 중립을 준수할 의무를 위반하였다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"기본권"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-5","t":"헌법 제23조의 재산권은 자기 노력의 대가나 자본의 투자 등 특별한 희생을 통하여 얻은 공법상의 권리도 포함한다.","ox":"O","m":"⑤","c":"A","tp":"기본권"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-1","t":"부모가 자녀의 이름을 지어주는 것은 자녀의 양육과 가족생활을 위하여 필수적인 것이고, 가족생활의 핵심적 요소라 할 수 있으므로, ‘부모가 자녀의 이름을 지을 자유’는 혼인과 가족생활을 보장하는 헌법 제36조 제1항과 행복추구권을 보장하는 헌법 제10조에 의하여 보호받는다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-2","t":"초등학교 정규교과에서 영어를 배제하거나 영어교육 시수를 제한하는 것은 학생들의 인격의 자유로운 발현권을 제한하나, 이는 균형적인 교육을 통해 초등학생의 전인적 성장을 도모하고 영어과목에 대한 지나친 사교육의 폐단을 막기 위한 것으로 초등학생들의 인격의 자유로운 발현권을 침해하지 않는다.","ox":"O","m":"②","c":"A","tp":"헌법 제10조"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-3","t":"거짓이나 그 밖의 부정한 수단으로 운전면허를 받은 경우 모든 범위의 운전면허를 필요적으로 취소하도록 규정하여 부정 취득하지 않은 운전면허까지 필요적으로 취소하도록 한 것은 운전면허 소유자의 일반적 행동의 자유를 침해한다.","ox":"O","m":"③","c":"A","tp":"헌법 제10조"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-4","t":"친일반민족행위반민규명위원회의 조사대상자 선정 및 친일반민족행위결정이 이루어지면 조사대상자의 사회적 평가에 영향을 미치므로 헌법 제10조에서 유래하는 일반적 인격권이 제한받는다고 할 수 있겠으나, 조사대상자가 사자(死者)인 경우 이들의 청구인능력은 인정되지 않으며, 이로 인하여 그 후손의 법적 지위에 아무런 영향을 미치지 않는 만큼 후손의 인격권이 제한된다고도 볼 수 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-5","t":"헌법 제10조는 개인의 인격권과 행복추구권을 보장하고 있고, 개인의 인격권과 행복추구권은 개인의 자기운명결정권을 전제로 하는데, 이 자기운명결정권에는 성행위 여부 및 그 상대방을 결정할 수 있는 성적자기결정권이 포함되어 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-1","t":"임신 32주 이전에 태아의 성별 고지를 금지하는 의료법 조항은 과잉금지원칙을 위반하여 헌법 제10조로부터 도출되는 일반적 인격권에서 나오는 부모가 태아의 성별 정보에 대한 접근을 방해받지 않을 권리를 침해한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-2","t":"누구든지 금융회사 등에 종사하는 자에게 타인의 금융거래의 내용에 관한 정보 또는 자료를 요구하는 것을 금지하고, 이를 위반 시 형사처벌하는 금융실명거래 및 비밀보장에 관한 법률 조항은 과잉금지원칙에 반하여 일반적 행동자유권을 침해하지 아니한다.","ox":"X","m":"②","c":"A","tp":"헌법 제10조"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-3","t":"유족은 일정 기간 내에 매장·화장·봉안된 가족 또는 친지의 묘지에서 망인에게 경배와 추모 등 적절한 예우를 취하거나 시체·유골 등을 인수하여 분묘 등을 가꾸고 봉제사를 하고자 하는 권리를 보유하고, 이는 헌법 제10조의 행복추구권에 의하여 보장된다. 이러한 기본권이 실질적으로 보장되기 위해서는 국가권력으로부터 개인의 자유영역을 보호하는 것이 필요할 뿐 아니라 기본권 행사의 실질적인 조건을 형성하고 유지하는 국가의 적극적인 활동을 필요로 한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-4","t":"헌법 제10조 제1문이 보호하는 인간의 존엄성으로부터 개인의 일반적 인격권이 보장된다. 일반적 인격권은 인간의 존엄성과 밀접한 연관관계를 보이는 자유로운 인격발현의 기본조건을 포괄적으로 보호하는데, 개인의 자기결정권은 일반적 인격권에서 파생된다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-5","t":"이미 의식의 회복가능성을 상실하여 더 이상 인격체로서의 활동을 기대할 수 없고 자연적으로는 이미 죽음의 과정이 시작되었다고 볼 수 있는 회복불가능한 사망의 단계에 이른 후에는, 의학적으로 무의미한 신체 침해 행위에 해당하는 연명치료를 환자에게 강요하는 것이 오히려 인간의 존엄과 가치를 해하게 되므로, 이와 같은 예외적인 상황에서 죽음을 맞이하려는 환자의 의사결정을 존중하여 환자의 인간으로서의 존엄과 가치 및 행복추구권을 보호하는 것이 사회상규에 부합되고 헌법정신에도 어긋나지 아니한다.","ox":"O","m":"⑤","c":"A","tp":"헌법 제10조"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12-1","t":"흡연권은 사생활의 자유를 실질적 핵으로 하는 것이고, 혐연권은 사생활의 자유뿐만 아니라 생명권에까지 연결되는 것이므로 혐연권이 흡연권보다 상위의 기본권이다.","ox":"O","m":"①","c":"A","tp":"기본권의 효력"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12-2","t":"근로자의 단결하지 아니할 자유와 노동조합의 적극적 단결권이 충돌하는 경우 노동조합의 적극적 단결권이 근로자의 단결하지 아니할 자유보다 중시된다.","ox":"O","m":"②","c":"A","tp":"기본권의 효력"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12-3","t":"교사의 수업권과 학생의 수학권이 충돌하는 경우 두 기본권 모두 효력을 나타내는 규범조화적 해석에 따라 기본권 충돌은 해결되어야 한다.","ox":"X","m":"③","c":"A","tp":"기본권의 효력"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12-4","t":"기본권 제한에 관한 법률유보원칙은 기본권 제한에 법률의 근거를 요청하나, 기본권 제한의 형식이 반드시 형식적 의미의 법률일 필요는 없다.","ox":"O","m":"④","c":"A","tp":"기본권의 효력"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12-5","t":"하나의 규제로 인해 여러 기본권이 동시에 제약을 받는 기본권경합의 경우에는, 기본권 침해를 주장하는 제청신청인과 제청법원의 의도 및 기본권을 제한하는 입법자의 객관적 동기 등을 참작하여 사안과 가장 밀접한 관계에 있고 또 침해의 정도가 큰 주된 기본권을 중심으로 해서 그 제한의 한계를 따져 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"기본권의 효력"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-1","t":"불법체류 중인 외국인의 경우에도 원칙적으로 기본권의 주체가 된다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-2","t":"의료인의 면허된 의료행위 이외의 의료행위를 금지하고 처벌하는 의료법 규정에 대하여 외국인의 직업의 자유 및 평등권에 관한 기본권 주체성은 인정되지 않는다.","ox":"O","m":"②","c":"A","tp":"기본권의 주체"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-3","t":"국회의 일부조직인 국회노동위원회는 기본권의 주체가 될 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-4","t":"직장의료보험조합은 공법인으로서 기본권의 주체가 될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-5","t":"국가균형발전특별법에 의한 도지사의 혁신도시 입지선정과 관련하여 그 입지선정에서 제외된 지방자치단체로서는 입지선정 기준이 합리성과 타당성을 결여하였다고 다투는 등 평등권의 주체가 될 수 있다.","ox":"X","m":"⑤","c":"A","tp":"기본권의 주체"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-1","t":"태어난 즉시 ‘출생등록될 권리’는 헌법에 명시되지 아니한 독자적 기본권으로서, 자유로운 인격실현을 보장하는 자유권적 성격과 아동의 건강한 성장과 발달을 보장하는 사회적 기본권의 성격을 함께 지닌다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-2","t":"혼인 중인 여자와 남편 아닌 남자 사이에서 출생한 자녀의 경우에 혼인 외 출생자의 신고의무를 모에게만 부과하고, 남편 아닌 남자인 생부에게 자신의 혼인 외 자녀에 대해서 출생신고를 할 수 있도록 규정하지 아니한 것은 생부의 평등권을 침해한다.","ox":"X","m":"②","c":"A","tp":"출생등록"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-3","t":"‘혼인 중 여자와 남편 아닌 남자 사이에서 출생한 자녀에 대한 생부의 출생신고’를 허용하도록 규정하지 아니한 가족관계의 등록 등에 관한 법률 조항은 혼인 외 출생자의 태어난 즉시 ‘출생등록될 권리’를 침해한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-4","t":"태어난 즉시 ‘출생등록될 권리’는 입법자가 출생등록제도를 통하여 형성하고 구체화하여야 할 권리이다. 입법자는 출생등록제도를 형성함에 있어 단지 출생등록의 이론적 가능성을 허용하는 것에 그쳐서는 아니 되며, 실효적으로 출생등록될 권리가 보장되도록 하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-5","t":"평등권은 입법자에게 본질적으로 같은 것을 자의적으로 다르게, 본질적으로 다른 것을 자의적으로 같게 취급하는 것을 금하고 있고 본질적으로 동일한가의 판단은 일반적으로 당해 법률조항의 의미와 목적에 달려 있으므로, 당해 법률조항의 의미와 목적에 비추어 차별취급을 정당화할 수 있을 정도의 차이가 없음에도 차별한다면, 입법자는 이로써 평등권을 침해하게 된다.","ox":"O","m":"⑤","c":"A","tp":"출생등록"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-1","t":"강도상해죄 또는 강도치상죄의 법정형의 하한을 징역 7년으로 정하고 있는 형법 규정은 법관이 작량감경을 하더라도 별도로 법률상 감경사유가 없는 한 집행유예를 선고할 수 없게 되어 범행의 개별성에 맞추어 그 책임에 상응하는 형벌을 선고할 수 없는 결과가 발생하는바, 책임과 형벌 간의 비례원칙에 위반된다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-2","t":"야간주거침입절도죄의 미수범이 준강제추행죄를 범한 경우 무기징역 또는 7년 이상의 징역에 처하도록 한 성폭력범죄의 처벌 등에 관한 특례법 규정은 지나치게 높은 형벌을 규정하기 때문에, 법관은 범행별로 책임에 상응하는 형벌을 선고할 수 없으므로, 책임과 형벌 사이의 비례원칙에 위반된다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-3","t":"보안관찰처분대상자가 교도소 등에서 출소한 후 기존에 신고한 거주예정지 등 정보에 변동이 생길 때마다 7일 이내에 이를 신고하도록 하고 이를 위반할 경우 처벌하도록 정한 보안관찰법 규정은 과잉금지원칙을 위반하여 사생활의 비밀과 자유 및 개인정보자기결정권을 침해하지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-4","t":"대형트롤어업의 허가를 할 때 동경 128도 이동수역에서 조업하여서는 아니 된다는 조건을 붙이도록 한 구 어업의 허가 및 신고 등에 관한 규칙의 규정은 과잉금지원칙에 위반하여 직업수행의 자유를 침해한다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-5","t":"상속개시 후 인지 또는 재판확정에 의하여 공동상속인이 된 자가 다른 공동상속인에 대해 그 상속분에 상당한 가액의 지급에 관한 청구권(상속분가액지급청구권)을 행사하는 경우에도 상속회복청구권에 관한 10년의 제척기간을 적용하도록 한 민법의 규정은 입법형성의 한계를 일탈하여 재산권과 재판청구권을 침해한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-1","t":"상하의 위계질서가 있는 기본권끼리 충돌하는 경우에는 상위기본권우선의 원칙에 따라 하위기본권이 제한될 수 있으므로, 흡연권은 혐연권을 침해하지 않는 한에서 인정되어야 한다.","ox":"O","m":"①","c":"A","tp":"기본권의 충돌"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-2","t":"노동조합의 적극적 단결권은 근로자 개인의 단결하지 않을 자유보다 중시된다고 할 것이어서 노동조합에 적극적 단결권(조직강제권)을 부여한다고 하여 이를 두고 곧바로 근로자의 단결하지 아니할 자유의 본질적인 내용을 침해하는 것으로 단정할 수는 없다.","ox":"O","m":"②","c":"A","tp":"기본권의 충돌"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-3","t":"학생이 가지는 소극적 종교행위의 자유 및 소극적 신앙고백의 자유는 부작위에 의하여 자신의 종교적 신념을 외부로 표현하고 실현하는 기본권으로서, 학교법인이 가지는 종교교육의 자유보다 상위기본권에 해당한다.","ox":"X","m":"③","c":"A","tp":"기본권의 충돌"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-4","t":"학교교육에 있어서 교원의 가르치는 권리를 수업권이라고 한다면, 이것은 교원의 지위에서 생기는 학생에 대한 일차적인 교육상의 직무권한이지만 어디까지나 학생의 학습권 실현을 위하여 인정되는 것이므로, 학생의 학습권은 교원의 수업권에 대하여 우월한 지위에 있다.","ox":"O","m":"④","c":"A","tp":"기본권의 충돌"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-5","t":"인격권으로서의 개인의 명예의 보호와 표현의 자유의 보장이라는 두 법익이 충돌하였을 때 그 조정을 어떻게 할 것인지는 구체적인 경우에 사회적인 여러 가지 이익을 비교하여 표현의 자유로 얻어지는 이익, 가치와 인격권의 보호에 의하여 달성되는 가치를 형량하여 그 규제의 폭과 방법을 정하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"기본권의 충돌"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-1","t":"헌법 제39조 제1항에 규정된 국방의 의무는 외부 적대세력의 직·간접적인 침략행위로부터 국가의 독립을 유지하고 영토를 보전하기 위한 의무를 말한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-2","t":"헌법에서 국방의 의무를 국민에게 부과하고 있으므로, 병역법에 따라 군복무를 하는 것은 국민이 마땅히 하여야 할 이른바 신성한 의무를 다 하는 것일 뿐, 국가나 공익목적을 위하여 개인이 특별한 희생을 하는 것이라고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-3","t":"군형법 제1조 제3항 제3호에서 소집되어 실역에 복무중인 예비역에 대하여 현역군인에 준하여 군형법을 적용토록 하였다 하더라도 이는 국방의 의무(헌법 제39조 제1항)에 근거한 것으로서 그 병역의무의 이행을 실효성 있게 확보하기 위한 것이라 할 것이므로 헌법에 위반된다고 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-4","t":"헌법 제39조 제2항이 “누구든지 병역의무의 이행으로 인하여 불이익한 처우를 받지 아니한다.”라고 규정하고 있고, 향토예비군설치법 제11조는 “예비군부대의 지휘관 및 동원된 예비군대원에 대하여는 대통령령이 정하는 바에 의하여 급식 기타 실비변상을 할 수 있다.”고 규정하여 병력동원을 위한 훈련에 소집된 예비군에게는 급식 및 실비변상이 이루어지고 있으므로, 교육훈련을 위하여 소집된 예비군에게도 그에 준하는 보상이 이루어져야 한다.","ox":"X","m":"④","c":"A","tp":"국방의 의무"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-5","t":"병역의무 그 자체를 이행하느라 받는 불이익은 병역의무의 이행으로 인한 불이익한 처우의 금지와는 무관하다.","ox":"O","m":"⑤","c":"A","tp":"국방의 의무"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14-1","t":"장애인의 접근권은 헌법상 인간의 존엄과 가치 및 행복을 추구할 권리를 장애인에게도 동등하게 보장하고, 사회적 약자인 장애인이 인간다운 생활을 하는 데 필수적인 전제가 되는 권리로서, 비록 헌법에 명시되지는 않았으나 헌법 규정들로부터 도출되는 기본권으로서의 지위를 가진다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14-2","t":"장애인의 접근권은 비장애인과 동등한 수준의 접근을 보장할 수 있는 특정 시설과 설비를 설치할 것을 국가나 사인에게 적극적으로 요구할 수 있는 권리를 포함하므로, 그와 같은 권리의 내용을 구체화하는 법률은 필요하지 아니하다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14-3","t":"국가는 제한된 재정 능력과 사회·경제적 발전 수준 등을 고려하여 장애인에 대한 접근권이 적절히 보장되도록 필요한 조치를 취할 의무가 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14-4","t":"국회가 법률로 행정청에 특정한 사항을 위임했음에도 불구하고 행정청이 정당한 이유 없이 이를 이행하지 않는다면 권력분립의 원칙과 법치국가 또는 법치행정의 원칙에 위배되는 것으로서 위법·위헌에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14-5","t":"행정청이 법률에서 대통령령으로 정하도록 위임받은 사항을 전혀 입법하지 않은 경우는 물론 그 법률이 위임한 사항을 불충분하게 규정함으로써 법률이 위임한 행정입법의무를 제대로 이행하지 않은 경우에도 위법·위헌에 해당한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-1","t":"헌법재판소는 등록된 출판사가 음란 또는 저속한 간행물을 출판하여 공중도덕이나 사회윤리를 침해하였다고 인정되는 경우 등록청이 그 출판사의 등록을 취소할 수 있도록 하는 법률의 규정에 대하여 언론·출판의 자유를 중심으로 위헌 여부를 판단하였다.","ox":"O","m":"①","c":"A","tp":"기본권의 경합"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-2","t":"헌법재판소는 의료인이 아닌 자의 문신시술업을 금지·처벌하는 법률의 규정에 대하여 예술의 자유를 중심으로 위헌 여부를 판단하였다.","ox":"X","m":"②","c":"A","tp":"기본권의 경합"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-3","t":"헌법재판소는 법무법인 구성원의 지분을 압류한 채권자가 영업년도말에 그 구성원을 퇴사시킬 수 있도록 한 법률의 규정에 대하여 재산권을 중심으로 위헌 여부를 판단하였다.","ox":"O","m":"③","c":"A","tp":"기본권의 경합"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-4","t":"헌법재판소는 2019학년도 대학 보건·의료계열 학생정원 조정계획 중 2019학년도 여자대학 약학대학의 정원을 동결한 부분에 대하여 직업선택의 자유를 중심으로 위헌 여부를 판단하였다.","ox":"O","m":"④","c":"A","tp":"기본권의 경합"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-5","t":"헌법재판소는 변호사에 대한 징계결정정보를 인터넷 홈페이지에 공개하도록 한 법령의 규정에 대하여 일반적 인격권을 중심으로 위헌 여부를 판단하였다.","ox":"O","m":"⑤","c":"A","tp":"기본권의 경합"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-1","t":"과잉금지의 원칙이라는 것은 국가가 국민의 기본권을 제한하는 내용의 입법활동을 함에 있어서, 준수하여야 할 기본원칙 내지 입법활동의 한계를 의미하는 것으로서 국민의 기본권을 제한하려는 입법의 목적이 헌법 및 법률의 체제상 그 정당성이 인정되어야 하고(목적의 정당성), 그 목적의 달성을 위하여 그 방법이 효과적이고 적절하여야 하며(방법의 적절성), 입법권자가 선택한 기본권 제한의 조치가 입법목적달성을 위하여 설사 적절하다 할지라도 보다 완화된 형태나 방법을 모색함으로써 기본권의 제한은 필요한 최소한도에 그치도록 하여야 하며(피해의 최소성), 그 입법에 의하여 보호하려는 공익과 침해되는 사익을 비교형량할 때 보호되는 공익이 더 커야 한다(법익의 균형성)는 헌법상의 원칙이다.","ox":"O","m":"①","c":"A","tp":"과잉금지원칙"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-2","t":"재산권에 대한 제한의 허용정도는 재산권 객체의 사회적 기능, 즉 재산권의 행사가 기본권의 주체와 사회전반에 대하여 가지는 의미에 달려 있다. 재산권의 이용과 처분이 소유자의 개인적 영역에 머무르지 아니하고 국민 일반의 자유행사에 큰 영향을 미치거나 국민 일반이 자신의 자유를 행사하기 위하여 문제되는 재산권에 의존하는 경우에는 입법자가 공동체의 이익을 위하여 개인의 재산권을 제한하는 규율권한은 더욱 넓어진다. 이러한 입법재량을 고려하면, 재산권의 사회적 기속성에 기한 제한에는 비례원칙을 적용한 심사가 아닌 완화된 기준에 따른 심사가 이루어져야 한다.","ox":"X","m":"②","c":"A","tp":"과잉금지원칙"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-3","t":"입법자가 임의적 규정으로도 법의 목적을 실현할 수 있는 경우에 구체적 사안의 개별성과 특수성을 고려할 수 있는 가능성을 일체 배제하는 필요적 규정을 둔다면 이는 비례의 원칙의 한 요소인 ‘최소침해성의 원칙’에 위배된다는 점에서 부정한 방법으로 건설업 등록을 한 경우에 대하여 행정청에 의한 재량행사의 여지없이 필요적으로 등록을 말소하도록 규정하는 법률조항의 경우 최소침해성의 원칙에 부합하는지의 문제가 제기된다.","ox":"O","m":"③","c":"A","tp":"과잉금지원칙"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-4","t":"다른 사람의 자동차 등을 훔친 경우에 운전면허를 필요적으로 취소하도록 규정하고 있는 구 도로교통법(2011. 6. 8. 법률 제10790호로 개정되고, 2016. 1. 27. 법률 제13829호로 개정되기 전의 것) 제93조 제1항 제12호 중 ‘다른 사람의 자동차 등을 훔친 경우’ 부분은 구체적 사안의 개별성과 특수성을 고려할 수 있는 여지를 일절 배제하고 있어 침해의 최소성 원칙에 위반된다.","ox":"O","m":"④","c":"A","tp":"과잉금지원칙"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-5","t":"양심적 병역거부자의 수는 병역자원의 감소를 논할 정도가 아니고, 이들을 처벌한다고 하더라도 교도소에 수감할 수 있을 뿐 병역자원으로 활용할 수는 없으므로, 대체복무제를 도입하더라도 우리나라의 국방력에 의미 있는 수준의 영향을 미친다고 보기는 어렵다. 국가가 관리하는 객관적이고 공정한 사전심사절차와 엄격한 사후관리절차를 갖추고, 현역복무와 대체복무 사이에 복무의 난이도나 기간과 관련하여 형평성을 확보해 현역복무를 회피할 요인을 제거한다면, 심사의 곤란성과 양심을 빙자한 병역기피자의 증가 문제를 해결할 수 있으므로, 대체복무제를 도입하면서도 병역의무의 형평을 유지하는 것은 충분히 가능하다. 따라서 대체복무제라는 대안이 있음에도 불구하고 군사훈련을 수반하는 병역의무만을 규정한 병역종류조항은, 침해의 최소성 원칙에 어긋난다.","ox":"O","m":"⑤","c":"A","tp":"과잉금지원칙"}],"4":[{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20","t":"직업선택의 자유에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"직업선택의 자유에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","d":"가.게임 결과물의 환전업은 게임이용자로부터 게임 결과물을 매수하여 다른 게임이용자에게 이윤을 붙여 되파는 영업으로서 헌법 제15조가 보장하는 직업에 해당한다.\n나.일반학원의 강사라는 직업의 개시를 위한 주관적 전제조건으로서 ‘대학 졸업 이상의 학력 소지’라는 자격기준을 갖추도록 요구함으로써 직업선택의 자유를 제한하고 있으나 일률적으로 자격기준을 설정하여 통제하는 방식만큼의 효과를 거둘 만한 다른 제도나 절차를 쉽게 찾아보기 어려우므로 최소침해의 원칙은 문제되지 않는다.\n다.입법자는 일정한 전문분야에 관한 자격제도를 마련함에 있어서 그 제도를 마련한 목적을 고려하여 정책적인 판단에 따라 제도의 내용을 구성할 수 있으므로 자격요건에 관한 법률조항은 합리적인 근거 없이 현저히 자의적인 경우에만 헌법에 위반된다.\n라.‘자동차운전전문학원을 졸업하고 운전면허를 받은 사람 중 교통사고를 일으킨 비율이 대통령령이 정하는 비율을 초과하는 때’에는 학원의 등록을 취소하거나 1년 이내의 운영정지를 명할 수 있도록 하는 것은 운전전문학원이 조성하는 사회적 위험을 관리하기 위한 것이므로 운전전문학원 운영자의 직업의 자유를 침해한다고 볼 수 없다.\n마.건설산업기본법에서 건설업자가 명의대여를 한 경우 건설업의 등록을 필요적으로 말소하도록 규정하는 것은 합헌이지만, 임원이 금고 이상의 형을 선고받은 경우 법인의 건설업 등록을 필요적으로 말소하도록 규정한 것은 위헌이다.","o":["1개","2개","3개","4개","5개"],"a":1}},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04-1","t":"우리 헌법은 경제주체의 경제상의 자유와 창의를 존중함을 기본으로 하므로 국민경제상 긴절한 필요가 있어 법률로 규정하더라도 사영기업을 국유 또는 공유로 이전하는 것은 인정되지 않는다.","ox":"X","m":"①","c":"A","tp":"헌법상 경제질서"},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04-2","t":"자경농지의 양도소득세 면제대상자를 ‘농지소재지에 거주하는 거주자’로 제한하는 것은 외지인의 농지투기를 방지하고 조세부담을 덜어주어 농업과 농촌을 활성화하기 위한 것이므로 경자유전의 원칙에 위배되지 않는다.","ox":"O","m":"②","c":"A","tp":"헌법상 경제질서"},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04-3","t":"국민연금제도는 상호부조의 원리에 입각한 사회연대성에 기초하여 소득재분배의 기능을 함으로써 사회적 시장경제질서에 부합하는 제도이므로, 국민연금에 가입을 강제하는 법률조항은 헌법의 시장경제질서에 위배되지 않는다.","ox":"O","m":"③","c":"A","tp":"헌법상 경제질서"},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04-4","t":"헌법 제119조 제2항에 규정된 ‘경제주체간의 조화를 통한 경제민주화’의 이념은 경제영역에서 정의로운 사회질서를 형성하기 위하여 추구할 수 있는 국가목표로서 개인의 기본권을 제한하는 국가행위를 정당화하는 헌법규범이다.","ox":"O","m":"④","c":"A","tp":"헌법상 경제질서"},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04-5","t":"수력(水力)은 법률이 정하는 바에 의하여 일정한 기간 그 이용을 특허할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"헌법상 경제질서"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-1","t":"약사 또는 한약사가 아니면 약국을 개설할 수 없다고 규정한 약사법은 법인을 구성하여 약국을 개설·운영하려고 하는 약사들 및 이들 약사들로 구성된 법인의 직업선택의 자유를 침해한 것이다.","ox":"O","m":"①","c":"A","tp":"직업의 자유"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-2","t":"성인대상 성범죄로 형을 선고받아 확정된 자에게 그 형의 집행을 종료한 날부터 10년 동안 의료기관을 개설하거나 의료기관에 취업할 수 없도록 한 아동·청소년의 성보호에 관한 법률은 직업선택의 자유를 침해한다.","ox":"O","m":"②","c":"A","tp":"직업의 자유"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-3","t":"보건복지부장관이 치과전문의자격시험제도를 실시할 수 있도록 시행규칙을 마련하지 아니한 행정입법부작위는 전공의수련과정을 마친 청구인들의 직업의 자유를 침해한 것이다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-4","t":"운전면허를 받은 사람이 자동차 등을 이용하여 살인 또는 강간 등의 범죄행위를 한 때 필요적으로 운전면허를 취소하도록 규정한 도로교통법은 직업의 자유를 침해한 것이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-5","t":"유치원 주변 학교환경위생 정화구역에서 성관련 청소년유해물건을 제작·생산·유통하는 청소년유해업소를 예외 없이 금지하는 학교보건법은 직업의 자유를 침해한 것이다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-1","t":"재산권에 대한 제약이 비례원칙에 합치하는 것이라면 그 제약은 재산권자가 수인하여야 하는 사회적 제약의 범위 내에 있는 것이고, 반대로 재산권에 대한 제약이 비례원칙에 반하여 과잉된 것이라면 그 제약은 재산권자가 수인하여야 하는 사회적 제약의 한계를 넘는 것이다.","ox":"O","m":"①","c":"A","tp":"재산권 제한"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-2","t":"개발제한구역지정 당시의 상태대로 토지를 사용·수익·처분할 수 있는 이상, 자신의 토지를 장래에 건축이나 개발목적으로 사용할 수 있으리라는 기대가능성이나 신뢰 및 이에 따른 지가상승의 기회는 원칙적으로 재산권의 보호범위에 속하지 않는다.","ox":"O","m":"②","c":"A","tp":"재산권 제한"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-3","t":"개발제한구역의 지정으로 말미암아 예외적으로 토지를 종래의 목적으로도 사용할 수 없거나 또는 법률상으로 허용된 토지이용의 방법이 없기 때문에 실질적으로 토지의 사용·수익권이 폐지된 경우에는 토지소유자가 수인해야 할 사회적 제약의 정도를 넘는 것이라고 보아야 한다.","ox":"O","m":"③","c":"A","tp":"재산권 제한"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-4","t":"도시계획시설의 지정으로 말미암아 당해 토지의 이용가능성이 배제되거나 또는 토지소유자가 토지를 종래 허용된 용도대로도 사용할 수 없기 때문에 이로 말미암아 현저한 재산적 손실이 발생하는 경우에는, 원칙적으로 사회적 제약의 범위를 넘는 수용적 효과를 인정하여 국가나 지방자치단체는 이에 대한 보상을 해야 한다.","ox":"O","m":"④","c":"A","tp":"재산권 제한"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-5","t":"토지소유자가 수인해야 할 사회적 제약의 정도를 넘는 경우에도 아무런 보상없이 재산권의 과도한 제한을 감수해야 하는 의무를 부과하는 것은 위헌이다. 이러한 경우 입법자는 비례의 원칙을 충족시키고 이로써 법률의 위헌성을 제거하기 위하여 예외적으로 발생한 특별한 부담에 대하여 보상규정을 두어야 하는데, 여기에서 보상이란 헌법상 정당보상원칙에 따라 금전보상만을 의미한다.","ox":"X","m":"⑤","c":"A","tp":"재산권 제한"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-1","t":"변호사가 법률사건 수임에 관하여 알선의 대가로 금품을 제공하는 행위를 금지하고 처벌하는 것은 변호사의 직업수행의 자유를 제한하는 것이다.","ox":"O","m":"①","c":"A","tp":"변호사의 직업의 자유"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-2","t":"변호사시험에 응시하여 합격하여야만 변호사의 자격을 취득할 수 있으므로, 금고 이상의 형의 집행유예를 선고받고 그 유예기간이 지난 후 2년이 지나지 아니한 자의 변호사시험 응시자격을 제한하고 있는 응시 결격조항은 변호사 자격을 취득하고자 하는 청구인의 직업선택의 자유를 제한하는 것이다.","ox":"O","m":"②","c":"A","tp":"변호사의 직업의 자유"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-3","t":"변호사들로 하여금 소속지방변호사회에 수임사건의 건수 및 수임액을 보고하도록 하는 것은 변호사의 직업수행의 자유를 제한하는 것이다.","ox":"O","m":"③","c":"A","tp":"변호사의 직업의 자유"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-4","t":"변호사 자격을 취득하기 위해서는 변호사시험에 합격하여야 하는데, 법학전문대학원 졸업 후 5년 내에 5회만 변호사시험에 응시할 수 있도록 하는 응시기회제한조항은 변호사 자격을 취득하고자 하는 청구인의 직업선택의 자유를 제한하는 것이다.","ox":"O","m":"④","c":"A","tp":"변호사의 직업의 자유"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-5","t":"변호사시험에 응시한 자의 시험성적을 응시자 본인에게도 공개하지 않는 것은 응시자의 직업선택의 자유를 제한하는 것이다.","ox":"X","m":"⑤","c":"A","tp":"변호사의 직업의 자유"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-1","t":"직업의 자유는 개인의 주관적 공권임과 동시에 사회적 시장경제질서라고 하는 객관적 법질서의 구성요소이다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-2","t":"직업의 자유에 대한 제한이라고 하더라도 그 제한사유가 직업의 자유의 내용을 이루는 직업수행의 자유와 직업선택의 자유 중 어느 쪽에 작용하느냐에 따라 그 제한에 대하여 요구되는 정당화의 수준이 달라진다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-3","t":"직업의 자유에 대한 법적 규율이 직업수행에 대한 규율로부터 직업선택에 대한 규율로 가면 갈수록 자유제약의 정도가 상대적으로 강해져 입법재량의 폭이 좁아지게 되고, 직업선택의 자유에 대한 제한이 문제되는 경우에 있어서도 일정한 주관적 사유를 직업의 개시 또는 계속수행의 전제조건으로 삼아 직업선택의 자유를 제한하는 경우보다는 직업의 선택을 객관적 허가조건에 걸리게 하는 방법으로 제한하는 경우에 침해의 심각성이 더 크므로 보다 엄밀한 정당화가 요구된다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-4","t":"어떠한 직업분야에 관한 자격제도를 만들면서 그 자격요건을 어떻게 설정할 것인가에 관하여는 국가에게 폭넓은 입법재량권이 부여되어 있는 것이므로 다른 방법으로 직업선택의 자유를 제한하는 경우에 비하여 보다 유연하고 탄력적인 심사가 필요하다 할 것이다.","ox":"O","m":"④","c":"A","tp":"직업의 자유"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-5","t":"헌법 제15조의 직업의 자유 또는 헌법 제32조의 근로의 권리, 사회국가원리 등에 근거하여 근로자에게 국가에 대한 직접적인 직장존속보장청구권이 인정된다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-1","t":"어떤 공과금이 조세인지 아니면 부담금인지는 단순히 법률에서 그것을 무엇으로 성격 규정하고 있느냐를 기준으로 할 것이 아니라, 그 실질적인 내용을 결정적인 기준으로 삼아야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-2","t":"부담금은 그 부과목적과 기능에 따라 ㈎ 순수하게 재정조달의 목적만 가지는 재정조달목적 부담금과 ㈏ 재정조달 목적뿐만 아니라 부담금의 부과 자체로써 국민의 행위를 특정한 방향으로 유도하거나 특정한 공법적 의무의 이행 또는 공공출연으로부터의 특별한 이익과 관련된 집단 간의 형평성 문제를 조정하여 특정한 사회·경제정책을 실현하기 위한 정책실현목적 부담금으로 구분될 수 있다. 전자의 경우에는 공적 과제가 부담금 수입의 지출 단계에서 비로소 실현되나, 후자의 경우에는 공적 과제의 전부 혹은 일부가 부담금의 부과 단계에서 이미 실현된다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-3","t":"재정조달목적 부담금은 특정한 반대급부 없이 부과될 수 있다는 점에서 조세와 매우 유사하므로 헌법 제38조가 정한 조세법률주의, 헌법 제11조 제1항이 정한 법 앞의 평등원칙에서 파생되는 공과금 부담의 형평성, 헌법 제54조 제1항이 정한 국회의 예산심의·확정권에 의한 재정감독권과의 관계에서 오는 한계를 고려하여, 그 부과가 헌법적으로 정당화되기 위하여는 ㈎ 조세에 대한 관계에서 예외적으로만 인정되어야 하며 국가의 일반적 과제를 수행하는 데에 부담금 형식을 남용하여서는 아니 되고, ㈏ 부담금 납부의무자는 일반 국민에 비해 부담금을 통해 추구하고자 하는 공적 과제에 대하여 특별히 밀접한 관련성을 가져야 하며, ㈐ 부담금이 장기적으로 유지되는 경우 그 징수의 타당성이나 적정성이 입법자에 의해 지속적으로 심사되어야 한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-4","t":"부담금은 국민의 재산권을 제한하는 성격을 가지고 있으므로 부담금을 부과함에 있어서도 평등원칙이나 비례성원칙과 같은 기본권제한입법의 한계는 준수되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-5","t":"부담금관리 기본법 제3조는 부담금은 별표에 규정된 법률에 따르지 아니하고는 설치할 수 없다고 규정하고 있으므로 개별 법률에 부담금 부과에 관한 근거규정이 존재하더라도 그 개별 법률의 근거규정이 부담금관리 기본법 별표에 포함되어 있지 않다면 그 개별 법률의 근거규정에 따른 부담금을 부과하는 것은 허용될 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-1","t":"시혜적 입법의 시혜대상에서 제외되었다는 이유만으로 재산권의 침해가 발생하는 것은 아니고 시혜대상에 포함될 경우 얻을 수 있었던 재산상 이익의 기대가 성취되지 않았다고 하여도 이와 같은 단순한 재산상 이익에 대한 기대는 헌법이 보호하는 재산권의 영역에 포함되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-2","t":"연금수급권의 내용은 사회·경제적 상황을 고려한 입법자의 정책적 판단에 의하여 변경될 수 있어 조기노령연금의 수급개시연령에 대한 신뢰는 보호가치가 크지 않으므로, 조기노령연금을 수급할 수 있는 연령이 59세에서 60세로 인상하는 법률은 재산권을 침해하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-3","t":"유류분 반환청구는 피상속인이 생전에 한 유효한 증여라도 그 효력을 잃게 하는 것이므로, 민법 제1117조에서 ‘반환하여야 할 증여를 한 사실을 안 때로부터 1년’이라는 단기소멸시효를 정한 것은 재산권을 침해하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-4","t":"헌법이 규정한 ‘정당한 보상’이란 손실보상의 원인이 되는 재산권의 침해가 기존의 법질서 안에서 개인의 재산권에 대한 개별적인 침해인 경우에는 그 손실 보상은 원칙적으로 피수용재산의 객관적인 재산가치를 완전하게 보상하는 것이어야 한다는 완전보상을 뜻하는 것이다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-5","t":"재산권의 객체가 갖는 객관적 가치란 그 물건의 성질에 정통한 사람들의 자유로운 거래에 의하여 도달할 수 있는 합리적인 매매가능가격 즉 시가에 의하여 산정되는 것이 보통이므로, 수용으로 인한 보상가액은 피수용토지의 수용시점 시가에 의하여야 하고, 공익사업의 시행으로 지가가 상승하여 발생하는 개발이익 역시 해당 토지의 객관적 가치에 포함되므로, 손실보상액에서 그와 같은 개발이익을 배제하는 것은 헌법이 정한 정당보상의 원리에 위배된다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-1","t":"직업의 자유에 의한 보호의 대상이 되는 '직업'은 '생활의 기본적 수요를 충족시키기 위한 계속적 소득활동'을 의미하며 그러한 내용의 활동인 한 그 종류나 성질을 묻지 아니하므로, 대학생이 방학기간을 이용하여 학비 등을 벌기 위하여 학원강사로서 일하는 행위도 직업의 자유의 보호영역에 속한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-2","t":"성인대상 성범죄로 형을 선고받아 확정된 자로 하여금 그 형의 집행을 종료한 날로부터 10년 동안 의료기관을 개설하거나 의료기관에 취업할 수 없도록 한 구 아동·청소년의 성보호에 관한 법률은 직업선택의 자유를 침해한다.","ox":"O","m":"②","c":"A","tp":"직업의 자유"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-3","t":"직업수행의 자유에 대한 제한은 인격발현에 대한 침해의 효과가 일반적으로 직업선택의 자유에 대한 제한에 비하여 작기 때문에, 그에 대한 제한은 보다 폭넓게 허용된다.","ox":"O","m":"③","c":"A","tp":"직업의 자유"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-4","t":"직업의 자유에는 해당 직업에 합당한 보수를 받을 권리도 포함되어 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-5","t":"자격제도를 시행함에 있어서 설정하는 자격요건에 대한 판단은 원칙적으로 입법자의 입법형성권의 영역에 있으므로, 그것이 입법재량의 범위를 일탈하여 현저히 불합리한 경우에 한하여 헌법에 위반된다고 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"직업의 자유"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-1","t":"공익사업을 위한 토지 등의 취득 및 보상에 관한 법률 제91조 제1항이 환매권의 발생기간을 ‘취득일로부터 10년 이내’로 제한한 것은 환매권의 구체적 행사를 위한 내용을 정한 것이라기보다는 환매권의 발생 여부 자체를 정하는 것이어서 사실상 원소유자의 환매권을 배제하는 결과를 초래할 수 있으므로, 침해의 최소성 및 법익의 균형성 등 기본권 제한입법의 한계를 준수하지 못하고 있어 헌법에 위반된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-2","t":"노동조합 및 노동관계조정법 제94조는 양벌규정으로서 “법인 또는 단체의 대표자, 법인·단체 또는 개인의 대리인·사용인 기타의 종업원이 그 법인·단체 또는 개인의 업무에 관하여 제88조 내지 제93조의 위반행위를 한 때에는 행위자를 벌하는 외에 그 법인·단체 또는 개인에 대하여도 각 해당 조의 벌금형을 과한다.”라고 규정하고 있는데, 위 규정 중 ‘법인의 대리인·사용인 기타의 종업원’ 관련 부분은 책임주의 원칙에 위배되지만, ‘법인의 대표자’ 관련 부분은 책임주의 원칙에 위배되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-3","t":"건강보험수급권은 가입자가 납부한 보험료에 대한 반대급부의 성격을 가지며, 보험사고로 초래되는 재산상 부담을 전보하여 주는 경제적 유용성을 가지므로, 헌법상 재산권의 보호범위에 속한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-4","t":"초·중등학교 교원에 대해서는 정당가입의 자유를 금지하면서 대학의 교원에게 이를 허용한다 하더라도, 이는 양자 간 직무의 본질과 내용, 근무 태양이 다른 점을 고려한 합리적인 차별이므로 평등원칙에 위배되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-5","t":"국가공무원법 제66조 제1항 본문은 “공무원은 노동운동이나 그 밖에 공무 외의 일을 위한 집단행위를 하여서는 아니 된다.”라고 규정하고 있는데, 위 규정 중 ‘그 밖에 공무 외의 일을 위한 집단행위’ 부분은 명확성 원칙에 위반될 뿐 아니라 공무에 속하지 아니하는 어떤 일을 위하여 공무원들이 하는 모든 집단적 행위를 금지함으로써 표현의 자유에 대한 과도한 제한에 해당하므로, 헌법에 위반된다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-1","t":"헌법재판소는 법무사보수기준제가 법무사라는 직업의 선택 그 자체를 제한하는 것이 아니라 직업행사의 자유를 제한하는 제도에 해당한다고 보아 그것이 직업의 자유를 침해하는지 여부를 심사하기 위한 기준으로 비례성원칙이 아닌 자의금지원칙을 적용하였다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-2","t":"출석주의를 완화하여 최초의 전자등기신청 전에 한 차례 사용자등록을 하도록 한 부동산등기규칙 조항은 무자격 등기 브로커에 의한 무차별적 등기를 가능하게 하여 법무사인 청구인들의 직업에 대한 신뢰가 훼손됨으로써 직업선택의 자유를 침해한다.","ox":"X","m":"②","c":"A","tp":"직업의 자유"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-3","t":"법무사 아닌 자가 등기신청대행 등의 법무행위를 업으로 하는 것을 금지하고 이를 위반하는 경우 형사처벌하는 법무사법 조항은 법무사 자격이 없는 일반 국민의 직업 선택의 자유를 과도하게 제한하여 헌법에 위반된다.","ox":"X","m":"③","c":"A","tp":"직업의 자유"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-4","t":"고소고발장을 법무사만이 그 작성사무를 업으로 할 수 있는 법원과 검찰청의 업무에 관련된 서류로 규정한 것은 일반행정사의 직업 선택의 자유 등의 기본권을 침해한다.","ox":"X","m":"④","c":"A","tp":"직업의 자유"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-5","t":"헌법재판소는 일정한 경력을 가진 공무원이 법무사시험을 보지 않고도 법무사 자격을 취득할 수 있도록 하는 경력공무원에 대한 자격부여제도를 규정하고 있던 법무사법 조항에 대하여 경력공무원이 아닌 일반인들도 법무사시험을 보아 합격하면 법무사가 될 수 있는 길을 열어 놓고 있고, 경력공무원에 대한 자격부여제도가 합리성을 갖고 있어서 법무사시험제도를 유명무실하게 하는 요소를 찾기 어렵다고 보아 법무사라는 직업을 선택하는 자유를 침해하지 않는다고 결정한 적이 있다.","ox":"O","m":"⑤","c":"A","tp":"직업의 자유"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-1","t":"관리처분계획인가의 고시가 있으면 별도의 영업손실보상 없이 재건축사업구역 내 임차권자의 사용·수익을 중지시키는 것은 임차권자의 재산권을 침해한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-2","t":"공무원연금법상 퇴직연금수급자가 지방의회의원으로 선출되어 받게 되는 보수가 기존의 연금에 미치지 못하는 경우에도 연금 전액의 지급을 정지하도록 한 규정은 그에 해당하는 지방의회의원의 재산권을 침해한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-3","t":"지역구국회의원선거 예비후보자가 정당의 공천심사에서 탈락하여 후보자등록을 하지 않은 경우를 지역구국회의원선거 예비후보자의 기탁금 반환 사유로 규정하지 않은 것은 예비후보자의 재산권을 침해한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-4","t":"보안거리에 저촉되는 화약류저장소에 대한 시설이전명령 때문에 화약류저장소를 이용한 영업을 하지 못하게 된다 하더라도 그로 인해 상실되는 영리획득의 기회를 헌법에 의해 보장되는 재산권으로 보기는 어렵다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-5","t":"공무원연금법상의 각종 급여는 기본적으로 모두 사회보장적 급여로서의 성격을 가짐과 동시에 공로보상 내지 후불임금으로서의 성격도 함께 가지며, 특히 공무원연금법상 퇴직연금수급권은 경제적 가치 있는 권리로서 헌법 제23조에 의하여 보장되는 재산권으로서의 성격을 가진다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-1","t":"법 규정이 직업의 자유를 직접 규율하고자 하는 것은 아니지만 간접적으로 직업의 행사를 저해하거나 불가능하게 하는 경우에도 직업의 자유에 대한 제한이 인정될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-2","t":"어린이통학버스를 운영함에 있어서 반드시 보호자를 동승하도록 하는 조항은 동승보호자의 추가 고용에 따른 비용 지출을 유발할 뿐 학원의 영업방식을 직접 제한하는 것은 아니므로 그로 인해 직업수행의 자유는 제한되지 아니한다.","ox":"X","m":"②","c":"A","tp":"직업의 자유"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-3","t":"헌법 제15조에서 보장하는 직업의 자유에는 기업의 설립과 경영의 자유를 의미하는 기업의 자유도 포함된다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-4","t":"최저임금의 적용을 위하여 주(週) 단위로 정해진 비교대상 임금을 시간에 대한 임금으로 환산할 때, 1주 동안의 소정근로시간 수와 법정 주휴시간 수를 합산한 시간 수로 해당 임금을 나누도록 하는 규정은 근로자를 고용하여 재화나 용역을 제공하는 사용자의 활동을 제한한다는 측면에서 직업의 자유를 제한한다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-5","t":"외국인근로자의 사업장 변경 사유를 제한하는 규정은, 그로 인해 외국인근로자가 일단 형성된 근로관계를 포기하고 직장을 이탈하는 데 있어 제한을 받게 되므로 직업선택의 자유 중 직장선택의 자유를 제한한다.","ox":"O","m":"⑤","c":"A","tp":"직업의 자유"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-1","t":"헌법이 규정한 ‘정당한 보상’이란 손실보상의 원인이 되는 재산권의 침해가 기존의 법질서 안에서 개인의 재산권에 대한 개별적인 침해인 경우에 원칙적으로 피수용재산의 객관적인 재산가치를 완전하게 보상하는 것을 의미하는 것이고, 개발이익은 그 성질상 완전보상의 범위에 포함되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-2","t":"헌법 제23조 제3항은 재산권 수용의 주체를 한정하지 않고 있으므로, 수용의 주체를 국가 등 공적 기관에 한정하여 해석할 이유가 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-3","t":"사회부조와 같이 국가의 일방적인 급부에 대한 권리라 하더라도 그것이 금전의 급부로서 주어지는 경우 원칙적으로 재산권의 보호대상에 포함된다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-4","t":"일반적으로 소급입법의 태양에는 이미 과거에 완성된 사실 또는 법률관계를 규율의 대상으로 하는 진정소급입법과 이미 과거에 시작되었으나 아직 완성되지 아니하고 진행과정에 있는 사실 또는 법률관계를 규율대상으로 하는 부진정소급입법이 있고, 헌법 제13조 제2항에 의하여 소급입법에 의한 재산권의 박탈이 금지되는 것은 진정소급입법이다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-5","t":"공용수용에 관하여 규정하고 있는 헌법 제23조 제3항의 ‘공공필요’의 의미에 비추어 볼 때, 행정기관이 개발촉진지구 지역개발사업으로 실시계획을 승인하고 이를 고시하기만 하면 고급골프장 사업과 같이 공익성이 낮은 사업에 대해서까지도 시행자인 민간개발자에게 수용권한을 부여하는 법률조항은 헌법 제23조 제3항에 위반된다.","ox":"O","m":"⑤","c":"A","tp":"재산권"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07-1","t":"개성공단 전면중단 조치가 고도의 정치적 결단을 요하는 문제이기는 하나, 조치 결과 개성공단 투자기업인에게 기본권 제한이 발생하였고, 국민의 기본권 제한과 직접 관련된 공권력의 행사는 고도의 정치적 고려가 필요한 행위라도 헌법과 법률에 따라 결정하고 집행하도록 견제하는 것이 헌법재판소 본연의 임무이므로, 그 한도에서 헌법소원심판의 대상이 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07-2","t":"개성공단 전면중단 조치는 국제평화를 위협하는 북한의 핵무기 개발을 경제적 제재조치를 통해 저지하려는 국제적 합의에 이바지하기 위한 조치로서, 통일부장관의 조정명령에 관한 남북교류협력에 관한 법률 제18조 제1항 제2호, 대통령의 국가의 계속성 보장 책무, 행정에 대한 지휘·감독권 등을 규정한 헌법 제66조, 정부조직법 제11조 등이 근거가 될 수 있으므로, 헌법과 법률에 근거한 조치로 보아야 한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07-3","t":"국무회의 심의, 이해관계자에 대한 의견청취절차 등을 거치지 아니한 이상 개성공단 전면중단 조치는 적법절차원칙을 위반하여 개성공단 투자기업인의 영업의 자유와 재산권을 침해한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07-4","t":"‘개성공단의 정상화를 위한 합의서’에는 국내법과 동일한 법적 구속력을 인정하기 어렵고, 과거 사례 등에 비추어 개성공단의 중단 가능성은 충분히 예상할 수 있었으므로, 개성공단 전면중단 조치는 신뢰보호원칙을 위반하여 개성공단 투자기업인의 영업의 자유와 재산권을 침해하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07-5","t":"개성공단 전면중단 조치는 공익 목적을 위하여 개별적, 구체적으로 형성된 구체적인 재산권의 이용을 제한하는 공용 제한이 아니므로, 이에 대한 정당한 보상이 지급되지 않았다고 하더라도 그 조치가 헌법 제23조 제3항을 위반하여 개성공단 투자기업인의 재산권을 침해한 것으로 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-1","t":"학원설립·운영자가 학원의 설립·운영 및 과외교습에 관한 법률을 위반하여 벌금형을 선고받은 경우 등록의 효력을 잃도록 정하고 있는 위 법률의 규정은 직업선택의 자유를 침해하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-2","t":"직업선택의 자유에 직업 내지 직종에 종사하는 데 필요한 전문지식을 습득하기 위한 직업교육장을 임의로 선택할 수 있는 직업교육장 선택의 자유도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-3","t":"읍·면의 이장은 직업의 자유에서 말하는 직업에 해당한다고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"직업선택의 자유"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-4","t":"새마을금고법위반죄로 벌금형을 선고받을 경우 그 선고받은 벌금액수에 상관없이 해당 임원이 당연퇴임되도록 규정한 새마을금고법의 규정은 직업선택의 자유를 침해하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-5","t":"제1종 운전면허의 취득요건으로 양쪽 눈의 시력이 각각 0.5(교정시력 포함) 이상일 것을 요구하는 도로교통법 시행령의 규정은 직업선택의 자유를 침해하지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-1","t":"임대차존속기간을 20년으로 제한한 민법 조항은 과잉금지원칙을 위반하여 계약의 자유를 침해하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-2","t":"헌법 제10조에 의하여 보장되는 행복추구권 속에는 일반적 행동자유권이 포함되고, 이 일반적 행동자유권으로부터 계약 체결의 여부, 계약의 상대방, 계약의 방식과 내용 등을 당사자의 자유로운 의사로 결정할 수 있는 계약의 자유가 파생된다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-3","t":"임대인이 실제 거주를 이유로 갱신을 거절한 후 정당한 사유 없이 제3자에게 임대한 경우의 손해배상책임 및 손해액을 규정한 주택임대차보호법 조항은 과잉금지원칙에 반하여 임대인의 계약의 자유와 재산권을 침해한다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-4","t":"주 52시간 상한제조항을 두어 1주간 최대 근로시간을 52시간으로 한정한 근로기준법 조항이 과잉금지원칙에 반하여 상시 5명 이상 근로자를 사용하는 사업주의 계약의 자유와 직업의 자유, 근로자의 계약의 자유를 침해하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-5","t":"금융위원회위원장이 2019. 12. 16. 시중 은행을 상대로 투기지역·투기과열지구 내 초고가 아파트(시가 15억 원 초과)에 대한 주택구입용 주택담보대출을 2019. 12. 17.부터 금지한 조치는 과잉금지원칙에 반하여 해당 주택담보대출을 받고자 하는 사람의 재산권 및 계약의 자유를 침해하지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-1","t":"안경사가 전자상거래 등의 방법으로 콘택트렌즈를 판매하는 것을 금지하고 있는 의료기사 등에 관한 법률 규정은 과잉금지원칙에 위반하여 안경사의 직업수행의 자유를 침해한다.","ox":"X","m":"①","c":"A","tp":"직업의 자유"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-2","t":"의료인의 의료기관 중복 개설을 금지·처벌하는 의료법 규정은 의료인의 직업수행의 자유를 침해한다고 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"직업의 자유"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-3","t":"직업의 선택 혹은 수행의 자유는 각자의 생활의 기본적 수요를 충족시키는 방편이 되고, 또한 개성신장의 바탕이 된다는 점에서 주관적 공권의 성격이 두드러진 것이기는 하나, 다른 한편으로는 국민 개개인이 선택한 직업의 수행에 의하여 국가의 사회질서와 경제질서가 형성된다는 점에서 사회적 시장경제질서라고 하는 객관적 법질서의 구성요소이기도 하다.","ox":"O","m":"③","c":"A","tp":"직업의 자유"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-4","t":"학원의 설립·운영 및 과외교습에 관한 법률(이하 ‘학원법’이라 한다)을 위반하여 벌금형을 선고받은 후 1년이 지나지 아니한 자는 학원설립·운영의 등록을 할 수 없도록 한 학원법 규정은 과잉금지원칙에 위배되어 직업선택의 자유를 침해한다고 보기 어렵다.","ox":"O","m":"④","c":"A","tp":"직업의 자유"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-5","t":"법인의 임원이 학원법을 위반하여 벌금형을 선고받은 경우, 법인의 학원설립·운영 등록이 효력을 잃도록 한 학원법 규정은 과잉금지원칙을 위반하여 학원법인의 직업수행의 자유를 침해한다.","ox":"O","m":"⑤","c":"A","tp":"직업의 자유"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-1","t":"헌법이 보장하고 있는 재산권은 재산가치 있는 모든 사법 및 공법상의 권리를 포함한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-2","t":"기초생활보장수급권은 공공부조의 일종으로서 순수하게 사회정책적 목적에서 주어지는 권리로서, 개인의 노력과 금전적 기여를 통하여 취득되는 재산권의 보호대상에 포함된다고 보기 어렵다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-3","t":"재산권에 대한 제한의 허용정도는 재산권 객체의 사회적 기능, 즉 재산권의 행사가 기본권의 주체와 사회전반에 대하여 가지는 의미에 달려 있다고 할 것인데, 재산권의 행사가 사회적 연관성과 사회적 기능을 가지면 가질수록 입법자에 의한 보다 광범위한 제한이 허용된다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-4","t":"토지는 국민경제의 관점에서나 그 사회적 기능에 있어서 다른 재산권과 같게 다루어야 할 성질의 것이 아니므로 다른 재산권에 비하여 보다 강하게 공동체의 이익을 관철할 것이 요구된다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-5","t":"헌법 제13조 제2항은 “모든 국민은 소급입법에 의하여 재산권을 박탈당하지 아니한다.”고 규정하고 있으므로, 진정소급입법에 의한 재산권의 제한은 국민이 소급입법을 예상할 수 있었던 경우에도 허용되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-1","t":"의료인의 면허된 의료행위 이외의 의료행위를 금지하고 처벌하는 의료법 규정이 제한하고 있는 직업의 자유는 국가자격제도정책과 국가의 경제상황에 따라 법률에 의하여 제한할 수 있는 국민의 권리에 해당한다. 국가정책에 따라 정부의 허가를 받은 외국인은 정부가 허가한 범위 내에서 소득활동을 할 수 있는 것이므로, 외국인이 국내에서 누리는 직업의 자유는 법률에 따른 정부의 허가에 의해 비로소 발생하는 권리이다. 따라서 외국인에게는 그 기본권주체성이 인정되지 아니하며, 자격제도 자체를 다툴 수 있는 기본권주체성이 인정되지 아니하는 이상 국가자격제도에 관련된 평등권에 관하여 따로 기본권주체성을 인정할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-2","t":"성매매를 한 사람을 형사처벌 하도록 규정한 성매매알선 등 행위의 처벌에 관한 법률 규정은 성행위 여부 및 그 상대방을 결정할 수 있는 개인의 성적 자기결정권을 제한하고, 개인의 성생활이라는 내밀한 사적 생활영역에서의 행위를 제한하고 있으므로 헌법 제17조가 보장하는 사생활의 비밀과 자유도 제한한다고 볼 수 있으나, 성매매의 사회적 유해성을 고려할 때 성판매자의 직업선택의 자유를 제한하고 있다고 보기는 어렵다.","ox":"X","m":"②","c":"A","tp":"직업의 자유"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-3","t":"헌법 제15조는 “모든 국민은 직업선택의 자유를 가진다.”라고 규정하고 있다. 여기서 규정하는 직업선택의 자유는 자신이 원하는 직업을 자유롭게 선택하는 좁은 의미의 ‘직업선택의 자유’와 그가 선택한 직업을 자기가 원하는 방식으로 자유롭게 수행할 수 있는 ‘직업수행의 자유’를 포함하는 “직업의 자유”를 뜻한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-4","t":"경비업을 경영하고 있는 자들이나 다른 업종을 경영하면서 새로이 경비업에 진출하고자 하는 자들로 하여금 경비업을 전문으로 하는 별개의 법인을 설립하지 않는 한 경비업과 그 밖의 업종을 겸영하지 못하도록 금지하고 있는 구 경비업법 규정은 이미 선택한 직업을 어떠한 제약 아래 수행하느냐의 관점이나 당사자의 능력이나 자격과도 상관없는 객관적 사유에 의한 제한으로서 직업의 자유에 대한 제한 중에서도 가장 심각한 제약이 아닐 수 없다. 이러한 제한은 월등하게 중요한 공익을 위하여 명백하고 확실한 위험을 방지하기 위한 경우에만 정당화될 수 있다고 보아야 한다. 따라서 이를 심사함에 있어서는 헌법 제37조 제2항이 요구하는 과잉금지의 원칙, 즉 엄격한 비례의 원칙이 그 심사척도가 된다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-5","t":"과잉금지원칙을 적용함에 있어, 어떠한 직업분야에 관한 자격제도를 만들면서 그 자격요건을 어떻게 설정할 것인가에 관하여는 국가에 폭넓은 입법재량권이 부여되어 있으므로, 다른 방법으로 직업선택의 자유를 제한하는 경우에 비하여 보다 유연하고 탄력적인 심사가 필요하다.","ox":"O","m":"⑤","c":"A","tp":"직업의 자유"}],"5":[{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-1","t":"법관에 의한 재판을 받을 권리를 보장한다고 함은 결국 법관이 사실을 확정하고 법률을 해석ㆍ적용하는 재판을 받을 권리를 보장한다는 뜻이고, 그와 같은 법관에 의한 사실 확정과 법률의 해석적용의 기회에 접근하기 어렵도록 제약이나 장벽을 쌓는 것은 허용되지 않는다.","ox":"O","m":"①","c":"A","tp":"헌법 제27조 재판청구권"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-2","t":"헌법 제27조에서 규정한 재판을 받을 권리에 모든 사건에 대해 상소법원의 구성 법관에 의한, 상소심 절차에 의한 재판을 받을 권리까지도 당연히 포함된다고 단정할 수는 없다.","ox":"O","m":"②","c":"A","tp":"헌법 제27조 재판청구권"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-3","t":"현역병이 군대 입대 전에 범한 범죄에 대하여 군사법원의 재판권을 규정하고 있는 군사법원법 조항은 현역병의 재판청구권을 침해하여 위헌이다.","ox":"X","m":"③","c":"A","tp":"헌법 제27조 재판청구권"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-4","t":"검사의 기소유예처분에 대하여 피의자가 불복하여 법원의 재판을 받을 수 있는 절차를 국가가 법률로 마련해야 할 헌법적 의무는 존재하지 않는다.","ox":"O","m":"④","c":"A","tp":"헌법 제27조 재판청구권"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-5","t":"어떤 사유를 재심사유로 정하여 재심을 허용할 것인가는 입법자가 확정판결에 대한 법적 안정성, 재판의 신속ㆍ적정성, 법원의 업무부담 등을 고려하여 결정하여야 할 입법정책의 문제이다.","ox":"O","m":"⑤","c":"A","tp":"헌법 제27조 재판청구권"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-1","t":"형사보상은 과실책임의 원리에 의하여 고의ㆍ과실로 인한 위법행위와 인과관계 있는 모든 손해를 배상하는 손해배상과는 달리, 형사사법절차에 내재하는 불가피한 위험에 대하여 형사사법기관의 귀책사유를 따지지 않고 형사보상청구권자가 입은 손실을 보상하는 제도이다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-2","t":"국가의 형사사법행위가 고의ㆍ과실로 인한 것으로 인정되는 경우에는 국가배상청구 등 별개의 절차에 의하여 인과관계 있는 모든 손해를 배상받을 수 있다.","ox":"O","m":"②","c":"A","tp":"형사보상청구권"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-3","t":"피고인으로서 구금되었다가 무죄판결을 받은 자 뿐만 아니라, 피의자로 구금되었다가 검사로부터 불기소처분(기소중지, 기소유예 제외)을 받은 자도 형사보상의 대상이 된다.","ox":"O","m":"③","c":"A","tp":"형사보상청구권"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-4","t":"형사보상청구는 무죄재판이 확정된 사실을 안 날로부터 3년, 무죄재판이 확정된 날로부터 5년 이내에 하여야 한다.","ox":"O","m":"④","c":"A","tp":"형사보상청구권"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-5","t":"형사보상청구권은 일신전속적 권리이므로, 청구권자 본인이 사망한 경우에는 상속인은 청구할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-1","t":"태평양전쟁 전후 강제동원된 자들 중 국내 강제동원자를 제외하고 국외 강제동원자에게만 위로금을 지급한 것은 합리적 근거가 없는 차별로서 위헌이다.","ox":"X","m":"①","c":"A","tp":"평등의 원칙과 평등권"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-2","t":"대한민국 국민인 남자에 한하여 병역의무를 부과한 법률조항은 평등권을 침해하는 것으로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"평등의 원칙과 평등권"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-3","t":"소년심판절차에서 검사에게 상소권이 인정되지 않는 것은 합리적 이유가 있어 피해자의 평등권을 침해한다고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"평등의 원칙과 평등권"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-4","t":"형법상의 범죄와 똑같은 구성요건을 규정하면서 법정형만을 상향 조정한 특정범죄 가중처벌 등에 관한 법률 규정은 평등원칙을 위반한 것이다.","ox":"O","m":"④","c":"A","tp":"평등의 원칙과 평등권"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-5","t":"개별법률금지의 원칙은 법률제정에 있어서 입법자가 평등원칙을 준수할 것을 요구하는 것이기 때문에 특정규범이 개별사건법률에 해당한다 하여 곧바로 위헌을 뜻하는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"평등의 원칙과 평등권"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-1","t":"대통령은 국민 전체에 대한 봉사자로 헌법상 공무원에 해당한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-2","t":"공무원이 국가 또는 지방자치단체에 대하여 어느 수준의 보수를 청구할 수 있는 권리는 헌법상 보장된 공무원의 재산권이다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-3","t":"고도의 정책결정 업무를 담당하거나 이러한 업무를 보조하는 공무원으로서 법령에서 지정된 정무직공무원은 특수경력직공무원에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-4","t":"직업공무원제도는 헌법이 보장하는 제도적 보장중의 하나이므로 입법자는 직업공무원제에 관하여 ‘최소한 보장’의 원칙의 한계 안에서 폭넓은 입법형성의 자유를 가진다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-5","t":"공무담임권의 보호영역에는 공직취임 기회의 자의적인 배제 뿐 아니라 공무원 신분의 부당한 박탈이나 권한(직무)의 부당한 정지도 포함된다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-1","t":"헌법상 보장된 청원권은 공권력과의 관계에서 일어나는 여러가지 이해관계, 의견, 희망 등에 관하여 적법한 청원을 한 모든 국민에게 국가기관이 청원을 수리할 뿐만 아니라 이를 심사하여 청원자에게 적어도 그 처리결과를 통지할 것을 요구할 수 있는 권리를 말한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-2","t":"국민이면 누구든지 널리 제기할 수 있는 민중적 청원제도는 재판청구권 기타 준사법적 구제청구와는 완전히 성질을 달리하는 것이기 때문에 청원권의 보호범위에는 청원사항의 처리결과에 심판서나 재결서에 준하여 이유를 명시할 것까지를 요구하는 것은 포함되지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-3","t":"법률·명령·조례·규칙 등의 제정·개정 또는 폐지도 청원할 수 있는 사항에 해당한다.","ox":"O","m":"③","c":"A","tp":"청원권"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-4","t":"헌법상 보장된 청원권의 주체는 국민이고, 국민에는 법인도 포함된다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-5","t":"청원소관관서는 청원법이 정하는 절차와 범위내에서 청원사항을 성실·공정·신속히 심사하고 청원인에게 그 처리결과를 통지할 의무가 있고, 그 처리내용은 공권력의 행사 또는 불행사에 해당하므로 청원인은 그 처리내용이 기대하는 바에 미치지 못하는 경우라면 헌법소원심판을 제기하는 것이 허용된다.","ox":"X","m":"⑤","c":"A","tp":"청원권"},{"y":2019,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2019_25-08","t":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"헌법 규정에 관한 다음 설명 중 옳지 않은 것은 모두 몇 개인가?","d":"가.모든 국민은 법률이 정하는 바에 의하여 국가기관에 문서로 청원할 권리를 가진다.\n나.형사피고인은 유죄의 판결이 선고될 때까지는 무죄로 추정된다.\n다.정당의 목적이나 활동이 민주적 기본질서에 위배될 때에는 국회는 헌법재판소에 그 해산을 제소할 수 있고, 정당은 헌법재판소의 심판에 의하여 해산된다.\n라.국회는 의원의 자격을 심사하며, 의원을 징계할 수 있다. 의원을 제명하려면 국회재적의원 3분의 2 이상의 찬성이 있어야 하는데, 제명처분에 대하여는 법원에 제소할 수 없다.\n마.헌법재판소는 법관의 자격을 가진 9인의 재판관으로 구성하고, 대법원은 대법원장을 포함하여 14인의 대법관으로 구성한다.","o":["1개","2개","3개","4개","5개 22-3"],"a":3}},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-1","t":"가산점제도는 제대군인과 제대군인이 아닌 사람을 차별하고, 현역복무나 상근예비역 소집근무를 할 수 있는 신체건장한 남자와 질병이나 심신장애로 병역을 감당할 수 없는 남자인 병역면제자를 차별하며, 보충역으로 편입되어 군복무를 마친 자를 차별하는 제도이므로, 그 입법목적의 정당성이 인정되지 않는다.","ox":"X","m":"①","c":"A","tp":"구 제대군인 지원"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-2","t":"가산점제도는 공직수행능력과는 아무런 합리적 관련성을 인정할 수 없는 성별 등을 기준으로 여성과 장애인 등의 사회진출기회를 박탈하는 것이므로 정책수단으로서의 적합성과 합리성을 상실한 것이다.","ox":"O","m":"②","c":"A","tp":"구 제대군인 지원"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-3","t":"가산점제도는 제대군인에게 채용시험 응시횟수에 무관하게, 가산점제도의 혜택을 받아 채용시험에 합격한 적이 있었는지에 관계없이 제대군인은 계속 가산점혜택을 부여하여, 한 사람의 제대군인을 위하여 몇 사람의 비제대군인의 기회가 박탈당할 수 있는 불합리한 결과를 초래한다.","ox":"O","m":"③","c":"A","tp":"구 제대군인 지원"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-4","t":"가산점제도는 승진, 봉급 등 공직내부에서의 차별이 아니라 공직에의 진입 자체를 어렵게 함으로써 공직선택의 기회를 원천적으로 박탈하는 것이기 때문에 공무담임권에 대한 더욱 중대한 제약으로서 작용하고 있다.","ox":"O","m":"④","c":"A","tp":"구 제대군인 지원"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-5","t":"여성공무원 채용목표제는 종래부터 차별을 받아 왔고 그 결과 현재 불리한 처지에 있는 여성을 유리한 처지에 있는 남성과 동등한 처지에까지 끌어 올리는 것을 목적으로 하는 제도이지만, 그 효과가 매우 제한적이어서, 이를 이유로 제대군인 가산점제도의 위헌성이 제거된다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"구 제대군인 지원"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-1","t":"모든 국민은 헌법과 법률이 정한 법관에 의하여 법률에 의한 재판을 받을 권리를 가진다.","ox":"O","m":"①","c":"A","tp":"헌법 제27조의 재판청구권"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-2","t":"공정한 재판을 받을 권리는 헌법 제27조의 재판청구권에 의하여 함께 보장된다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-3","t":"군인 또는 군무원이 아닌 국민은 대한민국의 영역 안에서는 중대한 군사상 기밀·초병·초소·유독음식물공급·포로·군용물에 관한 죄 중 법률이 정한 경우와 비상계엄이 선포된 경우를 제외하고는 군사법원의 재판을 받지 아니한다.","ox":"O","m":"③","c":"A","tp":"헌법 제27조의 재판청구권"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-4","t":"형사피해자는 법률이 정하는 바에 의하여 당해 사건의 재판절차에서 진술할 수 있다.","ox":"O","m":"④","c":"A","tp":"헌법 제27조의 재판청구권"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-5","t":"헌법에 재판청구권의 내용으로 신속한 재판을 받을 권리가 명시적으로 규정되어 있지 않다.","ox":"X","m":"⑤","c":"A","tp":"헌법 제27조의 재판청구권"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-1","t":"공무담임권의 보호영역에는 공무원이 특정의 장소에서 근무하는 것 또는 특정의 보직을 받아 근무하는 것을 포함하는 일종의 공무수행의 자유까지 포함된다.","ox":"X","m":"①","c":"A","tp":"헌법 제25조의 공무담임권"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-2","t":"헌법 제25조의 공무담임권이 공무원의 재임 기간 동안 충실한 공무 수행을 담보하기 위하여 공무원의 퇴직급여 및 공무상 재해보상을 보장할 것까지 그 보호영역으로 하고 있다고 보기 어렵다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-3","t":"공무담임권이란 입법부, 집행부, 사법부는 물론 지방자치단체 등 국가, 공공단체의 구성원으로서 그 직무를 담당할 수 있는 권리를 말한다. 여기서 직무를 담당한다는 것은 모든 국민이 현실적으로 그 직무를 담당할 수 있다고 하는 의미가 아니라, 국민이 공무담임에 관한 자의적이지 않고 평등한 기회를 보장받음을 의미한다.","ox":"O","m":"③","c":"A","tp":"헌법 제25조의 공무담임권"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-4","t":"공무담임권의 보호영역에는 공직취임의 기회의 자의적인 배제뿐만 아니라, 공무원 신분의 부당한 박탈도 포함된다.","ox":"O","m":"④","c":"A","tp":"헌법 제25조의 공무담임권"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-5","t":"모든 국민은 법률이 정하는 바에 의하여 공무담임권을 가진다.","ox":"O","m":"⑤","c":"A","tp":"헌법 제25조의 공무담임권"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-1","t":"평등의 원칙은 국민의 기본권 보장에 관한 우리 헌법의 최고원리로서 국가가 입법을 하거나 법을 해석 및 집행함에 있어 따라야 할 기준인 동시에, 국가에 대하여 합리적 이유 없이 불평등한 대우를 하지 말 것과 평등한 대우를 요구할 수 있는 국민의 권리이다.","ox":"O","m":"①","c":"A","tp":"평등권 및 평등의 원칙"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-2","t":"헌법은 사회적 신분에 대한 차별금지와 같이 헌법 제11조 제1항 후문에서 예시한 사유가 있는 경우에 절대적으로 차별을 금지할 것을 요구함으로써 입법자에게 인정되는 입법형성권을 제한한다.","ox":"X","m":"②","c":"A","tp":"평등권 및 평등의 원칙"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-3","t":"평등의 원칙은 일체의 차별적 대우를 부정하는 절대적 평등을 의미하는 것이 아니라 입법과 법의 적용에 있어서 합리적 근거 없는 차별을 하여서는 아니된다는 상대적 평등을 뜻하며, 합리적 근거 있는 차별 내지 불평등은 평등의 원칙에 반하는 것이 아니다.","ox":"O","m":"③","c":"A","tp":"평등권 및 평등의 원칙"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-4","t":"평등의 원칙 위반 여부를 심사함에 있어 엄격한 심사척도에 의할 것인지, 완화된 심사척도에 의할 것인지는 입법자에게 인정되는 입법형성권의 정도에 따라 달라지게 된다.","ox":"O","m":"④","c":"A","tp":"평등권 및 평등의 원칙"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-5","t":"특정법률 또는 법률조항이 단지 하나의 사건만을 규율하는 개별사건법률에 해당한다 하더라도 이러한 차별적 규율이 합리적인 이유로 정당화될 수 있는 경우에는 합헌적일 수 있다.","ox":"O","m":"⑤","c":"A","tp":"평등권 및 평등의 원칙"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-1","t":"법관에 의한 재판을 받을 권리를 보장한다고 함은 법관이 사실을 확정하고 법률을 해석ㆍ적용하는 재판을 받을 권리를 보장한다는 뜻이고, 그와 같은 법관에 의한 사실확정과 법률의 해석적용의 기회에 접근하기 어렵도록 제약이나 장벽을 쌓아서는 아니된다.","ox":"O","m":"①","c":"A","tp":"재판청구권"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-2","t":"재판청구권은 재판이라는 국가적 행위를 청구할 수 있는 적극적 측면과 헌법과 법률이 정한 법관이 아닌 자에 의한 재판이나 법률에 의하지 아니한 재판을 받지 아니하는 소극적 측면을 아울러 가지고 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-3","t":"법원이 직권으로 치료감호를 선고할 수 있는지 여부는 재판청구권의 적극적 측면은 물론 소극적 측면에도 해당하지 않는다. 따라서 ‘피고인 스스로 치료감호를 청구할 수 있는 권리’ 뿐만 아니라 ‘법원으로부터 직권으로 치료감호를 선고받을 수 있는 권리’는 헌법상 재판청구권의 보호범위에 포함된다고 보기 어렵다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-4","t":"헌법에 ‘공정한 재판’에 관한 명문의 규정은 없지만, 재판청구권이 국민에게 효율적인 권리보호를 제공하기 위해서는 법원에 의한 재판이 공정하여야 할 것임은 당연하므로 ‘공정한 재판을 받을 권리’는 헌법 제27조의 재판청구권에 의하여 함께 보장된다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-5","t":"재판에 대한 불복기간의 제한은 입법자가 상소심의 구조와 성격 등을 고려하여 결정할 입법재량의 문제이므로, 즉시항고 제기기간에 관하여 민사소송법은 1주로 규정하고 있음에도 형사소송법이 그 절반 가량인 3일로 규정한 것은 상대적으로 신속한 확정이 필요한 형사재판의 특성을 반영한 것으로서 그 차별취급에 합리적 이유가 있다.","ox":"X","m":"⑤","c":"A","tp":"재판청구권"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09","t":"평등의 원칙에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"평등의 원칙에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"㉠국가를 상대로 하는 당사자소송의 경우에는 가집행선고를 할 수 없다고 규정한 행정소송법 조항은 평등의 원칙에 반한다.\n㉡민사집행법상 경매절차에서의 매수신청보증금이 매수인의 대금미납으로 그에게 반환되지 아니하는 경우 국고에 귀속하지 않고 배당재원에 포함시키는 것과 달리 국세징수법상 공매절차에서 매각결정을 받은 매수인이 기한 내에 대금납부의무를 이행하지 아니하여 매각결정이 취소되는 경우 그가 납부한 계약보증금을 국고에 귀속하도록 규정한 국세징수법 조항은 국세징수절차와 민사집행절차의 성질이 다르므로 합리적 이유 있는 차별에 해당한다.\n㉢소년범 중 형의 집행이 종료되거나 면제된 자에 한하여 자격에 관한 법령의 적용에 있어 장래에 향하여 형의 선고를 받지 아니한 것으로 본다고 규정한 구 소년법(2018. 9. 18. 법률 제15757호로 개정되기 전의 것) 제67조는 평등의 원칙에 위반된다.\n㉣고소인․고발인만을 검찰청법상 항고권자로 규정하고 있는 검찰청법 조항은 기소유예처분을 받은 피의자의 평등권을 침해하는 것이다.\n㉤친고죄에 있어서 고소 취소가 가능한 시기를 제1심 판결선고전까지로 제한한 형사소송법 조항은 항소심 단계에서 고소 취소된 사람을 자의적으로 차별하는 것이 아니다.","o":["㉠, ㉡","㉡, ㉣","㉢, ㉣, ㉤","㉡, ㉢, ㉣","㉠, ㉢, ㉤"],"a":2}},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-1","t":"직업공무원제도는 헌법이 보장하는 제도적 보장의 하나이므로 ‘최대한 보장의 원칙’이 적용된다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-2","t":"공무원이 금고 이상의 형의 선고유예를 받은 경우 범죄의 유형과 내용에 관계없이 당연히 퇴직하도록 하는 것은 헌법에 위배되지 않는다.","ox":"X","m":"②","c":"A","tp":"공무원제도"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-3","t":"헌법 제7조 제1항에 의하여 국민전체에 대한 봉사자로서 국민에 대하여 책임을 지는 공무원과 같은 조 제2항에 의하여 신분과 정치적 중립성이 보장되는 공무원이 일치하지는 않는다.","ox":"O","m":"③","c":"A","tp":"공무원제도"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-4","t":"모든 공무원은 단체행동권을 가질 수 없다.","ox":"X","m":"④","c":"A","tp":"공무원제도"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-5","t":"공무원에게 직무의 내외를 불문하고 품위유지의무를 부과하고, 품위손상행위를 공무원에 대한 징계사유로 규정한 국가공무원법 조항은 명확성 원칙에 위배된다.","ox":"X","m":"⑤","c":"A","tp":"공무원제도"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-1","t":"헌법상 형사보상청구권은 구금되었던 형사피고인뿐만 아니라 구금되었던 형사피의자에게도 인정된다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-2","t":"입법자는 형사보상청구권의 구체적인 내용과 절차를 정함에 있어 광범위한 입법형성의 자유를 가진다. 따라서 형사보상청구권의 구체적인 내용과 절차를 정한 법률의 위헌 심사에서는 그 심사기준으로 자의금지원칙이 적용된다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-3","t":"형사보상청구권에 관한 헌법 제28조에서 규정하는 ‘정당한 보상’은 헌법 제23조 제3항에서 재산권의 침해에 대하여 규정하는 ‘정당한 보상’과는 차이가 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-4","t":"형사피고인으로서 구금되었던 자의 형사보상청구 사건은 무죄재판을 한 법원이 관할한다.","ox":"O","m":"④","c":"A","tp":"형사보상청구권"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-5","t":"형사피고인으로서 구금되었던 자의 형사보상청구는 무죄재판이 확정된 사실을 안 날부터 3년, 무죄재판이 확정된 때부터 5년 이내에 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"형사보상청구권"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-1","t":"국가배상법 제2조 소정의 “공무원”이라 함은 국가공무원법이나 지방공무원법에 의하여 공무원으로서의 신분을 가진 자에 국한하지 않고, 널리 공무를 위탁받아 실질적으로 공무에 종사하고 있는 일체의 자를 가리키는 것이라고 봄이 상당하다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-2","t":"헌법재판소는 헌법 제28조는 형사보상청구권의 내용을 법률에 의해 구체화하도록 규정하고 있으므로 형사보상법에서 형사보상청구의 제척기간을 1년의 단기로 규정하거나, 형사보상의 청구에 대하여 한 보상의 결정에 대하여 불복을 할 수 없도록 하여 단심재판으로 규정한 것은 형사보상청구권을 침해하는 것이 아니라고 보았다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-3","t":"대법원은 국회의원의 입법행위는 그 입법 내용이 헌법의 문언에 명백히 위반됨에도 불구하고 국회가 굳이 당해 입법을 한 것과 같은 특수한 경우가 아닌 한 국가배상법 제2조 제1항 소정의 위법행위에 해당된다고 볼 수 없다고 보았다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-4","t":"대법원은 국가 또는 지방자치단체라 할지라도 공권력의 행사가 아니고 단순한 사경제의 주체로 활동하였을 경우에는 그 손해배상책임에 국가배상법이 적용될 수 없고 민법상의 사용자책임 등이 인정된다고 보고 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-5","t":"청구인이 검사의 “무혐의” 불기소처분으로 말미암아 헌법상 보장된 재판절차진술권을 침해받았다고 주장하여 그 취소를 구하는 헌법소원심판을 청구할 수 있기 위하여는 헌법 제27조 제5항에 의하여 재판절차진술권이 보장되는 형사피해자이어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04-1","t":"민사소송법상 재심사유를 어떻게 정하여 재심을 허용할 것인가는 입법자가 확정판결에 대한 법적 안정성, 재판의 신속ㆍ적정성, 법원의 업무부담 등을 고려하여 결정하여야 할 입법정책의 문제이다.","ox":"O","m":"①","c":"A","tp":"민사소송법상 재심제도"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04-2","t":"판결주문에 영향이 없는 당사자의 공격방어방법에 대한 판단이 누락된 경우에는, 판결주문에 간접적으로만 연관되는 판단이유가 누락된 경우와 달리 재심의 소를 통하여 기판력 등 확정된 판결의 효력을 배제하는 것을 허용해야 할 만큼 정의의 요청이 절박하다고 할 수 없다.","ox":"X","m":"②","c":"A","tp":"민사소송법상 재심제도"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04-3","t":"재심사유의 위헌성은 입법자가 분쟁의 신속한 해결을 통한 법적 안정성의 확보에만 매몰되어 재판의 적정성이라는 법치주의의 또 다른 이념을 현저히 희생함으로써, 제반 기본권의 실현을 위한 기본권으로서의 재판청구권의 본질을 심각하게 훼손하는 등 입법형성권의 한계를 일탈하여 그 내용이 현저히 자의적인 것이 아닌 한 인정되기 어렵다.","ox":"O","m":"③","c":"A","tp":"민사소송법상 재심제도"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04-4","t":"재심은 판결에 대한 불복방법의 하나인 점에서는 상소와 마찬가지라고 할 수 있지만, 확정판결에 대한 불복방법인 점에서 상소와 다르고, 확정판결에 대한 법적안정성의 요청은 미확정판결에 대한 그것보다 훨씬 크기 때문에, 상소보다 더 예외적으로 인정되어야 한다는 점에서 본질적인 차이가 있다.","ox":"O","m":"④","c":"A","tp":"민사소송법상 재심제도"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04-5","t":"건전한 상식을 가진 일반인이면 재심사유인 ‘판결에 영향을 미칠 중요한 사항에 관하여 판단을 누락한 때’의 의미내용을 예측할 수 있고, 이미 확립된 판례에 기초하여 그 해석 및 적용에 대한 신뢰성이 있는 원칙을 도출할 수 있으므로 해석자 개인의 주관적인 판단에 따라 그 해석이 좌우될 가능성이 없다.","ox":"O","m":"⑤","c":"A","tp":"민사소송법상 재심제도"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-1","t":"공무원이 지위를 이용하여 범한 공직선거법위반죄에 대하여 일반인이 범한 공직선거법위반죄와 달리 해당 선거일 후 10년으로 공소시효를 정한 공직선거법 규정은 합리적인 이유 있는 차별로서 평등원칙에 위반되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-2","t":"반복적으로 범행을 저지르는 절도 사범에 관한 가중처벌 규정인 특정범죄가중처벌 등에 관한 법률(2016. 1. 6. 법률 제13717호로 개정된 것) 제5조의4 제5항 제1호는 불법성의 정도가 같다고 보기 어려운 형법상 절도죄, 야간주거침입절도죄, 특수절도죄를 동등하게 취급하는 것으로 평등원칙에 위반된다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-3","t":"선거와 무관하게 후원회를 설치 및 운영할 수 있는 자를 중앙당과 국회의원으로 한정하여 국회의원과 지방의회의원을 달리 취급하는 것은, 불합리한 차별에 해당한다.","ox":"O","m":"③","c":"A","tp":"평등 원칙"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-4","t":"군형법이 형법상 강제추행죄나 준강제추행죄 등과 달리 강제추행죄 및 항거불능 상태를 이용한 준강제추행죄에 대하여 벌금형을 선택형으로 규정하지 아니하였다 하더라도 형벌체계의 균형성을 상실하여 평등원칙에 위배된다고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-5","t":"동일한 밀수입 예비행위에 대하여 수입하려던 물품의 원가가 2억 원 미만인 때에는 관세법이 적용되어 본죄의 2분의 1을 감경한 범위에서 처벌하는 반면, 물품원가가 2억 원 이상인 경우에는 특정범죄 가중처벌 등에 관한 법률이 적용되어 가중처벌 하는 것은 합리적 이유가 있다고 보기 어렵다.","ox":"O","m":"⑤","c":"A","tp":"평등 원칙"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-1","t":"헌법 제7조 제2항이 규정한 직업공무원제도는 엽관제를 지양함으로써 정치와 공직을 분리하고 이를 통하여 공무수행의 안정성, 전문성을 꾀하려는 데에 그 목적이 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-2","t":"공무원은 정당의 발기인 및 당원이 될 수 없으나, 예외적으로 대통령, 국무총리, 국무위원, 국회의원, 지방의회의원, 선거에 의하여 취임하는 지방자치단체의 장이나 교육감에게는 이를 허용하고 있다.","ox":"X","m":"②","c":"A","tp":"직업공무원제도"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-3","t":"직업공무원의 신분을 보장하는 것은 소신과 능력에 따라 국민 전체를 위한 직무수행이 가능하도록 하기 위한 것으로, 생계보호, 직업보호의 의미도 아울러 지니며, 이러한 신분보장은 헌법 제25조의 공무담임권의 보호영역에도 포함된다.","ox":"O","m":"③","c":"A","tp":"직업공무원제도"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-4","t":"직무의 내외를 불문하고 체면이나 위신을 손상하는 행위를 징계사유로 규정한 국가공무원법 규정은 명확성원칙에 위배되거나 과잉금지원칙에 반한다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"직업공무원제도"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-5","t":"직업공무원제도에 있어 과학적 직위분류제나 성적주의 등에 따른 인사의 공정성을 유지하는 장치도 중요하지만, 무엇보다도 그 중추적 요소는 공무원의 정치적 중립과 신분보장에 있다 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-1","t":"공무담임권의 보장은 모든 국민이 현실적으로 국가나 공공단체의 직무를 담당할 수 있다고 하는 의미가 아니라, 국민이 공무담임에 관한 자의적이지 않고 평등한 기회를 보장받는 것, 즉 공직취임의 기회를 자의적으로 배제당하지 않음을 의미하며, 공무담임권의 보호영역에는 공직취임 기회의 자의적인 배제와 공무원 신분의 부당한 박탈 등이 포함된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-2","t":"선출직 공무원과 달리 직업공무원에게는 정치적 중립성과 더불어 효율적으로 업무를 수행할 수 있는 능력이 요구되므로, 직업공무원의 공직진출에 관한 규율은 임용희망자의 능력·전문성 등 능력주의를 바탕으로 이루어져야 한다. 헌법은 이를 명시적으로 밝히고 있지 않지만 헌법 제7조에서 보장하는 직업공무원제도의 기본적 요소에 능력주의가 포함되는 점에 비추어 공무담임권은 모든 국민이 그 능력과 적성에 따라 공직에 취임할 수 있는 균등한 기회를 보장함을 내용으로 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-3","t":"교육의원후보자가 되려는 사람으로 하여금 5년 이상의 교육경력 또는 교육행정경력을 갖추도록 규정한 법률조항은 전문성이 담보된 교육의원이 교육위원회의 구성원이 되도록 하여 헌법 제31조 제4항이 보장하고 있는 교육의 자주성·전문성·정치적 중립성을 보장하면서도 지방자치의 이념을 구현하기 위한 것으로서 공무담임권을 침해하는 것이라 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-4","t":"금고 이상의 형의 선고유예를 받은 경우에는 군무원직에서 당연퇴직하도록 규정한 법률조항은, 임용결격 사유에 해당하는 사람을 공무원의 직무로부터 배제함으로써 그 직무수행에 대한 국민의 신뢰, 공무원직에 대한 신용 등을 유지하고 그 직무의 정상적인 운영을 확보하기 위한 것으로서 헌법 제25조에 규정된 공무담임권을 침해하지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-5","t":"후보자가 되고자 하는 자가 당해 선거구 안에 있는 단체 등에 기부행위를 하는 경우 처벌하도록 규정한 공직선거법 조항은, 이로 인하여 벌금 100만 원 이상의 형을 선고받으면 공직선거법에 의하여 당선자는 그 당선이 무효로 되고 일정기간 동안 일부 공직에 취임하거나 임용될 수 없으며, 피선거권이 제한되지만, 이러한 기본권 제한은 위 조항의 직접적 효과라기보다는 벌금 100만 원 이상의 형을 선고받은 경우 공직선거법이 적용되어 나타난 결과이므로, 위 조항에 의하여 공무담임권이 제한된다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-1","t":"보훈보상대상자의 부모에 대한 유족보상금 지급 시 수급권자를 1인에 한정하고 나이가 많은 자를 우선하도록 규정한 보훈보상대상자 지원에 관한 법률의 규정은 나이가 적은 부모 일방을 합리적 이유 없이 차별하는 것에 해당하므로 헌법에 위반된다.","ox":"O","m":"①","c":"A","tp":"평등의 원칙"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-2","t":"교사의 신규채용에 있어 국·공립대학교졸업생을 우선시키는 교육공무원법은 사립사범대학 졸업자가 교육공무원으로 채용될 수 있는 기회를 제한 또는 박탈하게 되므로 평등의 원칙에 위반된다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-3","t":"공익근무요원의 경우와 달리 산업기능요원의 군 복무기간을 공무원 재직기간으로 산입하지 않도록 규정한 제대군인지원에 관한 법률의 규정은 헌법에 위반된다.","ox":"X","m":"③","c":"A","tp":"평등의 원칙"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-4","t":"형법 제159조 ‘시체 등의 오욕죄’의 법정형에 벌금형이 있는데 반하여, 형법 제160조 ‘분묘의 발굴죄’의 법정형에 벌금형을 선택적으로 규정함이 없이 5년 이하의 징역으로 규정하고 있더라도 평등의 원칙에 위배되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-5","t":"보상금의 지급을 신청할 수 있는 자의 범위를 ‘내부 공익신고자’로 한정함으로써 ‘외부 공익신고자’를 보상금 지급대상에서 배제하도록 정한 공익신고자 보호법의 규정은 평등의 원칙에 위배되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-1","t":"도시개발법의 도시개발사업, 도시 및 주거환경정비법의 재개발사업 및 재건축사업 등에 대해서는 사업시행 결과 사업구역 내 가구 수가 증가하지 아니하는 경우에는 학교용지부담금을 부과할 수 없도록 하면서, 주택법에 따른 주택건설사업에 대해서는 가구 수 증가와 상관없이 개발사업의 결과로 지어지는 전체 가구 수에 대하여 학교용지부담금을 부과하는 구 학교용지 확보 등에 관한 특례법 규정은 학교시설 확보의 필요성을 유발하는 정도와 무관한 불합리한 차별로서 헌법상 평등원칙에 위반된다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-2","t":"국가유공자의 유족 중 보상을 받을 자녀의 순위를 정함에 있어 협의로 지정되거나 주로 부양한 자녀가 없는 경우, 나이가 많은 자녀를 선순위 유족으로 정하는 국가유공자법 규정은 국가유공자의 자녀 중 나이가 많은 자와 그렇지 않은 자를 합리적인 이유 없이 차별하므로, 평등원칙에 위반된다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-3","t":"성폭력범죄 피해자가 국민참여재판을 원하지 아니하는 경우 법원이 국민참여재판 배제결정을 할 수 있도록 규정한 국민의 형사재판 참여에 관한 법률 규정은 성폭력범죄 및 그에 관한 재판의 특수성을 고려한 것으로 합리적인 근거가 있는바, 평등원칙에 위반되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-4","t":"일정한 법무법인으로 하여금 변리사 업무를 수행할 수 있도록 한 변호사법 규정은 평등원칙에 위반되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-5","t":"직계혈족, 배우자, 동거친족, 동거가족 또는 그 배우자 이외의 친족 간에 권리행사방해죄를 범한 때는 고소가 있어야 공소를 제기할 수 있도록 한 형법 제328조 제2항은 합리적 이유가 있으므로 평등원칙에 위배된다고 보기 어렵다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-1","t":"평등위반 여부를 심사함에 있어 엄격한 심사척도에 의할 것인지, 완화된 심사척도에 의할 것인지는 입법자에게 인정되는 입법형성권의 정도에 따라 달라지게 되는데, 헌법에서 특별히 평등을 요구하고 있는 경우에 한하여 예외적으로 엄격한 심사척도가 적용될 수 있다. 헌법이 스스로 차별의 근거로 삼아서는 아니 되는 기준을 제시하거나 차별을 특히 금지하고 있는 영역을 제시하고 있다면 그러한 기준을 근거로 한 차별이나 그러한 영역에서의 차별에 대하여 엄격하게 심사하는 것이 정당화된다.","ox":"X","m":"①","c":"A","tp":"평등권"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-2","t":"평등권의 침해 여부에 대한 심사기준 가운데 자의심사의 경우에는 차별을 정당화하는 합리적인 이유가 있는지만을 심사하기 때문에 그에 해당하는 비교대상 간의 사실상의 차이나 입법목적(차별목적)의 발견⋅확인에 그친다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-3","t":"평등권의 침해 여부에 대한 심사기준 가운데 비례원칙에 의한 심사의 경우에는 단순히 합리적인 이유의 존부문제가 아니라 차별을 정당화하는 이유와 차별 간의 상관관계에 대한 심사, 즉 비교대상 간의 사실상의 차이의 성질과 비중 또는 입법목적(차별목적)의 비중과 차별의 정도에 적정한 균형관계가 이루어져 있는가를 심사한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-4","t":"변호사, 공인회계사, 변리사, 관세사, 공인중개사 등과 세무사는 각각의 법률에 의하여 부여된 고유한 업무가 다르고 직종 간 특성에 따라 서로 다른 권한과 책임이 있으므로, 각 전문자격제도를 규율하기 위해 제정한 당해 법률 위반을 이유로 그 전문자격을 일정기간 제한하거나 정지시키는 사유 내지 등록취소사유를 정함에 있어 이를 각 법률마다 다르게 규정하고 있다고 할지라도 이를 본질적으로 동일한 집단에 대한 차별취급이라고 볼 수는 없다.","ox":"O","m":"④","c":"A","tp":"평등권"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-5","t":"헌법 제11조 제1항은 “모든 국민은 법 앞에 평등하다. 누구든지 성별⋅종교 또는 사회적 신분에 의하여 정치적⋅경제적⋅사회적⋅문화적 생활의 모든 영역에 있어서 차별을 받지 아니한다.”라고 규정하고 있는바 여기서 사회적 신분이란 사회에서 장기간 점하는 지위로서 일정한 사회적 평가를 수반하는 것을 의미한다 할 것이므로, 전과자도 사회적 신분에 해당된다고 할 것이며 누범을 가중처벌하는 것이 전과자라는 사회적 신분을 이유로 차별대우를 하는 것이 되어 헌법상의 평등의 원칙에 위배되는 것이 아닌가 하는 의문이 생길 수 있다.","ox":"O","m":"⑤","c":"A","tp":"평등권"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-1","t":"공무원의 정치적 중립과 신분보장은 직업공무원제도의 중추적 요소이다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-2","t":"공무담임권의 보호영역에는 공직취임의 기회의 자의적인 배제뿐만 아니라 공무원 신분의 부당한 박탈도 포함된다.","ox":"O","m":"②","c":"A","tp":"공무원제도"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-3","t":"대통령이 특정 사인의 이익을 위해 대통령으로서의 지위와 권한을 남용하는 것은 공무원은 국민전체에 대한 봉사자라고 규정한 헌법 제7조 제1항에 위반된 행위로서 탄핵사유가 될 수 있다.","ox":"O","m":"③","c":"A","tp":"공무원제도"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-4","t":"공무원이 감봉처분을 받은 경우 12개월간 승진임용을 제한하는 것은 과잉금지원칙에 위반되어 공무담임권을 침해한다.","ox":"X","m":"④","c":"A","tp":"공무원제도"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-5","t":"특별한 사정 없이 공무원이 특정의 장소에서 근무하는 것이나 특정의 보직을 받아 근무하는 것을 포함하는 일종의 ‘공무수행의 자유’가 헌법 제25조의 공무담임권의 보호영역에 포함된다고 보기는 어렵다.","ox":"O","m":"⑤","c":"A","tp":"공무원제도"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-1","t":"헌법 제27조 제1항에 따라 모든 국민은 헌법과 법률이 정한 자격과 절차에 의하여 임명되고 물적 독립과 인적 독립이 보장된 법관에 의하여 합헌적인 법률이 정한 내용과 절차에 따라 재판을 받을 권리를 가진다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-2","t":"형사소송에 있어서 재심은 판결에 대한 불복방법의 하나인 점에서는 상소와 마찬가지라고 할 수 있지만, 상소와는 달리 재심은 확정판결에 대한 불복방법이고, 확정판결에 대한 법적 안정성의 요청은 미확정판결에 대한 그것보다 훨씬 크기 때문에, 상소보다 더 예외적으로 인정되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-3","t":"확정력 있는 판결이 항상 정당성을 지닌다고 할 수는 없고 판결의 오류가능성을 완전히 배제할 수 없으므로 입법자는 확정력을 배제하고 그 오류를 시정해야 하는 경우가 무엇인지를 구체적으로 가려내어야 한다. 이는 법치주의에 내재된 두 가지의 대립적 이념, 즉 법적 안정성과 정의의 실현이라는 상반된 요청을 어떻게 조화시키느냐의 문제로서 입법자의 형성적 자유가 넓게 인정되는 영역이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-4","t":"재심제도와 관련하여 인정되는 입법적 재량을 감안하면, 형사소송법상 재심청구권자를 규정하고 있는 조항의 위헌성에 대한 판단은, 그 내용이 입법형성권의 한계를 일탈하여 현저히 자의적인지 여부에 의하여 결정되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-5","t":"구 진실ㆍ화해를 위한 과거사정리 기본법상 ‘1945년 8월 15일부터 한국전쟁 전후의 시기에 불법적으로 이루어진 민간인 집단 사망ㆍ상해ㆍ실종사건’, ‘1945년 8월 15일부터 권위주의 통치 시까지 헌정질서 파괴행위 등 위법 또는 현저히 부당한 공권력의 행사로 인하여 발생한 사망ㆍ상해ㆍ실종사건, 그 밖에 중대한 인권침해사건과 조작의혹사건’과 관련하여, 유죄의 선고를 받은 자가 사망한 경우 그 배우자, 직계친족 또는 형제자매를 재심청구권자로 정한 형사소송법 제424조 제4호가 현저히 자의적이어서 재심청구권자가 아닌 친족의 재판청구권을 침해한다고 보기는 어렵다.","ox":"X","m":"⑤","c":"A"}],"9":[{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-1","t":"대법관의 수는 대법원장을 제외하고 14명으로 한다.","ox":"X","m":"①","c":"A","tp":"법원의 조직"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-2","t":"행정법원의 심판권은 판사 3명으로 구성된 합의부에서 행사한다. 다만, 단독판사가 심판할 것으로 행정법원 합의부가 결정한 사건의 심판권은 단독판사가 행사한다.","ox":"O","m":"②","c":"A","tp":"법원의 조직"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-3","t":"대통령령이 헌법에 위반되는지 여부가 재판의 전제가 된 경우에는 법원은 헌법재판소에 제청하여 그 심판에 의하여 재판한다.","ox":"X","m":"③","c":"A","tp":"법원의 조직"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-4","t":"단심제인 대통령선거 무효소송에 있어서 대법원이 해당 선거가 무효라고 판결하기 위해서는 관여 대법관의 3분의 2 이상의 찬성이 필요하다.","ox":"X","m":"④","c":"A","tp":"법원의 조직"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-5","t":"판사의 임명 및 연임 동의를 위해서는 대법관회의에서 대법관 전원의 3분의 2 이상의 출석과 출석인원 전원의 찬성으로 의결되어야 한다.","ox":"X","m":"⑤","c":"A","tp":"법원의 조직"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-1","t":"대법원의 심판권은 대법관 전원의 3분의 2 이상으로 구성되고 대법원장이 재판장이 되는 합의체에서 행사하는 것이 원칙이다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-2","t":"대법원에 대법관이 아닌 법관을 둘 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-3","t":"대법관의 수는 대법원장을 포함하여 14명으로 한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-4","t":"대법원장은 대법관의 임명제청권을 가지며, 대법관이 아닌 법관은 대법관회의의 동의를 얻어 대법원장이 임명한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-5","t":"대법원장이 궐위되거나 부득이한 사유로 직무를 수행할 수 없을 때에는 법원행정처장이 그 권한을 대행한다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-1","t":"명령·규칙 또는 처분이 헌법이나 법률에 위반되는 여부가 재판의 전제가 된 경우에는 대법원은 이를 최종적으로 심사할 권한을 가진다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-2","t":"헌법이 대법원을 최고법원으로 규정하였다고 하여 곧바로 대법원이 모든 사건을 상고심으로서 관할하여야 한다는 결론이 당연히 도출되는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-3","t":"대법원장은 대법원의 일반사무를 관장하며, 대법원의 직원과 각급 법원 및 그 소속 기관의 사법행정사무에 관하여 직원을 지휘·감독한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-4","t":"대법원장의 임기는 6년으로 하며, 중임할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-5","t":"법관의 정년은 법률로 정한다.","ox":"O","m":"⑤","c":"A","tp":"법원"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-1","t":"대법관의 임기는 6년이고, 법률이 정하는 바에 의하여 연임할 수 있다.","ox":"O","m":"①","c":"A","tp":"법원"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-2","t":"법관은 탄핵 또는 금고 이상의 형의 선고에 의하지 아니하고는 파면되지 아니하고, 징계처분에 의하지 아니하고는 정직ㆍ감봉 기타 불리한 처분을 받지 아니한다.","ox":"O","m":"②","c":"A","tp":"법원"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-3","t":"법관에 대한 징계처분 취소청구소송을 대법원의 단심재판에 의하도록 한 법관징계법 조항은 재판청구권을 침해한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-4","t":"대법원장과 대법관이 아닌 법관은 대법관회의의 동의를 얻어 대법원장이 임명한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-5","t":"군사법원의 상고심은 대법원에서 관할한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-1","t":"대법원이 법관에 대한 징계처분 취소청구소송을 단심으로 재판하는 경우에는 사실확정도 대법원의 권한에 속하여 법관에 의한 사실확정의 기회가 박탈되었다고 볼 수 없으므로, 법관에 대한 대법원장의 징계처분 취소청구소송을 대법원에 의한 단심재판에 의하도록 한 것은 헌법 제27조 제1항의 재판청구권을 침해하지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-2","t":"단독판사와 합의부의 심판권을 어떻게 분배할 것인지 등에 관한 문제는 기본적으로 입법형성권을 가진 입법자가 사법정책을 고려하여 결정할 사항으로, 입법자는 국민의 권리가 효율적으로 보호되고 재판제도가 적정하게 운용되도록 법원조직에 따른 재판사무 범위를 배분·확정하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-3","t":"재판의 심리와 판결은 공개한다. 다만, 심리는 국가의 안전보장 또는 안녕질서를 방해하거나 선량한 풍속을 해할 염려가 있을 때에는 법원의 결정으로 공개하지 아니할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-4","t":"명령·규칙 또는 처분이 헌법이나 법률에 위반되는 여부가 재판의 전제가 된 경우에는 법원은 헌법재판소에 제청하여 그 심판에 의하여 재판한다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-5","t":"형사재판에 있어서 사법권의 독립은 심판기관인 법원과 소추기관인 검찰청의 분리를 요구함과 동시에 법관이 실제 재판에 있어서 소송당사자인 검사와 피고인으로부터 부당한 간섭을 받지 않은 채 독립하여야 할 것을 요구한다.","ox":"O","m":"⑤","c":"A"}]};
window.PAIRS=[{"n":19,"s":0.818,"o":{"i":"법무사2021_27-31-5","t":"선하증권은 운송물인도청구권을 표창하는 유가증권으로서 화물상환증과 같은 물권적 효력이 있다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2016_22-29-1","t":"선하증권은 운송물인도청구권을 표창하는 유가증권으로서 화물상환증과 같은 물권적 효력은 없다.","y":2016,"e":"법무사 1차"}},{"n":19,"s":0.8,"o":{"i":"법무사2016_22-29-4","t":"재용선계약 등에 의하여 복수의 해상운송 주체가 있는 경우 운송의 최종 수요자인 운송의뢰인에 대한 관계에서 선하증권의 발행사실만으로 당연히 운송인의 지위가 인정되는 것은 아니다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2021_27-31-2","t":"재용선계약 등에 의하여 복수의 해상운송 주체가 있는 경우 운송의 최종 수요자인 운송의뢰인에 대한 관계에서도 선하증권의 발행사실만으로 당연히 운송인의 지위가 인정된다.","y":2021,"e":"법무사 1차"}},{"n":19,"s":0.772,"o":{"i":"법무사2017_23-46-2","t":"상법 제731조 제1항을 위반하여 피보험자의 서면 동의 없이 타인의 사망을 보험사고로 하는 보험계약을 체결한 자 스스로가 무효를 주장하는 것은 신의성실 또는 금반언의 원칙에 반하지 않는 것으로서 허용된다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2025_31-37-1","t":"상법 제731조 제1항을 위반하여 피보험자의 서면 동의 없이 타인의 사망을 보험사고로 하는 보험계약을 체결한 자가 스스로가 무효를 주장하는 것은 신의성실 또는 금반언의 원칙에 반한다.","y":2025,"e":"법무사 1차"}},{"n":19,"s":0.713,"o":{"i":"법무사2026_32-36-3","t":"운송인은 여객의 연착으로 인한 손해에 대하여 책임을 진다. 다만, 운송인이 자신과 그 사용인 및 대리인이 손해를 방지하기 위하여 합리적으로 요구되는 모든 조치를 하였다는 것 또는 그 조치를 하는 것이 불가능하였다는 것을 증명한 경우에는 그 책임을 면한다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2026_32-36-5","t":"운송인은 수하물의 연착으로 인한 손해에 대하여 책임을 지고, 운송인이 자신과 그 사용인 및 대리인이 손해를 방지하기 위하여 합리적으로 요구되는 모든 조치를 하였다는 것 또는 그 조치를 하는 것이 불가능하였다는 것을 증명한 경우에도 그 책임을 면하지 못한다.","y":2026,"e":"법무사 1차"}},{"n":14,"s":0.829,"o":{"i":"법무사2026_32-49-4","t":"이사가 그 지위에 기하여 주주총회결의 취소의 소를 제기하였다가 소송계속 중에 사망하였거나 사실심 변론종결 후에 사망하였다면, 그 소송은 이사의 사망으로 중단되지 않고 그대로 종료된다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2019_25-34-1","t":"이사가 그 지위에 기하여 주주총회결의 취소의 소를 제기하였다가 소송 계속 중에 사망하였거나 사실심 변론종결 후에 사망하였다면, 그 소송은 이사의 사망으로 중단된다.","y":2019,"e":"법무사 1차"}},{"n":14,"s":0.786,"o":{"i":"법무사2022_28-42-3","t":"회사는 이사회의 결의로 회사를 대표할 이사를 선정하여야 한다. 그러나 정관으로 주주총회에서 이를 선정할 것을 정할 수 있다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2016_22-49-1","t":"회사는 주주총회의 결의로 회사를 대표할 이사를 선정하여야 한다. 그러나 정관으로 이사회에서 이를 선정할 것을 정할 수 있다.","y":2016,"e":"법무사 1차"}},{"n":14,"s":0.712,"o":{"i":"법무사2026_32-24-2","t":"회사를 대표할 권한이 없는 표현대표이사가 다른 대표이사의 명칭을 사용하여 어음행위를 한 경우, 회사가 책임을 지는 선의의 제3자의 범위에는 표현대표이사로부터 직접 어음을 취득한 상대방뿐만 아니라, 그로부터 어음을 다시 배서양도 받은 제3취득자도 포함된다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2017_23-32-4","t":"회사를 대표할 권한이 없는 표현대표이사가 다른 대표이사의 명칭을 사용하여 어음행위를 한 경우, 회사가 책임을 지는 선의의 제3자의 범위에는 표현대표이사로부터 직접 어음을 취득한 상대방만 포함된다.","y":2017,"e":"법무사 1차"}},{"n":14,"s":0.549,"o":{"i":"법무사2025_31-47-3","t":"상법 제368조 제2항이 규정하는 ‘대리권을 증명하는 서면’이라 함은 위임장을 일컫는 것으로서 회사가 위임장과 함께 인감증명서, 참석장 등을 제출하도록 요구하는 것은 대리인의 자격을 보다 확실하게 확인하기 위하여 요구하는 것일 뿐, 이러한 서류 등을 지참하지 아니하였다 하더라도 주주 또는 대리인이 다른 방법으로 위임장의 진정성 내지 위임의 사실을 증명할 수 있다면 회사는 그 대리권을 부정할 수 없다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2020_26-47-5","t":"상법 제368조 제2항이 규정하는 대리권을 증명하는 서면이란 위임장을 일컫는 것으로서 회사가 위임장과 함께 인감증명서, 참석장 등을 제출하도록 요구하는 것은 대리인의 자격 유무를 일률적으로 명확히 확인하기 위한 취지로서, 이러한 서류 등을 지참하지 아니한 대리인이 다른 방법으로 위임장의 진정성을 증명하더라도 회사는 그 대리권을 부정할 수 있다.","y":2020,"e":"법무사 1차"}},{"n":12,"s":0.509,"o":{"i":"법무사2026_32-48-2","t":"당사자 사이에 회사를 설립하기로 합의하면서 그 일방은 일정한 재산을 현물로 출자하고, 타방은 현금을 출자하되, 현물출자에 따른 번잡함을 피하기 위하여 회사의 성립 후 회사와 현물출자자 사이의 매매계약에 의한 방법에 의하여 위 현물출자를 완성하기로 약정하고 그 후 회사설립을 위한 소정의 절차를 거쳐 위 약정에 따른 현물출자가 이루어진 것이라면, 위 현물출자를 위한 약정은 실질이 재산인수에 해당한다고 할 것이어서 정관에 기재되지 아니하는 한 무효이다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2018_24-40-5","t":"현물출자에 따른 번잡함을 피하기 위해 회사 성립 후 회사와 甲 간의 매매계약에 의한 소유권이전등기의 방법에 의하여 위 현물출자를 완성하기로 약정하고 그 후 회사설립을 위한 소정의 절차를 거쳐 위 약정에 따른 현물출자가 이루어진 것이라면, 위 현물출자를 위한 약정은 실질 그대로 상법 제290조 제2호의 현물출자에 해당한다고 할 것이어서 정관에 기재되지 아니하는 한 무효이다.","y":2018,"e":"법무사 1차"}},{"n":12,"s":0.39,"o":{"i":"법무사2016_22-24-2","t":"기존회사가 채무를 면탈할 목적으로 기업의 형태·내용이 실질적으로 동일한 신설회사를 설립하였다면, 신설회사의 설립은 기존회사의 채무면탈이라는 위법한 목적달성을 위하여 회사제도를 남용한 것이므로, 기존회사의 채권자에 대하여 위 두 회사가 별개의 법인격을 갖고 있음을 주장하는 것은 신의성실의 원칙상 허용될 수 없고 기존회사의 채권자는 위 두 회사 어느 쪽에 대하여서도 채무의 이행을 청구할 수 있다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2025_31-40-4","t":"기존회사가 채무를 면탈할 목적으로 기업의 형태·내용이 실질적으로 동일한 신설회사를 설립하여 채무면탈이라는 위법한 목적달성을 위하여 회사제도를 남용하였다고 평가되는 경우, 기존회사의 채권자는 신설회사만을 상대로 채무 이행을 구하여야 하고 기존회사를 상대로 채무 이행을 청구할 수는 없다.","y":2025,"e":"법무사 1차"}},{"n":12,"s":0.318,"o":{"i":"법무사2025_31-40-3","t":"개인의 채무 부담행위에 대한 회사의 책임을 부인하는 것이 심히 정의와 형평에 반한다고 인정되어 회사에 대하여 개인이 부담한 채무의 이행을 청구하는 법리는 채무면탈을 목적으로 회사가 새로 설립된 경우뿐 아니라 같은 목적으로 기존 회사의 법인격이 이용되는 경우에도 적용되는데, 여기에는 회사가 이름뿐이고 실질적으로는 개인기업에 지나지 않은 상태로 될 정도로 형해화된 경우와 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하는 경우가 있을 수 있다. 이때 회사의 법인격이 형해화되었다고 볼 수 있는지 여부는 원칙적으로 문제가 되고 있는 법률행위나 사실행위를 한 시점을 기준으로, 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하였는지 여부는 채무면탈 등의 남용행위를 한 시점을 기준으로 각 판단하여야 한다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2023_29-37-5","t":"회사의 법인격이 형해화되었다고 볼 수 있는지 여부는 원칙적으로 회사가 성립되는 설립등기를 한 시점을 기준으로, 회사의 법인격이 형해화될 정도에 이르지 않더라도 개인이 회사의 법인격을 남용하였는지 여부는 채무면탈 등의 남용행위를 한 시점을 기준으로 각 판단하여야 한다.","y":2023,"e":"법무사 1차"}},{"n":11,"s":0.857,"o":{"i":"법무사2022_28-45-4","t":"동일한 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업으로 타인이 등기한 상호를 사용하는 자는 부정한 목적으로 사용하는 것으로 추정한다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2017_23-23-3","t":"동일한 특별시ㆍ광역시ㆍ시ㆍ군에서 동종영업으로 타인이 등기한 상호를 사용하는 자는 부정한 목적으로 사용하는 것으로 간주한다.","y":2017,"e":"법무사 1차"}},{"n":11,"s":0.706,"o":{"i":"법무사2023_29-45-5","t":"부분적 포괄대리권을 가진 사용인의 경우에는 표현지배인에 관한 상법 제14조의 규정이 유추적용되지 않는다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2018_24-48-5","t":"부분적 포괄대리권을 가진 사용인의 경우에도 표현지배인에 관한 상법 제14조의 규정이 유추적용된다.","y":2018,"e":"법무사 1차"}},{"n":11,"s":0.696,"o":{"i":"법무사2017_23-31-3","t":"법무사를 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고 볼 수 없다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2018_24-29-2","t":"변호사는 상법 제5조 제1항이 규정하는 ‘상인적 방법에 의하여 영업을 하는 자’라고 볼 수 있다.","y":2018,"e":"법무사 1차"}},{"n":11,"s":0.689,"o":{"i":"법무사2020_26-40-3","t":"영업양도에 의하여 승계되는 근로관계는 계약체결일 현재 실제로 그 영업부문에서 근무하고 있는 근로자와의 근로관계만을 의미하고, 계약체결일 이전에 해당 영업부문에서 근무하다가 해고된 근로자로서 해고의 효력을 다투는 근로자와의 근로관계까지 승계되는 것은 아니다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2018_24-37-2","t":"영업양도에 의하여 승계되는 근로관계는 계약체결일 현재 실제로 그 영업부문에서 근무하고 있는 근로자와의 근로관계뿐만이 아니라, 계약체결일 이전에 해당 영업부문에서 근무하다가 해고된 근로자로서 해고의 효력을 다투는 근로자와의 근로관계도 포함한다.","y":2018,"e":"법무사 1차"}},{"n":18,"s":0.648,"o":{"i":"법무사2021_27-34-3","t":"약속어음의 보증 부분이 위조된 경우, 해당 약속어음을 배서, 양도받는 제3취득자는 위 보증행위가 민법 제126조 소정의 표현대리행위로서 보증인에게 그 효력이 미친다고 주장할 수 있는 제3자에 해당하지 않는다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2017_23-48-2","t":"약속어음의 보증 부분이 위조된 경우 해당 약속어음을 배서, 양도받은 제3취득자는 위 보증행위가 민법 제126조가 정한 표현(表見)대리행위로서 보증인에게 그 효력이 미친다고 주장할 수 있는 제3자에 해당한다.","y":2017,"e":"법무사 1차"}},{"n":18,"s":0.626,"o":{"i":"법무사2026_32-21-5","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음의 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구하더라도, 그 청구로써 어음상의 청구권에 관한 소멸시효는 중단된다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2020_26-31-3","t":"만기는 기재되어 있으나 지급지, 지급을 받을 자 등과 같은 어음요건이 백지인 약속어음의 소지인이 그 백지 부분을 보충하지 않은 상태에서 어음금을 청구하는 경우, 이로써 어음상의 청구권에 관한 소멸시효는 중단된다. 다만 이 경우 백지에 대한 보충권은 어음상의 청구권과는 별개로 독립하여 시효로 소멸하게 된다.","y":2020,"e":"법무사 1차"}},{"n":18,"s":0.512,"o":{"i":"법무사2021_27-34-5","t":"어음행위의 대리 또는 대행권한을 수여받은 자가 그 수권의 범위를 넘어 어음행위를 한 경우에 본인은 그 수권의 범위 내에서는 대리 또는 대행자와 함께 어음상의 채무를 부담한다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2017_23-48-1","t":"어음행위의 대리 또는 대행권한을 수여받은 자가 그 수권의 범위를 넘어 어음행위를 한 경우 본인은 수권의 범위를 불문하고 아무런 어음상의 채무를 부담하지 않는다.","y":2017,"e":"법무사 1차"}},{"n":18,"s":0.452,"o":{"i":"법무사2017_23-39-5","t":"어음의 배서인이 발행인으로부터 지급받은 어음금 중 일부를 어음 소지인에게 지급한 경우 어음의 발행인은 그 범위 내에서 배서인에 대한 인적항변으로써 소지인에게 대항하여 그 부분 어음금 지급을 거절할 수 있다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2016_22-34-5","t":"어음에 의하여 청구를 받은 자는 종전의 소지인에 대한 인적관계로 인한 항변으로써 소지인에게 대항하지 못하므로, 어음의 배서인이 발행인으로부터 지급받은 어음 중 일부를 어음소지인에게 지급한 경우라도 어음의 발행인은 소지인에게 대항하여 그 부분 어음금의 지급을 거절하지 못한다.","y":2016,"e":"법무사 1차"}},{"n":13,"s":0.622,"o":{"i":"법무사2020_26-32-3","t":"회사는 특별한 사정이 없는 한 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았든 몰랐든 간에 주주명부상 주주의 주주권 행사를 부인할 수 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2026_32-39-5","t":"회사는 주주명부상 주주 외에 실제 주식을 인수하거나 양수하고자 하였던 자가 따로 존재한다는 사실을 알았다면 주주명부상 주주의 주주권 행사를 부인할 수 있다.","y":2026,"e":"법무사 1차"}},{"n":13,"s":0.556,"o":{"i":"법무사2024_30-36-3","t":"본인의 귀책사유가 아닌 사유로 퇴임 또는 퇴직하게 되더라도 퇴임 또는 퇴직일까지 상법 제340조의4 제1항의 ‘2년 이상 재임 또는 재직’ 요건을 충족하지 못한다면 위 조항에 따른 주식매수선택권을 행사할 수 없다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2019_25-29-4","t":"본인의 귀책사유가 아닌 사유로 퇴임 또는 퇴직하게 된 경우에는, 비록 형식적으로는 상법 제340조의4 제1항의 ‘2년 이상 재임 또는 재직’ 요건을 충족하지 못하더라도 주식매수선택권을 행사할 수 있다.","y":2019,"e":"법무사 1차"}},{"n":13,"s":0.519,"o":{"i":"법무사2021_27-21-3","t":"상법 제335조 제1항 단서는 주식의 양도를 전제로 하고, 다만 이를 제한하는 방법으로서 이사회의 승인을 요하도록 정관에 정할 수 있다는 취지이지 주식의 양도 그 자체를 금지할 수 있음을 정할 수 있다는 뜻은 아니기 때문에, 정관의 규정으로 주식의 양도를 제한하는 경우에도 주식양도를 전면적으로 금지하는 규정을 둘 수는 없다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2025_31-21-1","t":"상법 제335조 제1항 단서는 주식의 양도를 제한하는 방법으로서 이사회의 승인을 요하도록 정관에 정할 수 있다는 취지이다. 따라서 정관의 규정으로 주식의 양도를 제한하는 경우 주식양도를 전면적으로 금지하도록 할 수 있다.","y":2025,"e":"법무사 1차"}},{"n":13,"s":0.493,"o":{"i":"법무사2025_31-21-2","t":"주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우에 주식을 취득하였으나 회사로부터 양도승인거부의 통지를 받은 양수인은 회사에 대하여 주식매수청구권을 행사할 수 있다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2021_27-21-5","t":"주식의 양도에 관하여 이사회의 승인을 얻어야 하는 경우에 주식을 취득하였으나 회사로부터 양도승인거부의 통지를 받은 양수인은 상법 제335조의7에 따라 회사에 대하여 주식매수청구권을 행사할 수 있다. 이와 관련하여 주식을 취득하지 못한 양수인이 회사에 대하여 주식매수청구를 하더라도 이는 효력이 없으나, 사후적으로 양수인이 주식 취득의 요건을 갖추게 되면 그 하자가 치유될 수 있다.","y":2021,"e":"법무사 1차"}},{"n":15,"s":0.84,"o":{"i":"법무사2022_28-32-5","t":"주식배당의 의사결정은 주주총회의 결의로만 정할 수 있다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2022_28-32-2","t":"이익배당의 의사결정은 주주총회의 결의로만 정할 수 있다.","y":2022,"e":"법무사 1차"}},{"n":15,"s":0.786,"o":{"i":"법무사2020_26-24-2","t":"신주발행무효의 소에서 신주를 발행한 날부터 6월의 출소기간이 경과한 후에는 새로운 무효사유를 추가하여 주장할 수 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2017_23-41-2","t":"신주발행무효의 소에서 신주를 발행한 날부터 6월의 출소기간이 경과한 후에도 새로운 무효사유를 추가하여 주장할 수 있다.","y":2017,"e":"법무사 1차"}},{"n":15,"s":0.664,"o":{"i":"법무사2020_26-24-3","t":"회사가 주주배정방식에 의하여 신주를 발행하려는데 주주가 인수를 포기하거나 청약을 하지 아니함으로써 그 인수권을 잃은 때에는 회사는 이사회 결의로 인수가 없는 부분에 대하여 자유로이 이를 제3자에게 처분할 수 있고, 이 경우 실권된 신주를 제3자에게 발행하는 것에 관하여 정관에 반드시 근거 규정이 있어야 하는 것은 아니다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2023_29-25-4","t":"회사가 주주배정방식에 의하여 신주를 발행하려는데 주주가 인수를 포기하거나 청약을 하지 아니함으로써 그 인수권을 잃은 때에는 회사가 이사회 결의로 인수가 없는 부분을 제3자에게 처분할 수 있으나, 이 경우에도 실권된 신주를 제3자에게 발행하는 것에 관하여 정관에 반드시 근거 규정 자체는 있어야 한다.","y":2023,"e":"법무사 1차"}},{"n":15,"s":0.381,"o":{"i":"법무사2021_27-42-1","t":"발행주식 총수의 100분의 3 이상에 해당하는 주식을 가진 상태에서 회계장부와 서류 열람 등을 재판상으로 청구하였더라도 소송계속 중 신주발행 등으로 위 요건에 미달하게 된 경우에는 당사자적격이 상실된다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2019_25-24-5","t":"발행주식 총수의 100분의 3 이상에 해당하는 주식을 가진 상태에서 회계 장부와 서류 열람 등을 재판상으로 청구하였다면, 이후 소송계속 도중에 보유한 주식의 수가 발행주식 총수의 100분의 3 미만으로 되었다 하더라도 회계장부의 열람·등사를 구할 당사자적격을 상실하지 아니한다.","y":2019,"e":"법무사 1차"}},{"n":16,"s":0.624,"o":{"i":"법무사2017_23-40-2","t":"합병을 하는 회사의 일방 또는 쌍방이 주식회사, 유한회사 또는 유한책임회사인 경우에는 합병 후 존속하는 회사나 합병으로 설립되는 회사는 주식회사, 유한회사 또는 유한책임회사이어야 한다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2025_31-22-3","t":"합병을 하는 회사의 일방 또는 쌍방이 주식회사, 유한회사 또는 유한책임회사인 경우에는 합병 후 존속하는 회사나 합병으로 설립되는 회사는 합명회사, 합자회사, 유한책임회사, 주식회사와 유한회사로 자유롭게 정할 수 있다.","y":2025,"e":"법무사 1차"}},{"n":16,"s":0.362,"o":{"i":"법무사2018_24-46-1","t":"소규모합병의 경우 존속회사의 주주는 합병에 반대하더라도 주식매수청구권을 행사할 수 없다.","y":2018,"e":"법무사 1차"},"x":{"i":"법무사2018_24-46-3","t":"의결권이 없는 종류주식을 보유한 주주는 영업양도에 반대하더라도 주식매수청구권을 행사할 수 없다.","y":2018,"e":"법무사 1차"}},{"n":16,"s":0.34,"o":{"i":"법무사2024_30-50-1","t":"주식회사간 흡수합병의 경우 소멸회사 총주주의 동의가 있거나 그 회사 발행주식총수의 90% 이상을 합병후 존속회사가 소유하고 있는 때에는 소멸회사 주주총회 승인을 이사회 승인으로 갈음할 수 있다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2016_22-39-2","t":"주식회사가 합병을 함에는 합병계약서를 작성하여 주주총회의 승인을 얻어야 하지만, 합병으로 인하여 소멸하는 회사의 총주주의 동의가 있거나 그 회사의 발행주식총수의 100분의 90 이상을 합병 후 존속하는 회사가 소유하고 있는 때에는 합병 후 존속하는 회사의 주주총회의 승인은 이사회의 승인으로 갈음할 수 있다.","y":2016,"e":"법무사 1차"}},{"n":3,"s":0.496,"o":{"i":"법무사2017_23-13-1","t":"모든 인간은 헌법상 생명권의 주체가 되며, 형성 중의 생명인 태아에게도 생명에 대한 권리가 인정되어야 한다. 따라서 태아도 헌법상 생명권의 주체가 되며, 국가는 헌법 제10조에 따라 태아의 생명을 보호할 의무가 있다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2019_25-09-2","t":"모든 인간은 헌법상 생명권의 주체가 되며, 형성 중의 생명인 태아에게도 생명에 대한 권리가 인정되어야 한다. 따라서 국가는 헌법 제10조 제2문에 따라 태아의 생명을 보호할 의무가 있고, 생명을 보호하는 입법적 조치를 취함에 있어 인간생명의 발달단계에 따라 그 보호정도나 보호수단을 달리하여서는 아니 된다.","y":2019,"e":"법무사 1차"}},{"n":3,"s":0.493,"o":{"i":"법무사2023_29-05-1","t":"변호사 또는 소비자로부터 금전·기타 경제적 대가를 받고 법률상담 또는 사건 등을 소개·알선·유인하기 위하여 변호사 등을 광고·홍보·소개하는 행위를 금지하는 대한변호사협회의 변호사 광고에 관한 규정은 헌법소원의 대상이 되는 공권력의 행사에 해당한다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2023_29-05-5","t":"변호사 또는 소비자로부터 금전·기타 경제적 대가를 받고 법률상담 또는 사건 등을 소개·알선·유인하기 위하여 변호사 등을 광고·홍보·소개하는 행위를 금지하는 변호사 광고에 관한 규정은 변호사법이 금지하는 특정 변호사에 대한 소개·알선·유인행위의 실질을 갖춘 광고행위를 금지하는 것으로 과잉금지원칙에 위배되지 아니한다.","y":2023,"e":"법무사 1차"}},{"n":3,"s":0.485,"o":{"i":"법무사2024_30-20-5","t":"수사기관 등이 전기통신사업자에게 이용자의 성명 등 통신자료의 열람이나 제출을 요청할 수 있도록 한 전기통신사업법 조항은 통신자료 취득에 대한 사후통지 절차를 두지않아 적법절차원칙에 위배하여 개인정보자기결정권을 침해한다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2024_30-20-4","t":"수사기관 등이 전기통신사업자에게 이용자의 성명 등 통신자료의 열람이나 제출을 요청할 수 있도록 한 전기통신사업법 조항은 통신자료를 요청할 수 있는 사유를 지나치게 광범위하고 포괄적으로 규정하고 있으므로 과잉금지원칙을 위반하여 개인정보자기결정권을 침해한다.","y":2024,"e":"법무사 1차"}},{"n":3,"s":0.354,"o":{"i":"법무사2023_29-09-5","t":"성적목적공공장소침입죄로 유죄판결이 확정된 자는 신상정보 등록대상자가 되도록 규정한 법률조항은 등록대상자 선정에 있어 재범의 위험성을 전혀 요구하지 않고 있다 하더라도 위 범죄가 공공화장실 등 일정한 장소를 침입하는 경우에 한하여 성립하고 위 조항에 따른 등록대상자의 범위는 이에 따라 제한되므로, 개인정보자기결정권을 침해한다고 볼 수 없다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2023_29-09-2","t":"형법상 강제추행죄로 유죄판결이 확정된 자는 신상정보 등록대상자가 되도록 규정한 법률조항은 등록대상자 선정에 있어 재범의 위험성을 전혀 요구하지 않고 행위 태양의 특성이나 불법성의 경중을 고려하여 등록대상자의 범위를 축소하고 있지도 않으므로, 과잉금지원칙에 반하여 개인정보자기결정권을 침해한다.","y":2023,"e":"법무사 1차"}},{"n":6,"s":0.317,"o":{"i":"법무사2016_22-02-5","t":"근로자 개인뿐 아니라 근로자단체도 헌법상 단결권의 주체가 될 수 있다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2017_23-14-5","t":"근로의 권리는 근로자 개인뿐 아니라 노동조합도 그 주체가 될 수 있다.","y":2017,"e":"법무사 1차"}},{"n":1,"s":0.754,"o":{"i":"법무사2026_32-05-2","t":"헌법개정은 국회재적의원 과반수 또는 대통령의 발의로 제안된다. 제안된 헌법개정안은 대통령이 20일 이상의 기간 이를 공고하여야 한다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2018_24-16-2","t":"헌법개정은 국회재적의원 과반수 또는 대통령의 발의로 제안되고, 제안된 헌법개정안은 대통령이 30일 이상의 기간 이를 공고하여야 한다.","y":2018,"e":"법무사 1차"}},{"n":1,"s":0.739,"o":{"i":"법무사2021_27-14-3","t":"중앙선거관리위원회 위원의 임기는 6년으로 한다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2020_26-13-1","t":"중앙선거관리위원회 위원의 임기는 5년으로 한다.","y":2020,"e":"법무사 1차"}},{"n":7,"s":0.759,"o":{"i":"법무사2021_27-06-5","t":"법률안에 대한 재의의 요구가 있을 때에는 국회는 재의에 붙이고, 재적의원 과반수의 출석과 출석의원 3분의 2 이상의 찬성으로 전과 같은 의결을 하면 그 법률안은 법률로서 확정된다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2025_31-20-4","t":"법률안에 대한 대통령의 재의의 요구가 있을 때에는 국회는 재의에 붙이고, 재적의원 3분의 2 이상의 찬성으로 전과 같은 의결을 하면 그 법률안은 법률로서 확정된다.","y":2025,"e":"법무사 1차"}},{"n":7,"s":0.508,"o":{"i":"법무사2023_29-14-1","t":"국회의 정기회는 법률이 정하는 바에 의하여 매년 1회 집회되며, 국회의 임시회는 대통령 또는 국회재적의원 4분의 1 이상의 요구에 의하여 집회된다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2025_31-20-1","t":"국회의 임시회는 대통령 또는 국회재적의원 5분의 1 이상의 요구에 의하여 집회된다.","y":2025,"e":"법무사 1차"}},{"n":7,"s":0.451,"o":{"i":"법무사2023_29-14-5","t":"국회는 정부의 동의 없이 정부가 제출한 지출예산 각항의 금액을 증가하거나 새 비목을 설치할 수 없으며, 예산에 변경을 가할 필요가 있다 하더라도 직접 추가경정예산안을 제출, 의결할 수는 없다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2019_25-11-2","t":"국회는 정부의 동의 없이 정부가 제출한 지출예산 각항의 금액을 증가하거나 새 비목을 설치할 수 있다.","y":2019,"e":"법무사 1차"}},{"n":7,"s":0.45,"o":{"i":"법무사2021_27-06-4","t":"대통령은 국회에서 의결된 법률안에 이의가 있을 때에는 정부에 이송된 후 15일 이내에 이의서를 붙여 국회로 환부하여 그 재의를 요구할 수 있다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2023_29-14-2","t":"국회에서 의결된 법률안은 정부에 이송되어 15일 이내에 대통령이 공포하나, 법률안에 이의가 있을 때에는 대통령은 제1항의 기간 내에 그 전부 또는 일부에 관한 이의서를 붙여 국회로 환부하고, 그 재의를 요구할 수 있다.","y":2023,"e":"법무사 1차"}},{"n":8,"s":0.776,"o":{"i":"법무사2024_30-02-3","t":"대통령후보자가 1인일 때에는 그 득표수가 선거권자 총수의 3분의 1 이상이 아니면 대통령으로 당선될 수 없다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2019_25-19-3","t":"대통령후보자가 1인일 때에는 그 득표수가 선거권자 총수의 과반수 이상이 아니면 대통령으로 당선될 수 없다.","y":2019,"e":"법무사 1차"}},{"n":8,"s":0.346,"o":{"i":"법무사2016_22-08-2","t":"국무총리는 국무위원의 해임을 대통령에게 건의할 수 있다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2022_28-10-3","t":"국회는 국회재적의원 과반수의 발의와 국회재적의원 3분의 2 이상의 찬성으로 국무위원의 해임을 대통령에게 건의할 수 있다.","y":2022,"e":"법무사 1차"}},{"n":5,"s":0.495,"o":{"i":"법무사2026_32-08-5","t":"특별한 사정 없이 공무원이 특정의 장소에서 근무하는 것이나 특정의 보직을 받아 근무하는 것을 포함하는 일종의 ‘공무수행의 자유’가 헌법 제25조의 공무담임권의 보호영역에 포함된다고 보기는 어렵다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2020_26-08-1","t":"공무담임권의 보호영역에는 공무원이 특정의 장소에서 근무하는 것 또는 특정의 보직을 받아 근무하는 것을 포함하는 일종의 공무수행의 자유까지 포함된다.","y":2020,"e":"법무사 1차"}},{"n":9,"s":0.556,"o":{"i":"법무사2019_25-16-3","t":"대법관의 수는 대법원장을 포함하여 14명으로 한다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2017_23-08-1","t":"대법관의 수는 대법원장을 제외하고 14명으로 한다.","y":2017,"e":"법무사 1차"}},{"n":9,"s":0.436,"o":{"i":"법무사2020_26-19-1","t":"명령·규칙 또는 처분이 헌법이나 법률에 위반되는 여부가 재판의 전제가 된 경우에는 대법원은 이를 최종적으로 심사할 권한을 가진다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2023_29-18-4","t":"명령·규칙 또는 처분이 헌법이나 법률에 위반되는 여부가 재판의 전제가 된 경우에는 법원은 헌법재판소에 제청하여 그 심판에 의하여 재판한다.","y":2023,"e":"법무사 1차"}}];
